fn jump_number_for_distance(distance_parsecs: f64) -> u8 {
    distance_parsecs.ceil().clamp(1.0, f64::from(u8::MAX)) as u8
}

fn jump_fuel_for_distance(displacement_millitons: u64, distance_parsecs: f64) -> u64 {
    displacement_millitons
        .saturating_div(10)
        .saturating_mul(u64::from(jump_number_for_distance(distance_parsecs)))
}

fn encounter_kind_for_policy(entropy: u64, policy: Option<&SystemPolityPolicy>) -> EncounterKind {
    let Some(policy) = policy else {
        return match entropy % 12 {
            0 | 1 => EncounterKind::Hostile,
            2 => EncounterKind::Inspection,
            3 => EncounterKind::TrafficControl,
            4 => EncounterKind::Distress,
            5 => EncounterKind::Derelict,
            6 => EncounterKind::Hazard,
            7 => EncounterKind::Military,
            _ => EncounterKind::RoutineTraffic,
        };
    };
    let combat = u64::from(policy.trade_combat);
    let order = u64::from(policy.chaos_order);
    let weights = [
        (EncounterKind::Hostile, 5 + combat / 5 + (100 - order) / 10),
        (EncounterKind::Inspection, 5 + order / 10),
        (EncounterKind::TrafficControl, 10 + order / 10),
        (EncounterKind::Distress, 8),
        (EncounterKind::Derelict, 8 + (100 - order) / 20),
        (EncounterKind::Hazard, 8),
        (EncounterKind::Military, 5 + combat / 10 + order / 10),
        (EncounterKind::RoutineTraffic, 20 + (100 - combat) / 5),
    ];
    let total = weights.iter().map(|(_, weight)| *weight).sum::<u64>();
    let mut draw = entropy % total;
    for (kind, weight) in weights {
        if draw < weight {
            return kind;
        }
        draw -= weight;
    }
    EncounterKind::RoutineTraffic
}

#[derive(Debug, Error)]
pub enum StoreError {
    #[error("LMDB error: {0}")]
    Heed(#[from] heed::Error),
    #[error("storage I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("corrupt persistent record: {0}")]
    Corrupt(&'static str),
    #[error(
        "storage format {actual} is incompatible with required format {required}; reinitialize this undeployed game store"
    )]
    IncompatibleStorageFormat { actual: u64, required: u64 },
    #[error("unknown BBS identifier {0}")]
    UnknownBbs(u32),
    #[error("the game universe must be initialized before a BBS can be added")]
    UniverseNotInitialized,
    #[error(
        "persistent game state is inconsistent: system {0} is absent from the traffic simulator; stop the server and reinitialize the undeployed universe"
    )]
    MissingTrafficSimulationSystem(u64),
    #[error("initial universe needs exactly {expected} system seeds, received {actual}")]
    InvalidUniverseSeedCount { expected: usize, actual: usize },
    #[error(transparent)]
    CoverageGeometry(#[from] CoverageGeometryError),
    #[error("coverage revision {expected} is stale; current revision is {actual}")]
    StaleCoverageRevision { expected: u64, actual: u64 },
    #[error(transparent)]
    Crypto(#[from] CryptoError),
    #[error("operating-system random source failed: {0}")]
    Random(#[from] getrandom::Error),
    #[error(transparent)]
    PlaceName(#[from] PlaceNameError),
    #[error(transparent)]
    Simulation(#[from] SimulationError),
    #[error("cannot admit scheduled work while {0} input(s) remain in durable ingress")]
    PendingIngress(u64),
    #[error("simulation cannot move backward from second {current} to {target}")]
    SimulationTimeReversal { current: u64, target: u64 },
    #[error("settlement capacity materialization requires a finite positive extent")]
    InvalidSettlementExtent,
    #[error("settlement capacity materialization requires an unadvanced simulation")]
    SettlementCapacityAfterSimulation,
    #[error("could not derive an uninhabited system after {attempts} seed draws")]
    UninhabitedSeedSearchExhausted { attempts: usize },
    #[error("no eligible unexplored site can contain a BBS polity")]
    NoBbsPolitySite,
    #[error("exhausted {attempts} generation-seed draws for BBS system role {role}")]
    BbsSeedSearchExhausted { role: &'static str, attempts: usize },
    #[error(
        "system {system_id} uses generation version {actual}; server requires version {expected}"
    )]
    UnsupportedSystemGeneration {
        system_id: u64,
        actual: u16,
        expected: u16,
    },
    #[error("BBS placement entropy does not match the configured BBS set")]
    InvalidBbsPlacementEntropy,
    #[error("invalid sysop directive: {0}")]
    InvalidSysopDirective(&'static str),
    #[error("live backup conflict: {0}")]
    BackupConflict(&'static str),
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct QueuedCommand {
    pub identity: PlayerIdentity,
    pub request: CommandRequest,
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum ScheduledInput {
    Simulation(QueuedSimulationEvent),
    PlayerTravel {
        event_id: u64,
        due_second: u64,
        ship_id: u64,
    },
    ShipCondition {
        event_id: u64,
        due_second: u64,
        ship_id: u64,
    },
    PersonTraining {
        event_id: u64,
        due_second: u64,
        person_id: u64,
    },
    ShipActivity {
        event_id: u64,
        due_second: u64,
        ship_id: u64,
    },
    EncounterTurn {
        event_id: u64,
        due_second: u64,
        identity: PlayerIdentity,
        encounter_id: u64,
    },
    SharedCombatTurn {
        event_id: u64,
        due_second: u64,
        combat_id: u64,
    },
    ContactCheck {
        event_id: u64,
        due_second: u64,
        ship_id: u64,
    },
    MerchantWork {
        event_id: u64,
        due_second: u64,
        assignment_id: u64,
    },
}

impl ScheduledInput {
    fn due_second(&self) -> u64 {
        match self {
            Self::Simulation(event) => event.due_second,
            Self::PlayerTravel { due_second, .. }
            | Self::ShipCondition { due_second, .. }
            | Self::PersonTraining { due_second, .. }
            | Self::ShipActivity { due_second, .. }
            | Self::EncounterTurn { due_second, .. }
            | Self::SharedCombatTurn { due_second, .. } => *due_second,
            Self::ContactCheck { due_second, .. } | Self::MerchantWork { due_second, .. } => {
                *due_second
            }
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum EngineInput {
    Player(QueuedCommand),
    Scheduled(ScheduledInput),
    TimeAdvance { target_second: u64 },
}

#[derive(Clone, Debug)]
enum ScheduledCandidate {
    Simulation(ScheduledEventHead),
    PlayerTravel {
        key: Vec<u8>,
        due_second: u64,
        event_id: u64,
        ship_id: u64,
    },
    ShipCondition {
        key: Vec<u8>,
        due_second: u64,
        event_id: u64,
        ship_id: u64,
    },
    PersonTraining {
        key: Vec<u8>,
        due_second: u64,
        event_id: u64,
        person_id: u64,
    },
    ShipActivity {
        key: Vec<u8>,
        due_second: u64,
        event_id: u64,
        ship_id: u64,
    },
    EncounterTurn {
        key: Vec<u8>,
        due_second: u64,
        event_id: u64,
        identity: PlayerIdentity,
        encounter_id: u64,
    },
    SharedCombatTurn {
        key: Vec<u8>,
        due_second: u64,
        event_id: u64,
        combat_id: u64,
    },
    ContactCheck {
        key: Vec<u8>,
        due_second: u64,
        event_id: u64,
        ship_id: u64,
    },
    MerchantWork {
        key: Vec<u8>,
        due_second: u64,
        event_id: u64,
        assignment_id: u64,
    },
}

impl ScheduledCandidate {
    fn admission_key(&self) -> (u64, u64) {
        match self {
            Self::Simulation(head) => (head.due_second, head.event_id),
            Self::PlayerTravel {
                due_second,
                event_id,
                ..
            }
            | Self::ShipCondition {
                due_second,
                event_id,
                ..
            }
            | Self::PersonTraining {
                due_second,
                event_id,
                ..
            }
            | Self::ShipActivity {
                due_second,
                event_id,
                ..
            }
            | Self::EncounterTurn {
                due_second,
                event_id,
                ..
            }
            | Self::SharedCombatTurn {
                due_second,
                event_id,
                ..
            }
            | Self::ContactCheck {
                due_second,
                event_id,
                ..
            }
            | Self::MerchantWork {
                due_second,
                event_id,
                ..
            } => (*due_second, *event_id),
        }
    }
}

