#[derive(Clone, Debug, Eq, PartialEq)]
pub struct PersonRecord {
    pub person_id: u64,
    pub origin_bbs_id: u32,
    pub origin_system_id: u64,
    pub person: crate::wire::PersonDraft,
    pub current_strength: u8,
    pub current_dexterity: u8,
    pub current_endurance: u8,
    /// 0 is rested, 1 is fatigued, and 2 is fatigue-induced unconsciousness.
    pub fatigue_points: u16,
    pub last_injury_second: u64,
    pub first_aid_applied: bool,
    pub last_treatment_second: u64,
    /// A positive value restores characteristic points; a negative value
    /// applies surgical damage when the queued procedure completes.
    pub pending_treatment_effect: i16,
    pub pending_treatment_due_second: u64,
    /// Consecutive daily food settlements for which this person was not fed.
    /// CE starvation checks begin after the third such day.
    pub unfed_days: u16,
}

fn person_maximum(person: &PersonRecord) -> crate::personnel::PhysicalCondition {
    crate::personnel::PhysicalCondition {
        strength: person.person.characteristics.strength,
        dexterity: person.person.characteristics.dexterity,
        endurance: person.person.characteristics.endurance,
    }
}

fn person_physical(person: &PersonRecord) -> crate::personnel::PhysicalCondition {
    crate::personnel::PhysicalCondition {
        strength: person.current_strength,
        dexterity: person.current_dexterity,
        endurance: person.current_endurance,
    }
}

fn set_person_physical(person: &mut PersonRecord, condition: crate::personnel::PhysicalCondition) {
    person.current_strength = condition.strength;
    person.current_dexterity = condition.dexterity;
    person.current_endurance = condition.endurance;
}

fn person_injury_points(person: &PersonRecord) -> u16 {
    person_physical(person).missing_points(person_maximum(person))
}

fn person_dead(person: &PersonRecord) -> bool {
    person_physical(person).dead()
}

fn crew_service_living_positions(service: &CrewServiceRecord, person: &PersonRecord) -> u16 {
    service
        .represented_positions
        .saturating_sub(u16::from(person_dead(person)))
}

fn person_incapacitated(person: &PersonRecord) -> bool {
    let physical = person_physical(person);
    physical.dead() || physical.unconscious() || person.fatigue_points >= 2
}

fn person_condition_dm(person: &PersonRecord) -> i8 {
    if person.fatigue_points == 0 { 0 } else { -2 }
}

fn settle_person_food(person: &mut PersonRecord, fed: bool, due_second: u64) -> u8 {
    if person_dead(person) {
        return 0;
    }
    if fed {
        person.unfed_days = 0;
        return 0;
    }
    person.unfed_days = person.unfed_days.saturating_add(1);
    if person.unfed_days <= 3 {
        return 0;
    }
    let entropy = crate::ship_condition::mix64(
        person.person_id ^ due_second.rotate_left(23) ^ 0x5354_4152_5645_0001,
    );
    let check = crate::personnel::starvation_check(
        person.current_endurance,
        person.unfed_days.saturating_sub(4),
        entropy,
    );
    if check.success {
        return 0;
    }
    let mut physical = person_physical(person);
    crate::personnel::apply_damage(
        &mut physical,
        person_maximum(person),
        u16::from(check.damage),
    );
    set_person_physical(person, physical);
    person.last_injury_second = due_second;
    person.first_aid_applied = false;
    check.damage
}

