#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ShipLocusRecord {
    Port {
        system_id: u64,
        world_id: u64,
        facility_id: u64,
    },
    JumpLocus {
        system_id: u64,
    },
    Body {
        system_id: u64,
        body_id: u32,
    },
    DeepSpace {
        position: crate::wire::Coordinate3,
    },
}

impl ShipLocusRecord {
    fn system_id(self) -> u64 {
        match self {
            Self::Port { system_id, .. }
            | Self::JumpLocus { system_id }
            | Self::Body { system_id, .. } => system_id,
            Self::DeepSpace { .. } => 0,
        }
    }
}

fn flight_locus_status(locus: ShipLocusRecord) -> FlightLocus {
    match locus {
        ShipLocusRecord::Port {
            system_id,
            world_id,
            facility_id,
        } => FlightLocus::Port {
            system_id,
            world_id,
            facility_id,
        },
        ShipLocusRecord::JumpLocus { system_id } => FlightLocus::JumpLocus { system_id },
        ShipLocusRecord::Body { system_id, body_id } => FlightLocus::Body { system_id, body_id },
        ShipLocusRecord::DeepSpace { position } => FlightLocus::DeepSpace { position },
    }
}

