fn task_offer_is_open_at_system(
    stored: &StoredTaskOffer,
    system_id: u64,
    current_second: u64,
    closure_received: bool,
) -> bool {
    current_second <= stored.offer.expires_second
        && (stored.claimed_by.is_none()
            || system_id != stored.offer.origin_system_id && !closure_received)
}

