#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct OperatingAccountPayment {
    restricted_credits: u64,
    liquid_credits: u64,
    restricted_balance_credits: u64,
    liquid_balance_credits: u64,
}

fn ship_finance_key(ship_id: u64) -> [u8; 8] {
    ship_id.to_be_bytes()
}

fn finance_installment_due(finance: &FinanceRecord) -> (u64, u64, u64) {
    let principal = finance
        .principal_credits
        .min(finance.monthly_payment_credits);
    let insurance = finance.monthly_insurance_escrow_credits;
    (principal, insurance, principal.saturating_add(insurance))
}

fn operating_account_payment_parts(
    player: &PlayerRecord,
    finance: &FinanceRecord,
    amount: u64,
) -> (u64, u64) {
    let restricted_payment = finance.restricted_credits.min(amount);
    let liquid_payment = player.credits.min(amount - restricted_payment);
    (restricted_payment, liquid_payment)
}

fn apply_operating_account_payment(
    player: &mut PlayerRecord,
    finance: &mut FinanceRecord,
    amount: u64,
) -> u64 {
    let (restricted_payment, liquid_payment) =
        operating_account_payment_parts(player, finance, amount);
    finance.restricted_credits -= restricted_payment;
    player.credits -= liquid_payment;
    restricted_payment + liquid_payment
}

/// Applies one installment atomically. Mandatory insurance is an authorized
/// operating expense and therefore consumes restricted credit before liquid
/// cash; secured principal is always a personal cash obligation.
fn pay_finance_installment(player: &mut PlayerRecord, finance: &mut FinanceRecord) -> bool {
    let (principal, insurance, _) = finance_installment_due(finance);
    let restricted_payment = finance.restricted_credits.min(insurance);
    let liquid_payment = principal.saturating_add(insurance - restricted_payment);
    if player.credits < liquid_payment {
        return false;
    }
    finance.restricted_credits -= restricted_payment;
    player.credits -= liquid_payment;
    finance.principal_credits -= principal;
    player.debt_credits = player.debt_credits.saturating_sub(principal);
    if finance.principal_credits == 0 && finance.title == crate::wire::ShipTitleKind::OwnedWithLien
    {
        finance.title = crate::wire::ShipTitleKind::OwnedClear;
    }
    true
}

fn forged_receipt_detection_percent(
    amount: u64,
    authorized_expenses: u64,
    receipt_count: u32,
) -> u8 {
    let amount_risk = amount
        .checked_ilog2()
        .unwrap_or(0)
        .saturating_add(1)
        .saturating_mul(5);
    let repetition_risk = receipt_count.saturating_sub(1).saturating_mul(10).min(20);
    let total_expenses = amount.saturating_add(authorized_expenses).max(1);
    let fraudulent_percent = ((u128::from(amount) * 100) / u128::from(total_expenses)) as u32;

    // A false claim is easier to spot when it dominates the month's accounts
    // and easier to hide among legitimate ship expenses. Absolute scale and
    // repeated claims still matter independently. Detection remains uncertain.
    let scrutiny_percent = 50_u32.saturating_add(fraudulent_percent);
    amount_risk
        .saturating_add(repetition_risk)
        .saturating_mul(scrutiny_percent)
        .div_ceil(100)
        .clamp(1, 90) as u8
}

fn forged_receipt_audit_detected(
    ship_id: u64,
    due_second: u64,
    amount: u64,
    authorized_expenses: u64,
    receipt_count: u32,
) -> bool {
    let detection_percent =
        forged_receipt_detection_percent(amount, authorized_expenses, receipt_count);
    let entropy = crate::ship_condition::mix64(
        ship_id
            ^ due_second.rotate_left(17)
            ^ amount.rotate_left(31)
            ^ u64::from(receipt_count).rotate_left(47)
            ^ 0x4155_4449_545f_5243,
    );
    entropy % 100 < u64::from(detection_percent)
}

