fn starport_supports_yard(starport: crate::universe::Starport, required: char) -> bool {
    match required {
        'C' => matches!(
            starport,
            crate::universe::Starport::A
                | crate::universe::Starport::B
                | crate::universe::Starport::C
        ),
        'B' => matches!(
            starport,
            crate::universe::Starport::A | crate::universe::Starport::B
        ),
        _ => matches!(starport, crate::universe::Starport::A),
    }
}

fn new_primary_facility(system: &StellarSystem) -> Result<FacilityRecord, StoreError> {
    let world = derive_primary_world(system)?;
    let suffixes = [
        "Faraday Terminal",
        "Kepler Field",
        "Tsiolkovsky Port",
        "Sagan Anchorage",
        "Hopper Station",
        "Le Guin Terminal",
        "Armstrong Field",
        "Nightingale Port",
    ];
    let suffix = suffixes[usize::from(system.generation_seed[0]) % suffixes.len()];
    let (refined_fuel, unrefined_fuel, repair_shop, maximum_yard_hull_millitons, medical_level) =
        match world.starport {
            crate::universe::Starport::A => (true, true, true, 100_000_000, 3),
            crate::universe::Starport::B => (true, true, true, 20_000_000, 3),
            crate::universe::Starport::C => (false, true, true, 5_000_000, 2),
            crate::universe::Starport::D => (false, true, false, 0, 1),
            crate::universe::Starport::E => (false, false, false, 0, 0),
            crate::universe::Starport::X => (false, false, false, 0, 0),
        };
    Ok(FacilityRecord {
        facility_id: system.id,
        system_id: system.id,
        world_id: system.id,
        revision: 1,
        name: format!("{} {suffix}", world.name),
        operational: world.starport != crate::universe::Starport::X,
        starport: world.starport,
        tech_level: world.tech_level,
        refined_fuel,
        unrefined_fuel,
        repair_shop,
        maximum_yard_hull_millitons,
        maximum_component_tech_level: world.tech_level,
        medical_level,
        chandlery: matches!(
            world.starport,
            crate::universe::Starport::A
                | crate::universe::Starport::B
                | crate::universe::Starport::C
                | crate::universe::Starport::D
        ),
        ordnance: matches!(
            world.starport,
            crate::universe::Starport::A
                | crate::universe::Starport::B
                | crate::universe::Starport::C
        ),
        personnel_exchange: matches!(
            world.starport,
            crate::universe::Starport::A
                | crate::universe::Starport::B
                | crate::universe::Starport::C
        ),
        banking: matches!(
            world.starport,
            crate::universe::Starport::A
                | crate::universe::Starport::B
                | crate::universe::Starport::C
                | crate::universe::Starport::D
        ),
        authority_office: world.population != 0 && world.starport != crate::universe::Starport::X,
        clearance_required: world.law_level >= 8,
    })
}

fn replacement_quote(subsystem: &ShipSubsystemRecord, reconditioned: bool) -> (u64, u64) {
    let multiplier = match subsystem.kind {
        ShipSubsystemKind::JumpDrive
        | ShipSubsystemKind::ManeuverDrive
        | ShipSubsystemKind::PowerPlant => 150_u64,
        ShipSubsystemKind::Computer | ShipSubsystemKind::Sensors => 125,
        ShipSubsystemKind::WeaponMount if subsystem.label.to_ascii_lowercase().contains("bay") => {
            200
        }
        ShipSubsystemKind::WeaponMount
            if subsystem.label.to_ascii_lowercase().contains("barbette") =>
        {
            150
        }
        ShipSubsystemKind::WeaponMount => 100,
        _ => 110,
    };
    let new_cost = subsystem
        .replacement_price_credits
        .saturating_mul(multiplier)
        .div_ceil(100);
    let cost = if reconditioned {
        new_cost.saturating_mul(75).div_ceil(100)
    } else {
        new_cost
    };
    let weeks = match subsystem.kind {
        ShipSubsystemKind::Computer
        | ShipSubsystemKind::Sensors
        | ShipSubsystemKind::WeaponMount => 1,
        _ => subsystem.displacement_millitons.div_ceil(10_000).max(1),
    };
    (
        cost,
        weeks.saturating_mul(crate::ship_condition::SECONDS_PER_WEEK),
    )
}

