fn apply_ship_damage_to_combat(ship: &ShipRecord, vessel: &mut crate::combat::VesselState) {
    let remaining = |kind: ShipSubsystemKind| {
        ship.subsystems
            .iter()
            .find(|subsystem| subsystem.kind == kind)
            .map(|subsystem| {
                subsystem
                    .maximum_hits
                    .saturating_sub(subsystem.sustained_hits)
            })
    };
    if let Some(value) = remaining(ShipSubsystemKind::Hull) {
        vessel.hull_remaining = value;
    }
    if let Some(value) = remaining(ShipSubsystemKind::Structure) {
        vessel.structure_remaining = value;
    }
    if let Some(value) = remaining(ShipSubsystemKind::Armor) {
        vessel.armor_remaining = value;
    }
    for (index, kind) in [
        ShipSubsystemKind::Bridge,
        ShipSubsystemKind::Sensors,
        ShipSubsystemKind::ManeuverDrive,
        ShipSubsystemKind::JumpDrive,
        ShipSubsystemKind::PowerPlant,
        ShipSubsystemKind::FuelSystem,
        ShipSubsystemKind::CargoHold,
    ]
    .into_iter()
    .enumerate()
    {
        if let Some(subsystem) = ship
            .subsystems
            .iter()
            .find(|subsystem| subsystem.kind == kind)
        {
            let hits = subsystem.sustained_hits.min(u16::from(u8::MAX)) as u8;
            match kind {
                ShipSubsystemKind::Bridge => vessel.bridge_hits = hits,
                ShipSubsystemKind::Sensors => vessel.sensors_hits = hits,
                ShipSubsystemKind::ManeuverDrive => vessel.maneuver_hits = hits,
                ShipSubsystemKind::JumpDrive => vessel.jump_hits = hits,
                ShipSubsystemKind::PowerPlant => vessel.power_hits = hits,
                ShipSubsystemKind::FuelSystem => vessel.fuel_hits = hits,
                ShipSubsystemKind::CargoHold => vessel.hold_hits = hits,
                _ => unreachable!(),
            }
            vessel.battlefield_repairs[index] =
                subsystem.battlefield_repair_hits.min(u16::from(u8::MAX)) as u8;
        }
    }
    let mount_hits = ship
        .subsystems
        .iter()
        .filter(|subsystem| subsystem.kind == ShipSubsystemKind::WeaponMount)
        .map(|subsystem| {
            (
                subsystem.sustained_hits.min(u16::from(u8::MAX)) as u8,
                subsystem.battlefield_repair_hits.min(u16::from(u8::MAX)) as u8,
            )
        });
    for (mount, (hits, repairs)) in vessel.weapons.iter_mut().zip(mount_hits) {
        mount.damage_hits = hits;
        mount.battlefield_repair_hits = repairs;
    }
    for lot in &mut vessel.ammunition {
        lot.remaining = ship
            .ammunition
            .iter()
            .find(|stored| stored.ammunition_id == lot.ammunition_id)
            .map_or(0, |stored| stored.remaining);
    }
    if ship
        .latent_quirks
        .iter()
        .any(|quirk| quirk.manifested && quirk.kind == ShipQuirkKind::TurretFault)
    {
        vessel.targeting_dm = vessel.targeting_dm.saturating_sub(2);
    }
    if ship.latent_quirks.iter().any(|quirk| {
        quirk.manifested
            && matches!(
                quirk.kind,
                ShipQuirkKind::BridgeChairFault | ShipQuirkKind::FullSpeedVibration
            )
    }) {
        vessel.initiative = vessel.initiative.saturating_sub(1);
    }
}

fn apply_combat_damage_to_ship(vessel: &crate::combat::VesselState, ship: &mut ShipRecord) {
    for subsystem in &mut ship.subsystems {
        let remaining = match subsystem.kind {
            ShipSubsystemKind::Hull => Some(vessel.hull_remaining),
            ShipSubsystemKind::Structure => Some(vessel.structure_remaining),
            ShipSubsystemKind::Armor => Some(vessel.armor_remaining),
            ShipSubsystemKind::Bridge => Some(
                subsystem
                    .maximum_hits
                    .saturating_sub(u16::from(vessel.bridge_hits)),
            ),
            ShipSubsystemKind::Sensors => Some(
                subsystem
                    .maximum_hits
                    .saturating_sub(u16::from(vessel.sensors_hits)),
            ),
            ShipSubsystemKind::ManeuverDrive => Some(
                subsystem
                    .maximum_hits
                    .saturating_sub(u16::from(vessel.maneuver_hits)),
            ),
            ShipSubsystemKind::JumpDrive => Some(
                subsystem
                    .maximum_hits
                    .saturating_sub(u16::from(vessel.jump_hits)),
            ),
            ShipSubsystemKind::PowerPlant => Some(
                subsystem
                    .maximum_hits
                    .saturating_sub(u16::from(vessel.power_hits)),
            ),
            ShipSubsystemKind::FuelSystem => Some(
                subsystem
                    .maximum_hits
                    .saturating_sub(u16::from(vessel.fuel_hits)),
            ),
            ShipSubsystemKind::CargoHold => Some(
                subsystem
                    .maximum_hits
                    .saturating_sub(u16::from(vessel.hold_hits)),
            ),
            _ => None,
        };
        if let Some(remaining) = remaining {
            subsystem.sustained_hits = subsystem
                .maximum_hits
                .saturating_sub(remaining.min(subsystem.maximum_hits));
        }
        let repair_index = match subsystem.kind {
            ShipSubsystemKind::Bridge => Some(0),
            ShipSubsystemKind::Sensors => Some(1),
            ShipSubsystemKind::ManeuverDrive => Some(2),
            ShipSubsystemKind::JumpDrive => Some(3),
            ShipSubsystemKind::PowerPlant => Some(4),
            ShipSubsystemKind::FuelSystem => Some(5),
            ShipSubsystemKind::CargoHold => Some(6),
            _ => None,
        };
        if let Some(index) = repair_index {
            subsystem.battlefield_repair_hits =
                u16::from(vessel.battlefield_repairs[index]).min(subsystem.sustained_hits);
        }
    }
    for (subsystem, mount) in ship
        .subsystems
        .iter_mut()
        .filter(|subsystem| subsystem.kind == ShipSubsystemKind::WeaponMount)
        .zip(&vessel.weapons)
    {
        subsystem.sustained_hits = u16::from(mount.damage_hits).min(subsystem.maximum_hits);
        subsystem.battlefield_repair_hits =
            u16::from(mount.battlefield_repair_hits).min(subsystem.sustained_hits);
    }
    for stored in &mut ship.ammunition {
        stored.remaining = vessel
            .ammunition
            .iter()
            .find(|lot| lot.ammunition_id == stored.ammunition_id)
            .map_or(0, |lot| lot.remaining)
            .min(stored.capacity);
    }
    ship.revision = ship.revision.saturating_add(1);
}

fn apply_jump_transition_critical(ship: &mut ShipRecord, entropy: u64) {
    let eligible = ship
        .subsystems
        .iter()
        .enumerate()
        .filter(|(_, subsystem)| subsystem.maximum_hits != 0)
        .map(|(index, _)| index)
        .collect::<Vec<_>>();
    if eligible.is_empty() {
        return;
    }
    let selected =
        eligible[crate::ship_condition::mix64(entropy ^ ship.ship_id) as usize % eligible.len()];
    let subsystem = &mut ship.subsystems[selected];
    subsystem.sustained_hits = subsystem
        .sustained_hits
        .saturating_add(1)
        .min(subsystem.maximum_hits);
    subsystem.battlefield_repair_hits = subsystem
        .battlefield_repair_hits
        .min(subsystem.sustained_hits);
}

fn wire_combat_order(
    request: &crate::wire::CombatOrderSet,
    vessel_id: u64,
) -> Result<crate::combat::JointOrder, StoreError> {
    use crate::wire::CombatActionKind as Kind;
    let actions = request
        .actions
        .iter()
        .map(|action| {
            Ok(match action.kind {
                Kind::Hold => crate::combat::CrewAction::Hold,
                Kind::Coordinate => crate::combat::CrewAction::Coordinate,
                Kind::IncreaseInitiative => crate::combat::CrewAction::IncreaseInitiative,
                Kind::EvasiveManeuvers => crate::combat::CrewAction::EvasiveManeuvers,
                Kind::LineUpShot => crate::combat::CrewAction::LineUpShot,
                Kind::RangeCheckClose => crate::combat::CrewAction::RangeCheckClose,
                Kind::RangeCheckOpen => crate::combat::CrewAction::RangeCheckOpen,
                Kind::BreakPursuit => crate::combat::CrewAction::BreakPursuit,
                Kind::SensorTargeting => crate::combat::CrewAction::SensorTargeting,
                Kind::ElectronicWarfare => crate::combat::CrewAction::ElectronicWarfare,
                Kind::DamageControl => crate::combat::CrewAction::DamageControl,
                Kind::Attack => crate::combat::CrewAction::Attack {
                    mount_id: action.mount_id,
                    target_id: action.target_vessel_id,
                },
                Kind::Board => crate::combat::CrewAction::Board {
                    target_id: action.target_vessel_id,
                },
                Kind::PrepareJump => crate::combat::CrewAction::PrepareJump,
                Kind::LaunchEscapeCraft => crate::combat::CrewAction::LaunchEscapeCraft,
                Kind::OfferSurrender => crate::combat::CrewAction::OfferSurrender {
                    to_vessel_id: action.target_vessel_id,
                },
                Kind::AcceptSurrender => crate::combat::CrewAction::AcceptSurrender {
                    vessel_id: action.target_vessel_id,
                },
                Kind::InspectContact => crate::combat::CrewAction::InspectContact {
                    target_id: action.target_vessel_id,
                },
            })
        })
        .collect::<Result<Vec<_>, StoreError>>()?;
    let reactions = request
        .reactions
        .iter()
        .map(|reaction| match reaction.kind {
            crate::wire::CombatReaction::Dodge => crate::combat::ReactionKind::Dodge,
            crate::wire::CombatReaction::PointDefense => crate::combat::ReactionKind::PointDefense,
            crate::wire::CombatReaction::FireSand => crate::combat::ReactionKind::FireSand,
            crate::wire::CombatReaction::TriggerNuclearDamper => {
                crate::combat::ReactionKind::TriggerNuclearDamper
            }
            crate::wire::CombatReaction::TriggerMesonScreen => {
                crate::combat::ReactionKind::TriggerMesonScreen
            }
        })
        .collect::<Vec<_>>();
    let action_dms = vec![0; actions.len()];
    let reaction_dms = vec![0; reactions.len()];
    Ok(crate::combat::JointOrder {
        vessel_id,
        view_revision: request.view_revision,
        actions,
        action_dms,
        reactions,
        reaction_dms,
        automated: false,
    })
}

fn combat_snapshot(
    combat: &crate::combat::CombatState,
    ship: &ShipRecord,
    default: &crate::combat::JointOrder,
    actors: Vec<crate::wire::CombatActor>,
    submitted: bool,
    log: &[String],
    player_owned_ship_ids: &[u64],
) -> crate::wire::CombatSnapshot {
    let catalog = creation::ship_market_catalog()
        .into_iter()
        .map(|entry| (entry.catalog_id, entry.class_name))
        .collect::<std::collections::BTreeMap<_, _>>();
    let participants = combat
        .vessels
        .iter()
        .map(|vessel| crate::wire::CombatParticipant {
            vessel_id: vessel.vessel_id,
            side: vessel.side,
            name: vessel.name.clone(),
            class_name: catalog
                .get(&vessel.catalog_id)
                .cloned()
                .unwrap_or_else(|| "Unclassified vessel".into()),
            initiative: vessel.initiative,
            thrust: vessel.thrust,
            hull_remaining: vessel.hull_remaining,
            structure_remaining: vessel.structure_remaining,
            armor_remaining: vessel.armor_remaining,
            disposition: vessel.disposition,
            weapons: vessel
                .weapons
                .iter()
                .map(|mount| {
                    let ammunition_remaining = mount
                        .weapons
                        .iter()
                        .filter_map(|weapon| weapon.ammunition_id.as_ref())
                        .filter_map(|id| {
                            vessel
                                .ammunition
                                .iter()
                                .find(|lot| &lot.ammunition_id == id)
                                .map(|lot| lot.remaining)
                        })
                        .min()
                        .unwrap_or(u32::MAX);
                    crate::wire::CombatWeaponMount {
                        mount_id: mount.mount_id,
                        label: mount.catalog_mount_id.clone(),
                        weapons: mount
                            .weapons
                            .iter()
                            .map(|weapon| weapon.id.clone())
                            .collect(),
                        damage_hits: mount.damage_hits,
                        ammunition_remaining,
                    }
                })
                .collect(),
            commanded: vessel.vessel_id == ship.ship_id,
            player_owned: player_owned_ship_ids.contains(&vessel.vessel_id),
            online_controlled: false,
        })
        .collect();
    crate::wire::CombatSnapshot {
        combat_id: combat.combat_id,
        revision: combat.revision,
        round: combat.round,
        round_started_second: combat.round_started_second,
        order_due_second: combat
            .round_started_second
            .saturating_add(crate::combat::COMBAT_TURN_SECONDS),
        order_window_real_milliseconds: crate::combat::ORDER_WINDOW_REAL_MILLISECONDS,
        range: combat.range,
        participants,
        default_order: combat_order_wire(default, combat.combat_id, &actors),
        policy: crate::wire::CombatAutomationPolicy {
            expected_revision: ship.combat_policy.revision,
            minimum_victory_percent: ship.combat_policy.minimum_victory_percent,
            objective: ship.combat_policy.objective,
            permit_surrender: ship.combat_policy.permit_surrender,
            permit_abandon_ship: ship.combat_policy.permit_abandon_ship,
        },
        player_order_submitted: submitted,
        complete: combat.complete,
        log: log
            .iter()
            .map(|line| combat_log_text_for_snapshot(combat, line))
            .collect(),
        actors,
    }
}

fn combat_order_wire(
    order: &crate::combat::JointOrder,
    combat_id: u64,
    actors: &[crate::wire::CombatActor],
) -> crate::wire::CombatOrderSet {
    let mut assigned = HashSet::new();
    let actions = order
        .actions
        .iter()
        .filter_map(|action| {
            let (kind, mount_id, target_vessel_id) = match action {
                crate::combat::CrewAction::Hold => (crate::wire::CombatActionKind::Hold, 0, 0),
                crate::combat::CrewAction::Coordinate => {
                    (crate::wire::CombatActionKind::Coordinate, 0, 0)
                }
                crate::combat::CrewAction::IncreaseInitiative => {
                    (crate::wire::CombatActionKind::IncreaseInitiative, 0, 0)
                }
                crate::combat::CrewAction::EvasiveManeuvers => {
                    (crate::wire::CombatActionKind::EvasiveManeuvers, 0, 0)
                }
                crate::combat::CrewAction::LineUpShot => {
                    (crate::wire::CombatActionKind::LineUpShot, 0, 0)
                }
                crate::combat::CrewAction::RangeCheckClose => {
                    (crate::wire::CombatActionKind::RangeCheckClose, 0, 0)
                }
                crate::combat::CrewAction::RangeCheckOpen => {
                    (crate::wire::CombatActionKind::RangeCheckOpen, 0, 0)
                }
                crate::combat::CrewAction::BreakPursuit => {
                    (crate::wire::CombatActionKind::BreakPursuit, 0, 0)
                }
                crate::combat::CrewAction::SensorTargeting => {
                    (crate::wire::CombatActionKind::SensorTargeting, 0, 0)
                }
                crate::combat::CrewAction::ElectronicWarfare => {
                    (crate::wire::CombatActionKind::ElectronicWarfare, 0, 0)
                }
                crate::combat::CrewAction::DamageControl => {
                    (crate::wire::CombatActionKind::DamageControl, 0, 0)
                }
                crate::combat::CrewAction::Attack {
                    mount_id,
                    target_id,
                } => (crate::wire::CombatActionKind::Attack, *mount_id, *target_id),
                crate::combat::CrewAction::Board { target_id } => {
                    (crate::wire::CombatActionKind::Board, 0, *target_id)
                }
                crate::combat::CrewAction::PrepareJump => {
                    (crate::wire::CombatActionKind::PrepareJump, 0, 0)
                }
                crate::combat::CrewAction::LaunchEscapeCraft => {
                    (crate::wire::CombatActionKind::LaunchEscapeCraft, 0, 0)
                }
                crate::combat::CrewAction::OfferSurrender { to_vessel_id } => (
                    crate::wire::CombatActionKind::OfferSurrender,
                    0,
                    *to_vessel_id,
                ),
                crate::combat::CrewAction::AcceptSurrender { vessel_id } => (
                    crate::wire::CombatActionKind::AcceptSurrender,
                    0,
                    *vessel_id,
                ),
                crate::combat::CrewAction::InspectContact { target_id } => {
                    (crate::wire::CombatActionKind::InspectContact, 0, *target_id)
                }
            };
            let actor_person_id = preferred_combat_actor(actors, kind, &assigned)?;
            assigned.insert(actor_person_id);
            Some(crate::wire::CombatAction {
                kind,
                mount_id,
                target_vessel_id,
                actor_person_id,
            })
        })
        .collect();
    let reactions = order
        .reactions
        .iter()
        .filter_map(|reaction| {
            let kind = match reaction {
                crate::combat::ReactionKind::Dodge => crate::wire::CombatReaction::Dodge,
                crate::combat::ReactionKind::PointDefense => {
                    crate::wire::CombatReaction::PointDefense
                }
                crate::combat::ReactionKind::FireSand => crate::wire::CombatReaction::FireSand,
                crate::combat::ReactionKind::TriggerNuclearDamper => {
                    crate::wire::CombatReaction::TriggerNuclearDamper
                }
                crate::combat::ReactionKind::TriggerMesonScreen => {
                    crate::wire::CombatReaction::TriggerMesonScreen
                }
            };
            let actor_person_id = preferred_reaction_actor(actors, kind)?;
            Some(crate::wire::CombatReactionOrder {
                kind,
                actor_person_id,
            })
        })
        .collect();
    crate::wire::CombatOrderSet {
        combat_id,
        view_revision: order.view_revision,
        actions,
        reactions,
        use_tactical_controller: false,
    }
}

fn preferred_combat_actor(
    actors: &[crate::wire::CombatActor],
    kind: crate::wire::CombatActionKind,
    assigned: &HashSet<u64>,
) -> Option<u64> {
    let station_matches = |station: &str| {
        let station = station.to_ascii_lowercase();
        match kind {
            crate::wire::CombatActionKind::Coordinate
            | crate::wire::CombatActionKind::IncreaseInitiative
            | crate::wire::CombatActionKind::OfferSurrender
            | crate::wire::CombatActionKind::AcceptSurrender
            | crate::wire::CombatActionKind::LaunchEscapeCraft => station.contains("captain"),
            crate::wire::CombatActionKind::EvasiveManeuvers
            | crate::wire::CombatActionKind::LineUpShot
            | crate::wire::CombatActionKind::BreakPursuit => station.contains("pilot"),
            crate::wire::CombatActionKind::RangeCheckClose
            | crate::wire::CombatActionKind::RangeCheckOpen
            | crate::wire::CombatActionKind::PrepareJump => {
                station.contains("navigator") || station.contains("astrogator")
            }
            crate::wire::CombatActionKind::SensorTargeting
            | crate::wire::CombatActionKind::ElectronicWarfare
            | crate::wire::CombatActionKind::InspectContact => {
                station.contains("sensor") || station.contains("comm")
            }
            crate::wire::CombatActionKind::DamageControl => {
                station.contains("damage") || station.contains("engineer")
            }
            crate::wire::CombatActionKind::Attack => station.contains("gunner"),
            crate::wire::CombatActionKind::Board => {
                station.contains("marine") || station.contains("security")
            }
            crate::wire::CombatActionKind::Hold => true,
        }
    };
    actors
        .iter()
        .find(|actor| {
            actor.available
                && !assigned.contains(&actor.person_id)
                && station_matches(&actor.station)
        })
        .or_else(|| {
            actors.iter().find(|actor| {
                actor.available
                    && !assigned.contains(&actor.person_id)
                    && actor.station.eq_ignore_ascii_case("captain")
            })
        })
        .map(|actor| actor.person_id)
}

fn preferred_reaction_actor(
    actors: &[crate::wire::CombatActor],
    kind: crate::wire::CombatReaction,
) -> Option<u64> {
    actors
        .iter()
        .find(|actor| {
            if !actor.available {
                return false;
            }
            let station = actor.station.to_ascii_lowercase();
            match kind {
                crate::wire::CombatReaction::Dodge => station.contains("pilot"),
                _ => station.contains("gunner"),
            }
        })
        .or_else(|| {
            actors
                .iter()
                .find(|actor| actor.available && actor.station.eq_ignore_ascii_case("captain"))
        })
        .map(|actor| actor.person_id)
}

fn combat_actor_available(service: &CrewServiceRecord, person: &PersonRecord) -> bool {
    service.availability == CrewAvailability::Active
        && !person_incapacitated(person)
        && !service.assigned_slot_ids.is_empty()
}

fn crew_role_supports_skill(role: &str, skill: crate::wire::SkillId) -> bool {
    let role = role.to_ascii_lowercase();
    match skill {
        crate::wire::SkillId::PilotSpacecraft | crate::wire::SkillId::PilotSmallCraft => {
            role.contains("pilot")
        }
        crate::wire::SkillId::Astrogation => {
            role.contains("navigator") || role.contains("astrogator")
        }
        crate::wire::SkillId::EngineerJump
        | crate::wire::SkillId::EngineerManeuver
        | crate::wire::SkillId::EngineerPower => role.contains("engineer"),
        crate::wire::SkillId::Mechanic => role.contains("engineer") || role.contains("damage"),
        crate::wire::SkillId::Medicine => role.contains("medic"),
        crate::wire::SkillId::Communications => role.contains("comm"),
        crate::wire::SkillId::Electronics
        | crate::wire::SkillId::Computer
        | crate::wire::SkillId::Investigate => role.contains("sensor"),
        crate::wire::SkillId::GunnerTurrets
        | crate::wire::SkillId::GunnerCapital
        | crate::wire::SkillId::GunnerScreens => role.contains("gunner"),
        crate::wire::SkillId::Leadership | crate::wire::SkillId::Admin => {
            role.contains("captain") || role.contains("command")
        }
        _ => true,
    }
}

fn combat_action_role_matches(role: &str, kind: crate::wire::CombatActionKind) -> bool {
    let role = role.to_ascii_lowercase();
    if role.contains("captain") {
        return true;
    }
    match kind {
        crate::wire::CombatActionKind::Hold => true,
        crate::wire::CombatActionKind::Coordinate
        | crate::wire::CombatActionKind::IncreaseInitiative
        | crate::wire::CombatActionKind::OfferSurrender
        | crate::wire::CombatActionKind::AcceptSurrender
        | crate::wire::CombatActionKind::LaunchEscapeCraft => false,
        crate::wire::CombatActionKind::EvasiveManeuvers
        | crate::wire::CombatActionKind::LineUpShot
        | crate::wire::CombatActionKind::BreakPursuit => role.contains("pilot"),
        crate::wire::CombatActionKind::RangeCheckClose
        | crate::wire::CombatActionKind::RangeCheckOpen
        | crate::wire::CombatActionKind::PrepareJump => {
            role.contains("navigator") || role.contains("astrogator")
        }
        crate::wire::CombatActionKind::SensorTargeting
        | crate::wire::CombatActionKind::ElectronicWarfare
        | crate::wire::CombatActionKind::InspectContact => {
            role.contains("sensor") || role.contains("comm")
        }
        crate::wire::CombatActionKind::DamageControl => {
            role.contains("damage") || role.contains("engineer")
        }
        crate::wire::CombatActionKind::Attack => role.contains("gunner"),
        crate::wire::CombatActionKind::Board => {
            role.contains("marine") || role.contains("security")
        }
    }
}

fn combat_reaction_role_matches(role: &str, kind: crate::wire::CombatReaction) -> bool {
    let role = role.to_ascii_lowercase();
    role.contains("captain")
        || match kind {
            crate::wire::CombatReaction::Dodge => role.contains("pilot"),
            _ => role.contains("gunner"),
        }
}

fn combat_action_task_dm(
    person: &PersonRecord,
    kind: crate::wire::CombatActionKind,
    mount_id: u16,
    combat: &crate::combat::CombatState,
    vessel_id: u64,
    ordinal: usize,
) -> i8 {
    use crate::wire::CombatActionKind as Kind;
    use crate::wire::SkillId;
    let assignment = match kind {
        Kind::Coordinate | Kind::IncreaseInitiative => {
            Some((person.person.characteristics.charisma, SkillId::Leadership))
        }
        Kind::EvasiveManeuvers | Kind::LineUpShot | Kind::BreakPursuit => {
            Some((person.current_dexterity, SkillId::PilotSpacecraft))
        }
        Kind::RangeCheckClose | Kind::RangeCheckOpen | Kind::PrepareJump => Some((
            person.person.characteristics.education,
            SkillId::Astrogation,
        )),
        Kind::SensorTargeting | Kind::InspectContact => Some((
            person.person.characteristics.education,
            SkillId::Communications,
        )),
        Kind::ElectronicWarfare => Some((
            person.person.characteristics.intelligence,
            SkillId::Communications,
        )),
        Kind::DamageControl => Some((person.person.characteristics.education, SkillId::Mechanic)),
        Kind::Attack => {
            let capital = combat
                .vessels
                .iter()
                .find(|vessel| vessel.vessel_id == vessel_id)
                .and_then(|vessel| {
                    vessel
                        .weapons
                        .iter()
                        .find(|mount| mount.mount_id == mount_id)
                })
                .is_some_and(|mount| mount.weapons.iter().any(|weapon| weapon.bay));
            Some((
                person.current_dexterity,
                if capital {
                    SkillId::GunnerCapital
                } else {
                    SkillId::GunnerTurrets
                },
            ))
        }
        Kind::Board => Some((
            person.person.characteristics.intelligence,
            SkillId::TacticsMilitary,
        )),
        Kind::Hold | Kind::LaunchEscapeCraft | Kind::OfferSurrender | Kind::AcceptSurrender => None,
    };
    assignment.map_or(0, |(characteristic, skill)| {
        combat_person_task_dm(person, characteristic, skill, combat, vessel_id, ordinal)
    })
}

fn combat_reaction_task_dm(
    person: &PersonRecord,
    kind: crate::wire::CombatReaction,
    combat: &crate::combat::CombatState,
    vessel_id: u64,
    ordinal: usize,
) -> i8 {
    let skill = match kind {
        crate::wire::CombatReaction::Dodge => crate::wire::SkillId::PilotSpacecraft,
        crate::wire::CombatReaction::TriggerNuclearDamper
        | crate::wire::CombatReaction::TriggerMesonScreen => crate::wire::SkillId::GunnerScreens,
        crate::wire::CombatReaction::PointDefense | crate::wire::CombatReaction::FireSand => {
            crate::wire::SkillId::GunnerTurrets
        }
    };
    combat_person_task_dm(
        person,
        person.current_dexterity,
        skill,
        combat,
        vessel_id,
        ordinal.saturating_add(128),
    )
}

fn combat_person_task_dm(
    person: &PersonRecord,
    characteristic: u8,
    skill: crate::wire::SkillId,
    combat: &crate::combat::CombatState,
    vessel_id: u64,
    ordinal: usize,
) -> i8 {
    let condition_dm = person_condition_dm(person);
    let result = crate::task_resolution::resolve(
        &person.person,
        crate::task_resolution::TaskRequest {
            characteristic,
            skill,
            difficulty: 8,
            equipment_dm: 0,
            condition_dm,
            assistance_dm: 0,
            entropy: crate::ship_condition::mix64(
                combat.combat_id
                    ^ combat.revision.rotate_left(9)
                    ^ vessel_id.rotate_left(21)
                    ^ person.person_id.rotate_left(35)
                    ^ ordinal as u64,
            ),
        },
    );
    result
        .characteristic_dm
        .saturating_add(result.skill_dm)
        .saturating_add(condition_dm)
}

fn combat_vessel_name(combat: &crate::combat::CombatState, vessel_id: u64) -> &str {
    combat
        .vessels
        .iter()
        .find(|vessel| vessel.vessel_id == vessel_id)
        .map_or("Unknown vessel", |vessel| vessel.name.as_str())
}

fn combat_log_text_for_snapshot(combat: &crate::combat::CombatState, text: &str) -> String {
    // Active encounters created by older servers may still contain the former
    // "Vessel <u64>" prose. Translate those lines while presenting the snapshot
    // so an in-progress fight becomes readable immediately after an upgrade.
    combat.vessels.iter().fold(text.to_owned(), |line, vessel| {
        line.replace(
            &format!("Vessel {}", vessel.vessel_id),
            vessel.name.as_str(),
        )
        .replace(
            &format!("vessel {}", vessel.vessel_id),
            vessel.name.as_str(),
        )
    })
}

fn combat_event_text(
    combat: &crate::combat::CombatState,
    event: &crate::combat::CombatEvent,
) -> String {
    let vessel = |vessel_id| combat_vessel_name(combat, vessel_id);
    match event {
        crate::combat::CombatEvent::Action {
            vessel_id,
            description,
        } => format!("{}: {description}.", vessel(*vessel_id)),
        crate::combat::CombatEvent::AttackMissed {
            vessel_id,
            target_id,
            mount_id,
        } => format!(
            "{} mount {mount_id} misses {}.",
            vessel(*vessel_id),
            vessel(*target_id)
        ),
        crate::combat::CombatEvent::MissileLaunched {
            vessel_id,
            target_id,
            impact_round,
        } => format!(
            "{} launches missiles at {}; predicted impact is round {impact_round}.",
            vessel(*vessel_id),
            vessel(*target_id)
        ),
        crate::combat::CombatEvent::Damage {
            vessel_id,
            target_id,
            damage,
            hits,
        } => format!(
            "{} penetrates {} for {damage} damage and {hits} system hit(s).",
            vessel(*vessel_id),
            vessel(*target_id)
        ),
        crate::combat::CombatEvent::Withdrawal { vessel_id } => {
            format!("{} breaks contact.", vessel(*vessel_id))
        }
        crate::combat::CombatEvent::SurrenderOffered {
            vessel_id,
            to_vessel_id,
        } => format!(
            "{} offers surrender to {}.",
            vessel(*vessel_id),
            vessel(*to_vessel_id)
        ),
        crate::combat::CombatEvent::SurrenderAccepted {
            vessel_id,
            by_vessel_id,
        } => format!(
            "{} accepts {}'s surrender.",
            vessel(*by_vessel_id),
            vessel(*vessel_id)
        ),
        crate::combat::CombatEvent::BoardingStarted {
            attacker_id,
            defender_id,
        } => format!(
            "{} begins boarding {}.",
            vessel(*attacker_id),
            vessel(*defender_id)
        ),
        crate::combat::CombatEvent::BattlefieldRepair { vessel_id, targets } => {
            let targets = targets
                .iter()
                .map(|target| match target {
                    crate::combat::RepairTarget::Bridge => "bridge".into(),
                    crate::combat::RepairTarget::Sensors => "sensors".into(),
                    crate::combat::RepairTarget::ManeuverDrive => "maneuver drive".into(),
                    crate::combat::RepairTarget::JumpDrive => "Jump drive".into(),
                    crate::combat::RepairTarget::PowerPlant => "power plant".into(),
                    crate::combat::RepairTarget::FuelSystem => "fuel system".into(),
                    crate::combat::RepairTarget::CargoHold => "cargo hold".into(),
                    crate::combat::RepairTarget::WeaponMount(mount_id) => {
                        format!("weapon mount {mount_id}")
                    }
                })
                .collect::<Vec<String>>()
                .join(", ");
            format!(
                "{} establishes battlefield coverage on {targets}.",
                vessel(*vessel_id)
            )
        }
        crate::combat::CombatEvent::InspectionCompleted {
            vessel_id,
            target_id,
        } => format!(
            "{} completes and seals a sensor inspection of {}.",
            vessel(*vessel_id),
            vessel(*target_id)
        ),
        crate::combat::CombatEvent::VesselDestroyed { vessel_id } => {
            format!("{} is destroyed.", vessel(*vessel_id))
        }
    }
}

fn recovery_priority(kind: ShipSubsystemKind) -> (u8, &'static str) {
    match kind {
        ShipSubsystemKind::LifeSupport => (0, "restore life support"),
        ShipSubsystemKind::Hull
        | ShipSubsystemKind::Structure
        | ShipSubsystemKind::PowerPlant
        | ShipSubsystemKind::Bridge
        | ShipSubsystemKind::FuelSystem => (1, "restore dependencies for propulsion and survival"),
        ShipSubsystemKind::ManeuverDrive => (2, "restore maneuver drive"),
        ShipSubsystemKind::JumpDrive => (3, "restore jump drive"),
        ShipSubsystemKind::WeaponMount | ShipSubsystemKind::Screen => (4, "restore weapons"),
        _ => (5, "restore remaining ship systems"),
    }
}

fn begin_offline_recovery(ship: &mut ShipRecord, current_second: u64) {
    // CE battlefield coverage fails when combat ends.  The persistent damage
    // remains for the ordinary repair scheduler; keeping these separate is a
    // deliberate invariant, not a cosmetic reset.
    for subsystem in &mut ship.subsystems {
        subsystem.battlefield_repair_hits = 0;
    }
    ship.recovery_plan = ship
        .subsystems
        .iter()
        .filter(|subsystem| subsystem.sustained_hits != 0)
        .min_by_key(|subsystem| {
            (
                recovery_priority(subsystem.kind).0,
                subsystem.sustained_hits >= subsystem.maximum_hits,
                subsystem.subsystem_id,
            )
        })
        .map(|subsystem| PostCombatRecoveryPlan {
            revision: 1,
            started_second: current_second,
            target_subsystem_id: subsystem.subsystem_id,
            goal: recovery_priority(subsystem.kind).1.into(),
            status: if subsystem.sustained_hits >= subsystem.maximum_hits {
                "Destroyed installation requires refurbishment or replacement".into()
            } else {
                "Recovery watch assigned; awaiting proper repair capability".into()
            },
        });
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ShipSubsystemRecord {
    pub subsystem_id: u16,
    pub kind: ShipSubsystemKind,
    pub label: String,
    /// Underlying damage. Permanent repair reduces this value.
    pub sustained_hits: u16,
    /// Temporary coverage only. It is cleared when the encounter ends.
    pub battlefield_repair_hits: u16,
    pub maximum_hits: u16,
    /// Only a completed proper repair changes this timestamp.
    pub last_proper_repair_second: u64,
    /// Refits do not reset installation age; replacement does.
    pub installed_second: u64,
    pub last_refit_second: u64,
    pub calendar_age_months: u32,
    pub operating_seconds: u64,
    pub duty_cycles: u32,
    pub skimming_cycles: u32,
    /// Damage attributable to CE missed-maintenance degradation checks.
    pub neglect_damage_hits: u16,
    pub component_kind: String,
    pub component_id: String,
    pub displacement_millitons: u64,
    pub replacement_price_credits: u64,
    pub installation_generation: u16,
    pub reconditioned: bool,
    pub component_warranty_expires_second: u64,
}

