    fn collect_tax_arrears_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<u64, StoreError> {
        let key = encode_identity(identity);
        let Some(mut player) = self
            .players
            .get(txn, &key)?
            .map(decode_player_record)
            .transpose()?
        else {
            return Ok(0);
        };
        let collected = player.credits.min(player.tax_arrears_credits);
        if collected == 0 {
            return Ok(0);
        }
        player.credits -= collected;
        player.tax_arrears_credits -= collected;
        let balance = self
            .polity_fiscal
            .get(txn, &identity.bbs_id)?
            .map(decode_u64)
            .transpose()?
            .unwrap_or(0)
            .saturating_add(collected);
        self.polity_fiscal
            .put(txn, &identity.bbs_id, &balance.to_be_bytes())?;
        self.players
            .put(txn, &key, &encode_player_record(&player))?;
        Ok(collected)
    }

    fn apply_sysop_directive_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        message_id: u64,
        received_second: u64,
        player: &mut PlayerRecord,
    ) -> Result<(), StoreError> {
        let Some(mut directive) = self
            .sysop_directives
            .get(txn, &message_id)?
            .map(decode_sysop_directive)
            .transpose()?
        else {
            return Ok(());
        };
        if directive.identity != *identity || directive.applied_second.is_some() {
            return Ok(());
        }
        match directive.kind {
            SysopDirectiveKind::Tax { credits } => {
                player.tax_arrears_credits = player.tax_arrears_credits.saturating_add(credits);
                let collected = player.credits.min(player.tax_arrears_credits);
                player.credits -= collected;
                player.tax_arrears_credits -= collected;
                let fiscal = self
                    .polity_fiscal
                    .get(txn, &identity.bbs_id)?
                    .map(decode_u64)
                    .transpose()?
                    .unwrap_or(0)
                    .saturating_add(collected);
                self.polity_fiscal
                    .put(txn, &identity.bbs_id, &fiscal.to_be_bytes())?;
            }
            SysopDirectiveKind::Demote { naval_grade_index } => {
                let mut career = self.career_state_in(txn, identity)?;
                if career.mode == crate::careers::CombatCareerMode::Navy
                    && naval_grade_index < career.naval_grade_index
                {
                    career.naval_grade_index = naval_grade_index;
                    let maximum_points = crate::careers::NAVAL_GRADES
                        .get(usize::from(naval_grade_index) + 1)
                        .map_or(u16::MAX, |next| next.minimum_points.saturating_sub(1));
                    career.service_points = career.service_points.min(maximum_points);
                    for opportunity in &mut career.opportunities {
                        if opportunity.kind == crate::careers::OpportunityKind::NavalOrder
                            && matches!(
                                opportunity.state,
                                crate::careers::OpportunityState::Offered
                                    | crate::careers::OpportunityState::Accepted
                            )
                        {
                            opportunity.state = crate::careers::OpportunityState::Expired;
                        }
                    }
                    career.revision = career.revision.saturating_add(1);
                    self.put_career_state_in(txn, identity, &career)?;
                }
            }
        }
        directive.applied_second = Some(received_second);
        self.sysop_directives
            .put(txn, &message_id, &encode_sysop_directive(&directive))?;
        Ok(())
    }

    fn flight_plan_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<FlightPlanSnapshot, StoreError> {
        Ok(self
            .flight_plans
            .get(txn, &encode_identity(identity))?
            .map(decode_flight_plan_snapshot)
            .transpose()?
            .unwrap_or(FlightPlanSnapshot {
                plan_id: 0,
                revision: 0,
                current_step: 0,
                state: FlightPlanState::Inactive,
                steps: Vec::new(),
                policy: EncounterPolicy::default(),
                suspension_reason: String::new(),
            }))
    }

    fn projected_primary_approach_seconds_in(
        &self,
        txn: &heed::RoTxn<'_>,
        system_id: u64,
        projected_second: u64,
        thrust_g: u8,
    ) -> Result<u64, StoreError> {
        let system = self
            .systems
            .get(txn, &system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt(
                "flight-plan approach system is missing",
            ))?;
        let celestial = derive_celestial_system(&system)?;
        let approach = primary_world_jump_safety(
            &celestial,
            projected_second as f64 / crate::simulation::SECONDS_PER_DAY as f64,
            f64::from(thrust_g),
        );
        Ok((approach.travel_days * crate::simulation::SECONDS_PER_DAY as f64).ceil() as u64)
    }

    fn preview_flight_plan_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        proposal: &FlightPlanProposal,
    ) -> Result<RuleResult<FlightPlanPreview>, StoreError> {
        let current = self.flight_plan_in(txn, identity)?;
        if proposal.expected_plan_revision != current.revision {
            return Ok(RuleResult::Rejected(format!(
                "flight plan revision {} is stale; current revision is {}",
                proposal.expected_plan_revision, current.revision
            )));
        }
        if proposal.steps.is_empty() || proposal.steps.len() > 64 {
            return Ok(RuleResult::Rejected(
                "a flight plan must contain between one and 64 waypoints".into(),
            ));
        }
        let terminal_steps = proposal
            .steps
            .iter()
            .enumerate()
            .filter(|(_, step)| step.terminal)
            .map(|(index, _)| index)
            .collect::<Vec<_>>();
        if terminal_steps.len() != 1 || terminal_steps[0] + 1 != proposal.steps.len() {
            return Ok(RuleResult::Rejected(
                "a flight plan must have one terminal waypoint, and it must be last".into(),
            ));
        }
        let (player, ship) = self.player_and_ship_in(txn, identity)?;
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let game_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let mut system_id = ship.system_id;
        let mut fuel_millitons = 0_u64;
        let mut available_fuel_millitons = ship.current_fuel_millitons;
        let mut available_unrefined_millitons = ship.unrefined_fuel_millitons;
        let mut fuel_timings = Vec::new();
        let mut available_credits =
            self.operating_account_credits_in(txn, &player, ship.ship_id)?;
        let mut elapsed_seconds = match ship.location {
            ShipLocationRecord::InFlight(FlightLegRecord {
                due_second,
                purpose:
                    FlightLegPurpose::DepartForJump { .. }
                    | FlightLegPurpose::DepartForCoordinateJump { .. },
                ..
            }) => due_second.saturating_sub(game_second),
            _ => 0,
        };
        let mut at_primary_port = matches!(ship.location, ShipLocationRecord::Docked { .. });
        let mut warnings = Vec::new();
        let mut unattended_waypoints = Vec::new();
        let mut docked_arrivals = HashMap::new();
        let mut step_elapsed_seconds = Vec::with_capacity(proposal.steps.len());
        for (index, step) in proposal.steps.iter().enumerate() {
            if step.locus.system_id() != system_id {
                return Ok(RuleResult::Rejected(format!(
                    "waypoint {} is not reachable from the preceding action",
                    index + 1
                )));
            }
            match step.action {
                FlightPlanAction::Jump {
                    destination_system_id,
                    navigation,
                    proceed_on_known_bad_plot,
                } => {
                    let origin_position = if system_id == 0 {
                        let FlightLocus::DeepSpace { position } = step.locus else {
                            return Ok(RuleResult::Rejected(format!(
                                "waypoint {} must name the ship's deep-space holding locus",
                                index + 1
                            )));
                        };
                        let ShipLocationRecord::Holding {
                            locus: ShipLocusRecord::DeepSpace { position: held },
                            ..
                        } = ship.location
                        else {
                            return Ok(RuleResult::Rejected(
                                "the ship is not holding at deep-space coordinates".into(),
                            ));
                        };
                        if position != held {
                            return Ok(RuleResult::Rejected(format!(
                                "waypoint {} does not match the ship's holding coordinates",
                                index + 1
                            )));
                        }
                        position.parsecs()
                    } else {
                        if step.locus != (FlightLocus::JumpLocus { system_id }) {
                            return Ok(RuleResult::Rejected(format!(
                                "waypoint {} must name the current system's Jump locus",
                                index + 1
                            )));
                        }
                        self.systems
                            .get(txn, &system_id)?
                            .map(decode_stellar_system)
                            .transpose()?
                            .ok_or(StoreError::Corrupt("flight-plan origin system is missing"))?
                            .position_parsecs
                    };
                    if system_id != 0 && step.locus != (FlightLocus::JumpLocus { system_id }) {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} must name the current system's Jump locus",
                            index + 1
                        )));
                    }
                    let Some(destination) = self
                        .systems
                        .get(txn, &destination_system_id)?
                        .map(decode_stellar_system)
                        .transpose()?
                    else {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} names an unknown jump destination",
                            index + 1
                        )));
                    };
                    let distance = origin_position
                        .iter()
                        .zip(destination.position_parsecs)
                        .map(|(left, right)| (left - right).powi(2))
                        .sum::<f64>()
                        .sqrt();
                    if navigation == crate::wire::JumpNavigationMethod::CommercialTape {
                        if system_id == 0 {
                            return Ok(RuleResult::Rejected(format!(
                                "waypoint {} cannot purchase a commercial tape in deep space",
                                index + 1
                            )));
                        }
                        let origin_facility = self
                            .facilities
                            .get(txn, &system_id)?
                            .map(decode_facility)
                            .transpose()?
                            .ok_or(StoreError::Corrupt(
                                "course-tape origin facility is missing",
                            ))?;
                        let destination_world = self.primary_world_in(txn, &destination)?;
                        if !origin_facility.operational
                            || origin_facility.starport as u8 > crate::universe::Starport::D as u8
                            || !destination_world.is_inhabited()
                        {
                            return Ok(RuleResult::Rejected(format!(
                                "waypoint {} is not eligible for a standard Class-D-or-better populated-world course tape",
                                index + 1
                            )));
                        }
                    }
                    if distance > f64::from(spec.jump_rating) + 1.0e-9 {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} requires {:.3} pc, beyond Jump-{}",
                            index + 1,
                            distance,
                            spec.jump_rating
                        )));
                    }
                    if at_primary_port {
                        elapsed_seconds = elapsed_seconds.saturating_add(
                            self.projected_primary_approach_seconds_in(
                                txn,
                                system_id,
                                game_second.saturating_add(elapsed_seconds),
                                spec.thrust_g,
                            )?,
                        );
                    }
                    let leg_fuel = jump_fuel_for_distance(spec.displacement_millitons, distance);
                    if navigation == crate::wire::JumpNavigationMethod::CommercialTape {
                        warnings.push(FlightPlanWarning {
                            code: "COURSE_TAPE_COST".into(),
                            message: format!(
                                "A fresh course tape costs Cr{}.",
                                1_000_u64
                                    .saturating_mul(u64::from(jump_number_for_distance(distance)))
                            ),
                            step_indices: vec![index as u16],
                        });
                    }
                    if proceed_on_known_bad_plot {
                        warnings.push(FlightPlanWarning {
                            code: "KNOWN_BAD_PLOT_AUTHORITY".into(),
                            message: "Firing on a failed plot is authorized; CE makes that an automatic misjump."
                                .into(),
                            step_indices: vec![index as u16],
                        });
                    }
                    fuel_millitons = fuel_millitons.saturating_add(leg_fuel);
                    let projected_burn = leg_fuel.min(available_fuel_millitons);
                    let (_, unrefined_burn) = proportional_fuel_burn(
                        available_fuel_millitons,
                        available_unrefined_millitons,
                        projected_burn,
                    );
                    if unrefined_burn != 0 {
                        warnings.push(FlightPlanWarning {
                            code: "UNREFINED_JUMP_FUEL".into(),
                            message: "This Jump burns mixed or unrefined fuel and takes the normal -2 misjump DM."
                                .into(),
                            step_indices: vec![index as u16],
                        });
                    }
                    available_unrefined_millitons =
                        available_unrefined_millitons.saturating_sub(unrefined_burn);
                    if available_fuel_millitons < leg_fuel {
                        warnings.push(FlightPlanWarning {
                            code: "INSUFFICIENT_CARRIED_FUEL".into(),
                            message: "This step cannot begin with the fuel projected to be aboard."
                                .into(),
                            step_indices: vec![index as u16],
                        });
                        available_fuel_millitons = 0;
                    } else {
                        available_fuel_millitons -= leg_fuel;
                    }
                    elapsed_seconds = elapsed_seconds.saturating_add(STANDARD_JUMP_SECONDS);
                    system_id = destination_system_id;
                    at_primary_port = false;
                }
                FlightPlanAction::JumpCoordinates {
                    destination,
                    navigation,
                    proceed_on_known_bad_plot,
                } => {
                    if navigation == crate::wire::JumpNavigationMethod::CommercialTape {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} targets coordinates rather than a populated world; no standard commercial course tape is available",
                            index + 1
                        )));
                    }
                    if !destination.is_finite() {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} contains a non-finite coordinate",
                            index + 1
                        )));
                    }
                    if step.locus != (FlightLocus::JumpLocus { system_id }) || system_id == 0 {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} must begin at the current system's Jump locus",
                            index + 1
                        )));
                    }
                    let origin = self
                        .systems
                        .get(txn, &system_id)?
                        .map(decode_stellar_system)
                        .transpose()?
                        .ok_or(StoreError::Corrupt(
                            "coordinate-jump origin system is missing",
                        ))?;
                    let target = destination.parsecs();
                    let distance = origin
                        .position_parsecs
                        .iter()
                        .zip(target)
                        .map(|(left, right)| (left - right).powi(2))
                        .sum::<f64>()
                        .sqrt();
                    if distance > f64::from(spec.jump_rating) + 1.0e-9 {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} requires {:.3} pc, beyond Jump-{}",
                            index + 1,
                            distance,
                            spec.jump_rating
                        )));
                    }
                    if at_primary_port {
                        elapsed_seconds = elapsed_seconds.saturating_add(
                            self.projected_primary_approach_seconds_in(
                                txn,
                                system_id,
                                game_second.saturating_add(elapsed_seconds),
                                spec.thrust_g,
                            )?,
                        );
                    }
                    let leg_fuel = jump_fuel_for_distance(spec.displacement_millitons, distance);
                    if navigation == crate::wire::JumpNavigationMethod::CommercialTape {
                        warnings.push(FlightPlanWarning {
                            code: "COURSE_TAPE_COST".into(),
                            message: format!(
                                "A fresh coordinate course tape costs Cr{}.",
                                1_000_u64
                                    .saturating_mul(u64::from(jump_number_for_distance(distance)))
                            ),
                            step_indices: vec![index as u16],
                        });
                    }
                    if proceed_on_known_bad_plot {
                        warnings.push(FlightPlanWarning {
                            code: "KNOWN_BAD_PLOT_AUTHORITY".into(),
                            message: "Firing on a failed plot is authorized; CE makes that an automatic misjump."
                                .into(),
                            step_indices: vec![index as u16],
                        });
                    }
                    fuel_millitons = fuel_millitons.saturating_add(leg_fuel);
                    let projected_burn = leg_fuel.min(available_fuel_millitons);
                    let (_, unrefined_burn) = proportional_fuel_burn(
                        available_fuel_millitons,
                        available_unrefined_millitons,
                        projected_burn,
                    );
                    if unrefined_burn != 0 {
                        warnings.push(FlightPlanWarning {
                            code: "UNREFINED_JUMP_FUEL".into(),
                            message: "This Jump burns mixed or unrefined fuel and takes the normal -2 misjump DM."
                                .into(),
                            step_indices: vec![index as u16],
                        });
                    }
                    available_unrefined_millitons =
                        available_unrefined_millitons.saturating_sub(unrefined_burn);
                    if available_fuel_millitons < leg_fuel {
                        warnings.push(FlightPlanWarning {
                            code: "INSUFFICIENT_CARRIED_FUEL".into(),
                            message: "This step cannot begin with the fuel projected to be aboard."
                                .into(),
                            step_indices: vec![index as u16],
                        });
                        available_fuel_millitons = 0;
                    } else {
                        available_fuel_millitons -= leg_fuel;
                    }
                    elapsed_seconds = elapsed_seconds.saturating_add(STANDARD_JUMP_SECONDS);
                    system_id = 0;
                    at_primary_port = false;
                }
                FlightPlanAction::BeltCycle { body_id } => {
                    if !at_primary_port {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} must begin from the system's primary berth",
                            index + 1
                        )));
                    }
                    if spec.mining_drone_sets == 0 {
                        return Ok(RuleResult::Rejected(
                            "this ship has no mining-drone set for a belt cycle".into(),
                        ));
                    }
                    let FlightLocus::Body {
                        system_id: belt_system,
                        body_id: locus_body,
                    } = step.locus
                    else {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} must name a planetoid belt",
                            index + 1
                        )));
                    };
                    if belt_system != system_id || locus_body != body_id {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} belt identity disagrees with its action",
                            index + 1
                        )));
                    }
                    let stellar = self
                        .systems
                        .get(txn, &system_id)?
                        .map(decode_stellar_system)
                        .transpose()?
                        .ok_or(StoreError::Corrupt("belt system is missing"))?;
                    let celestial = derive_celestial_system(&stellar)?;
                    if !celestial.bodies.iter().any(|body| {
                        body.local_id == body_id
                            && matches!(body.kind, BodyKind::PlanetoidBelt { .. })
                    }) {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} is not a catalogued planetoid belt",
                            index + 1
                        )));
                    }
                    let Some(egress_index) = proposal.steps[index + 1..]
                        .iter()
                        .position(|candidate| {
                            matches!(candidate.action, FlightPlanAction::Dock { .. })
                        })
                        .map(|offset| index + 1 + offset)
                    else {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} needs a later prevalidated port egress",
                            index + 1
                        )));
                    };
                    let days = game_second.saturating_add(elapsed_seconds) as f64
                        / crate::simulation::SECONDS_PER_DAY as f64;
                    let primary_id = celestial
                        .bodies
                        .iter()
                        .find(|body| body.is_primary_world)
                        .map(|body| body.local_id)
                        .ok_or(StoreError::Corrupt("system has no primary world"))?;
                    let primary = body_position_au(&celestial, days, primary_id)
                        .ok_or(StoreError::Corrupt("primary world position is missing"))?;
                    let target = body_position_au(&celestial, days, body_id)
                        .ok_or(StoreError::Corrupt("belt position is missing"))?;
                    let distance_au = primary
                        .iter()
                        .zip(target)
                        .map(|(a, b)| (a - b).powi(2))
                        .sum::<f64>()
                        .sqrt();
                    let transit = (rest_to_rest_travel_days(distance_au, f64::from(spec.thrust_g))
                        * crate::simulation::SECONDS_PER_DAY as f64)
                        .ceil() as u64;
                    let local_cycle = transit
                        .saturating_mul(2)
                        .saturating_add(crate::mining::WATCH_SECONDS * 2)
                        .saturating_add(crate::mining::DAY_SECONDS);
                    let jump_count = proposal.steps[index + 1..=egress_index]
                        .iter()
                        .filter(|candidate| {
                            matches!(
                                candidate.action,
                                FlightPlanAction::Jump { .. }
                                    | FlightPlanAction::JumpCoordinates { .. }
                            )
                        })
                        .count() as u64;
                    let reserve_duration = local_cycle
                        .saturating_add(
                            jump_count.saturating_mul(crate::mining::MAXIMUM_JUMP_SECONDS),
                        )
                        .saturating_add(crate::mining::SAFE_MARGIN_SECONDS);
                    let power_fuel = crate::mining::power_fuel_for_duration(
                        spec.power_fuel_millitons,
                        spec.power_plant_endurance_seconds,
                        reserve_duration,
                    );
                    if available_fuel_millitons < power_fuel {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} needs {:.1} tons of protected power-plant reserve through its filed egress",
                            index + 1,
                            power_fuel as f64 / 1_000.0
                        )));
                    }
                    let (_, unrefined_power_burn) = proportional_fuel_burn(
                        available_fuel_millitons,
                        available_unrefined_millitons,
                        power_fuel,
                    );
                    available_fuel_millitons -= power_fuel;
                    available_unrefined_millitons =
                        available_unrefined_millitons.saturating_sub(unrefined_power_burn);
                    fuel_millitons = fuel_millitons.saturating_add(power_fuel);
                    elapsed_seconds = elapsed_seconds.saturating_add(local_cycle);
                    at_primary_port = true;
                }
                FlightPlanAction::Fuel {
                    operation,
                    quantity_millitons,
                    refine_collected,
                } => {
                    if quantity_millitons == 0 || quantity_millitons % MILLITONS_PER_TON != 0 {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} must acquire a positive whole-ton fuel quantity",
                            index + 1
                        )));
                    }
                    if available_fuel_millitons
                        .checked_add(quantity_millitons)
                        .is_none_or(|quantity| quantity > effective_fuel_capacity(&ship, &spec))
                    {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} would exceed the ship's fuel capacity",
                            index + 1
                        )));
                    }
                    match operation {
                        FuelOperation::BuyRefined | FuelOperation::BuyUnrefined => {
                            let FlightLocus::Port {
                                system_id: port_system_id,
                                world_id,
                                facility_id,
                            } = step.locus
                            else {
                                return Ok(RuleResult::Rejected(format!(
                                    "waypoint {} must name the fuel vendor's port",
                                    index + 1
                                )));
                            };
                            if port_system_id != system_id || world_id != system_id {
                                return Ok(RuleResult::Rejected(format!(
                                    "waypoint {} names a fuel vendor outside the current system",
                                    index + 1
                                )));
                            }
                            let facility = self
                                .facilities
                                .get(txn, &facility_id)?
                                .map(decode_facility)
                                .transpose()?
                                .ok_or(StoreError::Corrupt(
                                    "flight-plan fuel facility is missing",
                                ))?;
                            let available = facility.operational
                                && match operation {
                                    FuelOperation::BuyRefined => facility.refined_fuel,
                                    FuelOperation::BuyUnrefined => facility.unrefined_fuel,
                                    _ => unreachable!(),
                                };
                            if facility.system_id != system_id || !available {
                                return Ok(RuleResult::Rejected(format!(
                                    "waypoint {} selects fuel that is not sold at this port",
                                    index + 1
                                )));
                            }
                            let price = match operation {
                                FuelOperation::BuyRefined => REFINED_FUEL_PRICE_PER_TON,
                                FuelOperation::BuyUnrefined => UNREFINED_FUEL_PRICE_PER_TON,
                                _ => unreachable!(),
                            };
                            let cost = purchase_cost_credits(price, quantity_millitons)
                                .ok_or(StoreError::Corrupt("flight-plan fuel cost overflow"))?;
                            if available_credits < cost {
                                return Ok(RuleResult::Rejected(format!(
                                    "waypoint {} requires Cr{} for fuel; the operating account is short",
                                    index + 1,
                                    cost
                                )));
                            }
                            available_credits -= cost;
                            if operation == FuelOperation::BuyUnrefined {
                                if refine_collected && spec.fuel_processing_millitons_per_day != 0 {
                                    let processing_seconds = milliton_service_seconds(
                                        quantity_millitons,
                                        spec.fuel_processing_millitons_per_day,
                                    );
                                    let failed_processing_seconds =
                                        processing_seconds.saturating_mul(2);
                                    fuel_timings.push(FuelOperationTiming {
                                        step_index: index as u16,
                                        round_trip_seconds: 0,
                                        collection_seconds: 0,
                                        processing_seconds,
                                        failed_processing_seconds,
                                        normal_total_seconds: processing_seconds,
                                        failed_total_seconds: failed_processing_seconds,
                                        output_refined: true,
                                    });
                                    elapsed_seconds =
                                        elapsed_seconds.saturating_add(processing_seconds);
                                } else {
                                    available_unrefined_millitons = available_unrefined_millitons
                                        .saturating_add(quantity_millitons);
                                }
                            }
                        }
                        FuelOperation::GasGiant | FuelOperation::WildernessWater => {
                            let FlightLocus::Body {
                                system_id: body_system_id,
                                body_id,
                            } = step.locus
                            else {
                                return Ok(RuleResult::Rejected(format!(
                                    "waypoint {} must name a frontier fuel body",
                                    index + 1
                                )));
                            };
                            if body_system_id != system_id {
                                return Ok(RuleResult::Rejected(format!(
                                    "waypoint {} names a fuel body outside the current system",
                                    index + 1
                                )));
                            }
                            if !spec.has_fuel_scoop {
                                return Ok(RuleResult::Rejected(
                                    "this ship cannot execute frontier-fuel waypoints".into(),
                                ));
                            }
                            let system = self
                                .systems
                                .get(txn, &system_id)?
                                .map(decode_stellar_system)
                                .transpose()?
                                .ok_or(StoreError::Corrupt("flight-plan fuel system is missing"))?;
                            let celestial = derive_celestial_system(&system)?;
                            let days = game_second.saturating_add(elapsed_seconds) as f64
                                / crate::simulation::SECONDS_PER_DAY as f64;
                            let source = match operation {
                                FuelOperation::GasGiant => gas_giant_fuel_source(
                                    &celestial,
                                    days,
                                    f64::from(spec.thrust_g),
                                    body_id,
                                ),
                                FuelOperation::WildernessWater => wilderness_water_source(
                                    &celestial,
                                    days,
                                    f64::from(spec.thrust_g),
                                    body_id,
                                ),
                                _ => unreachable!(),
                            };
                            let Some(source) = source else {
                                return Ok(RuleResult::Rejected(format!(
                                    "waypoint {} does not name a usable source for the selected fuel operation",
                                    index + 1
                                )));
                            };
                            let collection_seconds = if operation == FuelOperation::GasGiant {
                                mean_skimming_seconds(quantity_millitons)
                            } else {
                                0
                            };
                            if refine_collected && spec.fuel_processing_millitons_per_day == 0 {
                                return Ok(RuleResult::Rejected(format!(
                                    "waypoint {} requests refining, but the ship has no fuel processor",
                                    index + 1
                                )));
                            }
                            let round_trip_seconds = (source.round_trip_days
                                * crate::simulation::SECONDS_PER_DAY as f64)
                                .ceil() as u64;
                            let processing_seconds = if refine_collected {
                                milliton_service_seconds(
                                    quantity_millitons,
                                    spec.fuel_processing_millitons_per_day,
                                )
                            } else {
                                0
                            };
                            let failed_processing_seconds = processing_seconds.saturating_mul(2);
                            let normal_total_seconds = round_trip_seconds
                                .saturating_add(collection_seconds.max(processing_seconds));
                            let failed_total_seconds = round_trip_seconds
                                .saturating_add(collection_seconds.max(failed_processing_seconds));
                            fuel_timings.push(FuelOperationTiming {
                                step_index: index as u16,
                                round_trip_seconds,
                                collection_seconds,
                                processing_seconds,
                                failed_processing_seconds,
                                normal_total_seconds,
                                failed_total_seconds,
                                output_refined: refine_collected,
                            });
                            elapsed_seconds = elapsed_seconds.saturating_add(normal_total_seconds);
                            if !refine_collected {
                                available_unrefined_millitons = available_unrefined_millitons
                                    .saturating_add(quantity_millitons);
                            }
                            at_primary_port = true;
                        }
                    }
                    available_fuel_millitons += quantity_millitons;
                }
                FlightPlanAction::RefineFuel { quantity_millitons } => {
                    if quantity_millitons == 0
                        || quantity_millitons % MILLITONS_PER_TON != 0
                        || quantity_millitons > available_unrefined_millitons
                    {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} must refine an available positive whole-ton quantity",
                            index + 1
                        )));
                    }
                    if spec.fuel_processing_millitons_per_day == 0 {
                        return Ok(RuleResult::Rejected(
                            "this ship has no fuel processor".into(),
                        ));
                    }
                    let safe_locus = if at_primary_port {
                        matches!(step.locus, FlightLocus::Port { system_id: port_system, .. } if port_system == system_id)
                    } else {
                        matches!(
                            step.locus,
                            FlightLocus::JumpLocus { system_id: locus_system }
                                if locus_system == system_id
                        ) || matches!(step.locus, FlightLocus::DeepSpace { .. })
                    };
                    if !safe_locus {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} must process fuel at a berth or safe holding locus",
                            index + 1
                        )));
                    }
                    let processing_seconds = milliton_service_seconds(
                        quantity_millitons,
                        spec.fuel_processing_millitons_per_day,
                    );
                    let failed_processing_seconds = processing_seconds.saturating_mul(2);
                    fuel_timings.push(FuelOperationTiming {
                        step_index: index as u16,
                        round_trip_seconds: 0,
                        collection_seconds: 0,
                        processing_seconds,
                        failed_processing_seconds,
                        normal_total_seconds: processing_seconds,
                        failed_total_seconds: failed_processing_seconds,
                        output_refined: true,
                    });
                    if !at_primary_port {
                        let reserve = crate::mining::power_fuel_for_duration(
                            spec.power_fuel_millitons,
                            spec.power_plant_endurance_seconds,
                            failed_processing_seconds,
                        );
                        let fuel_outside_batch =
                            available_fuel_millitons.saturating_sub(quantity_millitons);
                        if fuel_outside_batch < reserve {
                            return Ok(RuleResult::Rejected(format!(
                                "waypoint {} needs {:.1} tons of fuel outside the selected batch for power-plant reserve",
                                index + 1,
                                reserve as f64 / 1_000.0
                            )));
                        }
                        let normal_power_burn = crate::mining::power_fuel_for_duration(
                            spec.power_fuel_millitons,
                            spec.power_plant_endurance_seconds,
                            processing_seconds,
                        );
                        let unrefined_outside_batch =
                            available_unrefined_millitons.saturating_sub(quantity_millitons);
                        let (_, unrefined_power_burn) = proportional_fuel_burn(
                            fuel_outside_batch,
                            unrefined_outside_batch,
                            normal_power_burn,
                        );
                        available_fuel_millitons =
                            available_fuel_millitons.saturating_sub(normal_power_burn);
                        available_unrefined_millitons =
                            available_unrefined_millitons.saturating_sub(unrefined_power_burn);
                    }
                    available_unrefined_millitons =
                        available_unrefined_millitons.saturating_sub(quantity_millitons);
                    elapsed_seconds = elapsed_seconds.saturating_add(processing_seconds);
                }
                FlightPlanAction::Dock {
                    world_id,
                    facility_id,
                } => {
                    if step.locus
                        != (FlightLocus::Port {
                            system_id,
                            world_id,
                            facility_id,
                        })
                    {
                        return Ok(RuleResult::Rejected(format!(
                            "waypoint {} has inconsistent port details",
                            index + 1
                        )));
                    }
                    if !at_primary_port {
                        elapsed_seconds = elapsed_seconds.saturating_add(
                            self.projected_primary_approach_seconds_in(
                                txn,
                                system_id,
                                game_second.saturating_add(elapsed_seconds),
                                spec.thrust_g,
                            )?,
                        );
                    }
                    at_primary_port = true;
                    docked_arrivals.entry(system_id).or_insert_with(|| {
                        (
                            game_second.saturating_add(elapsed_seconds),
                            index as u16,
                            step.authority,
                        )
                    });
                }
                FlightPlanAction::Hold => {}
            }
            step_elapsed_seconds.push(elapsed_seconds);
            if step.authority == WaypointAuthority::Through {
                unattended_waypoints.push(index as u16);
            }
        }
        if !unattended_waypoints.is_empty() {
            warnings.push(FlightPlanWarning {
                code: "UNATTENDED_CHECKPOINT".into(),
                message: "Contacts may resolve under standing orders while the captain is away."
                    .into(),
                step_indices: unattended_waypoints,
            });
        }
        if !ship.cargo.is_empty() && current.plan_id != 0 && proposal.steps != current.steps {
            warnings.push(FlightPlanWarning { code: "CARRIAGE_DIVERSION".into(), message: "Carried cargo remains aboard; changing the route does not alter delivery obligations or their dates.".into(), step_indices: Vec::new() });
        }
        if ship.mail_custody.is_some() && proposal.steps != current.steps {
            warnings.push(FlightPlanWarning { code: "SEALED_MAIL_CUSTODY".into(), message: "The sealed mailbag remains in custody and must be delivered on its committed hop.".into(), step_indices: Vec::new() });
        }
        let plan_end_second = game_second.saturating_add(elapsed_seconds);
        for entry in self.tasks.iter(txn)? {
            let (_, value) = entry?;
            let stored = decode_stored_task(value)?;
            if stored.identity != *identity
                || stored.task.performing_ship_id != ship.ship_id
                || stored.task.offer.destination_system_id == 0
                || matches!(
                    stored.task.state,
                    crate::wire::TaskState::Completed
                        | crate::wire::TaskState::Expired
                        | crate::wire::TaskState::Cancelled
                        | crate::wire::TaskState::Defaulted
                )
            {
                continue;
            }
            let deadline = stored.task.offer.delivery_deadline_second;
            let arrival = docked_arrivals
                .get(&stored.task.offer.destination_system_id)
                .copied();
            let missed_by = match arrival {
                Some((arrival_second, _, _)) if arrival_second > deadline => {
                    Some(arrival_second - deadline)
                }
                None if plan_end_second > deadline => Some(plan_end_second - deadline),
                _ => None,
            };
            if let Some(late_seconds) = missed_by {
                let message = if arrival.is_some() {
                    format!(
                        "Task #{} ({}) reaches its destination {} after its delivery deadline.",
                        stored.task.task_id,
                        stored.task.offer.title,
                        format_game_duration(late_seconds),
                    )
                } else {
                    format!(
                        "Task #{} ({}) is still short of its destination when this plan ends {} after its delivery deadline.",
                        stored.task.task_id,
                        stored.task.offer.title,
                        format_game_duration(late_seconds),
                    )
                };
                warnings.push(FlightPlanWarning {
                    code: "TASK_DEADLINE_MISSED".into(),
                    message,
                    step_indices: arrival.map_or_else(Vec::new, |(_, index, _)| vec![index]),
                });
            } else if let Some((_, index, WaypointAuthority::Hold)) = arrival {
                warnings.push(FlightPlanWarning {
                    code: "TASK_DEADLINE_REQUIRES_WATCH".into(),
                    message: format!(
                        "Task #{} ({}) is not delivered until docking; take arrival watch before its delivery deadline or change this checkpoint to Through.",
                        stored.task.task_id, stored.task.offer.title,
                    ),
                    step_indices: vec![index],
                });
            }
        }
        for (kind, name) in [
            (ShipSubsystemKind::LifeSupport, "life support"),
            (ShipSubsystemKind::PowerPlant, "power plant"),
            (ShipSubsystemKind::ManeuverDrive, "maneuver drive"),
        ] {
            if ship
                .subsystems
                .iter()
                .filter(|subsystem| subsystem.kind == kind)
                .any(|subsystem| {
                    subsystem
                        .sustained_hits
                        .saturating_sub(subsystem.battlefield_repair_hits)
                        >= subsystem.maximum_hits
                })
            {
                warnings.push(FlightPlanWarning {
                    code: "DESTROYED_REQUIRED_SYSTEM".into(),
                    message: format!("The ship cannot depart with its {name} destroyed."),
                    step_indices: Vec::new(),
                });
            }
        }
        if proposal.steps.iter().any(|step| {
            matches!(
                step.action,
                FlightPlanAction::Jump { .. } | FlightPlanAction::JumpCoordinates { .. }
            )
        }) && ship
            .subsystems
            .iter()
            .filter(|subsystem| subsystem.kind == ShipSubsystemKind::JumpDrive)
            .any(|subsystem| {
                subsystem
                    .sustained_hits
                    .saturating_sub(subsystem.battlefield_repair_hits)
                    >= subsystem.maximum_hits
            })
        {
            warnings.push(FlightPlanWarning {
                code: "DESTROYED_REQUIRED_SYSTEM".into(),
                message: "The filed plan requires a functioning Jump drive.".into(),
                step_indices: Vec::new(),
            });
        }
        let mut carriage_offers = Vec::new();
        let mut carriage_revenue_credits = 0_u64;
        let mut carriage_broker_fees_credits = 0_u64;
        if matches!(ship.location, ShipLocationRecord::Docked { .. }) {
            let declaration = self.carriage_in(txn, identity)?;
            if declaration.destination_system_id != 0 {
                let mut freight = declaration.freight_capacity_millitons;
                let mut high = declaration.high_berths;
                let mut middle = declaration.middle_berths;
                let mut steerage = declaration.steerage_berths;
                let mut low = declaration.low_berths;
                for offer in self
                    .local_task_offers_in(txn, identity, &ship)?
                    .into_iter()
                    .filter(|offer| {
                        offer.destination_system_id == declaration.destination_system_id
                    })
                {
                    let eligible = match offer.kind {
                        crate::wire::TaskKind::Freight if offer.quantity_millitons <= freight => {
                            freight -= offer.quantity_millitons;
                            true
                        }
                        crate::wire::TaskKind::Passenger => match offer.passenger_class {
                            crate::wire::PassengerClass::High if offer.passenger_count <= high => {
                                high -= offer.passenger_count;
                                true
                            }
                            crate::wire::PassengerClass::Middle
                                if offer.passenger_count <= middle =>
                            {
                                middle -= offer.passenger_count;
                                true
                            }
                            crate::wire::PassengerClass::Steerage
                                if offer.passenger_count <= steerage =>
                            {
                                steerage -= offer.passenger_count;
                                true
                            }
                            crate::wire::PassengerClass::Low if offer.passenger_count <= low => {
                                low -= offer.passenger_count;
                                true
                            }
                            _ => false,
                        },
                        _ => false,
                    };
                    if eligible {
                        carriage_revenue_credits =
                            carriage_revenue_credits.saturating_add(offer.payment_credits);
                        if offer.kind == crate::wire::TaskKind::Freight {
                            let tons = offer.quantity_millitons / MILLITONS_PER_TON;
                            let rate = 100 + crate::ship_condition::mix64(offer.offer_id) % 201;
                            carriage_broker_fees_credits = carriage_broker_fees_credits
                                .saturating_add(tons.saturating_mul(rate));
                        }
                        carriage_offers.push(offer);
                    }
                }
                if (high != declaration.high_berths || middle != declaration.middle_berths)
                    && !self.ship_has_crew_skill_in(
                        txn,
                        identity,
                        ship.ship_id,
                        crate::wire::SkillId::Etiquette,
                    )?
                {
                    warnings.push(FlightPlanWarning { code: "PASSENGER_STEWARD_UNSTAFFED".into(), message: "High or middle passage is declared, but no qualified steward is aboard.".into(), step_indices: Vec::new() });
                }
                if low != declaration.low_berths
                    && !self.ship_has_crew_skill_in(
                        txn,
                        identity,
                        ship.ship_id,
                        crate::wire::SkillId::Medicine,
                    )?
                {
                    warnings.push(FlightPlanWarning {
                        code: "LOW_BERTH_MEDIC_UNSTAFFED".into(),
                        message:
                            "Low passage is declared, but no qualified medical attendant is aboard."
                                .into(),
                        step_indices: Vec::new(),
                    });
                }
            }
        }
        let mut crew_count = 0_u64;
        for service in self
            .crew_services
            .iter(txn)?
            .map(|entry| {
                let (_, bytes) = entry?;
                decode_crew_service(bytes)
            })
            .collect::<Result<Vec<_>, StoreError>>()?
            .into_iter()
            .filter(|service| {
                service.ship_id == ship.ship_id
                    && service_active(service)
                    && service.availability == CrewAvailability::Active
            })
        {
            let person = self
                .persons
                .get(txn, &service.person_id)?
                .map(decode_person_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("provisioned crewmember is missing"))?;
            crew_count = crew_count
                .saturating_add(u64::from(crew_service_living_positions(&service, &person)));
        }
        let selected_passengers = carriage_offers
            .iter()
            .filter(|offer| {
                offer.kind == crate::wire::TaskKind::Passenger
                    && offer.passenger_class != crate::wire::PassengerClass::Low
            })
            .map(|offer| u64::from(offer.passenger_count))
            .sum::<u64>();
        let persons_aboard = crew_count
            .saturating_add(awake_passenger_count(&ship.passengers))
            .saturating_add(selected_passengers);
        let voyage_days = elapsed_seconds
            .div_ceil(crate::simulation::SECONDS_PER_DAY)
            .max(1);
        let required_person_days = persons_aboard.saturating_mul(voyage_days);
        if ship.provisions.person_days_remaining < required_person_days {
            let step_indices = step_elapsed_seconds
                .iter()
                .enumerate()
                .filter_map(|(index, elapsed)| {
                    let days = elapsed.div_ceil(crate::simulation::SECONDS_PER_DAY).max(1);
                    let needed = persons_aboard.saturating_mul(days);
                    (needed > ship.provisions.person_days_remaining).then_some(index as u16)
                })
                .collect();
            warnings.push(FlightPlanWarning { code: "INSUFFICIENT_PROVISIONS".into(), message: format!("The filed voyage requires {required_person_days} person-days of life-support stores; {} remain aboard. Numbered markers identify every step reached after stores run short.", ship.provisions.person_days_remaining), step_indices });
        }
        let mut consolidated_warnings: Vec<FlightPlanWarning> = Vec::new();
        for warning in warnings {
            if let Some(existing) = consolidated_warnings.iter_mut().find(|existing| {
                existing.code == warning.code && existing.message == warning.message
            }) {
                for step_index in warning.step_indices {
                    if !existing.step_indices.contains(&step_index) {
                        existing.step_indices.push(step_index);
                    }
                }
            } else {
                consolidated_warnings.push(warning);
            }
        }
        let preview_hash = flight_plan_preview_hash(proposal, &carriage_offers)?;
        Ok(RuleResult::Applied(FlightPlanPreview {
            proposal: proposal.clone(),
            preview_hash,
            elapsed_seconds,
            fuel_millitons,
            warnings: consolidated_warnings,
            carriage_offers,
            carriage_revenue_credits,
            carriage_broker_fees_credits,
            fuel_timings,
        }))
    }

    fn commit_flight_plan_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        request: &CommitFlightPlanRequest,
    ) -> Result<RuleResult<FlightPlanSnapshot>, StoreError> {
        let RuleResult::Applied(preview) =
            self.preview_flight_plan_in(txn, identity, &request.proposal)?
        else {
            return Ok(RuleResult::Rejected(
                "the proposed flight plan is no longer valid".into(),
            ));
        };
        if request.preview_hash != preview.preview_hash {
            return Ok(RuleResult::Rejected(
                "the flight-plan preview has changed; preview it again before committing".into(),
            ));
        }
        if preview.warnings.iter().any(|warning| {
            matches!(
                warning.code.as_str(),
                "INSUFFICIENT_PROVISIONS"
                    | "DESTROYED_REQUIRED_SYSTEM"
                    | "PASSENGER_STEWARD_UNSTAFFED"
                    | "LOW_BERTH_MEDIC_UNSTAFFED"
            )
        }) {
            return Ok(RuleResult::Rejected(
                "the ship is not physically ready to execute the filed voyage".into(),
            ));
        }
        if !preview.warnings.is_empty() && !request.acknowledge_warnings {
            return Ok(RuleResult::Rejected(
                "the flight-plan preview contains warnings which must be acknowledged".into(),
            ));
        }
        let (_, watch_ship) = self.player_and_ship_in(txn, identity)?;
        let mut required_watch_skills = vec![
            crate::wire::SkillId::PilotSpacecraft,
            crate::wire::SkillId::EngineerManeuver,
            crate::wire::SkillId::EngineerPower,
        ];
        if request.proposal.steps.iter().any(|step| {
            matches!(
                step.action,
                FlightPlanAction::Jump { .. } | FlightPlanAction::JumpCoordinates { .. }
            )
        }) {
            required_watch_skills.extend([
                crate::wire::SkillId::Astrogation,
                crate::wire::SkillId::EngineerJump,
            ]);
        }
        let mut uncovered = Vec::new();
        for skill in required_watch_skills {
            if !self.watch_can_attempt_in(txn, identity, watch_ship.ship_id, skill)? {
                uncovered.push(skill.name());
            }
        }
        if !uncovered.is_empty() {
            return Ok(RuleResult::Rejected(format!(
                "the filed watch cannot cover: {}",
                uncovered.join(", ")
            )));
        }
        let first_jump = request
            .proposal
            .steps
            .iter()
            .enumerate()
            .find_map(|(index, step)| match &step.action {
                FlightPlanAction::Jump { .. } | FlightPlanAction::JumpCoordinates { .. } => {
                    Some((index, step.action.clone()))
                }
                _ => None,
            });
        if first_jump.is_none()
            && !request
                .proposal
                .steps
                .iter()
                .any(|step| matches!(step.action, FlightPlanAction::BeltCycle { .. }))
        {
            return Ok(RuleResult::Rejected(
                "the initial flight plan must contain a jump or belt cycle".into(),
            ));
        }
        let phase = self.player_phase_in(txn, identity)?;
        if phase != PlayerPhase::Docked && phase != PlayerPhase::Interplanetary {
            return Ok(RuleResult::Rejected(
                "the current physical leg is already committed; replan at its next checkpoint"
                    .into(),
            ));
        }
        let holding_in_deep_space = if phase == PlayerPhase::Interplanetary {
            let (_, ship) = self.player_and_ship_in(txn, identity)?;
            matches!(
                ship.location,
                ShipLocationRecord::Holding {
                    locus: ShipLocusRecord::DeepSpace { .. },
                    ..
                }
            )
        } else {
            false
        };
        if phase == PlayerPhase::Interplanetary && !holding_in_deep_space {
            let (_, ship) = self.player_and_ship_in(txn, identity)?;
            if !matches!(
                ship.location,
                ShipLocationRecord::InFlight(FlightLegRecord {
                    purpose: FlightLegPurpose::DepartForJump { .. },
                    ..
                })
            ) {
                return Ok(RuleResult::Rejected(
                    "the current physical leg is already committed; replan at its next checkpoint"
                        .into(),
                ));
            }
        }
        let current_plan = self.flight_plan_in(txn, identity)?;
        let plan_id = if current_plan.plan_id == 0 {
            take_next_id(self.meta, txn, META_NEXT_FLIGHT_PLAN_ID)?
        } else {
            current_plan.plan_id
        };
        let revision = request
            .proposal
            .expected_plan_revision
            .checked_add(1)
            .ok_or(StoreError::Corrupt("flight-plan revision overflow"))?;
        let mut plan = FlightPlanSnapshot {
            plan_id,
            revision,
            current_step: 0,
            state: FlightPlanState::Active,
            steps: request.proposal.steps.clone(),
            policy: request.proposal.policy.clone(),
            suspension_reason: String::new(),
        };
        if phase == PlayerPhase::Interplanetary && !holding_in_deep_space {
            let Some((first_jump_index, first_jump)) = first_jump else {
                return Ok(RuleResult::Rejected(
                    "a route revised after departure must retain its committed jump".into(),
                ));
            };
            if request.proposal.steps[..first_jump_index]
                .iter()
                .any(|step| !matches!(step.action, FlightPlanAction::Hold))
            {
                return Ok(RuleResult::Rejected(
                    "a route revised after departure cannot insert service before the committed jump"
                        .into(),
                ));
            }
            let (player, mut ship) = self.player_and_ship_in(txn, identity)?;
            let ShipLocationRecord::InFlight(ref mut leg) = ship.location else {
                return Ok(RuleResult::Rejected(
                    "the ship has no active route to revise".into(),
                ));
            };
            match (&mut leg.purpose, first_jump) {
                (
                    FlightLegPurpose::DepartForJump {
                        jump_destination_system_id,
                    },
                    FlightPlanAction::Jump {
                        destination_system_id,
                        ..
                    },
                ) => *jump_destination_system_id = destination_system_id,
                (
                    FlightLegPurpose::DepartForCoordinateJump { destination },
                    FlightPlanAction::JumpCoordinates {
                        destination: replacement,
                        ..
                    },
                ) => *destination = replacement,
                (
                    purpose @ FlightLegPurpose::DepartForJump { .. },
                    FlightPlanAction::JumpCoordinates { destination, .. },
                ) => *purpose = FlightLegPurpose::DepartForCoordinateJump { destination },
                (
                    purpose @ FlightLegPurpose::DepartForCoordinateJump { .. },
                    FlightPlanAction::Jump {
                        destination_system_id,
                        ..
                    },
                ) => {
                    *purpose = FlightLegPurpose::DepartForJump {
                        jump_destination_system_id: destination_system_id,
                    }
                }
                _ => {
                    return Ok(RuleResult::Rejected(
                        "the current physical leg is already committed; replan at its next checkpoint".into(),
                    ));
                }
            }
            leg.plan_id = plan_id;
            leg.plan_revision = revision;
            leg.leg_index = u16::try_from(first_jump_index)
                .map_err(|_| StoreError::Corrupt("flight-plan step index overflow"))?;
            plan.current_step = leg.leg_index;
            self.ships
                .put(txn, &player.ship_id, &encode_ship_record(&ship)?)?;
            self.flight_plans.put(
                txn,
                &encode_identity(identity),
                &encode_flight_plan_snapshot(&plan)?,
            )?;
            return Ok(RuleResult::Applied(plan));
        }
        self.activate_flight_plan_from_in(txn, identity, plan, 0, false)
    }

    fn watch_can_attempt_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship_id: u64,
        skill: crate::wire::SkillId,
    ) -> Result<bool, StoreError> {
        let current_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let role_catalog = self.crew_role_catalog_in(txn, identity, ship_id)?;
        for entry in self.crew_services.iter(txn)? {
            let (_, encoded) = entry?;
            let service = decode_crew_service(encoded)?;
            if service.command != *identity
                || service.ship_id != ship_id
                || service.assigned_slot_ids.is_empty()
                || !service_available_for_duty(&service, current_second)
                || !service.assigned_slot_ids.iter().any(|slot_id| {
                    role_catalog
                        .get(slot_id)
                        .is_some_and(|role| crew_role_supports_skill(role, skill))
                })
            {
                continue;
            }
            let person = self
                .persons
                .get(txn, &service.person_id)?
                .map(decode_person_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("watch assignment person is missing"))?;
            if person_incapacitated(&person) {
                continue;
            }
            if person.person.skills.iter().any(|rating| {
                (rating.skill == skill && rating.level >= 0)
                    || (rating.skill == crate::wire::SkillId::JackOfAllTrades && rating.level > 0)
            }) {
                return Ok(true);
            }
        }
        Ok(false)
    }

    fn ship_has_crew_skill_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship_id: u64,
        skill: crate::wire::SkillId,
    ) -> Result<bool, StoreError> {
        let current_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        for entry in self.crew_services.iter(txn)? {
            let (_, encoded) = entry?;
            let service = decode_crew_service(encoded)?;
            if service.command != *identity
                || service.ship_id != ship_id
                || !service_available_for_duty(&service, current_second)
            {
                continue;
            }
            let person = self
                .persons
                .get(txn, &service.person_id)?
                .map(decode_person_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("ship crewmember is missing"))?;
            if !person_dead(&person)
                && person
                    .person
                    .skills
                    .iter()
                    .any(|rating| rating.skill == skill && rating.level >= 0)
            {
                return Ok(true);
            }
        }
        Ok(false)
    }

    fn best_watch_operator_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship_id: u64,
        skill: crate::wire::SkillId,
    ) -> Result<(crate::wire::PersonDraft, i8), StoreError> {
        let current_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let role_catalog = self.crew_role_catalog_in(txn, identity, ship_id)?;
        let mut candidates = Vec::new();
        for entry in self.crew_services.iter(txn)? {
            let (_, encoded) = entry?;
            let service = decode_crew_service(encoded)?;
            if service.command != *identity
                || service.ship_id != ship_id
                || service.assigned_slot_ids.is_empty()
                || !service_available_for_duty(&service, current_second)
                || !service.assigned_slot_ids.iter().any(|slot_id| {
                    role_catalog
                        .get(slot_id)
                        .is_some_and(|role| crew_role_supports_skill(role, skill))
                })
            {
                continue;
            }
            let person = self
                .persons
                .get(txn, &service.person_id)?
                .map(decode_person_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("watch assignment person is missing"))?;
            if person_incapacitated(&person) {
                continue;
            }
            let direct = person
                .person
                .skills
                .iter()
                .find(|rating| rating.skill == skill)
                .map(|rating| rating.level);
            let jack = person
                .person
                .skills
                .iter()
                .find(|rating| rating.skill == crate::wire::SkillId::JackOfAllTrades)
                .map_or(0, |rating| rating.level.clamp(0, 2));
            let skill_dm = direct.unwrap_or(-3 + jack);
            let condition_dm = person_condition_dm(&person)
                .saturating_add(crate::personnel::discretionary_morale_dm(service.morale));
            candidates.push((
                skill_dm
                    + crate::task_resolution::characteristic_dm(
                        person.person.characteristics.education,
                    )
                    + condition_dm,
                person.person,
                condition_dm,
            ));
        }
        candidates
            .into_iter()
            .max_by_key(|(score, _, _)| *score)
            .map(|(_, person, condition_dm)| (person, condition_dm))
            .ok_or(StoreError::Corrupt(
                "required Jump watch operator is missing",
            ))
    }

    fn resolve_fuel_processing_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship_id: u64,
        entropy: u64,
        quantity_millitons: u64,
        processing_rate_millitons_per_day: u64,
    ) -> Result<(i16, u64, bool), StoreError> {
        let normal_seconds =
            milliton_service_seconds(quantity_millitons, processing_rate_millitons_per_day);
        let (engineer, condition_dm) = self.best_watch_operator_in(
            txn,
            identity,
            ship_id,
            crate::wire::SkillId::EngineerPower,
        )?;
        let result = crate::task_resolution::resolve(
            &engineer,
            crate::task_resolution::TaskRequest {
                characteristic: engineer.characteristics.education,
                skill: crate::wire::SkillId::EngineerPower,
                difficulty: 8,
                equipment_dm: 0,
                condition_dm,
                assistance_dm: 0,
                entropy: entropy ^ 0x4655_454c_5052_4f43,
            },
        );
        Ok((
            result.effect,
            if result.success {
                normal_seconds
            } else {
                normal_seconds.saturating_mul(2)
            },
            result.effect <= -6,
        ))
    }

    fn crew_role_catalog_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship_id: u64,
    ) -> Result<std::collections::BTreeMap<u16, String>, StoreError> {
        let mut roles = std::collections::BTreeMap::new();
        for entry in self.crew_services.iter(txn)? {
            let (_, encoded) = entry?;
            let service = decode_crew_service(encoded)?;
            if service.command == *identity && service.ship_id == ship_id {
                roles.entry(service.slot_id).or_insert(service.role);
            }
        }
        if !roles
            .values()
            .any(|role| role.eq_ignore_ascii_case("pilot"))
        {
            let slot = roles
                .keys()
                .next_back()
                .copied()
                .unwrap_or(0)
                .checked_add(1)
                .ok_or(StoreError::Corrupt("crew role identifier overflow"))?;
            roles.insert(slot, "pilot".into());
        }
        Ok(roles)
    }

    fn jump_plan_instruction_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        leg: &FlightLegRecord,
    ) -> Result<(crate::wire::JumpNavigationMethod, bool), StoreError> {
        let Some(plan) = self
            .flight_plans
            .get(txn, &encode_identity(identity))?
            .map(decode_flight_plan_snapshot)
            .transpose()?
        else {
            return Ok((crate::wire::JumpNavigationMethod::Onboard, false));
        };
        let Some(step) = plan.steps.get(usize::from(leg.leg_index)) else {
            return Ok((crate::wire::JumpNavigationMethod::Onboard, false));
        };
        Ok(match step.action {
            FlightPlanAction::Jump {
                navigation,
                proceed_on_known_bad_plot,
                ..
            }
            | FlightPlanAction::JumpCoordinates {
                navigation,
                proceed_on_known_bad_plot,
                ..
            } => (navigation, proceed_on_known_bad_plot),
            _ => (crate::wire::JumpNavigationMethod::Onboard, false),
        })
    }

    fn resolve_jump_preparation_in(
        &self,
        txn: &heed::RoTxn<'_>,
        ship: &ShipRecord,
        leg: &FlightLegRecord,
        distance_parsecs: f64,
        due_second: u64,
    ) -> Result<(u64, i16, bool, bool), StoreError> {
        let (navigation, proceed_on_known_bad_plot) =
            self.jump_plan_instruction_in(txn, &ship.command, leg)?;
        let entropy = crate::ship_condition::mix64(
            ship.ship_id ^ leg.plan_id ^ due_second ^ 0x4153_5452_4f47_4154,
        );
        let plot_seconds = if navigation == crate::wire::JumpNavigationMethod::CommercialTape {
            0
        } else {
            u64::from((entropy % 6) as u8 + 1) * 1_000
        };
        let bad_plot = if navigation == crate::wire::JumpNavigationMethod::CommercialTape {
            false
        } else {
            let (navigator, navigator_condition_dm) = self.best_watch_operator_in(
                txn,
                &ship.command,
                ship.ship_id,
                crate::wire::SkillId::Astrogation,
            )?;
            !crate::task_resolution::resolve(
                &navigator,
                crate::task_resolution::TaskRequest {
                    characteristic: navigator.characteristics.education,
                    skill: crate::wire::SkillId::Astrogation,
                    difficulty: 8,
                    equipment_dm: 4 - i8::try_from(jump_number_for_distance(distance_parsecs))
                        .unwrap_or(i8::MAX),
                    condition_dm: navigator_condition_dm,
                    assistance_dm: 0,
                    entropy,
                },
            )
            .success
        };
        let (engineer, engineer_condition_dm) = self.best_watch_operator_in(
            txn,
            &ship.command,
            ship.ship_id,
            crate::wire::SkillId::EngineerJump,
        )?;
        let engineering = crate::task_resolution::resolve(
            &engineer,
            crate::task_resolution::TaskRequest {
                characteristic: engineer.characteristics.education,
                skill: crate::wire::SkillId::EngineerJump,
                difficulty: 8,
                equipment_dm: 0,
                condition_dm: engineer_condition_dm,
                assistance_dm: 0,
                entropy: entropy ^ 0x454e_4749_4e45_4552,
            },
        );
        let engineering_seconds = u64::from(((entropy >> 8) % 6) as u8 + 1) * 10;
        Ok((
            plot_seconds.saturating_add(engineering_seconds),
            engineering.effect,
            bad_plot && proceed_on_known_bad_plot,
            bad_plot && !proceed_on_known_bad_plot,
        ))
    }

    /// Start the first actionable step at or after `start_index`. Every
    /// physical operation is admitted by its existing command path and then
    /// tagged with the durable plan identity. Dock and Hold steps are resolved
    /// locally because the ship is already at their locus when this helper is
    /// called.
    fn activate_flight_plan_from_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        mut plan: FlightPlanSnapshot,
        start_index: usize,
        hold_on_rejection: bool,
    ) -> Result<RuleResult<FlightPlanSnapshot>, StoreError> {
        let key = encode_identity(identity);
        for index in start_index..plan.steps.len() {
            let step = plan.steps[index].clone();
            plan.current_step = u16::try_from(index)
                .map_err(|_| StoreError::Corrupt("flight-plan step index overflow"))?;
            plan.suspension_reason.clear();
            match step.action {
                FlightPlanAction::Hold => {
                    plan.state = FlightPlanState::Held;
                    plan.suspension_reason = "flight plan is holding for the captain".into();
                    self.flight_plans
                        .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
                    return Ok(RuleResult::Applied(plan));
                }
                FlightPlanAction::Dock {
                    world_id,
                    facility_id,
                } => {
                    let (_, ship) = self.player_and_ship_in(txn, identity)?;
                    let at_plotted_port = matches!(
                        (ship.location, step.locus),
                        (
                            ShipLocationRecord::Docked {
                                world_id: actual_world,
                                facility_id: actual_facility,
                                ..
                            },
                            FlightLocus::Port {
                                system_id,
                                world_id: locus_world,
                                facility_id: locus_facility,
                            }
                        ) if ship.system_id == system_id
                            && actual_world == world_id
                            && actual_facility == facility_id
                            && locus_world == world_id
                            && locus_facility == facility_id
                    );
                    if !at_plotted_port {
                        return self.reject_or_hold_plan_in(
                            txn,
                            &key,
                            plan,
                            "the ship is not at the port named by the next flight-plan step",
                            hold_on_rejection,
                        );
                    }
                    if step.terminal {
                        plan.state = FlightPlanState::Completed;
                        self.flight_plans
                            .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
                        return Ok(RuleResult::Applied(plan));
                    }
                }
                FlightPlanAction::Jump {
                    destination_system_id,
                    navigation,
                    proceed_on_known_bad_plot,
                } => match if matches!(
                    self.player_and_ship_in(txn, identity)?.1.location,
                    ShipLocationRecord::Holding {
                        locus: ShipLocusRecord::DeepSpace { .. },
                        ..
                    }
                ) {
                    self.begin_deep_space_jump_in(
                        txn,
                        identity,
                        destination_system_id,
                        navigation,
                        proceed_on_known_bad_plot,
                    )?
                } else {
                    self.begin_voyage_in(txn, identity, destination_system_id, navigation)?
                } {
                    RuleResult::Rejected(message) => {
                        return self.reject_or_hold_plan_in(
                            txn,
                            &key,
                            plan,
                            &message,
                            hold_on_rejection,
                        );
                    }
                    RuleResult::Applied(_) => {
                        let (player, mut ship) = self.player_and_ship_in(txn, identity)?;
                        let ShipLocationRecord::InFlight(ref mut leg) = ship.location else {
                            return Err(StoreError::Corrupt(
                                "accepted jump step did not create a flight leg",
                            ));
                        };
                        leg.plan_id = plan.plan_id;
                        leg.plan_revision = plan.revision;
                        leg.leg_index = plan.current_step;
                        self.ships
                            .put(txn, &player.ship_id, &encode_ship_record(&ship)?)?;
                        plan.state = FlightPlanState::Active;
                        self.flight_plans
                            .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
                        return Ok(RuleResult::Applied(plan));
                    }
                },
                FlightPlanAction::JumpCoordinates {
                    destination,
                    navigation,
                    ..
                } => {
                    match self.begin_coordinate_voyage_in(txn, identity, destination, navigation)? {
                        RuleResult::Rejected(message) => {
                            return self.reject_or_hold_plan_in(
                                txn,
                                &key,
                                plan,
                                &message,
                                hold_on_rejection,
                            );
                        }
                        RuleResult::Applied(_) => {
                            let (player, mut ship) = self.player_and_ship_in(txn, identity)?;
                            let ShipLocationRecord::InFlight(ref mut leg) = ship.location else {
                                return Err(StoreError::Corrupt(
                                    "accepted coordinate Jump did not create a flight leg",
                                ));
                            };
                            leg.plan_id = plan.plan_id;
                            leg.plan_revision = plan.revision;
                            leg.leg_index = plan.current_step;
                            self.ships
                                .put(txn, &player.ship_id, &encode_ship_record(&ship)?)?;
                            plan.state = FlightPlanState::Active;
                            self.flight_plans.put(
                                txn,
                                &key,
                                &encode_flight_plan_snapshot(&plan)?,
                            )?;
                            return Ok(RuleResult::Applied(plan));
                        }
                    }
                }
                FlightPlanAction::Fuel {
                    operation,
                    quantity_millitons,
                    refine_collected,
                } => {
                    if matches!(
                        operation,
                        FuelOperation::BuyRefined | FuelOperation::BuyUnrefined
                    ) {
                        let FlightLocus::Port {
                            system_id,
                            world_id,
                            facility_id,
                        } = step.locus
                        else {
                            return self.reject_or_hold_plan_in(
                                txn,
                                &key,
                                plan,
                                "a fuel-purchase step must name its port",
                                hold_on_rejection,
                            );
                        };
                        let (_, ship) = self.player_and_ship_in(txn, identity)?;
                        let can_refine_purchase = creation::ship_status_spec(ship.catalog_id)
                            .is_some_and(|spec| spec.fuel_processing_millitons_per_day != 0);
                        let at_plotted_port = matches!(
                            ship.location,
                            ShipLocationRecord::Docked {
                                world_id: actual_world,
                                facility_id: actual_facility,
                                ..
                            } if ship.system_id == system_id
                                && actual_world == world_id
                                && actual_facility == facility_id
                        );
                        if !at_plotted_port {
                            return self.reject_or_hold_plan_in(
                                txn,
                                &key,
                                plan,
                                "the ship is not at the port named by the fuel-purchase step",
                                hold_on_rejection,
                            );
                        }
                        let result = match operation {
                            FuelOperation::BuyRefined => {
                                self.buy_fuel_in(txn, identity, quantity_millitons)?
                            }
                            FuelOperation::BuyUnrefined => {
                                self.buy_unrefined_fuel_in(txn, identity, quantity_millitons)?
                            }
                            _ => unreachable!(),
                        };
                        if let RuleResult::Rejected(message) = result {
                            return self.reject_or_hold_plan_in(
                                txn,
                                &key,
                                plan,
                                &message,
                                hold_on_rejection,
                            );
                        }
                        if operation == FuelOperation::BuyUnrefined
                            && refine_collected
                            && can_refine_purchase
                        {
                            match self.begin_fuel_processing_in(
                                txn,
                                identity,
                                quantity_millitons,
                            )? {
                                RuleResult::Rejected(message) => {
                                    return self.reject_or_hold_plan_in(
                                        txn,
                                        &key,
                                        plan,
                                        &message,
                                        hold_on_rejection,
                                    );
                                }
                                RuleResult::Applied(_) => {
                                    plan.state = FlightPlanState::Active;
                                    self.flight_plans.put(
                                        txn,
                                        &key,
                                        &encode_flight_plan_snapshot(&plan)?,
                                    )?;
                                    return Ok(RuleResult::Applied(plan));
                                }
                            }
                        }
                        continue;
                    }
                    let FlightLocus::Body { system_id, body_id } = step.locus else {
                        return self.reject_or_hold_plan_in(
                            txn,
                            &key,
                            plan,
                            "a frontier-fuel step must name its source body",
                            hold_on_rejection,
                        );
                    };
                    let (_, ship) = self.player_and_ship_in(txn, identity)?;
                    if ship.system_id != system_id {
                        return self.reject_or_hold_plan_in(
                            txn,
                            &key,
                            plan,
                            "the plotted fuel source is not in the ship's current system",
                            hold_on_rejection,
                        );
                    }
                    let gas_giant = match operation {
                        FuelOperation::GasGiant => true,
                        FuelOperation::WildernessWater => false,
                        FuelOperation::BuyRefined | FuelOperation::BuyUnrefined => unreachable!(),
                    };
                    match self.begin_frontier_fuel_in(
                        txn,
                        identity,
                        quantity_millitons,
                        gas_giant,
                        Some(refine_collected),
                        Some(body_id),
                    )? {
                        RuleResult::Rejected(message) => {
                            return self.reject_or_hold_plan_in(
                                txn,
                                &key,
                                plan,
                                &message,
                                hold_on_rejection,
                            );
                        }
                        RuleResult::Applied(_) => {
                            let (player, mut ship) = self.player_and_ship_in(txn, identity)?;
                            let ShipLocationRecord::InFlight(ref mut leg) = ship.location else {
                                return Err(StoreError::Corrupt(
                                    "accepted fuel step did not create a flight leg",
                                ));
                            };
                            leg.plan_id = plan.plan_id;
                            leg.plan_revision = plan.revision;
                            leg.leg_index = plan.current_step;
                            self.ships
                                .put(txn, &player.ship_id, &encode_ship_record(&ship)?)?;
                            plan.state = FlightPlanState::Active;
                            self.flight_plans.put(
                                txn,
                                &key,
                                &encode_flight_plan_snapshot(&plan)?,
                            )?;
                            return Ok(RuleResult::Applied(plan));
                        }
                    }
                }
                FlightPlanAction::RefineFuel { quantity_millitons } => match self
                    .begin_fuel_processing_in(txn, identity, quantity_millitons)?
                {
                    RuleResult::Rejected(message) => {
                        return self.reject_or_hold_plan_in(
                            txn,
                            &key,
                            plan,
                            &message,
                            hold_on_rejection,
                        );
                    }
                    RuleResult::Applied(_) => {
                        plan.state = FlightPlanState::Active;
                        self.flight_plans
                            .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
                        return Ok(RuleResult::Applied(plan));
                    }
                },
                FlightPlanAction::BeltCycle { body_id } => {
                    match self.begin_belt_cycle_in(txn, identity, body_id)? {
                        RuleResult::Rejected(message) => {
                            return self.reject_or_hold_plan_in(
                                txn,
                                &key,
                                plan,
                                &message,
                                hold_on_rejection,
                            );
                        }
                        RuleResult::Applied(_) => {
                            let (player, mut ship) = self.player_and_ship_in(txn, identity)?;
                            let ShipLocationRecord::InFlight(ref mut leg) = ship.location else {
                                return Err(StoreError::Corrupt(
                                    "accepted belt cycle did not create a flight leg",
                                ));
                            };
                            leg.plan_id = plan.plan_id;
                            leg.plan_revision = plan.revision;
                            leg.leg_index = plan.current_step;
                            self.ships
                                .put(txn, &player.ship_id, &encode_ship_record(&ship)?)?;
                            plan.state = FlightPlanState::Active;
                            self.flight_plans.put(
                                txn,
                                &key,
                                &encode_flight_plan_snapshot(&plan)?,
                            )?;
                            return Ok(RuleResult::Applied(plan));
                        }
                    }
                }
            }
        }
        plan.state = FlightPlanState::Completed;
        plan.suspension_reason.clear();
        self.flight_plans
            .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
        Ok(RuleResult::Applied(plan))
    }

    fn reject_or_hold_plan_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        key: &[u8],
        mut plan: FlightPlanSnapshot,
        message: &str,
        hold_on_rejection: bool,
    ) -> Result<RuleResult<FlightPlanSnapshot>, StoreError> {
        if !hold_on_rejection {
            return Ok(RuleResult::Rejected(message.into()));
        }
        plan.state = FlightPlanState::Held;
        plan.suspension_reason = message.into();
        self.flight_plans
            .put(txn, key, &encode_flight_plan_snapshot(&plan)?)?;
        Ok(RuleResult::Applied(plan))
    }

    fn encounter_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<Option<EncounterRecord>, StoreError> {
        self.encounters
            .get(txn, &encode_identity(identity))?
            .map(decode_encounter_record)
            .transpose()
    }

    fn acknowledge_checkpoint_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        checkpoint_id: u64,
    ) -> Result<RuleResult<CheckpointSnapshot>, StoreError> {
        let key = encode_identity(identity);
        let Some(mut checkpoint) = self
            .checkpoints
            .get(txn, &key)?
            .map(decode_checkpoint_snapshot)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected(
                "there is no arrival checkpoint awaiting acknowledgement".into(),
            ));
        };
        if checkpoint.checkpoint_id != checkpoint_id {
            return Ok(RuleResult::Rejected(
                "that arrival checkpoint is no longer current".into(),
            ));
        }
        checkpoint.acknowledged = true;
        self.checkpoints
            .put(txn, &key, &encode_checkpoint_snapshot(&checkpoint)?)?;
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let contact_roll =
            crate::ship_condition::mix64(checkpoint.checkpoint_id ^ ship.ship_id ^ ship.system_id);
        let simulation_system = self
            .simulation
            .systems(txn)?
            .into_iter()
            .find(|system| system.system_id == ship.system_id)
            .ok_or(StoreError::MissingTrafficSimulationSystem(ship.system_id))?;
        let candidates = crate::traffic::snapshot(&simulation_system, checkpoint.ready_second)?;
        let candidate_count = u32::try_from(candidates.len()).unwrap_or(u32::MAX);
        let threshold = 1.0 - (5.0_f64 / 6.0).powi(candidate_count as i32);
        let roll = (contact_roll >> 11) as f64 / ((1_u64 << 53) as f64);
        let policy = self
            .system_polity_policies
            .get(txn, &ship.system_id)?
            .map(decode_system_polity_policy)
            .transpose()?;
        let stellar = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("checkpoint system is missing"))?;
        let law = self.primary_world_in(txn, &stellar)?.law_level;
        let order = policy.as_ref().map_or(50, |value| value.chaos_order);
        let combat_orientation = policy.as_ref().map_or(50, |value| value.trade_combat);
        let security = (u16::from(order) + u16::from(law.min(10)) * 10) / 2;
        let enforcement_picket = checkpoint.kind == CheckpointKind::JumpArrival
            && security >= 60
            && contact_roll % 100 < u64::from((security - 40).min(55));
        let pirate_locus = match checkpoint.kind {
            CheckpointKind::JumpArrival => security < 45 && candidate_count < 12,
            CheckpointKind::GasGiant => {
                (35..70).contains(&security) || candidate_count >= 12 && security < 70
            }
            _ => false,
        };
        let pirate_picket = pirate_locus
            && contact_roll.rotate_left(13) % 100
                < u64::from(
                    (70_u16.saturating_sub(security) + u16::from(combat_orientation) / 4).min(60),
                );
        if roll < threshold || enforcement_picket || pirate_picket {
            let encounter_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
            let kind = if enforcement_picket {
                EncounterKind::Inspection
            } else if pirate_picket {
                EncounterKind::Hostile
            } else {
                encounter_kind_for_policy(contact_roll, policy.as_ref())
            };
            let hostile = kind == EncounterKind::Hostile;
            let projected = candidates.get(contact_roll as usize % candidates.len().max(1));
            let opponent_catalog_id = projected.map_or(72, |contact| contact.catalog_id);
            if hostile && security >= 70
                || hostile
                    && catalog_combat_power(ship.catalog_id).saturating_mul(2)
                        >= catalog_combat_power(opponent_catalog_id).saturating_mul(3)
            {
                self.finish_checkpoint_arrival_in(txn, identity, &checkpoint)?;
                return Ok(RuleResult::Applied(checkpoint));
            }
            let summary = match kind {
                EncounterKind::Hostile => {
                    "An armed contact is matching course and demanding that you heave to."
                }
                EncounterKind::Inspection => {
                    "Customs control directs the ship to hold for inspection."
                }
                EncounterKind::TrafficControl => {
                    "Traffic control assigns a crossing order at the arrival lane."
                }
                EncounterKind::Distress => "A nearby vessel is broadcasting a distress call.",
                EncounterKind::Derelict => {
                    "Sensors acquire a vessel drifting without an active transponder."
                }
                EncounterKind::Hazard => {
                    "Traffic control reports debris across the plotted approach."
                }
                EncounterKind::Military => {
                    "A naval picket challenges the ship and requests identification."
                }
                EncounterKind::RoutineTraffic => {
                    "A vessel crosses your arrival lane and exchanges routine identification."
                }
            };
            let snapshot = EncounterSnapshot {
                encounter_id,
                revision: 1,
                kind,
                state: EncounterState::AwaitingPosture,
                started_second: checkpoint.ready_second,
                next_turn_second: 0,
                turn: 0,
                contact: EncounterContact {
                    contact_id: projected.map_or_else(
                        || crate::ship_condition::mix64(encounter_id),
                        |contact| contact.contact_id,
                    ),
                    ship_name: if hostile {
                        "Unlit contact".into()
                    } else {
                        projected
                            .map_or("Passing merchant", |contact| contact.ship_name.as_str())
                            .into()
                    },
                    class_name: projected
                        .map_or(
                            if hostile {
                                "Armed vessel"
                            } else {
                                "Free trader"
                            },
                            |contact| contact.class_name.as_str(),
                        )
                        .into(),
                    transponder: if hostile {
                        "No response".into()
                    } else {
                        projected.map_or_else(
                            || format!("CT-{:08X}", contact_roll as u32),
                            |contact| contact.transponder.clone(),
                        )
                    },
                    role: if hostile {
                        "interceptor".into()
                    } else {
                        projected
                            .map_or("traffic", |contact| contact.role.as_str())
                            .into()
                    },
                    range: "contact range".into(),
                    confidence_percent: 75,
                },
                summary: summary.into(),
            };
            self.encounters.put(
                txn,
                &key,
                &encode_encounter_record(&EncounterRecord {
                    snapshot: snapshot.clone(),
                    opponent_catalog_id,
                    posture: None,
                    fallbacks: Vec::new(),
                    result: None,
                    combat: None,
                    player_order: None,
                    automation_decision: None,
                    combat_log: Vec::new(),
                    pending_interventions: Vec::new(),
                })?,
            )?;
            self.emit_encounter_radio_in(
                txn,
                &ship,
                &snapshot.contact,
                snapshot.kind,
                encounter_id,
                checkpoint.ready_second,
                true,
                &snapshot.summary,
            )?;
            if let Some(mut plan) = self
                .flight_plans
                .get(txn, &key)?
                .map(decode_flight_plan_snapshot)
                .transpose()?
            {
                plan.state = FlightPlanState::Encounter;
                plan.suspension_reason = "contact at arrival checkpoint".into();
                self.flight_plans
                    .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
            }
        } else {
            self.finish_checkpoint_arrival_in(txn, identity, &checkpoint)?;
        }
        Ok(RuleResult::Applied(checkpoint))
    }

    fn finish_checkpoint_arrival_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        checkpoint: &CheckpointSnapshot,
    ) -> Result<(), StoreError> {
        let key = encode_identity(identity);
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let arrived_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?
            .unwrap_or(checkpoint.ready_second)
            .max(checkpoint.ready_second);
        let (world_id, facility_id) = match checkpoint.locus {
            FlightLocus::Port {
                world_id,
                facility_id,
                ..
            } => (world_id, facility_id),
            _ => return Err(StoreError::Corrupt("arrival checkpoint is not at a port")),
        };
        ship.location = ShipLocationRecord::Docked {
            world_id,
            facility_id,
            arrived_second,
        };
        self.prepare_tasks_at_port_in(txn, identity, &mut ship, arrived_second)?;
        for subsystem in &mut ship.subsystems {
            if matches!(
                subsystem.kind,
                ShipSubsystemKind::ManeuverDrive | ShipSubsystemKind::PowerPlant
            ) {
                subsystem.duty_cycles = subsystem.duty_cycles.saturating_add(1);
            }
        }
        self.settle_tasks_at_port_in(txn, identity, &mut player, &mut ship, arrived_second)?;
        self.players
            .put(txn, &key, &encode_player_record(&player))?;
        self.ships
            .put(txn, &player.ship_id, &encode_ship_record(&ship)?)?;
        self.checkpoints.delete(txn, &key)?;
        let available = self
            .simulation
            .available_messages(txn, ship.system_id, arrived_second, false)?
            .into_iter()
            .map(|item| item.message.message_id)
            .collect::<HashSet<_>>();
        let stellar = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("arrival system is missing"))?;
        let law = self.primary_world_in(txn, &stellar)?.law_level;
        let career = self.career_state_in(txn, identity)?;
        let concealment_skill = self
            .persons
            .get(txn, &player.captain_person_id)?
            .map(decode_person_record)
            .transpose()?
            .and_then(|person| {
                person
                    .person
                    .skills
                    .iter()
                    .filter(|rating| rating.skill == crate::wire::SkillId::Stealth)
                    .map(|rating| rating.level)
                    .max()
            })
            .unwrap_or(-3);
        if let Some(warrant) = career.warrants.iter().find(|warrant| {
            let recognition_threshold = if warrant.issuing_polity_id == stellar.polity_id {
                8
            } else {
                14 + u16::from(warrant.evidence_percent < 75) * 3
            };
            let enforceable = crate::careers::warrant_is_enforceable(
                warrant,
                available.contains(&warrant.message_id),
                available.contains(&warrant.resolution_message_id),
            ) && u16::from(law) + u16::from(warrant.severity)
                >= recognition_threshold;
            let entropy = crate::ship_condition::mix64(
                warrant.warrant_id ^ ship.ship_id.rotate_left(11) ^ arrived_second,
            );
            let search_roll = (2 + entropy % 6 + entropy.rotate_left(17) % 6) as i16
                + i16::from(law.div_ceil(2))
                + i16::from(warrant.severity);
            let concealment_target = 8 + i16::from(concealment_skill.max(-3));
            enforceable && search_roll >= concealment_target
        }) {
            let encounter_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
            let record = EncounterRecord {
                snapshot: EncounterSnapshot {
                    encounter_id,
                    revision: 1,
                    kind: EncounterKind::Hostile,
                    state: EncounterState::AwaitingPosture,
                    started_second: arrived_second,
                    next_turn_second: 0,
                    turn: 0,
                    contact: EncounterContact {
                        contact_id: warrant.warrant_id,
                        ship_name: format!("{} Port Enforcement", stellar.name),
                        class_name: "security cutter".into(),
                        transponder: format!("WARRANT-{}", warrant.warrant_id),
                        role: "warrant enforcement".into(),
                        range: "port-control range".into(),
                        confidence_percent: 100,
                    },
                    summary: format!(
                        "Port enforcement has received warrant {}. A law-level {} boarding detail automatically searches the arriving ship, confirms the wanted captain is aboard, and orders this command to submit.",
                        warrant.warrant_id, law
                    ),
                },
                opponent_catalog_id: 144,
                posture: None,
                fallbacks: Vec::new(),
                result: None,
                combat: None,
                player_order: None,
                automation_decision: None,
                combat_log: Vec::new(),
                pending_interventions: Vec::new(),
            };
            self.encounters
                .put(txn, &key, &encode_encounter_record(&record)?)?;
            self.emit_encounter_radio_in(
                txn,
                &ship,
                &record.snapshot.contact,
                record.snapshot.kind,
                encounter_id,
                arrived_second,
                true,
                &record.snapshot.summary,
            )?;
            if let Some(mut plan) = self
                .flight_plans
                .get(txn, &key)?
                .map(decode_flight_plan_snapshot)
                .transpose()?
            {
                plan.state = FlightPlanState::Encounter;
                plan.suspension_reason =
                    "local authorities are executing a delivered warrant".into();
                self.flight_plans
                    .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
            }
            return Ok(());
        }
        if let Some(mut plan) = self
            .flight_plans
            .get(txn, &key)?
            .map(decode_flight_plan_snapshot)
            .transpose()?
        {
            let current = usize::from(plan.current_step);
            let continues = plan.steps.get(current).is_some_and(|step| !step.terminal);
            if continues && current + 1 < plan.steps.len() {
                plan.state = FlightPlanState::Active;
                plan.suspension_reason.clear();
                let _ =
                    self.activate_flight_plan_from_in(txn, identity, plan, current + 1, true)?;
            } else {
                plan.state = FlightPlanState::Completed;
                plan.suspension_reason.clear();
                self.flight_plans
                    .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
            }
        }
        Ok(())
    }

    fn settle_tasks_at_port_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        player: &mut PlayerRecord,
        ship: &mut ShipRecord,
        current: u64,
    ) -> Result<(), StoreError> {
        let mut changed = Vec::new();
        let tasks = self
            .tasks
            .iter(txn)?
            .map(|entry| {
                let (key, value) = entry?;
                Ok((key.to_vec(), decode_stored_task(value)?))
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for (key, mut stored) in tasks {
            if stored.identity != *identity
                || stored.task.performing_ship_id != ship.ship_id
                || stored.task.offer.destination_system_id != ship.system_id
                || !matches!(
                    stored.task.state,
                    crate::wire::TaskState::InTransit
                        | crate::wire::TaskState::Sourcing
                        | crate::wire::TaskState::AwaitingSettlement
                )
                || matches!(
                    stored.task.state,
                    crate::wire::TaskState::Completed
                        | crate::wire::TaskState::Expired
                        | crate::wire::TaskState::Cancelled
                        | crate::wire::TaskState::Defaulted
                )
            {
                continue;
            }
            if stored.task.offer.kind == crate::wire::TaskKind::SupplyCommitment
                && stored.task.performances_completed > 0
                && current
                    < stored
                        .task
                        .offer
                        .delivery_deadline_second
                        .saturating_sub(stored.task.offer.recurrence_seconds)
            {
                continue;
            }
            let late = current > stored.task.offer.delivery_deadline_second;
            let delivered = match stored.task.offer.kind {
                crate::wire::TaskKind::Freight => {
                    let quantity = ship
                        .cargo
                        .iter()
                        .filter(|lot| lot.task_id == stored.task.task_id)
                        .map(|lot| lot.quantity_millitons)
                        .sum::<u64>();
                    ship.cargo.retain(|lot| lot.task_id != stored.task.task_id);
                    if quantity != 0 {
                        ship.revision = ship.revision.saturating_add(1);
                    }
                    stored.task.delivered_quantity_millitons = stored
                        .task
                        .delivered_quantity_millitons
                        .saturating_add(quantity);
                    stored.task.delivered_quantity_millitons >= stored.task.offer.quantity_millitons
                        || (stored.task.offer.partial_delivery_allowed && quantity != 0)
                }
                crate::wire::TaskKind::Passenger
                | crate::wire::TaskKind::Charter
                | crate::wire::TaskKind::Courier => {
                    let carried = ship
                        .passengers
                        .iter()
                        .filter(|manifest| manifest.task_id == stored.task.task_id)
                        .map(|manifest| manifest.passenger_count)
                        .sum::<u16>();
                    ship.passengers
                        .retain(|manifest| manifest.task_id != stored.task.task_id);
                    if carried != 0 {
                        ship.revision = ship.revision.saturating_add(1);
                    }
                    carried >= stored.task.offer.passenger_count && carried != 0
                }
                crate::wire::TaskKind::PurchaseOrder
                | crate::wire::TaskKind::ForwardSale
                | crate::wire::TaskKind::SupplyCommitment => {
                    let mut needed = stored
                        .task
                        .offer
                        .quantity_millitons
                        .saturating_sub(stored.task.delivered_quantity_millitons);
                    let before = needed;
                    for lot in &mut ship.cargo {
                        if lot.title == CargoTitle::PlayerOwned
                            && lot.commodity_id == stored.task.offer.commodity_id
                            && needed > 0
                        {
                            let take = lot.quantity_millitons.min(needed);
                            lot.quantity_millitons -= take;
                            needed -= take;
                            stored.task.delivered_quantity_millitons = stored
                                .task
                                .delivered_quantity_millitons
                                .saturating_add(take);
                        }
                    }
                    ship.cargo.retain(|l| l.quantity_millitons > 0);
                    if before != needed {
                        ship.revision = ship.revision.saturating_add(1);
                    }
                    stored.task.delivered_quantity_millitons >= stored.task.offer.quantity_millitons
                        || stored.task.offer.partial_delivery_allowed && before != needed
                }
                _ => false,
            };
            let within_grace = current
                <= stored
                    .task
                    .offer
                    .delivery_deadline_second
                    .saturating_add(stored.task.offer.passenger_grace_seconds);
            if delivered && (!late || within_grace) {
                let fraction = if stored.task.offer.quantity_millitons == 0 {
                    1000
                } else {
                    stored
                        .task
                        .delivered_quantity_millitons
                        .saturating_mul(1000)
                        / stored.task.offer.quantity_millitons
                };
                let gross_payment = stored
                    .task
                    .offer
                    .payment_credits
                    .saturating_mul(fraction.min(1000))
                    / 1000;
                let late_days = current
                    .saturating_sub(stored.task.offer.delivery_deadline_second)
                    .div_ceil(crate::simulation::SECONDS_PER_DAY);
                let deduction = stored
                    .task
                    .offer
                    .late_deduction_per_day_credits
                    .saturating_mul(late_days)
                    .min(gross_payment);
                let payment = gross_payment.saturating_sub(deduction);
                let (settlement_message_id, _) = self.simulation.dispatch_message(
                    txn,
                    current,
                    ship.system_id,
                    crate::simulation::MessageClass::Private,
                    crate::simulation::MessageImportance::Important,
                    &format!("Settlement filing for task {}", stored.task.task_id),
                    &format!(
                        "The destination office certifies performance under task {} and submits a remittance claim for Cr{} plus release of the posted collateral.",
                        stored.task.task_id, payment
                    ),
                    &[stored.task.offer.origin_system_id],
                )?;
                stored.settlement_message_id = settlement_message_id;
                stored.remittance_message_id = 0;
                stored.pending_payment_credits = payment;
                stored.task.settled_second = current;
                stored.task.revision = stored.task.revision.saturating_add(1);
                stored.task.state = crate::wire::TaskState::AwaitingSettlement;
                stored.task.status_text = format!(
                    "Delivery certified; settlement filing {settlement_message_id} is in transit to the issuing office"
                );
            } else if late && !within_grace {
                let passenger_obligation = stored.task.reserved_passenger_count != 0;
                ship.cargo.retain(|lot| lot.task_id != stored.task.task_id);
                ship.passengers
                    .retain(|manifest| manifest.task_id != stored.task.task_id);
                let assessment = stored
                    .task
                    .reserved_credits
                    .saturating_add(stored.task.offer.failure_penalty_credits)
                    .saturating_add(stored.task.offer.non_delivery_liability_credits);
                player.credits = player.credits.saturating_sub(assessment);
                stored.task.state = crate::wire::TaskState::Defaulted;
                stored.task.reserved_credits = 0;
                stored.task.reserved_cargo_millitons = 0;
                stored.task.reserved_passenger_count = 0;
                stored.task.settled_second = current;
                stored.task.revision = stored.task.revision.saturating_add(1);
                stored.task.status_text = if passenger_obligation {
                    "Passenger grace expired; travelers disembarked at the first staffed port and capped liability was assessed".into()
                } else {
                    "Delivery deadline missed; penalty and capped non-delivery liability assessed"
                        .into()
                };
            } else {
                stored.task.state = crate::wire::TaskState::AwaitingSettlement;
                stored.task.status_text =
                    "Destination reached; required delivery is incomplete".into();
            }
            changed.push((key, stored));
        }
        for (key, stored) in changed {
            self.tasks.put(txn, &key, &encode_stored_task(&stored)?)?;
        }
        self.process_task_settlement_mail_arrival_in(txn, ship.system_id, current)?;
        self.receive_task_remittances_available_in(txn, identity, ship.system_id, current, player)?;
        Ok(())
    }

    fn prepare_tasks_at_port_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        ship: &mut ShipRecord,
        current: u64,
    ) -> Result<(), StoreError> {
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship status data missing"))?;
        let mut changed = Vec::new();
        let tasks = self
            .tasks
            .iter(txn)?
            .map(|entry| {
                let (key, value) = entry?;
                Ok((key.to_vec(), decode_stored_task(value)?))
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for (key, mut stored) in tasks {
            if stored.identity != *identity
                || stored.task.performing_ship_id != ship.ship_id
                || stored.task.offer.origin_system_id != ship.system_id
                || !stored.task.known_result
                || !matches!(
                    stored.task.state,
                    crate::wire::TaskState::ClaimPending | crate::wire::TaskState::Accepted
                )
            {
                continue;
            }
            match stored.task.offer.kind {
                crate::wire::TaskKind::Freight => {
                    let already_loaded = ship
                        .cargo
                        .iter()
                        .any(|lot| lot.task_id == stored.task.task_id);
                    let used = ship
                        .cargo
                        .iter()
                        .map(|lot| lot.quantity_millitons)
                        .sum::<u64>();
                    if !already_loaded
                        && effective_cargo_capacity(ship, &spec).saturating_sub(used)
                            >= stored.task.offer.quantity_millitons
                    {
                        let lot_id = take_id_range(self.meta, txn, META_NEXT_CARGO_LOT_ID, 1)?;
                        ship.cargo.push(CargoLot {
                            cargo_lot_id: lot_id,
                            commodity_id: stored.task.offer.commodity_id,
                            commodity_name: crate::commerce::commodity(
                                stored.task.offer.commodity_id,
                            )
                            .map_or("Contract cargo".into(), |goods| goods.name.into()),
                            quantity_millitons: stored.task.offer.quantity_millitons,
                            purchase_price_per_ton: 0,
                            origin_system_id: stored.task.offer.origin_system_id,
                            acquired_second: current,
                            title: CargoTitle::Freight,
                            task_id: stored.task.task_id,
                            unique_object_id: 0,
                            condition_percent: 100,
                            destination_system_id: stored.task.offer.destination_system_id,
                            source_body_id: 0,
                            source_lode_id: 0,
                        });
                        ship.revision = ship.revision.saturating_add(1);
                        stored.task.state = crate::wire::TaskState::Loading;
                        stored.task.loaded_second = current;
                        stored.task.revision = stored.task.revision.saturating_add(1);
                        stored.task.status_text =
                            "Contract cargo loaded; ready for departure".into();
                    } else if !already_loaded {
                        stored.task.status_text =
                            "At origin, but insufficient free hold space for loading".into();
                    }
                }
                crate::wire::TaskKind::Passenger
                | crate::wire::TaskKind::Charter
                | crate::wire::TaskKind::Courier => {
                    let already_embarked = ship
                        .passengers
                        .iter()
                        .any(|manifest| manifest.task_id == stored.task.task_id);
                    let occupied = ship
                        .passengers
                        .iter()
                        .filter(|manifest| {
                            (manifest.passenger_class == crate::wire::PassengerClass::Low)
                                == (stored.task.offer.passenger_class
                                    == crate::wire::PassengerClass::Low)
                        })
                        .map(|manifest| manifest.passenger_count)
                        .sum::<u16>();
                    let capacity =
                        if stored.task.offer.passenger_class == crate::wire::PassengerClass::Low {
                            spec.low_berths
                        } else {
                            spec.passenger_berths
                        };
                    if !already_embarked
                        && capacity.saturating_sub(occupied) >= stored.task.offer.passenger_count
                    {
                        ship.passengers.push(PassengerManifestRecord {
                            task_id: stored.task.task_id,
                            passenger_count: stored.task.offer.passenger_count,
                            passenger_class: stored.task.offer.passenger_class,
                            origin_system_id: stored.task.offer.origin_system_id,
                            destination_system_id: stored.task.offer.destination_system_id,
                            embarked_second: current,
                        });
                        ship.revision = ship.revision.saturating_add(1);
                        stored.task.state = crate::wire::TaskState::Loading;
                        stored.task.loaded_second = current;
                        stored.task.revision = stored.task.revision.saturating_add(1);
                        stored.task.status_text = format!(
                            "{} passengers embarked and entered in the ship manifest",
                            stored.task.offer.passenger_count
                        );
                    } else if !already_embarked {
                        stored.task.status_text =
                            "At origin, but the contracted accommodation is unavailable".into();
                    }
                }
                _ => {}
            }
            changed.push((key, stored));
        }
        for (key, stored) in changed {
            self.tasks.put(txn, &key, &encode_stored_task(&stored)?)?;
        }
        Ok(())
    }

    fn mark_tasks_in_transit_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        ship_id: u64,
        destination_system_id: u64,
    ) -> Result<(), StoreError> {
        let mut changed = Vec::new();
        for entry in self.tasks.iter(txn)? {
            let (key, value) = entry?;
            let mut stored = decode_stored_task(value)?;
            if stored.identity == *identity
                && stored.task.performing_ship_id == ship_id
                && stored.task.offer.destination_system_id == destination_system_id
                && matches!(
                    stored.task.state,
                    crate::wire::TaskState::Loading | crate::wire::TaskState::Sourcing
                )
            {
                stored.task.state = crate::wire::TaskState::InTransit;
                stored.task.status_text = "In transit under the active flight plan".into();
                changed.push((key.to_vec(), stored));
            }
        }
        for (key, stored) in changed {
            self.tasks.put(txn, &key, &encode_stored_task(&stored)?)?;
        }
        Ok(())
    }

    fn resolve_encounter_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        request: &crate::wire::ResolveEncounterRequest,
    ) -> Result<RuleResult<EncounterResult>, StoreError> {
        let key = encode_identity(identity);
        let Some(mut record) = self
            .encounters
            .get(txn, &key)?
            .map(decode_encounter_record)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected("there is no active encounter".into()));
        };
        if record.snapshot.encounter_id != request.encounter_id
            || record.snapshot.revision != request.expected_revision
        {
            return Ok(RuleResult::Rejected(
                "that encounter revision is stale".into(),
            ));
        }
        if record.snapshot.state != EncounterState::AwaitingPosture {
            return Ok(RuleResult::Rejected(
                "standing orders have already been submitted for this encounter".into(),
            ));
        }
        record.posture = Some(request.posture);
        record.fallbacks = request.fallbacks.clone();
        record.snapshot.revision += 1;
        record.snapshot.state = EncounterState::Resolving;
        record.snapshot.turn = 1;
        record.snapshot.next_turn_second = record.snapshot.started_second.saturating_add(1_000);
        let refusal_escalates = matches!(
            record.snapshot.kind,
            EncounterKind::Hostile | EncounterKind::Inspection | EncounterKind::Military
        ) && !matches!(
            request.posture,
            EncounterPosture::Comply | EncounterPosture::Surrender
        );
        if refusal_escalates {
            let (_, mut ship) = self.player_and_ship_in(txn, identity)?;
            if matches!(
                record.snapshot.kind,
                EncounterKind::Inspection | EncounterKind::Military
            ) {
                let mut career = self.career_state_in(txn, identity)?;
                let already_recorded = career.warrants.iter().any(|warrant| {
                    warrant.status != crate::careers::WarrantStatus::Satisfied
                        && warrant.accusation.contains("refusal of lawful boarding")
                        && warrant.origin_system_id == ship.system_id
                });
                if !already_recorded {
                    let stellar = self
                        .systems
                        .get(txn, &ship.system_id)?
                        .map(decode_stellar_system)
                        .transpose()?
                        .ok_or(StoreError::Corrupt("inspection system is missing"))?;
                    let warrant_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
                    let mut warrant = crate::careers::warrant_for_unlawful_attack(
                        warrant_id,
                        stellar.polity_id,
                        ship.system_id,
                        record.snapshot.started_second,
                        100_000,
                        100,
                    );
                    warrant.accusation = "refusal of lawful boarding and inspection orders".into();
                    warrant.bounty_credits = 10_000;
                    let destinations = self
                        .simulation
                        .systems(txn)?
                        .into_iter()
                        .map(|system| system.system_id)
                        .collect::<Vec<_>>();
                    let (message_id, _) = self.simulation.dispatch_message(
                        txn,
                        record.snapshot.started_second,
                        ship.system_id,
                        crate::simulation::MessageClass::PublicService,
                        crate::simulation::MessageImportance::Important,
                        &format!("Inspection refusal warrant {warrant_id}"),
                        &format!(
                            "The naval picket records refusal of lawful boarding and inspection orders. Warrant {warrant_id} directs capable enforcement vessels to intercept this command at its next controlled locus."
                        ),
                        &destinations,
                    )?;
                    warrant.message_id = message_id;
                    warrant.status = crate::careers::WarrantStatus::Propagating;
                    self.record_player_warrant_dossier_in(txn, identity, &ship, &warrant)?;
                    career.warrants.push(warrant);
                    career.revision = career.revision.saturating_add(1);
                    self.put_career_state_in(txn, identity, &career)?;
                }
            }
            manifest_ship_quirks(
                &mut ship,
                &[
                    ShipQuirkKind::TurretFault,
                    ShipQuirkKind::BridgeChairFault,
                    ShipQuirkKind::FullSpeedVibration,
                ],
            );
            let entropy = crate::ship_condition::mix64(record.snapshot.encounter_id ^ ship.ship_id);
            let player_initiative = ((entropy % 6) + 1 + ((entropy >> 8) % 6) + 1) as i16;
            let opponent_initiative =
                (((entropy >> 16) % 6) + 1 + ((entropy >> 24) % 6) + 1) as i16;
            let mut player_vessel = crate::combat::materialize_vessel(
                ship.ship_id,
                1,
                ship.name.clone(),
                ship.catalog_id,
                player_initiative,
            )
            .map_err(|_| StoreError::Corrupt("player combat loadout is invalid"))?;
            apply_ship_damage_to_combat(&ship, &mut player_vessel);
            self.ships
                .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
            let opponent_id = record.snapshot.contact.contact_id | (1_u64 << 63);
            let opponent = crate::combat::materialize_vessel(
                opponent_id,
                2,
                record.snapshot.contact.ship_name.clone(),
                record.opponent_catalog_id,
                opponent_initiative,
            )
            .map_err(|_| StoreError::Corrupt("contact combat loadout is invalid"))?;
            record.combat = Some(crate::combat::CombatState {
                combat_id: record.snapshot.encounter_id,
                revision: 1,
                round: 1,
                round_started_second: record.snapshot.started_second,
                range: crate::combat::RangeBand::Short,
                vessels: vec![player_vessel, opponent],
                missiles: Vec::new(),
                boarding: Vec::new(),
                complete: false,
            });
            let simulation_system = self
                .simulation
                .systems(txn)?
                .into_iter()
                .find(|system| system.system_id == ship.system_id)
                .ok_or(StoreError::MissingTrafficSimulationSystem(ship.system_id))?;
            record.pending_interventions = self.pending_interventions_for_combat(
                txn,
                &simulation_system,
                record.snapshot.started_second,
                record.snapshot.contact.contact_id,
                !matches!(
                    record.snapshot.kind,
                    EncounterKind::Inspection | EncounterKind::Military
                ),
                entropy,
            )?;
            record.snapshot.summary = if matches!(
                record.snapshot.kind,
                EncounterKind::Inspection | EncounterKind::Military
            ) {
                "The inspection order is refused. The picket opens range while calling more capable enforcement vessels; joint crew orders are due before the one-kilosecond activation closes."
            } else {
                "General quarters. Joint crew orders are due before the one-kilosecond activation closes."
            }.into();
        } else {
            record.snapshot.summary =
                "The declared response is queued for authoritative resolution.".into();
        }
        let result = EncounterResult {
            encounter_id: record.snapshot.encounter_id,
            resolved: false,
            terminal: false,
            outcome: "Encounter turn queued".into(),
            turns: 0,
            cargo_lost_millitons: 0,
            fuel_lost_millitons: 0,
            damage_hits: 0,
        };
        self.encounters
            .put(txn, &key, &encode_encounter_record(&record)?)?;
        self.schedule_encounter_turn_in(
            txn,
            identity,
            record.snapshot.encounter_id,
            record.snapshot.next_turn_second,
        )?;
        Ok(RuleResult::Applied(result))
    }

    fn combat_snapshot_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<Option<crate::wire::CombatSnapshot>, StoreError> {
        let Some(record) = self.encounter_in(txn, identity)? else {
            return Ok(None);
        };
        if let Some(shared) = self
            .shared_combats
            .get(txn, &record.snapshot.encounter_id)?
            .map(decode_shared_combat_record)
            .transpose()?
        {
            let (_, ship) = self.player_and_ship_in(txn, identity)?;
            let participant = shared
                .participants
                .iter()
                .find(|participant| {
                    participant.identity == *identity && participant.ship_id == ship.ship_id
                })
                .ok_or(StoreError::Corrupt(
                    "commanded ship is not a shared-combat participant",
                ))?;
            if !participant.directly_commanded {
                return Ok(None);
            }
            let default =
                crate::combat::conservative_order(&shared.combat, ship.ship_id).map_err(|_| {
                    StoreError::Corrupt("commanded vessel is absent from shared combat")
                })?;
            let actors = self.combat_actors_in(txn, identity, ship.ship_id)?;
            let submitted = shared
                .orders
                .iter()
                .any(|order| order.vessel_id == ship.ship_id);
            return Ok(Some(combat_snapshot(
                &shared.combat,
                &ship,
                &default,
                actors,
                submitted,
                &shared.combat_log,
                &shared
                    .participants
                    .iter()
                    .map(|participant| participant.ship_id)
                    .collect::<Vec<_>>(),
            )));
        }
        let Some(combat) = &record.combat else {
            return Ok(None);
        };
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let default = crate::combat::conservative_order(combat, ship.ship_id)
            .map_err(|_| StoreError::Corrupt("commanded vessel is absent from combat"))?;
        let actors = self.combat_actors_in(txn, identity, ship.ship_id)?;
        Ok(Some(combat_snapshot(
            combat,
            &ship,
            &default,
            actors,
            record.player_order.is_some(),
            &record.combat_log,
            &[ship.ship_id],
        )))
    }

    fn combat_actors_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship_id: u64,
    ) -> Result<Vec<crate::wire::CombatActor>, StoreError> {
        let mut actors = Vec::new();
        for entry in self.crew_services.iter(txn)? {
            let (_, encoded) = entry?;
            let service = decode_crew_service(encoded)?;
            if service.command != *identity || service.ship_id != ship_id {
                continue;
            }
            let person = self
                .persons
                .get(txn, &service.person_id)?
                .map(decode_person_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("combat crewmember is missing"))?;
            let incapacitated = person_incapacitated(&person);
            let role_kind = crate::wire::CrewRoleKind::from_slug(&service.role);
            let captain = service.role == "captain";
            actors.push(crate::wire::CombatActor {
                person_id: person.person_id,
                name: person.person.name,
                station: service.role,
                available: !incapacitated && !service.assigned_slot_ids.is_empty(),
                action_budget: u8::from(!incapacitated && !service.assigned_slot_ids.is_empty()),
                role_kind,
                captain,
            });
        }
        actors.sort_by_key(|actor| actor.person_id);
        Ok(actors)
    }

    fn player_combat_order_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship: &ShipRecord,
        combat: &crate::combat::CombatState,
        request: &crate::wire::CombatOrderSet,
    ) -> Result<Result<crate::combat::JointOrder, String>, StoreError> {
        let mut roster = HashMap::new();
        for entry in self.crew_services.iter(txn)? {
            let (_, encoded) = entry?;
            let service = decode_crew_service(encoded)?;
            if service.command != *identity || service.ship_id != ship.ship_id {
                continue;
            }
            let person = self
                .persons
                .get(txn, &service.person_id)?
                .map(decode_person_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("combat crewmember is missing"))?;
            roster.insert(service.person_id, (service, person));
        }
        let mut used = HashSet::new();
        let mut order = wire_combat_order(request, ship.ship_id)?;
        for (index, action) in request.actions.iter().enumerate() {
            let Some((service, person)) = roster.get(&action.actor_person_id) else {
                return Ok(Err(
                    "the named combat actor is not aboard this vessel".into()
                ));
            };
            if !used.insert(action.actor_person_id) {
                return Ok(Err(format!(
                    "{} already has a significant action this combat turn",
                    person.person.name
                )));
            }
            if !combat_actor_available(service, person) {
                return Ok(Err(format!(
                    "{} is off watch or incapacitated",
                    person.person.name
                )));
            }
            if !combat_action_role_matches(&service.role, action.kind) {
                return Ok(Err(format!(
                    "{} is not assigned to a station that can perform that action",
                    person.person.name
                )));
            }
            order.action_dms[index] = combat_action_task_dm(
                person,
                action.kind,
                action.mount_id,
                combat,
                ship.ship_id,
                index,
            );
        }
        for (index, reaction) in request.reactions.iter().enumerate() {
            let Some((service, person)) = roster.get(&reaction.actor_person_id) else {
                return Ok(Err(
                    "the named reaction operator is not aboard this vessel".into()
                ));
            };
            if !combat_actor_available(service, person)
                || !combat_reaction_role_matches(&service.role, reaction.kind)
            {
                return Ok(Err(format!(
                    "{} cannot stand the named reaction watch",
                    person.person.name
                )));
            }
            order.reaction_dms[index] =
                combat_reaction_task_dm(person, reaction.kind, combat, ship.ship_id, index);
        }
        Ok(Ok(order))
    }

    fn staff_automated_order_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship: &ShipRecord,
        combat: &crate::combat::CombatState,
        order: &crate::combat::JointOrder,
    ) -> Result<crate::combat::JointOrder, StoreError> {
        let actors = self.combat_actors_in(txn, identity, ship.ship_id)?;
        let request = combat_order_wire(order, combat.combat_id, &actors);
        let mut staffed = self
            .player_combat_order_in(txn, identity, ship, combat, &request)?
            .map_err(|_| StoreError::Corrupt("tactical controller produced an unstaffed order"))?;
        staffed.automated = true;
        Ok(staffed)
    }

    fn submit_combat_order_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        request: &crate::wire::CombatOrderSet,
    ) -> Result<RuleResult<crate::wire::CombatSnapshot>, StoreError> {
        let key = encode_identity(identity);
        let Some(mut record) = self
            .encounters
            .get(txn, &key)?
            .map(decode_encounter_record)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected("there is no active combat".into()));
        };
        if self
            .shared_combats
            .get(txn, &record.snapshot.encounter_id)?
            .is_some()
        {
            return self.submit_shared_combat_order_in(
                txn,
                identity,
                record.snapshot.encounter_id,
                request,
            );
        }
        let Some(combat) = record.combat.as_ref() else {
            return Ok(RuleResult::Rejected(
                "the current encounter is not a combat".into(),
            ));
        };
        if combat.complete
            || request.combat_id != combat.combat_id
            || request.view_revision != combat.revision
        {
            return Ok(RuleResult::Rejected("that combat view is stale".into()));
        }
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let order = if request.use_tactical_controller {
            let decision =
                crate::combat::risk_directed_order(combat, ship.ship_id, &ship.combat_policy)
                    .map_err(|_| {
                        StoreError::Corrupt("tactical controller could not create an order")
                    })?;
            let staffed =
                self.staff_automated_order_in(txn, identity, &ship, combat, &decision.order)?;
            let mut decision = decision;
            decision.order = staffed.clone();
            record.automation_decision = Some(decision);
            staffed
        } else {
            match self.player_combat_order_in(txn, identity, &ship, combat, request)? {
                Ok(order) => order,
                Err(message) => return Ok(RuleResult::Rejected(message)),
            }
        };
        // Validate shape immediately by completing the other participants with
        // deterministic controller orders against a clone.  This consumes no
        // game entropy and commits no outcome.
        let mut validation = vec![order.clone()];
        for vessel in combat.vessels.iter().filter(|vessel| {
            vessel.vessel_id != ship.ship_id
                && vessel.disposition == crate::combat::VesselDisposition::Active
        }) {
            validation.push(
                crate::combat::risk_directed_order(
                    combat,
                    vessel.vessel_id,
                    &crate::combat::AutomationPolicy {
                        objective: crate::combat::Objective::Defeat,
                        ..Default::default()
                    },
                )
                .map_err(|_| StoreError::Corrupt("contact controller could not create an order"))?
                .order,
            );
        }
        if let Err(message) = crate::combat::resolve_round(combat, &validation) {
            return Ok(RuleResult::Rejected(message));
        }
        record.player_order = Some(order);
        self.encounters
            .put(txn, &key, &encode_encounter_record(&record)?)?;
        let default = crate::combat::conservative_order(combat, ship.ship_id)
            .map_err(|_| StoreError::Corrupt("commanded vessel is absent from combat"))?;
        let actors = self.combat_actors_in(txn, identity, ship.ship_id)?;
        Ok(RuleResult::Applied(combat_snapshot(
            combat,
            &ship,
            &default,
            actors,
            true,
            &record.combat_log,
            &[ship.ship_id],
        )))
    }

    fn submit_shared_combat_order_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        combat_id: u64,
        request: &crate::wire::CombatOrderSet,
    ) -> Result<RuleResult<crate::wire::CombatSnapshot>, StoreError> {
        let Some(mut shared) = self
            .shared_combats
            .get(txn, &combat_id)?
            .map(decode_shared_combat_record)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected(
                "there is no active shared combat".into(),
            ));
        };
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let Some(participant) = shared.participants.iter().find(|participant| {
            participant.identity == *identity && participant.ship_id == ship.ship_id
        }) else {
            return Ok(RuleResult::Rejected(
                "the commanded ship is not in this combat".into(),
            ));
        };
        if !participant.directly_commanded {
            return Ok(RuleResult::Rejected(
                "that ship is fighting under its standing combat policy".into(),
            ));
        }
        if shared.combat.complete
            || request.combat_id != shared.combat.combat_id
            || request.view_revision != shared.combat.revision
        {
            return Ok(RuleResult::Rejected("that combat view is stale".into()));
        }
        if shared
            .orders
            .iter()
            .any(|order| order.vessel_id == ship.ship_id)
        {
            return Ok(RuleResult::Rejected(
                "orders for this combat revision are already sealed".into(),
            ));
        }
        let order = if request.use_tactical_controller {
            let mut decision = crate::combat::risk_directed_order(
                &shared.combat,
                ship.ship_id,
                &ship.combat_policy,
            )
            .map_err(|_| StoreError::Corrupt("tactical controller could not create an order"))?;
            decision.order = self.staff_automated_order_in(
                txn,
                identity,
                &ship,
                &shared.combat,
                &decision.order,
            )?;
            shared
                .automation_decisions
                .retain(|stored| stored.order.vessel_id != ship.ship_id);
            shared.automation_decisions.push(decision.clone());
            decision.order
        } else {
            match self.player_combat_order_in(txn, identity, &ship, &shared.combat, request)? {
                Ok(order) => order,
                Err(message) => return Ok(RuleResult::Rejected(message)),
            }
        };
        let mut validation = shared.orders.clone();
        validation.push(order.clone());
        let missing_vessels = shared
            .combat
            .vessels
            .iter()
            .filter(|vessel| {
                vessel.disposition == crate::combat::VesselDisposition::Active
                    && !validation
                        .iter()
                        .any(|order| order.vessel_id == vessel.vessel_id)
            })
            .cloned()
            .collect::<Vec<_>>();
        for vessel in &missing_vessels {
            validation.push(
                crate::combat::risk_directed_order(
                    &shared.combat,
                    vessel.vessel_id,
                    &crate::combat::AutomationPolicy::default(),
                )
                .map_err(|_| StoreError::Corrupt("combat controller could not validate orders"))?
                .order,
            );
        }
        if let Err(message) = crate::combat::resolve_round(&shared.combat, &validation) {
            return Ok(RuleResult::Rejected(message));
        }
        shared.orders.push(order);
        self.shared_combats
            .put(txn, &combat_id, &encode_shared_combat_record(&shared)?)?;
        let default = crate::combat::conservative_order(&shared.combat, ship.ship_id)
            .map_err(|_| StoreError::Corrupt("commanded vessel is absent from shared combat"))?;
        let actors = self.combat_actors_in(txn, identity, ship.ship_id)?;
        Ok(RuleResult::Applied(combat_snapshot(
            &shared.combat,
            &ship,
            &default,
            actors,
            true,
            &shared.combat_log,
            &shared
                .participants
                .iter()
                .map(|participant| participant.ship_id)
                .collect::<Vec<_>>(),
        )))
    }

    fn set_combat_policy_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        request: &crate::wire::CombatAutomationPolicy,
    ) -> Result<RuleResult<crate::wire::CombatSnapshot>, StoreError> {
        let (_, mut ship) = self.player_and_ship_in(txn, identity)?;
        if request.expected_revision != ship.combat_policy.revision
            || request.minimum_victory_percent > 100
        {
            return Ok(RuleResult::Rejected(
                "the combat policy revision or probability is invalid".into(),
            ));
        }
        ship.combat_policy = crate::combat::AutomationPolicy {
            revision: ship.combat_policy.revision.saturating_add(1),
            minimum_victory_percent: request.minimum_victory_percent,
            objective: request.objective,
            permit_surrender: request.permit_surrender,
            permit_abandon_ship: request.permit_abandon_ship,
        };
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        let Some(record) = self.encounter_in(txn, identity)? else {
            return Ok(RuleResult::Rejected(
                "combat policy saved; there is no active combat".into(),
            ));
        };
        if let Some(shared) = self
            .shared_combats
            .get(txn, &record.snapshot.encounter_id)?
            .map(decode_shared_combat_record)
            .transpose()?
        {
            let default =
                crate::combat::conservative_order(&shared.combat, ship.ship_id).map_err(|_| {
                    StoreError::Corrupt("commanded vessel is absent from shared combat")
                })?;
            let actors = self.combat_actors_in(txn, identity, ship.ship_id)?;
            return Ok(RuleResult::Applied(combat_snapshot(
                &shared.combat,
                &ship,
                &default,
                actors,
                shared
                    .orders
                    .iter()
                    .any(|order| order.vessel_id == ship.ship_id),
                &shared.combat_log,
                &shared
                    .participants
                    .iter()
                    .map(|participant| participant.ship_id)
                    .collect::<Vec<_>>(),
            )));
        }
        let Some(combat) = &record.combat else {
            return Ok(RuleResult::Rejected(
                "combat policy saved; there is no active combat".into(),
            ));
        };
        let default = crate::combat::conservative_order(combat, ship.ship_id)
            .map_err(|_| StoreError::Corrupt("commanded vessel is absent from combat"))?;
        let actors = self.combat_actors_in(txn, identity, ship.ship_id)?;
        Ok(RuleResult::Applied(combat_snapshot(
            combat,
            &ship,
            &default,
            actors,
            record.player_order.is_some(),
            &record.combat_log,
            &[ship.ship_id],
        )))
    }

    fn generated_warrant_contacts_in(
        &self,
        txn: &heed::RoTxn<'_>,
        system_id: u64,
        current: u64,
    ) -> Result<Vec<crate::traffic::TrafficContact>, StoreError> {
        let mut result = Vec::new();
        for entry in self.warrant_dossiers.iter(txn)? {
            let (_, encoded) = entry?;
            let dossier = decode_warrant_dossier(encoded)?;
            if dossier.target_kind != WarrantTargetKind::Generated
                || dossier.custody != WarrantCustodyState::AtLarge
                || dossier.current_system_id != system_id
            {
                continue;
            }
            let spec = creation::ship_status_spec(dossier.catalog_id).ok_or(
                StoreError::Corrupt("generated bounty vessel catalog missing"),
            )?;
            let class_name = creation::ship_market_catalog()
                .into_iter()
                .find(|entry| entry.catalog_id == dossier.catalog_id)
                .map_or_else(|| "unclassified vessel".into(), |entry| entry.class_name);
            result.push(crate::traffic::TrafficContact {
                contact_id: dossier.associated_ship_id,
                catalog_id: dossier.catalog_id,
                class_name,
                ship_name: dossier.associated_ship_name,
                transponder: dossier.associated_transponder,
                operator_name: "Independent operator".into(),
                role: "transient merchant".into(),
                displacement_millitons: spec.displacement_millitons,
                origin_system_id: dossier.origin_system_id,
                destination_system_id: system_id,
                movement: crate::traffic::TrafficMovementKind::Present,
                edge_second: current,
                resolution: crate::traffic::TrafficContactResolution::Identified,
                confidence_percent: 100,
                player_owned: false,
                online_controlled: false,
                attachment: crate::traffic::TrafficAttachment::Spaceborne,
            });
        }
        Ok(result)
    }

    fn process_generated_warrant_day_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        system_id: u64,
        current: u64,
    ) -> Result<(), StoreError> {
        let systems = self.simulation.systems(txn)?;
        let Some(system) = systems
            .iter()
            .find(|candidate| candidate.system_id == system_id)
        else {
            return Ok(());
        };
        if systems.iter().map(|candidate| candidate.system_id).min() == Some(system_id) {
            let records = self
                .warrant_dossiers
                .iter(txn)?
                .map(|entry| {
                    let (_, encoded) = entry?;
                    decode_warrant_dossier(encoded)
                })
                .collect::<Result<Vec<_>, StoreError>>()?;
            for mut dossier in records.into_iter().filter(|dossier| {
                dossier.target_kind == WarrantTargetKind::Generated
                    && dossier.custody == WarrantCustodyState::AtLarge
                    && dossier.next_move_second <= current
            }) {
                if let Some(location) = systems
                    .iter()
                    .find(|candidate| candidate.system_id == dossier.current_system_id)
                {
                    if !location.jump_two_neighbors.is_empty() {
                        let index = (dossier.warrant_id ^ current) as usize
                            % location.jump_two_neighbors.len();
                        dossier.current_system_id = location.jump_two_neighbors[index];
                    }
                }
                dossier.next_move_second =
                    current.saturating_add(7 * crate::simulation::SECONDS_PER_DAY);
                self.warrant_dossiers.put(
                    txn,
                    &dossier.warrant_id,
                    &encode_warrant_dossier(&dossier)?,
                )?;
            }
        }

        let day = current / crate::simulation::SECONDS_PER_DAY;
        if (day.saturating_add(system_id)) % 14 != 0 {
            return Ok(());
        }
        let Some(contact) = crate::traffic::snapshot(system, current)?
            .into_iter()
            .next()
        else {
            return Ok(());
        };
        let warrant_id = take_id_range(self.meta, txn, META_NEXT_ENCOUNTER_ID, 1)?;
        let person_id = GENERATED_LEGAL_ENTITY_BIT | warrant_id;
        let ship_id = GENERATED_LEGAL_ENTITY_BIT | warrant_id.rotate_left(17);
        let subject_name =
            crate::person_names::generated_person_name(system_id ^ current, person_id);
        let severity = 1 + (warrant_id % 4) as u8;
        let bounty_credits = 4_000_u64.saturating_mul(u64::from(severity).pow(2));
        let accusations = [
            "failure to answer a lawful customs summons",
            "cargo theft and fraudulent manifesting",
            "assault upon a port officer",
            "armed piracy and flight from lawful custody",
        ];
        let accusation = accusations[usize::from(severity - 1)].to_owned();
        let destinations = systems
            .iter()
            .map(|value| value.system_id)
            .collect::<Vec<_>>();
        let (message_id, _) = self.simulation.dispatch_message(
            txn,
            current,
            system_id,
            crate::simulation::MessageClass::PublicService,
            crate::simulation::MessageImportance::Important,
            &format!("Warrant {warrant_id}: {subject_name}"),
            &format!(
                "The authority issues a severity-{severity} warrant for {subject_name}, last reported aboard {} ({}). Accusation: {accusation}. Lawful delivery of the subject pays Cr{bounty_credits}.",
                contact.ship_name, contact.transponder
            ),
            &destinations,
        )?;
        let dossier = WarrantDossierRecord {
            warrant_id,
            message_id,
            resolution_message_id: 0,
            issuing_polity_id: system.polity_id,
            origin_system_id: system_id,
            filed_second: current,
            subject_person_id: person_id,
            subject_name,
            subject_role: if warrant_id & 1 == 0 {
                "captain"
            } else {
                "crew member"
            }
            .into(),
            accusation,
            bounty_credits,
            severity,
            evidence_percent: 65_u8.saturating_add(severity.saturating_mul(7)).min(95),
            target_kind: WarrantTargetKind::Generated,
            target_identity: PlayerIdentity {
                bbs_id: 0,
                player_id: 0,
            },
            associated_ship_ids: vec![ship_id],
            associated_ship_id: ship_id,
            associated_ship_name: contact.ship_name,
            associated_transponder: contact.transponder,
            catalog_id: contact.catalog_id,
            current_system_id: system_id,
            next_move_second: current.saturating_add(7 * crate::simulation::SECONDS_PER_DAY),
            association_confirmed: true,
            subject_present: true,
            concealment_skill: (severity as i8).saturating_sub(2),
            custody: WarrantCustodyState::AtLarge,
            custodian: PlayerIdentity {
                bbs_id: 0,
                player_id: 0,
            },
            custody_ship_id: 0,
            settled_second: 0,
        };
        self.warrant_dossiers
            .put(txn, &warrant_id, &encode_warrant_dossier(&dossier)?)?;
        Ok(())
    }

    fn combat_career_snapshot_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<crate::wire::CombatCareerSnapshot, StoreError> {
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let mut state = self.career_state_in(txn, identity)?;
        state.opportunities.retain(|offer| {
            offer.state != crate::careers::OpportunityState::Offered
                || current < offer.expires_second
        });
        let system_contacts = if ship.system_id == 0
            || matches!(
                ship.location,
                ShipLocationRecord::InFlight(FlightLegRecord {
                    purpose: FlightLegPurpose::Jump { .. },
                    ..
                })
            ) {
            Vec::new()
        } else {
            let system = self
                .simulation
                .systems(txn)?
                .into_iter()
                .find(|system| system.system_id == ship.system_id)
                .ok_or(StoreError::MissingTrafficSimulationSystem(ship.system_id))?;
            let mut contacts = crate::traffic::snapshot(&system, current)?;
            contacts.extend(self.player_traffic_contacts_in(txn, &ship, None, current)?);
            contacts.extend(self.generated_warrant_contacts_in(txn, ship.system_id, current)?);
            contacts.sort_by_key(|contact| (contact.edge_second, contact.contact_id));
            contacts
                .into_iter()
                .map(|mut contact| {
                    contact.catalog_id = 0;
                    contact.class_name.clear();
                    contact.displacement_millitons = 0;
                    contact.resolution = crate::traffic::TrafficContactResolution::TransponderOnly;
                    contact.confidence_percent = 100;
                    contact
                })
                .collect()
        };
        let local_contacts = self.observed_local_traffic_in(txn, identity, &ship, current)?;
        let delivered = self
            .simulation
            .available_messages(txn, ship.system_id, current, false)?
            .into_iter()
            .map(|item| item.message.message_id)
            .collect::<HashSet<_>>();
        state.opportunities.retain(|offer| {
            offer.state != crate::careers::OpportunityState::Offered
                || offer.order_message_id == 0
                || delivered.contains(&offer.order_message_id)
        });
        state.warrants.retain(|warrant| {
            delivered.contains(&warrant.message_id)
                || (warrant.resolution_message_id != 0
                    && delivered.contains(&warrant.resolution_message_id))
        });
        let rank = if state.mode == crate::careers::CombatCareerMode::Navy {
            crate::careers::naval_grade_by_index(state.naval_grade_index)
                .name
                .to_owned()
        } else {
            match state.mode {
                crate::careers::CombatCareerMode::Privateer => "Commissioned captain",
                crate::careers::CombatCareerMode::Pirate => "Independent raider",
                _ => "Independent captain",
            }
            .into()
        };
        let available = self
            .simulation
            .available_messages(txn, ship.system_id, current, false)?;
        let active = state
            .warrants
            .iter()
            .filter(|warrant| {
                crate::careers::warrant_is_enforceable(
                    warrant,
                    available
                        .iter()
                        .any(|message| message.message.message_id == warrant.message_id),
                    available
                        .iter()
                        .any(|message| message.message.message_id == warrant.resolution_message_id),
                )
            })
            .count();
        let known_warrants = self.known_warrants_in(txn, identity, &ship, current, &delivered)?;
        Ok(crate::wire::CombatCareerSnapshot {
            monthly_salary_credits: if state.mode == crate::careers::CombatCareerMode::Navy {
                crate::careers::naval_salary_for_grade(state.naval_grade_index)
            } else {
                0
            },
            rank,
            state,
            local_enforcement_summary: if active == 0 {
                "No warrant concerning this command has reached local enforcement.".into()
            } else {
                format!(
                    "Local enforcement has received {active} active warrant(s) concerning this command."
                )
            },
            system_contacts,
            local_contacts,
            interception_watch: self.interception_watch_status_in(txn, ship.ship_id)?,
            known_warrants,
        })
    }

    fn known_warrants_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship: &ShipRecord,
        _current: u64,
        delivered: &HashSet<u64>,
    ) -> Result<Vec<crate::wire::KnownWarrant>, StoreError> {
        let mut result = Vec::new();
        for entry in self.warrant_dossiers.iter(txn)? {
            let (_, encoded) = entry?;
            let dossier = decode_warrant_dossier(encoded)?;
            if dossier.custody == WarrantCustodyState::Settled
                || (!delivered.contains(&dossier.message_id)
                    && !(dossier.custody == WarrantCustodyState::HeldAboard
                        && dossier.custodian == *identity))
            {
                continue;
            }
            let custody = match dossier.custody {
                WarrantCustodyState::AtLarge => crate::wire::BountyCustodyState::AtLarge,
                WarrantCustodyState::HeldAboard => crate::wire::BountyCustodyState::HeldAboard,
                WarrantCustodyState::Settled => crate::wire::BountyCustodyState::Settled,
            };
            let locally_observed = dossier.current_system_id == ship.system_id;
            let association = if dossier.target_kind == WarrantTargetKind::Generated
                && dossier.subject_present
                && locally_observed
            {
                crate::wire::WarrantAssociationKind::ConfirmedAboard
            } else if dossier.association_confirmed {
                crate::wire::WarrantAssociationKind::ReportedAboard
            } else {
                crate::wire::WarrantAssociationKind::Historical
            };
            result.push(crate::wire::KnownWarrant {
                warrant_id: dossier.warrant_id,
                subject_person_id: dossier.subject_person_id,
                subject_name: dossier.subject_name,
                subject_role: dossier.subject_role,
                accusation: dossier.accusation,
                bounty_credits: dossier.bounty_credits,
                severity: dossier.severity,
                evidence_percent: dossier.evidence_percent,
                issuing_polity_id: dossier.issuing_polity_id,
                origin_system_id: dossier.origin_system_id,
                filed_second: dossier.filed_second,
                associated_ship_id: dossier.associated_ship_id,
                associated_ship_name: dossier.associated_ship_name,
                associated_transponder: dossier.associated_transponder,
                last_known_system_id: if locally_observed {
                    dossier.current_system_id
                } else {
                    dossier.origin_system_id
                },
                association,
                custody,
                generated_target: dossier.target_kind == WarrantTargetKind::Generated,
            });
        }
        result.sort_by_key(|warrant| {
            (
                warrant.custody != crate::wire::BountyCustodyState::HeldAboard,
                std::cmp::Reverse(warrant.bounty_credits),
                warrant.warrant_id,
            )
        });
        Ok(result)
    }

    fn record_player_warrant_dossier_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        ship: &ShipRecord,
        warrant: &crate::careers::WarrantRecord,
    ) -> Result<(), StoreError> {
        let player = self
            .players
            .get(txn, &encode_identity(identity))?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("warrant subject has no player record"))?;
        let person = self
            .persons
            .get(txn, &player.captain_person_id)?
            .map(decode_person_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("warrant subject captain is missing"))?;
        let mut associated_ship_ids = vec![ship.ship_id];
        if let Some(existing) = self
            .warrant_dossiers
            .get(txn, &warrant.warrant_id)?
            .map(decode_warrant_dossier)
            .transpose()?
        {
            associated_ship_ids.extend(existing.associated_ship_ids);
            associated_ship_ids.sort_unstable();
            associated_ship_ids.dedup();
        }
        let dossier = WarrantDossierRecord {
            warrant_id: warrant.warrant_id,
            message_id: warrant.message_id,
            resolution_message_id: warrant.resolution_message_id,
            issuing_polity_id: warrant.issuing_polity_id,
            origin_system_id: warrant.origin_system_id,
            filed_second: warrant.filed_second,
            subject_person_id: player.captain_person_id,
            subject_name: person.person.name,
            subject_role: "captain".into(),
            accusation: warrant.accusation.clone(),
            bounty_credits: warrant.bounty_credits,
            severity: warrant.severity,
            evidence_percent: warrant.evidence_percent,
            target_kind: WarrantTargetKind::Player,
            target_identity: identity.clone(),
            associated_ship_ids,
            associated_ship_id: ship.ship_id,
            associated_ship_name: ship.name.clone(),
            associated_transponder: crate::traffic::transponder_for_id(ship.ship_id),
            catalog_id: ship.catalog_id,
            current_system_id: ship.system_id,
            next_move_second: 0,
            association_confirmed: true,
            subject_present: true,
            concealment_skill: 0,
            custody: if matches!(
                warrant.status,
                crate::careers::WarrantStatus::Revoked | crate::careers::WarrantStatus::Satisfied
            ) {
                WarrantCustodyState::Settled
            } else {
                WarrantCustodyState::AtLarge
            },
            custodian: PlayerIdentity {
                bbs_id: 0,
                player_id: 0,
            },
            custody_ship_id: 0,
            settled_second: warrant.resolved_second,
        };
        self.warrant_dossiers
            .put(txn, &warrant.warrant_id, &encode_warrant_dossier(&dossier)?)?;
        Ok(())
    }

    fn backfill_player_warrant_dossiers_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<(), StoreError> {
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let career = self.career_state_in(txn, identity)?;
        for warrant in &career.warrants {
            if self
                .warrant_dossiers
                .get(txn, &warrant.warrant_id)?
                .is_none()
            {
                self.record_player_warrant_dossier_in(txn, identity, &ship, warrant)?;
            }
        }
        Ok(())
    }

    fn local_traffic_locus_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship: &ShipRecord,
    ) -> Result<Option<ShipLocusRecord>, StoreError> {
        if let Some(checkpoint) = self
            .checkpoints
            .get(txn, &encode_identity(identity))?
            .map(decode_checkpoint_snapshot)
            .transpose()?
            .filter(|checkpoint| !checkpoint.acknowledged)
        {
            return Ok(match checkpoint.locus {
                FlightLocus::Port {
                    system_id,
                    world_id,
                    facility_id,
                } => Some(ShipLocusRecord::Port {
                    system_id,
                    world_id,
                    facility_id,
                }),
                FlightLocus::JumpLocus { system_id } => {
                    Some(ShipLocusRecord::JumpLocus { system_id })
                }
                FlightLocus::Body { system_id, body_id } => {
                    Some(ShipLocusRecord::Body { system_id, body_id })
                }
                FlightLocus::DeepSpace { .. } => None,
            });
        }
        Ok(Self::ship_traffic_locus(ship))
    }

    fn ship_traffic_locus(ship: &ShipRecord) -> Option<ShipLocusRecord> {
        match ship.location {
            ShipLocationRecord::Docked {
                world_id,
                facility_id,
                ..
            } => Some(ShipLocusRecord::Port {
                system_id: ship.system_id,
                world_id,
                facility_id,
            }),
            ShipLocationRecord::Holding { locus, .. } => match locus {
                ShipLocusRecord::DeepSpace { .. } => None,
                _ => Some(locus),
            },
            ShipLocationRecord::InFlight(FlightLegRecord {
                origin: locus @ ShipLocusRecord::Body { .. },
                destination,
                purpose: FlightLegPurpose::ProcessFrontierFuel { .. },
                ..
            }) if locus == destination => Some(locus),
            _ => None,
        }
    }

    fn ship_traffic_attachment(ship: &ShipRecord) -> crate::traffic::TrafficAttachment {
        match ship.location {
            ShipLocationRecord::Docked { .. } => crate::traffic::TrafficAttachment::Berthed,
            ShipLocationRecord::InFlight(FlightLegRecord {
                purpose: FlightLegPurpose::ProcessFrontierFuel { .. },
                ..
            }) if ship.activity.as_ref().is_some_and(|activity| {
                matches!(activity.kind, ShipActivityKind::WildernessWater { .. })
            }) =>
            {
                crate::traffic::TrafficAttachment::Landed
            }
            _ => crate::traffic::TrafficAttachment::Spaceborne,
        }
    }

    fn interception_watch_in(
        &self,
        txn: &heed::RoTxn<'_>,
        hunter_ship_id: u64,
    ) -> Result<Option<InterceptionWatchRecord>, StoreError> {
        self.interception_watches
            .get(txn, &hunter_ship_id)?
            .map(decode_interception_watch)
            .transpose()
    }

    fn interception_watch_status_in(
        &self,
        txn: &heed::RoTxn<'_>,
        hunter_ship_id: u64,
    ) -> Result<Option<crate::wire::InterceptionWatchStatus>, StoreError> {
        Ok(self
            .interception_watch_in(txn, hunter_ship_id)?
            .map(|watch| {
                let (filter, target_contact_id, target_catalog_id) = match watch.filter {
                    InterceptionWatchFilter::NamedVessel { ship_id } => (
                        crate::wire::InterceptionWatchFilterKind::NamedVessel,
                        ship_id,
                        0,
                    ),
                    InterceptionWatchFilter::CraftClass { catalog_id } => (
                        crate::wire::InterceptionWatchFilterKind::CraftClass,
                        0,
                        catalog_id,
                    ),
                    InterceptionWatchFilter::AllCraft => {
                        (crate::wire::InterceptionWatchFilterKind::AllCraft, 0, 0)
                    }
                };
                crate::wire::InterceptionWatchStatus {
                    started_second: watch.started_second,
                    target_contact_id,
                    target_catalog_id,
                    target_ship_name: watch.target_ship_name,
                    filter,
                    locus: flight_locus_status(watch.locus),
                    purpose: watch.purpose,
                }
            }))
    }

    fn local_traffic_contacts_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship: &ShipRecord,
        current: u64,
    ) -> Result<Vec<crate::traffic::TrafficContact>, StoreError> {
        let Some(locus) = self.local_traffic_locus_in(txn, identity, ship)? else {
            return Ok(Vec::new());
        };
        if ship.system_id == 0 || locus.system_id() != ship.system_id {
            return Ok(Vec::new());
        }
        let system = self
            .simulation
            .systems(txn)?
            .into_iter()
            .find(|system| system.system_id == ship.system_id)
            .ok_or(StoreError::MissingTrafficSimulationSystem(ship.system_id))?;
        let stellar = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("local-traffic system is missing"))?;
        let celestial = derive_celestial_system(&stellar)?;
        let secondary_bodies = celestial
            .bodies
            .iter()
            .filter(|body| !body.is_primary_world)
            .map(|body| body.local_id)
            .collect::<Vec<_>>();
        let mut contacts = crate::traffic::snapshot(&system, current)?;
        contacts.retain(|contact| {
            let present = match contact.movement {
                crate::traffic::TrafficMovementKind::Arrival => contact.edge_second <= current,
                crate::traffic::TrafficMovementKind::Departure => contact.edge_second >= current,
                crate::traffic::TrafficMovementKind::Present => true,
            };
            if !present {
                return false;
            }
            let allocation =
                crate::ship_condition::mix64(contact.contact_id ^ system.system_id.rotate_left(23));
            let bucket = allocation % 100;
            match locus {
                ShipLocusRecord::Port { .. } => bucket < 55,
                ShipLocusRecord::JumpLocus { .. } => (55..85).contains(&bucket),
                ShipLocusRecord::Body { body_id, .. } => {
                    bucket >= 85
                        && !secondary_bodies.is_empty()
                        && secondary_bodies
                            [allocation.rotate_left(19) as usize % secondary_bodies.len()]
                            == body_id
                }
                ShipLocusRecord::DeepSpace { .. } => false,
            }
        });
        contacts.extend(self.player_traffic_contacts_in(txn, ship, Some(&locus), current)?);
        if matches!(locus, ShipLocusRecord::Port { .. }) {
            contacts.extend(self.generated_warrant_contacts_in(txn, ship.system_id, current)?);
        }
        contacts.sort_by_key(|contact| (contact.edge_second, contact.contact_id));
        Ok(contacts)
    }

    fn player_traffic_contacts_in(
        &self,
        txn: &heed::RoTxn<'_>,
        observing_ship: &ShipRecord,
        required_locus: Option<&ShipLocusRecord>,
        current: u64,
    ) -> Result<Vec<crate::traffic::TrafficContact>, StoreError> {
        let catalog = creation::ship_market_catalog();
        let mut contacts = Vec::new();
        for entry in self.ships.iter(txn)? {
            let (_, encoded) = entry?;
            let candidate = decode_ship_record(encoded)?;
            if candidate.ship_id == observing_ship.ship_id
                || candidate.system_id == 0
                || candidate.system_id != observing_ship.system_id
                || matches!(
                    candidate.location,
                    ShipLocationRecord::InFlight(FlightLegRecord {
                        purpose: FlightLegPurpose::Jump { .. },
                        ..
                    })
                )
            {
                continue;
            }
            let Some(owner) = self
                .players
                .get(txn, &encode_identity(&candidate.command))?
                .map(decode_player_record)
                .transpose()?
            else {
                continue;
            };
            if !owner.managed_ship_ids.contains(&candidate.ship_id) {
                continue;
            }
            if let Some(required) = required_locus {
                let candidate_locus = if owner.ship_id == candidate.ship_id {
                    self.local_traffic_locus_in(txn, &candidate.command, &candidate)?
                } else {
                    Self::ship_traffic_locus(&candidate)
                };
                if candidate_locus.as_ref() != Some(required) {
                    continue;
                }
            }
            let design = catalog
                .iter()
                .find(|entry| entry.catalog_id == candidate.catalog_id)
                .ok_or(StoreError::Corrupt(
                    "player traffic catalog data is missing",
                ))?;
            let registry = self.bbs_configuration_in(txn, candidate.command.bbs_id)?;
            let role = match candidate.career {
                crate::wire::Career::Trader => "independent merchant",
                crate::wire::Career::Privateer => "commissioned privateer",
                crate::wire::Career::Navy => "naval vessel",
            };
            contacts.push(crate::traffic::TrafficContact {
                contact_id: candidate.ship_id,
                catalog_id: candidate.catalog_id,
                class_name: design.class_name.clone(),
                ship_name: candidate.name.clone(),
                transponder: crate::traffic::transponder_for_id(candidate.ship_id),
                operator_name: format!("{} registry", registry.settings.bbs_name),
                role: role.into(),
                displacement_millitons: design.displacement_millitons,
                origin_system_id: candidate.system_id,
                destination_system_id: candidate.system_id,
                movement: crate::traffic::TrafficMovementKind::Present,
                edge_second: current,
                resolution: crate::traffic::TrafficContactResolution::Identified,
                confidence_percent: 100,
                player_owned: true,
                online_controlled: false,
                attachment: Self::ship_traffic_attachment(&candidate),
            });
        }
        Ok(contacts)
    }

    fn observed_local_traffic_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship: &ShipRecord,
        current: u64,
    ) -> Result<Vec<crate::traffic::TrafficContact>, StoreError> {
        let electronics_dm = creation::ship_electronics_dm(ship.catalog_id).ok_or(
            StoreError::Corrupt("ship electronics catalog data is missing"),
        )?;
        let sensor_damage = ship
            .subsystems
            .iter()
            .find(|subsystem| subsystem.kind == ShipSubsystemKind::Sensors)
            .map(|subsystem| {
                subsystem
                    .sustained_hits
                    .saturating_sub(subsystem.battlefield_repair_hits)
            })
            .ok_or(StoreError::Corrupt("ship sensor subsystem is missing"))?;
        self.local_traffic_contacts_in(txn, identity, ship, current)?
            .into_iter()
            .map(|mut contact| {
                let entropy =
                    crate::ship_condition::mix64(contact.contact_id ^ ship.ship_id.rotate_left(29));
                let roll = i16::try_from(2 + entropy % 6 + entropy.rotate_left(11) % 6)
                    .expect("two dice fit in i16");
                let size_dm = match contact.displacement_millitons {
                    0..=99_999 => -1,
                    100_000..=999_999 => 0,
                    1_000_000..=4_999_999 => 1,
                    _ => 2,
                };
                let total = roll + i16::from(electronics_dm) + size_dm
                    - 2 * i16::try_from(sensor_damage).unwrap_or(i16::MAX / 2);
                if total >= 10 {
                    contact.resolution = crate::traffic::TrafficContactResolution::Identified;
                    contact.confidence_percent =
                        u8::try_from(80 + (total - 10) * 5).unwrap_or(100).min(100);
                } else if total >= 6 {
                    contact.resolution = crate::traffic::TrafficContactResolution::Approximate;
                    contact.confidence_percent =
                        u8::try_from(45 + (total - 6) * 10).unwrap_or(75).min(75);
                    contact.catalog_id = 0;
                    contact.class_name = match contact.displacement_millitons {
                        0..=99_999 => "small craft",
                        100_000..=499_999 => "small ship",
                        500_000..=1_999_999 => "medium ship",
                        _ => "large ship",
                    }
                    .into();
                    let tons = contact.displacement_millitons.div_ceil(1_000);
                    contact.displacement_millitons = tons
                        .saturating_add(50)
                        .div_euclid(100)
                        .saturating_mul(100_000);
                } else {
                    contact.resolution = crate::traffic::TrafficContactResolution::TransponderOnly;
                    contact.confidence_percent = 25;
                    contact.catalog_id = 0;
                    contact.class_name.clear();
                    contact.displacement_millitons = 0;
                }
                Ok(contact)
            })
            .collect()
    }

    fn accept_career_opportunity_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        opportunity_id: u64,
        expected_revision: u64,
    ) -> Result<RuleResult<crate::wire::CombatCareerSnapshot>, StoreError> {
        let mut career = self.career_state_in(txn, identity)?;
        if career.revision != expected_revision {
            return Ok(RuleResult::Rejected(
                "the career ledger revision is stale".into(),
            ));
        }
        let (_, mut ship) = self.player_and_ship_in(txn, identity)?;
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let delivered = self
            .simulation
            .available_messages(txn, ship.system_id, current, false)?
            .into_iter()
            .map(|item| item.message.message_id)
            .collect::<HashSet<_>>();
        let Some(index) = career
            .opportunities
            .iter()
            .position(|offer| offer.opportunity_id == opportunity_id)
        else {
            return Ok(RuleResult::Rejected(
                "that opportunity is no longer available".into(),
            ));
        };
        match career.opportunities[index].state {
            crate::careers::OpportunityState::Offered => {
                let offer = &mut career.opportunities[index];
                if current >= offer.expires_second
                    || offer.order_message_id != 0 && !delivered.contains(&offer.order_message_id)
                {
                    return Ok(RuleResult::Rejected(
                        "that opportunity is no longer available".into(),
                    ));
                }
                offer.state = crate::careers::OpportunityState::Accepted;
            }
            crate::careers::OpportunityState::Accepted => {
                let offer = &career.opportunities[index];
                if offer.objective_kind == crate::careers::ObjectiveKind::Escort
                    && offer.evidence_kind == crate::careers::ObjectiveEvidenceKind::None
                {
                    let ShipLocationRecord::Docked {
                        world_id,
                        facility_id,
                        ..
                    } = ship.location
                    else {
                        return Ok(RuleResult::Rejected(
                            "escort duty must commence from the named port traffic locus".into(),
                        ));
                    };
                    if ship.activity.is_some() {
                        return Ok(RuleResult::Rejected(
                            "the ship is already committed to another timed operation".into(),
                        ));
                    }
                    if !self
                        .local_traffic_contacts_in(txn, identity, &ship, current)?
                        .iter()
                        .any(|contact| contact.contact_id == offer.target_contact_id)
                    {
                        return Ok(RuleResult::Rejected(
                            "the protected vessel has already cleared the local traffic locus"
                                .into(),
                        ));
                    }
                    let due_second = current.saturating_add(3 * crate::combat::COMBAT_TURN_SECONDS);
                    ship.activity = Some(ShipActivityRecord {
                        activity_id: crate::ship_condition::mix64(
                            ship.ship_id ^ offer.opportunity_id ^ current,
                        ),
                        kind: ShipActivityKind::EscortDuty {
                            opportunity_id: offer.opportunity_id,
                            target_contact_id: offer.target_contact_id,
                        },
                        started_second: current,
                        due_second,
                        cost_credits: 0,
                        site: ShipActivitySite::Dockyard {
                            system_id: ship.system_id,
                            world_id,
                            facility_id,
                        },
                    });
                    ship.revision = ship.revision.saturating_add(1);
                    career.revision = career.revision.saturating_add(1);
                    self.schedule_ship_activity_in(txn, ship.ship_id, due_second)?;
                    self.ships
                        .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
                    self.put_career_state_in(txn, identity, &career)?;
                    return Ok(RuleResult::Applied(
                        self.combat_career_snapshot_in(txn, identity)?,
                    ));
                }
                if offer.evidence_kind == crate::careers::ObjectiveEvidenceKind::None {
                    return Ok(RuleResult::Rejected(
                        "the order has no reportable evidence yet".into(),
                    ));
                }
                if offer.evidence_kind == crate::careers::ObjectiveEvidenceKind::CargoSecured {
                    let captured = self
                        .ships
                        .get(txn, &offer.evidence_vessel_id)?
                        .map(decode_ship_record)
                        .transpose()?
                        .ok_or(StoreError::Corrupt("seized-cargo vessel is missing"))?;
                    if captured.system_id != offer.issued_system_id || captured.cargo.is_empty() {
                        return Ok(RuleResult::Rejected(
                            "the seized cargo is not present at the issuing authority".into(),
                        ));
                    }
                }
                let (message_id, _) = self.simulation.dispatch_message(
                    txn,
                    current,
                    ship.system_id,
                    crate::simulation::MessageClass::Private,
                    crate::simulation::MessageImportance::Important,
                    &format!("Operations report {}", opportunity_id),
                    &format!(
                        "This command files {} as evidence for order {}. Settlement remains pending until this sealed report reaches the issuing authority.",
                        crate::careers::objective_evidence_description(offer.evidence_kind),
                        opportunity_id,
                    ),
                    &[offer.issued_system_id],
                )?;
                let offer = &mut career.opportunities[index];
                offer.report_message_id = message_id;
                offer.state = crate::careers::OpportunityState::Reporting;
            }
            _ => {
                return Ok(RuleResult::Rejected(
                    "that order cannot be accepted or reported in its present state".into(),
                ));
            }
        }
        career.revision = career.revision.saturating_add(1);
        self.put_career_state_in(txn, identity, &career)?;
        Ok(RuleResult::Applied(
            self.combat_career_snapshot_in(txn, identity)?,
        ))
    }

    fn set_pirate_cruise_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        request: &crate::careers::PirateCruise,
    ) -> Result<RuleResult<crate::wire::CombatCareerSnapshot>, StoreError> {
        let mut career = self.career_state_in(txn, identity)?;
        if request.revision != career.cruise.revision
            || request
                .crew_share_percent
                .saturating_add(request.ship_fund_percent)
                > 100
            || request.active && career.crew_pressure >= 100
        {
            return Ok(RuleResult::Rejected(
                "the cruise revision, share division, or crew confidence is invalid".into(),
            ));
        }
        career.mode = crate::careers::CombatCareerMode::Pirate;
        career.cruise = request.clone();
        career.cruise.revision = career.cruise.revision.saturating_add(1);
        career.revision = career.revision.saturating_add(1);
        self.put_career_state_in(txn, identity, &career)?;
        Ok(RuleResult::Applied(
            self.combat_career_snapshot_in(txn, identity)?,
        ))
    }

    fn release_berth_for_interception_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<RuleResult<(ShipRecord, ShipLocusRecord)>, StoreError> {
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            arrived_second,
        } = ship.location
        else {
            return Ok(RuleResult::Rejected(
                "the ship is not occupying a berth".into(),
            ));
        };
        if ship.activity.is_some() {
            return Ok(RuleResult::Rejected(
                "the ship must finish its dockside activity before clearing the berth".into(),
            ));
        }
        if ship.provisions.person_days_remaining == 0 {
            return Ok(RuleResult::Rejected(
                "the ship cannot clear the berth without life-support stores".into(),
            ));
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let berth_fee = crate::ship_condition::berth_fee_credits(arrived_second, current);
        if !self.charge_operating_account_in(txn, &mut player, ship.ship_id, berth_fee)? {
            return Ok(RuleResult::Rejected(format!(
                "clearing the berth for interception requires Cr{berth_fee}; the operating account is short"
            )));
        }
        let locus = ShipLocusRecord::Port {
            system_id: ship.system_id,
            world_id,
            facility_id,
        };
        ship.location = ShipLocationRecord::Holding {
            locus,
            arrived_second: current,
        };
        ship.revision = ship.revision.saturating_add(1);
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        Ok(RuleResult::Applied((ship, locus)))
    }

    fn stable_interception_locus_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<RuleResult<(ShipRecord, ShipLocusRecord)>, StoreError> {
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        if ship.activity.is_some() {
            return Ok(RuleResult::Rejected(
                "the ship must finish or cancel its current operation before setting a watch"
                    .into(),
            ));
        }
        match ship.location {
            ShipLocationRecord::Docked { .. } => {
                self.release_berth_for_interception_in(txn, identity)
            }
            ShipLocationRecord::Holding {
                locus:
                    locus @ (ShipLocusRecord::Port { .. }
                    | ShipLocusRecord::JumpLocus { .. }
                    | ShipLocusRecord::Body { .. }),
                ..
            } => Ok(RuleResult::Applied((ship, locus))),
            ShipLocationRecord::Holding {
                locus: ShipLocusRecord::DeepSpace { .. },
                ..
            } => Ok(RuleResult::Rejected(
                "there is no modeled traffic locus at these deep-space coordinates".into(),
            )),
            ShipLocationRecord::InFlight(_) => Ok(RuleResult::Rejected(
                "the ship must reach and hold at a traffic locus before setting a watch".into(),
            )),
        }
    }

    fn put_interception_watch_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        watch: &InterceptionWatchRecord,
    ) -> Result<(), StoreError> {
        self.interception_watches.put(
            txn,
            &watch.hunter_ship_id,
            &encode_interception_watch(watch)?,
        )?;
        self.remove_contact_schedules_in(txn, watch.hunter_ship_id)?;
        self.schedule_next_interception_watch_in(txn, watch, watch.started_second)?;
        Ok(())
    }

    fn establish_named_interception_watch_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        target: &crate::traffic::TrafficContact,
        mut career: crate::careers::CareerState,
        purpose: crate::wire::InterceptionPurpose,
    ) -> Result<RuleResult<crate::wire::CombatCareerSnapshot>, StoreError> {
        let (_, current_ship) = self.player_and_ship_in(txn, identity)?;
        for entry in self.interception_watches.iter(txn)? {
            let (_, bytes) = entry?;
            let watch = decode_interception_watch(bytes)?;
            if watch.hunter_ship_id != current_ship.ship_id
                && matches!(
                    watch.filter,
                    InterceptionWatchFilter::NamedVessel { ship_id }
                        if ship_id == target.contact_id
                )
            {
                return Ok(RuleResult::Rejected(
                    "another command already has a specific departure watch on that vessel".into(),
                ));
            }
        }
        let (ship, locus) = match self.stable_interception_locus_in(txn, identity)? {
            RuleResult::Applied(value) => value,
            RuleResult::Rejected(message) => return Ok(RuleResult::Rejected(message)),
        };
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let watch = InterceptionWatchRecord {
            hunter_ship_id: ship.ship_id,
            locus,
            started_second: current,
            filter: InterceptionWatchFilter::NamedVessel {
                ship_id: target.contact_id,
            },
            target_ship_name: target.ship_name.clone(),
            purpose,
        };
        self.put_interception_watch_in(txn, &watch)?;
        career.revision = career.revision.saturating_add(1);
        self.put_career_state_in(txn, identity, &career)?;
        Ok(RuleResult::Applied(
            self.combat_career_snapshot_in(txn, identity)?,
        ))
    }

    fn set_interception_watch_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        request: &crate::wire::InterceptionWatchRequest,
    ) -> Result<RuleResult<crate::wire::CombatCareerSnapshot>, StoreError> {
        let mut career = self.career_state_in(txn, identity)?;
        let expected_revision = match *request {
            crate::wire::InterceptionWatchRequest::Cancel { expected_revision }
            | crate::wire::InterceptionWatchRequest::AllCraft {
                expected_revision, ..
            }
            | crate::wire::InterceptionWatchRequest::CraftClass {
                expected_revision, ..
            } => expected_revision,
        };
        if career.revision != expected_revision {
            return Ok(RuleResult::Rejected(
                "the career ledger revision is stale".into(),
            ));
        }
        if matches!(
            request,
            crate::wire::InterceptionWatchRequest::AllCraft {
                purpose: crate::wire::InterceptionPurpose::Arrest,
                ..
            } | crate::wire::InterceptionWatchRequest::CraftClass {
                purpose: crate::wire::InterceptionPurpose::Arrest,
                ..
            }
        ) {
            return Ok(RuleResult::Rejected(
                "an arrest watch must name the vessel associated with a locally received warrant"
                    .into(),
            ));
        }
        let (_, mut ship) = self.player_and_ship_in(txn, identity)?;
        if matches!(
            request,
            crate::wire::InterceptionWatchRequest::Cancel { .. }
        ) {
            let Some(watch) = self.interception_watch_in(txn, ship.ship_id)? else {
                return Ok(RuleResult::Rejected(
                    "the ship has no interception watch to cancel".into(),
                ));
            };
            if self.ship_combats.get(txn, &ship.ship_id)?.is_some() {
                return Ok(RuleResult::Rejected(
                    "an interception watch cannot be cancelled during combat".into(),
                ));
            }
            self.interception_watches.delete(txn, &ship.ship_id)?;
            self.remove_contact_schedules_in(txn, ship.ship_id)?;
            if let ShipLocationRecord::Holding { locus, .. } = ship.location {
                if locus == watch.locus {
                    if let ShipLocusRecord::Port {
                        world_id,
                        facility_id,
                        ..
                    } = watch.locus
                    {
                        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
                        ship.location = ShipLocationRecord::Docked {
                            world_id,
                            facility_id,
                            arrived_second: current,
                        };
                        ship.revision = ship.revision.saturating_add(1);
                        self.ships
                            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
                    }
                }
            }
        } else {
            let (ship, locus) = match self.stable_interception_locus_in(txn, identity)? {
                RuleResult::Applied(value) => value,
                RuleResult::Rejected(message) => return Ok(RuleResult::Rejected(message)),
            };
            let (filter, target_ship_name, purpose) = match *request {
                crate::wire::InterceptionWatchRequest::AllCraft { purpose, .. } => (
                    InterceptionWatchFilter::AllCraft,
                    "all craft".into(),
                    purpose,
                ),
                crate::wire::InterceptionWatchRequest::CraftClass {
                    catalog_id,
                    purpose,
                    ..
                } => {
                    let class_name = creation::ship_market_catalog()
                        .into_iter()
                        .find(|entry| entry.catalog_id == catalog_id)
                        .map(|entry| entry.class_name)
                        .ok_or(StoreError::Corrupt(
                            "interception-watch catalog class is missing",
                        ))?;
                    (
                        InterceptionWatchFilter::CraftClass { catalog_id },
                        class_name,
                        purpose,
                    )
                }
                crate::wire::InterceptionWatchRequest::Cancel { .. } => unreachable!(),
            };
            let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
            self.put_interception_watch_in(
                txn,
                &InterceptionWatchRecord {
                    hunter_ship_id: ship.ship_id,
                    locus,
                    started_second: current,
                    filter,
                    target_ship_name,
                    purpose,
                },
            )?;
        }
        career.revision = career.revision.saturating_add(1);
        self.put_career_state_in(txn, identity, &career)?;
        Ok(RuleResult::Applied(
            self.combat_career_snapshot_in(txn, identity)?,
        ))
    }

    fn trigger_interception_watches_at_locus_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        departing_ship: &mut ShipRecord,
        departure_locus: ShipLocusRecord,
        include_named_watch: bool,
    ) -> Result<Option<u64>, StoreError> {
        let mut matching = Vec::new();
        for entry in self.interception_watches.iter(txn)? {
            let (_, bytes) = entry?;
            let watch = decode_interception_watch(bytes)?;
            if watch.hunter_ship_id == departing_ship.ship_id || watch.locus != departure_locus {
                continue;
            }
            let Some(hunter) = self
                .ships
                .get(txn, &watch.hunter_ship_id)?
                .map(decode_ship_record)
                .transpose()?
            else {
                continue;
            };
            if Self::ship_traffic_locus(&hunter) != Some(watch.locus)
                || self.ship_combats.get(txn, &hunter.ship_id)?.is_some()
            {
                continue;
            }
            let matches = match watch.filter {
                InterceptionWatchFilter::NamedVessel { ship_id } => {
                    include_named_watch && ship_id == departing_ship.ship_id
                }
                InterceptionWatchFilter::CraftClass { catalog_id } => {
                    catalog_id == departing_ship.catalog_id
                }
                InterceptionWatchFilter::AllCraft => true,
            };
            if matches {
                matching.push(watch);
            }
        }
        matching.sort_by_key(|watch| {
            (
                !matches!(watch.filter, InterceptionWatchFilter::NamedVessel { .. }),
                watch.started_second,
                watch.hunter_ship_id,
            )
        });
        let Some(watch) = matching.into_iter().next() else {
            return Ok(None);
        };
        let desired_location = departing_ship.location;
        let desired_revision = departing_ship.revision;
        departing_ship.location = ShipLocationRecord::Holding {
            locus: departure_locus,
            arrived_second: get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0),
        };
        self.ships.put(
            txn,
            &departing_ship.ship_id,
            &encode_ship_record(departing_ship)?,
        )?;
        let hunter = self
            .ships
            .get(txn, &watch.hunter_ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("interception-watch hunter disappeared"))?;
        let career = self.career_state_in(txn, &hunter.command)?;
        let named_departure_watch =
            matches!(watch.filter, InterceptionWatchFilter::NamedVessel { .. });
        let combat_id = match self.engage_traffic_contact_in(
            txn,
            &hunter.command,
            departing_ship.ship_id,
            career.revision,
            watch.purpose,
        )? {
            RuleResult::Applied(InterceptionStart::Combat(snapshot)) => Some(snapshot.combat_id),
            RuleResult::Applied(InterceptionStart::Watch(_)) => {
                return Err(StoreError::Corrupt(
                    "departing vessel produced another interception watch",
                ));
            }
            RuleResult::Applied(InterceptionStart::Resolution(_)) => None,
            RuleResult::Rejected(_) => None,
        };
        if named_departure_watch {
            self.interception_watches
                .delete(txn, &watch.hunter_ship_id)?;
            self.remove_contact_schedules_in(txn, watch.hunter_ship_id)?;
        }
        let mut stored = self
            .ships
            .get(txn, &departing_ship.ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt(
                "departing interception target disappeared",
            ))?;
        stored.location = desired_location;
        stored.revision = stored.revision.max(desired_revision);
        self.ships
            .put(txn, &stored.ship_id, &encode_ship_record(&stored)?)?;
        *departing_ship = stored;
        Ok(combat_id)
    }

    fn engage_traffic_contact_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        contact_id: u64,
        expected_revision: u64,
        purpose: crate::wire::InterceptionPurpose,
    ) -> Result<RuleResult<InterceptionStart>, StoreError> {
        if self.player_phase_in(txn, identity)? == PlayerPhase::Encounter {
            return Ok(RuleResult::Rejected(
                "the command is already engaged".into(),
            ));
        }
        let (_, mut ship) = self.player_and_ship_in(txn, identity)?;
        let mut career = self.career_state_in(txn, identity)?;
        if career.revision != expected_revision {
            return Ok(RuleResult::Rejected(
                "the career ledger revision is stale".into(),
            ));
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let Some(contact) = self
            .local_traffic_contacts_in(txn, identity, &ship, current)?
            .into_iter()
            .find(|contact| contact.contact_id == contact_id)
        else {
            return Ok(RuleResult::Rejected(
                "the named traffic contact is no longer at this locus".into(),
            ));
        };
        let delivered = self
            .simulation
            .available_messages(txn, ship.system_id, current, false)?
            .into_iter()
            .map(|message| message.message.message_id)
            .collect::<HashSet<_>>();
        let arrest = purpose == crate::wire::InterceptionPurpose::Arrest;
        let arrest_dossier = if arrest {
            self.warrant_dossiers
                .iter(txn)?
                .filter_map(|entry| match entry {
                    Ok((_, encoded)) => match decode_warrant_dossier(encoded) {
                        Ok(dossier)
                            if dossier.associated_ship_id == contact_id
                                && dossier.custody == WarrantCustodyState::AtLarge
                                && delivered.contains(&dossier.message_id) =>
                        {
                            Some(Ok(dossier))
                        }
                        Ok(_) => None,
                        Err(error) => Some(Err(error)),
                    },
                    Err(error) => Some(Err(StoreError::Heed(error))),
                })
                .next()
                .transpose()?
        } else {
            None
        };
        if arrest && arrest_dossier.is_none() {
            return Ok(RuleResult::Rejected(
                "no locally received warrant names a subject associated with that vessel".into(),
            ));
        }
        if contact.attachment != crate::traffic::TrafficAttachment::Spaceborne {
            if !contact.player_owned {
                return Ok(RuleResult::Rejected(
                    "attached background traffic cannot be selected for an armed intercept".into(),
                ));
            }
            return Ok(
                match self.establish_named_interception_watch_in(
                    txn, identity, &contact, career, purpose,
                )? {
                    RuleResult::Applied(snapshot) => {
                        RuleResult::Applied(InterceptionStart::Watch(snapshot))
                    }
                    RuleResult::Rejected(message) => RuleResult::Rejected(message),
                },
            );
        }
        if matches!(ship.location, ShipLocationRecord::Docked { .. }) {
            let released = match self.release_berth_for_interception_in(txn, identity)? {
                RuleResult::Applied((released, _)) => released,
                RuleResult::Rejected(message) => return Ok(RuleResult::Rejected(message)),
            };
            ship = released;
        } else if Self::ship_traffic_attachment(&ship)
            != crate::traffic::TrafficAttachment::Spaceborne
        {
            return Ok(RuleResult::Rejected(
                "the ship must lift or undock before attempting an intercept".into(),
            ));
        }
        if ship.activity.is_some() {
            return Ok(RuleResult::Rejected(
                "the ship must finish or cancel its current operation before intercepting traffic"
                    .into(),
            ));
        }
        if self.ship_combats.get(txn, &ship.ship_id)?.is_some() {
            return Ok(RuleResult::Rejected(
                "the command is already engaged in combat".into(),
            ));
        }
        let mut player_target = if contact.player_owned {
            let Some(target) = self
                .ships
                .get(txn, &contact.contact_id)?
                .map(decode_ship_record)
                .transpose()?
            else {
                return Ok(RuleResult::Rejected(
                    "the player-owned contact is no longer present".into(),
                ));
            };
            if target.command == *identity {
                return Ok(RuleResult::Rejected(
                    "a command cannot intercept another vessel in its own fleet".into(),
                ));
            }
            if self.ship_combats.get(txn, &target.ship_id)?.is_some() {
                return Ok(RuleResult::Rejected(
                    "that vessel is already engaged in combat".into(),
                ));
            }
            Some(target)
        } else {
            None
        };
        let system = self
            .simulation
            .systems(txn)?
            .into_iter()
            .find(|system| system.system_id == ship.system_id)
            .ok_or(StoreError::MissingTrafficSimulationSystem(ship.system_id))?;
        let authorized = arrest_dossier.is_some()
            || career.opportunities.iter().any(|offer| {
                offer.state == crate::careers::OpportunityState::Accepted
                    && offer.target_contact_id == contact_id
                    && matches!(
                        offer.kind,
                        crate::careers::OpportunityKind::NavalOrder
                            | crate::careers::OpportunityKind::PrivateerCommission
                    )
            });
        let boarding_inspection = matches!(
            purpose,
            crate::wire::InterceptionPurpose::BoardingInspection
                | crate::wire::InterceptionPurpose::Arrest
        );
        let target_complies = if arrest_dossier
            .as_ref()
            .is_some_and(|dossier| dossier.target_kind == WarrantTargetKind::Generated)
        {
            true
        } else if arrest {
            let dossier = arrest_dossier.as_ref().ok_or(StoreError::Corrupt(
                "arrest authorization lost its warrant dossier",
            ))?;
            let target = player_target.as_ref().ok_or(StoreError::Corrupt(
                "player warrant is not associated with a player vessel",
            ))?;
            let subject_aboard = self
                .crew_services
                .get(txn, &dossier.subject_person_id)?
                .map(decode_crew_service)
                .transpose()?
                .is_some_and(|service| {
                    service.ship_id == target.ship_id && service_active(&service)
                });
            if !subject_aboard {
                self.flight_plans
                    .get(txn, &encode_identity(&target.command))?
                    .map(decode_flight_plan_snapshot)
                    .transpose()?
                    .is_none_or(|plan| plan.policy.comply_with_inspection)
            } else {
                let hunter_power = catalog_combat_power(ship.catalog_id).max(1);
                let target_power = catalog_combat_power(target.catalog_id).max(1);
                let estimated_victory =
                    target_power.saturating_mul(100) / hunter_power.saturating_add(target_power);
                target.combat_policy.permit_surrender
                    && estimated_victory < u64::from(target.combat_policy.minimum_victory_percent)
            }
        } else if boarding_inspection {
            if authorized {
                if let Some(target) = player_target.as_ref() {
                    self.flight_plans
                        .get(txn, &encode_identity(&target.command))?
                        .map(decode_flight_plan_snapshot)
                        .transpose()?
                        .is_none_or(|plan| plan.policy.comply_with_inspection)
                } else {
                    true
                }
            } else {
                let hunter_power = catalog_combat_power(ship.catalog_id);
                let target_power = catalog_combat_power(contact.catalog_id);
                if target_power.saturating_mul(2) >= hunter_power.saturating_mul(3) {
                    return Ok(RuleResult::Rejected(format!(
                        "{} is assessed as capable of easily destroying this picket; the boarding attempt is abandoned",
                        contact.ship_name
                    )));
                }
                let permits_surrender = player_target
                    .as_ref()
                    .is_none_or(|target| target.combat_policy.permit_surrender);
                permits_surrender
                    && hunter_power.saturating_mul(2) >= target_power.saturating_mul(3)
            }
        } else {
            false
        };
        if !authorized {
            if career.mode == crate::careers::CombatCareerMode::Independent {
                career.mode = crate::careers::CombatCareerMode::Pirate;
            }
            career.public_heat = career.public_heat.saturating_add(10);
            let stellar = self
                .systems
                .get(txn, &ship.system_id)?
                .map(decode_stellar_system)
                .transpose()?
                .ok_or(StoreError::Corrupt("combat system is missing"))?;
            let value = creation::ship_market_catalog()
                .into_iter()
                .find(|entry| entry.catalog_id == contact.catalog_id)
                .map_or(10_000_000, |entry| entry.price_credits);
            let warrant_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
            let mut warrant = crate::careers::warrant_for_unlawful_attack(
                warrant_id,
                stellar.polity_id,
                ship.system_id,
                current,
                value,
                75,
            );
            let destinations = self
                .simulation
                .systems(txn)?
                .into_iter()
                .map(|candidate| candidate.system_id)
                .collect::<Vec<_>>();
            let (message_id, _) = self.simulation.dispatch_message(
                txn,
                current,
                ship.system_id,
                crate::simulation::MessageClass::PublicService,
                crate::simulation::MessageImportance::Important,
                &format!(
                    "Warrant {warrant_id}: {} of {}",
                    if boarding_inspection {
                        "unlawful boarding demand"
                    } else {
                        "armed interception"
                    },
                    contact.transponder
                ),
                &format!(
                    "The local authority alleges that this command initiated {} against {}. Warrant {} was filed in {} on day {}.",
                    if boarding_inspection {
                        "an unauthorized boarding demand"
                    } else {
                        "an unauthorized armed interception"
                    },
                    contact.transponder,
                    warrant_id,
                    stellar.name,
                    current / crate::simulation::SECONDS_PER_DAY,
                ),
                &destinations,
            )?;
            warrant.message_id = message_id;
            warrant.status = crate::careers::WarrantStatus::Propagating;
            self.record_player_warrant_dossier_in(txn, identity, &ship, &warrant)?;
            career.warrants.push(warrant);
        }
        career.revision = career.revision.saturating_add(1);
        if arrest && target_complies {
            let mut dossier = arrest_dossier.ok_or(StoreError::Corrupt(
                "authorized arrest lost its warrant dossier",
            ))?;
            let mut searchers = 0_u16;
            let mut best_search_skill = -3_i8;
            for entry in self.crew_services.iter(txn)? {
                let (_, encoded) = entry?;
                let service = decode_crew_service(encoded)?;
                if service.command != *identity
                    || service.ship_id != ship.ship_id
                    || !service_available_for_duty(&service, current)
                {
                    continue;
                }
                searchers = searchers.saturating_add(service.represented_positions.max(1));
                let person = self
                    .persons
                    .get(txn, &service.person_id)?
                    .map(decode_person_record)
                    .transpose()?
                    .ok_or(StoreError::Corrupt("search-party member is missing"))?;
                for rating in &person.person.skills {
                    if matches!(
                        rating.skill,
                        crate::wire::SkillId::Investigate
                            | crate::wire::SkillId::Recon
                            | crate::wire::SkillId::Streetwise
                    ) {
                        best_search_skill = best_search_skill.max(rating.level);
                    }
                }
            }
            let entropy = crate::ship_condition::mix64(
                dossier.warrant_id ^ ship.ship_id.rotate_left(19) ^ current,
            );
            let roll = (2 + entropy % 6 + entropy.rotate_left(13) % 6) as i16;
            let searcher_dm = i16::from(searchers.max(1).ilog2() as u8);
            let search_total = roll + i16::from(best_search_skill) + searcher_dm;
            let target = 7 + i16::from(dossier.concealment_skill);
            let subject_actually_aboard = if dossier.target_kind == WarrantTargetKind::Player {
                self.crew_services
                    .get(txn, &dossier.subject_person_id)?
                    .map(decode_crew_service)
                    .transpose()?
                    .is_some_and(|service| {
                        service.ship_id == contact.contact_id && service_active(&service)
                    })
            } else {
                dossier.subject_present
            };
            let found = subject_actually_aboard && search_total >= target;
            let encounter_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
            let outcome = if found {
                if dossier.target_kind == WarrantTargetKind::Player {
                    let mut target_player = self
                        .players
                        .get(txn, &encode_identity(&dossier.target_identity))?
                        .map(decode_player_record)
                        .transpose()?
                        .ok_or(StoreError::Corrupt("arrest target player is missing"))?;
                    let mut target_ship = self
                        .ships
                        .get(txn, &dossier.associated_ship_id)?
                        .map(decode_ship_record)
                        .transpose()?
                        .ok_or(StoreError::Corrupt("arrest target ship is missing"))?;
                    let replacement = self
                        .crew_services
                        .iter(txn)?
                        .filter_map(|entry| match entry {
                            Ok((_, encoded)) => match decode_crew_service(encoded) {
                                Ok(service)
                                    if service.ship_id == target_ship.ship_id
                                        && service.person_id != dossier.subject_person_id
                                        && service_active(&service) =>
                                {
                                    Some(Ok(service.person_id))
                                }
                                Ok(_) => None,
                                Err(error) => Some(Err(error)),
                            },
                            Err(error) => Some(Err(StoreError::Heed(error))),
                        })
                        .next()
                        .transpose()?;
                    if target_player.captain_person_id == dossier.subject_person_id {
                        let Some(replacement) = replacement else {
                            return Ok(RuleResult::Rejected(
                                "the wanted captain cannot surrender while no officer remains to assume command"
                                    .into(),
                            ));
                        };
                        target_player.captain_person_id = replacement;
                        target_ship.commanding_person_id = replacement;
                        target_player.fleet_revision =
                            target_player.fleet_revision.saturating_add(1);
                        target_ship.revision = target_ship.revision.saturating_add(1);
                    }
                    if let Some(encoded) =
                        self.crew_services.get(txn, &dossier.subject_person_id)?
                    {
                        let mut service = decode_crew_service(encoded)?;
                        service.availability = CrewAvailability::Detached;
                        service.service_end_second = current;
                        service.revision = service.revision.saturating_add(1);
                        self.crew_services.put(
                            txn,
                            &service.person_id,
                            &encode_crew_service(&service)?,
                        )?;
                    }
                    self.players.put(
                        txn,
                        &encode_identity(&dossier.target_identity),
                        &encode_player_record(&target_player),
                    )?;
                    self.ships.put(
                        txn,
                        &target_ship.ship_id,
                        &encode_ship_record(&target_ship)?,
                    )?;
                }
                dossier.custody = WarrantCustodyState::HeldAboard;
                dossier.custodian = identity.clone();
                dossier.custody_ship_id = ship.ship_id;
                dossier.subject_present = false;
                dossier.association_confirmed = true;
                format!(
                    "{} submits to the lawful boarding demand. A search party of {} finds {} aboard {} and takes the subject into custody (search total {} against {}).",
                    contact.ship_name,
                    searchers.max(1),
                    dossier.subject_name,
                    contact.ship_name,
                    search_total,
                    target
                )
            } else {
                format!(
                    "{} submits to search, but the party finds no reportable evidence that {} is aboard (search total {} against {}). The warrant remains active.",
                    contact.ship_name, dossier.subject_name, search_total, target
                )
            };
            self.warrant_dossiers.put(
                txn,
                &dossier.warrant_id,
                &encode_warrant_dossier(&dossier)?,
            )?;
            career.revision = career.revision.saturating_add(1);
            self.put_career_state_in(txn, identity, &career)?;
            return Ok(RuleResult::Applied(InterceptionStart::Resolution(
                EncounterResult {
                    encounter_id,
                    resolved: true,
                    terminal: false,
                    outcome,
                    turns: 0,
                    cargo_lost_millitons: 0,
                    fuel_lost_millitons: 0,
                    damage_hits: 0,
                },
            )));
        }
        if boarding_inspection && target_complies {
            let encounter_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
            let mut recorded = false;
            for opportunity in career.opportunities.iter_mut().filter(|opportunity| {
                opportunity.state == crate::careers::OpportunityState::Accepted
                    && opportunity.target_contact_id == contact.contact_id
                    && opportunity.objective_kind == crate::careers::ObjectiveKind::Inspect
            }) {
                opportunity.evidence_kind = crate::careers::ObjectiveEvidenceKind::InspectionRecord;
                opportunity.evidence_second = current;
                recorded = true;
            }
            if recorded {
                career.revision = career.revision.saturating_add(1);
            }
            self.put_career_state_in(txn, identity, &career)?;
            let outcome = if authorized {
                format!(
                    "{} heaves to. The boarding party completes and seals the ordered inspection without combat.",
                    contact.ship_name
                )
            } else {
                format!(
                    "{} heaves to rather than contest the boarding demand. The boarding is completed without combat.",
                    contact.ship_name
                )
            };
            return Ok(RuleResult::Applied(InterceptionStart::Resolution(
                EncounterResult {
                    encounter_id,
                    resolved: true,
                    terminal: false,
                    outcome,
                    turns: 0,
                    cargo_lost_millitons: 0,
                    fuel_lost_millitons: 0,
                    damage_hits: 0,
                },
            )));
        }
        manifest_ship_quirks(
            &mut ship,
            &[
                ShipQuirkKind::TurretFault,
                ShipQuirkKind::BridgeChairFault,
                ShipQuirkKind::FullSpeedVibration,
            ],
        );
        let encounter_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
        let entropy = crate::ship_condition::mix64(encounter_id ^ ship.ship_id);
        let mut player_vessel = crate::combat::materialize_vessel(
            ship.ship_id,
            1,
            ship.name.clone(),
            ship.catalog_id,
            ((entropy % 6) + ((entropy >> 8) % 6) + 2) as i16,
        )
        .map_err(|_| StoreError::Corrupt("player combat loadout is invalid"))?;
        apply_ship_damage_to_combat(&ship, &mut player_vessel);
        if let Some(mut target_ship) = player_target.take() {
            manifest_ship_quirks(
                &mut target_ship,
                &[
                    ShipQuirkKind::TurretFault,
                    ShipQuirkKind::BridgeChairFault,
                    ShipQuirkKind::FullSpeedVibration,
                ],
            );
            let target_owner = self
                .players
                .get(txn, &encode_identity(&target_ship.command))?
                .map(decode_player_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("player combat target has no owner"))?;
            let target_directly_commanded = target_owner.ship_id == target_ship.ship_id;
            if target_directly_commanded
                && self.player_phase_in(txn, &target_ship.command)? == PlayerPhase::Encounter
            {
                return Ok(RuleResult::Rejected(
                    "that captain is already resolving another encounter".into(),
                ));
            }
            let mut target_vessel = crate::combat::materialize_vessel(
                target_ship.ship_id,
                2,
                target_ship.name.clone(),
                target_ship.catalog_id,
                (((entropy >> 16) % 6) + ((entropy >> 24) % 6) + 2) as i16,
            )
            .map_err(|_| StoreError::Corrupt("player target combat loadout is invalid"))?;
            apply_ship_damage_to_combat(&target_ship, &mut target_vessel);
            let combat = crate::combat::CombatState {
                combat_id: encounter_id,
                revision: 1,
                round: 1,
                round_started_second: current,
                range: crate::combat::RangeBand::Short,
                vessels: vec![player_vessel, target_vessel],
                missiles: Vec::new(),
                boarding: Vec::new(),
                complete: false,
            };
            let shared = SharedCombatRecord {
                combat: combat.clone(),
                system_id: ship.system_id,
                authorized_attack: authorized,
                participants: vec![
                    SharedCombatParticipant {
                        identity: identity.clone(),
                        ship_id: ship.ship_id,
                        side: 1,
                        directly_commanded: true,
                        initiated: true,
                    },
                    SharedCombatParticipant {
                        identity: target_ship.command.clone(),
                        ship_id: target_ship.ship_id,
                        side: 2,
                        directly_commanded: target_directly_commanded,
                        initiated: false,
                    },
                ],
                orders: Vec::new(),
                automation_decisions: Vec::new(),
                combat_log: vec![format!(
                    "{} {} {}.",
                    ship.name,
                    if boarding_inspection {
                        "orders boarding inspection of"
                    } else {
                        "initiates armed interception of"
                    },
                    target_ship.name
                )],
                pending_interventions: self.pending_interventions_for_combat(
                    txn, &system, current, contact_id, authorized, entropy,
                )?,
            };
            let attacker_record = EncounterRecord {
                snapshot: EncounterSnapshot {
                    encounter_id,
                    revision: 1,
                    kind: EncounterKind::Hostile,
                    state: EncounterState::Resolving,
                    started_second: current,
                    next_turn_second: current
                        .saturating_add(crate::combat::COMBAT_TURN_SECONDS),
                    turn: 1,
                    contact: EncounterContact {
                        contact_id: target_ship.ship_id,
                        ship_name: target_ship.name.clone(),
                        class_name: contact.class_name.clone(),
                        transponder: contact.transponder.clone(),
                        role: contact.role.clone(),
                        range: "short".into(),
                        confidence_percent: contact.confidence_percent,
                    },
                    summary: if boarding_inspection {
                        "The intercepted captain refuses boarding. Combat begins; joint crew orders are required."
                    } else {
                        "Your command initiates an armed intercept against another captain. Joint crew orders are required."
                    }.into(),
                },
                opponent_catalog_id: target_ship.catalog_id,
                posture: Some(EncounterPosture::Fight),
                fallbacks: vec![EncounterFallback::BreakOff, EncounterFallback::Surrender],
                result: None,
                combat: None,
                player_order: None,
                automation_decision: None,
                combat_log: shared.combat_log.clone(),
                pending_interventions: Vec::new(),
            };
            self.encounters.put(
                txn,
                &encode_identity(identity),
                &encode_encounter_record(&attacker_record)?,
            )?;
            if target_directly_commanded {
                let defender_record = EncounterRecord {
                    snapshot: EncounterSnapshot {
                        encounter_id,
                        revision: 1,
                        kind: EncounterKind::Hostile,
                        state: EncounterState::Resolving,
                        started_second: current,
                        next_turn_second: current
                            .saturating_add(crate::combat::COMBAT_TURN_SECONDS),
                        turn: 1,
                        contact: EncounterContact {
                            contact_id: ship.ship_id,
                            ship_name: ship.name.clone(),
                            class_name: creation::ship_market_catalog()
                                .into_iter()
                                .find(|entry| entry.catalog_id == ship.catalog_id)
                                .map_or_else(
                                    || "Unclassified vessel".into(),
                                    |entry| entry.class_name,
                                ),
                            transponder: crate::traffic::transponder_for_id(ship.ship_id),
                            role: if boarding_inspection {
                                "boarding picket"
                            } else {
                                "armed interceptor"
                            }
                            .into(),
                            range: "short".into(),
                            confidence_percent: 100,
                        },
                        summary: format!(
                            "{} has {}. Joint crew orders are required.",
                            ship.name,
                            if boarding_inspection {
                                "ordered boarding; standing orders refused and combat has begun"
                            } else {
                                "initiated an armed intercept against your command"
                            }
                        ),
                    },
                    opponent_catalog_id: ship.catalog_id,
                    posture: Some(EncounterPosture::Fight),
                    fallbacks: vec![EncounterFallback::BreakOff, EncounterFallback::Surrender],
                    result: None,
                    combat: None,
                    player_order: None,
                    automation_decision: None,
                    combat_log: shared.combat_log.clone(),
                    pending_interventions: Vec::new(),
                };
                self.encounters.put(
                    txn,
                    &encode_identity(&target_ship.command),
                    &encode_encounter_record(&defender_record)?,
                )?;
            }
            self.shared_combats
                .put(txn, &encounter_id, &encode_shared_combat_record(&shared)?)?;
            self.ship_combats
                .put(txn, &ship.ship_id, &encounter_id.to_be_bytes())?;
            self.ship_combats
                .put(txn, &target_ship.ship_id, &encounter_id.to_be_bytes())?;
            self.ships
                .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
            self.ships.put(
                txn,
                &target_ship.ship_id,
                &encode_ship_record(&target_ship)?,
            )?;
            self.put_career_state_in(txn, identity, &career)?;
            self.schedule_shared_combat_turn_in(
                txn,
                encounter_id,
                current.saturating_add(crate::combat::COMBAT_TURN_SECONDS),
            )?;
            let default =
                crate::combat::conservative_order(&combat, ship.ship_id).map_err(|_| {
                    StoreError::Corrupt("commanded vessel is absent from shared combat")
                })?;
            let actors = self.combat_actors_in(txn, identity, ship.ship_id)?;
            return Ok(RuleResult::Applied(InterceptionStart::Combat(
                combat_snapshot(
                    &combat,
                    &ship,
                    &default,
                    actors,
                    false,
                    &shared.combat_log,
                    &[ship.ship_id, target_ship.ship_id],
                ),
            )));
        }
        let opponent_id = contact.contact_id | (1_u64 << 63);
        let opponent = crate::combat::materialize_vessel(
            opponent_id,
            2,
            contact.ship_name.clone(),
            contact.catalog_id,
            (((entropy >> 16) % 6) + ((entropy >> 24) % 6) + 2) as i16,
        )
        .map_err(|_| StoreError::Corrupt("contact combat loadout is invalid"))?;
        let combat = crate::combat::CombatState {
            combat_id: encounter_id,
            revision: 1,
            round: 1,
            round_started_second: current,
            range: crate::combat::RangeBand::Short,
            vessels: vec![player_vessel, opponent],
            missiles: Vec::new(),
            boarding: Vec::new(),
            complete: false,
        };
        let default = crate::combat::conservative_order(&combat, ship.ship_id)
            .map_err(|_| StoreError::Corrupt("commanded vessel is absent from combat"))?;
        let record = EncounterRecord {
            snapshot: EncounterSnapshot {
                encounter_id,
                revision: 1,
                kind: EncounterKind::Hostile,
                state: EncounterState::Resolving,
                started_second: current,
                next_turn_second: current.saturating_add(crate::combat::COMBAT_TURN_SECONDS),
                turn: 1,
                contact: EncounterContact {
                    contact_id: contact.contact_id,
                    ship_name: contact.ship_name,
                    class_name: contact.class_name,
                    transponder: contact.transponder,
                    role: contact.role,
                    range: "short".into(),
                    confidence_percent: 100,
                },
                summary: if boarding_inspection {
                    "The contact refuses boarding. Combat begins; joint crew orders are required."
                } else {
                    "Your command initiates an armed intercept. Joint crew orders are required."
                }
                .into(),
            },
            opponent_catalog_id: contact.catalog_id,
            posture: Some(EncounterPosture::Fight),
            fallbacks: vec![EncounterFallback::BreakOff, EncounterFallback::Surrender],
            result: None,
            combat: Some(combat.clone()),
            player_order: None,
            automation_decision: None,
            combat_log: vec![if boarding_inspection {
                "The registered traffic refuses the boarding order; the picket escalates to combat."
                    .into()
            } else {
                "The command initiates armed interception of registered traffic.".into()
            }],
            pending_interventions: self.pending_interventions_for_combat(
                txn, &system, current, contact_id, authorized, entropy,
            )?,
        };
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        self.put_career_state_in(txn, identity, &career)?;
        self.encounters.put(
            txn,
            &encode_identity(identity),
            &encode_encounter_record(&record)?,
        )?;
        self.schedule_encounter_turn_in(
            txn,
            identity,
            encounter_id,
            record.snapshot.next_turn_second,
        )?;
        let actors = self.combat_actors_in(txn, identity, ship.ship_id)?;
        Ok(RuleResult::Applied(InterceptionStart::Combat(
            combat_snapshot(
                &combat,
                &ship,
                &default,
                actors,
                false,
                &record.combat_log,
                &[ship.ship_id],
            ),
        )))
    }

    fn pending_interventions_for_combat(
        &self,
        txn: &heed::RoTxn<'_>,
        system: &SimulationSystem,
        current_second: u64,
        target_contact_id: u64,
        player_is_authorized: bool,
        _entropy: u64,
    ) -> Result<Vec<PendingCombatIntervention>, StoreError> {
        let law = self
            .systems
            .get(txn, &system.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .and_then(|stellar| self.primary_world_in(txn, &stellar).ok())
            .map_or(0, |world| world.law_level);
        let mut candidates = crate::traffic::snapshot(system, current_second)?
            .into_iter()
            .filter(|contact| contact.contact_id != target_contact_id)
            .filter(|contact| {
                let role = contact.role.to_ascii_lowercase();
                let enforcement = ["patrol", "security", "naval", "defense", "gunboat"]
                    .iter()
                    .any(|word| role.contains(word));
                let well_armed = creation::ship_combat_spec(contact.catalog_id)
                    .is_some_and(|spec| !spec.weapons.is_empty());
                enforcement || (well_armed && law >= 8)
            })
            .collect::<Vec<_>>();
        candidates.sort_by_key(|contact| {
            (
                std::cmp::Reverse(catalog_combat_power(contact.catalog_id)),
                contact.edge_second.abs_diff(current_second),
                contact.contact_id,
            )
        });
        let Some(contact) = candidates.into_iter().next() else {
            return Ok(Vec::new());
        };
        // The traffic edge is the response vessel's durable movement time.  A
        // vessel already present still needs one activation to observe the
        // refusal and complete a local intercept.
        let due_second = contact
            .edge_second
            .max(current_second.saturating_add(crate::combat::COMBAT_TURN_SECONDS));
        Ok(vec![PendingCombatIntervention {
            due_second,
            contact_id: contact.contact_id,
            catalog_id: contact.catalog_id,
            side: if player_is_authorized { 1 } else { 2 },
            ship_name: contact.ship_name,
        }])
    }

    fn dispose_managed_ship_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        player: &mut PlayerRecord,
        ship_id: u64,
    ) -> Result<(), StoreError> {
        if player.ship_id == ship_id {
            return Err(StoreError::Corrupt("cannot dispose the active command"));
        }
        let Some(index) = player
            .managed_ship_ids
            .iter()
            .position(|managed_id| *managed_id == ship_id)
        else {
            return Err(StoreError::Corrupt("disposed prize is absent from fleet"));
        };
        if self
            .crew_services
            .iter(txn)?
            .filter_map(Result::ok)
            .map(|(_, value)| decode_crew_service(value))
            .collect::<Result<Vec<_>, _>>()?
            .iter()
            .any(|service| service.ship_id == ship_id)
        {
            return Err(StoreError::Corrupt(
                "cannot dispose a prize while crew remain assigned",
            ));
        }
        let stale = self
            .ship_condition_events
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((key, value)) => match decode_scheduled_object(key, value) {
                    Ok((_, _, object_id)) if object_id == ship_id => Some(Ok(key.to_vec())),
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for key in stale {
            self.ship_condition_events.delete(txn, &key)?;
        }
        player.managed_ship_ids.remove(index);
        player.fleet_revision = player.fleet_revision.saturating_add(1);
        self.finances.delete(txn, &ship_finance_key(ship_id))?;
        self.ships.delete(txn, &ship_id)?;
        Ok(())
    }

    fn settle_prize_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        prize_id: u64,
        expected_revision: u64,
        method: crate::wire::PrizeSettlementMethod,
    ) -> Result<RuleResult<crate::wire::CombatCareerSnapshot>, StoreError> {
        let (mut player, ship) = self.player_and_ship_in(txn, identity)?;
        let mut career = self.career_state_in(txn, identity)?;
        if career.revision != expected_revision {
            return Ok(RuleResult::Rejected(
                "the career ledger revision is stale".into(),
            ));
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let mode = career.mode;
        let crew_share_percent = career.cruise.crew_share_percent;
        let Some(prize_index) = career
            .prizes
            .iter()
            .position(|prize| prize.prize_id == prize_id)
        else {
            return Ok(RuleResult::Rejected(
                "that prize is not held by this command".into(),
            ));
        };
        let captured_ship_id = career.prizes[prize_index].captured_vessel_id;
        let captured_person_ids = career.prizes[prize_index].captured_person_ids.clone();
        if matches!(
            method,
            crate::wire::PrizeSettlementMethod::Fence
                | crate::wire::PrizeSettlementMethod::CourtSale
        ) {
            let active_lost_command = self
                .players
                .iter(txn)?
                .map(|entry| {
                    let (_, bytes) = entry?;
                    decode_player_record(bytes)
                })
                .collect::<Result<Vec<_>, StoreError>>()?
                .into_iter()
                .any(|candidate| candidate.ship_id == captured_ship_id);
            if active_lost_command {
                return Ok(RuleResult::Rejected(
                    "the captured command cannot be disposed of before parole and recovery conclude"
                        .into(),
                ));
            }
        }
        let mut custody_transferred = false;
        match method {
            crate::wire::PrizeSettlementMethod::FileClaim => {
                let prize = &mut career.prizes[prize_index];
                if !matches!(
                    mode,
                    crate::careers::CombatCareerMode::Independent
                        | crate::careers::CombatCareerMode::Navy
                        | crate::careers::CombatCareerMode::Privateer
                ) || prize.status != crate::careers::PrizeStatus::Secured
                {
                    return Ok(RuleResult::Rejected(
                        "this prize is not eligible for a lawful claim".into(),
                    ));
                }
                let systems = self.simulation.systems(txn)?;
                let polity = systems
                    .iter()
                    .find(|system| system.system_id == ship.system_id)
                    .map_or(0, |system| system.polity_id);
                let authority = systems
                    .iter()
                    .filter(|system| system.polity_id == polity)
                    .map(|system| system.system_id)
                    .min()
                    .unwrap_or(ship.system_id);
                let (message_id, _) = self.simulation.dispatch_message(
                    txn,
                    current,
                    ship.system_id,
                    crate::simulation::MessageClass::Private,
                    crate::simulation::MessageImportance::Important,
                    &format!("Prize claim {} for {}", prize.prize_id, prize.name),
                    &format!(
                        "This sealed filing asks the prize authority to adjudicate captured vessel {} under claim {}. The claimant has retained physical custody pending a mailed ruling.",
                        prize.name, prize.prize_id,
                    ),
                    &[authority],
                )?;
                prize.claim_message_id = message_id;
                prize.status = crate::careers::PrizeStatus::ClaimInTransit;
            }
            crate::wire::PrizeSettlementMethod::TakeAdvance => {
                let prize = &mut career.prizes[prize_index];
                if !matches!(
                    mode,
                    crate::careers::CombatCareerMode::Independent
                        | crate::careers::CombatCareerMode::Navy
                        | crate::careers::CombatCareerMode::Privateer
                ) || !matches!(
                    prize.status,
                    crate::careers::PrizeStatus::Secured
                        | crate::careers::PrizeStatus::ClaimInTransit
                ) || prize.advance_credits != 0
                {
                    return Ok(RuleResult::Rejected(
                        "no secured operating advance is available".into(),
                    ));
                }
                let advance = prize.settlement_credits / 2;
                prize.advance_credits = advance;
                player.credits = player.credits.saturating_add(advance);
            }
            crate::wire::PrizeSettlementMethod::Fence => {
                let prize = &mut career.prizes[prize_index];
                if mode != crate::careers::CombatCareerMode::Pirate
                    || prize.status != crate::careers::PrizeStatus::ReadyToFence
                {
                    return Ok(RuleResult::Rejected(
                        "this port cannot fence that prize".into(),
                    ));
                }
                let crew_share = prize
                    .settlement_credits
                    .saturating_mul(u64::from(crew_share_percent))
                    / 100;
                player.credits = player
                    .credits
                    .saturating_add(prize.settlement_credits.saturating_sub(crew_share));
                prize.status = crate::careers::PrizeStatus::Settled;
                career.underworld_standing = career.underworld_standing.saturating_add(1);
                career.crew_pressure = career.crew_pressure.saturating_sub(25);
                self.dispose_managed_ship_in(txn, &mut player, captured_ship_id)?;
                custody_transferred = true;
            }
            crate::wire::PrizeSettlementMethod::CourtSale => {
                let prize = &mut career.prizes[prize_index];
                if !matches!(
                    mode,
                    crate::careers::CombatCareerMode::Independent
                        | crate::careers::CombatCareerMode::Navy
                        | crate::careers::CombatCareerMode::Privateer
                ) || prize.status != crate::careers::PrizeStatus::Adjudicated
                {
                    return Ok(RuleResult::Rejected(
                        "the prize court has not released this vessel for sale".into(),
                    ));
                }
                player.credits = player.credits.saturating_add(
                    prize
                        .settlement_credits
                        .saturating_sub(prize.advance_credits),
                );
                prize.status = crate::careers::PrizeStatus::Settled;
                self.dispose_managed_ship_in(txn, &mut player, captured_ship_id)?;
                custody_transferred = true;
            }
            crate::wire::PrizeSettlementMethod::KeepPrize => {
                let prize = &mut career.prizes[prize_index];
                if mode != crate::careers::CombatCareerMode::Privateer
                    || prize.status != crate::careers::PrizeStatus::Adjudicated
                {
                    return Ok(RuleResult::Rejected(
                        "the prize court has not awarded title to this vessel".into(),
                    ));
                }
                let equity = prize
                    .settlement_credits
                    .saturating_sub(prize.advance_credits);
                let principal = prize.realizable_value_credits.saturating_sub(equity);
                let finance_key = ship_finance_key(captured_ship_id);
                let mut finance = self
                    .finances
                    .get(txn, &finance_key)?
                    .map(decode_finance_record)
                    .transpose()?
                    .ok_or(StoreError::Corrupt("prize title record is missing"))?;
                finance.title = if principal == 0 {
                    crate::wire::ShipTitleKind::OwnedClear
                } else {
                    crate::wire::ShipTitleKind::OwnedWithLien
                };
                finance.principal_credits = principal;
                finance.monthly_payment_credits = principal.div_ceil(240);
                finance.next_payment_due_second =
                    current.saturating_add(crate::ship_condition::ACCOUNTING_MONTH_SECONDS);
                self.finances
                    .put(txn, &finance_key, &encode_finance_record(&finance))?;
                player.debt_credits = player.debt_credits.saturating_add(principal);
                prize.status = crate::careers::PrizeStatus::Settled;
                custody_transferred = true;
            }
            crate::wire::PrizeSettlementMethod::LaunderRegistry => {
                let prize = &mut career.prizes[prize_index];
                if mode != crate::careers::CombatCareerMode::Pirate
                    || prize.status != crate::careers::PrizeStatus::ReadyToFence
                {
                    return Ok(RuleResult::Rejected(
                        "no underworld registry service is available for that vessel".into(),
                    ));
                }
                let laundering_cost = prize
                    .gross_value_credits
                    .saturating_sub(prize.realizable_value_credits);
                if player.credits < laundering_cost {
                    return Ok(RuleResult::Rejected(format!(
                        "the registry broker demands Cr{laundering_cost}"
                    )));
                }
                player.credits -= laundering_cost;
                let finance_key = ship_finance_key(captured_ship_id);
                let mut finance = self
                    .finances
                    .get(txn, &finance_key)?
                    .map(decode_finance_record)
                    .transpose()?
                    .ok_or(StoreError::Corrupt("captured title record is missing"))?;
                finance.title = crate::wire::ShipTitleKind::OwnedClear;
                self.finances
                    .put(txn, &finance_key, &encode_finance_record(&finance))?;
                prize.status = crate::careers::PrizeStatus::Settled;
                career.underworld_standing = career.underworld_standing.saturating_add(2);
                custody_transferred = true;
            }
        }
        if custody_transferred {
            for person_id in captured_person_ids {
                self.crew_services.delete(txn, &person_id)?;
                self.persons.delete(txn, &person_id)?;
            }
            career.prizes[prize_index].captured_person_ids.clear();
        }
        career.revision = career.revision.saturating_add(1);
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        self.put_career_state_in(txn, identity, &career)?;
        Ok(RuleResult::Applied(
            self.combat_career_snapshot_in(txn, identity)?,
        ))
    }

    fn settle_warrant_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        warrant_id: u64,
        expected_revision: u64,
    ) -> Result<RuleResult<crate::wire::CombatCareerSnapshot>, StoreError> {
        let (mut player, ship) = self.player_and_ship_in(txn, identity)?;
        let mut career = self.career_state_in(txn, identity)?;
        if career.revision != expected_revision {
            return Ok(RuleResult::Rejected(
                "the career ledger revision is stale".into(),
            ));
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let available = self
            .simulation
            .available_messages(txn, ship.system_id, current, false)?
            .into_iter()
            .map(|item| item.message.message_id)
            .collect::<HashSet<_>>();
        let warrant_index = career
            .warrants
            .iter()
            .position(|warrant| warrant.warrant_id == warrant_id);
        if warrant_index.is_none() {
            let Some(encoded) = self.warrant_dossiers.get(txn, &warrant_id)? else {
                return Ok(RuleResult::Rejected(
                    "that warrant is not in this ledger".into(),
                ));
            };
            let mut dossier = decode_warrant_dossier(encoded)?;
            if dossier.custody != WarrantCustodyState::HeldAboard
                || dossier.custodian != *identity
                || dossier.custody_ship_id != ship.ship_id
            {
                return Ok(RuleResult::Rejected(
                    "this command does not hold the named subject in custody".into(),
                ));
            }
            let ShipLocationRecord::Docked { facility_id, .. } = ship.location else {
                return Ok(RuleResult::Rejected(
                    "a prisoner must be delivered to a port authority while docked".into(),
                ));
            };
            let authority = self
                .facilities
                .get(txn, &facility_id)?
                .map(decode_facility)
                .transpose()?
                .is_some_and(|facility| facility.authority_office);
            if !authority {
                return Ok(RuleResult::Rejected(
                    "this port has no authority office able to receive a prisoner".into(),
                ));
            }
            let destinations = self
                .simulation
                .systems(txn)?
                .into_iter()
                .map(|system| system.system_id)
                .collect::<Vec<_>>();
            let (resolution_message_id, _) = self.simulation.dispatch_message(
                txn,
                current,
                ship.system_id,
                crate::simulation::MessageClass::PublicService,
                crate::simulation::MessageImportance::Important,
                &format!("Warrant {warrant_id}: subject delivered"),
                &format!(
                    "The authority at system {} records lawful delivery of {} under warrant {} and payment of the Cr{} bounty.",
                    ship.system_id, dossier.subject_name, warrant_id, dossier.bounty_credits
                ),
                &destinations,
            )?;
            player.credits = player.credits.saturating_add(dossier.bounty_credits);
            dossier.custody = WarrantCustodyState::Settled;
            dossier.resolution_message_id = resolution_message_id;
            dossier.settled_second = current;
            self.warrant_dossiers
                .put(txn, &warrant_id, &encode_warrant_dossier(&dossier)?)?;
            career.revision = career.revision.saturating_add(1);
            self.players.put(
                txn,
                &encode_identity(identity),
                &encode_player_record(&player),
            )?;
            self.put_career_state_in(txn, identity, &career)?;
            return Ok(RuleResult::Applied(
                self.combat_career_snapshot_in(txn, identity)?,
            ));
        }
        let warrant_index = warrant_index.expect("checked above");
        let warrant = &career.warrants[warrant_index];
        if !available.contains(&warrant.message_id)
            || matches!(
                warrant.status,
                crate::careers::WarrantStatus::Revoked | crate::careers::WarrantStatus::Satisfied
            )
        {
            return Ok(RuleResult::Rejected(
                "that warrant cannot be settled through local authorities".into(),
            ));
        }
        let assessment = (warrant.bounty_credits / 2).max(1);
        if player.credits < assessment {
            return Ok(RuleResult::Rejected(format!(
                "local court requires Cr{assessment} in assessment and bond"
            )));
        }
        player.credits -= assessment;
        let destinations = self
            .simulation
            .systems(txn)?
            .into_iter()
            .map(|system| system.system_id)
            .collect::<Vec<_>>();
        let (resolution_message_id, _) = self.simulation.dispatch_message(
            txn,
            current,
            ship.system_id,
            crate::simulation::MessageClass::PublicService,
            crate::simulation::MessageImportance::Important,
            &format!("Warrant {warrant_id}: satisfaction entered"),
            &format!(
                "The court at system {} records payment of Cr{assessment} in assessment and bond on warrant {warrant_id}. Authorities receiving this signed instrument are directed to end enforcement of that warrant.",
                ship.system_id,
            ),
            &destinations,
        )?;
        let warrant = &mut career.warrants[warrant_index];
        warrant.status = crate::careers::WarrantStatus::Satisfied;
        warrant.resolution_message_id = resolution_message_id;
        warrant.resolved_second = current;
        warrant.resolving_system_id = ship.system_id;
        if let Some(encoded) = self.warrant_dossiers.get(txn, &warrant_id)? {
            let mut dossier = decode_warrant_dossier(encoded)?;
            dossier.resolution_message_id = resolution_message_id;
            dossier.custody = WarrantCustodyState::Settled;
            dossier.settled_second = current;
            self.warrant_dossiers
                .put(txn, &warrant_id, &encode_warrant_dossier(&dossier)?)?;
        }
        career.revision = career.revision.saturating_add(1);
        let key = encode_identity(identity);
        if let Some(mut plan) = self
            .flight_plans
            .get(txn, &key)?
            .map(decode_flight_plan_snapshot)
            .transpose()?
        {
            if plan.state == FlightPlanState::Held && plan.suspension_reason.contains("warrant") {
                plan.state = FlightPlanState::Completed;
                plan.suspension_reason.clear();
                self.flight_plans
                    .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
            }
        }
        self.players
            .put(txn, &key, &encode_player_record(&player))?;
        self.put_career_state_in(txn, identity, &career)?;
        Ok(RuleResult::Applied(
            self.combat_career_snapshot_in(txn, identity)?,
        ))
    }

    fn set_combat_career_mode_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        requested_mode: crate::careers::CombatCareerMode,
        expected_revision: u64,
    ) -> Result<RuleResult<crate::wire::CombatCareerSnapshot>, StoreError> {
        if self.player_phase_in(txn, identity)? != PlayerPhase::Docked {
            return Ok(RuleResult::Rejected(
                "service and commission changes must be filed while docked".into(),
            ));
        }
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let mut career = self.career_state_in(txn, identity)?;
        if career.revision != expected_revision {
            return Ok(RuleResult::Rejected(
                "the career ledger revision is stale".into(),
            ));
        }
        if career.mode == requested_mode {
            return Ok(RuleResult::Rejected(
                "the requested service status is already recorded".into(),
            ));
        }

        let finance_key = ship_finance_key(ship.ship_id);
        let mut finance = self
            .finances
            .get(txn, &finance_key)?
            .map(decode_finance_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("active ship title is missing"))?;
        let stellar = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("career filing system is missing"))?;
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let available = self
            .simulation
            .available_messages(txn, ship.system_id, current, false)?
            .into_iter()
            .map(|item| item.message.message_id)
            .collect::<HashSet<_>>();
        let locally_wanted = career.warrants.iter().any(|warrant| {
            crate::careers::warrant_is_enforceable(
                warrant,
                available.contains(&warrant.message_id),
                available.contains(&warrant.resolution_message_id),
            )
        });

        match requested_mode {
            crate::careers::CombatCareerMode::Navy => {
                if finance.title != crate::wire::ShipTitleKind::InstitutionOwned {
                    return Ok(RuleResult::Rejected(
                        "naval service requires an issued command already in the fleet".into(),
                    ));
                }
                if locally_wanted {
                    return Ok(RuleResult::Rejected(
                        "local naval authorities will not accept this command while an enforceable warrant is on file"
                            .into(),
                    ));
                }
            }
            crate::careers::CombatCareerMode::Privateer => {
                if !matches!(
                    finance.title,
                    crate::wire::ShipTitleKind::OwnedWithLien
                        | crate::wire::ShipTitleKind::SponsorOwned
                        | crate::wire::ShipTitleKind::OwnedClear
                ) {
                    return Ok(RuleResult::Rejected(
                        "a privateer commission requires a privately registered vessel".into(),
                    ));
                }
                let world = self.primary_world_in(txn, &stellar)?;
                if stellar.polity_id == 0 || world.law_level < 4 {
                    return Ok(RuleResult::Rejected(
                        "no authority at this port can issue a recognized privateer commission"
                            .into(),
                    ));
                }
                if locally_wanted {
                    return Ok(RuleResult::Rejected(
                        "the prize office refuses a commission while a locally enforceable warrant remains"
                            .into(),
                    ));
                }
            }
            crate::careers::CombatCareerMode::Independent => {
                if finance.title == crate::wire::ShipTitleKind::InstitutionOwned {
                    return Ok(RuleResult::Rejected(
                        "select a private vessel before resigning an issued command".into(),
                    ));
                }
            }
            crate::careers::CombatCareerMode::Pirate => {
                if finance.title == crate::wire::ShipTitleKind::InstitutionOwned {
                    let value = creation::ship_market_catalog()
                        .into_iter()
                        .find(|entry| entry.catalog_id == ship.catalog_id)
                        .map_or(10_000_000, |entry| entry.price_credits);
                    let warrant_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
                    let mut warrant = crate::careers::warrant_for_unlawful_attack(
                        warrant_id,
                        stellar.polity_id,
                        ship.system_id,
                        current,
                        value,
                        100,
                    );
                    warrant.accusation =
                        format!("mutiny and theft of the institution vessel {}", ship.name);
                    let destinations = self
                        .simulation
                        .systems(txn)?
                        .into_iter()
                        .map(|system| system.system_id)
                        .collect::<Vec<_>>();
                    let (message_id, _) = self.simulation.dispatch_message(
                        txn,
                        current,
                        ship.system_id,
                        crate::simulation::MessageClass::PublicService,
                        crate::simulation::MessageImportance::Headline,
                        &format!("Naval warrant {warrant_id}: mutiny aboard {}", ship.name),
                        &format!(
                            "The Admiralty reports the unlawful seizure of {} and has issued warrant {warrant_id} against its former command.",
                            ship.name,
                        ),
                        &destinations,
                    )?;
                    warrant.message_id = message_id;
                    warrant.status = crate::careers::WarrantStatus::Propagating;
                    self.record_player_warrant_dossier_in(txn, identity, &ship, &warrant)?;
                    career.warrants.push(warrant);
                    career.public_heat = career.public_heat.saturating_add(50);
                    finance.title = crate::wire::ShipTitleKind::StolenRegistry;
                }
            }
        }

        career.mode = requested_mode;
        if requested_mode != crate::careers::CombatCareerMode::Pirate {
            career.cruise.active = false;
            career.cruise.revision = career.cruise.revision.saturating_add(1);
        }
        career.revision = career.revision.saturating_add(1);
        self.finances
            .put(txn, &finance_key, &encode_finance_record(&finance))?;
        self.put_career_state_in(txn, identity, &career)?;
        Ok(RuleResult::Applied(
            self.combat_career_snapshot_in(txn, identity)?,
        ))
    }

    fn declare_bankruptcy_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        successor_name: &str,
    ) -> Result<RuleResult<crate::wire::FleetSnapshot>, StoreError> {
        if self.player_phase_in(txn, identity)? != PlayerPhase::Docked {
            return Ok(RuleResult::Rejected(
                "bankruptcy may only be declared while docked".into(),
            ));
        }
        let successor_name = successor_name.trim();
        if successor_name.is_empty() || successor_name.len() > 80 {
            return Ok(RuleResult::Rejected(
                "the bankruptcy estate requires a successor name of at most 80 characters".into(),
            ));
        }
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let finance = self
            .finances
            .get(txn, &ship_finance_key(ship.ship_id))?
            .map(decode_finance_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("active ship finance record is missing"))?;
        if finance.principal_credits == 0 || !finance.in_default {
            return Ok(RuleResult::Rejected(
                "the secured account is not in irrecoverable default".into(),
            ));
        }

        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let encounter_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
        let encounter = EncounterRecord {
            snapshot: EncounterSnapshot {
                encounter_id,
                revision: 1,
                kind: EncounterKind::Inspection,
                state: EncounterState::Resolved,
                started_second: current,
                next_turn_second: current,
                turn: 0,
                contact: EncounterContact {
                    contact_id: encounter_id,
                    ship_name: "Secured-credit court".into(),
                    class_name: "commercial tribunal".into(),
                    transponder: format!("ESTATE-{encounter_id}"),
                    role: "bankruptcy receiver".into(),
                    range: "port jurisdiction".into(),
                    confidence_percent: 100,
                },
                summary: "The secured-credit court has accepted an irrecoverable bankruptcy petition."
                    .into(),
            },
            opponent_catalog_id: 0,
            posture: Some(EncounterPosture::Comply),
            fallbacks: Vec::new(),
            result: Some(EncounterResult {
                encounter_id,
                resolved: true,
                terminal: true,
                outcome: "The court records irrecoverable bankruptcy and places the estate in receivership."
                    .into(),
                turns: 0,
                cargo_lost_millitons: 0,
                fuel_lost_millitons: 0,
                damage_hits: 0,
            }),
            combat: None,
            player_order: None,
            automation_decision: None,
            combat_log: vec!["The captain surrenders the insolvent estate to its creditors.".into()],
            pending_interventions: Vec::new(),
        };
        self.encounters.put(
            txn,
            &encode_identity(identity),
            &encode_encounter_record(&encounter)?,
        )?;
        self.recover_command_in(txn, identity, successor_name)
    }

    fn abandon_player_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        confirmation: &str,
    ) -> Result<RuleResult<()>, StoreError> {
        if confirmation != "ABANDON EVERYTHING" {
            return Ok(RuleResult::Rejected(
                "permanent abandonment requires the exact confirmation phrase".into(),
            ));
        }
        let identity_key = encode_identity(identity);
        let Some(player) = self
            .players
            .get(txn, &identity_key)?
            .map(decode_player_record)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected(
                "this account has no captain to abandon".into(),
            ));
        };
        if self.player_phase_in(txn, identity)? == PlayerPhase::Encounter {
            return Ok(RuleResult::Rejected(
                "the captain cannot be abandoned while an encounter is being resolved".into(),
            ));
        }

        let owned_ships = self
            .ships
            .iter(txn)?
            .map(|entry| {
                let (_, value) = entry?;
                decode_ship_record(value)
            })
            .collect::<Result<Vec<_>, StoreError>>()?
            .into_iter()
            .filter(|ship| ship.command == *identity)
            .collect::<Vec<_>>();
        for ship in &owned_ships {
            if self.ship_combats.get(txn, &ship.ship_id)?.is_some() {
                return Ok(RuleResult::Rejected(
                    "the captain cannot be abandoned during a shared combat".into(),
                ));
            }
        }
        let owned_ship_ids = owned_ships
            .iter()
            .map(|ship| ship.ship_id)
            .collect::<Vec<_>>();
        let release_system_id = owned_ships
            .iter()
            .find(|ship| ship.ship_id == player.ship_id)
            .or_else(|| owned_ships.first())
            .map_or(0, |ship| ship.system_id);
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);

        let services = self
            .crew_services
            .iter(txn)?
            .map(|entry| {
                let (_, value) = entry?;
                decode_crew_service(value)
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        let mut person_ids = services
            .iter()
            .filter(|service| {
                service.command == *identity || owned_ship_ids.contains(&service.ship_id)
            })
            .map(|service| service.person_id)
            .collect::<Vec<_>>();
        if !person_ids.contains(&player.captain_person_id) {
            person_ids.push(player.captain_person_id);
        }

        let warrants = self
            .warrant_dossiers
            .iter(txn)?
            .map(|entry| {
                let (key, value) = entry?;
                Ok((key, decode_warrant_dossier(value)?))
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for (warrant_id, mut warrant) in warrants {
            let mut changed = false;
            if warrant.target_kind == WarrantTargetKind::Player
                && warrant.target_identity == *identity
            {
                warrant.custody = WarrantCustodyState::Settled;
                warrant.settled_second = current;
                warrant.subject_present = false;
                warrant.association_confirmed = false;
                warrant.target_identity = PlayerIdentity {
                    bbs_id: 0,
                    player_id: 0,
                };
                warrant.current_system_id = 0;
                changed = true;
            }
            if warrant.custody == WarrantCustodyState::HeldAboard && warrant.custodian == *identity
            {
                warrant.custody = WarrantCustodyState::AtLarge;
                warrant.custodian = PlayerIdentity {
                    bbs_id: 0,
                    player_id: 0,
                };
                warrant.custody_ship_id = 0;
                warrant.subject_present = true;
                warrant.current_system_id = release_system_id;
                warrant.next_move_second =
                    current.saturating_add(7 * crate::simulation::SECONDS_PER_DAY);
                changed = true;
            }
            if changed {
                self.warrant_dossiers
                    .put(txn, &warrant_id, &encode_warrant_dossier(&warrant)?)?;
            }
        }

        let unique_objects = self
            .unique_cargo
            .iter(txn)?
            .map(|entry| {
                let (key, value) = entry?;
                Ok((key, decode_unique_cargo(value)?))
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for (object_id, mut object) in unique_objects {
            if matches!(object.location, UniqueCargoLocation::PlayerShip { ship_id, .. }
                if owned_ship_ids.contains(&ship_id))
            {
                object.location = UniqueCargoLocation::Port {
                    system_id: release_system_id,
                };
                self.unique_cargo
                    .put(txn, &object_id, &encode_unique_cargo(&object)?)?;
            }
        }

        let tasks = self
            .tasks
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((key, value)) => match decode_stored_task(value) {
                    Ok(task) if task.identity == *identity => Some(Ok(key.to_vec())),
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for key in tasks {
            self.tasks.delete(txn, &key)?;
        }
        let offers = self
            .task_offers
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((key, value)) => match decode_stored_task_offer(value) {
                    Ok(offer) if offer.claimed_by.as_ref() == Some(identity) => {
                        Some(Ok(key.to_vec()))
                    }
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for key in offers {
            self.task_offers.delete(txn, &key)?;
        }

        let work = self
            .work_assignments
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((key, value)) => match decode_stored_work_assignment(value) {
                    Ok(work) if work.identity == *identity => {
                        Some(Ok((key.to_vec(), work.assignment.assignment_id)))
                    }
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        let work_ids = work.iter().map(|(_, id)| *id).collect::<Vec<_>>();
        for (key, _) in work {
            self.work_assignments.delete(txn, &key)?;
        }

        for scheduled in [
            &self.player_events,
            &self.ship_condition_events,
            &self.ship_activity_events,
            &self.contact_events,
        ] {
            let keys = scheduled
                .iter(txn)?
                .filter_map(|entry| match entry {
                    Ok((key, value)) => match decode_scheduled_object(key, value) {
                        Ok((_, _, object_id)) if owned_ship_ids.contains(&object_id) => {
                            Some(Ok(key.to_vec()))
                        }
                        Ok(_) => None,
                        Err(error) => Some(Err(error)),
                    },
                    Err(error) => Some(Err(StoreError::Heed(error))),
                })
                .collect::<Result<Vec<_>, StoreError>>()?;
            for key in keys {
                scheduled.delete(txn, &key)?;
            }
        }
        for (scheduled, object_ids) in [
            (&self.work_assignment_events, &work_ids),
            (&self.person_training_events, &person_ids),
        ] {
            let keys = scheduled
                .iter(txn)?
                .filter_map(|entry| match entry {
                    Ok((key, value)) => match decode_scheduled_object(key, value) {
                        Ok((_, _, object_id))
                            if object_ids.contains(
                                &(object_id
                                    & !(PERSON_TREATMENT_EVENT_BIT
                                        | PERSON_PRISONER_RELEASE_EVENT_BIT)),
                            ) =>
                        {
                            Some(Ok(key.to_vec()))
                        }
                        Ok(_) => None,
                        Err(error) => Some(Err(error)),
                    },
                    Err(error) => Some(Err(StoreError::Heed(error))),
                })
                .collect::<Result<Vec<_>, StoreError>>()?;
            for key in keys {
                scheduled.delete(txn, &key)?;
            }
        }
        let encounter_event_keys = self
            .encounter_events
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((key, value)) if value.len() == 17 && value[1..9] == identity_key => {
                    Some(Ok(key.to_vec()))
                }
                Ok(_) => None,
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for key in encounter_event_keys {
            self.encounter_events.delete(txn, &key)?;
        }

        let identity_databases = [
            self.market_observations,
            self.player_message_state,
            self.player_feed_cursors,
            self.player_system_mappings,
            self.insurance_policies,
        ];
        for database in identity_databases {
            let keys = database
                .iter(txn)?
                .filter_map(|entry| match entry {
                    Ok((key, _)) if key.starts_with(&identity_key) => Some(Ok(key.to_vec())),
                    Ok(_) => None,
                    Err(error) => Some(Err(StoreError::Heed(error))),
                })
                .collect::<Result<Vec<_>, StoreError>>()?;
            for key in keys {
                database.delete(txn, &key)?;
            }
        }
        let mute_keys = self
            .radio_mutes
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((key, _))
                    if key.starts_with(&identity_key)
                        || (key.len() == 16 && key[8..] == identity_key) =>
                {
                    Some(Ok(key.to_vec()))
                }
                Ok(_) => None,
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for key in mute_keys {
            self.radio_mutes.delete(txn, &key)?;
        }

        let leads = self
            .market_leads
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((key, value)) => match decode_market_lead(value) {
                    Ok(lead) if lead.identity == *identity => Some(Ok(key.to_vec())),
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for key in leads {
            self.market_leads.delete(txn, &key)?;
        }
        let recipients = self
            .private_message_recipients
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((key, value)) => match decode_private_message_recipient(value) {
                    Ok(recipient) if recipient.recipient == *identity => Some(Ok(key.to_vec())),
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for key in recipients {
            self.private_message_recipients.delete(txn, &key)?;
        }
        let claims = self
            .discovery_claims
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((key, value)) => match decode_discovery_claim(value) {
                    Ok(claim) if claim.claimant == *identity => Some(Ok(key)),
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for key in claims {
            self.discovery_claims.delete(txn, &key)?;
        }
        let directives = self
            .sysop_directives
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((key, value)) => match decode_sysop_directive(value) {
                    Ok(directive) if directive.identity == *identity => Some(Ok(key)),
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for key in directives {
            self.sysop_directives.delete(txn, &key)?;
        }

        let receptions = self
            .radio_receptions
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((key, value)) => match decode_radio_reception(value) {
                    Ok(reception) if owned_ship_ids.contains(&reception.receiving_ship_id) => {
                        Some(Ok((key.to_vec(), reception)))
                    }
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        let mut released_receptions = std::collections::HashMap::<u64, u64>::new();
        for (key, reception) in receptions {
            self.radio_receptions.delete(txn, &key)?;
            if !reception.consumed {
                *released_receptions
                    .entry(reception.transmission_id)
                    .or_default() += 1;
            }
        }
        for (transmission_id, released) in released_receptions {
            let Some(mut transmission) = self
                .radio_transmissions
                .get(txn, &transmission_id)?
                .map(decode_radio_transmission)
                .transpose()?
            else {
                return Err(StoreError::Corrupt(
                    "abandoned radio reception content is missing",
                ));
            };
            transmission.reference_count = transmission.reference_count.saturating_sub(released);
            if transmission.reference_count == 0 {
                self.radio_transmissions.delete(txn, &transmission_id)?;
            } else {
                self.radio_transmissions.put(
                    txn,
                    &transmission_id,
                    &encode_radio_transmission(&transmission)?,
                )?;
            }
        }

        for person_id in person_ids {
            self.crew_services.delete(txn, &person_id)?;
            self.persons.delete(txn, &person_id)?;
        }
        for ship_id in owned_ship_ids {
            self.ships.delete(txn, &ship_id)?;
            self.finances.delete(txn, &ship_finance_key(ship_id))?;
            self.interception_watches.delete(txn, &ship_id)?;
        }

        self.careers.delete(txn, &identity_key)?;
        self.carriage_declarations.delete(txn, &identity_key)?;
        self.radio_cooldowns.delete(txn, &identity_key)?;
        self.player_arrivals.delete(txn, &identity_key)?;
        self.flight_plans.delete(txn, &identity_key)?;
        self.checkpoints.delete(txn, &identity_key)?;
        self.encounters.delete(txn, &identity_key)?;
        self.players.delete(txn, &identity_key)?;
        Ok(RuleResult::Applied(()))
    }

    fn recover_command_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        successor_name: &str,
    ) -> Result<RuleResult<crate::wire::FleetSnapshot>, StoreError> {
        if self.player_phase_in(txn, identity)? != PlayerPhase::Terminal {
            return Ok(RuleResult::Rejected(
                "there is no unresolved command loss".into(),
            ));
        }
        let key = encode_identity(identity);
        let encounter = self
            .encounters
            .get(txn, &key)?
            .map(decode_encounter_record)
            .transpose()?
            .ok_or(StoreError::Corrupt(
                "terminal command has no encounter record",
            ))?;
        if !encounter
            .result
            .as_ref()
            .is_some_and(|result| result.terminal)
        {
            return Err(StoreError::Corrupt(
                "terminal command has no terminal encounter result",
            ));
        }
        let mut player = self
            .players
            .get(txn, &key)?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("terminal player is missing"))?;
        let lost_ship = self
            .ships
            .get(txn, &player.ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("lost command vessel is missing"))?;
        let bankruptcy = encounter
            .result
            .as_ref()
            .is_some_and(|result| result.outcome.contains("irrecoverable bankruptcy"));
        let disposition = encounter
            .combat
            .as_ref()
            .and_then(|combat| {
                combat
                    .vessels
                    .iter()
                    .find(|vessel| vessel.vessel_id == lost_ship.ship_id)
            })
            .map_or(crate::combat::VesselDisposition::Destroyed, |vessel| {
                vessel.disposition
            });
        let delay_days = if bankruptcy {
            0
        } else {
            match disposition {
                crate::combat::VesselDisposition::Captured
                | crate::combat::VesselDisposition::Surrendered => 30,
                crate::combat::VesselDisposition::Abandoned => 7,
                _ => 14,
            }
        };
        let ready_second = encounter
            .snapshot
            .next_turn_second
            .saturating_add(delay_days * crate::simulation::SECONDS_PER_DAY);
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        if current < ready_second {
            return Ok(RuleResult::Rejected(format!(
                "recovery, parole, and estate proceedings are expected after day {}",
                ready_second / crate::simulation::SECONDS_PER_DAY,
            )));
        }
        let captain = self
            .persons
            .get(txn, &player.captain_person_id)?
            .map(decode_person_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("lost command captain is missing"))?;
        let captain_replaced = person_dead(&captain) || bankruptcy;
        let successor_name = successor_name.trim();
        if captain_replaced && (successor_name.is_empty() || successor_name.len() > 80) {
            return Ok(RuleResult::Rejected(
                "the estate requires a successor name of at most 80 characters".into(),
            ));
        }
        if !captain_replaced && !successor_name.is_empty() {
            return Ok(RuleResult::Rejected(
                "the surviving captain retains this command through recovery and parole".into(),
            ));
        }

        let career = self.career_state_in(txn, identity)?;
        let (replacement_catalog_id, replacement_catalog_revision) = if bankruptcy {
            let (path, _) = self
                .creation_origin_in(txn, identity.bbs_id)?
                .ok_or(StoreError::Corrupt("player creation origin is missing"))?;
            let offer = creation::offer_summaries(path)
                .into_iter()
                .find(|offer| offer.offer_id == player.starting_offer_id)
                .ok_or(StoreError::Corrupt("starting offer is missing"))?;
            (
                offer.ship_catalog_id,
                creation::offer_catalog_revision(path, player.starting_offer_id)
                    .ok_or(StoreError::Corrupt("starting offer revision is missing"))?,
            )
        } else {
            (lost_ship.catalog_id, lost_ship.catalog_revision)
        };
        let spec = creation::ship_status_spec(replacement_catalog_id).ok_or(
            StoreError::Corrupt("replacement ship catalog data is missing"),
        )?;
        let catalog = creation::ship_market_catalog()
            .into_iter()
            .find(|entry| entry.catalog_id == replacement_catalog_id)
            .ok_or(StoreError::Corrupt(
                "replacement ship market data is missing",
            ))?;
        let ship_id = take_id_range(self.meta, txn, META_NEXT_SHIP_ID, 1)?;
        let title = match career.mode {
            crate::careers::CombatCareerMode::Navy => crate::wire::ShipTitleKind::InstitutionOwned,
            crate::careers::CombatCareerMode::Pirate => crate::wire::ShipTitleKind::SponsorOwned,
            _ => crate::wire::ShipTitleKind::OwnedWithLien,
        };
        let principal = if title == crate::wire::ShipTitleKind::OwnedWithLien {
            catalog.price_credits.saturating_mul(4) / 5
        } else {
            0
        };
        if bankruptcy {
            player.credits = 0;
            player.debt_credits = principal;
        } else {
            player.debt_credits = player.debt_credits.saturating_add(principal);
        }

        let captain_person_id = if captain_replaced {
            let person_id = take_id_range(self.meta, txn, META_NEXT_PERSON_ID, 1)?;
            let characteristics = crate::wire::Characteristics {
                strength: 9,
                dexterity: 9,
                endurance: 9,
                intelligence: 9,
                education: 9,
                charisma: 9,
            };
            let skills = vec![
                crate::wire::SkillRating {
                    skill: crate::wire::SkillId::JackOfAllTrades,
                    level: 2,
                },
                crate::wire::SkillRating {
                    skill: crate::wire::SkillId::Leadership,
                    level: 1,
                },
                crate::wire::SkillRating {
                    skill: crate::wire::SkillId::PilotSpacecraft,
                    level: 0,
                },
                crate::wire::SkillRating {
                    skill: crate::wire::SkillId::Astrogation,
                    level: 0,
                },
                crate::wire::SkillRating {
                    skill: crate::wire::SkillId::EngineerJump,
                    level: 0,
                },
            ];
            let training = creation::initial_training(&skills, crate::wire::SkillId::Leadership)
                .ok_or(StoreError::Corrupt("successor training package is invalid"))?;
            self.persons.put(
                txn,
                &person_id,
                &encode_person_record(&PersonRecord {
                    person_id,
                    origin_bbs_id: identity.bbs_id,
                    origin_system_id: lost_ship.system_id,
                    person: crate::wire::PersonDraft {
                        name: successor_name.to_owned(),
                        characteristics,
                        skills,
                        training,
                    },
                    current_strength: characteristics.strength,
                    current_dexterity: characteristics.dexterity,
                    current_endurance: characteristics.endurance,
                    fatigue_points: 0,
                    last_injury_second: 0,
                    first_aid_applied: false,
                    last_treatment_second: current,
                    pending_treatment_effect: 0,
                    pending_treatment_due_second: 0,
                    unfed_days: 0,
                })?,
            )?;
            player.captain_person_id = person_id;
            self.schedule_person_training_in(
                txn,
                person_id,
                current.saturating_add(crate::ship_condition::SECONDS_PER_WEEK),
            )?;
            person_id
        } else {
            player.captain_person_id
        };

        let replacement = ShipRecord {
            revision: 1,
            ship_id,
            catalog_id: replacement_catalog_id,
            catalog_revision: replacement_catalog_revision,
            name: if bankruptcy {
                format!("{}'s Venture", successor_name)
            } else {
                format!("{} II", lost_ship.name)
            },
            career: lost_ship.career,
            command: identity.clone(),
            commanding_person_id: captain_person_id,
            standing_order: crate::wire::ManagedShipOrderKind::Hold,
            system_id: lost_ship.system_id,
            current_fuel_millitons: spec.fuel_capacity_millitons,
            unrefined_fuel_millitons: 0,
            fuel_capacity_bonus_millitons: 0,
            cargo_capacity_penalty_millitons: 0,
            power_fuel_last_settled_second: u64::MAX,
            power_fuel_burn_remainder: 0,
            location: ShipLocationRecord::Docked {
                world_id: lost_ship.system_id,
                facility_id: lost_ship.system_id,
                arrived_second: current,
            },
            cargo: Vec::new(),
            passengers: Vec::new(),
            ammunition: new_ship_ammunition(replacement_catalog_id),
            provisions: new_ship_provisions(&spec, current),
            subsystems: new_ship_subsystems(&spec, current)?,
            maintenance: new_ship_maintenance(&spec, current)?,
            latent_quirks: Vec::new(),
            activity: None,
            mail_custody: None,
            combat_policy: lost_ship.combat_policy.clone(),
            recovery_plan: None,
            service_ledger: Vec::new(),
        };
        self.ships
            .put(txn, &ship_id, &encode_ship_record(&replacement)?)?;
        self.finances.put(
            txn,
            &ship_finance_key(ship_id),
            &encode_finance_record(&FinanceRecord {
                title,
                restricted_credits: 0,
                original_hull_price_credits: catalog.price_credits,
                principal_credits: principal,
                monthly_payment_credits: principal.div_ceil(240),
                monthly_insurance_escrow_credits: 0,
                next_payment_due_second: current
                    .saturating_add(crate::ship_condition::ACCOUNTING_MONTH_SECONDS),
                paid_through_second: current,
                in_default: false,
                impound_order_known_locally: false,
                impound_message_id: 0,
                authorized_expense_credits: 0,
                forged_receipt_credits: 0,
                forged_receipt_count: 0,
                forged_receipt_bbs_id: 0,
                forged_receipt_player_id: 0,
            }),
        )?;
        self.schedule_ship_condition_in(
            txn,
            ship_id,
            replacement.maintenance.next_accounting_second,
        )?;

        let liquidated_ship_ids = if bankruptcy {
            player.managed_ship_ids.clone()
        } else {
            vec![lost_ship.ship_id]
        };
        let removable_ship_ids = liquidated_ship_ids
            .iter()
            .copied()
            .filter_map(|candidate_id| {
                self.ships
                    .get(txn, &candidate_id)
                    .ok()
                    .flatten()
                    .and_then(|bytes| decode_ship_record(bytes).ok())
                    .filter(|candidate| candidate.command == *identity)
                    .map(|_| candidate_id)
            })
            .collect::<Vec<_>>();
        let services = self
            .crew_services
            .iter(txn)?
            .map(|entry| {
                let (_, bytes) = entry?;
                decode_crew_service(bytes)
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for mut service in services
            .into_iter()
            .filter(|service| liquidated_ship_ids.contains(&service.ship_id))
        {
            let person = self
                .persons
                .get(txn, &service.person_id)?
                .map(decode_person_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("lost ship crew record is missing"))?;
            if bankruptcy || person_dead(&person) {
                self.crew_services.delete(txn, &service.person_id)?;
                continue;
            }
            service.ship_id = ship_id;
            service.assigned_slot_ids.clear();
            service.availability = CrewAvailability::Active;
            service.available_second = current;
            service.revision = service.revision.saturating_add(1);
            self.crew_services
                .put(txn, &service.person_id, &encode_crew_service(&service)?)?;
        }
        if captain_replaced {
            self.crew_services.put(
                txn,
                &captain_person_id,
                &encode_crew_service(&CrewServiceRecord {
                    person_id: captain_person_id,
                    ship_id,
                    slot_id: 1,
                    role: "command".into(),
                    represented_positions: 1,
                    assigned_slot_ids: vec![1],
                    service_kind: CrewServiceKind::OwnerCaptain,
                    monthly_salary_credits: 0,
                    prize_share_basis_points: 0,
                    arrears_credits: 0,
                    service_start_second: current,
                    service_end_second: 0,
                    morale: 100,
                    loyalty: 100,
                    risk_tolerance: 100,
                    availability: CrewAvailability::Active,
                    available_second: current,
                    shore_system_id: 0,
                    shore_facility_id: 0,
                    revision: 1,
                    command: identity.clone(),
                })?,
            )?;
        }

        player
            .managed_ship_ids
            .retain(|managed_id| !liquidated_ship_ids.contains(managed_id));
        player.managed_ship_ids.push(ship_id);
        player.ship_id = ship_id;
        player.fleet_revision = player.fleet_revision.saturating_add(1);
        self.players
            .put(txn, &key, &encode_player_record(&player))?;
        for liquidated_ship_id in &removable_ship_ids {
            self.ships.delete(txn, liquidated_ship_id)?;
            self.finances
                .delete(txn, &ship_finance_key(*liquidated_ship_id))?;
            self.interception_watches.delete(txn, liquidated_ship_id)?;
        }
        if bankruptcy {
            if let Some(mut unique) = self
                .unique_cargo
                .get(txn, &UNIQUE_APPLE_PIE_ID)?
                .map(decode_unique_cargo)
                .transpose()?
            {
                if matches!(
                    unique.location,
                    UniqueCargoLocation::PlayerShip { ship_id, .. }
                        if liquidated_ship_ids.contains(&ship_id)
                ) {
                    unique.location = UniqueCargoLocation::Port {
                        system_id: lost_ship.system_id,
                    };
                    self.unique_cargo.put(
                        txn,
                        &unique.object_id,
                        &encode_unique_cargo(&unique)?,
                    )?;
                }
            }
        }
        for scheduled in [
            &self.player_events,
            &self.ship_condition_events,
            &self.ship_activity_events,
            &self.contact_events,
        ] {
            let stale_events = scheduled
                .iter(txn)?
                .filter_map(|entry| match entry {
                    Ok((event_key, bytes)) => match decode_scheduled_object(event_key, bytes) {
                        Ok((_, _, id)) if removable_ship_ids.contains(&id) => {
                            Some(Ok(event_key.to_vec()))
                        }
                        Ok(_) => None,
                        Err(error) => Some(Err(error)),
                    },
                    Err(error) => Some(Err(StoreError::Heed(error))),
                })
                .collect::<Result<Vec<_>, StoreError>>()?;
            for event_key in stale_events {
                scheduled.delete(txn, &event_key)?;
            }
        }
        self.flight_plans.delete(txn, &key)?;
        self.checkpoints.delete(txn, &key)?;
        self.encounters.delete(txn, &key)?;
        self.simulation.dispatch_message(
            txn,
            current,
            lost_ship.system_id,
            crate::simulation::MessageClass::Private,
            crate::simulation::MessageImportance::Important,
            if captain_replaced {
                "Estate succession and replacement command"
            } else {
                "Recovery and replacement command"
            },
            if bankruptcy {
                "The insolvent estate has been liquidated. Its recorded successor retains the career and legal ledger and begins again with a financed starting command."
            } else if captain_replaced {
                "The estate is settled, the recorded successor assumes the surviving career and legal ledger, and a replacement command is available at the primary berth."
            } else {
                "Recovery, parole, or rescue is complete. The same captain retains the career and legal ledger, and a replacement command is available at the primary berth."
            },
            &[lost_ship.system_id],
        )?;
        Ok(RuleResult::Applied(self.fleet_snapshot_in(txn, identity)?))
    }

    fn process_encounter_turn_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        due_second: u64,
        identity: &PlayerIdentity,
        encounter_id: u64,
    ) -> Result<(), StoreError> {
        let key = encode_identity(identity);
        let Some(mut record) = self
            .encounters
            .get(txn, &key)?
            .map(decode_encounter_record)
            .transpose()?
        else {
            return Err(StoreError::Corrupt("scheduled encounter is missing"));
        };
        if record.snapshot.encounter_id != encounter_id
            || record.snapshot.state != EncounterState::Resolving
            || record.snapshot.next_turn_second != due_second
        {
            return Err(StoreError::Corrupt(
                "encounter turn disagrees with encounter state",
            ));
        }
        let mut career = self.career_state_in(txn, identity)?;
        if let Some(combat) = record.combat.clone() {
            let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
            let player_order = if let Some(order) = record.player_order.take() {
                order
            } else {
                let mut decision =
                    crate::combat::risk_directed_order(&combat, ship.ship_id, &ship.combat_policy)
                        .map_err(|_| StoreError::Corrupt("offline tactical controller failed"))?;
                decision.order =
                    self.staff_automated_order_in(txn, identity, &ship, &combat, &decision.order)?;
                record.automation_decision = Some(decision.clone());
                decision.order
            };
            let mut orders = vec![player_order];
            for vessel in combat.vessels.iter().filter(|vessel| {
                vessel.vessel_id != ship.ship_id
                    && vessel.disposition == crate::combat::VesselDisposition::Active
            }) {
                let decision = crate::combat::risk_directed_order(
                    &combat,
                    vessel.vessel_id,
                    &crate::combat::AutomationPolicy {
                        objective: if matches!(
                            record.snapshot.kind,
                            EncounterKind::Inspection | EncounterKind::Military
                        ) {
                            crate::combat::Objective::Withdraw
                        } else {
                            crate::combat::Objective::Defeat
                        },
                        minimum_victory_percent: if matches!(
                            record.snapshot.kind,
                            EncounterKind::Inspection | EncounterKind::Military
                        ) {
                            0
                        } else {
                            55
                        },
                        ..Default::default()
                    },
                )
                .map_err(|_| StoreError::Corrupt("contact tactical controller failed"))?;
                orders.push(decision.order);
            }
            let resolution = crate::combat::resolve_round(&combat, &orders)
                .map_err(|_| StoreError::Corrupt("stored combat order failed resolution"))?;
            for event in &resolution.events {
                record.combat_log.push(combat_event_text(&combat, event));
            }
            let ordered_target_id = record.snapshot.contact.contact_id | (1_u64 << 63);
            if resolution.events.iter().any(|event| {
                matches!(
                    event,
                    crate::combat::CombatEvent::InspectionCompleted { target_id, .. }
                        if *target_id == ordered_target_id
                )
            }) {
                for opportunity in career.opportunities.iter_mut().filter(|opportunity| {
                    opportunity.state == crate::careers::OpportunityState::Accepted
                        && opportunity.target_contact_id == record.snapshot.contact.contact_id
                        && opportunity.objective_kind == crate::careers::ObjectiveKind::Inspect
                }) {
                    opportunity.evidence_kind =
                        crate::careers::ObjectiveEvidenceKind::InspectionRecord;
                    opportunity.evidence_second = due_second;
                    career.revision = career.revision.saturating_add(1);
                }
            }
            let mut next_state = resolution.state;
            let mut waiting = Vec::new();
            for intervention in record.pending_interventions.drain(..) {
                if intervention.due_second <= due_second {
                    let vessel_id = intervention.contact_id | (1_u64 << 62);
                    if !next_state
                        .vessels
                        .iter()
                        .any(|vessel| vessel.vessel_id == vessel_id)
                    {
                        let vessel = crate::combat::materialize_vessel(
                            vessel_id,
                            intervention.side,
                            intervention.ship_name.clone(),
                            intervention.catalog_id,
                            7,
                        )
                        .map_err(|_| {
                            StoreError::Corrupt("intervening combat loadout is invalid")
                        })?;
                        next_state.vessels.push(vessel);
                        next_state.revision = next_state.revision.saturating_add(1);
                        next_state.complete = false;
                        record.combat_log.push(format!(
                            "{} completes its delayed intercept and joins the engagement.",
                            intervention.ship_name
                        ));
                    }
                } else {
                    waiting.push(intervention);
                }
            }
            record.pending_interventions = waiting;
            if record.combat_log.len() > 40 {
                record.combat_log.drain(..record.combat_log.len() - 40);
            }
            let player_vessel = next_state
                .vessels
                .iter()
                .find(|vessel| vessel.vessel_id == ship.ship_id)
                .ok_or(StoreError::Corrupt("commanded vessel vanished from combat"))?;
            apply_combat_damage_to_ship(player_vessel, &mut ship);
            if let Some(captured) = next_state.vessels.iter().find(|vessel| {
                vessel.side != player_vessel.side
                    && matches!(
                        vessel.disposition,
                        crate::combat::VesselDisposition::Captured
                            | crate::combat::VesselDisposition::Surrendered
                    )
            }) && !career
                .prizes
                .iter()
                .any(|prize| prize.prize_id == encounter_id)
            {
                let gross = creation::ship_market_catalog()
                    .into_iter()
                    .find(|entry| entry.catalog_id == captured.catalog_id)
                    .map_or(0, |entry| entry.price_credits);
                let maximum = (captured.displacement_millitons / 50_000).max(1) as u16;
                let condition = u8::try_from(
                    (u32::from(captured.hull_remaining + captured.structure_remaining) * 100
                        / u32::from(maximum.saturating_mul(2)))
                    .min(100),
                )
                .unwrap_or(0);
                let law = self
                    .systems
                    .get(txn, &ship.system_id)?
                    .map(decode_stellar_system)
                    .transpose()?
                    .and_then(|system| self.primary_world_in(txn, &system).ok())
                    .map_or(0, |world| world.law_level);
                let terms = crate::careers::prize_terms(
                    career.mode,
                    gross,
                    condition,
                    law,
                    crate::ship_condition::mix64(encounter_id ^ captured.vessel_id),
                );
                if terms.percent != 0 {
                    let title = if career.mode == crate::careers::CombatCareerMode::Pirate {
                        crate::wire::ShipTitleKind::StolenRegistry
                    } else {
                        crate::wire::ShipTitleKind::PrizeCustody
                    };
                    let (captured_ship_id, captured_person_ids) = self
                        .materialize_captured_ship_in(
                            txn,
                            identity,
                            &mut player,
                            &ship,
                            captured,
                            title,
                            due_second,
                        )?;
                    career.prizes.push(crate::careers::PrizeRecord {
                        prize_id: encounter_id,
                        captured_vessel_id: captured_ship_id,
                        captured_person_ids,
                        catalog_id: captured.catalog_id,
                        name: captured.name.clone(),
                        gross_value_credits: gross,
                        realizable_value_credits: terms.realizable_value_credits,
                        condition_percent: condition,
                        status: if career.mode == crate::careers::CombatCareerMode::Pirate {
                            crate::careers::PrizeStatus::ReadyToFence
                        } else {
                            crate::careers::PrizeStatus::Secured
                        },
                        secured_second: due_second,
                        claim_message_id: 0,
                        settlement_credits: terms.settlement_credits,
                        advance_credits: 0,
                    });
                    career.revision = career.revision.saturating_add(1);
                }
            }
            self.ships
                .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
            record.combat = Some(next_state.clone());
            record.snapshot.revision = record.snapshot.revision.saturating_add(1);
            record.snapshot.turn = next_state.round;
            record.snapshot.next_turn_second = next_state
                .round_started_second
                .saturating_add(crate::combat::COMBAT_TURN_SECONDS);
            let command_lost = matches!(
                player_vessel.disposition,
                crate::combat::VesselDisposition::Surrendered
                    | crate::combat::VesselDisposition::Captured
                    | crate::combat::VesselDisposition::Abandoned
                    | crate::combat::VesselDisposition::Destroyed
            );
            if next_state.complete {
                self.apply_combat_crew_hits_in(
                    txn,
                    identity,
                    ship.ship_id,
                    player_vessel.crew_hits,
                    due_second,
                    encounter_id,
                )?;
                let hostile_defeated = next_state.vessels.iter().any(|vessel| {
                    vessel.side != player_vessel.side
                        && vessel.disposition != crate::combat::VesselDisposition::Active
                });
                let contact_id = record.snapshot.contact.contact_id;
                let target_vessel_id = contact_id | (1_u64 << 63);
                let target = next_state
                    .vessels
                    .iter()
                    .find(|vessel| vessel.vessel_id == target_vessel_id);
                let captured_prize_ship_id = career
                    .prizes
                    .iter()
                    .find(|prize| prize.prize_id == encounter_id)
                    .map_or(0, |prize| prize.captured_vessel_id);
                for opportunity in career.opportunities.iter_mut().filter(|offer| {
                    offer.state == crate::careers::OpportunityState::Accepted
                        && offer.target_contact_id == contact_id
                }) {
                    let evidence = crate::careers::combat_objective_evidence(
                        opportunity.objective_kind,
                        command_lost,
                        target.map(|vessel| vessel.disposition),
                        opportunity.evidence_kind
                            == crate::careers::ObjectiveEvidenceKind::InspectionRecord,
                    );
                    let Some(evidence) = evidence else {
                        continue;
                    };
                    opportunity.evidence_kind = evidence;
                    opportunity.evidence_second = due_second;
                    if matches!(
                        evidence,
                        crate::careers::ObjectiveEvidenceKind::TargetCaptured
                            | crate::careers::ObjectiveEvidenceKind::CargoSecured
                    ) {
                        opportunity.evidence_vessel_id = captured_prize_ship_id;
                    }
                    career.revision = career.revision.saturating_add(1);
                }
                if hostile_defeated {
                    self.settle_combat_bounties_in(
                        txn,
                        identity,
                        &mut player,
                        ship.system_id,
                        due_second,
                    )?;
                }
                record.snapshot.state = EncounterState::Resolved;
                if command_lost {
                    let captor_id = next_state
                        .vessels
                        .iter()
                        .find(|vessel| {
                            vessel.side != player_vessel.side
                                && vessel.disposition != crate::combat::VesselDisposition::Destroyed
                        })
                        .map_or(0, |vessel| vessel.vessel_id);
                    self.relocate_unique_cargo_after_command_loss_in(
                        txn,
                        ship.ship_id,
                        ship.system_id,
                        player_vessel.disposition,
                        captor_id,
                    )?;
                }
                let outcome = match player_vessel.disposition {
                    crate::combat::VesselDisposition::Destroyed => {
                        "The ship breaks up under fire; command and vessel are lost."
                    }
                    crate::combat::VesselDisposition::Captured
                    | crate::combat::VesselDisposition::Surrendered => {
                        "The opposing crew takes custody of the surrendered vessel."
                    }
                    crate::combat::VesselDisposition::Abandoned => {
                        "The surviving crew abandons the vessel in escape craft."
                    }
                    crate::combat::VesselDisposition::Withdrawing => {
                        "The ship opens the range and breaks contact."
                    }
                    _ => "The hostile vessel can no longer contest the engagement.",
                }
                .to_string();
                record.snapshot.summary = outcome.clone();
                let damage_hits = ship
                    .subsystems
                    .iter()
                    .map(|subsystem| subsystem.sustained_hits)
                    .sum();
                record.result = Some(EncounterResult {
                    encounter_id,
                    resolved: true,
                    terminal: command_lost,
                    outcome,
                    turns: next_state.round.saturating_sub(1),
                    cargo_lost_millitons: 0,
                    fuel_lost_millitons: 0,
                    damage_hits,
                });
                if !command_lost {
                    begin_offline_recovery(&mut ship, due_second);
                    self.ships
                        .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
                }
                if let Some(mut plan) = self
                    .flight_plans
                    .get(txn, &key)?
                    .map(decode_flight_plan_snapshot)
                    .transpose()?
                {
                    plan.state = if command_lost {
                        FlightPlanState::Terminal
                    } else {
                        FlightPlanState::Checkpoint
                    };
                    plan.suspension_reason = if command_lost {
                        "command lost during combat".into()
                    } else {
                        "combat resolved; recovery watch set".into()
                    };
                    self.flight_plans
                        .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
                }
                self.encounters
                    .put(txn, &key, &encode_encounter_record(&record)?)?;
                if !command_lost {
                    if let Some(checkpoint) = self
                        .checkpoints
                        .get(txn, &key)?
                        .map(decode_checkpoint_snapshot)
                        .transpose()?
                    {
                        self.finish_checkpoint_arrival_in(txn, identity, &checkpoint)?;
                    }
                    self.start_post_combat_recovery_in(txn, identity)?;
                }
                self.ships
                    .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
                if let Some(watch) = self.interception_watch_in(txn, ship.ship_id)? {
                    self.remove_contact_schedules_in(txn, ship.ship_id)?;
                    if !command_lost && Self::ship_traffic_locus(&ship) == Some(watch.locus) {
                        self.schedule_next_interception_watch_in(txn, &watch, due_second)?;
                    } else {
                        self.interception_watches.delete(txn, &ship.ship_id)?;
                    }
                }
            } else {
                record.snapshot.summary = format!(
                    "Combat round {} is complete. Fresh joint orders are required.",
                    next_state.round.saturating_sub(1)
                );
                self.encounters
                    .put(txn, &key, &encode_encounter_record(&record)?)?;
                self.schedule_encounter_turn_in(
                    txn,
                    identity,
                    encounter_id,
                    record.snapshot.next_turn_second,
                )?;
            }
            self.players
                .put(txn, &key, &encode_player_record(&player))?;
            self.put_career_state_in(txn, identity, &career)?;
            return Ok(());
        }
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let skill = self
            .persons
            .get(txn, &player.captain_person_id)?
            .map(decode_person_record)
            .transpose()?
            .map(|person| {
                person
                    .person
                    .skills
                    .iter()
                    .filter(|rating| {
                        matches!(
                            rating.skill,
                            crate::wire::SkillId::PilotSpacecraft
                                | crate::wire::SkillId::TacticsNaval
                                | crate::wire::SkillId::GunnerTurrets
                        )
                    })
                    .map(|rating| rating.level)
                    .max()
                    .unwrap_or(0)
            })
            .unwrap_or(0);
        let turn = record.snapshot.turn;
        let entropy = crate::ship_condition::mix64(encounter_id ^ due_second ^ u64::from(turn));
        let die = |shift: u32| -> i16 { (((entropy >> shift) % 6) + 1) as i16 };
        let posture = record.posture.unwrap_or(EncounterPosture::Flee);
        let posture_dm = match posture {
            EncounterPosture::Fight | EncounterPosture::Board => 1,
            EncounterPosture::Flee => 2,
            EncounterPosture::Comply => 3,
            EncounterPosture::Surrender => -6,
        };
        let intervention = if turn >= 2 {
            let system = self
                .systems
                .get(txn, &ship.system_id)?
                .map(decode_stellar_system)
                .transpose()?
                .ok_or(StoreError::Corrupt("encounter system is missing"))?;
            let world = self.primary_world_in(txn, &system)?;
            world.law_level >= 6
                && crate::ship_condition::mix64(encounter_id ^ u64::from(turn) ^ ship.system_id) % 4
                    == 0
        } else {
            false
        };
        let intervention_dm = if intervention { 3 } else { 0 };
        let player_total = die(0) + die(8) + i16::from(skill.max(0)) + posture_dm + intervention_dm;
        let opponent_total = die(16)
            + die(24)
            + if record.snapshot.kind == EncounterKind::Hostile {
                2
            } else {
                0
            };
        let mut damage_hits = 0_u16;
        let mut cargo_lost = 0_u64;
        let mut terminal = false;
        let mut resolved = false;
        let mut legal_hold = false;
        let outcome;
        if record.snapshot.kind != EncounterKind::Hostile || posture == EncounterPosture::Comply {
            resolved = true;
            outcome = if record.snapshot.contact.role == "warrant enforcement"
                && posture == EncounterPosture::Comply
            {
                let system = self
                    .systems
                    .get(txn, &ship.system_id)?
                    .map(decode_stellar_system)
                    .transpose()?
                    .ok_or(StoreError::Corrupt("enforcement system is missing"))?;
                let world = self.primary_world_in(txn, &system)?;
                let Some(warrant_index) = career
                    .warrants
                    .iter()
                    .position(|warrant| warrant.warrant_id == record.snapshot.contact.contact_id)
                else {
                    return Err(StoreError::Corrupt("enforced warrant is missing"));
                };
                let warrant = &career.warrants[warrant_index];
                let corrupt_accommodation = warrant.evidence_percent < 60
                    && entropy % 16 > u64::from(world.law_level.min(15));
                let assessment = if corrupt_accommodation {
                    warrant.bounty_credits / 4
                } else {
                    warrant.bounty_credits / 2
                }
                .max(1);
                let paid = player.credits.min(assessment);
                player.credits -= paid;
                if paid == assessment {
                    let destinations = self
                        .simulation
                        .systems(txn)?
                        .into_iter()
                        .map(|system| system.system_id)
                        .collect::<Vec<_>>();
                    let warrant_id = career.warrants[warrant_index].warrant_id;
                    let (resolution_message_id, _) = self.simulation.dispatch_message(
                        txn,
                        due_second,
                        ship.system_id,
                        crate::simulation::MessageClass::PublicService,
                        crate::simulation::MessageImportance::Important,
                        &format!("Warrant {warrant_id}: satisfaction entered"),
                        &format!(
                            "Authorities at system {} record satisfaction of warrant {warrant_id}. Authorities receiving this signed instrument are directed to end enforcement of that warrant.",
                            ship.system_id,
                        ),
                        &destinations,
                    )?;
                    let warrant = &mut career.warrants[warrant_index];
                    warrant.status = crate::careers::WarrantStatus::Satisfied;
                    warrant.resolution_message_id = resolution_message_id;
                    warrant.resolved_second = due_second;
                    warrant.resolving_system_id = ship.system_id;
                    career.revision = career.revision.saturating_add(1);
                    if corrupt_accommodation {
                        format!(
                            "A local official accepts Cr{paid} and records the warrant as satisfied without a public hearing."
                        )
                    } else {
                        format!(
                            "The command posts Cr{paid} in assessment and bond; local enforcement releases the ship."
                        )
                    }
                } else {
                    legal_hold = true;
                    format!(
                        "The command can post only Cr{paid} of the Cr{assessment} assessment; the vessel remains under port hold."
                    )
                }
            } else if record.snapshot.kind == EncounterKind::Inspection
                && posture == EncounterPosture::Comply
            {
                let system = self
                    .systems
                    .get(txn, &ship.system_id)?
                    .map(decode_stellar_system)
                    .transpose()?
                    .ok_or(StoreError::Corrupt("encounter system is missing"))?;
                let world = self.primary_world_in(txn, &system)?;
                let disposition =
                    apply_customs_inspection(&world, &mut ship.cargo, &mut player.credits);
                cargo_lost = disposition.confiscated_millitons;
                if disposition.assessed_fine_credits > disposition.collected_fine_credits {
                    let unpaid = disposition
                        .assessed_fine_credits
                        .saturating_sub(disposition.collected_fine_credits);
                    let warrant_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
                    let mut warrant = crate::careers::warrant_for_unlawful_attack(
                        warrant_id,
                        system.polity_id,
                        ship.system_id,
                        due_second,
                        unpaid.saturating_mul(10),
                        100,
                    );
                    warrant.accusation = format!(
                        "unpaid customs assessment for prohibited cargo ({})",
                        disposition.commodity_names.join(", ")
                    );
                    warrant.bounty_credits = unpaid;
                    let destinations = self
                        .simulation
                        .systems(txn)?
                        .into_iter()
                        .map(|candidate| candidate.system_id)
                        .collect::<Vec<_>>();
                    let (message_id, _) = self.simulation.dispatch_message(
                        txn,
                        due_second,
                        ship.system_id,
                        crate::simulation::MessageClass::PublicService,
                        crate::simulation::MessageImportance::Important,
                        &format!("Customs warrant {warrant_id}"),
                        &format!(
                            "Customs records Cr{unpaid} unpaid after confiscating prohibited cargo from this command. Warrant {warrant_id} has been issued for the outstanding assessment."
                        ),
                        &destinations,
                    )?;
                    warrant.message_id = message_id;
                    warrant.status = crate::careers::WarrantStatus::Propagating;
                    self.record_player_warrant_dossier_in(txn, identity, &ship, &warrant)?;
                    career.warrants.push(warrant);
                    career.revision = career.revision.saturating_add(1);
                }
                if disposition.commodity_names.is_empty() {
                    "The inspection clears the manifest and releases the ship.".to_string()
                } else {
                    format!(
                        "Customs confiscates {:.3} tons ({}) and collects a Cr{} fine.",
                        cargo_lost as f64 / crate::commerce::MILLITONS_PER_TON as f64,
                        disposition.commodity_names.join(", "),
                        disposition.collected_fine_credits
                    )
                }
            } else if record.snapshot.kind == EncounterKind::Hostile {
                "The demand is satisfied and the contact releases the ship.".to_string()
            } else {
                "Identification is exchanged and both vessels continue on course.".to_string()
            };
        } else if posture == EncounterPosture::Surrender {
            resolved = true;
            terminal = true;
            outcome = "The captain surrenders the ship and crew; command is lost.".into();
        } else if player_total >= opponent_total + 2 {
            resolved = true;
            outcome = if intervention {
                "A law-enforcement contact arrives after the sensor delay and forces the aggressor to break pursuit.".into()
            } else {
                match posture {
                EncounterPosture::Flee => "The pilot breaks pursuit and clears the contact.".into(),
                EncounterPosture::Board => {
                    "The hostile vessel is disabled and secured as a prize pending adjudication."
                        .into()
                }
                _ => "Coordinated fire disables the hostile contact.".into(),
            }
            };
        } else {
            damage_hits = (1 + (opponent_total - player_total).max(0) / 3) as u16;
            let mut remaining = damage_hits;
            for kind in [ShipSubsystemKind::Hull, ShipSubsystemKind::Structure] {
                if let Some(subsystem) = ship
                    .subsystems
                    .iter_mut()
                    .find(|subsystem| subsystem.kind == kind)
                {
                    let available = subsystem
                        .maximum_hits
                        .saturating_sub(subsystem.sustained_hits);
                    let applied = remaining.min(available);
                    subsystem.sustained_hits = subsystem.sustained_hits.saturating_add(applied);
                    remaining -= applied;
                    if kind == ShipSubsystemKind::Structure
                        && subsystem.sustained_hits >= subsystem.maximum_hits
                    {
                        terminal = true;
                        resolved = true;
                    }
                }
            }
            if record.fallbacks.contains(&EncounterFallback::JettisonCargo)
                && !ship.cargo.is_empty()
            {
                let unique_before = ship
                    .cargo
                    .iter()
                    .filter(|lot| lot.title == CargoTitle::UniqueObject)
                    .map(|lot| lot.unique_object_id)
                    .collect::<Vec<_>>();
                cargo_lost = ship
                    .cargo
                    .iter()
                    .map(|lot| lot.quantity_millitons)
                    .sum::<u64>()
                    / 2;
                let mut discard = cargo_lost;
                for lot in &mut ship.cargo {
                    let taken = discard.min(lot.quantity_millitons);
                    lot.quantity_millitons -= taken;
                    discard -= taken;
                }
                ship.cargo.retain(|lot| lot.quantity_millitons != 0);
                for object_id in unique_before {
                    if !ship
                        .cargo
                        .iter()
                        .any(|lot| lot.unique_object_id == object_id)
                    {
                        if let Some(mut object) = self
                            .unique_cargo
                            .get(txn, &object_id)?
                            .map(decode_unique_cargo)
                            .transpose()?
                        {
                            object.location = UniqueCargoLocation::Wreckage {
                                system_id: ship.system_id,
                            };
                            self.unique_cargo.put(
                                txn,
                                &object_id,
                                &encode_unique_cargo(&object)?,
                            )?;
                        }
                    }
                }
                resolved = true;
            }
            if !resolved && turn >= 4 {
                resolved = true;
                terminal = record.fallbacks.contains(&EncounterFallback::Surrender);
            }
            outcome = if terminal {
                "The ship is disabled beyond recovery and command is lost.".into()
            } else if resolved {
                "Standing orders end the engagement and the hostile contact breaks away.".into()
            } else {
                format!(
                    "Turn {turn}: hostile fire scores {damage_hits} damage hit(s); another 1-kilosecond turn is queued."
                )
            };
        }
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        self.players
            .put(txn, &key, &encode_player_record(&player))?;
        self.put_career_state_in(txn, identity, &career)?;
        if resolved {
            if terminal {
                self.relocate_unique_cargo_after_command_loss_in(
                    txn,
                    ship.ship_id,
                    ship.system_id,
                    if posture == EncounterPosture::Surrender {
                        crate::combat::VesselDisposition::Surrendered
                    } else {
                        crate::combat::VesselDisposition::Destroyed
                    },
                    record.snapshot.contact.contact_id,
                )?;
            }
            record.snapshot.state = EncounterState::Resolved;
            record.snapshot.summary = outcome.clone();
            let result = EncounterResult {
                encounter_id,
                resolved: true,
                terminal,
                outcome,
                turns: turn,
                cargo_lost_millitons: cargo_lost,
                fuel_lost_millitons: 0,
                damage_hits,
            };
            record.result = Some(result);
            self.encounters
                .put(txn, &key, &encode_encounter_record(&record)?)?;
            if let Some(mut plan) = self
                .flight_plans
                .get(txn, &key)?
                .map(decode_flight_plan_snapshot)
                .transpose()?
            {
                plan.state = if terminal {
                    FlightPlanState::Terminal
                } else {
                    FlightPlanState::Checkpoint
                };
                plan.suspension_reason = if terminal {
                    "command lost during encounter".into()
                } else {
                    "encounter resolved".into()
                };
                self.flight_plans
                    .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
            }
            if !terminal {
                if let Some(checkpoint) = self
                    .checkpoints
                    .get(txn, &key)?
                    .map(decode_checkpoint_snapshot)
                    .transpose()?
                {
                    self.finish_checkpoint_arrival_in(txn, identity, &checkpoint)?;
                } else if let Some(mut plan) = self
                    .flight_plans
                    .get(txn, &key)?
                    .map(decode_flight_plan_snapshot)
                    .transpose()?
                {
                    plan.state = if legal_hold {
                        FlightPlanState::Held
                    } else {
                        FlightPlanState::Active
                    };
                    plan.suspension_reason = if legal_hold {
                        "local warrant assessment remains unpaid".into()
                    } else {
                        String::new()
                    };
                    self.flight_plans
                        .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
                }
            }
        } else {
            record.snapshot.turn = record.snapshot.turn.saturating_add(1);
            record.snapshot.revision = record.snapshot.revision.saturating_add(1);
            record.snapshot.next_turn_second = due_second.saturating_add(1_000);
            record.snapshot.summary = outcome;
            self.encounters
                .put(txn, &key, &encode_encounter_record(&record)?)?;
            self.schedule_encounter_turn_in(
                txn,
                identity,
                encounter_id,
                record.snapshot.next_turn_second,
            )?;
        }
        Ok(())
    }

    fn process_shared_combat_turn_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        due_second: u64,
        combat_id: u64,
    ) -> Result<Vec<PlayerIdentity>, StoreError> {
        let Some(mut shared) = self
            .shared_combats
            .get(txn, &combat_id)?
            .map(decode_shared_combat_record)
            .transpose()?
        else {
            return Err(StoreError::Corrupt("scheduled shared combat is missing"));
        };
        if shared.combat.complete
            || shared
                .combat
                .round_started_second
                .saturating_add(crate::combat::COMBAT_TURN_SECONDS)
                != due_second
        {
            return Err(StoreError::Corrupt(
                "shared combat turn disagrees with combat state",
            ));
        }

        let mut orders = std::mem::take(&mut shared.orders);
        shared.automation_decisions.clear();
        let missing_vessels = shared
            .combat
            .vessels
            .iter()
            .filter(|vessel| {
                vessel.disposition == crate::combat::VesselDisposition::Active
                    && !orders
                        .iter()
                        .any(|order| order.vessel_id == vessel.vessel_id)
            })
            .cloned()
            .collect::<Vec<_>>();
        for vessel in &missing_vessels {
            if let Some(participant) = shared
                .participants
                .iter()
                .find(|participant| participant.ship_id == vessel.vessel_id)
            {
                let ship = self
                    .ships
                    .get(txn, &participant.ship_id)?
                    .map(decode_ship_record)
                    .transpose()?
                    .ok_or(StoreError::Corrupt("shared-combat ship is missing"))?;
                let mut decision = crate::combat::risk_directed_order(
                    &shared.combat,
                    ship.ship_id,
                    &ship.combat_policy,
                )
                .map_err(|_| StoreError::Corrupt("offline tactical controller failed"))?;
                decision.order = self.staff_automated_order_in(
                    txn,
                    &participant.identity,
                    &ship,
                    &shared.combat,
                    &decision.order,
                )?;
                orders.push(decision.order.clone());
                shared.automation_decisions.push(decision);
            } else {
                orders.push(
                    crate::combat::risk_directed_order(
                        &shared.combat,
                        vessel.vessel_id,
                        &crate::combat::AutomationPolicy {
                            objective: crate::combat::Objective::Defeat,
                            minimum_victory_percent: 55,
                            ..Default::default()
                        },
                    )
                    .map_err(|_| StoreError::Corrupt("contact tactical controller failed"))?
                    .order,
                );
            }
        }
        let resolution = crate::combat::resolve_round(&shared.combat, &orders)
            .map_err(|_| StoreError::Corrupt("shared combat order failed resolution"))?;
        for event in &resolution.events {
            shared
                .combat_log
                .push(combat_event_text(&shared.combat, event));
        }
        let mut next_state = resolution.state;
        let mut waiting = Vec::new();
        for intervention in shared.pending_interventions.drain(..) {
            if intervention.due_second <= due_second {
                let vessel_id = intervention.contact_id | (1_u64 << 62);
                if !next_state
                    .vessels
                    .iter()
                    .any(|vessel| vessel.vessel_id == vessel_id)
                {
                    next_state.vessels.push(
                        crate::combat::materialize_vessel(
                            vessel_id,
                            intervention.side,
                            intervention.ship_name.clone(),
                            intervention.catalog_id,
                            7,
                        )
                        .map_err(|_| {
                            StoreError::Corrupt("intervening combat loadout is invalid")
                        })?,
                    );
                    next_state.revision = next_state.revision.saturating_add(1);
                    next_state.complete = false;
                    shared.combat_log.push(format!(
                        "{} completes its delayed intercept and joins the engagement.",
                        intervention.ship_name
                    ));
                }
            } else {
                waiting.push(intervention);
            }
        }
        shared.pending_interventions = waiting;
        if shared.combat_log.len() > 40 {
            shared.combat_log.drain(..shared.combat_log.len() - 40);
        }

        let participants = shared.participants.clone();
        for participant in &participants {
            let vessel = next_state
                .vessels
                .iter()
                .find(|vessel| vessel.vessel_id == participant.ship_id)
                .ok_or(StoreError::Corrupt(
                    "player vessel vanished from shared combat",
                ))?
                .clone();
            let mut ship = self
                .ships
                .get(txn, &participant.ship_id)?
                .map(decode_ship_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("shared-combat ship is missing"))?;
            apply_combat_damage_to_ship(&vessel, &mut ship);
            if next_state.complete {
                self.apply_combat_crew_hits_in(
                    txn,
                    &participant.identity,
                    participant.ship_id,
                    vessel.crew_hits,
                    due_second,
                    combat_id,
                )?;
                if !matches!(
                    vessel.disposition,
                    crate::combat::VesselDisposition::Captured
                        | crate::combat::VesselDisposition::Surrendered
                        | crate::combat::VesselDisposition::Abandoned
                        | crate::combat::VesselDisposition::Destroyed
                ) {
                    begin_offline_recovery(&mut ship, due_second);
                }
            }
            self.ships
                .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        }
        shared.combat = next_state;

        if shared.combat.complete {
            self.finish_shared_combat_in(txn, due_second, &mut shared)?;
            for participant in &participants {
                self.ship_combats.delete(txn, &participant.ship_id)?;
                if let Some(watch) = self.interception_watch_in(txn, participant.ship_id)? {
                    let ship = self
                        .ships
                        .get(txn, &participant.ship_id)?
                        .map(decode_ship_record)
                        .transpose()?
                        .ok_or(StoreError::Corrupt(
                            "interception-watch ship disappeared after combat",
                        ))?;
                    let operational = shared
                        .combat
                        .vessels
                        .iter()
                        .find(|vessel| vessel.vessel_id == participant.ship_id)
                        .is_some_and(|vessel| {
                            !matches!(
                                vessel.disposition,
                                crate::combat::VesselDisposition::Captured
                                    | crate::combat::VesselDisposition::Surrendered
                                    | crate::combat::VesselDisposition::Abandoned
                                    | crate::combat::VesselDisposition::Destroyed
                            )
                        });
                    self.remove_contact_schedules_in(txn, participant.ship_id)?;
                    if operational && Self::ship_traffic_locus(&ship) == Some(watch.locus) {
                        self.schedule_next_interception_watch_in(txn, &watch, due_second)?;
                    } else {
                        self.interception_watches
                            .delete(txn, &participant.ship_id)?;
                    }
                }
            }
        } else {
            for participant in participants
                .iter()
                .filter(|participant| participant.directly_commanded)
            {
                self.update_shared_encounter_view_in(txn, participant, &shared, false)?;
            }
            self.schedule_shared_combat_turn_in(
                txn,
                combat_id,
                shared
                    .combat
                    .round_started_second
                    .saturating_add(crate::combat::COMBAT_TURN_SECONDS),
            )?;
        }
        self.shared_combats
            .put(txn, &combat_id, &encode_shared_combat_record(&shared)?)?;
        Ok(participants
            .into_iter()
            .filter(|participant| participant.directly_commanded)
            .map(|participant| participant.identity)
            .collect())
    }

    fn update_shared_encounter_view_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        participant: &SharedCombatParticipant,
        shared: &SharedCombatRecord,
        complete: bool,
    ) -> Result<(), StoreError> {
        let key = encode_identity(&participant.identity);
        let Some(mut record) = self
            .encounters
            .get(txn, &key)?
            .map(decode_encounter_record)
            .transpose()?
        else {
            return Err(StoreError::Corrupt(
                "shared-combat encounter view is missing",
            ));
        };
        let vessel = shared
            .combat
            .vessels
            .iter()
            .find(|vessel| vessel.vessel_id == participant.ship_id)
            .ok_or(StoreError::Corrupt("shared-combat participant is missing"))?;
        record.snapshot.revision = record.snapshot.revision.saturating_add(1);
        record.snapshot.turn = shared.combat.round;
        record.snapshot.next_turn_second = shared
            .combat
            .round_started_second
            .saturating_add(crate::combat::COMBAT_TURN_SECONDS);
        record.combat_log = shared.combat_log.clone();
        record.player_order = None;
        record.automation_decision = shared
            .automation_decisions
            .iter()
            .find(|decision| decision.order.vessel_id == participant.ship_id)
            .cloned();
        if complete {
            record.combat = Some(shared.combat.clone());
            let command_lost = matches!(
                vessel.disposition,
                crate::combat::VesselDisposition::Captured
                    | crate::combat::VesselDisposition::Surrendered
                    | crate::combat::VesselDisposition::Abandoned
                    | crate::combat::VesselDisposition::Destroyed
            );
            let outcome = match vessel.disposition {
                crate::combat::VesselDisposition::Destroyed => {
                    "The ship breaks up under fire; command and vessel are lost."
                }
                crate::combat::VesselDisposition::Captured
                | crate::combat::VesselDisposition::Surrendered => {
                    "The opposing crew takes custody of the surrendered vessel."
                }
                crate::combat::VesselDisposition::Abandoned => {
                    "The surviving crew abandons the vessel in escape craft."
                }
                crate::combat::VesselDisposition::Withdrawing => {
                    "The ship opens the range and breaks contact."
                }
                _ => "The opposing vessel can no longer contest the engagement.",
            }
            .to_string();
            let ship = self
                .ships
                .get(txn, &participant.ship_id)?
                .map(decode_ship_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("shared-combat result ship is missing"))?;
            record.snapshot.state = EncounterState::Resolved;
            record.snapshot.summary = outcome.clone();
            record.result = Some(EncounterResult {
                encounter_id: shared.combat.combat_id,
                resolved: true,
                terminal: command_lost,
                outcome,
                turns: shared.combat.round.saturating_sub(1),
                cargo_lost_millitons: 0,
                fuel_lost_millitons: 0,
                damage_hits: ship
                    .subsystems
                    .iter()
                    .map(|subsystem| subsystem.sustained_hits)
                    .sum(),
            });
        } else {
            record.snapshot.summary = format!(
                "Combat round {} is complete. Fresh joint orders are required.",
                shared.combat.round.saturating_sub(1)
            );
        }
        self.encounters
            .put(txn, &key, &encode_encounter_record(&record)?)?;
        Ok(())
    }

    fn finish_shared_combat_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        due_second: u64,
        shared: &mut SharedCombatRecord,
    ) -> Result<(), StoreError> {
        let participants = shared.participants.clone();
        for participant in &participants {
            if participant.directly_commanded {
                self.update_shared_encounter_view_in(txn, participant, shared, true)?;
                let key = encode_identity(&participant.identity);
                let vessel = shared
                    .combat
                    .vessels
                    .iter()
                    .find(|vessel| vessel.vessel_id == participant.ship_id)
                    .ok_or(StoreError::Corrupt("shared-combat participant is missing"))?;
                let command_lost = matches!(
                    vessel.disposition,
                    crate::combat::VesselDisposition::Captured
                        | crate::combat::VesselDisposition::Surrendered
                        | crate::combat::VesselDisposition::Abandoned
                        | crate::combat::VesselDisposition::Destroyed
                );
                if command_lost
                    && !matches!(
                        vessel.disposition,
                        crate::combat::VesselDisposition::Captured
                            | crate::combat::VesselDisposition::Surrendered
                    )
                {
                    self.relocate_unique_cargo_after_command_loss_in(
                        txn,
                        participant.ship_id,
                        shared.system_id,
                        vessel.disposition,
                        0,
                    )?;
                }
                if let Some(mut plan) = self
                    .flight_plans
                    .get(txn, &key)?
                    .map(decode_flight_plan_snapshot)
                    .transpose()?
                {
                    plan.state = if command_lost {
                        FlightPlanState::Terminal
                    } else {
                        FlightPlanState::Checkpoint
                    };
                    plan.suspension_reason = if command_lost {
                        "command lost during combat".into()
                    } else {
                        "combat resolved; recovery watch set".into()
                    };
                    self.flight_plans
                        .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
                }
                if !command_lost {
                    if let Some(checkpoint) = self
                        .checkpoints
                        .get(txn, &key)?
                        .map(decode_checkpoint_snapshot)
                        .transpose()?
                    {
                        self.finish_checkpoint_arrival_in(txn, &participant.identity, &checkpoint)?;
                    }
                    self.start_post_combat_recovery_in(txn, &participant.identity)?;
                }
            }
        }
        self.apply_inactive_shared_losses_in(txn, due_second, shared)?;
        self.transfer_shared_combat_prize_in(txn, due_second, shared)?;
        self.finish_shared_combat_careers_in(txn, due_second, shared)?;
        Ok(())
    }

    fn finish_shared_combat_careers_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        due_second: u64,
        shared: &SharedCombatRecord,
    ) -> Result<(), StoreError> {
        for participant in shared
            .participants
            .iter()
            .filter(|participant| participant.initiated)
        {
            let Some(target) = shared
                .participants
                .iter()
                .find(|target| target.side != participant.side)
            else {
                continue;
            };
            let Some(player_vessel) = shared
                .combat
                .vessels
                .iter()
                .find(|vessel| vessel.vessel_id == participant.ship_id)
            else {
                continue;
            };
            let Some(target_vessel) = shared
                .combat
                .vessels
                .iter()
                .find(|vessel| vessel.vessel_id == target.ship_id)
            else {
                continue;
            };
            let command_lost = matches!(
                player_vessel.disposition,
                crate::combat::VesselDisposition::Captured
                    | crate::combat::VesselDisposition::Surrendered
                    | crate::combat::VesselDisposition::Abandoned
                    | crate::combat::VesselDisposition::Destroyed
            );
            let mut career = self.career_state_in(txn, &participant.identity)?;
            for opportunity in career.opportunities.iter_mut().filter(|opportunity| {
                opportunity.state == crate::careers::OpportunityState::Accepted
                    && opportunity.target_contact_id == target.ship_id
            }) {
                let Some(evidence) = crate::careers::combat_objective_evidence(
                    opportunity.objective_kind,
                    command_lost,
                    Some(target_vessel.disposition),
                    false,
                ) else {
                    continue;
                };
                opportunity.evidence_kind = evidence;
                opportunity.evidence_second = due_second;
                if matches!(
                    evidence,
                    crate::careers::ObjectiveEvidenceKind::TargetCaptured
                        | crate::careers::ObjectiveEvidenceKind::CargoSecured
                ) {
                    opportunity.evidence_vessel_id = target.ship_id;
                }
                career.revision = career.revision.saturating_add(1);
            }
            let mut player = self
                .players
                .get(txn, &encode_identity(&participant.identity))?
                .map(decode_player_record)
                .transpose()?
                .ok_or(StoreError::Corrupt(
                    "shared-combat career player is missing",
                ))?;
            if target_vessel.disposition != crate::combat::VesselDisposition::Active {
                self.settle_combat_bounties_in(
                    txn,
                    &participant.identity,
                    &mut player,
                    shared.system_id,
                    due_second,
                )?;
            }
            self.players.put(
                txn,
                &encode_identity(&participant.identity),
                &encode_player_record(&player),
            )?;
            self.put_career_state_in(txn, &participant.identity, &career)?;
        }
        Ok(())
    }

    fn apply_inactive_shared_losses_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        due_second: u64,
        shared: &SharedCombatRecord,
    ) -> Result<(), StoreError> {
        for participant in shared
            .participants
            .iter()
            .filter(|participant| !participant.directly_commanded)
        {
            let vessel = shared
                .combat
                .vessels
                .iter()
                .find(|vessel| vessel.vessel_id == participant.ship_id)
                .ok_or(StoreError::Corrupt("shared-combat participant is missing"))?;
            if !matches!(
                vessel.disposition,
                crate::combat::VesselDisposition::Destroyed
                    | crate::combat::VesselDisposition::Abandoned
            ) {
                continue;
            }
            let ship = self
                .ships
                .get(txn, &participant.ship_id)?
                .map(decode_ship_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("lost managed ship is missing"))?;
            let mut owner = self
                .players
                .get(txn, &encode_identity(&participant.identity))?
                .map(decode_player_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("lost managed ship owner is missing"))?;
            owner
                .managed_ship_ids
                .retain(|ship_id| *ship_id != participant.ship_id);
            owner.fleet_revision = owner.fleet_revision.saturating_add(1);
            self.players.put(
                txn,
                &encode_identity(&participant.identity),
                &encode_player_record(&owner),
            )?;
            self.relocate_unique_cargo_after_command_loss_in(
                txn,
                ship.ship_id,
                shared.system_id,
                vessel.disposition,
                0,
            )?;
            let services = self
                .crew_services
                .iter(txn)?
                .map(|entry| {
                    let (_, bytes) = entry?;
                    decode_crew_service(bytes)
                })
                .collect::<Result<Vec<_>, StoreError>>()?;
            for mut service in services.into_iter().filter(|service| {
                service.ship_id == ship.ship_id && service.command == participant.identity
            }) {
                service.assigned_slot_ids.clear();
                service.availability = CrewAvailability::Detached;
                service.available_second = due_second.saturating_add(
                    if vessel.disposition == crate::combat::VesselDisposition::Abandoned {
                        7
                    } else {
                        14
                    } * crate::simulation::SECONDS_PER_DAY,
                );
                service.shore_system_id = shared.system_id;
                service.shore_facility_id = shared.system_id;
                service.revision = service.revision.saturating_add(1);
                self.crew_services
                    .put(txn, &service.person_id, &encode_crew_service(&service)?)?;
                self.schedule_prisoner_release_in(
                    txn,
                    service.person_id,
                    service.available_second,
                )?;
            }
            self.remove_ship_schedules_in(txn, ship.ship_id, true)?;
            self.ships.delete(txn, &ship.ship_id)?;
            self.finances.delete(txn, &ship_finance_key(ship.ship_id))?;
            self.dispatch_combat_aftermath_in(
                txn,
                due_second,
                shared.system_id,
                &participant.identity,
                &format!("Loss of {}", ship.name),
                &format!(
                    "A delayed command report records the loss of {} in system {}. Surviving personnel enter rescue or recovery proceedings.",
                    ship.name, shared.system_id
                ),
            )?;
        }
        Ok(())
    }

    fn transfer_shared_combat_prize_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        due_second: u64,
        shared: &SharedCombatRecord,
    ) -> Result<(), StoreError> {
        let captured = shared
            .participants
            .iter()
            .filter(|participant| {
                shared.combat.vessels.iter().any(|vessel| {
                    vessel.vessel_id == participant.ship_id
                        && matches!(
                            vessel.disposition,
                            crate::combat::VesselDisposition::Captured
                                | crate::combat::VesselDisposition::Surrendered
                        )
                })
            })
            .cloned()
            .collect::<Vec<_>>();
        for loser in captured {
            let Some(captor) = shared
                .participants
                .iter()
                .filter(|candidate| candidate.side != loser.side)
                .filter(|candidate| {
                    shared.combat.vessels.iter().any(|vessel| {
                        vessel.vessel_id == candidate.ship_id
                            && !matches!(
                                vessel.disposition,
                                crate::combat::VesselDisposition::Captured
                                    | crate::combat::VesselDisposition::Surrendered
                                    | crate::combat::VesselDisposition::Abandoned
                                    | crate::combat::VesselDisposition::Destroyed
                            )
                    })
                })
                .min_by_key(|candidate| (!candidate.initiated, candidate.ship_id))
                .cloned()
            else {
                continue;
            };
            let mut ship = self
                .ships
                .get(txn, &loser.ship_id)?
                .map(decode_ship_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("captured player ship is missing"))?;
            let mut loser_player = self
                .players
                .get(txn, &encode_identity(&loser.identity))?
                .map(decode_player_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("captured ship owner is missing"))?;
            let mut captor_player = self
                .players
                .get(txn, &encode_identity(&captor.identity))?
                .map(decode_player_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("captor is missing"))?;
            let mut captor_career = self.career_state_in(txn, &captor.identity)?;
            let unlawful = captor.initiated && !shared.authorized_attack;
            let stolen = unlawful || captor_career.mode == crate::careers::CombatCareerMode::Pirate;
            let title = if stolen {
                crate::wire::ShipTitleKind::StolenRegistry
            } else {
                crate::wire::ShipTitleKind::PrizeCustody
            };
            let gross = creation::ship_market_catalog()
                .into_iter()
                .find(|entry| entry.catalog_id == ship.catalog_id)
                .map_or(0, |entry| entry.price_credits);
            let combat_vessel = shared
                .combat
                .vessels
                .iter()
                .find(|vessel| vessel.vessel_id == ship.ship_id)
                .ok_or(StoreError::Corrupt("captured combat vessel is missing"))?;
            let maximum = (combat_vessel.displacement_millitons / 50_000).max(1) as u16;
            let condition = u8::try_from(
                (u32::from(combat_vessel.hull_remaining + combat_vessel.structure_remaining) * 100
                    / u32::from(maximum.saturating_mul(2)))
                .min(100),
            )
            .unwrap_or(0);
            let law = self
                .systems
                .get(txn, &shared.system_id)?
                .map(decode_stellar_system)
                .transpose()?
                .and_then(|system| self.primary_world_in(txn, &system).ok())
                .map_or(0, |world| world.law_level);
            let terms_mode =
                if !stolen && captor_career.mode == crate::careers::CombatCareerMode::Independent {
                    crate::careers::CombatCareerMode::Privateer
                } else {
                    captor_career.mode
                };
            let terms = crate::careers::prize_terms(
                terms_mode,
                gross,
                condition,
                law,
                crate::ship_condition::mix64(shared.combat.combat_id ^ ship.ship_id),
            );

            loser_player
                .managed_ship_ids
                .retain(|ship_id| *ship_id != ship.ship_id);
            loser_player.fleet_revision = loser_player.fleet_revision.saturating_add(1);
            if !captor_player.managed_ship_ids.contains(&ship.ship_id) {
                captor_player.managed_ship_ids.push(ship.ship_id);
            }
            captor_player.fleet_revision = captor_player.fleet_revision.saturating_add(1);
            ship.command = captor.identity.clone();
            ship.commanding_person_id = 0;
            ship.standing_order = crate::wire::ManagedShipOrderKind::Hold;
            ship.activity = None;
            ship.revision = ship.revision.saturating_add(1);
            self.remove_ship_schedules_in(txn, ship.ship_id, false)?;
            let finance_key = ship_finance_key(ship.ship_id);
            let mut finance = self
                .finances
                .get(txn, &finance_key)?
                .map(decode_finance_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("captured ship title is missing"))?;
            finance.title = title;
            finance.principal_credits = 0;
            finance.monthly_payment_credits = 0;
            finance.in_default = false;
            self.finances
                .put(txn, &finance_key, &encode_finance_record(&finance))?;
            let services = self
                .crew_services
                .iter(txn)?
                .map(|entry| {
                    let (_, bytes) = entry?;
                    decode_crew_service(bytes)
                })
                .collect::<Result<Vec<_>, StoreError>>()?;
            for mut service in services {
                if service.ship_id == ship.ship_id && service.command == loser.identity {
                    service.assigned_slot_ids.clear();
                    service.availability = CrewAvailability::Detached;
                    service.available_second =
                        due_second.saturating_add(30 * crate::simulation::SECONDS_PER_DAY);
                    service.shore_system_id = shared.system_id;
                    service.shore_facility_id = shared.system_id;
                    service.revision = service.revision.saturating_add(1);
                    self.crew_services.put(
                        txn,
                        &service.person_id,
                        &encode_crew_service(&service)?,
                    )?;
                    self.schedule_prisoner_release_in(
                        txn,
                        service.person_id,
                        service.available_second,
                    )?;
                }
            }
            let prize_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
            captor_career.prizes.push(crate::careers::PrizeRecord {
                prize_id,
                captured_vessel_id: ship.ship_id,
                captured_person_ids: Vec::new(),
                catalog_id: ship.catalog_id,
                name: ship.name.clone(),
                gross_value_credits: gross,
                realizable_value_credits: terms.realizable_value_credits,
                condition_percent: condition,
                status: if stolen {
                    crate::careers::PrizeStatus::ReadyToFence
                } else {
                    crate::careers::PrizeStatus::Secured
                },
                secured_second: due_second,
                claim_message_id: 0,
                settlement_credits: terms.settlement_credits,
                advance_credits: 0,
            });
            captor_career.revision = captor_career.revision.saturating_add(1);
            self.ships
                .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
            self.players.put(
                txn,
                &encode_identity(&loser.identity),
                &encode_player_record(&loser_player),
            )?;
            self.players.put(
                txn,
                &encode_identity(&captor.identity),
                &encode_player_record(&captor_player),
            )?;
            self.put_career_state_in(txn, &captor.identity, &captor_career)?;
            self.dispatch_combat_aftermath_in(
                txn,
                due_second,
                shared.system_id,
                &loser.identity,
                &format!("Loss of {}", ship.name),
                &format!(
                    "A delayed command report records that {} was surrendered or captured in system {}. Surviving personnel enter the established parole and recovery process.",
                    ship.name, shared.system_id
                ),
            )?;
        }
        Ok(())
    }

    fn remove_ship_schedules_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        ship_id: u64,
        include_condition: bool,
    ) -> Result<(), StoreError> {
        let mut databases = vec![
            &self.player_events,
            &self.ship_activity_events,
            &self.contact_events,
        ];
        if include_condition {
            databases.push(&self.ship_condition_events);
        }
        for database in databases {
            let stale = database
                .iter(txn)?
                .filter_map(|entry| match entry {
                    Ok((key, bytes)) => match decode_scheduled_object(key, bytes) {
                        Ok((_, _, candidate)) if candidate == ship_id => Some(Ok(key.to_vec())),
                        Ok(_) => None,
                        Err(error) => Some(Err(error)),
                    },
                    Err(error) => Some(Err(StoreError::Heed(error))),
                })
                .collect::<Result<Vec<_>, StoreError>>()?;
            for key in stale {
                database.delete(txn, &key)?;
            }
        }
        Ok(())
    }

    fn dispatch_combat_aftermath_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        current: u64,
        origin_system_id: u64,
        recipient: &PlayerIdentity,
        subject: &str,
        body: &str,
    ) -> Result<(), StoreError> {
        let destinations = self
            .simulation
            .systems(txn)?
            .into_iter()
            .map(|system| system.system_id)
            .collect::<Vec<_>>();
        let (message_id, _) = self.simulation.dispatch_message(
            txn,
            current,
            origin_system_id,
            crate::simulation::MessageClass::Private,
            crate::simulation::MessageImportance::Important,
            subject,
            body,
            &destinations,
        )?;
        self.private_message_recipients.put(
            txn,
            &message_id.to_be_bytes(),
            &encode_private_message_recipient(&PrivateMessageRecipientRecord {
                message_id,
                recipient_kind: crate::wire::PrivateRecipientKind::Captain,
                destination_system_id: 0,
                recipient: recipient.clone(),
                encryption_key_id: (u64::from(recipient.bbs_id) << 32)
                    | u64::from(recipient.player_id),
                revoked: false,
            }),
        )?;
        Ok(())
    }

    fn shared_combat_transitions(
        &self,
        combat_id: u64,
        committed_sequence: u64,
        revision: u64,
    ) -> Result<Vec<PlayerTravelTransition>, StoreError> {
        let txn = self.env.read_txn()?;
        self.shared_combat_transitions_in(&txn, combat_id, committed_sequence, revision)
    }

    fn shared_combat_transitions_in(
        &self,
        txn: &heed::RoTxn<'_>,
        combat_id: u64,
        committed_sequence: u64,
        revision: u64,
    ) -> Result<Vec<PlayerTravelTransition>, StoreError> {
        let Some(shared) = self
            .shared_combats
            .get(txn, &combat_id)?
            .map(decode_shared_combat_record)
            .transpose()?
        else {
            return Ok(Vec::new());
        };
        let mut transitions = Vec::new();
        for participant in shared
            .participants
            .iter()
            .filter(|participant| participant.directly_commanded)
        {
            transitions.push(PlayerTravelTransition {
                identity: participant.identity.clone(),
                committed_sequence,
                revision,
                phase: self.player_phase_in(txn, &participant.identity)?,
                status: self.travel_status_in(txn, &participant.identity)?,
            });
        }
        Ok(transitions)
    }

    fn relocate_unique_cargo_after_command_loss_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        ship_id: u64,
        system_id: u64,
        disposition: crate::combat::VesselDisposition,
        captor_id: u64,
    ) -> Result<(), StoreError> {
        let Some(mut unique) = self
            .unique_cargo
            .get(txn, &UNIQUE_APPLE_PIE_ID)?
            .map(decode_unique_cargo)
            .transpose()?
        else {
            return Ok(());
        };
        if !matches!(
            unique.location,
            UniqueCargoLocation::PlayerShip {
                ship_id: aboard,
                ..
            } if aboard == ship_id
        ) {
            return Ok(());
        }
        unique.location = match disposition {
            crate::combat::VesselDisposition::Destroyed => UniqueCargoLocation::Destroyed,
            crate::combat::VesselDisposition::Captured
            | crate::combat::VesselDisposition::Surrendered => UniqueCargoLocation::TrafficShip {
                traffic_ship_id: captor_id,
            },
            crate::combat::VesselDisposition::Abandoned => {
                UniqueCargoLocation::Wreckage { system_id }
            }
            _ => return Ok(()),
        };
        self.unique_cargo
            .put(txn, &unique.object_id, &encode_unique_cargo(&unique)?)?;
        Ok(())
    }

    fn process_contact_check_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        due_second: u64,
        ship_id: u64,
    ) -> Result<Option<PlayerIdentity>, StoreError> {
        let ship = self
            .ships
            .get(txn, &ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("contact-check ship is missing"))?;
        let identity = ship.command.clone();
        let key = encode_identity(&identity);
        let watch = self.interception_watch_in(txn, ship.ship_id)?;
        if self
            .encounters
            .get(txn, &key)?
            .map(decode_encounter_record)
            .transpose()?
            .is_some_and(|record| record.snapshot.state != EncounterState::Resolved)
        {
            if let Some(watch) = &watch {
                self.schedule_next_interception_watch_in(txn, watch, due_second)?;
            }
            return Ok(None);
        }
        let system = self
            .simulation
            .systems(txn)?
            .into_iter()
            .find(|system| system.system_id == ship.system_id)
            .ok_or(StoreError::MissingTrafficSimulationSystem(ship.system_id))?;
        if let Some(watch) = watch {
            if Self::ship_traffic_locus(&ship) != Some(watch.locus) {
                self.interception_watches.delete(txn, &ship.ship_id)?;
                return Ok(None);
            }
            let mut candidate = None;
            for contact in crate::traffic::movements(&system, due_second, due_second)? {
                let filter_matches = match watch.filter {
                    InterceptionWatchFilter::CraftClass { catalog_id } => {
                        contact.catalog_id == catalog_id
                    }
                    InterceptionWatchFilter::AllCraft => true,
                    InterceptionWatchFilter::NamedVessel { .. } => false,
                };
                if filter_matches
                    && self.traffic_contact_matches_watch_locus_in(txn, &contact, watch.locus)?
                {
                    candidate = Some(contact);
                    break;
                }
            }
            if let Some(contact) = candidate {
                let career = self.career_state_in(txn, &identity)?;
                match self.engage_traffic_contact_in(
                    txn,
                    &identity,
                    contact.contact_id,
                    career.revision,
                    watch.purpose,
                )? {
                    RuleResult::Applied(InterceptionStart::Combat(_)) => {
                        return Ok(Some(identity));
                    }
                    RuleResult::Applied(InterceptionStart::Watch(_)) => {
                        return Err(StoreError::Corrupt(
                            "spaceborne watch contact established another watch",
                        ));
                    }
                    RuleResult::Applied(InterceptionStart::Resolution(_)) => {
                        self.schedule_next_interception_watch_in(txn, &watch, due_second)?;
                        return Ok(Some(identity));
                    }
                    RuleResult::Rejected(_) => {}
                }
            }
            self.schedule_next_interception_watch_in(txn, &watch, due_second)?;
            return Ok(None);
        }
        let candidates = crate::traffic::snapshot(&system, due_second)?;
        if candidates.is_empty() {
            return Ok(None);
        }
        let entropy = crate::ship_condition::mix64(ship_id ^ due_second ^ 0x434f_4e54_4143_5400);
        let policy = self
            .system_polity_policies
            .get(txn, &ship.system_id)?
            .map(decode_system_polity_policy)
            .transpose()?;
        let stellar = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("contact-check system is missing"))?;
        let law = self.primary_world_in(txn, &stellar)?.law_level;
        let order = policy.as_ref().map_or(50, |value| value.chaos_order);
        let combat_orientation = policy.as_ref().map_or(50, |value| value.trade_combat);
        let security = (u16::from(order) + u16::from(law.min(10)) * 10) / 2;
        let encounter_locus = match ship.location {
            ShipLocationRecord::InFlight(FlightLegRecord {
                origin: locus @ ShipLocusRecord::JumpLocus { .. },
                started_second,
                purpose: FlightLegPurpose::ApproachPort,
                ..
            }) if due_second <= started_second.saturating_add(1) => Some(locus),
            _ => self.local_traffic_locus_in(txn, &identity, &ship)?,
        };
        let candidate_count = u32::try_from(candidates.len()).unwrap_or(u32::MAX);
        let enforcement_picket = matches!(encounter_locus, Some(ShipLocusRecord::JumpLocus { .. }))
            && security >= 60
            && entropy % 100 < u64::from((security - 40).min(55));
        let pirate_locus = match encounter_locus {
            Some(ShipLocusRecord::JumpLocus { .. }) => security < 45 && candidate_count < 12,
            Some(ShipLocusRecord::Body { .. }) => {
                (35..70).contains(&security) || candidate_count >= 12 && security < 70
            }
            Some(ShipLocusRecord::Port { .. }) => security < 25,
            _ => false,
        };
        let pirate_picket = pirate_locus
            && entropy.rotate_left(13) % 100
                < u64::from(
                    (70_u16.saturating_sub(security) + u16::from(combat_orientation) / 4).min(60),
                );
        let probability =
            1.0 - (5.0_f64 / 6.0).powi(i32::try_from(candidates.len()).unwrap_or(i32::MAX));
        let roll = (entropy >> 11) as f64 / ((1_u64 << 53) as f64);
        if roll >= probability && !enforcement_picket && !pirate_picket {
            return Ok(None);
        }
        let contact = &candidates[entropy as usize % candidates.len()];
        let mut kind = if enforcement_picket {
            EncounterKind::Inspection
        } else if pirate_picket {
            EncounterKind::Hostile
        } else {
            encounter_kind_for_policy(entropy, policy.as_ref())
        };
        if kind == EncounterKind::Hostile {
            let locus_allows_pirates = match encounter_locus {
                Some(ShipLocusRecord::JumpLocus { .. }) => security < 45,
                Some(ShipLocusRecord::Body { .. }) => (35..70).contains(&security),
                Some(ShipLocusRecord::Port { .. }) => security < 25,
                _ => false,
            };
            let target_overmatches = catalog_combat_power(ship.catalog_id).saturating_mul(2)
                >= catalog_combat_power(contact.catalog_id).saturating_mul(3);
            if !locus_allows_pirates || target_overmatches {
                kind = if security >= 60 {
                    EncounterKind::Inspection
                } else {
                    EncounterKind::RoutineTraffic
                };
            }
        }
        let hostile = kind == EncounterKind::Hostile;
        let filed_plan = self
            .flight_plans
            .get(txn, &key)?
            .map(decode_flight_plan_snapshot)
            .transpose()?;
        let through_authorized = filed_plan.as_ref().is_some_and(|plan| {
            if matches!(
                ship.location,
                ShipLocationRecord::InFlight(FlightLegRecord {
                    purpose: FlightLegPurpose::ApproachPort,
                    ..
                })
            ) {
                plan.steps
                    .iter()
                    .rev()
                    .find(|step| matches!(step.action, FlightPlanAction::Dock { .. }))
                    .is_some_and(|step| step.authority == WaypointAuthority::Through)
            } else {
                plan.steps
                    .get(usize::from(plan.current_step))
                    .is_some_and(|step| step.authority == WaypointAuthority::Through)
            }
        });
        let encounter_id = take_next_id(self.meta, txn, META_NEXT_ENCOUNTER_ID)?;
        let mut snapshot = EncounterSnapshot {
            encounter_id,
            revision: 1,
            kind,
            state: EncounterState::AwaitingPosture,
            started_second: due_second,
            next_turn_second: 0,
            turn: 0,
            contact: EncounterContact {
                contact_id: contact.contact_id,
                ship_name: if hostile {
                    "Unlit contact".into()
                } else {
                    contact.ship_name.clone()
                },
                class_name: contact.class_name.clone(),
                transponder: if hostile {
                    "No response".into()
                } else {
                    contact.transponder.clone()
                },
                role: if hostile {
                    "interceptor".into()
                } else {
                    contact.role.clone()
                },
                range: "local traffic range".into(),
                confidence_percent: 75,
            },
            summary: if hostile {
                "An armed contact alters course to intercept.".into()
            } else {
                "A contact intersects the ship's local traffic solution.".into()
            },
        };
        self.emit_encounter_radio_in(
            txn,
            &ship,
            &snapshot.contact,
            snapshot.kind,
            encounter_id,
            due_second,
            !through_authorized,
            &snapshot.summary,
        )?;
        if !hostile && through_authorized {
            snapshot.state = EncounterState::Resolved;
            snapshot.summary = match kind {
                EncounterKind::Inspection => {
                    "The ship complies with a routine inspection and is released."
                }
                EncounterKind::TrafficControl => {
                    "The assigned traffic crossing completes without delay."
                }
                EncounterKind::Distress
                    if self
                        .flight_plans
                        .get(txn, &key)?
                        .map(decode_flight_plan_snapshot)
                        .transpose()?
                        .is_some_and(|plan| plan.policy.assist_distress) =>
                {
                    "Standing orders render assistance before the voyage continues."
                }
                EncounterKind::Distress => {
                    "The distress call is logged and passed to traffic control."
                }
                EncounterKind::Derelict => "The drifting contact is logged for local authorities.",
                EncounterKind::Hazard => "The pilot avoids the reported traffic hazard.",
                EncounterKind::Military => {
                    "The naval challenge is answered and the picket releases the ship."
                }
                _ => "Identification is exchanged and both vessels continue.",
            }
            .into();
            let result = EncounterResult {
                encounter_id,
                resolved: true,
                terminal: false,
                outcome: snapshot.summary.clone(),
                turns: 0,
                cargo_lost_millitons: 0,
                fuel_lost_millitons: 0,
                damage_hits: 0,
            };
            self.encounters.put(
                txn,
                &key,
                &encode_encounter_record(&EncounterRecord {
                    snapshot,
                    opponent_catalog_id: contact.catalog_id,
                    posture: Some(EncounterPosture::Comply),
                    fallbacks: Vec::new(),
                    result: Some(result),
                    combat: None,
                    player_order: None,
                    automation_decision: None,
                    combat_log: Vec::new(),
                    pending_interventions: Vec::new(),
                })?,
            )?;
            return Ok(None);
        }
        self.encounters.put(
            txn,
            &key,
            &encode_encounter_record(&EncounterRecord {
                snapshot: snapshot.clone(),
                opponent_catalog_id: contact.catalog_id,
                posture: None,
                fallbacks: Vec::new(),
                result: None,
                combat: None,
                player_order: None,
                automation_decision: None,
                combat_log: Vec::new(),
                pending_interventions: Vec::new(),
            })?,
        )?;
        let policy = filed_plan
            .as_ref()
            .map(|plan| plan.policy.clone())
            .unwrap_or_default();
        if let Some(mut plan) = self
            .flight_plans
            .get(txn, &key)?
            .map(decode_flight_plan_snapshot)
            .transpose()?
        {
            plan.state = FlightPlanState::Encounter;
            plan.suspension_reason = "contact at traffic locus".into();
            self.flight_plans
                .put(txn, &key, &encode_flight_plan_snapshot(&plan)?)?;
        }
        if !through_authorized {
            return Ok(Some(identity));
        }
        let posture = match kind {
            EncounterKind::Hostile => policy.hostile_posture,
            EncounterKind::Inspection | EncounterKind::TrafficControl | EncounterKind::Military
                if policy.comply_with_inspection =>
            {
                EncounterPosture::Comply
            }
            EncounterKind::Distress if policy.assist_distress => EncounterPosture::Comply,
            _ => EncounterPosture::Flee,
        };
        let _ = self.resolve_encounter_in(
            txn,
            &identity,
            &crate::wire::ResolveEncounterRequest {
                encounter_id,
                expected_revision: 1,
                posture,
                fallbacks: policy.hostile_fallbacks,
            },
        )?;
        Ok(Some(identity))
    }

    fn ship_status_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<ShipStatusSnapshot, StoreError> {
        let player = self
            .players
            .get(txn, &encode_identity(identity))?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("existing player record is missing"))?;
        let ship = self
            .ships
            .get(txn, &player.ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("player ship record is missing"))?;
        if ship.command != *identity {
            let terminal_loss = self
                .encounters
                .get(txn, &encode_identity(identity))?
                .map(decode_encounter_record)
                .transpose()?
                .and_then(|encounter| encounter.result)
                .is_some_and(|result| result.terminal);
            if !terminal_loss {
                return Err(StoreError::Corrupt(
                    "player does not command the recorded ship",
                ));
            }
        }
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let current_game_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let subsystems = ship
            .subsystems
            .iter()
            .map(|record| {
                let battlefield_repair_hits =
                    record.battlefield_repair_hits.min(record.sustained_hits);
                let effective_hits = record
                    .sustained_hits
                    .saturating_sub(battlefield_repair_hits);
                ShipSubsystemStatus {
                    subsystem_id: record.subsystem_id,
                    kind: record.kind,
                    label: record.label.clone(),
                    maximum_hits: record.maximum_hits,
                    sustained_hits: record.sustained_hits,
                    battlefield_repair_hits,
                    effective_hits,
                    operational_effect: subsystem_operational_effect(
                        record.kind,
                        effective_hits,
                        record.maximum_hits,
                    ),
                    last_proper_repair_second: record.last_proper_repair_second,
                    installed_second: record.installed_second,
                    last_refit_second: record.last_refit_second,
                    calendar_age_months: record.calendar_age_months,
                    operating_seconds: record.operating_seconds,
                    duty_cycles: record.duty_cycles,
                    skimming_cycles: record.skimming_cycles,
                    neglect_damage_hits: record.neglect_damage_hits,
                    displacement_millitons: record.displacement_millitons,
                    replacement_price_credits: record.replacement_price_credits,
                    installation_generation: record.installation_generation,
                    reconditioned: record.reconditioned,
                }
            })
            .collect();
        let fuel_capacity_millitons = effective_fuel_capacity(&ship, &spec);
        let cargo_capacity_millitons = effective_cargo_capacity(&ship, &spec);
        Ok(ShipStatusSnapshot {
            ship_revision: ship.revision,
            ship_id: ship.ship_id,
            ship_name: ship.name,
            catalog_id: ship.catalog_id,
            catalog_revision: ship.catalog_revision,
            system_id: ship.system_id,
            current_game_second,
            displacement_millitons: spec.displacement_millitons,
            jump_rating: spec.jump_rating,
            thrust_g: spec.thrust_g,
            fuel_capacity_millitons,
            current_fuel_millitons: ship.current_fuel_millitons,
            jump_fuel_millitons: spec.jump_fuel_millitons,
            cargo_capacity_millitons,
            monthly_maintenance_credits: crate::ship_condition::monthly_maintenance_credits(
                ship.maintenance.purchase_price_credits,
            ),
            next_maintenance_second: ship.maintenance.next_accounting_second,
            maintenance_paid_through_second: ship.maintenance.paid_through_second,
            maintenance_arrears_credits: ship.maintenance.arrears_credits,
            completed_maintenance_cycles: ship.maintenance.completed_cycles,
            consecutive_missed_maintenance: ship.maintenance.consecutive_missed_cycles,
            commissioned_second: ship.maintenance.commissioned_second,
            transit_count: ship.maintenance.transit_count,
            warranty_expires_second: ship.maintenance.warranty_expires_second,
            warranty_transit_limit: ship.maintenance.warranty_transit_limit,
            warranty_repairs: ship.maintenance.warranty_repairs,
            last_refit_second: ship.maintenance.last_refit_second,
            completed_refits: ship.maintenance.completed_refits,
            active_activity: ship.activity.as_ref().map(|activity| ShipActivityStatus {
                activity_id: activity.activity_id,
                kind: match activity.kind {
                    ShipActivityKind::Construction => WireShipActivityKind::Construction,
                    ShipActivityKind::Refit => WireShipActivityKind::Refit,
                    ShipActivityKind::ProperRepair { subsystem_id } => {
                        WireShipActivityKind::ProperRepair { subsystem_id }
                    }
                    ShipActivityKind::GasGiantSkim {
                        quantity_millitons, ..
                    } => WireShipActivityKind::GasGiantSkim { quantity_millitons },
                    ShipActivityKind::WildernessWater {
                        quantity_millitons, ..
                    } => WireShipActivityKind::WildernessWater { quantity_millitons },
                    ShipActivityKind::FuelProcessing {
                        quantity_millitons, ..
                    } => WireShipActivityKind::FuelProcessing { quantity_millitons },
                    ShipActivityKind::Refurbishment {
                        ref subsystem_ids, ..
                    } => WireShipActivityKind::Refurbishment {
                        component_count: u16::try_from(subsystem_ids.len()).unwrap_or(u16::MAX),
                    },
                    ShipActivityKind::EscortDuty { opportunity_id, .. } => {
                        WireShipActivityKind::EscortDuty { opportunity_id }
                    }
                    ShipActivityKind::FieldRecovery { subsystem_id, .. } => {
                        WireShipActivityKind::FieldRecovery { subsystem_id }
                    }
                },
                started_second: activity.started_second,
                due_second: activity.due_second,
                cost_credits: activity.cost_credits,
                refine_collected: match activity.kind {
                    ShipActivityKind::GasGiantSkim {
                        refine_collected, ..
                    }
                    | ShipActivityKind::WildernessWater {
                        refine_collected, ..
                    } => refine_collected,
                    ShipActivityKind::FuelProcessing { .. } => true,
                    _ => false,
                },
                source_body_id: match activity.site {
                    ShipActivitySite::Frontier { source_body_id, .. } => Some(source_body_id),
                    _ => None,
                },
            }),
            unrefined_fuel_millitons: ship.unrefined_fuel_millitons,
            warranty_voided: ship.maintenance.warranty_voided,
            monthly_life_support_credits: spec.monthly_life_support_credits,
            recovery_status: ship
                .recovery_plan
                .as_ref()
                .map_or_else(String::new, |plan| {
                    format!("{}: {}", plan.goal, plan.status)
                }),
            ammunition: ship
                .ammunition
                .iter()
                .map(|lot| ShipAmmunitionStatus {
                    ammunition_id: lot.ammunition_id.clone(),
                    remaining: lot.remaining,
                    capacity: lot.capacity,
                    pack_units: lot.pack_units,
                    price_per_pack_credits: lot.price_per_pack_credits,
                })
                .collect(),
            provisions: ShipProvisionStatus {
                person_days_remaining: ship.provisions.person_days_remaining,
                capacity_person_days: ship.provisions.installed_capacity_person_days,
            },
            manifested_symptoms: ship
                .latent_quirks
                .iter()
                .filter(|quirk| quirk.manifested)
                .map(|quirk| manifested_quirk_symptom(quirk.kind).to_owned())
                .collect(),
            subsystems,
        })
    }

    fn player_and_ship_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<(PlayerRecord, ShipRecord), StoreError> {
        let player = self
            .players
            .get(txn, &encode_identity(identity))?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("existing player record is missing"))?;
        let ship = self
            .ships
            .get(txn, &player.ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("player ship record is missing"))?;
        if ship.command != *identity {
            return Err(StoreError::Corrupt(
                "player does not command the recorded ship",
            ));
        }
        Ok((player, ship))
    }

    fn operating_account_credits_in(
        &self,
        txn: &heed::RoTxn<'_>,
        player: &PlayerRecord,
        ship_id: u64,
    ) -> Result<u64, StoreError> {
        let finance = self
            .finances
            .get(txn, &ship_finance_key(ship_id))?
            .map(decode_finance_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship finance record is missing"))?;
        Ok(player.credits.saturating_add(finance.restricted_credits))
    }

    /// Pays an authorized ship expense, exhausting restricted operating
    /// credit before touching the captain's liquid account.
    fn charge_operating_account_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        player: &mut PlayerRecord,
        ship_id: u64,
        amount: u64,
    ) -> Result<bool, StoreError> {
        Ok(self
            .charge_operating_account_with_receipt_in(txn, player, ship_id, amount)?
            .is_some())
    }

    fn charge_operating_account_with_receipt_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        player: &mut PlayerRecord,
        ship_id: u64,
        amount: u64,
    ) -> Result<Option<OperatingAccountPayment>, StoreError> {
        let key = ship_finance_key(ship_id);
        let mut finance = self
            .finances
            .get(txn, &key)?
            .map(decode_finance_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship finance record is missing"))?;
        let (restricted_payment, liquid_payment) =
            operating_account_payment_parts(player, &finance, amount);
        if restricted_payment + liquid_payment != amount {
            return Ok(None);
        }
        let track_naval_expense =
            finance.title == crate::wire::ShipTitleKind::InstitutionOwned && amount != 0;
        if track_naval_expense {
            finance.authorized_expense_credits = finance
                .authorized_expense_credits
                .checked_add(amount)
                .ok_or(StoreError::Corrupt(
                    "naval operating expense total overflow",
                ))?;
        }
        let paid = apply_operating_account_payment(player, &mut finance, amount);
        debug_assert_eq!(paid, amount);
        if restricted_payment != 0 || track_naval_expense {
            self.finances
                .put(txn, &key, &encode_finance_record(&finance))?;
        }
        Ok(Some(OperatingAccountPayment {
            restricted_credits: restricted_payment,
            liquid_credits: liquid_payment,
            restricted_balance_credits: finance.restricted_credits,
            liquid_balance_credits: player.credits,
        }))
    }

