    fn docked_snapshot_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<DockedSnapshot, StoreError> {
        let (player, ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            arrived_second,
        } = ship.location
        else {
            return Err(StoreError::Corrupt(
                "docked snapshot requested while underway",
            ));
        };
        let system = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship system is missing"))?;
        let world = self.primary_world_in(txn, &system)?;
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("docked facility record is missing"))?;
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let cargo_used_millitons = ship
            .cargo
            .iter()
            .try_fold(0_u64, |sum, lot| sum.checked_add(lot.quantity_millitons))
            .ok_or(StoreError::Corrupt("cargo quantity overflow"))?;
        let current_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let fuel_capacity_millitons = effective_fuel_capacity(&ship, &spec);
        let cargo_capacity_millitons = effective_cargo_capacity(&ship, &spec);
        let restricted_credits = self
            .finances
            .get(txn, &ship_finance_key(ship.ship_id))?
            .map(decode_finance_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship finance record is missing"))?
            .restricted_credits;
        Ok(DockedSnapshot {
            ship_id: ship.ship_id,
            ship_name: ship.name,
            system_id: system.id,
            system_name: system.name,
            world_id,
            world_name: world.name.clone(),
            facility_id,
            facility_name: facility.name,
            starport: world.starport.code().to_string(),
            tech_level: world.tech_level,
            population: world.population,
            law_level: world.law_level,
            arrived_second,
            current_game_second: current_second,
            credits: player.credits,
            restricted_credits,
            debt_credits: player.debt_credits,
            fuel_millitons: ship.current_fuel_millitons,
            fuel_capacity_millitons,
            refined_fuel_price_per_ton: REFINED_FUEL_PRICE_PER_TON,
            cargo_used_millitons,
            cargo_capacity_millitons,
            unrefined_fuel_millitons: ship.unrefined_fuel_millitons,
            unrefined_fuel_price_per_ton: UNREFINED_FUEL_PRICE_PER_TON,
            accrued_berth_fee_credits: crate::ship_condition::berth_fee_credits(
                arrived_second,
                current_second,
            ),
            facility_revision: facility.revision,
            personnel_available: facility.operational && facility.personnel_exchange,
            banking_available: facility.operational && facility.banking,
            authority_available: facility.operational && facility.authority_office,
            medical_level: if facility.operational {
                facility.medical_level
            } else {
                0
            },
            clearance_required: facility.clearance_required,
        })
    }

    fn known_destinations_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<KnownDestinations, StoreError> {
        let (player, ship) = self.player_and_ship_in(txn, identity)?;
        let origin = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?;
        let origin_position = match (origin.as_ref(), ship.location) {
            (Some(system), _) => system.position_parsecs,
            (
                None,
                ShipLocationRecord::Holding {
                    locus: ShipLocusRecord::DeepSpace { position },
                    ..
                },
            ) => position.parsecs(),
            _ => return Err(StoreError::Corrupt("ship navigation origin is missing")),
        };
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let mut systems = Vec::new();
        for system_id in &player.known_system_ids {
            let Some(system) = self
                .systems
                .get(txn, system_id)?
                .map(decode_stellar_system)
                .transpose()?
            else {
                continue;
            };
            let distance = origin_position
                .iter()
                .zip(system.position_parsecs)
                .map(|(left, right)| (left - right).powi(2))
                .sum::<f64>()
                .sqrt();
            let world = self.primary_world_in(txn, &system)?;
            let mapping = self
                .player_system_mappings
                .get(txn, &player_system_mapping_key(identity, system.id))?
                .map(decode_player_system_mapping)
                .transpose()?;
            let remote_candidate = mapping
                .as_ref()
                .is_some_and(|record| record.state == SystemMappingState::Unresolved);
            let (observed_second, source, knowledge_source) = match mapping.as_ref() {
                Some(record) => (
                    record.changed_second,
                    match record.state {
                        SystemMappingState::KnownPublic => "Published navigation and mail records",
                        SystemMappingState::Unresolved => "Private carried observation",
                        SystemMappingState::PublicDispatched => "Captain's public mapping dispatch",
                        SystemMappingState::DirectDispatched => {
                            "Captain's sealed Federation filing"
                        }
                        SystemMappingState::Withheld => "Captain's withheld chart",
                        SystemMappingState::Secret => "Captain's secret chart",
                    },
                    match record.state {
                        SystemMappingState::KnownPublic => {
                            crate::wire::SystemKnowledgeSource::PublishedRecords
                        }
                        SystemMappingState::Unresolved => {
                            crate::wire::SystemKnowledgeSource::PrivateObservation
                        }
                        SystemMappingState::PublicDispatched => {
                            crate::wire::SystemKnowledgeSource::PublicDispatch
                        }
                        SystemMappingState::DirectDispatched => {
                            crate::wire::SystemKnowledgeSource::DirectDispatch
                        }
                        SystemMappingState::Withheld => {
                            crate::wire::SystemKnowledgeSource::Withheld
                        }
                        SystemMappingState::Secret => {
                            crate::wire::SystemKnowledgeSource::SecretChart
                        }
                    },
                ),
                None => (
                    player.knowledge_observed_second,
                    "Carried navigation records",
                    crate::wire::SystemKnowledgeSource::CarriedRecords,
                ),
            };
            systems.push(KnownSystemSummary {
                system_id: system.id,
                system_name: system.name,
                world_name: world.name,
                distance_milliparsecs: (distance * 1_000.0).round() as u64,
                within_jump_rating: distance <= f64::from(spec.jump_rating) + 1.0e-9,
                starport: world.starport.code().to_string(),
                population: world.population,
                tech_level: world.tech_level,
                observed_second,
                source: source.into(),
                position: crate::wire::Coordinate3::from_parsecs(system.position_parsecs),
                remote_candidate,
                knowledge_source,
                gas_giant_count: world.gas_giants,
            });
        }
        systems.sort_by_key(|system| (system.distance_milliparsecs, system.system_id));
        let belts = if let Some(origin) = origin.as_ref() {
            derive_celestial_system(origin)?
                .bodies
                .into_iter()
                .filter_map(|body| match body.kind {
                    BodyKind::PlanetoidBelt {
                        icy,
                        carbonaceous_percent,
                        silicate_or_rock_percent,
                        metal_or_water_ice_percent,
                        hydrocarbon_percent,
                        ..
                    } => Some(KnownBelt {
                        system_id: origin.id,
                        body_id: body.local_id,
                        name: body.name,
                        icy,
                        carbonaceous_percent,
                        silicate_or_rock_percent,
                        metal_or_water_ice_percent,
                        hydrocarbon_percent,
                    }),
                    _ => None,
                })
                .collect()
        } else {
            Vec::new()
        };
        Ok(KnownDestinations {
            current_system_id: origin.as_ref().map_or(0, |system| system.id),
            jump_rating: spec.jump_rating,
            systems,
            belts,
        })
    }

    fn open_arrival_packet_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<ArrivalPacket, StoreError> {
        let (mut player, ship) = self.player_and_ship_in(txn, identity)?;
        let current_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let identity_key = encode_identity(identity);
        let mut arrival = self
            .player_arrivals
            .get(txn, &identity_key)?
            .map(decode_player_arrival)
            .transpose()?
            .filter(|arrival| arrival.system_id == ship.system_id)
            .unwrap_or(PlayerArrivalRecord {
                system_id: ship.system_id,
                arrival_second: current_second,
                mailbag_id: None,
                mail_delivered: 0,
                mail_forwarded: 0,
                mail_expired: 0,
                stipend_credits: 0,
                presented: true,
            });
        let system = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("arrival packet system is missing"))?;
        let mut items = Vec::new();
        let new_arrival = !arrival.presented;
        if new_arrival {
            let available = self.simulation.available_messages(
                txn,
                ship.system_id,
                arrival.arrival_second,
                false,
            )?;
            let mut cursor = None::<PlayerFeedCursorRecord>;
            for available in available {
                if available.message.class == crate::simulation::MessageClass::Private {
                    let visible = self
                        .private_message_recipients
                        .get(txn, &available.message.message_id.to_be_bytes())?
                        .map(decode_private_message_recipient)
                        .transpose()?
                        .is_some_and(|record| {
                            !record.revoked
                                && match record.recipient_kind {
                                    crate::wire::PrivateRecipientKind::System => {
                                        record.destination_system_id == ship.system_id
                                    }
                                    crate::wire::PrivateRecipientKind::Captain => {
                                        record.recipient == *identity
                                    }
                                }
                        });
                    if !visible {
                        continue;
                    }
                    self.receive_task_claim_result_in(
                        txn,
                        identity,
                        available.message.message_id,
                        arrival.arrival_second,
                    )?;
                    self.receive_task_adjudication_result_in(
                        txn,
                        identity,
                        available.message.message_id,
                        arrival.arrival_second,
                    )?;
                    self.apply_sysop_directive_in(
                        txn,
                        identity,
                        available.message.message_id,
                        arrival.arrival_second,
                        &mut player,
                    )?;
                }
                let state_key = player_message_state_key(identity, available.message.message_id);
                let existing = self
                    .player_message_state
                    .get(txn, &state_key)?
                    .map(decode_player_message_state)
                    .transpose()?;
                let classification = existing
                    .map(|state| state.classification)
                    .unwrap_or(MessageClassification::Unreviewed);
                if existing.is_none() {
                    self.player_message_state.put(
                        txn,
                        &state_key,
                        &encode_player_message_state(&PlayerMessageStateRecord {
                            first_seen_system_id: ship.system_id,
                            first_seen_second: arrival.arrival_second,
                            classification,
                        }),
                    )?;
                }
                if available.message.class == crate::simulation::MessageClass::Private {
                    if !player
                        .known_system_ids
                        .contains(&available.message.origin_system_id)
                    {
                        player
                            .known_system_ids
                            .push(available.message.origin_system_id);
                    }
                } else {
                    // Public contact arrives as one carried dossier. Knowing
                    // its polity means learning the polity's complete system
                    // register together, not discovering its members one mail
                    // hop at a time.
                    self.merge_public_polity_dossier_in(
                        txn,
                        identity,
                        &mut player,
                        available.message.origin_system_id,
                        available.message.message_id,
                        available.available_second,
                    )?;
                }
                let candidate = PlayerFeedCursorRecord {
                    available_second: available.available_second,
                    message_id: available.message.message_id,
                };
                if cursor.is_none_or(|current| {
                    (candidate.available_second, candidate.message_id)
                        > (current.available_second, current.message_id)
                }) {
                    cursor = Some(candidate);
                }
                let passes_filter = (available.message.importance as u8)
                    >= player.message_filter_minimums[available.message.class as usize];
                if passes_filter
                    && !matches!(
                        classification,
                        MessageClassification::Ignored | MessageClassification::Archived
                    )
                {
                    items.push(self.message_item_in(
                        txn,
                        identity,
                        &available.message,
                        available.available_second,
                        classification,
                        existing.is_some(),
                        ship.system_id,
                        arrival.arrival_second,
                    )?);
                }
            }
            self.receive_task_remittances_available_in(
                txn,
                identity,
                ship.system_id,
                arrival.arrival_second,
                &mut player,
            )?;
            player.known_system_ids.sort_unstable();
            player.known_system_ids.dedup();
            player.knowledge_observed_second =
                player.knowledge_observed_second.max(arrival.arrival_second);
            self.players
                .put(txn, &identity_key, &encode_player_record(&player))?;
            if let Some(cursor) = cursor {
                self.player_feed_cursors.put(
                    txn,
                    &player_feed_cursor_key(identity, ship.system_id),
                    &encode_player_feed_cursor(&cursor),
                )?;
            }
            arrival.presented = true;
            self.player_arrivals
                .put(txn, &identity_key, &encode_player_arrival(&arrival))?;
        }
        Ok(ArrivalPacket {
            new_arrival,
            system_id: system.id,
            system_name: system.name,
            arrival_second: arrival.arrival_second,
            mailbag_id: arrival.mailbag_id,
            mail_delivered: arrival.mail_delivered,
            mail_forwarded: arrival.mail_forwarded,
            mail_expired: arrival.mail_expired,
            stipend_credits: arrival.stipend_credits,
            items,
            mapping_status: self.system_mapping_status_in(txn, identity, system.id)?,
        })
    }

    fn message_management_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<MessageManagement, StoreError> {
        let current_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let prefix = encode_identity(identity);
        let player = self
            .players
            .get(txn, &prefix)?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("message owner player is missing"))?;
        let ship = self
            .ships
            .get(txn, &player.ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("message owner ship is missing"))?;
        let mut items = Vec::new();
        for entry in self.player_message_state.prefix_iter(txn, &prefix)? {
            let (key, value) = entry?;
            let message_id = player_message_state_key_id(key)?;
            let state = decode_player_message_state(value)?;
            let message = self.simulation.message(txn, message_id)?;
            items.push(self.message_item_in(
                txn,
                identity,
                &message,
                state.first_seen_second,
                state.classification,
                true,
                ship.system_id,
                current_second,
            )?);
        }
        items.sort_by_key(|item| std::cmp::Reverse((item.created_second, item.message_id)));
        let classes = [
            crate::wire::MessageClass::AgencyNews,
            crate::wire::MessageClass::PublicService,
            crate::wire::MessageClass::ContractOffer,
            crate::wire::MessageClass::TrafficNotice,
            crate::wire::MessageClass::Private,
        ];
        let filters = classes
            .into_iter()
            .zip(player.message_filter_minimums)
            .map(|(class, value)| {
                Ok(crate::wire::MessageFilter {
                    class,
                    minimum_importance: wire_message_importance(value)?,
                })
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        Ok(MessageManagement { items, filters })
    }

    fn set_message_filter_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        class: crate::wire::MessageClass,
        minimum_importance: crate::wire::MessageImportance,
    ) -> Result<MessageManagement, StoreError> {
        let key = encode_identity(identity);
        let mut player = self
            .players
            .get(txn, &key)?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("message owner player is missing"))?;
        player.message_filter_minimums[wire_message_class_index(class)] =
            wire_message_importance_value(minimum_importance);
        self.players
            .put(txn, &key, &encode_player_record(&player))?;
        self.message_management_in(txn, identity)
    }

    fn set_message_classification_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        message_id: u64,
        classification: MessageClassification,
    ) -> Result<RuleResult<MessageManagement>, StoreError> {
        let key = player_message_state_key(identity, message_id);
        let Some(mut state) = self
            .player_message_state
            .get(txn, &key)?
            .map(decode_player_message_state)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected(
                "that message has not been received by this captain".into(),
            ));
        };
        state.classification = classification;
        self.player_message_state
            .put(txn, &key, &encode_player_message_state(&state))?;
        Ok(RuleResult::Applied(
            self.message_management_in(txn, identity)?,
        ))
    }

    fn system_mapping_status_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        system_id: u64,
    ) -> Result<SystemMappingStatus, StoreError> {
        let record = self
            .player_system_mappings
            .get(txn, &player_system_mapping_key(identity, system_id))?
            .map(decode_player_system_mapping)
            .transpose()?
            .unwrap_or(PlayerSystemMappingRecord {
                state: SystemMappingState::Unresolved,
                dispatch_message_id: None,
                changed_second: get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0),
            });
        Ok(SystemMappingStatus {
            system_id,
            state: record.state,
            dispatch_message_id: record.dispatch_message_id,
            changed_second: record.changed_second,
        })
    }

    fn begin_system_publication_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        system_id: u64,
        message_id: u64,
        dispatched_second: u64,
    ) -> Result<(), StoreError> {
        let existing = self
            .system_publications
            .get(txn, &system_id)?
            .map(decode_system_publication)
            .transpose()?;
        if existing.is_some_and(|record| record.state == SystemPublicationState::UniversallyKnown) {
            return Ok(());
        }
        if !existing.is_some_and(|record| record.state == SystemPublicationState::Pending) {
            let pending = get_meta_u64(self.meta, txn, META_PENDING_SYSTEM_PUBLICATIONS)?
                .unwrap_or(0)
                .checked_add(1)
                .ok_or(StoreError::Corrupt("pending publication count overflow"))?;
            put_meta_u64(self.meta, txn, META_PENDING_SYSTEM_PUBLICATIONS, pending)?;
        }
        self.system_publications.put(
            txn,
            &system_id,
            &encode_system_publication(&SystemPublicationRecord {
                message_id,
                dispatched_second,
                completed_second: 0,
                state: SystemPublicationState::Pending,
            }),
        )?;
        self.refresh_system_publications_in(txn, dispatched_second)
    }

    fn refresh_system_publications_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        current_second: u64,
    ) -> Result<(), StoreError> {
        let mut pending_count =
            get_meta_u64(self.meta, txn, META_PENDING_SYSTEM_PUBLICATIONS)?.unwrap_or(0);
        if pending_count == 0 {
            return Ok(());
        }
        let pending = self
            .system_publications
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((system_id, encoded)) => match decode_system_publication(encoded) {
                    Ok(record) if record.state == SystemPublicationState::Pending => {
                        Some(Ok((system_id, record)))
                    }
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for (system_id, mut record) in pending {
            record.state = match self
                .simulation
                .broadcast_completion(txn, record.message_id)?
            {
                BroadcastCompletion::Pending => continue,
                BroadcastCompletion::Complete => {
                    record.completed_second = current_second;
                    SystemPublicationState::UniversallyKnown
                }
                BroadcastCompletion::Failed => SystemPublicationState::Failed,
            };
            self.system_publications
                .put(txn, &system_id, &encode_system_publication(&record))?;
            pending_count = pending_count
                .checked_sub(1)
                .ok_or(StoreError::Corrupt("pending publication count underflow"))?;
        }
        put_meta_u64(
            self.meta,
            txn,
            META_PENDING_SYSTEM_PUBLICATIONS,
            pending_count,
        )?;
        Ok(())
    }

    fn extend_pending_system_publications_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        destination_system_ids: &[u64],
        current_second: u64,
    ) -> Result<(), StoreError> {
        let messages = self
            .system_publications
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((_, encoded)) => match decode_system_publication(encoded) {
                    Ok(record) if record.state == SystemPublicationState::Pending => {
                        Some(Ok(record.message_id))
                    }
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for message_id in messages {
            self.simulation.extend_message_destinations(
                txn,
                current_second,
                message_id,
                destination_system_ids,
            )?;
        }
        Ok(())
    }

    fn set_system_mapping_disclosure_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        system_id: u64,
        choice: SystemMappingChoice,
    ) -> Result<RuleResult<SystemMappingStatus>, StoreError> {
        let (mut player, ship) = self.player_and_ship_in(txn, identity)?;
        if !player.known_system_ids.contains(&system_id) {
            return Ok(RuleResult::Rejected(
                "that system is not present in the captain's carried charts".into(),
            ));
        }
        let sends_notice = matches!(
            choice,
            SystemMappingChoice::PublicNotification | SystemMappingChoice::DirectEarth
        );
        if sends_notice
            && (ship.system_id != system_id
                || matches!(
                    ship.location,
                    ShipLocationRecord::InFlight(FlightLegRecord {
                        purpose: FlightLegPurpose::Jump { .. },
                        ..
                    })
                ))
        {
            return Ok(RuleResult::Rejected(
                "mapping notices can only be filed from the system being reported".into(),
            ));
        }
        let key = player_system_mapping_key(identity, system_id);
        let existing = self
            .player_system_mappings
            .get(txn, &key)?
            .map(decode_player_system_mapping)
            .transpose()?;
        if existing.is_some_and(|record| {
            matches!(
                record.state,
                SystemMappingState::KnownPublic
                    | SystemMappingState::PublicDispatched
                    | SystemMappingState::DirectDispatched
            )
        }) {
            return Ok(RuleResult::Rejected(
                "that system's mapping notice has already been committed".into(),
            ));
        }
        let now = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let system = self
            .systems
            .get(txn, &system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("mapping-notice system is missing"))?;
        let (state, dispatch_message_id) = match choice {
            SystemMappingChoice::PublicNotification => {
                let destinations = self
                    .simulation
                    .systems(txn)?
                    .into_iter()
                    .map(|system| system.system_id)
                    .collect::<Vec<_>>();
                let (message_id, _) = self.simulation.dispatch_message(
                    txn,
                    now,
                    system_id,
                    crate::simulation::MessageClass::PublicService,
                    crate::simulation::MessageImportance::Routine,
                    &format!("Public mapping notice: {}", system.name),
                    &format!(
                        "Captain {}/{} reports a mapped system at coreward/spinward/north coordinates {:.6}/{:.6}/{:.6} parsecs and submits the observation for publication.",
                        identity.bbs_id,
                        identity.player_id,
                        system.position_parsecs[0],
                        system.position_parsecs[1],
                        system.position_parsecs[2],
                    ),
                    &destinations,
                )?;
                self.begin_system_publication_in(txn, system_id, message_id, now)?;
                (SystemMappingState::PublicDispatched, Some(message_id))
            }
            SystemMappingChoice::DirectEarth => {
                if !self
                    .simulation
                    .route_exists(txn, system_id, SOL_SYSTEM_ID)?
                {
                    return Ok(RuleResult::Rejected(
                        "no known mail route reaches the Federation repository on Earth".into(),
                    ));
                }
                let hops = self
                    .simulation
                    .route_hops(txn, system_id, SOL_SYSTEM_ID)?
                    .ok_or(StoreError::Corrupt(
                        "direct mapping route disappeared during quotation",
                    ))?;
                let ttl_weeks = 60_u64.div_ceil(7);
                let tariff = hops.saturating_mul(ttl_weeks);
                if player.credits < tariff {
                    return Ok(RuleResult::Rejected(format!(
                        "the sealed filing costs Cr{tariff} for {hops} hop(s) and a {ttl_weeks}-week retention period"
                    )));
                }
                player.credits -= tariff;
                self.players.put(
                    txn,
                    &encode_identity(identity),
                    &encode_player_record(&player),
                )?;
                let (message_id, _) = self.simulation.dispatch_message(
                    txn,
                    now,
                    system_id,
                    crate::simulation::MessageClass::Private,
                    crate::simulation::MessageImportance::Important,
                    &format!(
                        "Sealed Federation mapping filing: {} by {}/{}",
                        system.name, identity.bbs_id, identity.player_id
                    ),
                    &format!(
                        "Encrypted mapping claim for {} at {:.6}/{:.6}/{:.6} parsecs, filed by captain {}/{}. The Federation repository must determine whether this is the first valid settled-system report before issuing any award.",
                        system.name,
                        system.position_parsecs[0],
                        system.position_parsecs[1],
                        system.position_parsecs[2],
                        identity.bbs_id,
                        identity.player_id,
                    ),
                    &[SOL_SYSTEM_ID],
                )?;
                (SystemMappingState::DirectDispatched, Some(message_id))
            }
            SystemMappingChoice::Withhold => (SystemMappingState::Withheld, None),
            SystemMappingChoice::WithholdSecret => (SystemMappingState::Secret, None),
        };
        let record = PlayerSystemMappingRecord {
            state,
            dispatch_message_id,
            changed_second: now,
        };
        self.player_system_mappings
            .put(txn, &key, &encode_player_system_mapping(&record))?;
        if let Some(message_id) = dispatch_message_id
            && sends_notice
        {
            self.discovery_claims.put(
                txn,
                &message_id,
                &encode_discovery_claim(&DiscoveryClaimRecord {
                    message_id,
                    system_id,
                    claimant: identity.clone(),
                    reached_earth_second: None,
                    awarded: false,
                    result_message_id: 0,
                }),
            )?;
        }
        Ok(RuleResult::Applied(SystemMappingStatus {
            system_id,
            state,
            dispatch_message_id,
            changed_second: now,
        }))
    }

    fn message_item_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        message: &crate::simulation::Message,
        available_second: u64,
        classification: MessageClassification,
        previously_seen: bool,
        knowledge_system_id: u64,
        current_second: u64,
    ) -> Result<MessageItem, StoreError> {
        let origin_system_name = self
            .systems
            .get(txn, &message.origin_system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .map(|system| system.name)
            .unwrap_or_else(|| "Unlisted origin".into());
        let stored_offer = self
            .task_offers
            .get(txn, &message.message_id.to_be_bytes())?
            .map(decode_stored_task_offer)
            .transpose()?;
        let (body, offer_id, offer_revision, offer_available) = if let Some(stored) = stored_offer {
            let offer = &stored.offer;
            let offer_available =
                self.task_offer_is_open_in(txn, &stored, knowledge_system_id, current_second)?;
            let destination = self
                .systems
                .get(txn, &offer.destination_system_id)?
                .map(decode_stellar_system)
                .transpose()?
                .map(|system| system.name)
                .unwrap_or_else(|| "an unlisted destination".into());
            let commodity = crate::commerce::commodity(offer.commodity_id)
                .map_or("not applicable", |item| item.name);
            let availability = if current_second > offer.expires_second {
                "Expired"
            } else if knowledge_system_id == offer.origin_system_id
                && stored.claimed_by.as_ref() == Some(identity)
            {
                "Awarded to your claim"
            } else if !offer_available {
                "Closed by the issuing office"
            } else {
                "Open for claim"
            };
            (
                format!(
                    "Signed offer instrument #{id}\n\nDestination: {destination}\nCommodity: {commodity}\nQuantity: {tons}.{fraction:03} tons\nPassengers: {passengers}\nPayment: Cr{payment}\nCollateral: Cr{collateral}\nFailure penalty: Cr{penalty}\nPerformances: {performances}\nRecurrence: {recurrence_days} days\nClaim closes: day {expires}\nDelivery due: day {deadline}\nStatus: {availability}",
                    id = offer.offer_id,
                    tons = offer.quantity_millitons / 1_000,
                    fraction = offer.quantity_millitons % 1_000,
                    passengers = offer.passenger_count,
                    payment = offer.payment_credits,
                    collateral = offer.collateral_credits,
                    penalty = offer.failure_penalty_credits,
                    performances = offer.performance_count,
                    recurrence_days = offer.recurrence_seconds / crate::simulation::SECONDS_PER_DAY,
                    expires = offer.expires_second / crate::simulation::SECONDS_PER_DAY,
                    deadline = offer.delivery_deadline_second / crate::simulation::SECONDS_PER_DAY,
                ),
                Some(offer.offer_id),
                offer.revision,
                offer_available,
            )
        } else {
            (message.body.clone(), None, 0, false)
        };
        let (action_kind, action_reference_id) = if offer_id.is_some() {
            (
                crate::wire::MessageActionKind::ClaimOffer,
                offer_id.unwrap_or(0),
            )
        } else {
            let mut task_reference = None;
            for entry in self.tasks.iter(txn)? {
                let (_, encoded) = entry?;
                let task = decode_stored_task(encoded)?;
                if task.identity == *identity
                    && [
                        task.task.claim_message_id,
                        task.task.result_message_id,
                        task.task.dispute_message_id,
                        task.task.adjudication_message_id,
                        task.settlement_message_id,
                        task.remittance_message_id,
                    ]
                    .contains(&message.message_id)
                {
                    task_reference = Some(task.task.task_id);
                    break;
                }
            }
            if let Some(task_id) = task_reference {
                (crate::wire::MessageActionKind::ReviewTask, task_id)
            } else {
                let identity_key = encode_identity(identity);
                let mut mapping_reference = None;
                for entry in self.player_system_mappings.iter(txn)? {
                    let (key, encoded) = entry?;
                    if key.len() == 16
                        && key[..8] == identity_key
                        && decode_player_system_mapping(encoded)?.dispatch_message_id
                            == Some(message.message_id)
                    {
                        mapping_reference = Some(decode_u64(&key[8..])?);
                        break;
                    }
                }
                if mapping_reference.is_none() {
                    for entry in self.discovery_claims.iter(txn)? {
                        let (_, encoded) = entry?;
                        let claim = decode_discovery_claim(encoded)?;
                        if claim.claimant == *identity
                            && (claim.message_id == message.message_id
                                || claim.result_message_id == message.message_id)
                        {
                            mapping_reference = Some(claim.system_id);
                            break;
                        }
                    }
                }
                if let Some(system_id) = mapping_reference {
                    (crate::wire::MessageActionKind::ReviewMapping, system_id)
                } else {
                    let career = self.career_state_in(txn, identity)?;
                    let career_reference = career
                        .opportunities
                        .iter()
                        .find(|opportunity| {
                            opportunity.order_message_id == message.message_id
                                || opportunity.report_message_id == message.message_id
                        })
                        .map(|opportunity| opportunity.opportunity_id)
                        .or_else(|| {
                            career
                                .prizes
                                .iter()
                                .find(|prize| prize.claim_message_id == message.message_id)
                                .map(|prize| prize.prize_id)
                        })
                        .or_else(|| {
                            career
                                .warrants
                                .iter()
                                .find(|warrant| {
                                    warrant.message_id == message.message_id
                                        || warrant.resolution_message_id == message.message_id
                                })
                                .map(|warrant| warrant.warrant_id)
                        });
                    if let Some(reference) = career_reference {
                        (crate::wire::MessageActionKind::ReviewOperations, reference)
                    } else {
                        let player = self
                            .players
                            .get(txn, &encode_identity(identity))?
                            .map(decode_player_record)
                            .transpose()?
                            .ok_or(StoreError::Corrupt("message owner player is missing"))?;
                        let finance = self
                            .finances
                            .get(txn, &ship_finance_key(player.ship_id))?
                            .map(decode_finance_record)
                            .transpose()?
                            .is_some_and(|record| record.impound_message_id == message.message_id);
                        if finance {
                            (
                                crate::wire::MessageActionKind::ReviewFinance,
                                message.message_id,
                            )
                        } else {
                            (crate::wire::MessageActionKind::None, 0)
                        }
                    }
                }
            }
        };
        Ok(MessageItem {
            message_id: message.message_id,
            origin_system_id: message.origin_system_id,
            origin_system_name,
            created_second: message.created_second,
            available_second,
            expires_second: message.expires_second,
            class: match message.class {
                crate::simulation::MessageClass::AgencyNews => {
                    crate::wire::MessageClass::AgencyNews
                }
                crate::simulation::MessageClass::PublicService => {
                    crate::wire::MessageClass::PublicService
                }
                crate::simulation::MessageClass::ContractOffer => {
                    crate::wire::MessageClass::ContractOffer
                }
                crate::simulation::MessageClass::TrafficNotice => {
                    crate::wire::MessageClass::TrafficNotice
                }
                crate::simulation::MessageClass::Private => crate::wire::MessageClass::Private,
            },
            importance: match message.importance {
                crate::simulation::MessageImportance::Routine => {
                    crate::wire::MessageImportance::Routine
                }
                crate::simulation::MessageImportance::Notable => {
                    crate::wire::MessageImportance::Notable
                }
                crate::simulation::MessageImportance::Important => {
                    crate::wire::MessageImportance::Important
                }
                crate::simulation::MessageImportance::Headline => {
                    crate::wire::MessageImportance::Headline
                }
            },
            subject: message.subject.clone(),
            body,
            offer_id,
            offer_revision,
            offer_available,
            classification,
            previously_seen,
            expired: current_second >= message.expires_second,
            action_kind,
            action_reference_id,
        })
    }

    fn course_nodes_in(
        &self,
        txn: &heed::RoTxn<'_>,
        known_system_ids: &[u64],
        spec: &creation::ShipStatusSpec,
        current_second: u64,
    ) -> Result<Vec<CourseNode>, StoreError> {
        let game_days = current_second as f64 / crate::simulation::SECONDS_PER_DAY as f64;
        let frontier_capable = spec.has_fuel_scoop && spec.fuel_processing_millitons_per_day > 0;
        let mut nodes = Vec::with_capacity(known_system_ids.len());
        for system_id in known_system_ids {
            let Some(system) = self
                .systems
                .get(txn, system_id)?
                .map(decode_stellar_system)
                .transpose()?
            else {
                continue;
            };
            let world = self.primary_world_in(txn, &system)?;
            let celestial = derive_celestial_system(&system)?;
            let approach =
                primary_world_jump_safety(&celestial, game_days, f64::from(spec.thrust_g));
            let frontier_round_trip_seconds = frontier_capable
                .then(|| {
                    nearest_gas_giant_fuel_source(&celestial, game_days, f64::from(spec.thrust_g))
                })
                .flatten()
                .map(|source| {
                    (source.round_trip_days * crate::simulation::SECONDS_PER_DAY as f64).ceil()
                        as u64
                });
            let refined_port = self
                .facilities
                .get(txn, &system.id)?
                .map(decode_facility)
                .transpose()?
                .is_some_and(|facility| facility.operational && facility.refined_fuel);
            let unrefined_port = self
                .facilities
                .get(txn, &system.id)?
                .map(decode_facility)
                .transpose()?
                .is_some_and(|facility| facility.operational && facility.unrefined_fuel);
            nodes.push(CourseNode {
                system_id: system.id,
                system_name: system.name,
                world_name: world.name,
                position_parsecs: system.position_parsecs,
                refined_port,
                unrefined_port,
                approach_seconds: (approach.travel_days * crate::simulation::SECONDS_PER_DAY as f64)
                    .ceil() as u64,
                frontier_round_trip_seconds,
            });
        }
        nodes.sort_by_key(|node| node.system_id);
        Ok(nodes)
    }

    fn plot_course_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        origin_system_id: u64,
        destination_system_id: u64,
        use_current_fuel: bool,
    ) -> Result<RuleResult<CoursePlot>, StoreError> {
        let (player, ship) = self.player_and_ship_in(txn, identity)?;
        if use_current_fuel && origin_system_id != ship.system_id {
            return Ok(RuleResult::Rejected(
                "a current-position course must begin in the ship's present system".into(),
            ));
        }
        if !player.known_system_ids.contains(&origin_system_id)
            || !player.known_system_ids.contains(&destination_system_id)
        {
            return Ok(RuleResult::Rejected(
                "both course endpoints must be in the captain's Known Universe".into(),
            ));
        }
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        if spec.jump_rating == 0 || spec.jump_fuel_millitons == 0 {
            return Ok(RuleResult::Rejected(
                "the commanded ship has no interstellar course capability".into(),
            ));
        }
        let current_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let nodes = self.course_nodes_in(txn, &player.known_system_ids, &spec, current_second)?;
        let initial_fuel = if use_current_fuel {
            ship.current_fuel_millitons
        } else {
            0
        };
        let fastest = calculate_course_plan(
            &nodes,
            origin_system_id,
            destination_system_id,
            &spec,
            initial_fuel,
            CoursePreference::Fastest,
        );
        let cheapest = calculate_course_plan(
            &nodes,
            origin_system_id,
            destination_system_id,
            &spec,
            initial_fuel,
            CoursePreference::Cheapest,
        );
        Ok(RuleResult::Applied(CoursePlot {
            origin_system_id,
            destination_system_id,
            jump_rating: spec.jump_rating,
            fastest,
            cheapest,
            current_game_second: current_second,
        }))
    }

    fn suggest_task_course_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<RuleResult<CoursePlot>, StoreError> {
        let (player, ship) = self.player_and_ship_in(txn, identity)?;
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        if spec.jump_rating == 0 || spec.jump_fuel_millitons == 0 {
            return Ok(RuleResult::Rejected(
                "the commanded ship has no interstellar course capability".into(),
            ));
        }
        let mut requirements = Vec::new();
        for entry in self.tasks.iter(txn)? {
            let (_, value) = entry?;
            let stored = decode_stored_task(value)?;
            let task = stored.task;
            if stored.identity != *identity
                || task.performing_ship_id != ship.ship_id
                || task.offer.destination_system_id == 0
                || !task.known_result
                || !matches!(
                    task.state,
                    crate::wire::TaskState::Accepted
                        | crate::wire::TaskState::Sourcing
                        | crate::wire::TaskState::Loading
                        | crate::wire::TaskState::InTransit
                )
            {
                continue;
            }
            let pickup_system_id = (task.state == crate::wire::TaskState::Accepted
                && matches!(
                    task.offer.kind,
                    crate::wire::TaskKind::Freight
                        | crate::wire::TaskKind::Passenger
                        | crate::wire::TaskKind::Charter
                        | crate::wire::TaskKind::Courier
                ))
            .then_some(task.offer.origin_system_id);
            requirements.push(TaskCourseRequirement {
                task_id: task.task_id,
                pickup_system_id,
                destination_system_id: task.offer.destination_system_id,
                deadline_second: task.offer.delivery_deadline_second,
            });
        }
        requirements.sort_by_key(|requirement| requirement.task_id);
        if requirements.is_empty() {
            return Ok(RuleResult::Rejected(
                "this ship has no active accepted tasks with route destinations".into(),
            ));
        }
        if requirements.iter().any(|requirement| {
            !player
                .known_system_ids
                .contains(&requirement.destination_system_id)
                || requirement
                    .pickup_system_id
                    .is_some_and(|pickup| !player.known_system_ids.contains(&pickup))
        }) {
            return Ok(RuleResult::Rejected(
                "an active task requires a system absent from the captain's Known Universe".into(),
            ));
        }
        let current_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let mut nodes =
            self.course_nodes_in(txn, &player.known_system_ids, &spec, current_second)?;
        // A suggested course is intended for direct import into Flight Plan. The
        // compact course format cannot name the body required for a frontier-fuel
        // operation, so restrict this plot to carried and port fuel.
        for node in &mut nodes {
            node.frontier_round_trip_seconds = None;
        }
        let Some(stops) = suggest_task_stop_order(
            &nodes,
            ship.system_id,
            current_second,
            spec.jump_rating,
            &requirements,
        ) else {
            return Ok(RuleResult::Rejected(
                "no bounded task-route suggestion could cover every active obligation".into(),
            ));
        };
        let destination_system_id = stops.last().copied().unwrap_or(ship.system_id);
        let fastest = calculate_course_plan_sequence(
            &nodes,
            ship.system_id,
            &stops,
            &spec,
            ship.current_fuel_millitons,
            CoursePreference::Fastest,
        );
        if !fastest.available {
            return Ok(RuleResult::Rejected(
                "no executable course through known systems can visit every required task stop"
                    .into(),
            ));
        }
        let cheapest = calculate_course_plan_sequence(
            &nodes,
            ship.system_id,
            &stops,
            &spec,
            ship.current_fuel_millitons,
            CoursePreference::Cheapest,
        );
        Ok(RuleResult::Applied(CoursePlot {
            origin_system_id: ship.system_id,
            destination_system_id,
            jump_rating: spec.jump_rating,
            fastest,
            cheapest,
            current_game_second: current_second,
        }))
    }

    fn market_snapshot_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<MarketSnapshot, StoreError> {
        let (player, ship) = self.player_and_ship_in(txn, identity)?;
        if !matches!(ship.location, ShipLocationRecord::Docked { .. }) {
            return Err(StoreError::Corrupt(
                "market requested while ship is not docked",
            ));
        }
        let system = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship system is missing"))?;
        let world = self.primary_world_in(txn, &system)?;
        let game_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let game_day = game_second / crate::simulation::SECONDS_PER_DAY;
        let market_state = self
            .markets
            .get(txn, &market_key(system.id, game_day))?
            .map(decode_market_state)
            .transpose()?
            .unwrap_or(MarketStateRecord {
                revision: 0,
                consumed_millitons: Vec::new(),
            });
        let captain = self
            .persons
            .get(txn, &player.captain_person_id)?
            .map(decode_person_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("captain person is missing"))?;
        let broker_level = captain
            .person
            .skills
            .iter()
            .find(|rating| rating.skill == crate::wire::SkillId::Broker)
            .map_or(-3, |rating| rating.level);
        let quotes = quote_market_goods(
            system.generation_seed,
            system.id,
            game_day,
            identity,
            broker_level,
            captain.person.characteristics.charisma,
            &world,
        )?;
        let tariff_basis_points = market_tariff_basis_points(&world);
        let mut events = Vec::new();
        for entry in self
            .market_events
            .prefix_iter(txn, &system.id.to_be_bytes())?
        {
            let (_, value) = entry?;
            let event = decode_market_event(value)?;
            if event.start_second <= game_second && game_second < event.expires_second {
                events.push(event);
            }
        }
        let mut offers = quotes
            .into_iter()
            .map(|quote| {
                let event = events
                    .iter()
                    .find(|event| event.commodity_id == quote.commodity.id);
                let stock_multiplier = event.map_or(10_000, |event| {
                    u64::from(event.stock_multiplier_basis_points)
                });
                let purchase = event.map_or(quote.purchase_price_per_ton, |event| {
                    shift_price_tier(
                        quote.commodity.base_price_per_ton,
                        quote.purchase_price_per_ton,
                        event.purchase_tier_delta,
                        true,
                    )
                });
                let sale = event.map_or(quote.indicative_sale_price_per_ton, |event| {
                    shift_price_tier(
                        quote.commodity.base_price_per_ton,
                        quote.indicative_sale_price_per_ton,
                        event.sale_tier_delta,
                        false,
                    )
                });
                let purchase_price = price_with_import_tariff(purchase, tariff_basis_points);
                let purchase_distribution =
                    absolute_purchase_price_distribution(quote.commodity.base_price_per_ton);
                let sale_price = non_crossing_market_bid(
                    price_after_export_tariff(sale, tariff_basis_points),
                    purchase_price,
                );
                MarketOffer {
                    offer_id: quote.offer_id,
                    commodity_id: quote.commodity.id,
                    commodity_name: quote.commodity.name.into(),
                    base_price_per_ton: quote.commodity.base_price_per_ton,
                    purchase_price_per_ton: purchase_price,
                    sale_price_per_ton: sale_price,
                    available_millitons: quote
                        .available_millitons
                        .saturating_mul(stock_multiplier)
                        .div_ceil(10_000)
                        .saturating_sub(
                            market_state
                                .consumed_millitons
                                .iter()
                                .find(|(commodity_id, _)| *commodity_id == quote.commodity.id)
                                .map_or(0, |(_, consumed)| *consumed),
                        ),
                    legality: match quote.legality {
                        crate::commerce::Legality::Legal => CommodityLegality::Legal,
                        crate::commerce::Legality::Restricted => CommodityLegality::Restricted,
                        crate::commerce::Legality::Prohibited => CommodityLegality::Prohibited,
                    },
                    price_distribution: purchase_distribution,
                }
            })
            .collect::<Vec<_>>();
        if let Some(pie) = self
            .unique_cargo
            .get(txn, &UNIQUE_APPLE_PIE_ID)?
            .map(decode_unique_cargo)
            .transpose()?
        {
            if pie.location
                == (UniqueCargoLocation::Port {
                    system_id: system.id,
                })
            {
                offers.push(MarketOffer {
                    offer_id: UNIQUE_APPLE_PIE_OFFER_ID,
                    commodity_id: pie.commodity_id,
                    commodity_name: pie.name,
                    base_price_per_ton: 1_000,
                    purchase_price_per_ton: 1_000,
                    sale_price_per_ton: 1_000,
                    available_millitons: pie.mass_millitons,
                    legality: CommodityLegality::Legal,
                    price_distribution: PriceDistribution::flat(1_000),
                });
            }
        }
        let mut cargo_sale_quotes = Vec::new();
        for lot in &ship.cargo {
            let (price_per_ton, price_distribution) = match lot.title {
                CargoTitle::PlayerOwned => {
                    let item = commodity(lot.commodity_id)
                        .ok_or(StoreError::Corrupt("cargo commodity is unknown"))?;
                    let raw_price = negotiated_sale_price(
                        system.generation_seed,
                        game_day,
                        identity,
                        lot.cargo_lot_id,
                        broker_level,
                        captain.person.characteristics.charisma,
                        item,
                        &world,
                    )?;
                    let event_price = events
                        .iter()
                        .find(|event| event.commodity_id == lot.commodity_id)
                        .map_or(raw_price, |event| {
                            shift_price_tier(
                                item.base_price_per_ton,
                                raw_price,
                                event.sale_tier_delta,
                                false,
                            )
                        });
                    let bid = price_after_export_tariff(event_price, tariff_basis_points);
                    let current_bid = offers
                        .iter()
                        .find(|offer| offer.commodity_id == lot.commodity_id)
                        .map_or(bid, |offer| {
                            non_crossing_market_bid(bid, offer.purchase_price_per_ton)
                        });
                    let distribution = absolute_sale_price_distribution(item.base_price_per_ton);
                    (current_bid, distribution)
                }
                CargoTitle::UniqueObject => (1_000, PriceDistribution::flat(1_000)),
                CargoTitle::Freight | CargoTitle::Contract => continue,
            };
            cargo_sale_quotes.push(CargoSaleQuote {
                cargo_lot_id: lot.cargo_lot_id,
                price_per_ton,
                price_distribution,
            });
        }
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let cargo_used_millitons = ship.cargo.iter().map(|lot| lot.quantity_millitons).sum();
        let local_task_offers = self.local_task_offers_in(txn, identity, &ship)?;
        let work_assignments = self.work_assignments_in(txn, identity)?;
        let mut leads = Vec::new();
        for entry in self.market_leads.iter(txn)? {
            let (_, value) = entry?;
            let mut stored = decode_market_lead(value)?;
            if stored.identity == *identity && stored.lead.system_id == system.id {
                if stored.lead.state == crate::wire::MarketLeadState::Reserved
                    && stored.lead.reservation_expires_second <= game_second
                {
                    stored.lead.state = crate::wire::MarketLeadState::Expired;
                }
                leads.push(stored.lead);
            }
        }
        leads.sort_by_key(|lead| (lead.expires_second, lead.lead_id));
        events.sort_by_key(|event| (event.expires_second, event.event_id));
        Ok(MarketSnapshot {
            market_revision: market_state.revision,
            system_id: system.id,
            world_name: world.name.clone(),
            generated_day: game_day,
            credits: player.credits,
            cargo_used_millitons,
            cargo_capacity_millitons: effective_cargo_capacity(&ship, &spec),
            offers,
            cargo: ship.cargo,
            trade_codes: crate::commerce::world_trade_codes(&world)
                .into_iter()
                .map(|code| code.label().to_owned())
                .collect(),
            tariff_basis_points,
            local_task_offers,
            work_assignments,
            leads,
            events,
            cargo_sale_quotes,
        })
    }

    fn local_task_offers_in(
        &self,
        txn: &heed::RoTxn<'_>,
        _identity: &PlayerIdentity,
        ship: &ShipRecord,
    ) -> Result<Vec<crate::wire::TaskOffer>, StoreError> {
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let mut offers = Vec::new();
        for available in self
            .simulation
            .available_messages(txn, ship.system_id, current, false)?
        {
            if available.message.class != crate::simulation::MessageClass::ContractOffer {
                continue;
            }
            let Some(stored) = self
                .task_offers
                .get(txn, &available.message.message_id.to_be_bytes())?
                .map(decode_stored_task_offer)
                .transpose()?
            else {
                continue;
            };
            if self.task_offer_is_open_in(txn, &stored, ship.system_id, current)? {
                offers.push(stored.offer);
            }
        }
        offers.sort_by_key(|offer| (offer.expires_second, offer.offer_id));
        Ok(offers)
    }

    fn task_offer_is_open_in(
        &self,
        txn: &heed::RoTxn<'_>,
        stored: &StoredTaskOffer,
        system_id: u64,
        current: u64,
    ) -> Result<bool, StoreError> {
        let closure_received = if stored.closure_message_id == 0 {
            false
        } else {
            self.simulation
                .available_messages(txn, system_id, current, true)?
                .iter()
                .any(|available| available.message.message_id == stored.closure_message_id)
        };
        Ok(task_offer_is_open_at_system(
            stored,
            system_id,
            current,
            closure_received,
        ))
    }

    fn carriage_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<crate::wire::CarriageDeclaration, StoreError> {
        Ok(self
            .carriage_declarations
            .get(txn, &encode_identity(identity))?
            .map(decode_carriage_declaration)
            .transpose()?
            .unwrap_or_default())
    }
    fn work_assignments_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<Vec<crate::wire::WorkAssignment>, StoreError> {
        let mut out = Vec::new();
        for entry in self.work_assignments.iter(txn)? {
            let (_, value) = entry?;
            let stored = decode_stored_work_assignment(value)?;
            if stored.identity == *identity {
                out.push(stored.assignment);
            }
        }
        out.sort_by_key(|w| w.assignment_id);
        Ok(out)
    }
    fn task_ledger_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<crate::wire::TaskLedger, StoreError> {
        let (player, ship) = self.player_and_ship_in(txn, identity)?;
        let mut tasks = Vec::new();
        for entry in self.tasks.iter(txn)? {
            let (_, value) = entry?;
            let stored = decode_stored_task(value)?;
            if stored.identity == *identity {
                tasks.push(stored.task);
            }
        }
        tasks.sort_by_key(|t| t.task_id);
        let reserved_credits = tasks
            .iter()
            .filter(|t| {
                !matches!(
                    t.state,
                    crate::wire::TaskState::Completed
                        | crate::wire::TaskState::Expired
                        | crate::wire::TaskState::Cancelled
                        | crate::wire::TaskState::Defaulted
                )
            })
            .map(|t| t.reserved_credits)
            .sum();
        let unsettled = |task: &&crate::wire::TaskRecord| {
            !matches!(
                task.state,
                crate::wire::TaskState::Completed
                    | crate::wire::TaskState::Expired
                    | crate::wire::TaskState::Cancelled
                    | crate::wire::TaskState::Defaulted
            )
        };
        let reserved_cargo_millitons = tasks
            .iter()
            .filter(unsettled)
            .map(|t| t.reserved_cargo_millitons)
            .sum();
        let ship_reserved_cargo_millitons = tasks
            .iter()
            .filter(unsettled)
            .filter(|task| task.performing_ship_id == ship.ship_id)
            .map(|task| task.reserved_cargo_millitons)
            .sum();
        let reserved_passenger_count = tasks
            .iter()
            .filter(unsettled)
            .map(|t| t.reserved_passenger_count)
            .sum();
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship status data missing"))?;
        let cargo_used_millitons = ship
            .cargo
            .iter()
            .map(|lot| lot.quantity_millitons)
            .sum::<u64>();
        let occupied_regular_berths = ship
            .passengers
            .iter()
            .filter(|manifest| manifest.passenger_class != crate::wire::PassengerClass::Low)
            .map(|manifest| manifest.passenger_count)
            .fold(0_u16, u16::saturating_add);
        let occupied_low_berths = ship
            .passengers
            .iter()
            .filter(|manifest| manifest.passenger_class == crate::wire::PassengerClass::Low)
            .map(|manifest| manifest.passenger_count)
            .fold(0_u16, u16::saturating_add);
        let reserved_regular_berths = tasks
            .iter()
            .filter(unsettled)
            .filter(|task| task.performing_ship_id == ship.ship_id)
            .filter(|task| task.offer.passenger_class != crate::wire::PassengerClass::Low)
            .map(|task| task.reserved_passenger_count)
            .fold(0_u16, u16::saturating_add);
        let reserved_low_berths = tasks
            .iter()
            .filter(unsettled)
            .filter(|task| task.performing_ship_id == ship.ship_id)
            .filter(|task| task.offer.passenger_class == crate::wire::PassengerClass::Low)
            .map(|task| task.reserved_passenger_count)
            .fold(0_u16, u16::saturating_add);
        let has_steward = self.ship_has_crew_skill_in(
            txn,
            identity,
            ship.ship_id,
            crate::wire::SkillId::Etiquette,
        )?;
        let has_medic = self.ship_has_crew_skill_in(
            txn,
            identity,
            ship.ship_id,
            crate::wire::SkillId::Medicine,
        )?;
        let current_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let current_berth_fee = match ship.location {
            ShipLocationRecord::Docked { arrived_second, .. } => {
                crate::ship_condition::berth_fee_credits(arrived_second, current_second)
            }
            _ => 0,
        };
        let restricted_credits = self
            .finances
            .get(txn, &ship_finance_key(ship.ship_id))?
            .map(decode_finance_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship finance record is missing"))?
            .restricted_credits;
        let liquid_berth_fee = current_berth_fee.saturating_sub(restricted_credits);
        let unreserved_credits = player.credits.saturating_sub(reserved_credits);
        let mut local_offers = if matches!(ship.location, ShipLocationRecord::Docked { .. }) {
            self.local_task_offers_in(txn, identity, &ship)?
        } else {
            Vec::new()
        };
        for offer in &mut local_offers {
            let reasons = &mut offer.unavailable_reasons;
            if tasks
                .iter()
                .any(|task| task.offer.offer_id == offer.offer_id)
            {
                reasons.push("This offer has already been accepted.".into());
            }
            if unreserved_credits >= offer.collateral_credits
                && unreserved_credits.saturating_sub(offer.collateral_credits) < liquid_berth_fee
            {
                let remaining = unreserved_credits.saturating_sub(offer.collateral_credits);
                reasons.push(format!(
                    "Posting the collateral leaves Cr{remaining}; Cr{liquid_berth_fee} remains due to clear the current berth after applying ship credit."
                ));
            }
            if offer.kind == crate::wire::TaskKind::Freight {
                let available = effective_cargo_capacity(&ship, &spec)
                    .saturating_sub(cargo_used_millitons)
                    .saturating_sub(ship_reserved_cargo_millitons);
                if available < offer.quantity_millitons {
                    reasons.push(format!(
                        "The contract needs {:.3} t of hold space; only {:.3} t is uncommitted.",
                        offer.quantity_millitons as f64 / 1_000.0,
                        available as f64 / 1_000.0
                    ));
                }
            } else if matches!(
                offer.kind,
                crate::wire::TaskKind::PurchaseOrder
                    | crate::wire::TaskKind::ForwardSale
                    | crate::wire::TaskKind::SupplyCommitment
            ) && effective_cargo_capacity(&ship, &spec) < offer.quantity_millitons
            {
                reasons.push(format!(
                    "The contract needs {:.3} t of hold capacity; this ship has {:.3} t.",
                    offer.quantity_millitons as f64 / 1_000.0,
                    effective_cargo_capacity(&ship, &spec) as f64 / 1_000.0
                ));
            }
            if matches!(
                offer.kind,
                crate::wire::TaskKind::Passenger
                    | crate::wire::TaskKind::Charter
                    | crate::wire::TaskKind::Courier
            ) {
                let (capacity, occupied, reserved, accommodation) =
                    if offer.passenger_class == crate::wire::PassengerClass::Low {
                        (
                            spec.low_berths,
                            occupied_low_berths,
                            reserved_low_berths,
                            "low berths",
                        )
                    } else {
                        (
                            spec.passenger_berths,
                            occupied_regular_berths,
                            reserved_regular_berths,
                            "passenger berths",
                        )
                    };
                let available = capacity.saturating_sub(occupied).saturating_sub(reserved);
                if available < offer.passenger_count {
                    reasons.push(format!(
                        "The contract needs {} {accommodation}; only {available} are uncommitted.",
                        offer.passenger_count
                    ));
                }
            }
            if matches!(
                offer.passenger_class,
                crate::wire::PassengerClass::High | crate::wire::PassengerClass::Middle
            ) && !has_steward
            {
                reasons.push("No qualified steward is aboard for high or middle passage.".into());
            }
            if offer.passenger_class == crate::wire::PassengerClass::Low && !has_medic {
                reasons.push("No qualified medical attendant is aboard for low passage.".into());
            }
        }
        let route_assessments = if local_offers.is_empty() {
            Vec::new()
        } else {
            let nodes =
                self.course_nodes_in(txn, &player.known_system_ids, &spec, current_second)?;
            let mut pickup_routes = HashMap::new();
            let mut assessments = Vec::with_capacity(local_offers.len());
            for offer in &local_offers {
                let pickup = pickup_routes
                    .entry(offer.origin_system_id)
                    .or_insert_with(|| {
                        calculate_course_plan(
                            &nodes,
                            ship.system_id,
                            offer.origin_system_id,
                            &spec,
                            ship.current_fuel_millitons,
                            CoursePreference::Fastest,
                        )
                    });
                let pickup_available = pickup.available;
                let pickup_arrival_second = current_second.saturating_add(pickup.elapsed_seconds);
                let (delivery_available, delivery_arrival_second) = if offer.destination_system_id
                    == 0
                {
                    (pickup_available, pickup_arrival_second)
                } else {
                    let itinerary = calculate_course_plan_through(
                        &nodes,
                        ship.system_id,
                        offer.destination_system_id,
                        Some(offer.origin_system_id),
                        Some(offer.expires_second.saturating_sub(current_second)),
                        &spec,
                        ship.current_fuel_millitons,
                        CoursePreference::Fastest,
                    );
                    debug_assert!(
                        !itinerary.plan.available || itinerary.checkpoint_elapsed_seconds.is_some()
                    );
                    (
                        itinerary.plan.available,
                        current_second.saturating_add(itinerary.plan.elapsed_seconds),
                    )
                };
                assessments.push(TaskRouteAssessment {
                    offer_id: offer.offer_id,
                    pickup_available,
                    pickup_arrival_second,
                    delivery_available,
                    delivery_arrival_second,
                });
            }
            assessments
        };
        Ok(crate::wire::TaskLedger {
            current_second,
            available_credits: unreserved_credits,
            reserved_credits,
            reserved_cargo_millitons,
            reserved_passenger_count,
            tasks,
            local_offers,
            carriage: self.carriage_in(txn, identity)?,
            route_assessments,
        })
    }

    fn reserve_market_lead_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        lead_id: u64,
        expected_revision: u64,
        quantity_millitons: u64,
    ) -> Result<RuleResult<MarketSnapshot>, StoreError> {
        if quantity_millitons == 0 || quantity_millitons % 1_000 != 0 {
            return Ok(RuleResult::Rejected(
                "reservations require a positive whole-ton quantity".into(),
            ));
        }
        let key = lead_id.to_be_bytes();
        let Some(mut stored) = self
            .market_leads
            .get(txn, &key)?
            .map(decode_market_lead)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected(
                "market lead is no longer available".into(),
            ));
        };
        let (mut player, ship) = self.player_and_ship_in(txn, identity)?;
        let now = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        if stored.identity != *identity || stored.lead.system_id != ship.system_id {
            return Ok(RuleResult::Rejected(
                "market lead is not locally actionable by this captain".into(),
            ));
        }
        if stored.lead.revision != expected_revision
            || stored.lead.state != crate::wire::MarketLeadState::Available
            || stored.lead.expires_second <= now
        {
            return Ok(RuleResult::Rejected(
                "market lead revision or availability changed".into(),
            ));
        }
        if quantity_millitons > stored.lead.quantity_millitons {
            return Ok(RuleResult::Rejected(
                "reservation exceeds the finite lead quantity".into(),
            ));
        }
        let transaction_value = stored
            .lead
            .price_per_ton
            .checked_mul(quantity_millitons)
            .ok_or(StoreError::Corrupt("market lead value overflow"))?
            .div_ceil(1_000);
        let escrow = transaction_value.div_ceil(10);
        if player.credits < escrow {
            return Ok(RuleResult::Rejected(
                "insufficient credits for the ten-percent escrow".into(),
            ));
        }
        player.credits -= escrow;
        stored.lead.quantity_millitons = quantity_millitons;
        stored.lead.escrow_credits = escrow;
        stored.lead.reservation_expires_second =
            now.saturating_add(3 * crate::simulation::SECONDS_PER_DAY);
        stored.lead.state = crate::wire::MarketLeadState::Reserved;
        stored.lead.revision = stored.lead.revision.saturating_add(1);
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.market_leads
            .put(txn, &key, &encode_market_lead(&stored)?)?;
        Ok(RuleResult::Applied(self.market_snapshot_in(txn, identity)?))
    }

    fn release_market_reservation_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        lead_id: u64,
        expected_revision: u64,
    ) -> Result<RuleResult<MarketSnapshot>, StoreError> {
        let key = lead_id.to_be_bytes();
        let Some(mut stored) = self
            .market_leads
            .get(txn, &key)?
            .map(decode_market_lead)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected("market reservation is missing".into()));
        };
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        if stored.identity != *identity
            || stored.lead.system_id != ship.system_id
            || stored.lead.revision != expected_revision
            || stored.lead.state != crate::wire::MarketLeadState::Reserved
        {
            return Ok(RuleResult::Rejected(
                "market reservation revision or ownership changed".into(),
            ));
        }
        stored.lead.state = crate::wire::MarketLeadState::Cancelled;
        stored.lead.revision = stored.lead.revision.saturating_add(1);
        self.market_leads
            .put(txn, &key, &encode_market_lead(&stored)?)?;
        Ok(RuleResult::Applied(self.market_snapshot_in(txn, identity)?))
    }

    fn apply_task_action_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        task_id: u64,
        expected_revision: u64,
        action: crate::wire::TaskActionKind,
        explanation: &str,
    ) -> Result<RuleResult<crate::wire::TaskLedger>, StoreError> {
        let key = task_id.to_be_bytes();
        let Some(mut stored) = self
            .tasks
            .get(txn, &key)?
            .map(decode_stored_task)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected(
                "task is not in this captain's ledger".into(),
            ));
        };
        if stored.identity != *identity || stored.task.revision != expected_revision {
            return Ok(RuleResult::Rejected(
                "task ownership or revision changed".into(),
            ));
        }
        if matches!(
            stored.task.state,
            crate::wire::TaskState::Completed
                | crate::wire::TaskState::Expired
                | crate::wire::TaskState::Cancelled
                | crate::wire::TaskState::Defaulted
        ) {
            return Ok(RuleResult::Rejected(
                "a settled task cannot be changed".into(),
            ));
        }
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        if stored.task.performing_ship_id != ship.ship_id {
            return Ok(RuleResult::Rejected(
                "select the vessel carrying this obligation before changing it".into(),
            ));
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        match action {
            crate::wire::TaskActionKind::WithdrawClaim => {
                if stored.task.state != crate::wire::TaskState::ClaimPending
                    || stored.task.loaded_second != 0
                {
                    return Ok(RuleResult::Rejected(
                        "only an unresolved, unladen claim may be withdrawn".into(),
                    ));
                }
                stored.task.state = crate::wire::TaskState::Cancelled;
                stored.task.status_text =
                    "Claim withdrawn before custody transferred; no liability assessed".into();
            }
            crate::wire::TaskActionKind::Cancel => {
                if stored.task.loaded_second != 0
                    || matches!(
                        stored.task.state,
                        crate::wire::TaskState::InTransit
                            | crate::wire::TaskState::AwaitingSettlement
                    )
                {
                    return Ok(RuleResult::Rejected(
                        "custody has transferred; return the consignment or declare default".into(),
                    ));
                }
                stored.task.state = crate::wire::TaskState::Cancelled;
                stored.task.status_text =
                    "Task cancelled before custody transferred; reserved capacity released".into();
            }
            crate::wire::TaskActionKind::ReturnCustody => {
                if ship.system_id != stored.task.offer.origin_system_id
                    || !matches!(ship.location, ShipLocationRecord::Docked { .. })
                {
                    return Ok(RuleResult::Rejected(
                        "cargo or passengers may only be returned while docked at the origin"
                            .into(),
                    ));
                }
                let before = ship.cargo.len();
                ship.cargo.retain(|lot| lot.task_id != task_id);
                let passenger_before = ship.passengers.len();
                ship.passengers
                    .retain(|manifest| manifest.task_id != task_id);
                if stored.task.loaded_second == 0
                    && before == ship.cargo.len()
                    && passenger_before == ship.passengers.len()
                {
                    return Ok(RuleResult::Rejected(
                        "no custody has transferred under this task".into(),
                    ));
                }
                ship.revision = ship.revision.saturating_add(1);
                stored.task.state = crate::wire::TaskState::Cancelled;
                stored.task.status_text = "Custody returned at origin; collateral released".into();
                self.ships
                    .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
            }
            crate::wire::TaskActionKind::DefaultTask => {
                let cargo_before = ship.cargo.len();
                let passenger_before = ship.passengers.len();
                ship.cargo.retain(|lot| lot.task_id != task_id);
                ship.passengers
                    .retain(|manifest| manifest.task_id != task_id);
                if cargo_before != ship.cargo.len() || passenger_before != ship.passengers.len() {
                    ship.revision = ship.revision.saturating_add(1);
                }
                let assessment = stored
                    .task
                    .reserved_credits
                    .saturating_add(stored.task.offer.failure_penalty_credits)
                    .saturating_add(stored.task.offer.non_delivery_liability_credits);
                let paid = assessment.min(player.credits);
                player.credits -= paid;
                stored.task.state = crate::wire::TaskState::Defaulted;
                stored.task.settled_second = current;
                stored.task.status_text =
                    format!("Default entered; Cr{paid} assessed against available funds");
                self.players.put(
                    txn,
                    &encode_identity(identity),
                    &encode_player_record(&player),
                )?;
                self.ships
                    .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
            }
            crate::wire::TaskActionKind::FileDispute => {
                if explanation.trim().is_empty() {
                    return Ok(RuleResult::Rejected(
                        "a dispute filing requires a statement of grounds".into(),
                    ));
                }
                if stored.task.dispute_message_id != 0 {
                    return Ok(RuleResult::Rejected(
                        "a dispute filing is already in transit".into(),
                    ));
                }
                let systems = self.simulation.systems(txn)?;
                if crate::simulation::shortest_route(
                    &systems,
                    ship.system_id,
                    stored.task.offer.origin_system_id,
                )
                .is_none()
                {
                    return Ok(RuleResult::Rejected(
                        "no known mail route reaches the issuing office".into(),
                    ));
                }
                let captain_service = self
                    .crew_services
                    .get(txn, &ship.commanding_person_id)?
                    .map(decode_crew_service)
                    .transpose()?
                    .ok_or(StoreError::Corrupt("commanding captain service is missing"))?;
                let captain = self
                    .persons
                    .get(txn, &ship.commanding_person_id)?
                    .map(decode_person_record)
                    .transpose()?
                    .ok_or(StoreError::Corrupt("commanding captain person is missing"))?;
                if !service_available_for_duty(&captain_service, current)
                    || person_incapacitated(&captain)
                    || captain_service.assigned_slot_ids.is_empty()
                {
                    return Ok(RuleResult::Rejected(
                        "a conscious commanding officer on watch must sign the filing".into(),
                    ));
                }
                let evidence_dm = i8::from(stored.task.loaded_second != 0)
                    + i8::from(stored.task.delivered_quantity_millitons != 0)
                    + i8::from(stored.task.known_result);
                let common = crate::task_resolution::TaskRequest {
                    characteristic: captain.person.characteristics.education,
                    skill: crate::wire::SkillId::Admin,
                    difficulty: 8,
                    equipment_dm: 0,
                    condition_dm: person_condition_dm(&captain).saturating_add(
                        crate::personnel::discretionary_morale_dm(captain_service.morale),
                    ),
                    assistance_dm: evidence_dm,
                    entropy: crate::ship_condition::mix64(
                        task_id ^ current ^ captain.person_id.rotate_left(23),
                    ),
                };
                let admin = crate::task_resolution::resolve(&captain.person, common);
                let advocate = crate::task_resolution::resolve(
                    &captain.person,
                    crate::task_resolution::TaskRequest {
                        skill: crate::wire::SkillId::Advocate,
                        entropy: common.entropy ^ 0x4144_564f_4341_5445,
                        ..common
                    },
                );
                let (filing_skill, filing_effect) = if advocate.effect > admin.effect {
                    ("Advocate", advocate.effect)
                } else {
                    ("Admin", admin.effect)
                };
                let (message_id, _) = self.simulation.dispatch_message(
                    txn,
                    current,
                    ship.system_id,
                    crate::simulation::MessageClass::Private,
                    crate::simulation::MessageImportance::Important,
                    &format!("Sealed dispute on task {}", stored.task.task_id),
                    &format!(
                        "Captain {}/{} disputes task {} on these grounds: {} The sealed filing cites the task instrument, custody ledger, delivery ledger, and received correspondence. {} effect: {:+}.",
                        identity.bbs_id,
                        identity.player_id,
                        stored.task.task_id,
                        explanation.trim(),
                        filing_skill,
                        filing_effect,
                    ),
                    &[stored.task.offer.origin_system_id],
                )?;
                stored.task.dispute_message_id = message_id;
                stored.task.dispute_effect = filing_effect;
                stored.task.state = crate::wire::TaskState::Disputed;
                stored.task.status_text = format!(
                    "Sealed dispute filing {message_id} is in transit to the issuing office"
                );
            }
        }
        stored.task.revision = stored.task.revision.saturating_add(1);
        if action != crate::wire::TaskActionKind::FileDispute {
            stored.task.reserved_credits = 0;
            stored.task.reserved_cargo_millitons = 0;
            stored.task.reserved_passenger_count = 0;
        }
        self.tasks.put(txn, &key, &encode_stored_task(&stored)?)?;
        Ok(RuleResult::Applied(self.task_ledger_in(txn, identity)?))
    }

    fn dispatch_task_offer_closure_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        offer: &crate::wire::TaskOffer,
        current: u64,
    ) -> Result<u64, StoreError> {
        let systems = self.simulation.systems(txn)?;
        let origin = systems
            .iter()
            .find(|system| system.system_id == offer.origin_system_id)
            .ok_or(StoreError::Corrupt("offer origin system is missing"))?;
        let destinations = systems
            .iter()
            .filter(|system| {
                system.system_id != offer.origin_system_id
                    && system.polity_id == origin.polity_id
                    && crate::simulation::shortest_route(
                        &systems,
                        offer.origin_system_id,
                        system.system_id,
                    )
                    .is_some_and(|route| route.len().saturating_sub(1) <= 2)
            })
            .map(|system| system.system_id)
            .collect::<Vec<_>>();
        let (message_id, _) = self.simulation.dispatch_message(
            txn,
            current,
            offer.origin_system_id,
            crate::simulation::MessageClass::PublicService,
            crate::simulation::MessageImportance::Notable,
            &format!("Offer {} closed", offer.offer_id),
            &format!(
                "The issuing office has awarded signed offer {}. No later claim will be accepted.",
                offer.offer_id
            ),
            &destinations,
        )?;
        Ok(message_id)
    }

    fn process_task_claim_mail_arrival_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        system_id: u64,
        current: u64,
    ) -> Result<(), StoreError> {
        let available = self
            .simulation
            .available_messages(txn, system_id, current, false)?;
        let arrival_order = available
            .into_iter()
            .map(|item| (item.message.message_id, item.available_second))
            .collect::<HashMap<_, _>>();
        let pending = self
            .tasks
            .iter(txn)?
            .map(|entry| {
                let (key, value) = entry?;
                Ok((key.to_vec(), decode_stored_task(value)?))
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        let mut by_offer: HashMap<u64, Vec<(Vec<u8>, StoredTask, u64)>> = HashMap::new();
        let mut disputes = Vec::new();
        for (key, task) in pending {
            if task.task.offer.origin_system_id == system_id
                && task.task.state == crate::wire::TaskState::ClaimPending
                && task.task.claim_message_id != 0
                && task.task.result_message_id == 0
            {
                if let Some(available_second) = arrival_order.get(&task.task.claim_message_id) {
                    by_offer.entry(task.task.offer.offer_id).or_default().push((
                        key,
                        task,
                        *available_second,
                    ));
                }
            } else if task.task.offer.origin_system_id == system_id
                && task.task.state == crate::wire::TaskState::Disputed
                && task.task.dispute_message_id != 0
                && task.task.adjudication_message_id == 0
                && arrival_order.contains_key(&task.task.dispute_message_id)
            {
                disputes.push((key, task));
            }
        }
        if by_offer.is_empty() && disputes.is_empty() {
            return Ok(());
        }
        let destinations = self
            .simulation
            .systems(txn)?
            .into_iter()
            .map(|s| s.system_id)
            .collect::<Vec<_>>();
        for (key, mut dispute) in disputes {
            let sustained = dispute.task.dispute_effect >= 0;
            let subject = if sustained {
                format!("Dispute {} sustained", dispute.task.task_id)
            } else {
                format!("Dispute {} denied", dispute.task.task_id)
            };
            let body = if sustained {
                "The issuing office accepts the signed filing and objective custody and delivery records. Collateral and reserved capacity are released without a non-performance assessment."
            } else {
                "The issuing office finds that the signed filing and objective custody and delivery records do not excuse performance. The contractual assessment remains due."
            };
            let (message_id, _) = self.simulation.dispatch_message(
                txn,
                current,
                system_id,
                crate::simulation::MessageClass::Private,
                crate::simulation::MessageImportance::Important,
                &subject,
                body,
                &destinations,
            )?;
            self.private_message_recipients.put(
                txn,
                &message_id.to_be_bytes(),
                &encode_private_message_recipient(&PrivateMessageRecipientRecord {
                    message_id,
                    recipient_kind: crate::wire::PrivateRecipientKind::Captain,
                    destination_system_id: 0,
                    recipient: dispute.identity.clone(),
                    encryption_key_id: (u64::from(dispute.identity.bbs_id) << 32)
                        | u64::from(dispute.identity.player_id),
                    revoked: false,
                }),
            )?;
            dispute.task.adjudication_message_id = message_id;
            dispute.task.status_text = if sustained {
                "The issuing office sustained the dispute; its sealed ruling is in transit".into()
            } else {
                "The issuing office denied the dispute; its sealed ruling is in transit".into()
            };
            dispute.task.revision = dispute.task.revision.saturating_add(1);
            self.tasks.put(txn, &key, &encode_stored_task(&dispute)?)?;
        }
        for (offer_id, mut claims) in by_offer {
            claims.sort_by_key(|(_, task, available_second)| {
                (
                    *available_second,
                    task.task.claim_message_id,
                    task.task.task_id,
                )
            });
            let Some(mut offer) = self
                .task_offers
                .get(txn, &offer_id.to_be_bytes())?
                .map(decode_stored_task_offer)
                .transpose()?
            else {
                continue;
            };
            let winner = if offer.claimed_by.is_none() {
                let winner = claims[0].1.clone();
                offer.claimed_by = Some(winner.identity.clone());
                offer.claimed_task_id = winner.task.task_id;
                offer.closure_message_id =
                    self.dispatch_task_offer_closure_in(txn, &offer.offer, current)?;
                self.task_offers.put(
                    txn,
                    &offer_id.to_be_bytes(),
                    &encode_stored_task_offer(&offer)?,
                )?;
                Some(winner.task.task_id)
            } else {
                Some(offer.claimed_task_id)
            };
            for (key, mut claim, _) in claims {
                let won = winner == Some(claim.task.task_id);
                let subject = if won {
                    format!("Claim {} awarded", offer_id)
                } else {
                    format!("Claim {} declined", offer_id)
                };
                let body = if won {
                    "The issuing office received your claim first. Report under the signed terms; the reservation remains binding."
                } else {
                    "An earlier valid claim reached the issuing office. Your capacity and collateral reservation is released."
                };
                let (message_id, _) = self.simulation.dispatch_message(
                    txn,
                    current,
                    system_id,
                    crate::simulation::MessageClass::Private,
                    crate::simulation::MessageImportance::Important,
                    &subject,
                    body,
                    &destinations,
                )?;
                self.private_message_recipients.put(
                    txn,
                    &message_id.to_be_bytes(),
                    &encode_private_message_recipient(&PrivateMessageRecipientRecord {
                        message_id,
                        recipient_kind: crate::wire::PrivateRecipientKind::Captain,
                        destination_system_id: 0,
                        recipient: claim.identity.clone(),
                        encryption_key_id: (u64::from(claim.identity.bbs_id) << 32)
                            | u64::from(claim.identity.player_id),
                        revoked: false,
                    }),
                )?;
                claim.task.result_message_id = message_id;
                claim.task.status_text = "The issuing office has mailed its ruling; local instruments remain unchanged until that reply reaches the captain".into();
                claim.task.revision = claim.task.revision.saturating_add(1);
                self.tasks.put(txn, &key, &encode_stored_task(&claim)?)?;
            }
        }
        Ok(())
    }

    fn deliver_player_carried_task_claims_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        ship_id: u64,
        destination_system_id: u64,
        current: u64,
    ) -> Result<(), StoreError> {
        let claim_message_ids = self
            .tasks
            .iter(txn)?
            .map(|entry| {
                let (_, value) = entry?;
                decode_stored_task(value)
            })
            .collect::<Result<Vec<_>, StoreError>>()?
            .into_iter()
            .filter(|stored| {
                stored.identity == *identity
                    && stored.task.performing_ship_id == ship_id
                    && stored.task.state == crate::wire::TaskState::ClaimPending
                    && stored.task.offer.origin_system_id == destination_system_id
                    && stored.task.claim_message_id != 0
                    && stored.task.result_message_id == 0
            })
            .map(|stored| stored.task.claim_message_id)
            .collect::<Vec<_>>();
        for message_id in claim_message_ids {
            self.simulation.deliver_player_carried_message(
                txn,
                message_id,
                destination_system_id,
                current,
            )?;
        }
        Ok(())
    }

    fn deliver_player_carried_task_settlements_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        ship_id: u64,
        destination_system_id: u64,
        current: u64,
    ) -> Result<(), StoreError> {
        let message_ids = self
            .tasks
            .iter(txn)?
            .map(|entry| {
                let (_, value) = entry?;
                decode_stored_task(value)
            })
            .collect::<Result<Vec<_>, StoreError>>()?
            .into_iter()
            .filter(|stored| {
                stored.identity == *identity
                    && stored.task.performing_ship_id == ship_id
                    && stored.task.state == crate::wire::TaskState::AwaitingSettlement
                    && stored.task.offer.origin_system_id == destination_system_id
                    && stored.settlement_message_id != 0
                    && stored.remittance_message_id == 0
            })
            .map(|stored| stored.settlement_message_id)
            .collect::<Vec<_>>();
        for message_id in message_ids {
            self.simulation.deliver_player_carried_message(
                txn,
                message_id,
                destination_system_id,
                current,
            )?;
        }
        Ok(())
    }

    fn process_task_settlement_mail_arrival_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        system_id: u64,
        current: u64,
    ) -> Result<(), StoreError> {
        let available = self
            .simulation
            .available_messages(txn, system_id, current, false)?
            .into_iter()
            .map(|available| available.message.message_id)
            .collect::<HashSet<_>>();
        let pending = self
            .tasks
            .iter(txn)?
            .map(|entry| {
                let (key, value) = entry?;
                Ok((key.to_vec(), decode_stored_task(value)?))
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        let destinations = self
            .simulation
            .systems(txn)?
            .into_iter()
            .map(|system| system.system_id)
            .collect::<Vec<_>>();
        for (key, mut stored) in pending {
            if stored.task.state != crate::wire::TaskState::AwaitingSettlement
                || stored.task.offer.origin_system_id != system_id
                || stored.settlement_message_id == 0
                || stored.remittance_message_id != 0
                || !available.contains(&stored.settlement_message_id)
            {
                continue;
            }
            let (message_id, _) = self.simulation.dispatch_message(
                txn,
                current,
                system_id,
                crate::simulation::MessageClass::Private,
                crate::simulation::MessageImportance::Important,
                &format!("Task {} remittance", stored.task.task_id),
                &format!(
                    "The issuing office approves Cr{} for task {} and releases the posted collateral.",
                    stored.pending_payment_credits, stored.task.task_id
                ),
                &destinations,
            )?;
            self.private_message_recipients.put(
                txn,
                &message_id.to_be_bytes(),
                &encode_private_message_recipient(&PrivateMessageRecipientRecord {
                    message_id,
                    recipient_kind: crate::wire::PrivateRecipientKind::Captain,
                    destination_system_id: 0,
                    recipient: stored.identity.clone(),
                    encryption_key_id: (u64::from(stored.identity.bbs_id) << 32)
                        | u64::from(stored.identity.player_id),
                    revoked: false,
                }),
            )?;
            stored.remittance_message_id = message_id;
            stored.task.revision = stored.task.revision.saturating_add(1);
            stored.task.status_text = format!(
                "The issuing office approved settlement; remittance {message_id} and the bond release are in transit"
            );
            self.tasks.put(txn, &key, &encode_stored_task(&stored)?)?;
        }
        Ok(())
    }

    fn receive_task_remittances_available_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        system_id: u64,
        current: u64,
        player: &mut PlayerRecord,
    ) -> Result<(), StoreError> {
        let available = self
            .simulation
            .available_messages(txn, system_id, current, false)?
            .into_iter()
            .map(|available| available.message.message_id)
            .collect::<HashSet<_>>();
        let pending = self
            .tasks
            .iter(txn)?
            .map(|entry| {
                let (key, value) = entry?;
                Ok((key.to_vec(), decode_stored_task(value)?))
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for (key, mut stored) in pending {
            if stored.identity != *identity
                || stored.task.state != crate::wire::TaskState::AwaitingSettlement
                || stored.remittance_message_id == 0
                || !available.contains(&stored.remittance_message_id)
            {
                continue;
            }
            let payment = stored.pending_payment_credits;
            let message_state_key =
                player_message_state_key(identity, stored.remittance_message_id);
            if self
                .player_message_state
                .get(txn, &message_state_key)?
                .is_none()
            {
                self.player_message_state.put(
                    txn,
                    &message_state_key,
                    &encode_player_message_state(&PlayerMessageStateRecord {
                        first_seen_system_id: system_id,
                        first_seen_second: current,
                        classification: MessageClassification::Unreviewed,
                    }),
                )?;
            }
            player.credits = player
                .credits
                .checked_add(payment)
                .ok_or(StoreError::Corrupt("task remittance balance overflow"))?;
            stored.task.performances_completed =
                stored.task.performances_completed.saturating_add(1);
            stored.task.revision = stored.task.revision.saturating_add(1);
            stored.task.settled_second = current;
            stored.settlement_message_id = 0;
            stored.remittance_message_id = 0;
            stored.pending_payment_credits = 0;
            if stored.task.offer.recurrence_seconds != 0
                && stored.task.performances_completed < stored.task.offer.performance_count
            {
                stored.task.state = crate::wire::TaskState::Sourcing;
                stored.task.delivered_quantity_millitons = 0;
                stored.task.offer.delivery_deadline_second = stored
                    .task
                    .offer
                    .delivery_deadline_second
                    .max(current)
                    .saturating_add(stored.task.offer.recurrence_seconds);
                stored.task.status_text = format!(
                    "Performance {}/{} paid Cr{}; next delivery is due on day {}",
                    stored.task.performances_completed,
                    stored.task.offer.performance_count,
                    payment,
                    stored.task.offer.delivery_deadline_second / crate::simulation::SECONDS_PER_DAY
                );
                let event_id = self.simulation.take_scheduled_event_id(txn)?;
                self.work_assignment_events.put(
                    txn,
                    &scheduled_event_key(stored.task.offer.delivery_deadline_second, event_id),
                    &encode_scheduled_object(stored.task.task_id | (1_u64 << 63)),
                )?;
            } else {
                stored.task.state = crate::wire::TaskState::Completed;
                stored.task.reserved_credits = 0;
                stored.task.reserved_cargo_millitons = 0;
                stored.task.reserved_passenger_count = 0;
                stored.task.status_text = format!(
                    "All {}/{} performances paid; final remittance Cr{} and bond release received",
                    stored.task.performances_completed,
                    stored.task.offer.performance_count,
                    payment
                );
            }
            self.tasks.put(txn, &key, &encode_stored_task(&stored)?)?;
        }
        Ok(())
    }

    fn receive_task_claim_result_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        message_id: u64,
        current: u64,
    ) -> Result<(), StoreError> {
        let pending = self
            .tasks
            .iter(txn)?
            .map(|entry| {
                let (key, value) = entry?;
                Ok((key.to_vec(), decode_stored_task(value)?))
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for (key, mut stored) in pending {
            if stored.identity != *identity
                || stored.task.result_message_id != message_id
                || stored.task.known_result
            {
                continue;
            }
            let won = self
                .task_offers
                .get(txn, &stored.task.offer.offer_id.to_be_bytes())?
                .map(decode_stored_task_offer)
                .transpose()?
                .is_some_and(|offer| {
                    offer.claimed_task_id == stored.task.task_id
                        && offer.claimed_by.as_ref() == Some(identity)
                });
            stored.task.known_result = true;
            stored.task.revision = stored.task.revision.saturating_add(1);
            if won {
                let enforcement_second = stored
                    .task
                    .offer
                    .delivery_deadline_second
                    .saturating_add(stored.task.offer.passenger_grace_seconds);
                if current > enforcement_second {
                    stored.task.state = crate::wire::TaskState::Expired;
                    stored.task.reserved_credits = 0;
                    stored.task.reserved_cargo_millitons = 0;
                    stored.task.reserved_passenger_count = 0;
                    stored.task.status_text = "Award arrived after the performance window closed; no custody transferred and no liability was assessed".into();
                } else {
                    stored.task.state = match stored.task.offer.kind {
                        crate::wire::TaskKind::PurchaseOrder
                        | crate::wire::TaskKind::ForwardSale
                        | crate::wire::TaskKind::SupplyCommitment => {
                            crate::wire::TaskState::Sourcing
                        }
                        _ => crate::wire::TaskState::Accepted,
                    };
                    stored.task.status_text =
                        "Claim awarded; report to the origin or perform the stated obligation"
                            .into();
                    if current == enforcement_second {
                        let event_id = self.simulation.take_scheduled_event_id(txn)?;
                        self.work_assignment_events.put(
                            txn,
                            &scheduled_event_key(enforcement_second, event_id),
                            &encode_scheduled_object(stored.task.task_id | (1_u64 << 63)),
                        )?;
                    }
                }
            } else {
                stored.task.state = crate::wire::TaskState::Cancelled;
                stored.task.reserved_credits = 0;
                stored.task.reserved_cargo_millitons = 0;
                stored.task.reserved_passenger_count = 0;
                stored.task.status_text =
                    "Claim declined because an earlier filing reached the issuing office".into();
            }
            self.tasks.put(txn, &key, &encode_stored_task(&stored)?)?;
        }
        Ok(())
    }

    fn receive_task_adjudication_result_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        message_id: u64,
        current: u64,
    ) -> Result<(), StoreError> {
        let pending = self
            .tasks
            .iter(txn)?
            .map(|entry| {
                let (key, value) = entry?;
                Ok((key.to_vec(), decode_stored_task(value)?))
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for (key, mut stored) in pending {
            if stored.identity != *identity
                || stored.task.state != crate::wire::TaskState::Disputed
                || stored.task.adjudication_message_id != message_id
            {
                continue;
            }
            let mut player = self
                .players
                .get(txn, &encode_identity(identity))?
                .map(decode_player_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("task-dispute player is missing"))?;
            if stored.task.dispute_effect >= 0 {
                stored.task.state = crate::wire::TaskState::Cancelled;
                stored.task.status_text =
                    "Dispute sustained; collateral and capacity released without assessment".into();
            } else {
                let assessment = stored
                    .task
                    .reserved_credits
                    .saturating_add(stored.task.offer.failure_penalty_credits)
                    .saturating_add(stored.task.offer.non_delivery_liability_credits);
                let paid = assessment.min(player.credits);
                player.credits -= paid;
                stored.task.state = crate::wire::TaskState::Defaulted;
                stored.task.status_text =
                    format!("Dispute denied; Cr{paid} assessed against available local funds");
                self.players.put(
                    txn,
                    &encode_identity(identity),
                    &encode_player_record(&player),
                )?;
            }
            stored.task.reserved_credits = 0;
            stored.task.reserved_cargo_millitons = 0;
            stored.task.reserved_passenger_count = 0;
            stored.task.settled_second = current;
            stored.task.revision = stored.task.revision.saturating_add(1);
            self.tasks.put(txn, &key, &encode_stored_task(&stored)?)?;
        }
        Ok(())
    }

    fn ship_radio_available(ship: &ShipRecord) -> bool {
        ship.system_id != 0
            && !matches!(
                ship.location,
                ShipLocationRecord::InFlight(FlightLegRecord {
                    purpose: FlightLegPurpose::Jump { .. },
                    ..
                })
            )
            && ship.subsystems.iter().any(|subsystem| {
                subsystem.kind == ShipSubsystemKind::Sensors
                    && subsystem
                        .sustained_hits
                        .saturating_sub(subsystem.battlefield_repair_hits)
                        < subsystem.maximum_hits
            })
    }

    fn radio_locus_position_au_in(
        &self,
        txn: &heed::RoTxn<'_>,
        ship: &ShipRecord,
        locus: ShipLocusRecord,
        second: u64,
    ) -> Result<Option<[f64; 3]>, StoreError> {
        let system_id = locus.system_id();
        if system_id == 0 {
            return Ok(None);
        }
        let system = self
            .systems
            .get(txn, &system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("radio locus system is missing"))?;
        let celestial = derive_celestial_system(&system)?;
        let days = second as f64 / crate::simulation::SECONDS_PER_DAY as f64;
        Ok(match locus {
            ShipLocusRecord::Port { .. } => {
                body_position_au(&celestial, days, celestial.primary_world_body().local_id)
            }
            ShipLocusRecord::Body { body_id, .. } => body_position_au(&celestial, days, body_id),
            ShipLocusRecord::JumpLocus { .. } => {
                let thrust = creation::ship_status_spec(ship.catalog_id)
                    .ok_or(StoreError::Corrupt("radio ship catalog is missing"))?
                    .thrust_g;
                Some(primary_world_jump_safety(&celestial, days, f64::from(thrust)).locus_au)
            }
            ShipLocusRecord::DeepSpace { .. } => None,
        })
    }

    fn radio_position_au_in(
        &self,
        txn: &heed::RoTxn<'_>,
        ship: &ShipRecord,
        second: u64,
    ) -> Result<Option<[f64; 3]>, StoreError> {
        if !Self::ship_radio_available(ship) {
            return Ok(None);
        }
        match ship.location {
            ShipLocationRecord::Docked {
                world_id,
                facility_id,
                ..
            } => self.radio_locus_position_au_in(
                txn,
                ship,
                ShipLocusRecord::Port {
                    system_id: ship.system_id,
                    world_id,
                    facility_id,
                },
                second,
            ),
            ShipLocationRecord::Holding { locus, .. } => {
                self.radio_locus_position_au_in(txn, ship, locus, second)
            }
            ShipLocationRecord::InFlight(leg) => {
                if matches!(leg.purpose, FlightLegPurpose::Jump { .. }) {
                    return Ok(None);
                }
                let origin =
                    self.radio_locus_position_au_in(txn, ship, leg.origin, leg.started_second)?;
                let destination =
                    self.radio_locus_position_au_in(txn, ship, leg.destination, leg.due_second)?;
                let (Some(origin), Some(destination)) = (origin, destination) else {
                    return Ok(None);
                };
                let duration = leg.due_second.saturating_sub(leg.started_second).max(1);
                let fraction = second.saturating_sub(leg.started_second).min(duration) as f64
                    / duration as f64;
                let progress = if fraction <= 0.5 {
                    2.0 * fraction * fraction
                } else {
                    1.0 - 2.0 * (1.0 - fraction) * (1.0 - fraction)
                };
                Ok(Some(std::array::from_fn(|index| {
                    origin[index] + (destination[index] - origin[index]) * progress
                })))
            }
        }
    }

    fn radio_is_muted_in(
        &self,
        txn: &heed::RoTxn<'_>,
        owner: &PlayerIdentity,
        sender: &PlayerIdentity,
    ) -> Result<bool, StoreError> {
        Ok(self
            .radio_mutes
            .get(txn, &radio_mute_key(owner, sender))?
            .is_some())
    }

    fn radio_reception_for_transmission_in(
        &self,
        txn: &heed::RoTxn<'_>,
        ship_id: u64,
        transmission_id: u64,
    ) -> Result<Option<RadioReceptionRecord>, StoreError> {
        for entry in self
            .radio_receptions
            .prefix_iter(txn, &ship_id.to_be_bytes())?
        {
            let (_, value) = entry?;
            let reception = decode_radio_reception(value)?;
            if reception.transmission_id == transmission_id {
                return Ok(Some(reception));
            }
        }
        Ok(None)
    }

    fn reconcile_radio_transmission_for_ship_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        transmission: &mut RadioTransmissionRecord,
        ship: &ShipRecord,
        current: u64,
    ) -> Result<bool, StoreError> {
        let existing = self.radio_reception_for_transmission_in(
            txn,
            ship.ship_id,
            transmission.transmission_id,
        )?;
        if existing
            .is_some_and(|reception| reception.consumed || reception.received_second <= current)
        {
            return Ok(false);
        }
        let mut changed = false;
        if let Some(reception) = existing {
            self.radio_receptions.delete(
                txn,
                &radio_reception_key(ship.ship_id, reception.reception_id),
            )?;
            transmission.reference_count = transmission.reference_count.saturating_sub(1);
            changed = true;
        }
        if !transmission.wave_active
            || current > transmission.wave_expires_second
            || ship.ship_id == transmission.sender_ship_id
            || ship.system_id != transmission.system_id
            || !Self::ship_radio_available(ship)
            || transmission.kind == crate::wire::RadioTransmissionKind::PlayerBroadcast
                && self.radio_is_muted_in(txn, &ship.command, &transmission.sender)?
        {
            return Ok(changed);
        }
        let source = transmission.source_position_bits.map(f64::from_bits);
        let Some(now_position) = self.radio_position_au_in(txn, ship, current)? else {
            return Ok(false);
        };
        let distance = |left: [f64; 3], right: [f64; 3]| {
            left.into_iter()
                .zip(right)
                .map(|(a, b)| (a - b).powi(2))
                .sum::<f64>()
                .sqrt()
        };
        let wave_radius =
            current.saturating_sub(transmission.emitted_second) as f64 / LIGHT_SECONDS_PER_AU;
        if wave_radius > distance(source, now_position) + 1.0e-9 {
            return Ok(changed);
        }
        let mut received = current.max(transmission.emitted_second);
        for _ in 0..8 {
            let Some(position) = self.radio_position_au_in(txn, ship, received)? else {
                return Ok(changed);
            };
            received = transmission
                .emitted_second
                .saturating_add((distance(source, position) * LIGHT_SECONDS_PER_AU).ceil() as u64);
        }
        if received < current || received > transmission.wave_expires_second {
            return Ok(changed);
        }
        let reception_id = take_next_id(self.meta, txn, META_NEXT_RADIO_RECEPTION_ID)?;
        let reception = RadioReceptionRecord {
            reception_id,
            transmission_id: transmission.transmission_id,
            receiving_ship_id: ship.ship_id,
            received_second: received,
            expires_second: received.saturating_add(RADIO_UNREAD_LIFETIME_SECONDS),
            consumed: false,
        };
        self.radio_receptions.put(
            txn,
            &radio_reception_key(ship.ship_id, reception_id),
            &encode_radio_reception(reception),
        )?;
        transmission.reference_count = transmission.reference_count.saturating_add(1);
        Ok(true)
    }

    fn reconcile_radio_for_ship_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        ship: &ShipRecord,
        current: u64,
    ) -> Result<(), StoreError> {
        let transmissions = self
            .radio_transmissions
            .iter(txn)?
            .map(|entry| {
                let (_, value) = entry?;
                decode_radio_transmission(value)
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for mut transmission in transmissions {
            if self.reconcile_radio_transmission_for_ship_in(
                txn,
                &mut transmission,
                ship,
                current,
            )? {
                self.radio_transmissions.put(
                    txn,
                    &transmission.transmission_id,
                    &encode_radio_transmission(&transmission)?,
                )?;
            }
        }
        Ok(())
    }

    fn emit_encounter_radio_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        target: &ShipRecord,
        contact: &EncounterContact,
        kind: EncounterKind,
        encounter_id: u64,
        emitted_second: u64,
        actionable: bool,
        body: &str,
    ) -> Result<(), StoreError> {
        let radio_kind = match kind {
            EncounterKind::Hostile => crate::wire::RadioTransmissionKind::SurrenderDemand,
            EncounterKind::Inspection => crate::wire::RadioTransmissionKind::InspectionOrder,
            EncounterKind::Military => crate::wire::RadioTransmissionKind::BoardingOrder,
            _ => return Ok(()),
        };
        let Some(source) = self.radio_position_au_in(txn, target, emitted_second)? else {
            return Ok(());
        };
        let stellar = self
            .systems
            .get(txn, &target.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("encounter radio system is missing"))?;
        let celestial = derive_celestial_system(&stellar)?;
        let system_radius = celestial
            .stars
            .iter()
            .map(|star| star.zones.outer_limit_au)
            .fold(0.0_f64, f64::max)
            .max(source.into_iter().map(f64::abs).fold(0.0, f64::max));
        let source_radius = source
            .into_iter()
            .map(|value| value * value)
            .sum::<f64>()
            .sqrt();
        let transmission_id = take_next_id(self.meta, txn, META_NEXT_RADIO_TRANSMISSION_ID)?;
        let sender_ship_id = contact.contact_id | (1_u64 << 63);
        let mut transmission = RadioTransmissionRecord {
            transmission_id,
            system_id: target.system_id,
            sender_ship_id,
            sender_ship_name: contact.ship_name.clone(),
            sender_transponder: contact.transponder.clone(),
            sender: PlayerIdentity {
                bbs_id: 0,
                player_id: contact.contact_id as u32,
            },
            emitted_second,
            source_position_bits: source.map(f64::to_bits),
            wave_expires_second: emitted_second.saturating_add(
                ((system_radius + source_radius) * LIGHT_SECONDS_PER_AU).ceil() as u64 + 1,
            ),
            wave_active: true,
            kind: radio_kind,
            action_ship_id: if actionable { target.ship_id } else { 0 },
            action_reference_id: if actionable { encounter_id } else { 0 },
            body: body.to_owned(),
            reference_count: 1,
        };
        let ships = self
            .ships
            .iter(txn)?
            .map(|entry| {
                let (_, value) = entry?;
                decode_ship_record(value)
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for receiver in &ships {
            self.reconcile_radio_transmission_for_ship_in(
                txn,
                &mut transmission,
                receiver,
                emitted_second,
            )?;
        }
        self.radio_transmissions.put(
            txn,
            &transmission_id,
            &encode_radio_transmission(&transmission)?,
        )?;
        Ok(())
    }

    fn cleanup_radio_in(&self, txn: &mut heed::RwTxn<'_>, current: u64) -> Result<(), StoreError> {
        let expired = self
            .radio_receptions
            .iter(txn)?
            .map(|entry| {
                let (key, value) = entry?;
                Ok((key.to_vec(), decode_radio_reception(value)?))
            })
            .collect::<Result<Vec<_>, StoreError>>()?
            .into_iter()
            .filter(|(_, reception)| reception.expires_second <= current)
            .collect::<Vec<_>>();
        let mut released = std::collections::HashMap::<u64, u64>::new();
        for (key, reception) in expired {
            self.radio_receptions.delete(txn, &key)?;
            if !reception.consumed {
                *released.entry(reception.transmission_id).or_default() += 1;
            }
        }
        let transmissions = self
            .radio_transmissions
            .iter(txn)?
            .map(|entry| {
                let (_, value) = entry?;
                decode_radio_transmission(value)
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for mut transmission in transmissions {
            let mut decrement = released.remove(&transmission.transmission_id).unwrap_or(0);
            if transmission.wave_active && transmission.wave_expires_second <= current {
                transmission.wave_active = false;
                decrement = decrement.saturating_add(1);
            }
            transmission.reference_count = transmission.reference_count.saturating_sub(decrement);
            if transmission.reference_count == 0 {
                self.radio_transmissions
                    .delete(txn, &transmission.transmission_id)?;
            } else if decrement != 0 {
                self.radio_transmissions.put(
                    txn,
                    &transmission.transmission_id,
                    &encode_radio_transmission(&transmission)?,
                )?;
            }
        }
        Ok(())
    }

    fn system_radio_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<crate::wire::SystemRadioSnapshot, StoreError> {
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        self.cleanup_radio_in(txn, current)?;
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        self.reconcile_radio_for_ship_in(txn, &ship, current)?;
        let mut entries = Vec::new();
        for entry in self
            .radio_receptions
            .prefix_iter(txn, &ship.ship_id.to_be_bytes())?
        {
            let (_, value) = entry?;
            let reception = decode_radio_reception(value)?;
            if reception.consumed || reception.received_second > current {
                continue;
            }
            let Some(transmission) = self
                .radio_transmissions
                .get(txn, &reception.transmission_id)?
                .map(decode_radio_transmission)
                .transpose()?
            else {
                continue;
            };
            entries.push(crate::wire::RadioInboxEntry {
                reception_id: reception.reception_id,
                transmission_id: transmission.transmission_id,
                receiving_ship_id: reception.receiving_ship_id,
                sender_ship_id: transmission.sender_ship_id,
                sender_ship_name: transmission.sender_ship_name,
                sender_transponder: transmission.sender_transponder,
                sender: transmission.sender,
                emitted_second: transmission.emitted_second,
                received_second: reception.received_second,
                expires_second: reception.expires_second,
                kind: transmission.kind,
                actionable: transmission.action_reference_id != 0
                    && transmission.action_ship_id == ship.ship_id,
                action_reference_id: transmission.action_reference_id,
            });
        }
        entries.sort_by_key(|entry| (entry.received_second, entry.reception_id));
        let prefix = encode_identity(identity);
        let mut mutes = Vec::new();
        for entry in self.radio_mutes.prefix_iter(txn, &prefix)? {
            let (key, _) = entry?;
            if key.len() == 16 {
                let mut decoder = Decoder::new(&key[8..]);
                mutes.push(decode_identity(&mut decoder)?);
            }
        }
        let can_transmit = Self::ship_radio_available(&ship);
        Ok(crate::wire::SystemRadioSnapshot {
            ship_id: ship.ship_id,
            system_id: ship.system_id,
            current_second: current,
            can_transmit,
            unavailable_reason: if can_transmit {
                String::new()
            } else if ship.system_id == 0
                || matches!(
                    ship.location,
                    ShipLocationRecord::InFlight(FlightLegRecord {
                        purpose: FlightLegPurpose::Jump { .. },
                        ..
                    })
                )
            {
                "System Common is unavailable in Jump or interstellar space".into()
            } else {
                "The ship has no functioning communications installation".into()
            },
            entries,
            mutes,
        })
    }

    fn transmit_system_radio_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        body: &str,
    ) -> Result<RuleResult<crate::wire::SystemRadioSnapshot>, StoreError> {
        if body.is_empty()
            || body.len() > RADIO_MAX_BODY_BYTES
            || !body.bytes().all(|byte| (0x20..=0x7e).contains(&byte))
        {
            return Ok(RuleResult::Rejected(
                "System Common transmissions require 1-500 printable ASCII characters".into(),
            ));
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        self.cleanup_radio_in(txn, current)?;
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        if !Self::ship_radio_available(&ship) {
            return Ok(RuleResult::Rejected(
                "System Common is unavailable at the ship's present location or condition".into(),
            ));
        }
        let cooldown_key = encode_identity(identity);
        let next_allowed = self
            .radio_cooldowns
            .get(txn, &cooldown_key)?
            .map(decode_u64)
            .transpose()?
            .unwrap_or(0);
        if current < next_allowed {
            return Ok(RuleResult::Rejected(format!(
                "System Common transmitter cooling down for {} game seconds",
                next_allowed - current
            )));
        }
        let source = self
            .radio_position_au_in(txn, &ship, current)?
            .ok_or(StoreError::Corrupt(
                "radio transmitter has no in-system position",
            ))?;
        let stellar = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("radio transmitter system is missing"))?;
        let celestial = derive_celestial_system(&stellar)?;
        let system_radius = celestial
            .stars
            .iter()
            .map(|star| star.zones.outer_limit_au)
            .fold(0.0_f64, f64::max)
            .max(source.into_iter().map(f64::abs).fold(0.0, f64::max));
        let source_radius = source
            .into_iter()
            .map(|value| value * value)
            .sum::<f64>()
            .sqrt();
        let transmission_id = take_next_id(self.meta, txn, META_NEXT_RADIO_TRANSMISSION_ID)?;
        let mut transmission = RadioTransmissionRecord {
            transmission_id,
            system_id: ship.system_id,
            sender_ship_id: ship.ship_id,
            sender_ship_name: ship.name.clone(),
            sender_transponder: crate::traffic::transponder_for_id(ship.ship_id),
            sender: identity.clone(),
            emitted_second: current,
            source_position_bits: source.map(f64::to_bits),
            wave_expires_second: current.saturating_add(
                ((system_radius + source_radius) * LIGHT_SECONDS_PER_AU).ceil() as u64 + 1,
            ),
            wave_active: true,
            kind: crate::wire::RadioTransmissionKind::PlayerBroadcast,
            action_ship_id: 0,
            action_reference_id: 0,
            body: body.to_owned(),
            reference_count: 1,
        };
        let ships = self
            .ships
            .iter(txn)?
            .map(|entry| {
                let (_, value) = entry?;
                decode_ship_record(value)
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for receiver in &ships {
            self.reconcile_radio_transmission_for_ship_in(
                txn,
                &mut transmission,
                receiver,
                current,
            )?;
        }
        self.radio_transmissions.put(
            txn,
            &transmission_id,
            &encode_radio_transmission(&transmission)?,
        )?;
        self.radio_cooldowns.put(
            txn,
            &cooldown_key,
            &current
                .saturating_add(RADIO_SEND_INTERVAL_SECONDS)
                .to_be_bytes(),
        )?;
        Ok(RuleResult::Applied(self.system_radio_in(txn, identity)?))
    }

    fn peek_radio_reception_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        reception_id: u64,
    ) -> Result<RuleResult<crate::wire::RadioContent>, StoreError> {
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        self.cleanup_radio_in(txn, current)?;
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let Some(reception) = self
            .radio_receptions
            .get(txn, &radio_reception_key(ship.ship_id, reception_id))?
            .map(decode_radio_reception)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected(
                "that unread radio reception is unavailable".into(),
            ));
        };
        if reception.consumed {
            return Ok(RuleResult::Rejected(
                "that radio reception was already consumed".into(),
            ));
        }
        if reception.received_second > current {
            return Ok(RuleResult::Rejected(
                "that radio wave has not reached the ship".into(),
            ));
        }
        let transmission = self
            .radio_transmissions
            .get(txn, &reception.transmission_id)?
            .map(decode_radio_transmission)
            .transpose()?
            .ok_or(StoreError::Corrupt("radio reception content is missing"))?;
        Ok(RuleResult::Applied(crate::wire::RadioContent {
            reception_id,
            transmission_id: reception.transmission_id,
            body: transmission.body,
        }))
    }

    fn acknowledge_radio_reception_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        reception_id: u64,
    ) -> Result<RuleResult<crate::wire::SystemRadioSnapshot>, StoreError> {
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let key = radio_reception_key(ship.ship_id, reception_id);
        let Some(mut reception) = self
            .radio_receptions
            .get(txn, &key)?
            .map(decode_radio_reception)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected(
                "that radio reception was already consumed".into(),
            ));
        };
        if reception.consumed {
            return Ok(RuleResult::Rejected(
                "that radio reception was already consumed".into(),
            ));
        }
        let Some(mut transmission) = self
            .radio_transmissions
            .get(txn, &reception.transmission_id)?
            .map(decode_radio_transmission)
            .transpose()?
        else {
            return Err(StoreError::Corrupt("radio reception content is missing"));
        };
        transmission.reference_count = transmission.reference_count.saturating_sub(1);
        reception.consumed = true;
        reception.expires_second = transmission.wave_expires_second;
        self.radio_receptions
            .put(txn, &key, &encode_radio_reception(reception))?;
        if transmission.reference_count == 0 {
            self.radio_transmissions
                .delete(txn, &transmission.transmission_id)?;
        } else {
            self.radio_transmissions.put(
                txn,
                &transmission.transmission_id,
                &encode_radio_transmission(&transmission)?,
            )?;
        }
        Ok(RuleResult::Applied(self.system_radio_in(txn, identity)?))
    }

    fn set_radio_mute_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        sender: &PlayerIdentity,
        muted: bool,
    ) -> Result<RuleResult<crate::wire::SystemRadioSnapshot>, StoreError> {
        if sender == identity {
            return Ok(RuleResult::Rejected(
                "a captain cannot mute their own identity".into(),
            ));
        }
        let key = radio_mute_key(identity, sender);
        if muted {
            self.radio_mutes.put(txn, &key, &[1])?;
        } else {
            self.radio_mutes.delete(txn, &key)?;
        }
        Ok(RuleResult::Applied(self.system_radio_in(txn, identity)?))
    }

    fn send_private_message_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        request: &crate::wire::PrivateMessageRequest,
    ) -> Result<RuleResult<MessageManagement>, StoreError> {
        if request.ttl_weeks == 0 || request.ttl_weeks > 52 {
            return Ok(RuleResult::Rejected(
                "private mail requires a TTL from one to fifty-two weeks".into(),
            ));
        }
        if request.subject.trim().is_empty() || request.body.trim().is_empty() {
            return Ok(RuleResult::Rejected(
                "private mail requires both a subject and body".into(),
            ));
        }
        let (mut player, ship) = self.player_and_ship_in(txn, identity)?;
        let systems = self.simulation.systems(txn)?;
        let max_hops = usize::from(request.ttl_weeks);
        let (recipient, destinations, charged_hops) = match request.recipient_kind {
            crate::wire::PrivateRecipientKind::System => {
                if !systems
                    .iter()
                    .any(|s| s.system_id == request.destination_system_id)
                {
                    return Ok(RuleResult::Rejected(
                        "destination system is not in the carried directory".into(),
                    ));
                }
                let Some(route) = crate::simulation::shortest_route(
                    &systems,
                    ship.system_id,
                    request.destination_system_id,
                ) else {
                    return Ok(RuleResult::Rejected(
                        "no known mail route reaches that system".into(),
                    ));
                };
                let hops = route.len().saturating_sub(1);
                if hops > max_hops {
                    return Ok(RuleResult::Rejected(
                        "the destination lies beyond the purchased TTL".into(),
                    ));
                }
                (
                    PlayerIdentity {
                        bbs_id: 0,
                        player_id: 0,
                    },
                    vec![request.destination_system_id],
                    hops.max(1) as u64,
                )
            }
            crate::wire::PrivateRecipientKind::Captain => {
                if self
                    .players
                    .get(txn, &encode_identity(&request.recipient))?
                    .is_none()
                {
                    return Ok(RuleResult::Rejected(
                        "recipient captain is not registered".into(),
                    ));
                }
                let expected_key = (u64::from(request.recipient.bbs_id) << 32)
                    | u64::from(request.recipient.player_id);
                if request.encryption_key_id != expected_key {
                    return Ok(RuleResult::Rejected(
                        "the selected public key does not identify that captain".into(),
                    ));
                }
                let mut destinations = Vec::new();
                let mut charged = 0_u64;
                for system in &systems {
                    if let Some(route) = crate::simulation::shortest_route(
                        &systems,
                        ship.system_id,
                        system.system_id,
                    ) {
                        let hops = route.len().saturating_sub(1);
                        if hops <= max_hops {
                            destinations.push(system.system_id);
                            charged = charged.saturating_add(hops.max(1) as u64);
                        }
                    }
                }
                (request.recipient.clone(), destinations, charged.max(1))
            }
        };
        let kib = (request.subject.len().saturating_add(request.body.len()) as u64)
            .div_ceil(1024)
            .max(1);
        let price = kib
            .saturating_mul(charged_hops)
            .saturating_mul(u64::from(request.ttl_weeks));
        if player.credits < price {
            return Ok(RuleResult::Rejected(format!(
                "private carriage costs Cr{price}; available funds are insufficient"
            )));
        }
        player.credits -= price;
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let (message_id, _) = self.simulation.dispatch_message(
            txn,
            current,
            ship.system_id,
            crate::simulation::MessageClass::Private,
            crate::simulation::MessageImportance::Routine,
            request.subject.trim(),
            request.body.trim(),
            &destinations,
        )?;
        self.simulation.set_message_expiry(
            txn,
            message_id,
            current.saturating_add(
                u64::from(request.ttl_weeks) * 7 * crate::simulation::SECONDS_PER_DAY,
            ),
        )?;
        let record = PrivateMessageRecipientRecord {
            message_id,
            recipient_kind: request.recipient_kind,
            destination_system_id: request.destination_system_id,
            recipient,
            encryption_key_id: request.encryption_key_id,
            revoked: false,
        };
        self.private_message_recipients.put(
            txn,
            &message_id.to_be_bytes(),
            &encode_private_message_recipient(&record),
        )?;
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        Ok(RuleResult::Applied(
            self.message_management_in(txn, identity)?,
        ))
    }

    fn purchase_insurance_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        kind: crate::wire::InsuranceKind,
        enabled: bool,
    ) -> Result<RuleResult<crate::wire::FinanceSnapshot>, StoreError> {
        let (mut player, ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked { facility_id, .. } = ship.location else {
            return Ok(RuleResult::Rejected(
                "insurance may only be bound or cancelled while docked".into(),
            ));
        };
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("banking facility is missing"))?;
        if !facility.operational || !facility.banking {
            return Ok(RuleResult::Rejected(
                "no recognized banking house operates at this port".into(),
            ));
        }
        let mut key = encode_identity(identity).to_vec();
        key.push(match kind {
            crate::wire::InsuranceKind::DestinationAssistance => 1,
        });
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let existing = self
            .insurance_policies
            .get(txn, &key)?
            .and_then(|value| <[u8; 8]>::try_from(value).ok())
            .map(u64::from_be_bytes)
            .is_some_and(|expires| current < expires);
        if existing == enabled {
            return Ok(RuleResult::Applied(
                self.finance_snapshot_in(txn, identity)?,
            ));
        }
        if enabled {
            const ANNUAL_PREMIUM: u64 = 350_000;
            if player.credits < ANNUAL_PREMIUM {
                return Ok(RuleResult::Rejected(
                    "destination assistance requires the Cr350000 annual premium".into(),
                ));
            }
            player.credits -= ANNUAL_PREMIUM;
            let expires = current.saturating_add(365 * crate::simulation::SECONDS_PER_DAY);
            self.insurance_policies
                .put(txn, &key, &expires.to_be_bytes())?;
            self.players.put(
                txn,
                &encode_identity(identity),
                &encode_player_record(&player),
            )?;
        } else {
            self.insurance_policies.delete(txn, &key)?;
        }
        Ok(RuleResult::Applied(
            self.finance_snapshot_in(txn, identity)?,
        ))
    }

    fn misappropriate_restricted_credits_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        amount: u64,
    ) -> Result<RuleResult<crate::wire::FinanceSnapshot>, StoreError> {
        if amount == 0 {
            return Ok(RuleResult::Rejected(
                "a forged receipt must claim a positive amount".into(),
            ));
        }
        let (mut player, ship) = self.player_and_ship_in(txn, identity)?;
        let career = self.career_state_in(txn, identity)?;
        let key = ship_finance_key(ship.ship_id);
        let mut finance = self
            .finances
            .get(txn, &key)?
            .map(decode_finance_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship finance record is missing"))?;
        if career.mode != crate::careers::CombatCareerMode::Navy
            || finance.title != crate::wire::ShipTitleKind::InstitutionOwned
        {
            return Ok(RuleResult::Rejected(
                "only a captain holding an institutional naval command can file against this service account"
                    .into(),
            ));
        }
        if finance.restricted_credits < amount {
            return Ok(RuleResult::Rejected(format!(
                "the naval service account has only Cr{} available",
                finance.restricted_credits
            )));
        }
        if finance.forged_receipt_count != 0
            && (finance.forged_receipt_bbs_id != identity.bbs_id
                || finance.forged_receipt_player_id != identity.player_id)
        {
            return Ok(RuleResult::Rejected(
                "the prior command's receipts remain pending for the next accounts audit".into(),
            ));
        }
        if finance.forged_receipt_count == 0 {
            finance.forged_receipt_bbs_id = identity.bbs_id;
            finance.forged_receipt_player_id = identity.player_id;
        }
        finance.restricted_credits -= amount;
        finance.forged_receipt_credits = finance
            .forged_receipt_credits
            .checked_add(amount)
            .ok_or(StoreError::Corrupt("forged receipt total overflow"))?;
        finance.forged_receipt_count = finance
            .forged_receipt_count
            .checked_add(1)
            .ok_or(StoreError::Corrupt("forged receipt count overflow"))?;
        player.credits = player
            .credits
            .checked_add(amount)
            .ok_or(StoreError::Corrupt("captain credit balance overflow"))?;
        self.finances
            .put(txn, &key, &encode_finance_record(&finance))?;
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        Ok(RuleResult::Applied(
            self.finance_snapshot_in(txn, identity)?,
        ))
    }

    fn cure_finance_default_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<RuleResult<crate::wire::FinanceSnapshot>, StoreError> {
        let (mut player, ship) = self.player_and_ship_in(txn, identity)?;
        let finance_key = ship_finance_key(ship.ship_id);
        let mut finance = self
            .finances
            .get(txn, &finance_key)?
            .map(decode_finance_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship finance record is missing"))?;
        if !finance.in_default {
            return Ok(RuleResult::Rejected(
                "this account is not in default".into(),
            ));
        }
        let (_, _, amount_due) = finance_installment_due(&finance);
        let insurance_from_restricted = finance
            .restricted_credits
            .min(finance.monthly_insurance_escrow_credits);
        let liquid_due = amount_due.saturating_sub(insurance_from_restricted);
        if !pay_finance_installment(&mut player, &mut finance) {
            return Ok(RuleResult::Rejected(format!(
                "posting Cr{} requires Cr{} liquid after available restricted operating credit; only Cr{} is liquid",
                amount_due, liquid_due, player.credits
            )));
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        finance.in_default = false;
        finance.impound_order_known_locally = false;
        finance.impound_message_id = 0;
        finance.paid_through_second = current;
        finance.next_payment_due_second =
            current.saturating_add(crate::ship_condition::ACCOUNTING_MONTH_SECONDS);
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.finances
            .put(txn, &finance_key, &encode_finance_record(&finance))?;
        Ok(RuleResult::Applied(
            self.finance_snapshot_in(txn, identity)?,
        ))
    }

    fn accept_task_offer_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        offer_id: u64,
        expected_revision: u64,
    ) -> Result<RuleResult<crate::wire::TaskLedger>, StoreError> {
        let (player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let Some(offer) = self
            .local_task_offers_in(txn, identity, &ship)?
            .into_iter()
            .find(|o| o.offer_id == offer_id)
        else {
            return Ok(RuleResult::Rejected("offer is no longer available".into()));
        };
        if offer.revision != expected_revision || offer.expires_second < current {
            return Ok(RuleResult::Rejected(
                "offer revision is stale or expired".into(),
            ));
        }
        let local_claim = ship.system_id == offer.origin_system_id;
        let Some(mut stored_offer) = self
            .task_offers
            .get(txn, &offer_id.to_be_bytes())?
            .map(decode_stored_task_offer)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected("offer instrument is missing".into()));
        };
        if local_claim && stored_offer.claimed_by.is_some() {
            return Ok(RuleResult::Rejected(
                "the issuing office has already awarded this offer".into(),
            ));
        }
        let active = self.task_ledger_in(txn, identity)?;
        if active.tasks.iter().any(|t| t.offer.offer_id == offer_id) {
            return Ok(RuleResult::Rejected(
                "offer has already been accepted".into(),
            ));
        }
        if player.credits.saturating_sub(active.reserved_credits) < offer.collateral_credits {
            return Ok(RuleResult::Rejected(
                "insufficient unreserved credits for collateral".into(),
            ));
        }
        let task_id = take_id_range(self.meta, txn, META_NEXT_TASK_ID, 1)?;
        let (awarded_state, reserved_cargo, reserved_passengers) = match offer.kind {
            crate::wire::TaskKind::Freight => (
                crate::wire::TaskState::Accepted,
                offer.quantity_millitons,
                0,
            ),
            crate::wire::TaskKind::Passenger
            | crate::wire::TaskKind::Charter
            | crate::wire::TaskKind::Courier => {
                (crate::wire::TaskState::Accepted, 0, offer.passenger_count)
            }
            crate::wire::TaskKind::PurchaseOrder
            | crate::wire::TaskKind::ForwardSale
            | crate::wire::TaskKind::SupplyCommitment => (crate::wire::TaskState::Sourcing, 0, 0),
            _ => (crate::wire::TaskState::Accepted, 0, 0),
        };
        let state = if local_claim {
            awarded_state
        } else {
            crate::wire::TaskState::ClaimPending
        };
        let status_text = match state {
            crate::wire::TaskState::ClaimPending => {
                "Sealed claim filed; capacity and collateral remain reserved while it travels to the issuing office"
            }
            crate::wire::TaskState::Sourcing => {
                "Claim awarded by the issuing office; acquire the specified goods for delivery"
            }
            _ => "Claim awarded by the issuing office; perform the stated obligation",
        };
        let task = crate::wire::TaskRecord {
            task_id,
            offer,
            state,
            accepted_second: current,
            delivered_quantity_millitons: 0,
            reserved_cargo_millitons: reserved_cargo,
            reserved_passenger_count: reserved_passengers,
            reserved_credits: 0,
            status_text: status_text.into(),
            performances_completed: 0,
            revision: 1,
            claim_message_id: 0,
            result_message_id: 0,
            known_result: local_claim,
            loaded_second: 0,
            settled_second: 0,
            insurance_claim_id: 0,
            dispute_message_id: 0,
            dispute_effect: 0,
            adjudication_message_id: 0,
            performing_ship_id: ship.ship_id,
        };
        let mut task = task;
        task.reserved_credits = task.offer.collateral_credits;
        let delivery_deadline_second = task.offer.delivery_deadline_second;
        if !local_claim {
            let (message_id, _) = self.simulation.dispatch_message(
                txn,
                current,
                ship.system_id,
                crate::simulation::MessageClass::Private,
                crate::simulation::MessageImportance::Important,
                &format!("Sealed claim on offer {}", task.offer.offer_id),
                &format!("Captain {}/{} files a binding claim on offer {}. Receipt order at the issuing office controls.", identity.bbs_id, identity.player_id, task.offer.offer_id),
                &[task.offer.origin_system_id],
            )?;
            task.claim_message_id = message_id;
            task.state = crate::wire::TaskState::ClaimPending;
            task.status_text = "Sealed claim is in the mail; capacity and collateral remain reserved until the issuing office replies".into();
            // The issuing office consumes this sealed traffic. It is not
            // correspondence addressed to every captain in the system.
        }
        self.tasks.put(
            txn,
            &task_id.to_be_bytes(),
            &encode_stored_task(&StoredTask {
                identity: identity.clone(),
                task,
                settlement_message_id: 0,
                remittance_message_id: 0,
                pending_payment_credits: 0,
            })?,
        )?;
        if local_claim {
            stored_offer.claimed_by = Some(identity.clone());
            stored_offer.claimed_task_id = task_id;
            stored_offer.closure_message_id =
                self.dispatch_task_offer_closure_in(txn, &stored_offer.offer, current)?;
            self.task_offers.put(
                txn,
                &offer_id.to_be_bytes(),
                &encode_stored_task_offer(&stored_offer)?,
            )?;
        }
        let message_state_key = player_message_state_key(identity, offer_id);
        let mut message_state = self
            .player_message_state
            .get(txn, &message_state_key)?
            .map(decode_player_message_state)
            .transpose()?
            .unwrap_or(PlayerMessageStateRecord {
                first_seen_system_id: ship.system_id,
                first_seen_second: current,
                classification: MessageClassification::Unreviewed,
            });
        message_state.classification = MessageClassification::Actioned;
        self.player_message_state.put(
            txn,
            &message_state_key,
            &encode_player_message_state(&message_state),
        )?;
        if matches!(ship.location, ShipLocationRecord::Docked { .. })
            && ship.system_id == stored_offer.offer.origin_system_id
        {
            self.prepare_tasks_at_port_in(txn, identity, &mut ship, current)?;
            self.ships
                .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        }
        let event_id = self.simulation.take_scheduled_event_id(txn)?;
        let enforcement_second =
            delivery_deadline_second.saturating_add(stored_offer.offer.passenger_grace_seconds);
        self.work_assignment_events.put(
            txn,
            &scheduled_event_key(enforcement_second, event_id),
            &encode_scheduled_object(task_id | (1_u64 << 63)),
        )?;
        Ok(RuleResult::Applied(self.task_ledger_in(txn, identity)?))
    }

    fn set_carriage_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        value: crate::wire::CarriageDeclaration,
    ) -> Result<RuleResult<crate::wire::TaskLedger>, StoreError> {
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        if !matches!(ship.location, ShipLocationRecord::Docked { .. }) {
            return Ok(RuleResult::Rejected(
                "carriage declarations may only be changed while docked".into(),
            ));
        }
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship status data missing"))?;
        if value.freight_capacity_millitons > effective_cargo_capacity(&ship, &spec) {
            return Ok(RuleResult::Rejected(
                "declared freight exceeds fitted cargo capacity".into(),
            ));
        }
        let occupied_staterooms = value
            .high_berths
            .saturating_add(value.middle_berths)
            .saturating_add(value.steerage_berths);
        if occupied_staterooms > spec.passenger_berths || value.low_berths > spec.low_berths {
            return Ok(RuleResult::Rejected(
                "declared passenger capacity exceeds fitted accommodations".into(),
            ));
        }
        self.carriage_declarations.put(
            txn,
            &encode_identity(identity),
            &encode_carriage_declaration(value),
        )?;
        Ok(RuleResult::Applied(self.task_ledger_in(txn, identity)?))
    }

    fn fleet_snapshot_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<crate::wire::FleetSnapshot, StoreError> {
        let player = self
            .players
            .get(txn, &encode_identity(identity))?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("fleet player is missing"))?;
        let mut ships = Vec::with_capacity(player.managed_ship_ids.len());
        for ship_id in &player.managed_ship_ids {
            let ship = self
                .ships
                .get(txn, ship_id)?
                .map(decode_ship_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("managed vessel is missing"))?;
            if ship.command != *identity {
                return Err(StoreError::Corrupt("managed vessel has another owner"));
            }
            let finance = self
                .finances
                .get(txn, &ship_finance_key(*ship_id))?
                .map(decode_finance_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("managed vessel title is missing"))?;
            let system_name = self
                .systems
                .get(txn, &ship.system_id)?
                .map(decode_stellar_system)
                .transpose()?
                .map_or_else(|| "Uncharted space".to_owned(), |system| system.name);
            let under_construction = matches!(
                ship.activity.as_ref().map(|activity| &activity.kind),
                Some(ShipActivityKind::Construction)
            );
            let location = match ship.location {
                ShipLocationRecord::Docked { .. } if under_construction => {
                    "Under construction".to_owned()
                }
                ShipLocationRecord::Docked { .. } => "In berth".to_owned(),
                ShipLocationRecord::InFlight(_) => "Under way".to_owned(),
                ShipLocationRecord::Holding { .. } => "Holding station".to_owned(),
            };
            let commanding_person_name = if ship.commanding_person_id == 0 {
                "Unassigned".to_owned()
            } else {
                self.persons
                    .get(txn, &ship.commanding_person_id)?
                    .map(decode_person_record)
                    .transpose()?
                    .map_or_else(|| "Unassigned".to_owned(), |person| person.person.name)
            };
            let class_name = creation::ship_market_catalog()
                .into_iter()
                .find(|entry| entry.catalog_id == ship.catalog_id)
                .map(|entry| entry.class_name)
                .ok_or(StoreError::Corrupt(
                    "managed vessel catalog data is missing",
                ))?;
            let spec = creation::ship_status_spec(ship.catalog_id)
                .ok_or(StoreError::Corrupt("managed vessel status data is missing"))?;
            let cargo_used_millitons = ship.cargo.iter().map(|lot| lot.quantity_millitons).sum();
            let ammunition = ship
                .ammunition
                .iter()
                .map(|lot| crate::wire::ShipAmmunitionStatus {
                    ammunition_id: lot.ammunition_id.clone(),
                    remaining: lot.remaining,
                    capacity: lot.capacity,
                    pack_units: lot.pack_units,
                    price_per_pack_credits: lot.price_per_pack_credits,
                })
                .collect();
            ships.push(crate::wire::ManagedShipSummary {
                ship_id: *ship_id,
                name: ship.name.clone(),
                class_name,
                catalog_id: ship.catalog_id,
                system_id: ship.system_id,
                system_name,
                location,
                title: finance.title,
                active: *ship_id == player.ship_id,
                commanding_person_id: ship.commanding_person_id,
                commanding_person_name,
                standing_order: ship.standing_order,
                can_assume_command: *ship_id == player.ship_id
                    || !under_construction
                        && matches!(ship.location, ShipLocationRecord::Docked { .. })
                        && !matches!(
                            finance.title,
                            crate::wire::ShipTitleKind::PrizeCustody
                                | crate::wire::ShipTitleKind::CourtImpound
                        ),
                fuel_millitons: ship.current_fuel_millitons,
                fuel_capacity_millitons: effective_fuel_capacity(&ship, &spec),
                cargo_used_millitons,
                cargo_capacity_millitons: effective_cargo_capacity(&ship, &spec),
                provision_person_days: ship.provisions.person_days_remaining,
                provision_capacity_person_days: ship.provisions.installed_capacity_person_days,
                cargo: ship.cargo.clone(),
                ammunition,
                online_controlled: false,
            });
        }
        Ok(crate::wire::FleetSnapshot {
            revision: player.fleet_revision,
            active_ship_id: player.ship_id,
            ships,
        })
    }

    fn set_active_ship_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        expected_revision: u64,
        ship_id: u64,
    ) -> Result<RuleResult<crate::wire::FleetSnapshot>, StoreError> {
        let identity_key = encode_identity(identity);
        let mut player = self
            .players
            .get(txn, &identity_key)?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("fleet player is missing"))?;
        if player.fleet_revision != expected_revision {
            return Ok(RuleResult::Rejected("the vessel roster has changed".into()));
        }
        if ship_id == player.ship_id {
            return Ok(RuleResult::Applied(self.fleet_snapshot_in(txn, identity)?));
        }
        if self.ship_combats.get(txn, &player.ship_id)?.is_some()
            || self.ship_combats.get(txn, &ship_id)?.is_some()
        {
            return Ok(RuleResult::Rejected(
                "command cannot be exchanged while either vessel is engaged in combat".into(),
            ));
        }
        if !player.managed_ship_ids.contains(&ship_id) {
            return Ok(RuleResult::Rejected(
                "that vessel is not in this account's roster".into(),
            ));
        }
        let mut old_ship = self
            .ships
            .get(txn, &player.ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("commanded vessel is missing"))?;
        let mut new_ship = self
            .ships
            .get(txn, &ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("selected vessel is missing"))?;
        if matches!(
            new_ship.activity.as_ref().map(|activity| &activity.kind),
            Some(ShipActivityKind::Construction)
        ) {
            return Ok(RuleResult::Rejected(
                "the selected vessel is still under construction".into(),
            ));
        }
        let same_berth = matches!(
            (old_ship.location, new_ship.location),
            (
                ShipLocationRecord::Docked { world_id: a_world, facility_id: a_facility, .. },
                ShipLocationRecord::Docked { world_id: b_world, facility_id: b_facility, .. }
            ) if old_ship.system_id == new_ship.system_id
                && a_world == b_world
                && a_facility == b_facility
        );
        if !same_berth {
            return Ok(RuleResult::Rejected(
                "command may only be exchanged between vessels in the same berth".into(),
            ));
        }
        let title = self
            .finances
            .get(txn, &ship_finance_key(ship_id))?
            .map(decode_finance_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("selected vessel title is missing"))?
            .title;
        if matches!(
            title,
            crate::wire::ShipTitleKind::PrizeCustody | crate::wire::ShipTitleKind::CourtImpound
        ) {
            return Ok(RuleResult::Rejected(
                "the selected vessel is held under court authority".into(),
            ));
        }
        if new_ship.commanding_person_id == 0 {
            return Ok(RuleResult::Rejected(
                "assign a qualified captain to the selected vessel first".into(),
            ));
        }
        let relief_id = new_ship.commanding_person_id;
        new_ship.commanding_person_id = player.captain_person_id;
        old_ship.commanding_person_id = relief_id;
        for person_id in [player.captain_person_id, relief_id] {
            if let Some(encoded) = self.crew_services.get(txn, &person_id)? {
                let mut service = decode_crew_service(encoded)?;
                service.ship_id = if person_id == player.captain_person_id {
                    ship_id
                } else {
                    old_ship.ship_id
                };
                service.assigned_slot_ids.clear();
                self.crew_services
                    .put(txn, &person_id, &encode_crew_service(&service)?)?;
            }
        }
        old_ship.revision = old_ship.revision.saturating_add(1);
        new_ship.revision = new_ship.revision.saturating_add(1);
        player.ship_id = ship_id;
        player.fleet_revision = player.fleet_revision.saturating_add(1);
        self.ships
            .put(txn, &old_ship.ship_id, &encode_ship_record(&old_ship)?)?;
        self.ships
            .put(txn, &new_ship.ship_id, &encode_ship_record(&new_ship)?)?;
        self.players
            .put(txn, &identity_key, &encode_player_record(&player))?;
        Ok(RuleResult::Applied(self.fleet_snapshot_in(txn, identity)?))
    }

    fn assign_ship_captain_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        expected_revision: u64,
        ship_id: u64,
        person_id: u64,
    ) -> Result<RuleResult<crate::wire::FleetSnapshot>, StoreError> {
        let identity_key = encode_identity(identity);
        let mut player = self
            .players
            .get(txn, &identity_key)?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("fleet player is missing"))?;
        if player.fleet_revision != expected_revision {
            return Ok(RuleResult::Rejected("the vessel roster has changed".into()));
        }
        if ship_id == player.ship_id {
            return Ok(RuleResult::Rejected(
                "the player captain retains direct command of the active vessel".into(),
            ));
        }
        if !player.managed_ship_ids.contains(&ship_id) {
            return Ok(RuleResult::Rejected(
                "that vessel is not in this account's roster".into(),
            ));
        }
        if player.captain_person_id == person_id {
            return Ok(RuleResult::Rejected(
                "the player captain cannot command two vessels".into(),
            ));
        }
        let person = self
            .persons
            .get(txn, &person_id)?
            .map(decode_person_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("selected captain is missing"))?;
        if person_dead(&person) {
            return Ok(RuleResult::Rejected("the selected officer is dead".into()));
        }
        let Some(mut service) = self
            .crew_services
            .get(txn, &person_id)?
            .map(decode_crew_service)
            .transpose()?
            .filter(|service| service.command == *identity)
        else {
            return Ok(RuleResult::Rejected(
                "the selected officer is not employed by this account".into(),
            ));
        };
        for managed_id in &player.managed_ship_ids {
            let managed = self
                .ships
                .get(txn, managed_id)?
                .map(decode_ship_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("managed vessel is missing"))?;
            if managed.ship_id != ship_id && managed.commanding_person_id == person_id {
                return Ok(RuleResult::Rejected(
                    "the selected officer already commands another vessel".into(),
                ));
            }
        }
        let mut ship = self
            .ships
            .get(txn, &ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("selected vessel is missing"))?;
        if matches!(
            ship.activity.as_ref().map(|activity| &activity.kind),
            Some(ShipActivityKind::Construction)
        ) {
            return Ok(RuleResult::Rejected(
                "a captain cannot be assigned before delivery".into(),
            ));
        }
        service.ship_id = ship_id;
        service.assigned_slot_ids.clear();
        ship.commanding_person_id = person_id;
        ship.revision = ship.revision.saturating_add(1);
        player.fleet_revision = player.fleet_revision.saturating_add(1);
        self.crew_services
            .put(txn, &person_id, &encode_crew_service(&service)?)?;
        self.ships.put(txn, &ship_id, &encode_ship_record(&ship)?)?;
        self.players
            .put(txn, &identity_key, &encode_player_record(&player))?;
        Ok(RuleResult::Applied(self.fleet_snapshot_in(txn, identity)?))
    }

    #[allow(clippy::too_many_arguments)]
    fn transfer_ship_stores_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        expected_revision: u64,
        from_ship_id: u64,
        to_ship_id: u64,
        kind: crate::wire::StoreTransferKind,
        cargo_lot_id: u64,
        item_id: &str,
        quantity: u64,
    ) -> Result<RuleResult<crate::wire::FleetSnapshot>, StoreError> {
        if from_ship_id == to_ship_id || quantity == 0 {
            return Ok(RuleResult::Rejected(
                "a positive quantity must move between two different vessels".into(),
            ));
        }
        let identity_key = encode_identity(identity);
        let mut player = self
            .players
            .get(txn, &identity_key)?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("fleet player is missing"))?;
        if player.fleet_revision != expected_revision {
            return Ok(RuleResult::Rejected("the vessel roster has changed".into()));
        }
        if !player.managed_ship_ids.contains(&from_ship_id)
            || !player.managed_ship_ids.contains(&to_ship_id)
        {
            return Ok(RuleResult::Rejected(
                "both vessels must be in this account's roster".into(),
            ));
        }
        let mut source = self
            .ships
            .get(txn, &from_ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("source vessel is missing"))?;
        let mut destination = self
            .ships
            .get(txn, &to_ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("destination vessel is missing"))?;
        if [&source, &destination].into_iter().any(|ship| {
            matches!(
                ship.activity.as_ref().map(|activity| &activity.kind),
                Some(ShipActivityKind::Construction)
            )
        }) {
            return Ok(RuleResult::Rejected(
                "stores cannot move through an undelivered hull".into(),
            ));
        }
        let co_located = source.system_id == destination.system_id
            && match (source.location, destination.location) {
                (
                    ShipLocationRecord::Docked {
                        world_id: aw,
                        facility_id: af,
                        ..
                    },
                    ShipLocationRecord::Docked {
                        world_id: bw,
                        facility_id: bf,
                        ..
                    },
                ) => aw == bw && af == bf,
                (
                    ShipLocationRecord::Holding { locus: a, .. },
                    ShipLocationRecord::Holding { locus: b, .. },
                ) => a == b,
                _ => false,
            };
        if !co_located {
            return Ok(RuleResult::Rejected(
                "stores may only be transferred between vessels alongside one another".into(),
            ));
        }
        match kind {
            crate::wire::StoreTransferKind::Cargo => {
                let Some(index) = source
                    .cargo
                    .iter()
                    .position(|lot| lot.cargo_lot_id == cargo_lot_id)
                else {
                    return Ok(RuleResult::Rejected(
                        "the source cargo lot is not aboard".into(),
                    ));
                };
                if source.cargo[index].quantity_millitons < quantity {
                    return Ok(RuleResult::Rejected(
                        "the cargo lot contains less than requested".into(),
                    ));
                }
                if source.cargo[index].unique_object_id != 0
                    && source.cargo[index].quantity_millitons != quantity
                {
                    return Ok(RuleResult::Rejected(
                        "a unique cargo object cannot be divided".into(),
                    ));
                }
                let spec = creation::ship_status_spec(destination.catalog_id)
                    .ok_or(StoreError::Corrupt("destination catalog data is missing"))?;
                let used = destination
                    .cargo
                    .iter()
                    .map(|lot| lot.quantity_millitons)
                    .sum::<u64>();
                if used.saturating_add(quantity) > effective_cargo_capacity(&destination, &spec) {
                    return Ok(RuleResult::Rejected(
                        "the destination hold lacks capacity".into(),
                    ));
                }
                let mut moved = source.cargo[index].clone();
                moved.quantity_millitons = quantity;
                moved.cargo_lot_id = take_id_range(self.meta, txn, META_NEXT_CARGO_LOT_ID, 1)?;
                source.cargo[index].quantity_millitons -= quantity;
                if source.cargo[index].quantity_millitons == 0 {
                    source.cargo.remove(index);
                }
                if moved.unique_object_id != 0 {
                    let mut unique = self
                        .unique_cargo
                        .get(txn, &moved.unique_object_id)?
                        .map(decode_unique_cargo)
                        .transpose()?
                        .ok_or(StoreError::Corrupt("unique cargo record is missing"))?;
                    unique.location = UniqueCargoLocation::PlayerShip {
                        ship_id: to_ship_id,
                        cargo_lot_id: moved.cargo_lot_id,
                    };
                    self.unique_cargo.put(
                        txn,
                        &unique.object_id,
                        &encode_unique_cargo(&unique)?,
                    )?;
                }
                destination.cargo.push(moved);
            }
            crate::wire::StoreTransferKind::Fuel => {
                if source.current_fuel_millitons < quantity {
                    return Ok(RuleResult::Rejected(
                        "the source tanks contain less fuel".into(),
                    ));
                }
                let spec = creation::ship_status_spec(destination.catalog_id)
                    .ok_or(StoreError::Corrupt("destination catalog data is missing"))?;
                if destination.current_fuel_millitons.saturating_add(quantity)
                    > effective_fuel_capacity(&destination, &spec)
                {
                    return Ok(RuleResult::Rejected(
                        "the destination tanks lack capacity".into(),
                    ));
                }
                source.current_fuel_millitons -= quantity;
                destination.current_fuel_millitons += quantity;
            }
            crate::wire::StoreTransferKind::Ammunition => {
                let Some(source_lot) = source
                    .ammunition
                    .iter_mut()
                    .find(|lot| lot.ammunition_id == item_id)
                else {
                    return Ok(RuleResult::Rejected(
                        "that ammunition is not aboard the source vessel".into(),
                    ));
                };
                let units = u32::try_from(quantity)
                    .map_err(|_| StoreError::Corrupt("ammunition transfer quantity overflow"))?;
                if source_lot.remaining < units {
                    return Ok(RuleResult::Rejected(
                        "the source magazine contains less ammunition".into(),
                    ));
                }
                let Some(destination_lot) = destination
                    .ammunition
                    .iter_mut()
                    .find(|lot| lot.ammunition_id == item_id)
                else {
                    return Ok(RuleResult::Rejected(
                        "the destination has no compatible magazine".into(),
                    ));
                };
                if destination_lot.remaining.saturating_add(units) > destination_lot.capacity {
                    return Ok(RuleResult::Rejected(
                        "the destination magazine lacks capacity".into(),
                    ));
                }
                source_lot.remaining -= units;
                destination_lot.remaining += units;
            }
            crate::wire::StoreTransferKind::Provisions => {
                if source.provisions.person_days_remaining < quantity {
                    return Ok(RuleResult::Rejected(
                        "the source vessel has fewer provisions".into(),
                    ));
                }
                if destination
                    .provisions
                    .person_days_remaining
                    .saturating_add(quantity)
                    > destination.provisions.installed_capacity_person_days
                {
                    return Ok(RuleResult::Rejected(
                        "the destination lockers lack capacity".into(),
                    ));
                }
                source.provisions.person_days_remaining -= quantity;
                destination.provisions.person_days_remaining += quantity;
            }
        }
        source.revision = source.revision.saturating_add(1);
        destination.revision = destination.revision.saturating_add(1);
        player.fleet_revision = player.fleet_revision.saturating_add(1);
        self.ships
            .put(txn, &from_ship_id, &encode_ship_record(&source)?)?;
        self.ships
            .put(txn, &to_ship_id, &encode_ship_record(&destination)?)?;
        self.players
            .put(txn, &identity_key, &encode_player_record(&player))?;
        Ok(RuleResult::Applied(self.fleet_snapshot_in(txn, identity)?))
    }

    fn materialize_captured_ship_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        player: &mut PlayerRecord,
        captor: &ShipRecord,
        captured: &crate::combat::VesselState,
        title: crate::wire::ShipTitleKind,
        current_second: u64,
    ) -> Result<(u64, Vec<u64>), StoreError> {
        let ship_id = take_id_range(self.meta, txn, META_NEXT_SHIP_ID, 1)?;
        let spec = creation::ship_status_spec(captured.catalog_id).ok_or(StoreError::Corrupt(
            "captured vessel catalog data is missing",
        ))?;
        let mut ship = ShipRecord {
            revision: 1,
            ship_id,
            catalog_id: captured.catalog_id,
            catalog_revision: creation::ship_catalog_revision(captured.catalog_id).ok_or(
                StoreError::Corrupt("captured vessel catalog revision is missing"),
            )?,
            name: captured.name.clone(),
            career: captor.career,
            command: identity.clone(),
            commanding_person_id: 0,
            standing_order: crate::wire::ManagedShipOrderKind::Hold,
            system_id: captor.system_id,
            current_fuel_millitons: spec.fuel_capacity_millitons / 2,
            unrefined_fuel_millitons: 0,
            fuel_capacity_bonus_millitons: 0,
            cargo_capacity_penalty_millitons: 0,
            power_fuel_last_settled_second: u64::MAX,
            power_fuel_burn_remainder: 0,
            location: captor.location,
            cargo: Vec::new(),
            passengers: Vec::new(),
            ammunition: captured
                .ammunition
                .iter()
                .map(|lot| {
                    let template = new_ship_ammunition(captured.catalog_id)
                        .into_iter()
                        .find(|template| template.ammunition_id == lot.ammunition_id);
                    template.map_or(
                        ShipAmmunitionRecord {
                            ammunition_id: lot.ammunition_id.clone(),
                            remaining: lot.remaining,
                            capacity: lot.remaining,
                            pack_units: 1,
                            price_per_pack_credits: 0,
                        },
                        |mut template| {
                            template.remaining = lot.remaining.min(template.capacity);
                            template
                        },
                    )
                })
                .collect(),
            provisions: new_ship_provisions(&spec, current_second),
            subsystems: new_ship_subsystems(&spec, current_second)?,
            maintenance: new_ship_maintenance(&spec, current_second)?,
            latent_quirks: Vec::new(),
            activity: None,
            mail_custody: None,
            combat_policy: crate::combat::AutomationPolicy::default(),
            recovery_plan: None,
            service_ledger: Vec::new(),
        };
        apply_combat_damage_to_ship(captured, &mut ship);
        for subsystem in &mut ship.subsystems {
            subsystem.battlefield_repair_hits = 0;
        }
        if spec.cargo_capacity_millitons >= MILLITONS_PER_TON {
            let entropy = crate::ship_condition::mix64(captured.vessel_id ^ current_second);
            if let Some(commodity) =
                crate::commerce::commodity_by_index(entropy % crate::commerce::COMMODITY_COUNT)
            {
                let quantity = ((1 + entropy.rotate_left(17) % 20) * MILLITONS_PER_TON)
                    .min(spec.cargo_capacity_millitons / 4)
                    .max(MILLITONS_PER_TON);
                ship.cargo.push(CargoLot {
                    cargo_lot_id: take_id_range(self.meta, txn, META_NEXT_CARGO_LOT_ID, 1)?,
                    commodity_id: commodity.id,
                    commodity_name: commodity.name.into(),
                    quantity_millitons: quantity,
                    purchase_price_per_ton: commodity.base_price_per_ton,
                    origin_system_id: captor.system_id,
                    acquired_second: current_second,
                    title: CargoTitle::PlayerOwned,
                    task_id: 0,
                    unique_object_id: 0,
                    condition_percent: 100,
                    destination_system_id: 0,
                    source_body_id: 0,
                    source_lode_id: 0,
                });
            }
        }
        let gross = creation::ship_market_catalog()
            .into_iter()
            .find(|entry| entry.catalog_id == captured.catalog_id)
            .map_or(0, |entry| entry.price_credits);
        self.ships.put(txn, &ship_id, &encode_ship_record(&ship)?)?;
        self.finances.put(
            txn,
            &ship_finance_key(ship_id),
            &encode_finance_record(&FinanceRecord {
                title,
                restricted_credits: 0,
                original_hull_price_credits: gross,
                principal_credits: 0,
                monthly_payment_credits: 0,
                monthly_insurance_escrow_credits: 0,
                next_payment_due_second: current_second
                    .saturating_add(crate::ship_condition::ACCOUNTING_MONTH_SECONDS),
                paid_through_second: current_second,
                in_default: false,
                impound_order_known_locally: false,
                impound_message_id: 0,
                authorized_expense_credits: 0,
                forged_receipt_credits: 0,
                forged_receipt_count: 0,
                forged_receipt_bbs_id: 0,
                forged_receipt_player_id: 0,
            }),
        )?;
        self.schedule_ship_condition_in(txn, ship_id, ship.maintenance.next_accounting_second)?;
        player.managed_ship_ids.push(ship_id);
        player.fleet_revision = player.fleet_revision.saturating_add(1);
        let minimum_crew = creation::ship_market_catalog()
            .into_iter()
            .find(|entry| entry.catalog_id == captured.catalog_id)
            .map_or(1, |entry| entry.minimum_crew.max(1));
        let casualties = captured.crew_hits.div_ceil(3).min(minimum_crew);
        let survivor_count = minimum_crew.saturating_sub(casualties);
        let first_person_id = if survivor_count == 0 {
            0
        } else {
            take_id_range(
                self.meta,
                txn,
                META_NEXT_PERSON_ID,
                u64::from(survivor_count),
            )?
        };
        let mut captured_person_ids = Vec::with_capacity(usize::from(survivor_count));
        for ordinal in 0..survivor_count {
            let person_id = first_person_id.saturating_add(u64::from(ordinal));
            let entropy = crate::ship_condition::mix64(
                captured.vessel_id ^ current_second ^ u64::from(ordinal).rotate_left(23),
            );
            let characteristics = crate::wire::Characteristics {
                strength: 6 + (entropy % 5) as u8,
                dexterity: 6 + (entropy.rotate_left(7) % 5) as u8,
                endurance: 6 + (entropy.rotate_left(13) % 5) as u8,
                intelligence: 6 + (entropy.rotate_left(19) % 5) as u8,
                education: 6 + (entropy.rotate_left(29) % 5) as u8,
                charisma: 6 + (entropy.rotate_left(37) % 5) as u8,
            };
            let person = PersonRecord {
                person_id,
                origin_bbs_id: 0,
                origin_system_id: captor.system_id,
                person: crate::wire::PersonDraft {
                    name: crate::person_names::generated_person_name(entropy, person_id),
                    characteristics,
                    skills: vec![crate::wire::SkillRating {
                        skill: crate::wire::SkillId::Mechanic,
                        level: 0,
                    }],
                    training: crate::wire::SkillTraining {
                        skill: crate::wire::SkillId::Mechanic,
                        needed_weeks: 8,
                        current_weeks: 0,
                    },
                },
                current_strength: characteristics.strength,
                current_dexterity: characteristics.dexterity,
                current_endurance: characteristics.endurance,
                fatigue_points: 0,
                last_injury_second: 0,
                first_aid_applied: false,
                last_treatment_second: current_second,
                pending_treatment_effect: 0,
                pending_treatment_due_second: 0,
                unfed_days: 0,
            };
            self.persons
                .put(txn, &person_id, &encode_person_record(&person)?)?;
            captured_person_ids.push(person_id);
        }
        Ok((ship_id, captured_person_ids))
    }

    fn finance_snapshot_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<crate::wire::FinanceSnapshot, StoreError> {
        let (player, ship) = self.player_and_ship_in(txn, identity)?;
        let identity_key = encode_identity(identity);
        let key = ship_finance_key(ship.ship_id);
        let mut finance = self
            .finances
            .get(txn, &key)?
            .map(decode_finance_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("finance record is missing"))?;
        if finance.impound_message_id != 0 && !finance.impound_order_known_locally {
            let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
            if self
                .simulation
                .available_messages(txn, ship.system_id, current, true)?
                .iter()
                .any(|message| message.message.message_id == finance.impound_message_id)
            {
                finance.impound_order_known_locally = true;
                self.finances
                    .put(txn, &key, &encode_finance_record(&finance))?;
            }
        }
        let reserved = self.task_ledger_in(txn, identity)?.reserved_credits;
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let mut insurance_key = identity_key.to_vec();
        insurance_key.push(1);
        let destination_assistance_expires_second = self
            .insurance_policies
            .get(txn, &insurance_key)?
            .map(|bytes| {
                let bytes: [u8; 8] = bytes
                    .try_into()
                    .map_err(|_| StoreError::Corrupt("invalid insurance expiry record"))?;
                Ok::<u64, StoreError>(u64::from_be_bytes(bytes))
            })
            .transpose()?
            .unwrap_or(0);
        Ok(crate::wire::FinanceSnapshot {
            title: finance.title,
            liquid_credits: player.credits,
            restricted_credits: finance.restricted_credits,
            reserved_credits: reserved,
            original_hull_price_credits: finance.original_hull_price_credits,
            principal_credits: finance.principal_credits,
            monthly_payment_credits: finance.monthly_payment_credits,
            monthly_insurance_escrow_credits: finance.monthly_insurance_escrow_credits,
            next_payment_due_second: finance.next_payment_due_second,
            grace_expires_second: finance
                .next_payment_due_second
                .saturating_add(crate::ship_condition::ACCOUNTING_MONTH_SECONDS),
            paid_through_second: finance.paid_through_second,
            in_default: finance.in_default,
            impound_order_known_locally: finance.impound_order_known_locally,
            credit_status: if finance.impound_order_known_locally {
                if finance.principal_credits == 0 && finance.monthly_insurance_escrow_credits != 0 {
                    "A sponsor-insurance impound order has reached local authorities".into()
                } else {
                    "A secured-credit impound order has reached local authorities".into()
                }
            } else if finance.in_default {
                if finance.principal_credits == 0 && finance.monthly_insurance_escrow_credits != 0 {
                    "Mandatory sponsor insurance is in default; an impound order has been filed"
                        .into()
                } else {
                    "Payment is in default; an impound order has been filed".into()
                }
            } else if finance.principal_credits == 0 {
                "Clear title or institutional account".into()
            } else {
                "Account current".into()
            },
            destination_assistance_active: current < destination_assistance_expires_second,
            destination_assistance_expires_second,
        })
    }

    fn market_knowledge_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<crate::wire::MarketKnowledge, StoreError> {
        let mut observations = Vec::new();
        for entry in self.market_observations.iter(txn)? {
            let (_, v) = entry?;
            let (id, o) = decode_stored_observation(v)?;
            if id == *identity {
                observations.push(o);
            }
        }
        observations.sort_by_key(|o| (o.system_id, o.commodity_id));
        Ok(crate::wire::MarketKnowledge {
            current_second: get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0),
            observations,
        })
    }

    fn record_market_snapshot_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        snapshot: &MarketSnapshot,
    ) -> Result<(), StoreError> {
        let acquired = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        for offer in &snapshot.offers {
            let observation = crate::wire::MarketObservation {
                system_id: snapshot.system_id,
                system_name: snapshot.world_name.clone(),
                commodity_id: offer.commodity_id,
                commodity_name: offer.commodity_name.clone(),
                observed_second: snapshot.generated_day * crate::simulation::SECONDS_PER_DAY,
                acquired_second: acquired,
                source: "Captain's port market observation".into(),
                confidence_percent: 100,
                minimum_price_per_ton: offer.purchase_price_per_ton,
                maximum_price_per_ton: offer.purchase_price_per_ton,
                minimum_available_millitons: offer.available_millitons,
                maximum_available_millitons: offer.available_millitons,
            };
            let mut key = Vec::from(encode_identity(identity));
            key.extend_from_slice(&snapshot.system_id.to_be_bytes());
            key.extend_from_slice(&offer.commodity_id.to_be_bytes());
            self.market_observations.put(
                txn,
                &key,
                &encode_stored_observation(identity, &observation)?,
            )?;
        }
        Ok(())
    }

    fn ship_market_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<crate::wire::ShipMarket, StoreError> {
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked { facility_id, .. } = ship.location else {
            return Err(StoreError::Corrupt("ship market requested while underway"));
        };
        let day = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0)
            / crate::simulation::SECONDS_PER_DAY;
        let current = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship status data missing"))?;
        let condition = ship
            .subsystems
            .iter()
            .map(|s| 100_u64.saturating_sub(u64::from(s.sustained_hits) * 25))
            .sum::<u64>()
            / ship.subsystems.len().max(1) as u64;
        let trade_in = current
            .construction_price_credits
            .saturating_mul(condition)
            .saturating_mul(55)
            / 10_000;
        let lien = self
            .finances
            .get(txn, &ship_finance_key(ship.ship_id))?
            .map(decode_finance_record)
            .transpose()?
            .map_or(0, |f| f.principal_credits);
        let system = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship-market system missing"))?;
        let world = self.primary_world_in(txn, &system)?;
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship-market facility missing"))?;
        let mut catalog = creation::ship_market_catalog()
            .into_iter()
            .filter(|entry| entry.tech_level <= world.tech_level)
            .collect::<Vec<_>>();
        catalog.sort_by_key(|entry| entry.catalog_id);
        let count = catalog.len().min(7);
        let start =
            (crate::ship_condition::mix64(ship.system_id ^ day) as usize) % catalog.len().max(1);
        let mut offers = Vec::new();
        for i in 0..count {
            let source = &catalog[(start + i) % catalog.len()];
            let entropy =
                crate::ship_condition::mix64(day ^ ship.system_id ^ u64::from(source.catalog_id));
            let used = entropy % 3 != 0;
            let age = if used { 12 + (entropy % 228) as u32 } else { 0 };
            let visible = if used { 65 + (entropy % 31) as u8 } else { 100 };
            let price = if used {
                source
                    .price_credits
                    .saturating_mul(u64::from(visible))
                    .saturating_mul(80)
                    / 10_000
            } else {
                source.price_credits
            };
            offers.push(crate::wire::ShipMarketOffer {
                offer_id: crate::ship_condition::mix64(entropy ^ 0x5348_4950_4d41_524b),
                catalog_id: source.catalog_id,
                class_name: source.class_name.clone(),
                price_credits: price,
                original_price_credits: source.price_credits,
                used,
                age_months: age,
                visible_condition_percent: visible,
                cargo_capacity_millitons: source.cargo_capacity_millitons,
                jump_rating: source.jump_rating,
                minimum_crew: source.minimum_crew,
            });
        }
        let mut unclaimed = Vec::with_capacity(offers.len());
        for offer in offers {
            if self
                .market_claims
                .get(txn, &market_claim_key(1, offer.offer_id))?
                .is_none()
            {
                unclaimed.push(offer);
            }
        }
        let mut commissionable_designs = creation::ship_market_catalog()
            .into_iter()
            .filter(|entry| {
                facility.operational
                    && facility.repair_shop
                    && entry.tech_level <= facility.maximum_component_tech_level
                    && entry.displacement_millitons <= facility.maximum_yard_hull_millitons
            })
            .map(|entry| crate::wire::ShipCommissionDesign {
                catalog_id: entry.catalog_id,
                class_name: entry.class_name,
                tech_level: entry.tech_level,
                price_credits: entry.price_credits,
                deposit_credits: entry.price_credits / 5,
                construction_seconds: u64::from(entry.construction_weeks)
                    .saturating_mul(crate::ship_condition::SECONDS_PER_WEEK),
                displacement_millitons: entry.displacement_millitons,
                jump_rating: entry.jump_rating,
                fuel_capacity_millitons: entry.fuel_capacity_millitons,
                jump_fuel_millitons: entry.jump_fuel_millitons,
                cargo_capacity_millitons: entry.cargo_capacity_millitons,
                minimum_crew: entry.minimum_crew,
            })
            .collect::<Vec<_>>();
        commissionable_designs.sort_by(|a, b| {
            b.jump_rating.cmp(&a.jump_rating).then(
                a.class_name
                    .cmp(&b.class_name)
                    .then(a.catalog_id.cmp(&b.catalog_id)),
            )
        });
        Ok(crate::wire::ShipMarket {
            generated_day: day,
            current_ship_trade_in_credits: trade_in,
            outstanding_lien_credits: lien,
            offers: unclaimed,
            commissionable_designs,
        })
    }

    fn crew_market_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<crate::wire::CrewMarket, StoreError> {
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked { facility_id, .. } = ship.location else {
            return Err(StoreError::Corrupt(
                "crew exchange requested while underway",
            ));
        };
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("crew-exchange facility is missing"))?;
        if !facility.operational || !facility.personnel_exchange {
            return Err(StoreError::Corrupt(
                "crew exchange requested at a port without personnel services",
            ));
        }
        let day = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0)
            / crate::simulation::SECONDS_PER_DAY;
        let roles = [
            ("Pilot", crate::wire::SkillId::PilotSpacecraft),
            ("Navigator", crate::wire::SkillId::Astrogation),
            ("Engineer", crate::wire::SkillId::EngineerJump),
            ("Medic", crate::wire::SkillId::Medicine),
            ("Steward", crate::wire::SkillId::Etiquette),
            ("Gunner", crate::wire::SkillId::GunnerTurrets),
        ];
        let mut candidates = Vec::new();
        let mut used_names = HashSet::new();
        for i in 0..6 {
            let entropy = crate::ship_condition::mix64(ship.system_id ^ day ^ ((i as u64) << 40));
            let (role, skill) = roles[entropy as usize % roles.len()];
            let level = (entropy % 3) as i8;
            let candidate_id = crate::ship_condition::mix64(entropy ^ 0x4352_4557_4d41_524b);
            let mut name_discriminator = candidate_id;
            let name = loop {
                let candidate =
                    crate::person_names::generated_person_name(entropy, name_discriminator);
                if used_names.insert(candidate.clone()) {
                    break candidate;
                }
                name_discriminator = name_discriminator.wrapping_add(1);
            };
            candidates.push(crate::wire::CrewCandidate {
                candidate_id,
                role: role.into(),
                name,
                primary_skill: skill,
                skill_level: level,
                monthly_salary_credits: 1_000 * (1 + u64::from(level as u8)).pow(2),
            });
        }
        let mut unclaimed = Vec::with_capacity(candidates.len());
        for candidate in candidates {
            if self
                .market_claims
                .get(txn, &market_claim_key(2, candidate.candidate_id))?
                .is_none()
            {
                unclaimed.push(candidate);
            }
        }
        Ok(crate::wire::CrewMarket {
            generated_day: day,
            candidates: unclaimed,
        })
    }

    fn hire_crew_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        candidate_id: u64,
    ) -> Result<RuleResult<crate::wire::CrewMarket>, StoreError> {
        let (player, ship) = self.player_and_ship_in(txn, identity)?;
        if !matches!(ship.location, ShipLocationRecord::Docked { .. }) {
            return Ok(RuleResult::Rejected(
                "crew may only be hired while docked".into(),
            ));
        }
        let Some(candidate) = self
            .crew_market_in(txn, identity)?
            .candidates
            .into_iter()
            .find(|c| c.candidate_id == candidate_id)
        else {
            return Ok(RuleResult::Rejected(
                "candidate is no longer available".into(),
            ));
        };
        if self
            .crew_services
            .iter(txn)?
            .filter_map(Result::ok)
            .filter_map(|(_, v)| decode_crew_service(v).ok())
            .any(|s| s.command == *identity && s.person_id == candidate_id)
        {
            return Ok(RuleResult::Rejected(
                "candidate has already signed articles".into(),
            ));
        }
        let person_id = take_id_range(self.meta, txn, META_NEXT_PERSON_ID, 1)?;
        let skills = vec![
            crate::wire::SkillRating {
                skill: candidate.primary_skill,
                level: candidate.skill_level,
            },
            crate::wire::SkillRating {
                skill: crate::wire::SkillId::JackOfAllTrades,
                level: 0,
            },
        ];
        let training = creation::initial_training(&skills, candidate.primary_skill)
            .ok_or(StoreError::Corrupt("crew candidate has invalid training"))?;
        let person = PersonRecord {
            person_id,
            origin_bbs_id: identity.bbs_id,
            origin_system_id: ship.system_id,
            person: crate::wire::PersonDraft {
                name: candidate.name.clone(),
                characteristics: crate::wire::Characteristics {
                    strength: 8,
                    dexterity: 9,
                    endurance: 8,
                    intelligence: 10,
                    education: 7,
                    charisma: 6,
                },
                skills,
                training,
            },
            current_strength: 8,
            current_dexterity: 9,
            current_endurance: 8,
            fatigue_points: 0,
            last_injury_second: 0,
            first_aid_applied: false,
            last_treatment_second: 0,
            pending_treatment_effect: 0,
            pending_treatment_due_second: 0,
            unfed_days: 0,
        };
        let slot_id = self
            .crew_services
            .iter(txn)?
            .filter_map(Result::ok)
            .filter_map(|(_, v)| decode_crew_service(v).ok())
            .filter(|s| s.ship_id == player.ship_id)
            .map(|s| s.slot_id)
            .max()
            .unwrap_or(0)
            .saturating_add(1);
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        self.persons
            .put(txn, &person_id, &encode_person_record(&person)?)?;
        self.crew_services.put(
            txn,
            &person_id,
            &encode_crew_service(&CrewServiceRecord {
                person_id,
                ship_id: player.ship_id,
                slot_id,
                role: candidate.role,
                represented_positions: 1,
                assigned_slot_ids: Vec::new(),
                service_kind: CrewServiceKind::Salaried,
                monthly_salary_credits: candidate.monthly_salary_credits,
                prize_share_basis_points: 0,
                arrears_credits: 0,
                service_start_second: current,
                service_end_second: 0,
                morale: 70,
                loyalty: 60,
                risk_tolerance: 50,
                availability: CrewAvailability::Active,
                available_second: current,
                shore_system_id: 0,
                shore_facility_id: 0,
                revision: 1,
                command: identity.clone(),
            })?,
        )?;
        self.market_claims
            .put(txn, &market_claim_key(2, candidate_id), &[1])?;
        self.schedule_person_training_in(
            txn,
            person_id,
            current.saturating_add(crate::ship_condition::SECONDS_PER_WEEK),
        )?;
        Ok(RuleResult::Applied(self.crew_market_in(txn, identity)?))
    }

    fn purchase_ship_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        offer_id: u64,
        trade_in: bool,
    ) -> Result<RuleResult<crate::wire::ShipMarket>, StoreError> {
        let (mut player, old_ship) = self.player_and_ship_in(txn, identity)?;
        if !matches!(old_ship.location, ShipLocationRecord::Docked { .. }) {
            return Ok(RuleResult::Rejected(
                "title transfer requires the commanded ship to be docked".into(),
            ));
        }
        if trade_in
            && self.task_ledger_in(txn, identity)?.tasks.iter().any(|t| {
                t.performing_ship_id == old_ship.ship_id
                    && !matches!(
                        t.state,
                        crate::wire::TaskState::Completed
                            | crate::wire::TaskState::Cancelled
                            | crate::wire::TaskState::Expired
                            | crate::wire::TaskState::Defaulted
                    )
            })
        {
            return Ok(RuleResult::Rejected(
                "active obligations must be settled or transferred before a ship trade".into(),
            ));
        }
        if trade_in
            && (old_ship.cargo.iter().any(|lot| lot.task_id != 0)
                || !old_ship.passengers.is_empty())
        {
            return Ok(RuleResult::Rejected(
                "passengers and entrusted cargo must be discharged before title transfer".into(),
            ));
        }
        let market = self.ship_market_in(txn, identity)?;
        let Some(offer) = market.offers.into_iter().find(|o| o.offer_id == offer_id) else {
            return Ok(RuleResult::Rejected(
                "ship offer is no longer available".into(),
            ));
        };
        let spec = creation::ship_status_spec(offer.catalog_id)
            .ok_or(StoreError::Corrupt("ship-market catalog data missing"))?;
        let cargo_used: u64 = old_ship.cargo.iter().map(|c| c.quantity_millitons).sum();
        if trade_in && cargo_used > spec.cargo_capacity_millitons {
            return Ok(RuleResult::Rejected(
                "cargo aboard does not fit the selected vessel".into(),
            ));
        }
        let identity_key = encode_identity(identity);
        let old_finance_key = ship_finance_key(old_ship.ship_id);
        let old_finance = self
            .finances
            .get(txn, &old_finance_key)?
            .map(decode_finance_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("finance record missing"))?;
        let finance = FinanceRecord {
            title: crate::wire::ShipTitleKind::OwnedWithLien,
            restricted_credits: 0,
            original_hull_price_credits: offer.original_price_credits,
            principal_credits: offer.price_credits.saturating_mul(4) / 5,
            monthly_payment_credits: offer.price_credits.div_ceil(240),
            monthly_insurance_escrow_credits: offer
                .price_credits
                .saturating_mul(102)
                .div_ceil(10_000)
                .saturating_add(15_000)
                .div_ceil(12),
            next_payment_due_second: get_meta_u64(self.meta, txn, META_GAME_SECOND)?
                .unwrap_or(0)
                .saturating_add(crate::ship_condition::ACCOUNTING_MONTH_SECONDS),
            paid_through_second: get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0),
            in_default: false,
            impound_order_known_locally: false,
            impound_message_id: 0,
            authorized_expense_credits: 0,
            forged_receipt_credits: 0,
            forged_receipt_count: 0,
            forged_receipt_bbs_id: 0,
            forged_receipt_player_id: 0,
        };
        match old_finance.title {
            crate::wire::ShipTitleKind::OwnedWithLien => {
                let equity = if trade_in {
                    market
                        .current_ship_trade_in_credits
                        .saturating_sub(old_finance.principal_credits)
                } else {
                    0
                };
                let down = offer.price_credits / 5;
                let cash = down.saturating_sub(equity);
                if player.credits < cash {
                    return Ok(RuleResult::Rejected(format!(
                        "title transfer requires Cr{} cash after lien settlement",
                        cash
                    )));
                }
                player.credits -= cash;
            }
            crate::wire::ShipTitleKind::SponsorOwned => {
                // The sponsor receives its vessel back; the captain may use
                // accumulated prize money as the deposit on a private hull.
                let down = offer.price_credits / 5;
                if player.credits < down {
                    return Ok(RuleResult::Rejected(format!(
                        "private title transfer requires a Cr{down} deposit"
                    )));
                }
                player.credits -= down;
            }
            crate::wire::ShipTitleKind::InstitutionOwned => {
                if trade_in {
                    return Ok(RuleResult::Rejected(
                        "an Admiralty vessel cannot be offered in a private title transfer".into(),
                    ));
                }
                let down = offer.price_credits / 5;
                if player.credits < down {
                    return Ok(RuleResult::Rejected(format!(
                        "private title transfer requires a Cr{down} deposit"
                    )));
                }
                player.credits -= down;
            }
            crate::wire::ShipTitleKind::OwnedClear => {
                let equity = if trade_in {
                    market.current_ship_trade_in_credits
                } else {
                    0
                };
                let down = offer.price_credits / 5;
                let cash = down.saturating_sub(equity);
                if player.credits < cash {
                    return Ok(RuleResult::Rejected(format!(
                        "title transfer requires Cr{cash} cash"
                    )));
                }
                player.credits -= cash;
            }
            crate::wire::ShipTitleKind::PrizeCustody
            | crate::wire::ShipTitleKind::StolenRegistry
            | crate::wire::ShipTitleKind::CourtImpound => {
                return Ok(RuleResult::Rejected(
                    "the commanded vessel does not have transferable market title".into(),
                ));
            }
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let ship_id = take_id_range(self.meta, txn, META_NEXT_SHIP_ID, 1)?;
        let mut maintenance = new_ship_maintenance(&spec, current)?;
        if offer.used {
            maintenance.commissioned_second = current.saturating_sub(
                u64::from(offer.age_months) * crate::ship_condition::ACCOUNTING_MONTH_SECONDS,
            );
            maintenance.warranty_expires_second = 0;
        }
        let mut subsystems = new_ship_subsystems(&spec, current)?;
        for subsystem in &mut subsystems {
            subsystem.calendar_age_months = offer.age_months;
        }
        let mut new_ship = ShipRecord {
            revision: 1,
            ship_id,
            catalog_id: offer.catalog_id,
            catalog_revision: creation::ship_catalog_revision(offer.catalog_id)
                .ok_or(StoreError::Corrupt("ship-market catalog revision missing"))?,
            name: if trade_in {
                old_ship.name.clone()
            } else {
                crate::traffic::registered_ship_name(ship_id, offer.catalog_id)
            },
            career: old_ship.career,
            command: identity.clone(),
            commanding_person_id: if trade_in {
                old_ship.commanding_person_id
            } else {
                0
            },
            standing_order: crate::wire::ManagedShipOrderKind::Hold,
            system_id: old_ship.system_id,
            current_fuel_millitons: if trade_in {
                old_ship
                    .current_fuel_millitons
                    .min(spec.fuel_capacity_millitons)
            } else {
                spec.fuel_capacity_millitons
            },
            unrefined_fuel_millitons: if trade_in {
                old_ship
                    .unrefined_fuel_millitons
                    .min(spec.fuel_capacity_millitons)
            } else {
                0
            },
            fuel_capacity_bonus_millitons: 0,
            cargo_capacity_penalty_millitons: 0,
            power_fuel_last_settled_second: u64::MAX,
            power_fuel_burn_remainder: 0,
            location: old_ship.location,
            cargo: if trade_in {
                old_ship.cargo.clone()
            } else {
                Vec::new()
            },
            passengers: if trade_in {
                old_ship.passengers.clone()
            } else {
                Vec::new()
            },
            ammunition: new_ship_ammunition(offer.catalog_id),
            provisions: new_ship_provisions(&spec, current),
            subsystems,
            maintenance,
            latent_quirks: Vec::new(),
            activity: None,
            mail_custody: None,
            combat_policy: old_ship.combat_policy.clone(),
            recovery_plan: None,
            service_ledger: Vec::new(),
        };
        if offer.used {
            let entropy = crate::ship_condition::mix64(offer.offer_id ^ ship_id);
            let candidates = aging_quirk_candidates(&new_ship);
            if let Some(index) = crate::ship_condition::stable_index(entropy, candidates.len()) {
                let (subsystem_id, kind) = candidates[index];
                new_ship.latent_quirks.push(ShipQuirkRecord {
                    quirk_id: 1,
                    subsystem_id,
                    kind,
                    attached_second: current.saturating_sub(
                        u64::from(offer.age_months)
                            * crate::ship_condition::ACCOUNTING_MONTH_SECONDS
                            / 2,
                    ),
                    manifested: false,
                    warranty_claimed: false,
                });
            }
        }
        if trade_in {
            let stale = self
                .ship_condition_events
                .iter(txn)?
                .filter_map(|entry| match entry {
                    Ok((k, v)) => match decode_scheduled_object(k, v) {
                        Ok((_, _, id)) if id == old_ship.ship_id => Some(Ok(k.to_vec())),
                        Ok(_) => None,
                        Err(e) => Some(Err(e)),
                    },
                    Err(e) => Some(Err(StoreError::Heed(e))),
                })
                .collect::<Result<Vec<_>, StoreError>>()?;
            for k in stale {
                self.ship_condition_events.delete(txn, &k)?;
            }
            let services = self
                .crew_services
                .iter(txn)?
                .filter_map(Result::ok)
                .map(|(_, v)| decode_crew_service(v))
                .collect::<Result<Vec<_>, _>>()?;
            for entry in services {
                if entry.ship_id == old_ship.ship_id && entry.command == *identity {
                    let mut service = entry;
                    service.ship_id = ship_id;
                    self.crew_services.put(
                        txn,
                        &service.person_id,
                        &encode_crew_service(&service)?,
                    )?;
                }
            }
            if let Some(mut pie) = self
                .unique_cargo
                .get(txn, &UNIQUE_APPLE_PIE_ID)?
                .map(decode_unique_cargo)
                .transpose()?
            {
                if let UniqueCargoLocation::PlayerShip {
                    ship_id: pie_ship, ..
                } = pie.location
                {
                    if pie_ship == old_ship.ship_id {
                        let lot_id = new_ship
                            .cargo
                            .iter()
                            .find(|l| l.unique_object_id == pie.object_id)
                            .map_or(0, |l| l.cargo_lot_id);
                        pie.location = UniqueCargoLocation::PlayerShip {
                            ship_id,
                            cargo_lot_id: lot_id,
                        };
                        self.unique_cargo
                            .put(txn, &pie.object_id, &encode_unique_cargo(&pie)?)?;
                    }
                }
            }
            self.ships.delete(txn, &old_ship.ship_id)?;
            self.finances.delete(txn, &old_finance_key)?;
        }
        self.ships
            .put(txn, &ship_id, &encode_ship_record(&new_ship)?)?;
        self.schedule_ship_condition_in(txn, ship_id, new_ship.maintenance.next_accounting_second)?;
        if trade_in {
            let roster_entry = player
                .managed_ship_ids
                .iter_mut()
                .find(|managed_id| **managed_id == old_ship.ship_id)
                .ok_or(StoreError::Corrupt(
                    "active ship absent from managed roster",
                ))?;
            *roster_entry = ship_id;
            player.ship_id = ship_id;
        } else {
            player.managed_ship_ids.push(ship_id);
        }
        player.fleet_revision = player.fleet_revision.saturating_add(1);
        player.debt_credits = player
            .debt_credits
            .saturating_sub(if trade_in {
                old_finance.principal_credits
            } else {
                0
            })
            .saturating_add(finance.principal_credits);
        self.players
            .put(txn, &identity_key, &encode_player_record(&player))?;
        self.finances.put(
            txn,
            &ship_finance_key(ship_id),
            &encode_finance_record(&finance),
        )?;
        self.market_claims
            .put(txn, &market_claim_key(1, offer_id), &[1])?;
        Ok(RuleResult::Applied(self.ship_market_in(txn, identity)?))
    }

    fn commission_ship_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        catalog_id: u32,
    ) -> Result<RuleResult<crate::wire::ShipMarket>, StoreError> {
        let (mut player, commanded_ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            ..
        } = commanded_ship.location
        else {
            return Ok(RuleResult::Rejected(
                "a ship commission must be placed at a dockyard".into(),
            ));
        };
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("commissioning facility is missing"))?;
        let Some(design) = creation::ship_market_catalog()
            .into_iter()
            .find(|entry| entry.catalog_id == catalog_id)
        else {
            return Ok(RuleResult::Rejected(
                "that design is not in the admitted starship catalog".into(),
            ));
        };
        if !facility.operational || !facility.repair_shop {
            return Ok(RuleResult::Rejected(
                "this port does not operate a construction yard".into(),
            ));
        }
        if design.displacement_millitons > facility.maximum_yard_hull_millitons {
            return Ok(RuleResult::Rejected(format!(
                "this yard cannot construct a {}-ton hull",
                design.displacement_millitons / 1_000
            )));
        }
        if design.tech_level > facility.maximum_component_tech_level {
            return Ok(RuleResult::Rejected(format!(
                "this yard supports components through TL{}; {} requires TL{}",
                facility.maximum_component_tech_level, design.class_name, design.tech_level
            )));
        }
        let deposit = design.price_credits / 5;
        if player.credits < deposit {
            return Ok(RuleResult::Rejected(format!(
                "the construction contract requires a Cr{deposit} deposit"
            )));
        }
        let spec = creation::ship_status_spec(catalog_id)
            .ok_or(StoreError::Corrupt("commissioned ship status data missing"))?;
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let due = current
            .checked_add(
                u64::from(design.construction_weeks)
                    .saturating_mul(crate::ship_condition::SECONDS_PER_WEEK),
            )
            .ok_or(StoreError::Corrupt("ship construction time overflow"))?;
        let ship_id = take_id_range(self.meta, txn, META_NEXT_SHIP_ID, 1)?;
        let activity_id = crate::ship_condition::mix64(
            ship_id ^ current ^ u64::from(catalog_id) ^ 0x434f_4e53_5452_5543,
        );
        let finance = FinanceRecord {
            title: crate::wire::ShipTitleKind::OwnedWithLien,
            restricted_credits: 0,
            original_hull_price_credits: design.price_credits,
            principal_credits: design.price_credits.saturating_mul(4) / 5,
            monthly_payment_credits: design.price_credits.div_ceil(240),
            monthly_insurance_escrow_credits: design
                .price_credits
                .saturating_mul(102)
                .div_ceil(10_000)
                .saturating_add(15_000)
                .div_ceil(12),
            next_payment_due_second: due
                .saturating_add(crate::ship_condition::ACCOUNTING_MONTH_SECONDS),
            paid_through_second: due,
            in_default: false,
            impound_order_known_locally: false,
            impound_message_id: 0,
            authorized_expense_credits: 0,
            forged_receipt_credits: 0,
            forged_receipt_count: 0,
            forged_receipt_bbs_id: 0,
            forged_receipt_player_id: 0,
        };
        let ship = ShipRecord {
            revision: 1,
            ship_id,
            catalog_id,
            catalog_revision: creation::ship_catalog_revision(catalog_id).ok_or(
                StoreError::Corrupt("commissioned ship catalog revision missing"),
            )?,
            name: crate::traffic::registered_ship_name(ship_id, catalog_id),
            career: commanded_ship.career,
            command: identity.clone(),
            commanding_person_id: 0,
            standing_order: crate::wire::ManagedShipOrderKind::Hold,
            system_id: commanded_ship.system_id,
            current_fuel_millitons: 0,
            unrefined_fuel_millitons: 0,
            fuel_capacity_bonus_millitons: 0,
            cargo_capacity_penalty_millitons: 0,
            power_fuel_last_settled_second: u64::MAX,
            power_fuel_burn_remainder: 0,
            location: ShipLocationRecord::Docked {
                world_id,
                facility_id,
                arrived_second: current,
            },
            cargo: Vec::new(),
            passengers: Vec::new(),
            ammunition: new_ship_ammunition(catalog_id),
            provisions: new_ship_provisions(&spec, due),
            subsystems: new_ship_subsystems(&spec, due)?,
            maintenance: new_ship_maintenance(&spec, due)?,
            latent_quirks: Vec::new(),
            activity: Some(ShipActivityRecord {
                activity_id,
                kind: ShipActivityKind::Construction,
                started_second: current,
                due_second: due,
                cost_credits: design.price_credits,
                site: ShipActivitySite::Dockyard {
                    system_id: commanded_ship.system_id,
                    world_id,
                    facility_id,
                },
            }),
            mail_custody: None,
            combat_policy: commanded_ship.combat_policy,
            recovery_plan: None,
            service_ledger: Vec::new(),
        };
        player.credits -= deposit;
        player.debt_credits = player
            .debt_credits
            .saturating_add(finance.principal_credits);
        player.managed_ship_ids.push(ship_id);
        player.fleet_revision = player.fleet_revision.saturating_add(1);
        self.ships.put(txn, &ship_id, &encode_ship_record(&ship)?)?;
        self.finances.put(
            txn,
            &ship_finance_key(ship_id),
            &encode_finance_record(&finance),
        )?;
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.schedule_ship_activity_in(txn, ship_id, due)?;
        Ok(RuleResult::Applied(self.ship_market_in(txn, identity)?))
    }

    fn begin_market_search_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        kind: crate::wire::MarketSearchKind,
        method: crate::wire::MarketSearchMethod,
        person_id: u64,
        commodity_id: u16,
        destination_system_id: u64,
    ) -> Result<RuleResult<MarketSnapshot>, StoreError> {
        let (mut player, ship) = self.player_and_ship_in(txn, identity)?;
        if !matches!(ship.location, ShipLocationRecord::Docked { .. }) {
            return Ok(RuleResult::Rejected(
                "market searches require access to the local port".into(),
            ));
        }
        if method != crate::wire::MarketSearchMethod::HiredBroker {
            let Some(service) = self.current_crew_service_in(txn, identity, person_id)? else {
                return Ok(RuleResult::Rejected(
                    "assigned searcher is not aboard the commanded ship".into(),
                ));
            };
            let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
            let person = self
                .persons
                .get(txn, &person_id)?
                .map(decode_person_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("assigned market searcher is missing"))?;
            if !service_available_for_duty(&service, current)
                || service.assigned_slot_ids.is_empty()
                || person_incapacitated(&person)
            {
                return Ok(RuleResult::Rejected(
                    "the assigned searcher must be fit and on watch".into(),
                ));
            }
        }
        if commodity_id != 0 && crate::commerce::commodity(commodity_id).is_none() {
            return Ok(RuleResult::Rejected("unknown commodity".into()));
        }
        if kind == crate::wire::MarketSearchKind::Buyer
            && !ship.cargo.iter().any(|lot| {
                lot.commodity_id == commodity_id
                    && lot.quantity_millitons != 0
                    && lot.title == CargoTitle::PlayerOwned
            })
        {
            return Ok(RuleResult::Rejected(
                "buyer searches require matching player-owned speculative cargo aboard the commanded ship"
                    .into(),
            ));
        }
        if method == crate::wire::MarketSearchMethod::HiredBroker {
            const LOCAL_BROKER_COMMISSION: u64 = 500;
            if player.credits < LOCAL_BROKER_COMMISSION {
                return Ok(RuleResult::Rejected(
                    "the operating account cannot cover the local broker's Cr500 commission".into(),
                ));
            }
            player.credits -= LOCAL_BROKER_COMMISSION;
            self.players.put(
                txn,
                &encode_identity(identity),
                &encode_player_record(&player),
            )?;
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let id = take_id_range(self.meta, txn, META_NEXT_WORK_ASSIGNMENT_ID, 1)?;
        let hours = match method {
            crate::wire::MarketSearchMethod::Physical | crate::wire::MarketSearchMethod::Online => {
                1 + crate::ship_condition::mix64(id ^ current) % 6
            }
            crate::wire::MarketSearchMethod::BlackMarket => {
                6 + crate::ship_condition::mix64(id ^ current) % 19
            }
            crate::wire::MarketSearchMethod::HiredBroker => {
                1 + crate::ship_condition::mix64(id ^ current) % 3
            }
        };
        let assignment = crate::wire::WorkAssignment {
            assignment_id: id,
            kind,
            method,
            person_id,
            commodity_id,
            destination_system_id,
            started_second: current,
            due_second: current + hours * 60,
            state: crate::wire::WorkState::Scheduled,
            result_text: "Search in progress".into(),
        };
        let stored = StoredWorkAssignment {
            identity: identity.clone(),
            system_id: ship.system_id,
            assignment: assignment.clone(),
        };
        self.work_assignments.put(
            txn,
            &id.to_be_bytes(),
            &encode_stored_work_assignment(&stored)?,
        )?;
        let event_id = self.simulation.take_scheduled_event_id(txn)?;
        self.work_assignment_events.put(
            txn,
            &scheduled_event_key(assignment.due_second, event_id),
            &encode_scheduled_object(id),
        )?;
        Ok(RuleResult::Applied(self.market_snapshot_in(txn, identity)?))
    }

    fn cancel_work_assignment_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        assignment_id: u64,
    ) -> Result<RuleResult<MarketSnapshot>, StoreError> {
        let Some(mut stored) = self
            .work_assignments
            .get(txn, &assignment_id.to_be_bytes())?
            .map(decode_stored_work_assignment)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected(
                "work assignment does not exist".into(),
            ));
        };
        if stored.identity != *identity {
            return Ok(RuleResult::Rejected(
                "work assignment belongs to another command".into(),
            ));
        }
        if stored.assignment.state != crate::wire::WorkState::Scheduled {
            return Ok(RuleResult::Rejected(
                "work assignment is no longer active".into(),
            ));
        }
        self.work_assignment_events.delete(
            txn,
            &scheduled_event_key(stored.assignment.due_second, assignment_id),
        )?;
        stored.assignment.state = crate::wire::WorkState::Cancelled;
        stored.assignment.result_text = "Cancelled before completion".into();
        self.work_assignments.put(
            txn,
            &assignment_id.to_be_bytes(),
            &encode_stored_work_assignment(&stored)?,
        )?;
        Ok(RuleResult::Applied(self.market_snapshot_in(txn, identity)?))
    }

    fn buy_cargo_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        expected_revision: u64,
        offer_id: u64,
        quantity_millitons: u64,
    ) -> Result<RuleResult<MarketSnapshot>, StoreError> {
        if quantity_millitons == 0 {
            return Ok(RuleResult::Rejected(
                "cargo must be purchased in a positive quantity".into(),
            ));
        }
        let snapshot = self.market_snapshot_in(txn, identity)?;
        if snapshot.market_revision != expected_revision {
            return Ok(RuleResult::Rejected(format!(
                "market revision is stale; current revision is {}",
                snapshot.market_revision
            )));
        }
        let normal_offer = snapshot
            .offers
            .iter()
            .find(|offer| offer.offer_id == offer_id)
            .cloned();
        let mut reserved_lead = None;
        let offer = if let Some(offer) = normal_offer {
            offer
        } else {
            let Some(stored) = self
                .market_leads
                .get(txn, &offer_id.to_be_bytes())?
                .map(decode_market_lead)
                .transpose()?
            else {
                return Ok(RuleResult::Rejected(
                    "that offer is not present in the current local market".into(),
                ));
            };
            let now = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
            if stored.identity != *identity
                || stored.lead.side != crate::wire::MarketLeadSide::Supplier
                || stored.lead.state != crate::wire::MarketLeadState::Reserved
                || stored.lead.reservation_expires_second <= now
            {
                return Ok(RuleResult::Rejected(
                    "supplier lead is not reserved and current".into(),
                ));
            }
            let definition = crate::commerce::commodity(stored.lead.commodity_id)
                .ok_or(StoreError::Corrupt("market lead commodity is missing"))?;
            let offer = MarketOffer {
                offer_id,
                commodity_id: definition.id,
                commodity_name: definition.name.into(),
                base_price_per_ton: definition.base_price_per_ton,
                purchase_price_per_ton: stored.lead.price_per_ton,
                sale_price_per_ton: 0,
                available_millitons: stored.lead.quantity_millitons,
                legality: CommodityLegality::Legal,
                price_distribution: PriceDistribution::flat(stored.lead.price_per_ton),
            };
            reserved_lead = Some(stored);
            offer
        };
        if quantity_millitons > offer.available_millitons {
            return Ok(RuleResult::Rejected(
                "the requested quantity is no longer available".into(),
            ));
        }
        if offer.offer_id == UNIQUE_APPLE_PIE_OFFER_ID && quantity_millitons != 1 {
            return Ok(RuleResult::Rejected(
                "the pie is a single one-kilogram cargo object".into(),
            ));
        }
        if offer.legality == CommodityLegality::Prohibited {
            return Ok(RuleResult::Rejected(
                "local law prohibits an open-market purchase of that commodity".into(),
            ));
        }
        if snapshot
            .cargo_used_millitons
            .checked_add(quantity_millitons)
            .is_none_or(|used| used > snapshot.cargo_capacity_millitons)
        {
            return Ok(RuleResult::Rejected(
                "the requested cargo does not fit in the ship's hold".into(),
            ));
        }
        let cost = purchase_cost_credits(offer.purchase_price_per_ton, quantity_millitons)
            .ok_or(StoreError::Corrupt("cargo purchase price overflow"))?;
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let amount_due = cost.saturating_sub(
            reserved_lead
                .as_ref()
                .map_or(0, |lead| lead.lead.escrow_credits),
        );
        if amount_due > player.credits {
            return Ok(RuleResult::Rejected(
                "the account has insufficient available credits".into(),
            ));
        }
        let game_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let game_day = game_second / crate::simulation::SECONDS_PER_DAY;
        let key = market_key(ship.system_id, game_day);
        let mut state = self
            .markets
            .get(txn, &key)?
            .map(decode_market_state)
            .transpose()?
            .unwrap_or(MarketStateRecord {
                revision: 0,
                consumed_millitons: Vec::new(),
            });
        if state.revision != expected_revision {
            return Ok(RuleResult::Rejected(format!(
                "market revision is stale; current revision is {}",
                state.revision
            )));
        }
        let consumed = if let Some((_, consumed)) = state
            .consumed_millitons
            .iter_mut()
            .find(|(commodity_id, _)| *commodity_id == offer.commodity_id)
        {
            consumed
        } else {
            state.consumed_millitons.push((offer.commodity_id, 0));
            &mut state.consumed_millitons.last_mut().expect("just pushed").1
        };
        if offer.offer_id != UNIQUE_APPLE_PIE_OFFER_ID && reserved_lead.is_none() {
            *consumed = consumed
                .checked_add(quantity_millitons)
                .ok_or(StoreError::Corrupt("market consumption overflow"))?;
        }
        state.revision = state
            .revision
            .checked_add(1)
            .ok_or(StoreError::Corrupt("market revision overflow"))?;
        let cargo_lot_id = get_meta_u64(self.meta, txn, META_NEXT_CARGO_LOT_ID)?.unwrap_or(1);
        put_meta_u64(
            self.meta,
            txn,
            META_NEXT_CARGO_LOT_ID,
            cargo_lot_id
                .checked_add(1)
                .ok_or(StoreError::Corrupt("cargo lot identifier overflow"))?,
        )?;
        player.credits -= amount_due;
        ship.cargo.push(CargoLot {
            cargo_lot_id,
            commodity_id: offer.commodity_id,
            commodity_name: offer.commodity_name.clone(),
            quantity_millitons,
            purchase_price_per_ton: offer.purchase_price_per_ton,
            origin_system_id: ship.system_id,
            acquired_second: game_second,
            title: if offer.offer_id == UNIQUE_APPLE_PIE_OFFER_ID {
                CargoTitle::UniqueObject
            } else {
                CargoTitle::PlayerOwned
            },
            task_id: 0,
            unique_object_id: if offer.offer_id == UNIQUE_APPLE_PIE_OFFER_ID {
                UNIQUE_APPLE_PIE_ID
            } else {
                0
            },
            condition_percent: 100,
            destination_system_id: 0,
            source_body_id: 0,
            source_lode_id: 0,
        });
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        if let Some(mut lead) = reserved_lead {
            lead.lead.state = crate::wire::MarketLeadState::Performed;
            lead.lead.revision = lead.lead.revision.saturating_add(1);
            self.market_leads
                .put(txn, &offer_id.to_be_bytes(), &encode_market_lead(&lead)?)?;
        }
        if offer.offer_id == UNIQUE_APPLE_PIE_OFFER_ID {
            let pie = UniqueCargoRecord {
                object_id: UNIQUE_APPLE_PIE_ID,
                name: offer.commodity_name.clone(),
                commodity_id: offer.commodity_id,
                mass_millitons: 1,
                price_credits: 1,
                location: UniqueCargoLocation::PlayerShip {
                    ship_id: ship.ship_id,
                    cargo_lot_id,
                },
            };
            self.unique_cargo
                .put(txn, &UNIQUE_APPLE_PIE_ID, &encode_unique_cargo(&pie)?)?;
        }
        self.markets.put(txn, &key, &encode_market_state(&state))?;
        Ok(RuleResult::Applied(self.market_snapshot_in(txn, identity)?))
    }

    fn sell_cargo_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        expected_revision: u64,
        cargo_lot_id: u64,
        quantity_millitons: u64,
        buyer_lead_id: u64,
    ) -> Result<RuleResult<MarketSnapshot>, StoreError> {
        if quantity_millitons == 0 {
            return Ok(RuleResult::Rejected(
                "cargo must be sold in a positive quantity".into(),
            ));
        }
        let snapshot = self.market_snapshot_in(txn, identity)?;
        if snapshot.market_revision != expected_revision {
            return Ok(RuleResult::Rejected(format!(
                "market revision is stale; current revision is {}",
                snapshot.market_revision
            )));
        }
        let Some(lot) = snapshot
            .cargo
            .iter()
            .find(|lot| lot.cargo_lot_id == cargo_lot_id)
        else {
            return Ok(RuleResult::Rejected(
                "that cargo lot is not aboard the commanded ship".into(),
            ));
        };
        if quantity_millitons > lot.quantity_millitons {
            return Ok(RuleResult::Rejected(
                "the requested sale exceeds the cargo lot quantity".into(),
            ));
        }
        if lot.title == CargoTitle::Freight || lot.title == CargoTitle::Contract {
            return Ok(RuleResult::Rejected(
                "cargo held for another party cannot be sold as speculative trade".into(),
            ));
        }
        if lot.title == CargoTitle::UniqueObject {
            if quantity_millitons != lot.quantity_millitons {
                return Ok(RuleResult::Rejected(
                    "a unique cargo object cannot be divided".into(),
                ));
            }
            let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
            let position = ship
                .cargo
                .iter()
                .position(|c| c.cargo_lot_id == cargo_lot_id)
                .ok_or(StoreError::Corrupt("unique cargo lot disappeared"))?;
            ship.cargo.remove(position);
            player.credits = player.credits.saturating_add(1);
            let pie = UniqueCargoRecord {
                object_id: lot.unique_object_id,
                name: lot.commodity_name.clone(),
                commodity_id: lot.commodity_id,
                mass_millitons: lot.quantity_millitons,
                price_credits: 1,
                location: UniqueCargoLocation::Port {
                    system_id: ship.system_id,
                },
            };
            self.unique_cargo
                .put(txn, &pie.object_id, &encode_unique_cargo(&pie)?)?;
            self.players.put(
                txn,
                &encode_identity(identity),
                &encode_player_record(&player),
            )?;
            self.ships
                .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
            return Ok(RuleResult::Applied(self.market_snapshot_in(txn, identity)?));
        }
        let (_, ship_before) = self.player_and_ship_in(txn, identity)?;
        let system = self
            .systems
            .get(txn, &ship_before.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship system is missing"))?;
        let world = self.primary_world_in(txn, &system)?;
        let game_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let game_day = game_second / crate::simulation::SECONDS_PER_DAY;
        let mut buyer_lead = if buyer_lead_id == 0 {
            None
        } else {
            let Some(stored) = self
                .market_leads
                .get(txn, &buyer_lead_id.to_be_bytes())?
                .map(decode_market_lead)
                .transpose()?
            else {
                return Ok(RuleResult::Rejected(
                    "reserved buyer lead is missing".into(),
                ));
            };
            if stored.identity != *identity
                || stored.lead.side != crate::wire::MarketLeadSide::Buyer
                || stored.lead.state != crate::wire::MarketLeadState::Reserved
                || stored.lead.commodity_id != lot.commodity_id
                || quantity_millitons > stored.lead.quantity_millitons
                || stored.lead.reservation_expires_second <= game_second
            {
                return Ok(RuleResult::Rejected(
                    "buyer reservation does not cover this sale".into(),
                ));
            }
            Some(stored)
        };
        let sale_price = if let Some(stored) = &buyer_lead {
            price_after_export_tariff(
                stored.lead.price_per_ton,
                market_tariff_basis_points(&world),
            )
        } else {
            snapshot
                .cargo_sale_quotes
                .iter()
                .find(|quote| quote.cargo_lot_id == cargo_lot_id)
                .map(|quote| quote.price_per_ton)
                .ok_or(StoreError::Corrupt("ordinary cargo sale quote is missing"))?
        };
        let proceeds = sale_proceeds_credits(sale_price, quantity_millitons)
            .ok_or(StoreError::Corrupt("cargo sale price overflow"))?;
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        player.credits = player
            .credits
            .checked_add(
                proceeds.saturating_add(
                    buyer_lead
                        .as_ref()
                        .map_or(0, |lead| lead.lead.escrow_credits),
                ),
            )
            .ok_or(StoreError::Corrupt("account balance overflow"))?;
        let lot_index = ship
            .cargo
            .iter()
            .position(|candidate| candidate.cargo_lot_id == cargo_lot_id)
            .ok_or(StoreError::Corrupt("cargo lot disappeared during sale"))?;
        ship.cargo[lot_index].quantity_millitons -= quantity_millitons;
        if ship.cargo[lot_index].quantity_millitons == 0 {
            ship.cargo.remove(lot_index);
        }
        if let Some(mut lead) = buyer_lead.take() {
            lead.lead.state = crate::wire::MarketLeadState::Performed;
            lead.lead.revision = lead.lead.revision.saturating_add(1);
            self.market_leads.put(
                txn,
                &buyer_lead_id.to_be_bytes(),
                &encode_market_lead(&lead)?,
            )?;
        }
        let key = market_key(ship.system_id, game_day);
        let mut state = self
            .markets
            .get(txn, &key)?
            .map(decode_market_state)
            .transpose()?
            .unwrap_or(MarketStateRecord {
                revision: 0,
                consumed_millitons: Vec::new(),
            });
        state.revision = state
            .revision
            .checked_add(1)
            .ok_or(StoreError::Corrupt("market revision overflow"))?;
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        self.markets.put(txn, &key, &encode_market_state(&state))?;
        Ok(RuleResult::Applied(self.market_snapshot_in(txn, identity)?))
    }

    fn docked_services_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<DockedServices, StoreError> {
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked { facility_id, .. } = ship.location else {
            return Err(StoreError::Corrupt(
                "docked services requested away from a port",
            ));
        };
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("docked facility record is missing"))?;
        let system = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship system is missing"))?;
        let celestial = derive_celestial_system(&system)?;
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let ship_tech_level = creation::ship_market_catalog()
            .into_iter()
            .find(|entry| entry.catalog_id == ship.catalog_id)
            .map(|entry| entry.tech_level)
            .ok_or(StoreError::Corrupt(
                "ship catalog technology data is missing",
            ))?;
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let days = current as f64 / crate::simulation::SECONDS_PER_DAY as f64;
        let remaining =
            effective_fuel_capacity(&ship, &spec).saturating_sub(ship.current_fuel_millitons);
        let mut fuel = Vec::new();
        let refined = facility.operational && facility.refined_fuel;
        fuel.push(DockedFuelService {
            kind: DockedFuelServiceKind::Refined,
            label: "Refined starship fuel".into(),
            source_body_id: None,
            available: refined && remaining != 0,
            unavailable_reason: if remaining == 0 {
                "The ship's fuel tanks are full.".into()
            } else if refined {
                String::new()
            } else {
                "No refined-fuel depot operates at this port.".into()
            },
            price_per_ton_credits: REFINED_FUEL_PRICE_PER_TON,
            maximum_millitons: remaining,
            service_seconds: 0,
            body_kind: FuelSourceBodyKind::NotApplicable,
            access_kind: FuelAccessKind::PortSale,
            can_refine: spec.fuel_processing_millitons_per_day != 0,
        });
        let unrefined = facility.operational && facility.unrefined_fuel;
        fuel.push(DockedFuelService {
            kind: DockedFuelServiceKind::Unrefined,
            label: "Unrefined bulk fuel".into(),
            source_body_id: None,
            available: unrefined && remaining != 0,
            unavailable_reason: if remaining == 0 {
                "The ship's fuel tanks are full.".into()
            } else if unrefined {
                String::new()
            } else {
                "No bulk-fuel depot operates at this port.".into()
            },
            price_per_ton_credits: UNREFINED_FUEL_PRICE_PER_TON,
            maximum_millitons: remaining,
            service_seconds: 0,
            body_kind: FuelSourceBodyKind::NotApplicable,
            access_kind: FuelAccessKind::PortSale,
            can_refine: spec.fuel_processing_millitons_per_day != 0,
        });
        let equipped = spec.has_fuel_scoop;
        for source in gas_giant_fuel_sources(&celestial, days, f64::from(spec.thrust_g)) {
            fuel.push(DockedFuelService {
                kind: DockedFuelServiceKind::GasGiant,
                label: format!("Skim {}", source.body_name),
                source_body_id: Some(source.body_local_id),
                available: equipped && remaining != 0,
                unavailable_reason: if remaining == 0 {
                    "The ship's fuel tanks are full.".into()
                } else if equipped {
                    String::new()
                } else {
                    "The ship lacks fuel-scooping equipment.".into()
                },
                price_per_ton_credits: 0,
                maximum_millitons: remaining,
                service_seconds: (source.round_trip_days
                    * crate::simulation::SECONDS_PER_DAY as f64)
                    .ceil() as u64
                    + mean_skimming_seconds(remaining).max(milliton_service_seconds(
                        remaining,
                        spec.fuel_processing_millitons_per_day,
                    )),
                body_kind: fuel_source_body_kind(source.body_kind),
                access_kind: FuelAccessKind::RoutineWilderness,
                can_refine: spec.fuel_processing_millitons_per_day != 0,
            });
        }
        for source in wilderness_water_sources(&celestial, days, f64::from(spec.thrust_g)) {
            fuel.push(DockedFuelService {
                kind: DockedFuelServiceKind::WildernessWater,
                label: format!("Collect water or ice at {}", source.body_name),
                source_body_id: Some(source.body_local_id),
                available: equipped && remaining != 0,
                unavailable_reason: if remaining == 0 {
                    "The ship's fuel tanks are full.".into()
                } else if equipped {
                    String::new()
                } else {
                    "The ship lacks fuel-scooping equipment.".into()
                },
                price_per_ton_credits: 0,
                maximum_millitons: remaining,
                service_seconds: (source.round_trip_days
                    * crate::simulation::SECONDS_PER_DAY as f64)
                    .ceil() as u64
                    + milliton_service_seconds(remaining, spec.fuel_processing_millitons_per_day),
                body_kind: fuel_source_body_kind(source.body_kind),
                access_kind: FuelAccessKind::RoutineWilderness,
                can_refine: spec.fuel_processing_millitons_per_day != 0,
            });
        }
        let required = crate::ship_condition::minimum_refit_starport(spec.displacement_millitons);
        let yard = facility.operational
            && facility.repair_shop
            && starport_supports_yard(facility.starport, required)
            && spec.displacement_millitons <= facility.maximum_yard_hull_millitons;
        let busy = ship.activity.is_some();
        let mut repair = Vec::new();
        for subsystem in &ship.subsystems {
            if subsystem.sustained_hits == 0 {
                continue;
            }
            let destroyed = subsystem.sustained_hits >= subsystem.maximum_hits;
            if destroyed {
                for reconditioned in [false, true] {
                    let (cost, seconds) = replacement_quote(subsystem, reconditioned);
                    let priced = subsystem.replacement_price_credits != 0;
                    repair.push(DockedRepairService {
                        subsystem_id: subsystem.subsystem_id,
                        label: format!(
                            "{} — {} replacement",
                            subsystem.label,
                            if reconditioned {
                                "reconditioned"
                            } else {
                                "new"
                            }
                        ),
                        available: yard && !busy && priced,
                        unavailable_reason: if !yard {
                            format!("This hull requires a class {required} or better yard.")
                        } else if busy {
                            "Other yard work is already active.".into()
                        } else if !priced {
                            "No admitted component price is available.".into()
                        } else {
                            String::new()
                        },
                        cost_credits: cost,
                        service_seconds: seconds,
                        replacement: true,
                        reconditioned,
                    });
                }
            } else {
                let capable = facility.operational
                    && facility.repair_shop
                    && ship_tech_level <= facility.maximum_component_tech_level;
                repair.push(DockedRepairService {
                    subsystem_id: subsystem.subsystem_id,
                    label: format!("Proper repair: {}", subsystem.label),
                    available: capable && !busy,
                    unavailable_reason: if !capable {
                        "No guaranteed starship repair shop operates here.".into()
                    } else if busy {
                        "Other yard work is already active.".into()
                    } else {
                        String::new()
                    },
                    cost_credits: 0,
                    service_seconds: u64::from(subsystem.sustained_hits)
                        * crate::ship_condition::SECONDS_PER_DAY,
                    replacement: false,
                    reconditioned: false,
                });
            }
        }
        let refit_cost =
            crate::ship_condition::refit_price_credits(ship.maintenance.purchase_price_credits);
        Ok(DockedServices {
            ship_revision: ship.revision,
            current_game_second: current,
            fuel,
            ammunition: ship
                .ammunition
                .iter()
                .map(|lot| ShipAmmunitionStatus {
                    ammunition_id: lot.ammunition_id.clone(),
                    remaining: lot.remaining,
                    capacity: lot.capacity,
                    pack_units: lot.pack_units,
                    price_per_pack_credits: lot.price_per_pack_credits,
                })
                .collect(),
            provisions: ShipProvisionStatus {
                person_days_remaining: ship.provisions.person_days_remaining,
                capacity_person_days: ship.provisions.installed_capacity_person_days,
            },
            provision_package_person_days: u64::from(spec.life_support_capacity_persons)
                .saturating_mul(30),
            provision_package_price_credits: spec.monthly_life_support_credits,
            provisions_available: facility.operational && facility.chandlery,
            ammunition_available: facility.operational && facility.ordnance,
            repair,
            refit_available: yard && !busy,
            refit_unavailable_reason: if !yard {
                format!("This hull requires a class {required} or better yard.")
            } else if busy {
                "Other yard work is already active.".into()
            } else {
                String::new()
            },
            refit_cost_credits: refit_cost,
            refit_service_seconds: crate::ship_condition::refit_duration_for_revision(
                ship.ship_id,
                ship.revision,
            ),
        })
    }

    fn buy_ship_ammunition_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        ammunition_id: &str,
        packs: u32,
    ) -> Result<RuleResult<ShipStatusSnapshot>, StoreError> {
        if packs == 0 {
            return Ok(RuleResult::Rejected(
                "at least one ammunition pack must be ordered".into(),
            ));
        }
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked { facility_id, .. } = ship.location else {
            return Ok(RuleResult::Rejected(
                "ammunition can only be loaded while docked".into(),
            ));
        };
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("docked ordnance facility is missing"))?;
        if !facility.operational || !facility.ordnance {
            return Ok(RuleResult::Rejected(
                "no licensed starship ordnance dealer operates at this port".into(),
            ));
        }
        let Some(lot) = ship
            .ammunition
            .iter_mut()
            .find(|lot| lot.ammunition_id == ammunition_id)
        else {
            return Ok(RuleResult::Rejected(
                "that ammunition is not compatible with the ship's fitted weapons".into(),
            ));
        };
        let units = packs
            .checked_mul(lot.pack_units)
            .ok_or(StoreError::Corrupt("ammunition quantity overflow"))?;
        if lot
            .remaining
            .checked_add(units)
            .is_none_or(|value| value > lot.capacity)
        {
            return Ok(RuleResult::Rejected(
                "the order exceeds the ship's catalogued magazine capacity".into(),
            ));
        }
        let cost = u64::from(packs)
            .checked_mul(lot.price_per_pack_credits)
            .ok_or(StoreError::Corrupt("ammunition price overflow"))?;
        if !self.charge_operating_account_in(txn, &mut player, ship.ship_id, cost)? {
            return Ok(RuleResult::Rejected(
                "the operating account cannot cover that ammunition order".into(),
            ));
        }
        lot.remaining += units;
        ship.revision = ship.revision.saturating_add(1);
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        Ok(RuleResult::Applied(self.ship_status_in(txn, identity)?))
    }

    fn buy_ship_provisions_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        packages: u16,
    ) -> Result<RuleResult<ProvisionPurchaseReceipt>, StoreError> {
        if packages == 0 {
            return Ok(RuleResult::Rejected(
                "at least one life-support package must be ordered".into(),
            ));
        }
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked { facility_id, .. } = ship.location else {
            return Ok(RuleResult::Rejected(
                "life-support stores can only be loaded while docked".into(),
            ));
        };
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("docked chandlery is missing"))?;
        if !facility.operational || !facility.chandlery {
            return Ok(RuleResult::Rejected(
                "no bonded chandlery supplies starships at this port".into(),
            ));
        }
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let per_package = u64::from(spec.life_support_capacity_persons).saturating_mul(30);
        let quantity = per_package.saturating_mul(u64::from(packages));
        let maximum = u64::from(spec.life_support_capacity_persons).saturating_mul(180);
        if ship
            .provisions
            .person_days_remaining
            .checked_add(quantity)
            .is_none_or(|value| value > maximum)
        {
            return Ok(RuleResult::Rejected(
                "the order exceeds the ship's six-month installed stores limit".into(),
            ));
        }
        let cost = spec
            .monthly_life_support_credits
            .saturating_mul(u64::from(packages));
        let Some(payment) =
            self.charge_operating_account_with_receipt_in(txn, &mut player, ship.ship_id, cost)?
        else {
            return Ok(RuleResult::Rejected(
                "the operating account cannot cover those life-support stores".into(),
            ));
        };
        ship.provisions.person_days_remaining += quantity;
        ship.provisions.installed_capacity_person_days = maximum;
        ship.revision = ship.revision.saturating_add(1);
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        Ok(RuleResult::Applied(ProvisionPurchaseReceipt {
            packages,
            person_days_loaded: quantity,
            person_days_remaining: ship.provisions.person_days_remaining,
            capacity_person_days: ship.provisions.installed_capacity_person_days,
            cost_credits: cost,
            restricted_payment_credits: payment.restricted_credits,
            liquid_payment_credits: payment.liquid_credits,
            restricted_balance_credits: payment.restricted_balance_credits,
            liquid_balance_credits: payment.liquid_balance_credits,
        }))
    }

    fn begin_replacement_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        subsystem_id: u16,
        reconditioned: bool,
    ) -> Result<RuleResult<ShipStatusSnapshot>, StoreError> {
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            ..
        } = ship.location
        else {
            return Ok(RuleResult::Rejected(
                "component replacement can only begin while docked".into(),
            ));
        };
        if ship.activity.is_some() {
            return Ok(RuleResult::Rejected(
                "the ship already has active yard work".into(),
            ));
        }
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt(
                "docked replacement facility is missing",
            ))?;
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let required = crate::ship_condition::minimum_refit_starport(spec.displacement_millitons);
        if !facility.operational
            || !facility.repair_shop
            || !starport_supports_yard(facility.starport, required)
            || spec.displacement_millitons > facility.maximum_yard_hull_millitons
        {
            return Ok(RuleResult::Rejected(format!(
                "this hull requires a class {required} or better replacement yard"
            )));
        }
        let subsystem = ship
            .subsystems
            .iter()
            .find(|item| item.subsystem_id == subsystem_id)
            .ok_or(StoreError::Corrupt("selected subsystem is missing"))?;
        if subsystem.sustained_hits < subsystem.maximum_hits {
            return Ok(RuleResult::Rejected(
                "only a destroyed installation enters the replacement market".into(),
            ));
        }
        if subsystem.replacement_price_credits == 0 {
            return Ok(RuleResult::Rejected(
                "no admitted component price is available for this installation".into(),
            ));
        }
        let (cost, duration) = replacement_quote(subsystem, reconditioned);
        if !self.charge_operating_account_in(txn, &mut player, ship.ship_id, cost)? {
            return Ok(RuleResult::Rejected(format!(
                "replacement costs {cost} credits; the operating account is short"
            )));
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let due = current
            .checked_add(duration)
            .ok_or(StoreError::Corrupt("replacement due time overflow"))?;
        let activity_id = crate::ship_condition::mix64(
            ship.ship_id ^ current ^ u64::from(subsystem_id) ^ 0x5245_504c_4143_4500,
        );
        ship.activity = Some(ShipActivityRecord {
            activity_id,
            kind: ShipActivityKind::Refurbishment {
                subsystem_ids: vec![subsystem_id],
                reconditioned,
            },
            started_second: current,
            due_second: due,
            cost_credits: cost,
            site: ShipActivitySite::Dockyard {
                system_id: ship.system_id,
                world_id,
                facility_id,
            },
        });
        ship.revision = ship.revision.saturating_add(1);
        self.schedule_ship_activity_in(txn, ship.ship_id, due)?;
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        Ok(RuleResult::Applied(self.ship_status_in(txn, identity)?))
    }

    fn commit_docked_service_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        order: &crate::wire::DockedServiceOrder,
    ) -> Result<RuleResult<DockedServiceReceipt>, StoreError> {
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        if ship.revision != order.expected_ship_revision {
            return Ok(RuleResult::Rejected("the ship's stores or service ledger changed; review the current dockside quotation".into()));
        }
        let mut detail = DockedServiceReceiptDetail::Generic;
        match &order.kind {
            DockedServiceOrderKind::Fuel {
                kind: DockedFuelServiceKind::Refined,
                quantity_millitons,
                ..
            } => match self.buy_fuel_in(txn, identity, *quantity_millitons)? {
                RuleResult::Applied(receipt) => {
                    detail = DockedServiceReceiptDetail::FuelPurchase(receipt)
                }
                RuleResult::Rejected(reason) => return Ok(RuleResult::Rejected(reason)),
            },
            DockedServiceOrderKind::Fuel {
                kind: DockedFuelServiceKind::Unrefined,
                quantity_millitons,
                ..
            } => match self.buy_unrefined_fuel_in(txn, identity, *quantity_millitons)? {
                RuleResult::Applied(receipt) => {
                    detail = DockedServiceReceiptDetail::FuelPurchase(receipt)
                }
                RuleResult::Rejected(reason) => return Ok(RuleResult::Rejected(reason)),
            },
            DockedServiceOrderKind::Fuel {
                kind: DockedFuelServiceKind::GasGiant,
                source_body_id: Some(source_body_id),
                quantity_millitons,
            } => match self.begin_frontier_fuel_in(
                txn,
                identity,
                *quantity_millitons,
                true,
                None,
                Some(*source_body_id),
            )? {
                RuleResult::Applied(_) => {}
                RuleResult::Rejected(reason) => return Ok(RuleResult::Rejected(reason)),
            },
            DockedServiceOrderKind::Fuel {
                kind: DockedFuelServiceKind::WildernessWater,
                source_body_id: Some(source_body_id),
                quantity_millitons,
            } => match self.begin_frontier_fuel_in(
                txn,
                identity,
                *quantity_millitons,
                false,
                None,
                Some(*source_body_id),
            )? {
                RuleResult::Applied(_) => {}
                RuleResult::Rejected(reason) => return Ok(RuleResult::Rejected(reason)),
            },
            DockedServiceOrderKind::Fuel {
                kind: DockedFuelServiceKind::GasGiant | DockedFuelServiceKind::WildernessWater,
                source_body_id: None,
                ..
            } => {
                return Ok(RuleResult::Rejected(
                    "a frontier fuel order must name the quoted celestial body".into(),
                ));
            }
            DockedServiceOrderKind::Ammunition {
                ammunition_id,
                packs,
            } => {
                return Ok(
                    match self.buy_ship_ammunition_in(txn, identity, ammunition_id, *packs)? {
                        RuleResult::Applied(ship_status) => {
                            RuleResult::Applied(DockedServiceReceipt {
                                ship_status,
                                detail: DockedServiceReceiptDetail::Generic,
                            })
                        }
                        RuleResult::Rejected(reason) => RuleResult::Rejected(reason),
                    },
                );
            }
            DockedServiceOrderKind::Provisions { packages } => {
                return Ok(
                    match self.buy_ship_provisions_in(txn, identity, *packages)? {
                        RuleResult::Applied(provision_purchase) => {
                            RuleResult::Applied(DockedServiceReceipt {
                                ship_status: self.ship_status_in(txn, identity)?,
                                detail: DockedServiceReceiptDetail::ProvisionPurchase(
                                    provision_purchase,
                                ),
                            })
                        }
                        RuleResult::Rejected(reason) => RuleResult::Rejected(reason),
                    },
                );
            }
            DockedServiceOrderKind::ProperRepair { subsystem_id } => {
                return Ok(
                    match self.begin_proper_repair_in(txn, identity, *subsystem_id)? {
                        RuleResult::Applied(ship_status) => {
                            RuleResult::Applied(DockedServiceReceipt {
                                ship_status,
                                detail: DockedServiceReceiptDetail::Generic,
                            })
                        }
                        RuleResult::Rejected(reason) => RuleResult::Rejected(reason),
                    },
                );
            }
            DockedServiceOrderKind::Refit => {
                return Ok(match self.begin_refit_in(txn, identity)? {
                    RuleResult::Applied(ship_status) => RuleResult::Applied(DockedServiceReceipt {
                        ship_status,
                        detail: DockedServiceReceiptDetail::Generic,
                    }),
                    RuleResult::Rejected(reason) => RuleResult::Rejected(reason),
                });
            }
            DockedServiceOrderKind::Replacement {
                subsystem_id,
                reconditioned,
            } => {
                return Ok(
                    match self.begin_replacement_in(txn, identity, *subsystem_id, *reconditioned)? {
                        RuleResult::Applied(ship_status) => {
                            RuleResult::Applied(DockedServiceReceipt {
                                ship_status,
                                detail: DockedServiceReceiptDetail::Generic,
                            })
                        }
                        RuleResult::Rejected(reason) => RuleResult::Rejected(reason),
                    },
                );
            }
        }
        Ok(RuleResult::Applied(DockedServiceReceipt {
            ship_status: self.ship_status_in(txn, identity)?,
            detail,
        }))
    }

    fn buy_fuel_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        quantity_millitons: u64,
    ) -> Result<RuleResult<FuelPurchaseReceipt>, StoreError> {
        if quantity_millitons == 0 || quantity_millitons % MILLITONS_PER_TON != 0 {
            return Ok(RuleResult::Rejected(
                "refined fuel must be purchased in a positive whole-ton quantity".into(),
            ));
        }
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked { facility_id, .. } = ship.location else {
            return Ok(RuleResult::Rejected(
                "fuel can only be purchased while docked".into(),
            ));
        };
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("docked fuel facility is missing"))?;
        if !facility.operational || !facility.refined_fuel {
            return Ok(RuleResult::Rejected(
                "this starport does not sell refined fuel".into(),
            ));
        }
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let capacity = effective_fuel_capacity(&ship, &spec);
        if ship
            .current_fuel_millitons
            .checked_add(quantity_millitons)
            .is_none_or(|fuel| fuel > capacity)
        {
            return Ok(RuleResult::Rejected(
                "the requested fuel exceeds tank capacity".into(),
            ));
        }
        let cost = REFINED_FUEL_PRICE_PER_TON
            .checked_mul(quantity_millitons / MILLITONS_PER_TON)
            .ok_or(StoreError::Corrupt("fuel price overflow"))?;
        let Some(payment) =
            self.charge_operating_account_with_receipt_in(txn, &mut player, ship.ship_id, cost)?
        else {
            return Ok(RuleResult::Rejected(
                "the account has insufficient available credits".into(),
            ));
        };
        ship.current_fuel_millitons += quantity_millitons;
        ship.revision = ship.revision.saturating_add(1);
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        Ok(RuleResult::Applied(FuelPurchaseReceipt {
            kind: DockedFuelServiceKind::Refined,
            quantity_millitons,
            current_fuel_millitons: ship.current_fuel_millitons,
            unrefined_fuel_millitons: ship.unrefined_fuel_millitons,
            fuel_capacity_millitons: capacity,
            cost_credits: cost,
            restricted_payment_credits: payment.restricted_credits,
            liquid_payment_credits: payment.liquid_credits,
            restricted_balance_credits: payment.restricted_balance_credits,
            liquid_balance_credits: payment.liquid_balance_credits,
        }))
    }

    fn begin_refit_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<RuleResult<ShipStatusSnapshot>, StoreError> {
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            ..
        } = ship.location
        else {
            return Ok(RuleResult::Rejected(
                "a refit can only begin while docked".into(),
            ));
        };
        if ship.activity.is_some() {
            return Ok(RuleResult::Rejected(
                "the ship already has active yard work".into(),
            ));
        }
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("docked refit facility is missing"))?;
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let required = crate::ship_condition::minimum_refit_starport(spec.displacement_millitons);
        let capable = facility.operational
            && facility.repair_shop
            && starport_supports_yard(facility.starport, required)
            && spec.displacement_millitons <= facility.maximum_yard_hull_millitons;
        if !capable {
            return Ok(RuleResult::Rejected(format!(
                "this hull requires a class {required} or better refit yard"
            )));
        }
        let cost =
            crate::ship_condition::refit_price_credits(ship.maintenance.purchase_price_credits);
        if !self.charge_operating_account_in(txn, &mut player, ship.ship_id, cost)? {
            return Ok(RuleResult::Rejected(format!(
                "the refit costs {cost} credits; the operating account is short"
            )));
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let activity_id = crate::ship_condition::mix64(ship.ship_id ^ current ^ 0x5245_4649_5400);
        let due = current
            .checked_add(crate::ship_condition::refit_duration_for_revision(
                ship.ship_id,
                ship.revision,
            ))
            .ok_or(StoreError::Corrupt("refit due time overflow"))?;
        ship.activity = Some(ShipActivityRecord {
            activity_id,
            kind: ShipActivityKind::Refit,
            started_second: current,
            due_second: due,
            cost_credits: cost,
            site: ShipActivitySite::Dockyard {
                system_id: ship.system_id,
                world_id,
                facility_id,
            },
        });
        ship.revision = ship.revision.saturating_add(1);
        self.schedule_ship_activity_in(txn, ship.ship_id, due)?;
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        Ok(RuleResult::Applied(self.ship_status_in(txn, identity)?))
    }

    fn begin_proper_repair_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        subsystem_id: u16,
    ) -> Result<RuleResult<ShipStatusSnapshot>, StoreError> {
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            arrived_second,
        } = ship.location
        else {
            return Ok(RuleResult::Rejected(
                "proper subsystem repair can only begin while docked".into(),
            ));
        };
        if ship.activity.is_some() {
            return Ok(RuleResult::Rejected(
                "the ship already has active yard work".into(),
            ));
        }
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("docked repair facility is missing"))?;
        let ship_tl = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?
            .tech_level;
        if !facility.operational
            || !facility.repair_shop
            || ship_tl > facility.maximum_component_tech_level
        {
            return Ok(RuleResult::Rejected(
                "this port has no guaranteed starship repair facility".into(),
            ));
        }
        let subsystem = ship
            .subsystems
            .iter()
            .find(|subsystem| subsystem.subsystem_id == subsystem_id)
            .ok_or_else(|| StoreError::Corrupt("selected subsystem is missing"))?;
        if subsystem.sustained_hits == 0 {
            return Ok(RuleResult::Rejected(
                "that subsystem has no physical damage".into(),
            ));
        }
        if subsystem.sustained_hits >= subsystem.maximum_hits {
            return Ok(RuleResult::Rejected(
                "a destroyed installation requires refurbishment or replacement, not minor repair"
                    .into(),
            ));
        }
        let repair_hits = u64::from(subsystem.sustained_hits);
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let berth_fee = crate::ship_condition::berth_fee_credits(arrived_second, current);
        if !self.charge_operating_account_in(txn, &mut player, ship.ship_id, berth_fee)? {
            return Ok(RuleResult::Rejected(format!(
                "frontier fueling departure requires Cr{berth_fee} to clear the berth; the operating account is short"
            )));
        }
        // The monthly upkeep charge already purchases ordinary parts and
        // repair items. This work order therefore accounts for elapsed shop
        // access rather than inventing an unsupported per-hit material price.
        let due = current
            .checked_add(repair_hits.saturating_mul(crate::ship_condition::SECONDS_PER_DAY))
            .ok_or(StoreError::Corrupt("repair due time overflow"))?;
        let activity_id = crate::ship_condition::mix64(
            ship.ship_id ^ current ^ u64::from(subsystem_id) ^ 0x5052_4f50_4552,
        );
        ship.activity = Some(ShipActivityRecord {
            activity_id,
            kind: ShipActivityKind::ProperRepair { subsystem_id },
            started_second: current,
            due_second: due,
            cost_credits: 0,
            site: ShipActivitySite::Dockyard {
                system_id: ship.system_id,
                world_id,
                facility_id,
            },
        });
        ship.revision = ship.revision.saturating_add(1);
        self.schedule_ship_activity_in(txn, ship.ship_id, due)?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        Ok(RuleResult::Applied(self.ship_status_in(txn, identity)?))
    }

    fn buy_unrefined_fuel_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        quantity_millitons: u64,
    ) -> Result<RuleResult<FuelPurchaseReceipt>, StoreError> {
        if quantity_millitons == 0 || quantity_millitons % MILLITONS_PER_TON != 0 {
            return Ok(RuleResult::Rejected(
                "unrefined fuel must be purchased in a positive whole-ton quantity".into(),
            ));
        }
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked { facility_id, .. } = ship.location else {
            return Ok(RuleResult::Rejected(
                "fuel can only be purchased while docked".into(),
            ));
        };
        let facility = self
            .facilities
            .get(txn, &facility_id)?
            .map(decode_facility)
            .transpose()?
            .ok_or(StoreError::Corrupt("docked fuel facility is missing"))?;
        if !facility.operational || !facility.unrefined_fuel {
            return Ok(RuleResult::Rejected(
                "this starport does not sell bulk unrefined fuel".into(),
            ));
        }
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let capacity = effective_fuel_capacity(&ship, &spec);
        if ship
            .current_fuel_millitons
            .checked_add(quantity_millitons)
            .is_none_or(|fuel| fuel > capacity)
        {
            return Ok(RuleResult::Rejected(
                "the requested fuel exceeds tank capacity".into(),
            ));
        }
        let cost = UNREFINED_FUEL_PRICE_PER_TON
            .checked_mul(quantity_millitons / MILLITONS_PER_TON)
            .ok_or(StoreError::Corrupt("fuel price overflow"))?;
        let Some(payment) =
            self.charge_operating_account_with_receipt_in(txn, &mut player, ship.ship_id, cost)?
        else {
            return Ok(RuleResult::Rejected(
                "the account has insufficient available credits".into(),
            ));
        };
        ship.current_fuel_millitons += quantity_millitons;
        ship.unrefined_fuel_millitons += quantity_millitons;
        ship.revision = ship.revision.saturating_add(1);
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        Ok(RuleResult::Applied(FuelPurchaseReceipt {
            kind: DockedFuelServiceKind::Unrefined,
            quantity_millitons,
            current_fuel_millitons: ship.current_fuel_millitons,
            unrefined_fuel_millitons: ship.unrefined_fuel_millitons,
            fuel_capacity_millitons: capacity,
            cost_credits: cost,
            restricted_payment_credits: payment.restricted_credits,
            liquid_payment_credits: payment.liquid_credits,
            restricted_balance_credits: payment.restricted_balance_credits,
            liquid_balance_credits: payment.liquid_balance_credits,
        }))
    }

    fn begin_frontier_fuel_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        quantity_millitons: u64,
        gas_giant: bool,
        requested_refining: Option<bool>,
        selected_body_id: Option<u32>,
    ) -> Result<RuleResult<TravelStatus>, StoreError> {
        if quantity_millitons == 0 || quantity_millitons % MILLITONS_PER_TON != 0 {
            return Ok(RuleResult::Rejected(
                "frontier fuel must be collected in a positive whole-ton quantity".into(),
            ));
        }
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            arrived_second,
        } = ship.location
        else {
            return Ok(RuleResult::Rejected(
                "a frontier fueling expedition can only begin while docked".into(),
            ));
        };
        if ship.activity.is_some() {
            return Ok(RuleResult::Rejected(
                "the ship already has active work".into(),
            ));
        }
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        if !spec.has_fuel_scoop {
            return Ok(RuleResult::Rejected(
                "the ship has no fuel-scooping equipment".into(),
            ));
        }
        let refine_collected =
            requested_refining.unwrap_or(spec.fuel_processing_millitons_per_day != 0);
        if refine_collected && spec.fuel_processing_millitons_per_day == 0 {
            return Ok(RuleResult::Rejected(
                "the ship has no operational fuel processor".into(),
            ));
        }
        if ship
            .current_fuel_millitons
            .checked_add(quantity_millitons)
            .is_none_or(|fuel| fuel > effective_fuel_capacity(&ship, &spec))
        {
            return Ok(RuleResult::Rejected(
                "the requested fuel exceeds tank capacity".into(),
            ));
        }
        let system = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship system is missing"))?;
        let celestial = derive_celestial_system(&system)?;
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let berth_fee = crate::ship_condition::berth_fee_credits(arrived_second, current);
        if !self.charge_operating_account_in(txn, &mut player, ship.ship_id, berth_fee)? {
            return Ok(RuleResult::Rejected(format!(
                "departure requires Cr{berth_fee} berth; the operating account is short"
            )));
        }
        let days = current as f64 / crate::simulation::SECONDS_PER_DAY as f64;
        let source = if gas_giant {
            selected_body_id.map_or_else(
                || nearest_gas_giant_fuel_source(&celestial, days, f64::from(spec.thrust_g)),
                |body_id| {
                    gas_giant_fuel_source(&celestial, days, f64::from(spec.thrust_g), body_id)
                },
            )
        } else {
            selected_body_id.map_or_else(
                || nearest_wilderness_water_source(&celestial, days, f64::from(spec.thrust_g)),
                |body_id| {
                    wilderness_water_source(&celestial, days, f64::from(spec.thrust_g), body_id)
                },
            )
        };
        let Some(source) = source else {
            return Ok(RuleResult::Rejected(if gas_giant {
                if selected_body_id.is_some() {
                    "the plotted body is not a usable gas-giant fuel source".into()
                } else {
                    "no mapped gas giant is available in this system".into()
                }
            } else {
                if selected_body_id.is_some() {
                    "the plotted body is not a usable uninhabited water or ice source".into()
                } else {
                    "no mapped uninhabited water or ice source is available in this system".into()
                }
            }));
        };
        let travel_seconds =
            (source.round_trip_days * crate::simulation::SECONDS_PER_DAY as f64).ceil() as u64;
        let collection_seconds = if gas_giant {
            mean_skimming_seconds(quantity_millitons)
        } else {
            0
        };
        let activity_id = crate::ship_condition::mix64(
            ship.ship_id
                ^ current
                ^ if gas_giant {
                    0x0047_4153_534b_494d
                } else {
                    0x5741_5445_5249_4345
                },
        );
        let (processing_effect, processing_seconds, processing_damages_jump_drive) =
            if refine_collected {
                self.resolve_fuel_processing_in(
                    txn,
                    identity,
                    ship.ship_id,
                    activity_id,
                    quantity_millitons,
                    spec.fuel_processing_millitons_per_day,
                )?
            } else {
                (0, 0, false)
            };
        let service_seconds = collection_seconds.max(processing_seconds);
        for subsystem in &mut ship.subsystems {
            if matches!(
                subsystem.kind,
                ShipSubsystemKind::ManeuverDrive | ShipSubsystemKind::PowerPlant
            ) {
                subsystem.operating_seconds =
                    subsystem.operating_seconds.saturating_add(travel_seconds);
            }
            if subsystem.kind == ShipSubsystemKind::FuelSystem {
                subsystem.operating_seconds = subsystem
                    .operating_seconds
                    .saturating_add(collection_seconds.max(processing_seconds));
            }
        }
        let outbound_seconds = (travel_seconds / 2).max(1);
        let return_seconds = travel_seconds.saturating_sub(outbound_seconds).max(1);
        let outbound_due = current
            .checked_add(outbound_seconds)
            .ok_or(StoreError::Corrupt("frontier outbound time overflow"))?;
        let service_due = outbound_due
            .checked_add(service_seconds)
            .ok_or(StoreError::Corrupt("frontier service time overflow"))?;
        let due = service_due
            .checked_add(return_seconds)
            .ok_or(StoreError::Corrupt("frontier return time overflow"))?;
        let plan_id = crate::ship_condition::mix64(ship.ship_id ^ current ^ activity_id);
        ship.activity = Some(ShipActivityRecord {
            activity_id,
            kind: if gas_giant {
                ShipActivityKind::GasGiantSkim {
                    quantity_millitons,
                    refine_collected,
                    processing_effect,
                    processing_damages_jump_drive,
                }
            } else {
                ShipActivityKind::WildernessWater {
                    quantity_millitons,
                    refine_collected,
                    processing_effect,
                    processing_damages_jump_drive,
                }
            },
            started_second: current,
            due_second: due,
            cost_credits: 0,
            site: ShipActivitySite::Frontier {
                system_id: ship.system_id,
                source_body_id: source.body_local_id,
                return_world_id: world_id,
                return_facility_id: facility_id,
            },
        });
        ship.revision = ship.revision.saturating_add(1);
        ship.location = ShipLocationRecord::InFlight(FlightLegRecord {
            plan_id,
            plan_revision: 1,
            leg_index: 0,
            origin: ShipLocusRecord::Port {
                system_id: ship.system_id,
                world_id,
                facility_id,
            },
            destination: ShipLocusRecord::Body {
                system_id: ship.system_id,
                body_id: source.body_local_id,
            },
            started_second: current,
            due_second: outbound_due,
            purpose: FlightLegPurpose::ReachFrontierFuel {
                activity_id,
                service_due_second: service_due,
            },
        });
        self.trigger_interception_watches_at_locus_in(
            txn,
            &mut ship,
            ShipLocusRecord::Port {
                system_id: system.id,
                world_id,
                facility_id,
            },
            true,
        )?;
        self.schedule_player_travel_in(txn, ship.ship_id, outbound_due)?;
        self.schedule_contact_check_in(txn, ship.ship_id, current.saturating_add(1))?;
        self.schedule_contact_check_in(txn, ship.ship_id, outbound_due.saturating_add(1))?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        Ok(RuleResult::Applied(self.travel_status_in(txn, identity)?))
    }

    fn begin_fuel_processing_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        quantity_millitons: u64,
    ) -> Result<RuleResult<ShipStatusSnapshot>, StoreError> {
        if quantity_millitons == 0 || quantity_millitons % MILLITONS_PER_TON != 0 {
            return Ok(RuleResult::Rejected(
                "fuel processing requires a positive whole-ton quantity".into(),
            ));
        }
        let (_, mut ship) = self.player_and_ship_in(txn, identity)?;
        if ship.activity.is_some() || matches!(ship.location, ShipLocationRecord::InFlight(_)) {
            return Ok(RuleResult::Rejected(
                "fuel can only be processed while safely docked or holding".into(),
            ));
        }
        if quantity_millitons > ship.unrefined_fuel_millitons {
            return Ok(RuleResult::Rejected(
                "the selected quantity exceeds the unrefined fuel aboard".into(),
            ));
        }
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        if spec.fuel_processing_millitons_per_day == 0 {
            return Ok(RuleResult::Rejected(
                "the ship has no operational fuel processor".into(),
            ));
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let activity_id = crate::ship_condition::mix64(
            ship.ship_id ^ current ^ quantity_millitons ^ 0x4655_454c_5245_4649,
        );
        let (processing_effect, processing_seconds, processing_damages_jump_drive) = self
            .resolve_fuel_processing_in(
                txn,
                identity,
                ship.ship_id,
                activity_id,
                quantity_millitons,
                spec.fuel_processing_millitons_per_day,
            )?;
        if !matches!(ship.location, ShipLocationRecord::Docked { .. }) {
            let worst_case_processing_seconds = milliton_service_seconds(
                quantity_millitons,
                spec.fuel_processing_millitons_per_day,
            )
            .saturating_mul(2);
            let reserve = crate::mining::power_fuel_for_duration(
                spec.power_fuel_millitons,
                spec.power_plant_endurance_seconds,
                worst_case_processing_seconds,
            );
            if ship
                .current_fuel_millitons
                .saturating_sub(quantity_millitons)
                < reserve
            {
                return Ok(RuleResult::Rejected(format!(
                    "processing away from port needs {:.1} tons of fuel outside the selected batch for power-plant reserve",
                    reserve as f64 / 1_000.0
                )));
            }
        }
        let site = match ship.location {
            ShipLocationRecord::Docked {
                world_id,
                facility_id,
                ..
            } => ShipActivitySite::Dockyard {
                system_id: ship.system_id,
                world_id,
                facility_id,
            },
            ShipLocationRecord::Holding { .. } => ShipActivitySite::Field {
                system_id: ship.system_id,
            },
            ShipLocationRecord::InFlight(_) => unreachable!(),
        };
        let due = current
            .checked_add(processing_seconds)
            .ok_or(StoreError::Corrupt("fuel-processing due time overflow"))?;
        ship.activity = Some(ShipActivityRecord {
            activity_id,
            kind: ShipActivityKind::FuelProcessing {
                quantity_millitons,
                processing_effect,
                processing_damages_jump_drive,
            },
            started_second: current,
            due_second: due,
            cost_credits: 0,
            site,
        });
        if let Some(subsystem) = ship
            .subsystems
            .iter_mut()
            .find(|subsystem| subsystem.kind == ShipSubsystemKind::FuelSystem)
        {
            subsystem.operating_seconds = subsystem
                .operating_seconds
                .saturating_add(processing_seconds);
        }
        ship.revision = ship.revision.saturating_add(1);
        self.schedule_ship_activity_in(txn, ship.ship_id, due)?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        Ok(RuleResult::Applied(self.ship_status_in(txn, identity)?))
    }

    fn begin_belt_cycle_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        body_id: u32,
    ) -> Result<RuleResult<TravelStatus>, StoreError> {
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            arrived_second,
        } = ship.location
        else {
            return Ok(RuleResult::Rejected(
                "a belt cycle can only begin while docked".into(),
            ));
        };
        if ship.activity.is_some() {
            return Ok(RuleResult::Rejected(
                "the ship already has active work".into(),
            ));
        }
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        if spec.mining_drone_sets == 0 {
            return Ok(RuleResult::Rejected(
                "the ship has no mining-drone set".into(),
            ));
        }
        if !self.ship_has_crew_skill_in(
            txn,
            identity,
            ship.ship_id,
            crate::wire::SkillId::TradeProspector,
        )? {
            return Ok(RuleResult::Rejected(
                "the filed cycle needs a trained Trade (Prospector) watchkeeper".into(),
            ));
        }
        let cargo_used = ship
            .cargo
            .iter()
            .try_fold(0_u64, |sum, lot| sum.checked_add(lot.quantity_millitons))
            .ok_or(StoreError::Corrupt("cargo quantity overflow"))?;
        if cargo_used >= effective_cargo_capacity(&ship, &spec) {
            return Ok(RuleResult::Rejected(
                "the cargo hold has no room for recovered material".into(),
            ));
        }
        let system = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship system is missing"))?;
        let celestial = derive_celestial_system(&system)?;
        if !celestial.bodies.iter().any(|body| {
            body.local_id == body_id && matches!(body.kind, BodyKind::PlanetoidBelt { .. })
        }) {
            return Ok(RuleResult::Rejected(
                "the selected body is not a catalogued planetoid belt".into(),
            ));
        }
        let current = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let days = current as f64 / crate::simulation::SECONDS_PER_DAY as f64;
        let primary_id = celestial
            .bodies
            .iter()
            .find(|body| body.is_primary_world)
            .map(|body| body.local_id)
            .ok_or(StoreError::Corrupt("system has no primary world"))?;
        let primary = body_position_au(&celestial, days, primary_id)
            .ok_or(StoreError::Corrupt("primary world position is missing"))?;
        let target = body_position_au(&celestial, days, body_id)
            .ok_or(StoreError::Corrupt("belt position is missing"))?;
        let distance_au = primary
            .iter()
            .zip(target)
            .map(|(a, b)| (a - b).powi(2))
            .sum::<f64>()
            .sqrt();
        let transit_seconds = (rest_to_rest_travel_days(distance_au, f64::from(spec.thrust_g))
            * crate::simulation::SECONDS_PER_DAY as f64)
            .ceil() as u64;
        let minimum_cycle = transit_seconds
            .saturating_mul(2)
            .saturating_add(crate::mining::WATCH_SECONDS * 2)
            .saturating_add(crate::mining::DAY_SECONDS)
            .saturating_add(crate::mining::SAFE_MARGIN_SECONDS);
        let required_power = crate::mining::power_fuel_for_duration(
            spec.power_fuel_millitons,
            spec.power_plant_endurance_seconds,
            minimum_cycle,
        );
        if ship.current_fuel_millitons < required_power {
            return Ok(RuleResult::Rejected(format!(
                "the belt cycle and one-day safety margin require {:.1} tons of power-plant fuel",
                required_power as f64 / 1_000.0
            )));
        }
        let berth_fee = crate::ship_condition::berth_fee_credits(arrived_second, current);
        if !self.charge_operating_account_in(txn, &mut player, ship.ship_id, berth_fee)? {
            return Ok(RuleResult::Rejected(format!(
                "departure requires Cr{berth_fee} berth; the operating account is short"
            )));
        }
        let known_lode = self
            .resource_lodes
            .iter(txn)?
            .filter_map(|entry| entry.ok())
            .filter_map(|(_, bytes)| decode_resource_lode(bytes).ok())
            .find(|lode| {
                lode.system_id == ship.system_id
                    && lode.body_id == body_id
                    && lode.remaining_raw_millitons != 0
                    && self
                        .resource_observations
                        .get(txn, &resource_observation_key(identity, lode.lode_id))
                        .ok()
                        .flatten()
                        .is_some()
            });
        let lode_id = if let Some(lode) = known_lode {
            lode.lode_id
        } else {
            take_next_id(self.meta, txn, META_NEXT_RESOURCE_LODE_ID)?
        };
        let context = BeltCycleContext {
            lode_id,
            body_id,
            return_world_id: world_id,
            return_facility_id: facility_id,
            transit_seconds: transit_seconds.max(1),
        };
        let due = current
            .checked_add(context.transit_seconds)
            .ok_or(StoreError::Corrupt("belt transit time overflow"))?;
        ship.location = ShipLocationRecord::InFlight(FlightLegRecord {
            plan_id: crate::ship_condition::mix64(ship.ship_id ^ current ^ u64::from(body_id)),
            plan_revision: 1,
            leg_index: 0,
            origin: ShipLocusRecord::Port {
                system_id: ship.system_id,
                world_id,
                facility_id,
            },
            destination: ShipLocusRecord::Body {
                system_id: ship.system_id,
                body_id,
            },
            started_second: current,
            due_second: due,
            purpose: FlightLegPurpose::ReachBelt(context),
        });
        ship.power_fuel_last_settled_second = current;
        ship.power_fuel_burn_remainder = 0;
        for subsystem in &mut ship.subsystems {
            if matches!(
                subsystem.kind,
                ShipSubsystemKind::ManeuverDrive | ShipSubsystemKind::PowerPlant
            ) {
                subsystem.operating_seconds = subsystem
                    .operating_seconds
                    .saturating_add(context.transit_seconds * 2);
            }
        }
        self.schedule_player_travel_in(txn, ship.ship_id, due)?;
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        Ok(RuleResult::Applied(self.travel_status_in(txn, identity)?))
    }

    fn travel_status_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<TravelStatus, StoreError> {
        let (_, ship) = self.player_and_ship_in(txn, identity)?;
        let current_game_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let current = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?;
        if ship.system_id != 0 && current.is_none() {
            return Err(StoreError::Corrupt("ship system is missing"));
        }
        let (
            destination_system_id,
            due_second,
            stage,
            plan_id,
            plan_revision,
            leg_index,
            origin_locus,
            destination_locus,
        ) = match ship.location {
            ShipLocationRecord::Docked {
                world_id,
                facility_id,
                ..
            } => {
                let stage = match ship.activity.as_ref().map(|activity| &activity.kind) {
                    Some(ShipActivityKind::Refit) => TravelStage::Refit,
                    Some(ShipActivityKind::ProperRepair { .. }) => TravelStage::ProperRepair,
                    _ => TravelStage::Docked,
                };
                let locus = FlightLocus::Port {
                    system_id: ship.system_id,
                    world_id,
                    facility_id,
                };
                (
                    ship.system_id,
                    current_game_second,
                    stage,
                    0,
                    0,
                    0,
                    locus,
                    locus,
                )
            }
            ShipLocationRecord::InFlight(leg) => {
                let (destination_system_id, stage) = match leg.purpose {
                    FlightLegPurpose::DepartForJump {
                        jump_destination_system_id,
                    } => (jump_destination_system_id, TravelStage::DepartingForJump),
                    FlightLegPurpose::DepartForCoordinateJump { .. } => {
                        (0, TravelStage::DepartingForJump)
                    }
                    FlightLegPurpose::Jump { .. } => {
                        (leg.destination.system_id(), TravelStage::JumpSpace)
                    }
                    FlightLegPurpose::ApproachPort => (
                        leg.destination.system_id(),
                        TravelStage::ApproachingStarport,
                    ),
                    FlightLegPurpose::ReachFrontierFuel { .. }
                    | FlightLegPurpose::ProcessFrontierFuel { .. }
                    | FlightLegPurpose::ReturnFromFrontierFuel { .. } => {
                        let stage = match ship.activity.as_ref().map(|activity| &activity.kind) {
                            Some(ShipActivityKind::GasGiantSkim { .. }) => {
                                TravelStage::GasGiantSkim
                            }
                            Some(ShipActivityKind::WildernessWater { .. }) => {
                                TravelStage::WildernessWater
                            }
                            Some(ShipActivityKind::FuelProcessing { .. }) => {
                                TravelStage::FuelProcessing
                            }
                            _ => {
                                return Err(StoreError::Corrupt(
                                    "frontier flight has no matching activity",
                                ));
                            }
                        };
                        (leg.destination.system_id(), stage)
                    }
                    FlightLegPurpose::ReachBelt(_) | FlightLegPurpose::ProspectBelt(_) => {
                        (leg.destination.system_id(), TravelStage::BeltProspecting)
                    }
                    FlightLegPurpose::SurveyBelt(_) => {
                        (leg.destination.system_id(), TravelStage::BeltSurvey)
                    }
                    FlightLegPurpose::MineBelt(_) => {
                        (leg.destination.system_id(), TravelStage::BeltMining)
                    }
                    FlightLegPurpose::RefineBelt(_) => {
                        (leg.destination.system_id(), TravelStage::BeltRefining)
                    }
                    FlightLegPurpose::RecoverBelt { .. } => {
                        (leg.destination.system_id(), TravelStage::BeltRecovery)
                    }
                    FlightLegPurpose::ReturnFromBelt(_) => {
                        (leg.destination.system_id(), TravelStage::BeltEgress)
                    }
                };
                (
                    destination_system_id,
                    leg.due_second,
                    stage,
                    leg.plan_id,
                    leg.plan_revision,
                    leg.leg_index,
                    flight_locus_status(leg.origin),
                    flight_locus_status(leg.destination),
                )
            }
            ShipLocationRecord::Holding {
                locus,
                arrived_second,
            } => (
                locus.system_id(),
                arrived_second,
                TravelStage::Holding,
                0,
                0,
                0,
                flight_locus_status(locus),
                flight_locus_status(locus),
            ),
        };
        let stage = if self
            .encounters
            .get(txn, &encode_identity(identity))?
            .map(decode_encounter_record)
            .transpose()?
            .is_some_and(|record| record.snapshot.state != EncounterState::Resolved)
        {
            TravelStage::Encounter
        } else if self
            .checkpoints
            .get(txn, &encode_identity(identity))?
            .is_some()
        {
            TravelStage::Holding
        } else {
            stage
        };
        let destination = self
            .systems
            .get(txn, &destination_system_id)?
            .map(decode_stellar_system)
            .transpose()?;
        if destination_system_id != 0 && destination.is_none() {
            return Err(StoreError::Corrupt("travel destination system is missing"));
        }
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        Ok(TravelStatus {
            ship_id: ship.ship_id,
            ship_name: ship.name,
            current_system_id: current.as_ref().map_or(0, |system| system.id),
            current_system_name: current.map_or_else(|| "Deep space".into(), |system| system.name),
            destination_system_id: destination.as_ref().map_or(0, |system| system.id),
            destination_system_name: destination
                .map_or_else(|| "Plotted coordinates".into(), |system| system.name),
            stage,
            current_game_second,
            due_second,
            current_fuel_millitons: ship.current_fuel_millitons,
            jump_fuel_millitons: spec.jump_fuel_millitons,
            plan_id,
            plan_revision,
            leg_index,
            origin: origin_locus,
            destination: destination_locus,
        })
    }

    fn begin_voyage_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        destination_system_id: u64,
        navigation: crate::wire::JumpNavigationMethod,
    ) -> Result<RuleResult<TravelStatus>, StoreError> {
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        if ship.activity.is_some() {
            return Ok(RuleResult::Rejected(
                "the ship cannot depart while yard work is active".into(),
            ));
        }
        if ship.provisions.person_days_remaining == 0 {
            return Ok(RuleResult::Rejected(
                "the ship cannot depart without life-support stores".into(),
            ));
        }
        for (kind, name) in [
            (ShipSubsystemKind::LifeSupport, "life support"),
            (ShipSubsystemKind::PowerPlant, "power plant"),
            (ShipSubsystemKind::ManeuverDrive, "maneuver drive"),
            (ShipSubsystemKind::JumpDrive, "Jump drive"),
        ] {
            if ship
                .subsystems
                .iter()
                .filter(|subsystem| subsystem.kind == kind)
                .any(|subsystem| {
                    subsystem
                        .sustained_hits
                        .saturating_sub(subsystem.battlefield_repair_hits)
                        >= subsystem.maximum_hits
                })
            {
                return Ok(RuleResult::Rejected(format!(
                    "the ship cannot depart with its {name} destroyed"
                )));
            }
        }
        manifest_ship_quirks(
            &mut ship,
            &[
                ShipQuirkKind::JumpDriveDefect,
                ShipQuirkKind::FullSpeedVibration,
                ShipQuirkKind::TemperatureFault,
                ShipQuirkKind::BridgeChairFault,
                ShipQuirkKind::HullAirLeak,
            ],
        );
        if destination_system_id == ship.system_id {
            return Ok(RuleResult::Rejected(
                "the destination must be a different system".into(),
            ));
        }
        if !player.known_system_ids.contains(&destination_system_id) {
            return Ok(RuleResult::Rejected(
                "the destination is not in the captain's Known Universe".into(),
            ));
        }
        let origin = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt("ship system is missing"))?;
        let Some(destination) = self
            .systems
            .get(txn, &destination_system_id)?
            .map(decode_stellar_system)
            .transpose()?
        else {
            return Ok(RuleResult::Rejected(
                "the destination system is no longer available".into(),
            ));
        };
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let distance = origin
            .position_parsecs
            .iter()
            .zip(destination.position_parsecs)
            .map(|(left, right)| (left - right).powi(2))
            .sum::<f64>()
            .sqrt();
        if navigation == crate::wire::JumpNavigationMethod::CommercialTape {
            let origin_facility = self
                .facilities
                .get(txn, &origin.id)?
                .map(decode_facility)
                .transpose()?
                .ok_or(StoreError::Corrupt(
                    "course-tape origin facility is missing",
                ))?;
            let destination_world = self.primary_world_in(txn, &destination)?;
            if !origin_facility.operational
                || origin_facility.starport as u8 > crate::universe::Starport::D as u8
                || !destination_world.is_inhabited()
            {
                return Ok(RuleResult::Rejected(
                    "commercial course tapes require a Class-D-or-better origin and a populated destination".into(),
                ));
            }
        }
        if distance > f64::from(spec.jump_rating) + 1.0e-9 {
            return Ok(RuleResult::Rejected(format!(
                "{distance:.3} pc exceeds this ship's Jump-{} rating",
                spec.jump_rating
            )));
        }
        let required_fuel = jump_fuel_for_distance(spec.displacement_millitons, distance);
        if ship.current_fuel_millitons < required_fuel {
            return Ok(RuleResult::Rejected(
                "the ship does not have enough fuel for one jump".into(),
            ));
        }
        let game_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            arrived_second,
        } = ship.location
        else {
            return Ok(RuleResult::Rejected(
                "a voyage can only begin while docked".into(),
            ));
        };
        let berth_fee = crate::ship_condition::berth_fee_credits(arrived_second, game_second);
        let tape_cost = if navigation == crate::wire::JumpNavigationMethod::CommercialTape {
            1_000_u64.saturating_mul(u64::from(jump_number_for_distance(distance)))
        } else {
            0
        };
        let departure_cost = berth_fee.saturating_add(tape_cost);
        if let RuleResult::Rejected(message) =
            self.load_declared_carriage_in(txn, identity, destination_system_id, departure_cost)?
        {
            return Ok(RuleResult::Rejected(message));
        }
        (player, ship) = self.player_and_ship_in(txn, identity)?;
        manifest_ship_quirks(
            &mut ship,
            &[
                ShipQuirkKind::JumpDriveDefect,
                ShipQuirkKind::FullSpeedVibration,
                ShipQuirkKind::TemperatureFault,
                ShipQuirkKind::BridgeChairFault,
                ShipQuirkKind::HullAirLeak,
            ],
        );
        if !self.charge_operating_account_in(txn, &mut player, ship.ship_id, departure_cost)? {
            return Ok(RuleResult::Rejected(format!(
                "departure requires Cr{departure_cost} (Cr{berth_fee} berth and Cr{tape_cost} navigation); the operating account is short"
            )));
        }
        let celestial = derive_celestial_system(&origin)?;
        let approach = primary_world_jump_safety(
            &celestial,
            game_second as f64 / crate::simulation::SECONDS_PER_DAY as f64,
            f64::from(spec.thrust_g),
        );
        let travel_seconds =
            (approach.travel_days * crate::simulation::SECONDS_PER_DAY as f64).ceil() as u64;
        let due_second = game_second
            .checked_add(travel_seconds)
            .ok_or(StoreError::Corrupt("travel due time overflow"))?;
        let plan_id = crate::ship_condition::mix64(
            ship.ship_id ^ game_second ^ destination_system_id ^ 0x464c_4947_4854_504c,
        );
        ship.location = ShipLocationRecord::InFlight(FlightLegRecord {
            plan_id,
            plan_revision: 1,
            leg_index: 0,
            origin: ShipLocusRecord::Port {
                system_id: origin.id,
                world_id,
                facility_id,
            },
            destination: ShipLocusRecord::JumpLocus {
                system_id: origin.id,
            },
            started_second: game_second,
            due_second,
            purpose: FlightLegPurpose::DepartForJump {
                jump_destination_system_id: destination_system_id,
            },
        });
        self.trigger_interception_watches_at_locus_in(
            txn,
            &mut ship,
            ShipLocusRecord::Port {
                system_id: origin.id,
                world_id,
                facility_id,
            },
            true,
        )?;
        for subsystem in &mut ship.subsystems {
            if matches!(
                subsystem.kind,
                ShipSubsystemKind::ManeuverDrive | ShipSubsystemKind::PowerPlant
            ) {
                subsystem.operating_seconds =
                    subsystem.operating_seconds.saturating_add(travel_seconds);
            }
        }
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.schedule_player_travel_in(txn, ship.ship_id, due_second)?;
        self.schedule_contact_check_in(txn, ship.ship_id, game_second.saturating_add(1))?;
        self.schedule_contact_check_in(
            txn,
            ship.ship_id,
            due_second
                .saturating_sub(70)
                .max(game_second.saturating_add(2)),
        )?;
        Ok(RuleResult::Applied(self.travel_status_in(txn, identity)?))
    }

    fn begin_coordinate_voyage_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        destination: crate::wire::Coordinate3,
        navigation: crate::wire::JumpNavigationMethod,
    ) -> Result<RuleResult<TravelStatus>, StoreError> {
        if !destination.is_finite() {
            return Ok(RuleResult::Rejected(
                "Jump coordinates must be finite".into(),
            ));
        }
        let (mut player, mut ship) = self.player_and_ship_in(txn, identity)?;
        if ship.activity.is_some() || ship.provisions.person_days_remaining == 0 {
            return Ok(RuleResult::Rejected(
                "the ship is not ready to leave the berth".into(),
            ));
        }
        for (kind, name) in [
            (ShipSubsystemKind::LifeSupport, "life support"),
            (ShipSubsystemKind::PowerPlant, "power plant"),
            (ShipSubsystemKind::ManeuverDrive, "maneuver drive"),
            (ShipSubsystemKind::JumpDrive, "Jump drive"),
        ] {
            if ship
                .subsystems
                .iter()
                .filter(|subsystem| subsystem.kind == kind)
                .any(|subsystem| {
                    subsystem
                        .sustained_hits
                        .saturating_sub(subsystem.battlefield_repair_hits)
                        >= subsystem.maximum_hits
                })
            {
                return Ok(RuleResult::Rejected(format!(
                    "the ship cannot depart with its {name} destroyed"
                )));
            }
        }
        let origin = self
            .systems
            .get(txn, &ship.system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt(
                "coordinate-jump origin system is missing",
            ))?;
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let target = destination.parsecs();
        if navigation == crate::wire::JumpNavigationMethod::CommercialTape {
            return Ok(RuleResult::Rejected(
                "standard commercial course tapes are sold only for populated-world destinations; plot exploratory coordinates aboard".into(),
            ));
        }
        let distance = origin
            .position_parsecs
            .iter()
            .zip(target)
            .map(|(left, right)| (left - right).powi(2))
            .sum::<f64>()
            .sqrt();
        if distance <= 1.0e-9 || distance > f64::from(spec.jump_rating) + 1.0e-9 {
            return Ok(RuleResult::Rejected(format!(
                "{distance:.3} pc is outside this ship's usable Jump-{} range",
                spec.jump_rating
            )));
        }
        let required_fuel = jump_fuel_for_distance(spec.displacement_millitons, distance);
        if ship.current_fuel_millitons < required_fuel {
            return Ok(RuleResult::Rejected(format!(
                "the coordinate Jump requires {:.1} tons of fuel",
                required_fuel as f64 / 1_000.0
            )));
        }
        let game_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            arrived_second,
        } = ship.location
        else {
            return Ok(RuleResult::Rejected(
                "a coordinate Jump can only begin while docked or from a later supported staging checkpoint".into(),
            ));
        };
        let berth_fee = crate::ship_condition::berth_fee_credits(arrived_second, game_second);
        let tape_cost = if navigation == crate::wire::JumpNavigationMethod::CommercialTape {
            1_000_u64.saturating_mul(u64::from(jump_number_for_distance(distance)))
        } else {
            0
        };
        let departure_cost = berth_fee.saturating_add(tape_cost);
        if !self.charge_operating_account_in(txn, &mut player, ship.ship_id, departure_cost)? {
            return Ok(RuleResult::Rejected(format!(
                "departure requires Cr{departure_cost} (Cr{berth_fee} berth and Cr{tape_cost} navigation); the operating account is short"
            )));
        }
        let celestial = derive_celestial_system(&origin)?;
        let approach = primary_world_jump_safety(
            &celestial,
            game_second as f64 / crate::simulation::SECONDS_PER_DAY as f64,
            f64::from(spec.thrust_g),
        );
        let travel_seconds =
            (approach.travel_days * crate::simulation::SECONDS_PER_DAY as f64).ceil() as u64;
        let due_second = game_second
            .checked_add(travel_seconds)
            .ok_or(StoreError::Corrupt(
                "coordinate Jump approach time overflow",
            ))?;
        ship.location = ShipLocationRecord::InFlight(FlightLegRecord {
            plan_id: crate::ship_condition::mix64(
                ship.ship_id ^ game_second ^ destination.coreward_bits ^ destination.spinward_bits,
            ),
            plan_revision: 1,
            leg_index: 0,
            origin: ShipLocusRecord::Port {
                system_id: origin.id,
                world_id,
                facility_id,
            },
            destination: ShipLocusRecord::JumpLocus {
                system_id: origin.id,
            },
            started_second: game_second,
            due_second,
            purpose: FlightLegPurpose::DepartForCoordinateJump { destination },
        });
        self.trigger_interception_watches_at_locus_in(
            txn,
            &mut ship,
            ShipLocusRecord::Port {
                system_id: origin.id,
                world_id,
                facility_id,
            },
            true,
        )?;
        for subsystem in &mut ship.subsystems {
            if matches!(
                subsystem.kind,
                ShipSubsystemKind::ManeuverDrive | ShipSubsystemKind::PowerPlant
            ) {
                subsystem.operating_seconds =
                    subsystem.operating_seconds.saturating_add(travel_seconds);
            }
        }
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.schedule_player_travel_in(txn, ship.ship_id, due_second)?;
        self.schedule_contact_check_in(txn, ship.ship_id, game_second.saturating_add(1))?;
        self.schedule_contact_check_in(
            txn,
            ship.ship_id,
            due_second
                .saturating_sub(70)
                .max(game_second.saturating_add(2)),
        )?;
        Ok(RuleResult::Applied(self.travel_status_in(txn, identity)?))
    }

    fn begin_deep_space_jump_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        destination_system_id: u64,
        navigation: crate::wire::JumpNavigationMethod,
        proceed_on_known_bad_plot: bool,
    ) -> Result<RuleResult<TravelStatus>, StoreError> {
        let (player, mut ship) = self.player_and_ship_in(txn, identity)?;
        let ShipLocationRecord::Holding {
            locus: ShipLocusRecord::DeepSpace { position },
            ..
        } = ship.location
        else {
            return Ok(RuleResult::Rejected(
                "the ship is not holding at a deep-space Jump point".into(),
            ));
        };
        if navigation == crate::wire::JumpNavigationMethod::CommercialTape {
            return Ok(RuleResult::Rejected(
                "a world-to-world commercial course tape cannot be purchased or initialized from deep space; plot this leg aboard".into(),
            ));
        }
        if !player.known_system_ids.contains(&destination_system_id) {
            return Ok(RuleResult::Rejected(
                "the destination is not in the captain's Known Universe".into(),
            ));
        }
        let destination = self
            .systems
            .get(txn, &destination_system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt(
                "deep-space Jump destination is missing",
            ))?;
        let spec = creation::ship_status_spec(ship.catalog_id)
            .ok_or(StoreError::Corrupt("ship catalog status data is missing"))?;
        let origin = position.parsecs();
        let distance = origin
            .iter()
            .zip(destination.position_parsecs)
            .map(|(left, right)| (left - right).powi(2))
            .sum::<f64>()
            .sqrt();
        if distance <= 1.0e-9 || distance > f64::from(spec.jump_rating) + 1.0e-9 {
            return Ok(RuleResult::Rejected(format!(
                "{distance:.3} pc is outside this ship's usable Jump-{} range",
                spec.jump_rating
            )));
        }
        let required_fuel = jump_fuel_for_distance(spec.displacement_millitons, distance);
        if ship.current_fuel_millitons < required_fuel {
            return Ok(RuleResult::Rejected(format!(
                "the plotted Jump requires {:.1} tons of fuel",
                required_fuel as f64 / 1_000.0
            )));
        }
        let jump_destroyed = ship
            .subsystems
            .iter()
            .filter(|subsystem| subsystem.kind == ShipSubsystemKind::JumpDrive)
            .any(|subsystem| {
                subsystem
                    .sustained_hits
                    .saturating_sub(subsystem.battlefield_repair_hits)
                    >= subsystem.maximum_hits
            });
        if jump_destroyed {
            return Ok(RuleResult::Rejected(
                "the ship cannot jump with its Jump drive destroyed".into(),
            ));
        }

        let game_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let unrefined_consumed = consume_ship_fuel(&mut ship, required_fuel);
        let jump_drive_hits = ship
            .subsystems
            .iter()
            .filter(|subsystem| subsystem.kind == ShipSubsystemKind::JumpDrive)
            .map(|subsystem| {
                subsystem
                    .sustained_hits
                    .saturating_sub(subsystem.battlefield_repair_hits)
            })
            .sum::<u16>();
        let plan_id = crate::ship_condition::mix64(
            ship.ship_id ^ game_second ^ destination_system_id ^ 0x4445_4550_4a55_4d50,
        );
        let (navigator, navigator_condition_dm) = self.best_watch_operator_in(
            txn,
            identity,
            ship.ship_id,
            crate::wire::SkillId::Astrogation,
        )?;
        let mut preparation_seconds = 0_u64;
        let mut attempt_second = game_second;
        let known_bad_plot = loop {
            let entropy =
                crate::ship_condition::mix64(plan_id ^ attempt_second ^ 0x4445_4550_504c_4f54);
            let attempt_seconds = u64::from((entropy % 6) as u8 + 1) * 1_000;
            preparation_seconds = preparation_seconds.saturating_add(attempt_seconds);
            let plot = crate::task_resolution::resolve(
                &navigator,
                crate::task_resolution::TaskRequest {
                    characteristic: navigator.characteristics.education,
                    skill: crate::wire::SkillId::Astrogation,
                    difficulty: 8,
                    equipment_dm: 4 - i8::try_from(jump_number_for_distance(distance))
                        .unwrap_or(i8::MAX),
                    condition_dm: navigator_condition_dm,
                    assistance_dm: 0,
                    entropy,
                },
            );
            if plot.success {
                break false;
            }
            if proceed_on_known_bad_plot {
                break true;
            }
            attempt_second = attempt_second.saturating_add(attempt_seconds);
        };
        let (engineer, engineer_condition_dm) = self.best_watch_operator_in(
            txn,
            identity,
            ship.ship_id,
            crate::wire::SkillId::EngineerJump,
        )?;
        let engineering_entropy =
            crate::ship_condition::mix64(plan_id ^ attempt_second ^ 0x4445_4550_454e_4749);
        let engineering = crate::task_resolution::resolve(
            &engineer,
            crate::task_resolution::TaskRequest {
                characteristic: engineer.characteristics.education,
                skill: crate::wire::SkillId::EngineerJump,
                difficulty: 8,
                equipment_dm: 0,
                condition_dm: engineer_condition_dm,
                assistance_dm: 0,
                entropy: engineering_entropy,
            },
        );
        preparation_seconds =
            preparation_seconds.saturating_add(u64::from((engineering_entropy % 6) as u8 + 1) * 10);
        let resolution = crate::jump::resolve(
            crate::ship_condition::mix64(plan_id ^ game_second),
            engineering.effect,
            0,
            jump_drive_hits,
            unrefined_consumed != 0,
            known_bad_plot,
        );
        let due_second = game_second
            .checked_add(preparation_seconds)
            .ok_or(StoreError::Corrupt("deep-space Jump preparation overflow"))?
            .checked_add(resolution.duration_seconds)
            .ok_or(StoreError::Corrupt("deep-space Jump due time overflow"))?;
        let (jump_destination, inaccurate_extra_days, critical_transition) =
            match resolution.quality {
                crate::jump::JumpQuality::Accurate => (
                    ShipLocusRecord::JumpLocus {
                        system_id: destination_system_id,
                    },
                    0,
                    false,
                ),
                crate::jump::JumpQuality::Inaccurate { extra_days } => (
                    ShipLocusRecord::JumpLocus {
                        system_id: destination_system_id,
                    },
                    extra_days,
                    true,
                ),
                crate::jump::JumpQuality::Misjump {
                    distance_parsecs,
                    direction_millionths,
                } => {
                    let mut actual = destination.position_parsecs;
                    for index in 0..3 {
                        actual[index] += f64::from(direction_millionths[index])
                            * f64::from(distance_parsecs)
                            / 1_000_000.0;
                    }
                    (
                        ShipLocusRecord::DeepSpace {
                            position: crate::wire::Coordinate3::from_parsecs(actual),
                        },
                        0,
                        true,
                    )
                }
            };
        self.mark_tasks_in_transit_in(txn, identity, ship.ship_id, destination_system_id)?;
        ship.mail_custody = None;
        ship.location = ShipLocationRecord::InFlight(FlightLegRecord {
            plan_id,
            plan_revision: 1,
            leg_index: 0,
            origin: ShipLocusRecord::DeepSpace { position },
            destination: jump_destination,
            started_second: game_second,
            due_second,
            purpose: FlightLegPurpose::Jump {
                inaccurate_extra_days,
                critical_transition,
            },
        });
        self.ships
            .put(txn, &ship.ship_id, &encode_ship_record(&ship)?)?;
        self.schedule_player_travel_in(txn, ship.ship_id, due_second)?;
        Ok(RuleResult::Applied(self.travel_status_in(txn, identity)?))
    }

    fn load_declared_carriage_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        destination_system_id: u64,
        retained_credits: u64,
    ) -> Result<RuleResult<()>, StoreError> {
        let declaration = self.carriage_in(txn, identity)?;
        if declaration.destination_system_id != destination_system_id {
            return Ok(RuleResult::Applied(()));
        }
        let (mut player, ship) = self.player_and_ship_in(txn, identity)?;
        if !matches!(ship.location, ShipLocationRecord::Docked { .. }) {
            return Ok(RuleResult::Applied(()));
        }
        let offers = self.local_task_offers_in(txn, identity, &ship)?;
        let mut freight = declaration.freight_capacity_millitons;
        let mut high = declaration.high_berths;
        let mut middle = declaration.middle_berths;
        let mut steerage = declaration.steerage_berths;
        let mut low = declaration.low_berths;
        let mut selected = Vec::new();
        let mut broker_fees = 0_u64;
        for offer in offers
            .into_iter()
            .filter(|o| o.destination_system_id == destination_system_id)
        {
            let eligible = match offer.kind {
                crate::wire::TaskKind::Freight if offer.quantity_millitons <= freight => {
                    freight -= offer.quantity_millitons;
                    let tons = offer.quantity_millitons / MILLITONS_PER_TON;
                    broker_fees =
                        broker_fees.saturating_add(tons.saturating_mul(
                            100 + crate::ship_condition::mix64(offer.offer_id) % 201,
                        ));
                    true
                }
                crate::wire::TaskKind::Passenger => match offer.passenger_class {
                    crate::wire::PassengerClass::High if offer.passenger_count <= high => {
                        high -= offer.passenger_count;
                        true
                    }
                    crate::wire::PassengerClass::Middle if offer.passenger_count <= middle => {
                        middle -= offer.passenger_count;
                        true
                    }
                    crate::wire::PassengerClass::Steerage if offer.passenger_count <= steerage => {
                        steerage -= offer.passenger_count;
                        true
                    }
                    crate::wire::PassengerClass::Low if offer.passenger_count <= low => {
                        low -= offer.passenger_count;
                        true
                    }
                    _ => false,
                },
                _ => false,
            };
            if eligible {
                selected.push(offer);
            }
        }
        if player.credits < broker_fees.saturating_add(retained_credits) {
            return Ok(RuleResult::Rejected(format!(
                "ordinary freight brokerage costs Cr{broker_fees}; funds reserved for departure leave the operating account short"
            )));
        }
        for offer in selected {
            match self.accept_task_offer_in(txn, identity, offer.offer_id, offer.revision)? {
                RuleResult::Applied(_) => {}
                RuleResult::Rejected(message) => {
                    return Ok(RuleResult::Rejected(format!(
                        "carriage manifest changed before filing: {message}"
                    )));
                }
            }
        }
        player = self.player_and_ship_in(txn, identity)?.0;
        player.credits -= broker_fees;
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        Ok(RuleResult::Applied(()))
    }

    fn current_crew_service_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        person_id: u64,
    ) -> Result<Option<CrewServiceRecord>, StoreError> {
        let Some(player) = self
            .players
            .get(txn, &encode_identity(identity))?
            .map(decode_player_record)
            .transpose()?
        else {
            return Ok(None);
        };
        let service = self
            .crew_services
            .get(txn, &person_id)?
            .map(decode_crew_service)
            .transpose()?;
        Ok(service
            .filter(|service| service.ship_id == player.ship_id && service.command == *identity))
    }

    fn apply_personnel_action_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        person_id: u64,
        expected_service_revision: u64,
        action: crate::wire::PersonnelActionKind,
        target_ship_id: u64,
        duration_days: u16,
    ) -> Result<RuleResult<crate::wire::CrewManagementSnapshot>, StoreError> {
        let current_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let phase = self.player_phase_in(txn, identity)?;
        let (mut player, commanded_ship) = self.player_and_ship_in(txn, identity)?;
        let Some(mut service) = self
            .crew_services
            .get(txn, &person_id)?
            .map(decode_crew_service)
            .transpose()?
            .filter(|service| service.command == *identity && service_active(service))
        else {
            return Ok(RuleResult::Rejected(
                "that person is not in your ship service".into(),
            ));
        };
        if service.ship_id != commanded_ship.ship_id {
            return Ok(RuleResult::Rejected(
                "personnel orders may only be issued through the active ship's roster".into(),
            ));
        }
        if service.revision != expected_service_revision {
            return Ok(RuleResult::Rejected(
                "the personnel record changed; review the roster and try again".into(),
            ));
        }
        let mut person = self
            .persons
            .get(txn, &person_id)?
            .map(decode_person_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("crew service person is missing"))?;

        let requires_berth = !matches!(action, crate::wire::PersonnelActionKind::FirstAid);
        if requires_berth && phase != PlayerPhase::Docked {
            return Ok(RuleResult::Rejected(
                "that personnel action requires a berth".into(),
            ));
        }
        let commanded_berth = match commanded_ship.location {
            ShipLocationRecord::Docked {
                world_id: _,
                facility_id,
                ..
            } => Some((commanded_ship.system_id, facility_id)),
            _ => None,
        };
        if service.service_kind == CrewServiceKind::OwnerCaptain
            && matches!(
                action,
                crate::wire::PersonnelActionKind::Dismiss
                    | crate::wire::PersonnelActionKind::Transfer
                    | crate::wire::PersonnelActionKind::ShoreLeave
                    | crate::wire::PersonnelActionKind::MedicalCare
            )
        {
            return Ok(RuleResult::Rejected(
                "the commanding captain cannot leave the active command through Crew Management"
                    .into(),
            ));
        }

        match action {
            crate::wire::PersonnelActionKind::Dismiss => {
                if service.shore_facility_id != 0
                    && commanded_berth != Some((service.shore_system_id, service.shore_facility_id))
                {
                    return Ok(RuleResult::Rejected(
                        "dismissal papers must be served where the crewmember is ashore".into(),
                    ));
                }
                if service.service_kind == CrewServiceKind::Institutional {
                    return Ok(RuleResult::Rejected(
                        "institutional personnel must be released by their service authority"
                            .into(),
                    ));
                }
                service.assigned_slot_ids.clear();
                service.availability = CrewAvailability::Detached;
                service.service_end_second = current_second;
                service.available_second = current_second;
            }
            crate::wire::PersonnelActionKind::Transfer => {
                if service.availability != CrewAvailability::Active
                    || service.shore_facility_id != 0
                {
                    return Ok(RuleResult::Rejected(
                        "recall the crewmember aboard before transferring the posting".into(),
                    ));
                }
                if target_ship_id == service.ship_id {
                    return Ok(RuleResult::Rejected(
                        "that person is already posted to the selected ship".into(),
                    ));
                }
                if !player.managed_ship_ids.contains(&target_ship_id) {
                    return Ok(RuleResult::Rejected(
                        "the selected ship is not under your management".into(),
                    ));
                }
                let target = self
                    .ships
                    .get(txn, &target_ship_id)?
                    .map(decode_ship_record)
                    .transpose()?
                    .ok_or(StoreError::Corrupt("managed transfer ship is missing"))?;
                let co_located = matches!(
                    (&commanded_ship.location, &target.location),
                    (
                        ShipLocationRecord::Docked {
                            world_id: source_world,
                            facility_id: source_facility,
                            ..
                        },
                        ShipLocationRecord::Docked {
                            world_id: target_world,
                            facility_id: target_facility,
                            ..
                        }
                    ) if source_world == target_world && source_facility == target_facility
                );
                if service.ship_id != commanded_ship.ship_id || !co_located {
                    return Ok(RuleResult::Rejected(
                        "both the crewmember and receiving ship must share this berth".into(),
                    ));
                }
                service.ship_id = target_ship_id;
                service.assigned_slot_ids.clear();
            }
            crate::wire::PersonnelActionKind::ShoreLeave => {
                if !(1..=30).contains(&duration_days) {
                    return Ok(RuleResult::Rejected(
                        "shore leave must last from one through thirty days".into(),
                    ));
                }
                service.assigned_slot_ids.clear();
                service.availability = CrewAvailability::ShoreLeave;
                let Some((shore_system_id, shore_facility_id)) = commanded_berth else {
                    return Err(StoreError::Corrupt("docked personnel action has no berth"));
                };
                service.shore_system_id = shore_system_id;
                service.shore_facility_id = shore_facility_id;
                service.available_second = current_second.saturating_add(
                    u64::from(duration_days).saturating_mul(crate::simulation::SECONDS_PER_DAY),
                );
            }
            crate::wire::PersonnelActionKind::Recall => {
                if person.pending_treatment_due_second != 0 {
                    return Ok(RuleResult::Rejected(
                        "an active hospital procedure cannot be recalled to duty".into(),
                    ));
                }
                if !matches!(
                    service.availability,
                    CrewAvailability::ShoreLeave
                        | CrewAvailability::MedicalCare
                        | CrewAvailability::AwaitingRecall
                ) {
                    return Ok(RuleResult::Rejected(
                        "that crewmember is not away from duty".into(),
                    ));
                }
                if current_second < service.available_second {
                    service.morale = service.morale.saturating_sub(5);
                }
                if commanded_berth != Some((service.shore_system_id, service.shore_facility_id)) {
                    return Ok(RuleResult::Rejected(
                        "the ship must berth where the crewmember is ashore before recall".into(),
                    ));
                }
                service.availability = CrewAvailability::Active;
                service.available_second = current_second;
                service.shore_system_id = 0;
                service.shore_facility_id = 0;
            }
            crate::wire::PersonnelActionKind::FirstAid => {
                if service.availability != CrewAvailability::Active
                    && commanded_berth != Some((service.shore_system_id, service.shore_facility_id))
                {
                    return Ok(RuleResult::Rejected(
                        "the patient is not physically present for first aid".into(),
                    ));
                }
                if person_injury_points(&person) == 0 || person_dead(&person) {
                    return Ok(RuleResult::Rejected(
                        "first aid requires a living injured patient".into(),
                    ));
                }
                if person.first_aid_applied {
                    return Ok(RuleResult::Rejected(
                        "first aid has already been attempted for these wounds".into(),
                    ));
                }
                if current_second.saturating_sub(person.last_injury_second) > 60 * 60 {
                    return Ok(RuleResult::Rejected(
                        "the one-hour first-aid window has passed".into(),
                    ));
                }
                let Some((medic, medic_condition_dm)) =
                    self.best_available_medic_in(txn, identity, service.ship_id, current_second)?
                else {
                    return Ok(RuleResult::Rejected(
                        "no conscious on-watch crewmember can attempt first aid".into(),
                    ));
                };
                let result = crate::task_resolution::resolve(
                    &medic,
                    crate::task_resolution::TaskRequest {
                        characteristic: medic.characteristics.education,
                        skill: crate::wire::SkillId::Medicine,
                        difficulty: 8,
                        equipment_dm: 0,
                        condition_dm: medic_condition_dm,
                        assistance_dm: 0,
                        entropy: crate::ship_condition::mix64(
                            person_id ^ current_second ^ medic.name.len() as u64,
                        ),
                    },
                );
                let elapsed = current_second.saturating_sub(person.last_injury_second);
                let points = if elapsed <= 5 * 60 {
                    result.effect.max(0).saturating_mul(2)
                } else {
                    result.effect.max(0)
                } as u16;
                let mut physical = person_physical(&person);
                crate::personnel::restore_points(&mut physical, person_maximum(&person), points);
                set_person_physical(&mut person, physical);
                person.first_aid_applied = true;
                person.last_treatment_second = current_second;
                self.persons
                    .put(txn, &person_id, &encode_person_record(&person)?)?;
            }
            crate::wire::PersonnelActionKind::Surgery => {
                if person.pending_treatment_due_second != 0 {
                    return Ok(RuleResult::Rejected(
                        "a hospital procedure is already in progress".into(),
                    ));
                }
                let ShipLocationRecord::Docked { facility_id, .. } = commanded_ship.location else {
                    return Ok(RuleResult::Rejected("surgery requires a berth".into()));
                };
                let facility = self
                    .facilities
                    .get(txn, &facility_id)?
                    .map(decode_facility)
                    .transpose()?
                    .ok_or(StoreError::Corrupt("docked medical facility is missing"))?;
                if !facility.operational || facility.medical_level < 3 {
                    return Ok(RuleResult::Rejected(
                        "this port has no surgical hospital".into(),
                    ));
                }
                let mut physical = person_physical(&person);
                if !physical.seriously_wounded(person_maximum(&person)) || physical.dead() {
                    return Ok(RuleResult::Rejected(
                        "surgery is reserved for a living seriously wounded patient".into(),
                    ));
                }
                let Some((medic, medic_condition_dm)) =
                    self.best_available_medic_in(txn, identity, service.ship_id, current_second)?
                else {
                    return Ok(RuleResult::Rejected(
                        "no qualified medical attendant is available".into(),
                    ));
                };
                let entropy =
                    crate::ship_condition::mix64(person_id ^ current_second ^ 0x5355_5247);
                let result = crate::task_resolution::resolve(
                    &medic,
                    crate::task_resolution::TaskRequest {
                        characteristic: medic.characteristics.education,
                        skill: crate::wire::SkillId::Medicine,
                        difficulty: 8,
                        equipment_dm: 1,
                        condition_dm: medic_condition_dm,
                        assistance_dm: 0,
                        entropy,
                    },
                );
                let treatment_effect = if result.success {
                    crate::personnel::restore_points(
                        &mut physical,
                        person_maximum(&person),
                        result.effect.max(1).saturating_mul(2) as u16,
                    ) as i16
                } else {
                    let before = physical;
                    crate::personnel::apply_damage(
                        &mut physical,
                        person_maximum(&person),
                        result.effect.unsigned_abs(),
                    );
                    -(physical
                        .missing_points(person_maximum(&person))
                        .saturating_sub(before.missing_points(person_maximum(&person)))
                        as i16)
                };
                let cost = u64::from(treatment_effect.max(0) as u16).saturating_mul(5_000);
                if !self.charge_operating_account_in(
                    txn,
                    &mut player,
                    commanded_ship.ship_id,
                    cost,
                )? {
                    return Ok(RuleResult::Rejected(format!(
                        "the hospital requires Cr{cost} for the completed procedure"
                    )));
                }
                service.assigned_slot_ids.clear();
                service.availability = CrewAvailability::MedicalCare;
                service.shore_system_id = commanded_ship.system_id;
                service.shore_facility_id = facility_id;
                service.available_second =
                    current_second.saturating_add(((entropy % 6) + 1).saturating_mul(60 * 60));
                person.pending_treatment_effect = treatment_effect;
                person.pending_treatment_due_second = service.available_second;
                self.players.put(
                    txn,
                    &encode_identity(identity),
                    &encode_player_record(&player),
                )?;
                self.persons
                    .put(txn, &person_id, &encode_person_record(&person)?)?;
                self.schedule_person_treatment_in(txn, person_id, service.available_second)?;
            }
            crate::wire::PersonnelActionKind::MedicalCare => {
                if person.pending_treatment_due_second != 0 {
                    return Ok(RuleResult::Rejected(
                        "complete the active hospital procedure before changing care".into(),
                    ));
                }
                if !(1..=30).contains(&duration_days) {
                    return Ok(RuleResult::Rejected(
                        "medical care must be booked for one through thirty days".into(),
                    ));
                }
                let ShipLocationRecord::Docked { facility_id, .. } = commanded_ship.location else {
                    return Ok(RuleResult::Rejected("medical care requires a berth".into()));
                };
                let facility = self
                    .facilities
                    .get(txn, &facility_id)?
                    .map(decode_facility)
                    .transpose()?
                    .ok_or(StoreError::Corrupt("docked medical facility is missing"))?;
                if !facility.operational || facility.medical_level < 2 {
                    return Ok(RuleResult::Rejected(
                        "this port has no inpatient medical service".into(),
                    ));
                }
                if person_injury_points(&person) == 0 || person_dead(&person) {
                    return Ok(RuleResult::Rejected(
                        "medical care requires a living injured patient".into(),
                    ));
                }
                service.assigned_slot_ids.clear();
                service.availability = CrewAvailability::MedicalCare;
                service.shore_system_id = commanded_ship.system_id;
                service.shore_facility_id = facility_id;
                service.available_second = current_second.saturating_add(
                    u64::from(duration_days).saturating_mul(crate::simulation::SECONDS_PER_DAY),
                );
            }
        }
        service.revision = service.revision.saturating_add(1);
        self.crew_services
            .put(txn, &service.person_id, &encode_crew_service(&service)?)?;
        Ok(RuleResult::Applied(self.crew_management_in(txn, identity)?))
    }

    fn best_available_medic_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
        ship_id: u64,
        current_second: u64,
    ) -> Result<Option<(crate::wire::PersonDraft, i8)>, StoreError> {
        let role_catalog = self.crew_role_catalog_in(txn, identity, ship_id)?;
        let mut candidates = Vec::new();
        for entry in self.crew_services.iter(txn)? {
            let (_, bytes) = entry?;
            let service = decode_crew_service(bytes)?;
            if service.ship_id != ship_id
                || service.command != *identity
                || !service_available_for_duty(&service, current_second)
                || service.assigned_slot_ids.is_empty()
                || !service.assigned_slot_ids.iter().any(|slot_id| {
                    role_catalog.get(slot_id).is_some_and(|role| {
                        crew_role_supports_skill(role, crate::wire::SkillId::Medicine)
                    })
                })
            {
                continue;
            }
            let person = self
                .persons
                .get(txn, &service.person_id)?
                .map(decode_person_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("medical attendant person is missing"))?;
            if person_incapacitated(&person) {
                continue;
            }
            let medicine = person
                .person
                .skills
                .iter()
                .find(|rating| rating.skill == crate::wire::SkillId::Medicine)
                .map(|rating| rating.level)
                .unwrap_or(-3);
            candidates.push((
                medicine,
                person.person.characteristics.education,
                person_condition_dm(&person)
                    .saturating_add(crate::personnel::discretionary_morale_dm(service.morale)),
                service.person_id,
                person.person,
            ));
        }
        candidates.sort_by_key(|(medicine, education, condition_dm, person_id, _)| {
            (
                std::cmp::Reverse(medicine.saturating_add(*condition_dm)),
                std::cmp::Reverse(*education),
                *person_id,
            )
        });
        Ok(candidates
            .into_iter()
            .next()
            .map(|(_, _, condition_dm, _, person)| (person, condition_dm)))
    }

    fn crew_management_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<crate::wire::CrewManagementSnapshot, StoreError> {
        let player = self
            .players
            .get(txn, &encode_identity(identity))?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("existing player record is missing"))?;
        let ship = self
            .ships
            .get(txn, &player.ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("player ship record is missing"))?;
        if ship.command != *identity {
            return Err(StoreError::Corrupt(
                "player does not command the recorded ship",
            ));
        }
        let mut members = Vec::new();
        let mut roles = std::collections::BTreeMap::new();
        let mut designed_roles =
            creation::commanded_crew_roles(ship.catalog_id).unwrap_or_default();
        for entry in self.crew_services.iter(txn)? {
            let (_, encoded) = entry?;
            let service = decode_crew_service(encoded)?;
            if service.ship_id != ship.ship_id || service.command != *identity {
                continue;
            }
            let designed_positions = if service.slot_id == 0 {
                1
            } else if let Some(index) = designed_roles
                .iter()
                .position(|(role, _)| role == &service.role)
            {
                designed_roles
                    .remove(index)
                    .1
                    .max(service.represented_positions)
            } else {
                service.represented_positions
            };
            roles
                .entry(service.slot_id)
                .or_insert(crate::wire::CrewRole {
                    slot_id: service.slot_id,
                    role: service.role.clone(),
                    represented_positions: designed_positions,
                });
            if !service_active(&service) {
                continue;
            }
            let person = self
                .persons
                .get(txn, &service.person_id)?
                .map(decode_person_record)
                .transpose()?
                .ok_or(StoreError::Corrupt("crew service person is missing"))?;
            let physical = person_physical(&person);
            let maximum = person_maximum(&person);
            let injury_points = physical.missing_points(maximum);
            let condition = if physical.dead() {
                crate::wire::PersonCondition::Dead
            } else if physical.unconscious() || person.fatigue_points >= 2 {
                crate::wire::PersonCondition::Incapacitated
            } else if physical.wounded(maximum) {
                crate::wire::PersonCondition::Wounded
            } else if person.fatigue_points != 0 {
                crate::wire::PersonCondition::Fatigued
            } else {
                crate::wire::PersonCondition::Fit
            };
            let shore_location = if service.shore_facility_id == 0 {
                "Aboard ship".into()
            } else {
                self.facilities
                    .get(txn, &service.shore_facility_id)?
                    .map(decode_facility)
                    .transpose()?
                    .map_or_else(
                        || "An unlisted shore establishment".into(),
                        |facility| facility.name,
                    )
            };
            members.push(crate::wire::CrewManagementMember {
                person_id: service.person_id,
                slot_id: service.slot_id,
                role: service.role.clone(),
                represented_positions: service.represented_positions,
                captain: service.slot_id == 0,
                person: person.person.clone(),
                assigned_slot_ids: service.assigned_slot_ids.clone(),
                condition,
                injury_points,
                fatigue_points: person.fatigue_points,
                unfed_days: person.unfed_days,
                available: !person_incapacitated(&person)
                    && service_available_for_duty(
                        &service,
                        get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0),
                    ),
                current_strength: person.current_strength,
                current_dexterity: person.current_dexterity,
                current_endurance: person.current_endurance,
                service_kind: match service.service_kind {
                    CrewServiceKind::OwnerCaptain => crate::wire::CrewServiceKind::OwnerCaptain,
                    CrewServiceKind::Salaried => crate::wire::CrewServiceKind::Salaried,
                    CrewServiceKind::PrizeShare => crate::wire::CrewServiceKind::PrizeShare,
                    CrewServiceKind::Institutional => crate::wire::CrewServiceKind::Institutional,
                },
                monthly_salary_credits: service.monthly_salary_credits,
                arrears_credits: service.arrears_credits,
                prize_share_basis_points: service.prize_share_basis_points,
                morale: service.morale,
                loyalty: service.loyalty,
                risk_tolerance: service.risk_tolerance,
                availability: match service.availability {
                    CrewAvailability::Active => crate::wire::CrewAvailability::Active,
                    CrewAvailability::ShoreLeave => crate::wire::CrewAvailability::ShoreLeave,
                    CrewAvailability::MedicalCare => crate::wire::CrewAvailability::MedicalCare,
                    CrewAvailability::Detached => crate::wire::CrewAvailability::Detached,
                    CrewAvailability::AwaitingRecall => {
                        crate::wire::CrewAvailability::AwaitingRecall
                    }
                },
                available_second: service.available_second,
                service_revision: service.revision,
                shore_location,
            });
        }
        members.sort_by_key(|member| (member.slot_id, member.person_id));
        if !roles
            .values()
            .any(|role| role.role.eq_ignore_ascii_case("pilot"))
        {
            let pilot_slot = roles
                .keys()
                .next_back()
                .copied()
                .unwrap_or(0)
                .checked_add(1)
                .ok_or(StoreError::Corrupt("crew role identifier overflow"))?;
            roles.insert(
                pilot_slot,
                crate::wire::CrewRole {
                    slot_id: pilot_slot,
                    role: "pilot".into(),
                    represented_positions: 1,
                },
            );
        }
        Ok(crate::wire::CrewManagementSnapshot {
            ship_id: ship.ship_id,
            ship_name: ship.name,
            members,
            roles: roles.into_values().collect(),
            established_complement: creation::ship_crew_complement(ship.catalog_id)
                .unwrap_or_default(),
        })
    }

    fn materialize_player_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        proposal: &PlayerCreation,
        path: u8,
    ) -> Result<(), StoreError> {
        let current_game_second = get_meta_u64(self.meta, txn, META_GAME_SECOND)?.unwrap_or(0);
        let home = self
            .bbs_homes
            .get(txn, &identity.bbs_id)?
            .map(decode_bbs_home)
            .transpose()?
            .ok_or(StoreError::Corrupt("configured BBS has no home"))?;
        let offer = creation::offer_summaries(path)
            .into_iter()
            .find(|offer| offer.offer_id == proposal.starting_offer_id)
            .ok_or(StoreError::Corrupt("validated starting offer disappeared"))?;
        let plan = creation::crew_plan(path, proposal.setup_revision, proposal.starting_offer_id)
            .ok_or(StoreError::Corrupt("validated crew plan disappeared"))?;
        let first_person_id = take_id_range(
            self.meta,
            txn,
            META_NEXT_PERSON_ID,
            u64::try_from(proposal.crew.len() + 1)
                .map_err(|_| StoreError::Corrupt("too many initial people"))?,
        )?;
        let ship_id = take_id_range(self.meta, txn, META_NEXT_SHIP_ID, 1)?;
        let mut captain_assignments = vec![0];
        if !plan
            .slots
            .iter()
            .any(|slot| slot.role.eq_ignore_ascii_case("pilot"))
        {
            let pilot_slot = plan
                .slots
                .iter()
                .map(|slot| slot.slot_id)
                .max()
                .unwrap_or(0)
                .checked_add(1)
                .ok_or(StoreError::Corrupt("crew role identifier overflow"))?;
            captain_assignments.push(pilot_slot);
        }
        let captain = PersonRecord {
            person_id: first_person_id,
            origin_bbs_id: identity.bbs_id,
            origin_system_id: home.capital_system_id,
            person: proposal.captain.clone(),
            current_strength: proposal.captain.characteristics.strength,
            current_dexterity: proposal.captain.characteristics.dexterity,
            current_endurance: proposal.captain.characteristics.endurance,
            fatigue_points: 0,
            last_injury_second: 0,
            first_aid_applied: false,
            last_treatment_second: 0,
            pending_treatment_effect: 0,
            pending_treatment_due_second: 0,
            unfed_days: 0,
        };
        self.persons
            .put(txn, &captain.person_id, &encode_person_record(&captain)?)?;
        self.crew_services.put(
            txn,
            &captain.person_id,
            &encode_crew_service(&CrewServiceRecord {
                person_id: captain.person_id,
                ship_id,
                slot_id: 0,
                role: "captain".into(),
                represented_positions: 1,
                assigned_slot_ids: captain_assignments,
                service_kind: CrewServiceKind::OwnerCaptain,
                monthly_salary_credits: 0,
                prize_share_basis_points: 0,
                arrears_credits: 0,
                service_start_second: current_game_second,
                service_end_second: 0,
                morale: 100,
                loyalty: 100,
                risk_tolerance: 100,
                availability: CrewAvailability::Active,
                available_second: current_game_second,
                shore_system_id: 0,
                shore_facility_id: 0,
                revision: 1,
                command: identity.clone(),
            })?,
        )?;
        for (index, crew) in proposal.crew.iter().enumerate() {
            let person_id = first_person_id
                .checked_add(index as u64 + 1)
                .ok_or(StoreError::Corrupt("person identifier overflow"))?;
            let slot = plan
                .slots
                .iter()
                .find(|slot| slot.slot_id == crew.slot_id)
                .ok_or(StoreError::Corrupt("validated crew slot disappeared"))?;
            let mut canonical_person = slot.default_crew.clone();
            canonical_person.name = crew.name.clone();
            canonical_person.training =
                creation::initial_training(&canonical_person.skills, crew.training_skill).ok_or(
                    StoreError::Corrupt("validated crew training target disappeared"),
                )?;
            let person = PersonRecord {
                person_id,
                origin_bbs_id: identity.bbs_id,
                origin_system_id: home.capital_system_id,
                current_strength: canonical_person.characteristics.strength,
                current_dexterity: canonical_person.characteristics.dexterity,
                current_endurance: canonical_person.characteristics.endurance,
                person: canonical_person,
                fatigue_points: 0,
                last_injury_second: 0,
                first_aid_applied: false,
                last_treatment_second: 0,
                pending_treatment_effect: 0,
                pending_treatment_due_second: 0,
                unfed_days: 0,
            };
            self.persons
                .put(txn, &person_id, &encode_person_record(&person)?)?;
            self.crew_services.put(
                txn,
                &person_id,
                &encode_crew_service(&CrewServiceRecord {
                    person_id,
                    ship_id,
                    slot_id: slot.slot_id,
                    role: slot.role.clone(),
                    represented_positions: slot.represented_positions,
                    assigned_slot_ids: vec![slot.slot_id],
                    service_kind: match offer.career {
                        crate::wire::Career::Trader => CrewServiceKind::Salaried,
                        crate::wire::Career::Privateer => CrewServiceKind::PrizeShare,
                        crate::wire::Career::Navy => CrewServiceKind::Institutional,
                    },
                    monthly_salary_credits: u64::from(slot.represented_positions)
                        .saturating_mul(1_000),
                    prize_share_basis_points: if offer.career == crate::wire::Career::Privateer {
                        500
                    } else {
                        0
                    },
                    arrears_credits: 0,
                    service_start_second: current_game_second,
                    service_end_second: 0,
                    morale: if offer.career == crate::wire::Career::Privateer {
                        75
                    } else {
                        70
                    },
                    loyalty: if offer.career == crate::wire::Career::Navy {
                        80
                    } else if offer.career == crate::wire::Career::Privateer {
                        65
                    } else {
                        60
                    },
                    risk_tolerance: if offer.career == crate::wire::Career::Trader {
                        40
                    } else {
                        70
                    },
                    availability: CrewAvailability::Active,
                    available_second: current_game_second,
                    shore_system_id: 0,
                    shore_facility_id: 0,
                    revision: 1,
                    command: identity.clone(),
                })?,
            )?;
        }
        let ship_spec = creation::ship_status_spec(offer.ship_catalog_id)
            .ok_or(StoreError::Corrupt("starting ship status data is missing"))?;
        let home_member_positions = home
            .cluster_system_ids
            .iter()
            .map(|system_id| {
                self.systems
                    .get(txn, system_id)?
                    .map(decode_stellar_system)
                    .transpose()?
                    .map(|system| system.position_parsecs)
                    .ok_or(StoreError::Corrupt("home polity member system is missing"))
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        let frontier_radius_squared =
            crate::coverage::JUMP_ARRIVAL_MAPPING_RADIUS_PARSECS.powi(2) + 1.0e-9;
        let mut known_system_ids = Vec::new();
        for entry in self.systems.iter(txn)? {
            let (_, encoded) = entry?;
            let system = decode_stellar_system(encoded)?;
            let universally_known = self
                .system_publications
                .get(txn, &system.id)?
                .map(decode_system_publication)
                .transpose()?
                .is_some_and(|record| record.state == SystemPublicationState::UniversallyKnown);
            let in_home_frontier = home_member_positions.iter().any(|position| {
                system
                    .position_parsecs
                    .iter()
                    .zip(position)
                    .map(|(left, right)| (left - right).powi(2))
                    .sum::<f64>()
                    <= frontier_radius_squared
            });
            if system.polity_id == home.polity_id || universally_known || in_home_frontier {
                known_system_ids.push(system.id);
            }
        }
        known_system_ids.sort_unstable();
        known_system_ids.dedup();
        let (fuel_capacity_bonus_millitons, cargo_capacity_penalty_millitons) =
            creation::validate_refit_options(
                path,
                proposal.starting_offer_id,
                &proposal.refit_option_ids,
            )
            .map_err(|_| StoreError::Corrupt("validated starting refit disappeared"))?;
        let ship = ShipRecord {
            revision: 1,
            ship_id,
            catalog_id: offer.ship_catalog_id,
            catalog_revision: creation::offer_catalog_revision(path, proposal.starting_offer_id)
                .ok_or(StoreError::Corrupt(
                    "validated ship catalog revision disappeared",
                ))?,
            name: proposal.ship_name.clone(),
            career: offer.career,
            command: identity.clone(),
            commanding_person_id: captain.person_id,
            standing_order: crate::wire::ManagedShipOrderKind::Hold,
            system_id: home.capital_system_id,
            current_fuel_millitons: ship_spec
                .fuel_capacity_millitons
                .saturating_add(fuel_capacity_bonus_millitons),
            unrefined_fuel_millitons: 0,
            fuel_capacity_bonus_millitons,
            cargo_capacity_penalty_millitons,
            power_fuel_last_settled_second: u64::MAX,
            power_fuel_burn_remainder: 0,
            location: ShipLocationRecord::Docked {
                world_id: home.capital_system_id,
                facility_id: home.capital_system_id,
                arrived_second: current_game_second,
            },
            cargo: Vec::new(),
            passengers: Vec::new(),
            ammunition: new_ship_ammunition(offer.ship_catalog_id),
            provisions: new_ship_provisions(&ship_spec, current_game_second),
            subsystems: new_ship_subsystems(&ship_spec, current_game_second)?,
            maintenance: new_ship_maintenance(&ship_spec, current_game_second)?,
            latent_quirks: Vec::new(),
            activity: None,
            mail_custody: None,
            combat_policy: crate::combat::AutomationPolicy::default(),
            recovery_plan: None,
            service_ledger: Vec::new(),
        };
        self.ships.put(txn, &ship_id, &encode_ship_record(&ship)?)?;
        self.schedule_ship_condition_in(txn, ship_id, ship.maintenance.next_accounting_second)?;
        for offset in 0..=proposal.crew.len() {
            let person_id = first_person_id
                .checked_add(offset as u64)
                .ok_or(StoreError::Corrupt("person identifier overflow"))?;
            self.schedule_person_training_in(
                txn,
                person_id,
                current_game_second
                    .checked_add(crate::ship_condition::SECONDS_PER_WEEK)
                    .ok_or(StoreError::Corrupt("training time overflow"))?,
            )?;
        }
        let terms = creation::starting_offer_terms(path, proposal.starting_offer_id)
            .ok_or(StoreError::Corrupt("validated starting terms disappeared"))?;
        let player = PlayerRecord {
            captain_person_id: captain.person_id,
            ship_id,
            managed_ship_ids: vec![ship_id],
            fleet_revision: 1,
            setup_revision: proposal.setup_revision,
            starting_offer_id: proposal.starting_offer_id,
            credits: terms.liquid_reserve_credits,
            debt_credits: terms.principal_credits,
            tax_arrears_credits: 0,
            known_system_ids,
            knowledge_observed_second: current_game_second,
            message_filter_minimums: DEFAULT_MESSAGE_FILTER_MINIMUMS,
        };
        self.players.put(
            txn,
            &encode_identity(identity),
            &encode_player_record(&player),
        )?;
        self.put_career_state_in(
            txn,
            identity,
            &crate::careers::CareerState::for_starting_career(
                offer.career,
                current_game_second,
                crate::simulation::SECONDS_PER_DAY,
            ),
        )?;
        let annual_insurance = offer
            .price_credits
            .saturating_mul(102)
            .div_ceil(10_000)
            .saturating_add(15_000);
        let finance = FinanceRecord {
            title: match terms.title {
                crate::wire::StartingTitleKind::OwnedWithLien => {
                    crate::wire::ShipTitleKind::OwnedWithLien
                }
                crate::wire::StartingTitleKind::SponsorOwned => {
                    crate::wire::ShipTitleKind::SponsorOwned
                }
                crate::wire::StartingTitleKind::InstitutionOwned => {
                    crate::wire::ShipTitleKind::InstitutionOwned
                }
            },
            restricted_credits: terms.restricted_reserve_credits,
            original_hull_price_credits: offer.price_credits,
            principal_credits: player.debt_credits,
            monthly_payment_credits: terms.monthly_payment_credits,
            monthly_insurance_escrow_credits: if offer.career == crate::wire::Career::Navy {
                0
            } else {
                annual_insurance.div_ceil(12)
            },
            next_payment_due_second: current_game_second
                .saturating_add(crate::ship_condition::ACCOUNTING_MONTH_SECONDS),
            paid_through_second: current_game_second,
            in_default: false,
            impound_order_known_locally: false,
            impound_message_id: 0,
            authorized_expense_credits: 0,
            forged_receipt_credits: 0,
            forged_receipt_count: 0,
            forged_receipt_bbs_id: 0,
            forged_receipt_player_id: 0,
        };
        self.finances.put(
            txn,
            &ship_finance_key(ship_id),
            &encode_finance_record(&finance),
        )?;
        for system_id in &player.known_system_ids {
            self.player_system_mappings.put(
                txn,
                &player_system_mapping_key(identity, *system_id),
                &encode_player_system_mapping(&PlayerSystemMappingRecord {
                    state: SystemMappingState::KnownPublic,
                    dispatch_message_id: None,
                    changed_second: current_game_second,
                }),
            )?;
        }
        self.player_arrivals.put(
            txn,
            &encode_identity(identity),
            &encode_player_arrival(&PlayerArrivalRecord {
                system_id: home.capital_system_id,
                arrival_second: current_game_second,
                mailbag_id: None,
                mail_delivered: 0,
                mail_forwarded: 0,
                mail_expired: 0,
                stipend_credits: 0,
                presented: false,
            }),
        )?;
        record_first_system_visit_in(
            self.system_visits,
            txn,
            home.capital_system_id,
            current_game_second,
        )?;
        self.simulation
            .enable_generated_traffic(txn, home.capital_system_id)?;
        Ok(())
    }

    fn creation_origin_in(
        &self,
        txn: &heed::RoTxn<'_>,
        bbs_id: u32,
    ) -> Result<Option<(u8, OriginDossier)>, StoreError> {
        let configuration = self.bbs_configuration_in(txn, bbs_id)?;
        if !configuration.configured {
            return Ok(None);
        }
        let Some(home) = self
            .bbs_homes
            .get(txn, &bbs_id)?
            .map(decode_bbs_home)
            .transpose()?
        else {
            return Ok(None);
        };
        let Some(system) = self
            .systems
            .get(txn, &home.capital_system_id)?
            .map(decode_stellar_system)
            .transpose()?
        else {
            return Ok(None);
        };
        let path = creation::home_path(
            configuration.settings.trade_combat,
            configuration.settings.chaos_order,
        );
        Ok(Some((
            path,
            OriginDossier {
                bbs_name: configuration.settings.bbs_name,
                polity_name: configuration.settings.polity_name,
                home_system_name: system.name,
                home_world_name: system.primary_world_name,
                trade_combat: configuration.settings.trade_combat,
                chaos_order: configuration.settings.chaos_order,
            },
        )))
    }

