    pub fn crew_services(&self, ship_id: u64) -> Result<Vec<CrewServiceRecord>, StoreError> {
        let txn = self.env.read_txn()?;
        self.crew_services
            .iter(&txn)?
            .filter_map(|entry| match entry {
                Ok((_, encoded)) => match decode_crew_service(encoded) {
                    Ok(service) if service.ship_id == ship_id => Some(Ok(service)),
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect()
    }

    fn player_phase_in(
        &self,
        txn: &heed::RoTxn<'_>,
        identity: &PlayerIdentity,
    ) -> Result<PlayerPhase, StoreError> {
        let identity_key = encode_identity(identity);
        let Some(player) = self
            .players
            .get(txn, &identity_key)?
            .map(decode_player_record)
            .transpose()?
        else {
            return Ok(PlayerPhase::NewUser);
        };
        if let Some(plan) = self
            .flight_plans
            .get(txn, &identity_key)?
            .map(decode_flight_plan_snapshot)
            .transpose()?
        {
            if plan.state == FlightPlanState::Terminal {
                return Ok(PlayerPhase::Terminal);
            }
        }
        if let Some(encounter) = self
            .encounters
            .get(txn, &identity_key)?
            .map(decode_encounter_record)
            .transpose()?
        {
            if encounter
                .result
                .as_ref()
                .is_some_and(|result| result.terminal)
            {
                return Ok(PlayerPhase::Terminal);
            }
            if encounter.snapshot.state != EncounterState::Resolved {
                return Ok(PlayerPhase::Encounter);
            }
        }
        let ship = self
            .ships
            .get(txn, &player.ship_id)?
            .map(decode_ship_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("player ship record is missing"))?;
        Ok(match ship.location {
            ShipLocationRecord::Docked { .. } => PlayerPhase::Docked,
            ShipLocationRecord::InFlight(FlightLegRecord {
                purpose: FlightLegPurpose::Jump { .. },
                ..
            }) => PlayerPhase::Jump,
            ShipLocationRecord::InFlight(_) => PlayerPhase::Interplanetary,
            ShipLocationRecord::Holding { .. } => PlayerPhase::Interplanetary,
        })
    }

    pub fn pending_outbox(&self) -> Result<Vec<Delivery>, StoreError> {
        let txn = self.env.read_txn()?;
        self.outbox
            .iter(&txn)?
            .map(|item| {
                let (_, bytes) = item?;
                decode_delivery(bytes)
            })
            .collect()
    }

    pub fn acknowledge_outbox(&self, sequence: u64) -> Result<bool, StoreError> {
        let mut txn = self.env.write_txn()?;
        let removed = self.outbox.delete(&mut txn, &sequence)?;
        txn.commit()?;
        Ok(removed)
    }

    pub fn add_bbs(
        &self,
        command_id: &[u8; COMMAND_ID_BYTES],
        name: &str,
        psk: [u8; 32],
    ) -> Result<BbsCredential, StoreError> {
        let result_key = admin_result_key(command_id);
        let mut txn = self.env.write_txn()?;
        if let Some(previous) = self.results.get(&txn, &result_key)? {
            let result = decode_bbs_credential(previous)?;
            txn.abort();
            return Ok(result);
        }
        if self.meta.get(&txn, META_UNIVERSE_ID)?.is_none() {
            txn.abort();
            return Err(StoreError::UniverseNotInitialized);
        }
        let bbs_id = get_meta_u32(self.meta, &txn, META_NEXT_BBS_ID)?.unwrap_or(1);
        let next_bbs_id = bbs_id
            .checked_add(1)
            .ok_or(StoreError::Corrupt("BBS identifier overflow"))?;
        let sequence = get_meta_u64(self.meta, &txn, META_NEXT_INGRESS)?.unwrap_or(1);
        let next_sequence = sequence
            .checked_add(1)
            .ok_or(StoreError::Corrupt("ingress sequence overflow"))?;
        let credential = BbsCredential {
            bbs_id,
            name: name.to_owned(),
            psk,
            committed_sequence: sequence,
        };
        let encoded = encode_bbs_credential(&credential)?;
        self.bbs.put(&mut txn, &bbs_id, &encoded)?;
        self.results.put(&mut txn, &result_key, &encoded)?;
        self.journal
            .put(&mut txn, &sequence, &encode_bbs_journal(&credential)?)?;
        put_meta_u32(self.meta, &mut txn, META_NEXT_BBS_ID, next_bbs_id)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_INGRESS, next_sequence)?;
        put_meta_u64(self.meta, &mut txn, META_COMMITTED_SEQUENCE, sequence)?;
        txn.commit()?;
        Ok(credential)
    }

    pub fn bbs_credentials(&self) -> Result<Vec<BbsCredential>, StoreError> {
        let txn = self.env.read_txn()?;
        self.bbs
            .iter(&txn)?
            .map(|entry| {
                let (_, encoded) = entry?;
                decode_bbs_credential(encoded)
            })
            .collect()
    }

    /// Test whether the canonical six-parsec arrival footprint around a Jump
    /// target has been resolved. Missing cells are returned as chunk bitmaps
    /// suitable for a materialization plan.
    pub fn mapping_coverage(
        &self,
        target_parsecs: [f64; 3],
    ) -> Result<MappingCoverage, StoreError> {
        let footprint = jump_arrival_footprint_masks(target_parsecs)?;
        let footprint_cells = footprint.values().map(CellBitmap::count_ones).sum::<u64>();
        let txn = self.env.read_txn()?;
        let coverage_revision = get_meta_u64(self.meta, &txn, META_COVERAGE_REVISION)?.unwrap_or(0);
        let mut missing_cells = std::collections::BTreeMap::new();
        for (coordinate, required) in footprint {
            let mut missing = required;
            if let Some(encoded) = self
                .coverage_chunks
                .get(&txn, &coverage_chunk_key(coordinate))?
            {
                missing.subtract(&decode_coverage_chunk(encoded)?.resolved_cells());
            }
            if !missing.is_empty() {
                missing_cells.insert(coordinate, missing);
            }
        }
        txn.commit()?;
        Ok(if missing_cells.is_empty() {
            MappingCoverage::FullyMapped {
                coverage_revision,
                footprint_cells,
            }
        } else {
            MappingCoverage::NeedsMaterialization {
                coverage_revision,
                footprint_cells,
                missing_cells,
            }
        })
    }

    /// Apply resolved-cell masks inside a caller-owned authoritative
    /// transaction. The caller remains responsible for journaling the cause,
    /// generated systems, and any associated Jump completion in that same
    /// transaction.
    fn apply_coverage_bits_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        expected_revision: u64,
        stellar_distribution_version: u16,
        sampler_version: u16,
        resolved: &std::collections::BTreeMap<CoverageChunkCoordinate, CellBitmap>,
    ) -> Result<(u64, u64), StoreError> {
        let current = get_meta_u64(self.meta, txn, META_COVERAGE_REVISION)?.unwrap_or(0);
        if current != expected_revision {
            return Err(StoreError::StaleCoverageRevision {
                expected: expected_revision,
                actual: current,
            });
        }

        let mut added_cells = 0_u64;
        for (coordinate, requested) in resolved {
            if requested.is_empty() {
                continue;
            }
            let key = coverage_chunk_key(*coordinate);
            let mut chunk = self
                .coverage_chunks
                .get(txn, &key)?
                .map(decode_coverage_chunk)
                .transpose()?
                .unwrap_or_default();
            let added =
                chunk.add_resolution(stellar_distribution_version, sampler_version, requested);
            if added > 0 {
                self.coverage_chunks
                    .put(txn, &key, &encode_coverage_chunk(&chunk)?)?;
                added_cells = added_cells
                    .checked_add(added)
                    .ok_or(StoreError::Corrupt("coverage cell count overflow"))?;
            }
        }

        let revision = if added_cells == 0 {
            current
        } else {
            let next = current
                .checked_add(1)
                .ok_or(StoreError::Corrupt("coverage revision overflow"))?;
            put_meta_u64(self.meta, txn, META_COVERAGE_REVISION, next)?;
            next
        };
        Ok((revision, added_cells))
    }

    /// Resolve the canonical six-parsec sensor volume around a Jump breakout.
    ///
    /// Ordinary travel draws entropy while processing its authoritative
    /// transaction. Fresh-universe shell surveys instead pass domain-separated
    /// initialization entropy after the fixed hull is resolved. Generated
    /// component seeds and all resulting systems commit with the coverage bits.
    fn materialize_jump_arrival_volume_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        target_parsecs: [f64; 3],
        current_second: u64,
    ) -> Result<Vec<StellarSystem>, StoreError> {
        self.materialize_jump_arrival_volume_with_seed_in(txn, target_parsecs, current_second, None)
    }

    fn materialize_jump_arrival_volume_with_seed_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        target_parsecs: [f64; 3],
        current_second: u64,
        operation_seed: Option<[u8; 32]>,
    ) -> Result<Vec<StellarSystem>, StoreError> {
        let footprint = jump_arrival_footprint_masks(target_parsecs)?;
        let mut missing = footprint.clone();
        for (coordinate, cells) in &mut missing {
            if let Some(encoded) = self
                .coverage_chunks
                .get(txn, &coverage_chunk_key(*coordinate))?
            {
                cells.subtract(&decode_coverage_chunk(encoded)?.resolved_cells());
            }
        }
        missing.retain(|_, cells| !cells.is_empty());

        if !missing.is_empty() {
            let operation_seed = match operation_seed {
                Some(seed) => seed,
                None => {
                    let mut seed = [0_u8; 32];
                    getrandom::fill(&mut seed)?;
                    seed
                }
            };
            let mut stream = SeedStream::new(operation_seed);
            let mut name_stream =
                naming_stream(operation_seed, b"place-naming/frontier-arrival/v1")?;
            let mut used_system_names = HashSet::new();
            for entry in self.systems.iter(txn)? {
                let (_, encoded) = entry?;
                used_system_names.insert(decode_stellar_system(encoded)?.name.to_ascii_lowercase());
            }

            let target_radius = target_parsecs
                .iter()
                .map(|coordinate| coordinate * coordinate)
                .sum::<f64>()
                .sqrt();
            let upper_density = sol_centered_stellar_density_upper_bound(
                target_radius + crate::coverage::JUMP_ARRIVAL_MAPPING_RADIUS_PARSECS,
            );
            if !upper_density.is_finite() || upper_density <= 0.0 {
                return Err(StoreError::Corrupt(
                    "frontier stellar-density upper bound is invalid",
                ));
            }
            let radius = crate::coverage::JUMP_ARRIVAL_MAPPING_RADIUS_PARSECS;
            let poisson_measure =
                upper_density * (4.0 * std::f64::consts::PI * radius.powi(3) / 3.0);
            let mut poisson_cursor = 0.0;
            let mut next_system_id = get_meta_u64(self.meta, txn, META_NEXT_SYSTEM_ID)?
                .ok_or(StoreError::Corrupt("missing next system identifier"))?;
            let mut added_simulation_systems = Vec::new();

            loop {
                poisson_cursor += -stream_unit_open(&mut stream)?.ln();
                if poisson_cursor > poisson_measure {
                    break;
                }
                let candidate_radius = radius * stream_unit_open(&mut stream)?.cbrt();
                let cosine = 2.0 * stream_unit_open(&mut stream)? - 1.0;
                let azimuth = std::f64::consts::TAU * stream_unit_open(&mut stream)?;
                let sine = (1.0 - cosine * cosine).max(0.0).sqrt();
                let position = [
                    target_parsecs[0] + candidate_radius * sine * azimuth.cos(),
                    target_parsecs[1] + candidate_radius * sine * azimuth.sin(),
                    target_parsecs[2] + candidate_radius * cosine,
                ];
                let (coordinate, bit_index) = point_cell(position)?;
                if !missing
                    .get(&coordinate)
                    .is_some_and(|cells| cells.contains(bit_index))
                {
                    continue;
                }
                if stream_unit_open(&mut stream)?
                    > stellar_component_density_per_cubic_parsec(position) / upper_density
                {
                    continue;
                }

                let naming_profile_id = regional_profile(position);
                let system_name = unique_system_name(
                    &mut name_stream,
                    naming_profile_id,
                    &mut used_system_names,
                )?;
                let primary_world_name = world_name(&mut name_stream, naming_profile_id)?;
                let generation_seed = stream.next_seed()?;
                let world = generate_primary_world(
                    next_system_id,
                    next_system_id,
                    primary_world_name.clone(),
                    generation_seed,
                )?;
                let system = StellarSystem {
                    id: next_system_id,
                    name: system_name,
                    primary_world_name,
                    position_parsecs: position,
                    polity_id: 0,
                    generation_seed,
                    generation_version: INITIAL_GENERATION_VERSION,
                };
                self.systems
                    .put(txn, &system.id, &encode_stellar_system(&system)?)?;
                self.put_primary_facility_in(txn, &system)?;
                added_simulation_systems.push(SimulationSystem {
                    system_id: system.id,
                    name: system.name.clone(),
                    position_parsecs: system.position_parsecs,
                    polity_id: system.polity_id,
                    generation_seed: system.generation_seed,
                    population: world.population,
                    tech_level: world.tech_level,
                    starport: world.starport as u8,
                    generated_traffic_enabled: false,
                    next_system_day: 0,
                    jump_two_neighbors: Vec::new(),
                });
                next_system_id = next_system_id
                    .checked_add(1)
                    .ok_or(StoreError::Corrupt("system identifier overflow"))?;
            }
            put_meta_u64(self.meta, txn, META_NEXT_SYSTEM_ID, next_system_id)?;
            let added_system_ids = added_simulation_systems
                .iter()
                .map(|system| system.system_id)
                .collect::<Vec<_>>();
            self.simulation
                .add_systems(txn, added_simulation_systems, current_second)?;
            self.extend_pending_system_publications_in(txn, &added_system_ids, current_second)?;

            let coverage_revision =
                get_meta_u64(self.meta, txn, META_COVERAGE_REVISION)?.unwrap_or(0);
            self.apply_coverage_bits_in(
                txn,
                coverage_revision,
                STELLAR_DISTRIBUTION_VERSION,
                FRONTIER_ARRIVAL_SAMPLER_VERSION,
                &missing,
            )?;
        }

        let radius_squared = crate::coverage::JUMP_ARRIVAL_MAPPING_RADIUS_PARSECS.powi(2) + 1.0e-9;
        self.systems
            .iter(txn)?
            .filter_map(|entry| match entry {
                Ok((_, encoded)) => match decode_stellar_system(encoded) {
                    Ok(system)
                        if system
                            .position_parsecs
                            .iter()
                            .zip(target_parsecs)
                            .map(|(left, right)| (left - right).powi(2))
                            .sum::<f64>()
                            <= radius_squared =>
                    {
                        Some(Ok(system))
                    }
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect()
    }

    fn survey_jump_arrival_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        target_parsecs: [f64; 3],
        observed_second: u64,
    ) -> Result<Vec<StellarSystem>, StoreError> {
        let surveyed =
            self.materialize_jump_arrival_volume_in(txn, target_parsecs, observed_second)?;
        let identity_key = encode_identity(identity);
        let mut player = self
            .players
            .get(txn, &identity_key)?
            .map(decode_player_record)
            .transpose()?
            .ok_or(StoreError::Corrupt("surveying player record is missing"))?;
        for system in &surveyed {
            if !player.known_system_ids.contains(&system.id) {
                player.known_system_ids.push(system.id);
            }
            let mapping_key = player_system_mapping_key(identity, system.id);
            if self
                .player_system_mappings
                .get(txn, &mapping_key)?
                .is_none()
            {
                self.player_system_mappings.put(
                    txn,
                    &mapping_key,
                    &encode_player_system_mapping(&PlayerSystemMappingRecord {
                        state: SystemMappingState::Unresolved,
                        dispatch_message_id: None,
                        changed_second: observed_second,
                    }),
                )?;
            }
        }
        player.known_system_ids.sort_unstable();
        player.known_system_ids.dedup();
        player.knowledge_observed_second = player.knowledge_observed_second.max(observed_second);
        self.players
            .put(txn, &identity_key, &encode_player_record(&player))?;
        Ok(surveyed)
    }

    fn merge_public_polity_dossier_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        player: &mut PlayerRecord,
        origin_system_id: u64,
        message_id: u64,
        observed_second: u64,
    ) -> Result<(), StoreError> {
        let origin = self
            .systems
            .get(txn, &origin_system_id)?
            .map(decode_stellar_system)
            .transpose()?
            .ok_or(StoreError::Corrupt(
                "public message origin system is missing",
            ))?;
        let disclosed_system_ids = if origin.polity_id == 0 {
            vec![origin.id]
        } else {
            self.systems
                .iter(txn)?
                .filter_map(|entry| match entry {
                    Ok((system_id, encoded)) => match decode_stellar_system(encoded) {
                        Ok(system) if system.polity_id == origin.polity_id => Some(Ok(system_id)),
                        Ok(_) => None,
                        Err(error) => Some(Err(error)),
                    },
                    Err(error) => Some(Err(StoreError::Heed(error))),
                })
                .collect::<Result<Vec<_>, StoreError>>()?
        };
        for system_id in disclosed_system_ids {
            if !player.known_system_ids.contains(&system_id) {
                player.known_system_ids.push(system_id);
            }
            let mapping_key = player_system_mapping_key(identity, system_id);
            if self
                .player_system_mappings
                .get(txn, &mapping_key)?
                .is_none()
            {
                self.player_system_mappings.put(
                    txn,
                    &mapping_key,
                    &encode_player_system_mapping(&PlayerSystemMappingRecord {
                        state: SystemMappingState::KnownPublic,
                        dispatch_message_id: Some(message_id),
                        changed_second: observed_second,
                    }),
                )?;
            }
        }
        Ok(())
    }

    pub fn initialize_universe(
        &self,
        command_id: &[u8; COMMAND_ID_BYTES],
        universe_id: [u8; 16],
        system_seeds: &[[u8; 32]],
        bbs_placement_seeds: &[BbsPlacementSeed],
    ) -> Result<UniverseInitialization, StoreError> {
        if system_seeds.len() != INITIAL_SYSTEMS.len() {
            return Err(StoreError::InvalidUniverseSeedCount {
                expected: INITIAL_SYSTEMS.len(),
                actual: system_seeds.len(),
            });
        }
        let result_key = initialize_universe_result_key(command_id);
        let mut txn = self.env.write_txn()?;
        if let Some(previous) = self.results.get(&txn, &result_key)? {
            let result = decode_universe_initialization(previous)?;
            txn.abort();
            return Ok(result);
        }
        let configured = self
            .bbs_config
            .iter(&txn)?
            .filter_map(|entry| match entry {
                Ok((bbs_id, encoded)) => match decode_bbs_configuration(encoded) {
                    Ok(configuration) if configuration.configured => {
                        Some(Ok((bbs_id, configuration)))
                    }
                    Ok(_) => None,
                    Err(error) => Some(Err(error)),
                },
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        let placement_seeds = bbs_placement_seeds
            .iter()
            .map(|entry| (entry.bbs_id, entry.seed))
            .collect::<std::collections::BTreeMap<_, _>>();
        if placement_seeds.len() != bbs_placement_seeds.len()
            || configured.len() != placement_seeds.len()
            || configured
                .iter()
                .any(|(bbs_id, _)| !placement_seeds.contains_key(bbs_id))
        {
            return Err(StoreError::InvalidBbsPlacementEntropy);
        }

        // Enrollment credentials and sysop-selected BBS settings are control
        // state. Everything below is game state and is replaced atomically.
        self.queue.clear(&mut txn)?;
        self.sessions.clear(&mut txn)?;
        self.players.clear(&mut txn)?;
        self.persons.clear(&mut txn)?;
        self.ships.clear(&mut txn)?;
        self.careers.clear(&mut txn)?;
        self.crew_services.clear(&mut txn)?;
        self.outbox.clear(&mut txn)?;
        self.bbs_homes.clear(&mut txn)?;
        self.polity_policy_directives.clear(&mut txn)?;
        self.system_polity_policies.clear(&mut txn)?;
        self.polities.clear(&mut txn)?;
        self.systems.clear(&mut txn)?;
        self.facilities.clear(&mut txn)?;
        self.coverage_chunks.clear(&mut txn)?;
        self.markets.clear(&mut txn)?;
        self.tasks.clear(&mut txn)?;
        self.work_assignments.clear(&mut txn)?;
        self.work_assignment_events.clear(&mut txn)?;
        self.carriage_declarations.clear(&mut txn)?;
        self.finances.clear(&mut txn)?;
        self.market_observations.clear(&mut txn)?;
        self.market_leads.clear(&mut txn)?;
        self.market_events.clear(&mut txn)?;
        self.private_message_recipients.clear(&mut txn)?;
        self.radio_transmissions.clear(&mut txn)?;
        self.radio_receptions.clear(&mut txn)?;
        self.radio_mutes.clear(&mut txn)?;
        self.radio_cooldowns.clear(&mut txn)?;
        self.insurance_policies.clear(&mut txn)?;
        self.unique_cargo.clear(&mut txn)?;
        self.market_claims.clear(&mut txn)?;
        self.player_events.clear(&mut txn)?;
        self.ship_condition_events.clear(&mut txn)?;
        self.person_training_events.clear(&mut txn)?;
        self.ship_activity_events.clear(&mut txn)?;
        self.player_arrivals.clear(&mut txn)?;
        self.player_message_state.clear(&mut txn)?;
        self.player_feed_cursors.clear(&mut txn)?;
        self.player_system_mappings.clear(&mut txn)?;
        self.system_publications.clear(&mut txn)?;
        self.system_visits.clear(&mut txn)?;
        self.discovery_claims.clear(&mut txn)?;
        self.flight_plans.clear(&mut txn)?;
        self.checkpoints.clear(&mut txn)?;
        self.encounters.clear(&mut txn)?;
        self.encounter_events.clear(&mut txn)?;
        self.shared_combats.clear(&mut txn)?;
        self.ship_combats.clear(&mut txn)?;
        self.shared_combat_events.clear(&mut txn)?;
        self.contact_events.clear(&mut txn)?;
        self.interception_watches.clear(&mut txn)?;
        self.simulation.clear(&mut txn)?;
        put_meta_u64(self.meta, &mut txn, META_COVERAGE_REVISION, 0)?;
        put_meta_u64(
            self.meta,
            &mut txn,
            META_CLOCK_FORMAT_VERSION,
            crate::clock::CLOCK_FORMAT_VERSION,
        )?;
        put_meta_u64(
            self.meta,
            &mut txn,
            META_CLOCK_RATE_GAME_SECONDS,
            crate::clock::GAME_SECONDS_PER_RATE_PERIOD,
        )?;
        put_meta_u64(
            self.meta,
            &mut txn,
            META_CLOCK_RATE_REAL_SECONDS,
            crate::clock::RATE_PERIOD.as_secs(),
        )?;

        // Player command results have an eight-byte compound identity followed
        // by the 16-byte command ID. Preserve administrator and sysop results.
        let player_result_keys = self
            .results
            .iter(&txn)?
            .map(|entry| {
                let (key, _) = entry?;
                Ok(key.to_vec())
            })
            .collect::<Result<Vec<_>, heed::Error>>()?
            .into_iter()
            .filter(|key| key.len() == 8 + COMMAND_ID_BYTES)
            .collect::<Vec<_>>();
        for key in player_result_keys {
            self.results.delete(&mut txn, &key)?;
        }

        let federation = Polity {
            id: FEDERATION_POLITY_ID,
            name: "Federation".into(),
            naming_profile_id: FEDERATION_NAMING_PROFILE_ID,
        };
        self.polities
            .put(&mut txn, &federation.id, &encode_polity(&federation)?)?;
        for (specification, generation_seed) in INITIAL_SYSTEMS.iter().zip(system_seeds) {
            let primary_world_name = if specification.id == SOL_SYSTEM_ID {
                "Earth".into()
            } else {
                let mut naming = naming_stream(
                    *generation_seed,
                    b"place-naming/initial-federation-world/v1",
                )?;
                world_name(&mut naming, FEDERATION_NAMING_PROFILE_ID)?
            };
            let system = StellarSystem {
                id: specification.id,
                name: specification.name.into(),
                primary_world_name,
                position_parsecs: specification.position_parsecs,
                polity_id: FEDERATION_POLITY_ID,
                generation_seed: *generation_seed,
                generation_version: INITIAL_GENERATION_VERSION,
            };
            self.systems
                .put(&mut txn, &system.id, &encode_stellar_system(&system)?)?;
            self.system_publications.put(
                &mut txn,
                &system.id,
                &encode_system_publication(&SystemPublicationRecord {
                    message_id: 0,
                    dispatched_second: 0,
                    completed_second: 0,
                    state: SystemPublicationState::UniversallyKnown,
                }),
            )?;
            record_first_system_visit_in(self.system_visits, &mut txn, system.id, 0)?;
            self.put_primary_facility_in(&mut txn, &system)?;
        }
        put_meta_u64(
            self.meta,
            &mut txn,
            META_NEXT_POLITY_ID,
            FEDERATION_POLITY_ID + 1,
        )?;
        put_meta_u64(
            self.meta,
            &mut txn,
            META_NEXT_SYSTEM_ID,
            INITIAL_SYSTEMS.len() as u64 + 1,
        )?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_PERSON_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_SHIP_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_CARGO_LOT_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_TASK_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_WORK_ASSIGNMENT_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_MARKET_LEAD_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_MARKET_EVENT_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_INSURANCE_CLAIM_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_FLIGHT_PLAN_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_CHECKPOINT_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_ENCOUNTER_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_RADIO_TRANSMISSION_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_RADIO_RECEPTION_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_RESOURCE_LODE_ID, 1)?;
        put_meta_u64(self.meta, &mut txn, META_GAME_SECOND, 0)?;
        put_meta_u64(
            self.meta,
            &mut txn,
            META_SYSTEM_VISITS_BACKFILL_VERSION,
            SYSTEM_VISITS_BACKFILL_VERSION,
        )?;
        let pie = UniqueCargoRecord {
            object_id: 1,
            name: "apple pie (made from scratch)".into(),
            commodity_id: 1,
            mass_millitons: 1,
            price_credits: 1,
            location: UniqueCargoLocation::Port {
                system_id: SOL_SYSTEM_ID,
            },
        };
        self.unique_cargo
            .put(&mut txn, &pie.object_id, &encode_unique_cargo(&pie)?)?;

        // The fixed CNS5 catalog establishes the convex observed volume whose
        // vertices are the starting systems. Coverage cells are atomic, so
        // cells with any positive-volume intersection with that hull are
        // resolved by the fixed-catalog layer rather than rerolled later.
        let initial_coverage = convex_polyhedron_footprint_masks(
            INITIAL_CATALOG_HULL_VERTICES,
            INITIAL_CATALOG_HULL_FACE_NORMALS,
            INITIAL_CATALOG_HULL_EDGES,
        )?;
        let (_, initial_coverage_cells) = self.apply_coverage_bits_in(
            &mut txn,
            0,
            CNS5_COVERAGE_DISTRIBUTION_VERSION,
            CNS5_COVERAGE_SAMPLER_VERSION,
            &initial_coverage,
        )?;
        if initial_coverage_cells == 0 {
            return Err(StoreError::Corrupt("empty initial coverage footprint"));
        }

        // The fixed-catalog hull must win every overlapping coverage cell.
        // Only after that layer is complete do the hardcoded systems survey
        // their six-parsec surroundings, so the frontier sampler can populate
        // only the unresolved shell outside the established CNS5 volume.
        for (initial, generation_seed) in INITIAL_SYSTEMS.iter().zip(system_seeds) {
            let operation_seed =
                derive_seed(*generation_seed, b"frontier/initial-catalog-arrival/v1")?;
            self.materialize_jump_arrival_volume_with_seed_in(
                &mut txn,
                initial.position_parsecs,
                0,
                Some(operation_seed),
            )?;
        }
        let initial_frontier_ids = self
            .systems
            .iter(&txn)?
            .filter_map(|entry| match entry {
                Ok((system_id, _)) if system_id > INITIAL_SYSTEMS.len() as u64 => {
                    Some(Ok(system_id))
                }
                Ok(_) => None,
                Err(error) => Some(Err(StoreError::Heed(error))),
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for system_id in initial_frontier_ids {
            self.system_publications.put(
                &mut txn,
                &system_id,
                &encode_system_publication(&SystemPublicationRecord {
                    message_id: 0,
                    dispatched_second: 0,
                    completed_second: 0,
                    state: SystemPublicationState::UniversallyKnown,
                }),
            )?;
        }
        for (bbs_id, configuration) in &configured {
            let home = self.materialize_bbs_polity_in(
                &mut txn,
                *bbs_id,
                &configuration.settings,
                placement_seeds[bbs_id],
            )?;
            self.initialize_polity_policy_in(&mut txn, &home, configuration, 0)?;
        }

        let initial_facilities = self
            .systems
            .iter(&txn)?
            .map(|entry| {
                let (_, encoded) = entry?;
                new_primary_facility(&decode_stellar_system(encoded)?)
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        for facility in initial_facilities {
            self.facilities.put(
                &mut txn,
                &facility.facility_id,
                &encode_facility(&facility)?,
            )?;
        }

        let simulation_systems = self
            .systems
            .iter(&txn)?
            .map(|entry| {
                let (_, encoded) = entry?;
                let system = decode_stellar_system(encoded)?;
                let world = self.primary_world_in(&txn, &system)?;
                Ok(SimulationSystem {
                    system_id: system.id,
                    name: system.name,
                    position_parsecs: system.position_parsecs,
                    polity_id: system.polity_id,
                    generation_seed: system.generation_seed,
                    population: world.population,
                    tech_level: world.tech_level,
                    starport: world.starport as u8,
                    generated_traffic_enabled: self.system_visits.get(&txn, &system.id)?.is_some(),
                    next_system_day: 0,
                    jump_two_neighbors: Vec::new(),
                })
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        self.simulation.initialize(&mut txn, simulation_systems)?;
        for (bbs_id, configuration) in &configured {
            let home = self
                .bbs_homes
                .get(&txn, bbs_id)?
                .map(decode_bbs_home)
                .transpose()?
                .ok_or(StoreError::Corrupt("initialized BBS home is missing"))?;
            self.dispatch_bbs_founding_announcement_in(&mut txn, &home, &configuration.settings)?;
        }

        let sequence = get_meta_u64(self.meta, &txn, META_NEXT_INGRESS)?.unwrap_or(1);
        let next_sequence = sequence
            .checked_add(1)
            .ok_or(StoreError::Corrupt("ingress sequence overflow"))?;
        let initialization = UniverseInitialization {
            universe_id,
            polity_count: self
                .polities
                .len(&txn)?
                .try_into()
                .map_err(|_| StoreError::Corrupt("too many initial polities"))?,
            system_count: self
                .systems
                .len(&txn)?
                .try_into()
                .map_err(|_| StoreError::Corrupt("too many initial systems"))?,
            world_count: self
                .systems
                .len(&txn)?
                .try_into()
                .map_err(|_| StoreError::Corrupt("too many initial worlds"))?,
            committed_sequence: sequence,
        };
        self.results.put(
            &mut txn,
            &result_key,
            &encode_universe_initialization(&initialization),
        )?;
        self.journal.put(
            &mut txn,
            &sequence,
            &encode_universe_initialization_journal(&initialization),
        )?;
        self.meta.put(&mut txn, META_UNIVERSE_ID, &universe_id)?;
        put_meta_u64(self.meta, &mut txn, META_PENDING_SYSTEM_PUBLICATIONS, 0)?;
        let session_floor = get_meta_u64(self.meta, &txn, META_NEXT_EPOCH)?.unwrap_or(1);
        put_meta_u64(self.meta, &mut txn, META_SESSION_EPOCH_FLOOR, session_floor)?;
        put_meta_u64(self.meta, &mut txn, META_NEXT_INGRESS, next_sequence)?;
        put_meta_u64(self.meta, &mut txn, META_COMMITTED_SEQUENCE, sequence)?;
        txn.commit()?;
        Ok(initialization)
    }

    pub(crate) fn unique_cargo_reset_required(&self) -> Result<bool, StoreError> {
        let txn = self.env.read_txn()?;
        Ok(self
            .unique_cargo
            .get(&txn, &UNIQUE_APPLE_PIE_ID)?
            .map(decode_unique_cargo)
            .transpose()?
            .is_some_and(|record| record.location == UniqueCargoLocation::Destroyed))
    }

    /// Records actual destruction, as distinct from sale, theft, jettison, or
    /// loss in wreckage. The engine observes this committed state and invokes
    /// the normal whole-universe initialization boundary.
    pub(crate) fn record_unique_cargo_destruction(
        &self,
        object_id: u64,
    ) -> Result<bool, StoreError> {
        if object_id != UNIQUE_APPLE_PIE_ID {
            return Ok(false);
        }
        let mut txn = self.env.write_txn()?;
        let Some(mut record) = self
            .unique_cargo
            .get(&txn, &object_id)?
            .map(decode_unique_cargo)
            .transpose()?
        else {
            txn.abort();
            return Ok(false);
        };
        if record.location == UniqueCargoLocation::Destroyed {
            txn.abort();
            return Ok(false);
        }
        record.location = UniqueCargoLocation::Destroyed;
        self.unique_cargo
            .put(&mut txn, &object_id, &encode_unique_cargo(&record)?)?;
        txn.commit()?;
        Ok(true)
    }

    pub fn polities(&self) -> Result<Vec<Polity>, StoreError> {
        let txn = self.env.read_txn()?;
        self.polities
            .iter(&txn)?
            .map(|entry| {
                let (_, encoded) = entry?;
                decode_polity(encoded)
            })
            .collect()
    }

    /// Materialize the deterministic maximum-load settlement fixture.
    ///
    /// `settlement_extent_parsecs` is E, the furthest BBS prime distance.
    /// Ordinary CE population generation applies through 2E. From 2E to 3E,
    /// a linearly increasing fraction of retained stellar components are
    /// conditioned to an otherwise ordinary CE seed with population zero.
    /// The operation resolves the entire 3E sphere and rebuilds the scheduled
    /// simulation atomically, so it is permitted only before any event runs.
    pub fn materialize_settlement_capacity_fixture(
        &self,
        settlement_extent_parsecs: f64,
        operation_seed: [u8; 32],
    ) -> Result<SettlementCapacityMaterialization, StoreError> {
        if !settlement_extent_parsecs.is_finite() || settlement_extent_parsecs <= 0.0 {
            return Err(StoreError::InvalidSettlementExtent);
        }
        let normal_population_radius_parsecs = settlement_extent_parsecs * 2.0;
        let outer_radius_parsecs = settlement_extent_parsecs * 3.0;
        let footprint = settlement_sphere_footprint_masks([0.0; 3], outer_radius_parsecs)?;
        let mut txn = self.env.write_txn()?;
        let report = self.simulation.report(&txn, 0)?;
        if report.system_days_processed != 0
            || report.traffic_ships != 0
            || report.message_count() != 0
        {
            return Err(StoreError::SettlementCapacityAfterSimulation);
        }

        let mut missing = footprint.clone();
        for (coordinate, cells) in &mut missing {
            if let Some(encoded) = self
                .coverage_chunks
                .get(&txn, &coverage_chunk_key(*coordinate))?
            {
                cells.subtract(&decode_coverage_chunk(encoded)?.resolved_cells());
            }
        }
        missing.retain(|_, cells| !cells.is_empty());
        if missing.is_empty() {
            let total_systems = self.systems.len(&txn)?;
            txn.abort();
            return Ok(SettlementCapacityMaterialization {
                settlement_extent_parsecs,
                normal_population_radius_parsecs,
                outer_radius_parsecs,
                resolved_cells_added: 0,
                sampled_candidates: 0,
                stellar_components_added: 0,
                inhabited_components_added: 0,
                falloff_components_added: 0,
                forced_uninhabited_components_added: 0,
                total_systems,
            });
        }

        let upper_density = sol_centered_stellar_density_upper_bound(outer_radius_parsecs);
        if upper_density <= 0.0 || !upper_density.is_finite() {
            return Err(StoreError::InvalidSettlementExtent);
        }
        let sphere_volume = 4.0 * std::f64::consts::PI * outer_radius_parsecs.powi(3) / 3.0;
        let poisson_measure = upper_density * sphere_volume;
        let mut stream = SeedStream::new(operation_seed);
        let mut name_stream =
            naming_stream(operation_seed, b"place-naming/settlement-capacity/v1")?;
        let mut used_system_names = HashSet::new();
        for entry in self.systems.iter(&txn)? {
            let (_, encoded) = entry?;
            used_system_names.insert(decode_stellar_system(encoded)?.name.to_ascii_lowercase());
        }
        let mut poisson_cursor = 0.0;
        let mut sampled_candidates = 0_u64;
        let mut stellar_components_added = 0_u64;
        let mut inhabited_components_added = 0_u64;
        let mut falloff_components_added = 0_u64;
        let mut forced_uninhabited_components_added = 0_u64;
        let mut next_system_id = get_meta_u64(self.meta, &txn, META_NEXT_SYSTEM_ID)?
            .ok_or(StoreError::Corrupt("missing next system identifier"))?;

        loop {
            poisson_cursor += -stream_unit_open(&mut stream)?.ln();
            if poisson_cursor > poisson_measure {
                break;
            }
            sampled_candidates = sampled_candidates
                .checked_add(1)
                .ok_or(StoreError::Corrupt("settlement candidate count overflow"))?;

            let radius = outer_radius_parsecs * stream_unit_open(&mut stream)?.cbrt();
            let cosine = 2.0 * stream_unit_open(&mut stream)? - 1.0;
            let azimuth = std::f64::consts::TAU * stream_unit_open(&mut stream)?;
            let sine = (1.0 - cosine * cosine).max(0.0).sqrt();
            let position = [
                radius * sine * azimuth.cos(),
                radius * sine * azimuth.sin(),
                radius * cosine,
            ];
            let (coordinate, bit_index) = point_cell(position)?;
            if !missing
                .get(&coordinate)
                .is_some_and(|cells| cells.contains(bit_index))
            {
                continue;
            }
            let density = stellar_component_density_per_cubic_parsec(position);
            if stream_unit_open(&mut stream)? > density / upper_density {
                continue;
            }

            let in_falloff = radius > normal_population_radius_parsecs;
            let force_uninhabited = in_falloff
                && stream_unit_open(&mut stream)?
                    < ((radius - normal_population_radius_parsecs) / settlement_extent_parsecs)
                        .clamp(0.0, 1.0);
            let naming_profile_id = regional_profile(position);
            let system_name =
                unique_system_name(&mut name_stream, naming_profile_id, &mut used_system_names)?;
            let world_name = world_name(&mut name_stream, naming_profile_id)?;
            let (generation_seed, world) = if force_uninhabited {
                let mut selected = None;
                for _ in 0..MAX_UNINHABITED_SEED_DRAWS {
                    let seed = stream.next_seed()?;
                    let world = generate_primary_world(
                        next_system_id,
                        next_system_id,
                        world_name.clone(),
                        seed,
                    )?;
                    if !world.is_inhabited() {
                        selected = Some((seed, world));
                        break;
                    }
                }
                selected.ok_or(StoreError::UninhabitedSeedSearchExhausted {
                    attempts: MAX_UNINHABITED_SEED_DRAWS,
                })?
            } else {
                let seed = stream.next_seed()?;
                let world = generate_primary_world(
                    next_system_id,
                    next_system_id,
                    world_name.clone(),
                    seed,
                )?;
                (seed, world)
            };
            let system = StellarSystem {
                id: next_system_id,
                name: system_name,
                primary_world_name: world_name,
                position_parsecs: position,
                polity_id: 0,
                generation_seed,
                generation_version: INITIAL_GENERATION_VERSION,
            };
            self.systems
                .put(&mut txn, &system.id, &encode_stellar_system(&system)?)?;
            stellar_components_added += 1;
            inhabited_components_added += u64::from(world.is_inhabited());
            falloff_components_added += u64::from(in_falloff);
            forced_uninhabited_components_added += u64::from(force_uninhabited);
            next_system_id = next_system_id
                .checked_add(1)
                .ok_or(StoreError::Corrupt("system identifier overflow"))?;
        }
        put_meta_u64(self.meta, &mut txn, META_NEXT_SYSTEM_ID, next_system_id)?;

        let coverage_revision = get_meta_u64(self.meta, &txn, META_COVERAGE_REVISION)?.unwrap_or(0);
        let (_, resolved_cells_added) = self.apply_coverage_bits_in(
            &mut txn,
            coverage_revision,
            STELLAR_DISTRIBUTION_VERSION,
            SETTLEMENT_CAPACITY_SAMPLER_VERSION,
            &footprint,
        )?;

        let simulation_systems = self
            .systems
            .iter(&txn)?
            .map(|entry| {
                let (_, encoded) = entry?;
                let system = decode_stellar_system(encoded)?;
                let world = self.primary_world_in(&txn, &system)?;
                Ok(SimulationSystem {
                    system_id: system.id,
                    name: system.name,
                    position_parsecs: system.position_parsecs,
                    polity_id: system.polity_id,
                    generation_seed: system.generation_seed,
                    population: world.population,
                    tech_level: world.tech_level,
                    starport: world.starport as u8,
                    generated_traffic_enabled: self.system_visits.get(&txn, &system.id)?.is_some(),
                    next_system_day: 0,
                    jump_two_neighbors: Vec::new(),
                })
            })
            .collect::<Result<Vec<_>, StoreError>>()?;
        let total_systems = u64::try_from(simulation_systems.len())
            .map_err(|_| StoreError::Corrupt("too many settlement systems"))?;
        self.simulation.initialize(&mut txn, simulation_systems)?;
        txn.commit()?;
        Ok(SettlementCapacityMaterialization {
            settlement_extent_parsecs,
            normal_population_radius_parsecs,
            outer_radius_parsecs,
            resolved_cells_added,
            sampled_candidates,
            stellar_components_added,
            inhabited_components_added,
            falloff_components_added,
            forced_uninhabited_components_added,
            total_systems,
        })
    }

    pub fn stellar_systems(&self) -> Result<Vec<StellarSystem>, StoreError> {
        let txn = self.env.read_txn()?;
        self.systems
            .iter(&txn)?
            .map(|entry| {
                let (_, encoded) = entry?;
                decode_stellar_system(encoded)
            })
            .collect()
    }

    pub fn celestial_system(&self, system_id: u64) -> Result<Option<CelestialSystem>, StoreError> {
        let txn = self.env.read_txn()?;
        let Some(encoded) = self.systems.get(&txn, &system_id)? else {
            return Ok(None);
        };
        let system = decode_stellar_system(encoded)?;
        drop(txn);
        if system.generation_version != INITIAL_GENERATION_VERSION {
            return Err(StoreError::UnsupportedSystemGeneration {
                system_id,
                actual: system.generation_version,
                expected: INITIAL_GENERATION_VERSION,
            });
        }
        Ok(Some(derive_celestial_system(&system)?))
    }

    pub fn worlds(&self) -> Result<Vec<World>, StoreError> {
        self.stellar_systems()?
            .iter()
            .map(derive_primary_world)
            .collect::<Result<Vec<_>, _>>()
            .map_err(StoreError::from)
    }

    pub fn game_second(&self) -> Result<u64, StoreError> {
        let txn = self.env.read_txn()?;
        Ok(get_meta_u64(self.meta, &txn, META_GAME_SECOND)?.unwrap_or(0))
    }

    pub fn storage_bytes(&self) -> Result<u64, StoreError> {
        Ok(self.env.real_disk_size()?)
    }

