    fn schedule_encounter_turn_in(
        &self,
        txn: &mut heed::RwTxn<'_>,
        identity: &PlayerIdentity,
        encounter_id: u64,
        due_second: u64,
    ) -> Result<(), StoreError> {
        let event_id = self.simulation.take_scheduled_event_id(txn)?;
        let mut value = Vec::with_capacity(17);
        value.push(1);
        value.extend_from_slice(&identity.bbs_id.to_be_bytes());
        value.extend_from_slice(&identity.player_id.to_be_bytes());
        value.extend_from_slice(&encounter_id.to_be_bytes());
        self.encounter_events
            .put(txn, &scheduled_event_key(due_second, event_id), &value)?;
        Ok(())
    }

