    #[test]
    fn coverage_encoding_selects_compact_forms() {
        let layer = |cells| CoverageChunk {
            layers: vec![CoverageLayer {
                stellar_distribution_version: 1,
                sampler_version: 2,
                resolved_cells: cells,
            }],
        };

        let full = layer(CellBitmap::filled());
        let encoded_full = encode_coverage_chunk(&full).unwrap();
        assert_eq!(encoded_full.len(), 8);
        assert_eq!(decode_coverage_chunk(&encoded_full).unwrap(), full);

        let mut sparse = CellBitmap::empty();
        sparse.set(7);
        sparse.set(30_000);
        let sparse = layer(sparse);
        let encoded_sparse = encode_coverage_chunk(&sparse).unwrap();
        assert_eq!(encoded_sparse.len(), 14);
        assert_eq!(decode_coverage_chunk(&encoded_sparse).unwrap(), sparse);
    }

