    #[test]
    fn low_tech_ship_market_is_empty_without_poisoning_the_engine_queue() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        let ship = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap()
            .1;
        let mut txn = store.env.write_txn().unwrap();
        let mut system = store
            .systems
            .get(&txn, &ship.system_id)
            .unwrap()
            .map(decode_stellar_system)
            .transpose()
            .unwrap()
            .unwrap();
        let minimum_ship_tech_level = creation::ship_market_catalog()
            .into_iter()
            .map(|entry| entry.tech_level)
            .min()
            .unwrap();
        system.generation_seed = (0..=u8::MAX)
            .map(|value| [value; 32])
            .find(|seed| {
                let mut candidate = system.clone();
                candidate.generation_seed = *seed;
                derive_primary_world(&candidate)
                    .is_ok_and(|world| world.tech_level < minimum_ship_tech_level)
            })
            .expect("a deterministic low-tech test world seed");
        assert!(derive_primary_world(&system).unwrap().tech_level < minimum_ship_tech_level);
        store
            .systems
            .put(
                &mut txn,
                &system.id,
                &encode_stellar_system(&system).unwrap(),
            )
            .unwrap();
        txn.commit().unwrap();

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 201, Command::GetShipMarket),
            })
            .unwrap();
        drop(store);

        let store = Store::open(dir.path()).unwrap();
        let delivery = store.process_next().unwrap().unwrap();
        let OutcomeKind::ShipMarket(market) = delivery.outcome.kind else {
            panic!("expected an empty ship market");
        };
        assert!(market.offers.is_empty());
        assert!(store.process_next().unwrap().is_none());
    }

    #[test]
    fn commissioned_ship_persists_as_unavailable_until_timed_delivery() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let mut txn = store.env.write_txn().unwrap();
        let (mut player, commanded_ship) = store.player_and_ship_in(&txn, &identity()).unwrap();
        let ShipLocationRecord::Docked { facility_id, .. } = commanded_ship.location else {
            panic!("fixture ship is not docked");
        };
        let mut facility = store
            .facilities
            .get(&txn, &facility_id)
            .unwrap()
            .map(decode_facility)
            .transpose()
            .unwrap()
            .unwrap();
        facility.operational = true;
        facility.repair_shop = true;
        facility.maximum_yard_hull_millitons = 200_000;
        facility.maximum_component_tech_level = 12;
        store
            .facilities
            .put(&mut txn, &facility_id, &encode_facility(&facility).unwrap())
            .unwrap();
        player.credits = 20_000_000;
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity()),
                &encode_player_record(&player),
            )
            .unwrap();

        let market = store.ship_market_in(&txn, &identity()).unwrap();
        let leavitt = market
            .commissionable_designs
            .iter()
            .find(|design| design.catalog_id == 214)
            .unwrap();
        assert_eq!(leavitt.tech_level, 11);
        assert_eq!(leavitt.deposit_credits, 13_527_000);
        assert_eq!(
            leavitt.construction_seconds,
            44 * crate::ship_condition::SECONDS_PER_WEEK
        );
        assert!(matches!(
            store
                .commission_ship_in(&mut txn, &identity(), 214)
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let player = decode_player_record(
            store
                .players
                .get(&txn, &encode_identity(&identity()))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(player.credits, 6_473_000);
        assert_eq!(player.managed_ship_ids.len(), 2);
        let ship_id = *player
            .managed_ship_ids
            .iter()
            .find(|ship_id| **ship_id != commanded_ship.ship_id)
            .unwrap();
        let commissioned =
            decode_ship_record(store.ships.get(&txn, &ship_id).unwrap().unwrap()).unwrap();
        let activity = commissioned.activity.as_ref().unwrap();
        assert!(matches!(activity.kind, ShipActivityKind::Construction));
        assert_eq!(commissioned.current_fuel_millitons, 0);
        let due_second = activity.due_second;
        let finance = decode_finance_record(
            store
                .finances
                .get(&txn, &ship_finance_key(ship_id))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(finance.principal_credits, 54_108_000);
        assert_eq!(finance.paid_through_second, due_second);
        assert_eq!(
            finance.next_payment_due_second,
            due_second + crate::ship_condition::ACCOUNTING_MONTH_SECONDS
        );
        let fleet = store.fleet_snapshot_in(&txn, &identity()).unwrap();
        let summary = fleet
            .ships
            .iter()
            .find(|ship| ship.ship_id == ship_id)
            .unwrap();
        assert_eq!(summary.location, "Under construction");
        assert!(!summary.can_assume_command);
        assert!(matches!(
            store
                .set_active_ship_in(&mut txn, &identity(), fleet.revision, ship_id)
                .unwrap(),
            RuleResult::Rejected(_)
        ));
        txn.commit().unwrap();
        drop(store);

        let store = Store::open(dir.path()).unwrap();
        let mut txn = store.env.write_txn().unwrap();
        let before = decode_ship_record(store.ships.get(&txn, &ship_id).unwrap().unwrap()).unwrap();
        assert!(matches!(
            before.activity.as_ref().map(|activity| &activity.kind),
            Some(ShipActivityKind::Construction)
        ));
        store
            .process_ship_activity_in(&mut txn, due_second, ship_id)
            .unwrap();
        let delivered =
            decode_ship_record(store.ships.get(&txn, &ship_id).unwrap().unwrap()).unwrap();
        assert!(delivered.activity.is_none());
        assert_eq!(delivered.current_fuel_millitons, 132_000);
        let full_jump_fuel = jump_fuel_for_distance(200_000, 3.0);
        assert_eq!(full_jump_fuel, 60_000);
        assert!(delivered.current_fuel_millitons >= full_jump_fuel * 2);
        assert!(delivered.provisions.person_days_remaining > 0);
        assert!(
            store
                .ship_condition_events
                .iter(&txn)
                .unwrap()
                .filter_map(Result::ok)
                .any(|(key, value)| decode_scheduled_object(key, value)
                    .is_ok_and(|(_, _, scheduled_ship_id)| scheduled_ship_id == ship_id))
        );
        let fleet = store.fleet_snapshot_in(&txn, &identity()).unwrap();
        let summary = fleet
            .ships
            .iter()
            .find(|ship| ship.ship_id == ship_id)
            .unwrap();
        assert_eq!(summary.location, "In berth");
        txn.commit().unwrap();
    }

    fn make_fixture_naval_command(store: &Store, restricted_credits: u64) -> ShipRecord {
        let mut txn = store.env.write_txn().unwrap();
        let (mut player, ship) = store.player_and_ship_in(&txn, &identity()).unwrap();
        player.credits = 0;
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity()),
                &encode_player_record(&player),
            )
            .unwrap();
        let key = ship_finance_key(ship.ship_id);
        let mut finance =
            decode_finance_record(store.finances.get(&txn, &key).unwrap().unwrap()).unwrap();
        finance.title = crate::wire::ShipTitleKind::InstitutionOwned;
        finance.restricted_credits = restricted_credits;
        store
            .finances
            .put(&mut txn, &key, &encode_finance_record(&finance))
            .unwrap();
        let mut career = store.career_state_in(&txn, &identity()).unwrap();
        career.mode = crate::careers::CombatCareerMode::Navy;
        career.revision = career.revision.saturating_add(1);
        store
            .put_career_state_in(&mut txn, &identity(), &career)
            .unwrap();
        txn.commit().unwrap();
        ship
    }

    #[test]
    fn naval_service_account_pays_the_initial_berth_charge() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let ship = make_fixture_naval_command(&store, 10_000);
        let current = get_meta_u64(store.meta, &store.env.read_txn().unwrap(), META_GAME_SECOND)
            .unwrap()
            .unwrap_or(0);
        let arrived = match ship.location {
            ShipLocationRecord::Docked { arrived_second, .. } => arrived_second,
            _ => panic!("fixture ship is not docked"),
        };
        let berth_fee = crate::ship_condition::berth_fee_credits(arrived, current);
        assert!(berth_fee > 0);
        let destination = store
            .known_destinations_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap()
            .systems
            .into_iter()
            .find(|candidate| candidate.system_id != ship.system_id && candidate.within_jump_rating)
            .unwrap();

        let mut txn = store.env.write_txn().unwrap();
        assert!(matches!(
            store
                .begin_voyage_in(
                    &mut txn,
                    &identity(),
                    destination.system_id,
                    crate::wire::JumpNavigationMethod::Onboard,
                )
                .unwrap(),
            RuleResult::Applied(_)
        ));
        txn.commit().unwrap();

        let player = store.player_record(&identity()).unwrap().unwrap();
        assert_eq!(player.credits, 0);
        let finance = decode_finance_record(
            store
                .finances
                .get(
                    &store.env.read_txn().unwrap(),
                    &ship_finance_key(ship.ship_id),
                )
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(finance.restricted_credits, 10_000 - berth_fee);
    }

    #[test]
    fn forged_naval_receipts_move_cash_now_and_face_the_next_accounts_audit() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let ship = make_fixture_naval_command(&store, 1_000_000);
        let due = ship.maintenance.next_accounting_second;
        let amount = (1..=1_000_000)
            .find(|amount| forged_receipt_audit_detected(ship.ship_id, due, *amount, 0, 1))
            .unwrap();

        let mut txn = store.env.write_txn().unwrap();
        let RuleResult::Applied(snapshot) = store
            .misappropriate_restricted_credits_in(&mut txn, &identity(), amount)
            .unwrap()
        else {
            panic!("forged receipt was rejected");
        };
        assert_eq!(snapshot.liquid_credits, amount);
        assert_eq!(snapshot.restricted_credits, 1_000_000 - amount);
        assert!(
            store
                .career_state_in(&txn, &identity())
                .unwrap()
                .warrants
                .is_empty()
        );
        txn.commit().unwrap();

        let mut txn = store.env.write_txn().unwrap();
        store
            .process_ship_condition_in(&mut txn, due, ship.ship_id)
            .unwrap();
        let finance = decode_finance_record(
            store
                .finances
                .get(&txn, &ship_finance_key(ship.ship_id))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(finance.forged_receipt_credits, 0);
        assert_eq!(finance.forged_receipt_count, 0);
        let warrant = store
            .career_state_in(&txn, &identity())
            .unwrap()
            .warrants
            .into_iter()
            .find(|warrant| warrant.accusation.contains("misappropriation"))
            .expect("a detected forged receipt should produce a mailed warrant");
        assert_ne!(warrant.message_id, 0);
        txn.commit().unwrap();
    }

    #[test]
    fn forged_receipt_scrutiny_combines_amount_and_expense_share() {
        assert_eq!(forged_receipt_detection_percent(3, 1, 1), 13);
        assert!(
            forged_receipt_detection_percent(1_000_000, 0, 1)
                > forged_receipt_detection_percent(3, 1, 1)
        );
        assert_eq!(forged_receipt_detection_percent(1_000_000, 0, 1), 90);
        assert!(
            forged_receipt_detection_percent(3, 1, 2) > forged_receipt_detection_percent(3, 1, 1)
        );
        assert!(
            forged_receipt_detection_percent(3, 97, 1) < forged_receipt_detection_percent(3, 1, 1)
        );
    }

    fn establish_colocated_player(store: &Store, identity: &PlayerIdentity, template: &ShipRecord) {
        establish_player(store, identity);
        let mut txn = store.env.write_txn().unwrap();
        let player = store
            .players
            .get(&txn, &encode_identity(identity))
            .unwrap()
            .map(decode_player_record)
            .transpose()
            .unwrap()
            .unwrap();
        let mut ship = store
            .ships
            .get(&txn, &player.ship_id)
            .unwrap()
            .map(decode_ship_record)
            .transpose()
            .unwrap()
            .unwrap();
        ship.system_id = template.system_id;
        ship.location = template.location;
        ship.name = format!("Test Ship {}", identity.player_id);
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        txn.commit().unwrap();
    }

    fn clear_test_ship_to_port_locus(
        store: &Store,
        txn: &mut heed::RwTxn<'_>,
        ship_id: u64,
    ) -> ShipRecord {
        let mut ship = store
            .ships
            .get(txn, &ship_id)
            .unwrap()
            .map(decode_ship_record)
            .transpose()
            .unwrap()
            .unwrap();
        if let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            arrived_second,
        } = ship.location
        {
            ship.location = ShipLocationRecord::Holding {
                locus: ShipLocusRecord::Port {
                    system_id: ship.system_id,
                    world_id,
                    facility_id,
                },
                arrived_second,
            };
            store
                .ships
                .put(txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
                .unwrap();
        }
        ship
    }

    #[test]
    fn system_radio_stores_one_body_until_wave_and_receptions_release_it() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let sender = identity();
        let target = PlayerIdentity {
            bbs_id: sender.bbs_id,
            player_id: sender.player_id + 1,
        };
        let template = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &sender)
            .unwrap()
            .1;
        establish_colocated_player(&store, &target, &template);

        let mut txn = store.env.write_txn().unwrap();
        assert!(matches!(
            store
                .transmit_system_radio_in(&mut txn, &sender, "Rendezvous at the gas giant.")
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let inbox = store.system_radio_in(&mut txn, &target).unwrap();
        assert_eq!(inbox.entries.len(), 1);
        let reception_id = inbox.entries[0].reception_id;
        let transmission_id = inbox.entries[0].transmission_id;
        let transmission = store
            .radio_transmissions
            .get(&txn, &transmission_id)
            .unwrap()
            .map(decode_radio_transmission)
            .transpose()
            .unwrap()
            .unwrap();
        assert_eq!(transmission.body, "Rendezvous at the gas giant.");
        assert_eq!(transmission.reference_count, 2);
        let content = match store
            .peek_radio_reception_in(&mut txn, &target, reception_id)
            .unwrap()
        {
            RuleResult::Applied(content) => content,
            RuleResult::Rejected(reason) => panic!("radio reception was rejected: {reason}"),
        };
        assert_eq!(content.reception_id, reception_id);
        assert_eq!(content.transmission_id, transmission_id);
        assert_eq!(content.body, "Rendezvous at the gas giant.");
        assert!(matches!(
            store
                .acknowledge_radio_reception_in(&mut txn, &target, reception_id)
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let transmission = store
            .radio_transmissions
            .get(&txn, &transmission_id)
            .unwrap()
            .map(decode_radio_transmission)
            .transpose()
            .unwrap()
            .unwrap();
        assert_eq!(transmission.reference_count, 1);
        store
            .cleanup_radio_in(&mut txn, transmission.wave_expires_second)
            .unwrap();
        assert!(
            store
                .radio_transmissions
                .get(&txn, &transmission_id)
                .unwrap()
                .is_none()
        );
    }

    #[test]
    fn radio_mutes_only_player_broadcasts_and_structured_hails_target_one_ship() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let sender = identity();
        let target = PlayerIdentity {
            bbs_id: sender.bbs_id,
            player_id: sender.player_id + 1,
        };
        let template = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &sender)
            .unwrap()
            .1;
        establish_colocated_player(&store, &target, &template);

        let mut txn = store.env.write_txn().unwrap();
        assert!(matches!(
            store
                .set_radio_mute_in(&mut txn, &target, &sender, true)
                .unwrap(),
            RuleResult::Applied(_)
        ));
        assert!(matches!(
            store
                .transmit_system_radio_in(&mut txn, &sender, "Ordinary traffic call")
                .unwrap(),
            RuleResult::Applied(_)
        ));
        assert!(
            store
                .system_radio_in(&mut txn, &target)
                .unwrap()
                .entries
                .is_empty()
        );
        assert!(matches!(
            store
                .transmit_system_radio_in(&mut txn, &sender, "Too soon")
                .unwrap(),
            RuleResult::Rejected(_)
        ));

        let target_ship = store.player_and_ship_in(&txn, &target).unwrap().1;
        let contact = EncounterContact {
            contact_id: 77,
            ship_name: "Customs Cutter".into(),
            class_name: "inspection launch".into(),
            transponder: "CUSTOMS-77".into(),
            role: "customs inspection".into(),
            range: "local traffic range".into(),
            confidence_percent: 100,
        };
        store
            .emit_encounter_radio_in(
                &mut txn,
                &target_ship,
                &contact,
                EncounterKind::Inspection,
                9001,
                0,
                true,
                "Customs requests the cargo manifest.",
            )
            .unwrap();
        let target_inbox = store.system_radio_in(&mut txn, &target).unwrap();
        assert_eq!(target_inbox.entries.len(), 1);
        assert_eq!(
            target_inbox.entries[0].kind,
            crate::wire::RadioTransmissionKind::InspectionOrder
        );
        assert!(target_inbox.entries[0].actionable);
        assert_eq!(target_inbox.entries[0].action_reference_id, 9001);
        let overheard = store.system_radio_in(&mut txn, &sender).unwrap();
        assert_eq!(overheard.entries.len(), 1);
        assert!(!overheard.entries[0].actionable);
        assert_eq!(overheard.entries[0].action_reference_id, 9001);
    }

    #[test]
    fn pending_radio_reception_is_cancelled_when_the_ship_enters_jump() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let sender = identity();
        let target = PlayerIdentity {
            bbs_id: sender.bbs_id,
            player_id: sender.player_id + 1,
        };
        let template = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &sender)
            .unwrap()
            .1;
        establish_colocated_player(&store, &target, &template);
        let mut txn = store.env.write_txn().unwrap();
        let (_, mut target_ship) = store.player_and_ship_in(&txn, &target).unwrap();
        let jump_locus = ShipLocusRecord::JumpLocus {
            system_id: target_ship.system_id,
        };
        target_ship.location = ShipLocationRecord::Holding {
            locus: jump_locus,
            arrived_second: 0,
        };
        store
            .ships
            .put(
                &mut txn,
                &target_ship.ship_id,
                &encode_ship_record(&target_ship).unwrap(),
            )
            .unwrap();
        assert!(matches!(
            store
                .transmit_system_radio_in(&mut txn, &sender, "Port departure notice")
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let pending = store
            .radio_receptions
            .prefix_iter(&txn, &target_ship.ship_id.to_be_bytes())
            .unwrap()
            .map(|entry| decode_radio_reception(entry.unwrap().1).unwrap())
            .next()
            .unwrap();
        assert!(pending.received_second > 0);
        let transmission_id = pending.transmission_id;

        target_ship.location = ShipLocationRecord::InFlight(FlightLegRecord {
            plan_id: 1,
            plan_revision: 1,
            leg_index: 0,
            origin: jump_locus,
            destination: jump_locus,
            started_second: 0,
            due_second: crate::simulation::SECONDS_PER_DAY,
            purpose: FlightLegPurpose::Jump {
                inaccurate_extra_days: 0,
                critical_transition: false,
            },
        });
        store
            .reconcile_radio_for_ship_in(&mut txn, &target_ship, 0)
            .unwrap();
        assert!(
            store
                .radio_receptions
                .prefix_iter(&txn, &target_ship.ship_id.to_be_bytes())
                .unwrap()
                .next()
                .is_none()
        );
        let transmission = store
            .radio_transmissions
            .get(&txn, &transmission_id)
            .unwrap()
            .map(decode_radio_transmission)
            .transpose()
            .unwrap()
            .unwrap();
        assert_eq!(transmission.reference_count, 1);
    }

    #[test]
    fn radio_body_peek_is_not_retained_in_journal_results_or_outbox() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let sender = identity();
        let target = PlayerIdentity {
            bbs_id: sender.bbs_id,
            player_id: sender.player_id + 1,
        };
        let template = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &sender)
            .unwrap()
            .1;
        establish_colocated_player(&store, &target, &template);
        let mut txn = store.env.write_txn().unwrap();
        store.outbox.clear(&mut txn).unwrap();
        assert!(matches!(
            store
                .transmit_system_radio_in(&mut txn, &sender, "Transient body")
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let reception_id =
            store.system_radio_in(&mut txn, &target).unwrap().entries[0].reception_id;
        txn.commit().unwrap();

        let (epoch, _, _) = store.issue_session_epoch(&target).unwrap();
        store
            .enqueue(&QueuedCommand {
                identity: target.clone(),
                request: request(epoch, 211, Command::PeekRadioReception { reception_id }),
            })
            .unwrap();
        let delivery = store.process_next().unwrap().unwrap();
        assert!(matches!(
            delivery.outcome.kind,
            OutcomeKind::RadioContent(crate::wire::RadioContent { ref body, .. })
                if body == "Transient body"
        ));
        assert!(store.pending_outbox().unwrap().is_empty());
        let txn = store.env.read_txn().unwrap();
        let result_key = command_result_key(&target, &[211; COMMAND_ID_BYTES]).unwrap();
        assert!(store.results.get(&txn, &result_key).unwrap().is_none());
        let journal = store
            .journal
            .get(&txn, &delivery.outbox_sequence)
            .unwrap()
            .unwrap();
        assert!(
            !journal
                .windows("Transient body".len())
                .any(|window| window == b"Transient body")
        );
    }

    #[test]
    fn retained_vessels_have_independent_title_command_and_physical_stores() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let identity = identity();
        let original = store.player_record(&identity).unwrap().unwrap();
        let original_ship_id = original.ship_id;
        let mut txn = store.env.write_txn().unwrap();
        let mut funded = store
            .players
            .get(&txn, &encode_identity(&identity))
            .unwrap()
            .map(decode_player_record)
            .transpose()
            .unwrap()
            .unwrap();
        funded.credits = u64::MAX / 4;
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity),
                &encode_player_record(&funded),
            )
            .unwrap();
        let market = store.ship_market_in(&txn, &identity).unwrap();
        let offer = market.offers.first().unwrap().clone();
        assert!(matches!(
            store
                .purchase_ship_in(&mut txn, &identity, offer.offer_id, false)
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let purchased = store
            .players
            .get(&txn, &encode_identity(&identity))
            .unwrap()
            .map(decode_player_record)
            .transpose()
            .unwrap()
            .unwrap();
        assert_eq!(purchased.ship_id, original_ship_id);
        assert_eq!(purchased.managed_ship_ids.len(), 2);
        let purchased_ship_id = *purchased
            .managed_ship_ids
            .iter()
            .find(|ship_id| **ship_id != original_ship_id)
            .unwrap();
        assert!(store.ships.get(&txn, &original_ship_id).unwrap().is_some());
        assert!(
            store
                .finances
                .get(&txn, &ship_finance_key(original_ship_id))
                .unwrap()
                .is_some()
        );
        assert!(
            store
                .finances
                .get(&txn, &ship_finance_key(purchased_ship_id))
                .unwrap()
                .is_some()
        );
        let officer = store
            .crew_services
            .iter(&txn)
            .unwrap()
            .filter_map(Result::ok)
            .map(|(_, value)| decode_crew_service(value).unwrap())
            .find(|service| service.person_id != purchased.captain_person_id)
            .unwrap();
        assert!(matches!(
            store
                .assign_ship_captain_in(
                    &mut txn,
                    &identity,
                    purchased.fleet_revision,
                    purchased_ship_id,
                    officer.person_id,
                )
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let mut purchased_ship = store
            .ships
            .get(&txn, &purchased_ship_id)
            .unwrap()
            .map(decode_ship_record)
            .transpose()
            .unwrap()
            .unwrap();
        purchased_ship.current_fuel_millitons = 0;
        store
            .ships
            .put(
                &mut txn,
                &purchased_ship_id,
                &encode_ship_record(&purchased_ship).unwrap(),
            )
            .unwrap();
        let assigned = store
            .players
            .get(&txn, &encode_identity(&identity))
            .unwrap()
            .map(decode_player_record)
            .transpose()
            .unwrap()
            .unwrap();
        assert!(matches!(
            store
                .transfer_ship_stores_in(
                    &mut txn,
                    &identity,
                    assigned.fleet_revision,
                    original_ship_id,
                    purchased_ship_id,
                    crate::wire::StoreTransferKind::Fuel,
                    0,
                    "",
                    MILLITONS_PER_TON,
                )
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let transferred = store
            .players
            .get(&txn, &encode_identity(&identity))
            .unwrap()
            .map(decode_player_record)
            .transpose()
            .unwrap()
            .unwrap();
        assert!(matches!(
            store
                .set_active_ship_in(
                    &mut txn,
                    &identity,
                    transferred.fleet_revision,
                    purchased_ship_id,
                )
                .unwrap(),
            RuleResult::Applied(_)
        ));
        txn.commit().unwrap();
        drop(store);

        let reopened = Store::open(dir.path()).unwrap();
        let player = reopened.player_record(&identity).unwrap().unwrap();
        assert_eq!(player.ship_id, purchased_ship_id);
        assert_eq!(player.managed_ship_ids.len(), 2);
        let active = reopened.ship_record(purchased_ship_id).unwrap().unwrap();
        let inactive = reopened.ship_record(original_ship_id).unwrap().unwrap();
        assert_eq!(active.commanding_person_id, player.captain_person_id);
        assert_eq!(inactive.commanding_person_id, officer.person_id);
        assert_eq!(active.current_fuel_millitons, MILLITONS_PER_TON);
    }

    #[test]
    fn captured_vessel_and_surviving_people_remain_physical_until_settlement() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let identity = identity();
        let mut txn = store.env.write_txn().unwrap();
        let (mut player, captor) = store.player_and_ship_in(&txn, &identity).unwrap();
        let mut captured = crate::combat::materialize_vessel(9_001, 2, "Prize", 72, 7).unwrap();
        captured.crew_hits = 3;
        let (captured_ship_id, captured_person_ids) = store
            .materialize_captured_ship_in(
                &mut txn,
                &identity,
                &mut player,
                &captor,
                &captured,
                crate::wire::ShipTitleKind::StolenRegistry,
                500,
            )
            .unwrap();
        assert!(!captured_person_ids.is_empty());
        for person_id in &captured_person_ids {
            assert!(store.persons.get(&txn, person_id).unwrap().is_some());
        }
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity),
                &encode_player_record(&player),
            )
            .unwrap();
        let mut career = store.career_state_in(&txn, &identity).unwrap();
        career.mode = crate::careers::CombatCareerMode::Pirate;
        career.revision = career.revision.saturating_add(1);
        career.prizes.push(crate::careers::PrizeRecord {
            prize_id: 9_002,
            captured_vessel_id: captured_ship_id,
            captured_person_ids: captured_person_ids.clone(),
            catalog_id: captured.catalog_id,
            name: captured.name,
            gross_value_credits: 1_000_000,
            realizable_value_credits: 200_000,
            condition_percent: 80,
            status: crate::careers::PrizeStatus::ReadyToFence,
            secured_second: 500,
            claim_message_id: 0,
            settlement_credits: 200_000,
            advance_credits: 0,
        });
        store
            .put_career_state_in(&mut txn, &identity, &career)
            .unwrap();
        txn.commit().unwrap();
        drop(store);

        let reopened = Store::open(dir.path()).unwrap();
        let mut txn = reopened.env.write_txn().unwrap();
        let persisted = reopened.career_state_in(&txn, &identity).unwrap();
        assert_eq!(persisted.prizes[0].captured_person_ids, captured_person_ids);
        let credits_before = reopened
            .players
            .get(&txn, &encode_identity(&identity))
            .unwrap()
            .map(decode_player_record)
            .transpose()
            .unwrap()
            .unwrap()
            .credits;
        assert!(matches!(
            reopened
                .settle_prize_in(
                    &mut txn,
                    &identity,
                    9_002,
                    persisted.revision,
                    crate::wire::PrizeSettlementMethod::Fence,
                )
                .unwrap(),
            RuleResult::Applied(_)
        ));
        assert!(
            reopened
                .ships
                .get(&txn, &captured_ship_id)
                .unwrap()
                .is_none()
        );
        for person_id in &captured_person_ids {
            assert!(reopened.persons.get(&txn, person_id).unwrap().is_none());
        }
        let settled_player = reopened
            .players
            .get(&txn, &encode_identity(&identity))
            .unwrap()
            .map(decode_player_record)
            .transpose()
            .unwrap()
            .unwrap();
        let settled_career = reopened.career_state_in(&txn, &identity).unwrap();
        assert!(settled_player.credits > credits_before);
        assert!(settled_career.underworld_standing > persisted.underworld_standing);
        assert!(settled_career.crew_pressure <= persisted.crew_pressure);
        txn.commit().unwrap();
    }

    #[test]
    fn privateer_claim_mail_awards_financed_title_to_the_physical_prize() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let identity = identity();
        let mut txn = store.env.write_txn().unwrap();
        let (mut player, captor) = store.player_and_ship_in(&txn, &identity).unwrap();
        let captured = crate::combat::materialize_vessel(9_101, 2, "Lawful Prize", 72, 7).unwrap();
        let (captured_ship_id, captured_person_ids) = store
            .materialize_captured_ship_in(
                &mut txn,
                &identity,
                &mut player,
                &captor,
                &captured,
                crate::wire::ShipTitleKind::PrizeCustody,
                500,
            )
            .unwrap();
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity),
                &encode_player_record(&player),
            )
            .unwrap();
        let mut career = store.career_state_in(&txn, &identity).unwrap();
        career.mode = crate::careers::CombatCareerMode::Privateer;
        career.prizes.push(crate::careers::PrizeRecord {
            prize_id: 9_102,
            captured_vessel_id: captured_ship_id,
            captured_person_ids: captured_person_ids.clone(),
            catalog_id: captured.catalog_id,
            name: captured.name,
            gross_value_credits: 1_000_000,
            realizable_value_credits: 800_000,
            condition_percent: 80,
            status: crate::careers::PrizeStatus::Secured,
            secured_second: 500,
            claim_message_id: 0,
            settlement_credits: 200_000,
            advance_credits: 0,
        });
        career.revision = career.revision.saturating_add(1);
        store
            .put_career_state_in(&mut txn, &identity, &career)
            .unwrap();
        let filed = match store
            .settle_prize_in(
                &mut txn,
                &identity,
                9_102,
                career.revision,
                crate::wire::PrizeSettlementMethod::FileClaim,
            )
            .unwrap()
        {
            RuleResult::Applied(snapshot) => snapshot,
            RuleResult::Rejected(message) => panic!("{message}"),
        };
        let prize = &filed.state.prizes[0];
        assert_eq!(prize.status, crate::careers::PrizeStatus::ClaimInTransit);
        assert_ne!(prize.claim_message_id, 0);
        let polity_id = store
            .simulation
            .systems(&txn)
            .unwrap()
            .into_iter()
            .find(|system| system.system_id == captor.system_id)
            .unwrap()
            .polity_id;
        let authority_system_id = store
            .simulation
            .systems(&txn)
            .unwrap()
            .into_iter()
            .filter(|system| system.polity_id == polity_id)
            .map(|system| system.system_id)
            .min()
            .unwrap();
        let systems = store.simulation.systems(&txn).unwrap();
        let route =
            crate::simulation::shortest_route(&systems, captor.system_id, authority_system_id)
                .unwrap();
        let mut delivered_second = 500_u64;
        for hop in route.windows(2) {
            let due_second = delivered_second.saturating_add(STANDARD_JUMP_SECONDS);
            let pickup = store
                .simulation
                .pickup_player_mail(
                    &mut txn,
                    captor.ship_id,
                    hop[0],
                    hop[1],
                    delivered_second,
                    due_second,
                )
                .unwrap()
                .expect("claim envelope should enter player mail custody");
            store
                .simulation
                .handoff_player_mail(
                    &mut txn,
                    captor.ship_id,
                    pickup.mailbag_id,
                    pickup.carrier_leg_id,
                    hop[1],
                    due_second,
                )
                .unwrap();
            delivered_second = due_second;
        }
        store
            .process_career_mail_arrival_in(&mut txn, authority_system_id, delivered_second)
            .unwrap();
        let adjudicated = store.career_state_in(&txn, &identity).unwrap();
        assert_eq!(
            adjudicated.prizes[0].status,
            crate::careers::PrizeStatus::Adjudicated
        );
        assert!(matches!(
            store
                .settle_prize_in(
                    &mut txn,
                    &identity,
                    9_102,
                    adjudicated.revision,
                    crate::wire::PrizeSettlementMethod::KeepPrize,
                )
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let finance = store
            .finances
            .get(&txn, &ship_finance_key(captured_ship_id))
            .unwrap()
            .map(decode_finance_record)
            .transpose()
            .unwrap()
            .unwrap();
        assert!(matches!(
            finance.title,
            crate::wire::ShipTitleKind::OwnedWithLien | crate::wire::ShipTitleKind::OwnedClear
        ));
        assert!(store.ships.get(&txn, &captured_ship_id).unwrap().is_some());
        for person_id in captured_person_ids {
            assert!(store.persons.get(&txn, &person_id).unwrap().is_none());
        }
        txn.commit().unwrap();
    }

    #[test]
    fn an_empty_watch_cannot_commit_a_jump_plan() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let _epoch = initialize_player_fixture(&store);
        let known = store
            .known_destinations_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        let destination = known
            .systems
            .iter()
            .find(|system| system.within_jump_rating && system.system_id != known.current_system_id)
            .unwrap()
            .system_id;
        let proposal = FlightPlanProposal {
            expected_plan_revision: 0,
            steps: vec![
                FlightPlanStep {
                    locus: FlightLocus::JumpLocus {
                        system_id: known.current_system_id,
                    },
                    authority: WaypointAuthority::Through,
                    action: FlightPlanAction::Jump {
                        destination_system_id: destination,
                        navigation: crate::wire::JumpNavigationMethod::Onboard,
                        proceed_on_known_bad_plot: false,
                    },
                    terminal: false,
                },
                FlightPlanStep {
                    locus: FlightLocus::Port {
                        system_id: destination,
                        world_id: destination,
                        facility_id: destination,
                    },
                    authority: WaypointAuthority::Hold,
                    action: FlightPlanAction::Dock {
                        world_id: destination,
                        facility_id: destination,
                    },
                    terminal: true,
                },
            ],
            policy: EncounterPolicy::default(),
        };
        let mut txn = store.env.write_txn().unwrap();
        let services = store
            .crew_services
            .iter(&txn)
            .unwrap()
            .map(|entry| decode_crew_service(entry.unwrap().1))
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        for mut service in services {
            service.assigned_slot_ids.clear();
            store
                .crew_services
                .put(
                    &mut txn,
                    &service.person_id,
                    &encode_crew_service(&service).unwrap(),
                )
                .unwrap();
        }
        let preview = match store
            .preview_flight_plan_in(&txn, &identity(), &proposal)
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => panic!("preview rejected unexpectedly: {message}"),
        };
        let committed = store
            .commit_flight_plan_in(
                &mut txn,
                &identity(),
                &CommitFlightPlanRequest {
                    proposal,
                    preview_hash: preview.preview_hash,
                    acknowledge_warnings: true,
                },
            )
            .unwrap();
        match committed {
            RuleResult::Rejected(message) => {
                assert!(message.contains("filed watch cannot cover"), "{message}")
            }
            RuleResult::Applied(_) => panic!("empty watch committed a jump plan"),
        }
        txn.abort();
    }

    #[test]
    fn flight_plan_preview_warns_when_an_active_task_will_be_late() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let ship = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap()
            .1;
        let known = store
            .known_destinations_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        let destination = known
            .systems
            .iter()
            .find(|system| system.within_jump_rating && system.system_id != ship.system_id)
            .unwrap()
            .system_id;
        let proposal = FlightPlanProposal {
            expected_plan_revision: 0,
            steps: vec![
                FlightPlanStep {
                    locus: FlightLocus::JumpLocus {
                        system_id: ship.system_id,
                    },
                    authority: WaypointAuthority::Through,
                    action: FlightPlanAction::Jump {
                        destination_system_id: destination,
                        navigation: crate::wire::JumpNavigationMethod::Onboard,
                        proceed_on_known_bad_plot: false,
                    },
                    terminal: false,
                },
                FlightPlanStep {
                    locus: FlightLocus::Port {
                        system_id: destination,
                        world_id: destination,
                        facility_id: destination,
                    },
                    authority: WaypointAuthority::Hold,
                    action: FlightPlanAction::Dock {
                        world_id: destination,
                        facility_id: destination,
                    },
                    terminal: true,
                },
            ],
            policy: EncounterPolicy::default(),
        };
        let task_id = 990_001;
        let mut offer = test_task_offer(
            990_000,
            ship.system_id,
            destination,
            crate::wire::TaskKind::Freight,
        );
        offer.delivery_deadline_second = STANDARD_JUMP_SECONDS;
        let mut stored = test_task(identity(), task_id, offer, 0);
        stored.task.state = crate::wire::TaskState::Loading;
        stored.task.known_result = true;
        stored.task.performing_ship_id = ship.ship_id;
        let mut txn = store.env.write_txn().unwrap();
        store
            .tasks
            .put(
                &mut txn,
                &task_id.to_be_bytes(),
                &encode_stored_task(&stored).unwrap(),
            )
            .unwrap();
        txn.commit().unwrap();

        let preview = match store
            .preview_flight_plan_in(&store.env.read_txn().unwrap(), &identity(), &proposal)
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => panic!("preview rejected unexpectedly: {message}"),
        };
        let warning = preview
            .warnings
            .iter()
            .find(|warning| warning.code == "TASK_DEADLINE_MISSED")
            .expect("late active task should produce a deadline warning");
        assert!(warning.message.contains("Task #990001"));
        assert!(warning.message.contains("after its delivery deadline"));
        let course = match store
            .plot_course_in(
                &store.env.read_txn().unwrap(),
                &identity(),
                ship.system_id,
                destination,
                true,
            )
            .unwrap()
        {
            RuleResult::Applied(course) => course,
            RuleResult::Rejected(message) => panic!("course rejected unexpectedly: {message}"),
        };
        assert!(
            preview
                .elapsed_seconds
                .abs_diff(course.fastest.elapsed_seconds)
                <= 5 * 60,
            "course and executable-plan estimates diverged: course={}, preview={}",
            course.fastest.elapsed_seconds,
            preview.elapsed_seconds,
        );
    }

    #[test]
    fn flight_plan_preview_distinguishes_hold_from_terminal_completion() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let ship = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap()
            .1;
        let known = store
            .known_destinations_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        let destination = known
            .systems
            .iter()
            .find(|system| system.within_jump_rating && system.system_id != ship.system_id)
            .unwrap()
            .system_id;
        let mut proposal = FlightPlanProposal {
            expected_plan_revision: 0,
            steps: vec![
                FlightPlanStep {
                    locus: FlightLocus::JumpLocus {
                        system_id: ship.system_id,
                    },
                    authority: WaypointAuthority::Through,
                    action: FlightPlanAction::Jump {
                        destination_system_id: destination,
                        navigation: crate::wire::JumpNavigationMethod::Onboard,
                        proceed_on_known_bad_plot: false,
                    },
                    terminal: false,
                },
                FlightPlanStep {
                    locus: FlightLocus::Port {
                        system_id: destination,
                        world_id: destination,
                        facility_id: destination,
                    },
                    authority: WaypointAuthority::Hold,
                    action: FlightPlanAction::Dock {
                        world_id: destination,
                        facility_id: destination,
                    },
                    terminal: true,
                },
            ],
            policy: EncounterPolicy::default(),
        };
        let task_id = 990_002;
        let mut offer = test_task_offer(
            990_003,
            ship.system_id,
            destination,
            crate::wire::TaskKind::Freight,
        );
        offer.delivery_deadline_second = u64::MAX / 2;
        let mut stored = test_task(identity(), task_id, offer, 0);
        stored.task.state = crate::wire::TaskState::Loading;
        stored.task.known_result = true;
        stored.task.performing_ship_id = ship.ship_id;
        let mut txn = store.env.write_txn().unwrap();
        store
            .tasks
            .put(
                &mut txn,
                &task_id.to_be_bytes(),
                &encode_stored_task(&stored).unwrap(),
            )
            .unwrap();
        txn.commit().unwrap();

        let held = match store
            .preview_flight_plan_in(&store.env.read_txn().unwrap(), &identity(), &proposal)
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => panic!("preview rejected unexpectedly: {message}"),
        };
        let warning = held
            .warnings
            .iter()
            .find(|warning| warning.code == "TASK_DEADLINE_REQUIRES_WATCH")
            .expect("manual docking should identify the arrival-watch deadline");
        assert_eq!(warning.step_indices, vec![1]);

        proposal.steps[1].authority = WaypointAuthority::Through;
        let unattended = match store
            .preview_flight_plan_in(&store.env.read_txn().unwrap(), &identity(), &proposal)
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => panic!("preview rejected unexpectedly: {message}"),
        };
        assert!(!unattended.warnings.iter().any(|warning| {
            warning.code == "TASK_DEADLINE_REQUIRES_WATCH" || warning.code == "TASK_DEADLINE_MISSED"
        }));

        proposal.steps[0].terminal = true;
        assert!(matches!(
            store
                .preview_flight_plan_in(&store.env.read_txn().unwrap(), &identity(), &proposal)
                .unwrap(),
            RuleResult::Rejected(message) if message.contains("one terminal waypoint")
        ));
        proposal.steps[0].terminal = false;
        proposal.steps[1].terminal = false;
        assert!(matches!(
            store
                .preview_flight_plan_in(&store.env.read_txn().unwrap(), &identity(), &proposal)
                .unwrap(),
            RuleResult::Rejected(message) if message.contains("one terminal waypoint")
        ));
    }

    #[test]
    fn held_nonterminal_checkpoint_resumes_the_following_step_after_watch() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let ship = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap()
            .1;
        let key = encode_identity(&identity());
        let checkpoint = CheckpointSnapshot {
            checkpoint_id: 77,
            plan_id: 88,
            plan_revision: 1,
            step_index: 0,
            locus: FlightLocus::Port {
                system_id: ship.system_id,
                world_id: ship.system_id,
                facility_id: ship.system_id,
            },
            kind: CheckpointKind::InhabitedWorld,
            ready_second: 0,
            acknowledged: true,
        };
        let plan = FlightPlanSnapshot {
            plan_id: 88,
            revision: 1,
            current_step: 0,
            state: FlightPlanState::Checkpoint,
            steps: vec![
                FlightPlanStep {
                    locus: checkpoint.locus,
                    authority: WaypointAuthority::Hold,
                    action: FlightPlanAction::Dock {
                        world_id: ship.system_id,
                        facility_id: ship.system_id,
                    },
                    terminal: false,
                },
                FlightPlanStep {
                    locus: checkpoint.locus,
                    authority: WaypointAuthority::Hold,
                    action: FlightPlanAction::Hold,
                    terminal: true,
                },
            ],
            policy: EncounterPolicy::default(),
            suspension_reason: "arrival acknowledgement required".into(),
        };
        let mut txn = store.env.write_txn().unwrap();
        put_meta_u64(store.meta, &mut txn, META_GAME_SECOND, 123).unwrap();
        store
            .flight_plans
            .put(&mut txn, &key, &encode_flight_plan_snapshot(&plan).unwrap())
            .unwrap();
        store
            .checkpoints
            .put(
                &mut txn,
                &key,
                &encode_checkpoint_snapshot(&checkpoint).unwrap(),
            )
            .unwrap();
        store
            .finish_checkpoint_arrival_in(&mut txn, &identity(), &checkpoint)
            .unwrap();
        let resumed = store.flight_plan_in(&txn, &identity()).unwrap();
        assert_eq!(resumed.state, FlightPlanState::Held);
        assert_eq!(resumed.current_step, 1);
        assert_eq!(
            resumed.suspension_reason,
            "flight plan is holding for the captain"
        );
        let (_, docked_ship) = store.player_and_ship_in(&txn, &identity()).unwrap();
        assert!(matches!(
            docked_ship.location,
            ShipLocationRecord::Docked {
                arrived_second: 123,
                ..
            }
        ));
        txn.abort();
    }

    #[test]
    fn flight_plan_preview_commit_and_checkpoint_records_are_durable() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        let known = store
            .known_destinations_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        let destination = known
            .systems
            .iter()
            .find(|system| system.within_jump_rating && system.system_id != known.current_system_id)
            .unwrap()
            .system_id;
        let proposal = FlightPlanProposal {
            expected_plan_revision: 0,
            steps: vec![
                FlightPlanStep {
                    locus: FlightLocus::JumpLocus {
                        system_id: known.current_system_id,
                    },
                    authority: WaypointAuthority::Through,
                    action: FlightPlanAction::Jump {
                        destination_system_id: destination,
                        navigation: crate::wire::JumpNavigationMethod::Onboard,
                        proceed_on_known_bad_plot: false,
                    },
                    terminal: false,
                },
                FlightPlanStep {
                    locus: FlightLocus::Port {
                        system_id: destination,
                        world_id: destination,
                        facility_id: destination,
                    },
                    authority: WaypointAuthority::Hold,
                    action: FlightPlanAction::Dock {
                        world_id: destination,
                        facility_id: destination,
                    },
                    terminal: true,
                },
            ],
            policy: EncounterPolicy::default(),
        };
        let current_ship = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap()
            .1;
        let mut txn = store.env.write_txn().unwrap();
        let mut carriage_offer_ids = Vec::new();
        for (kind, subject) in [
            (crate::wire::TaskKind::Freight, "Ordinary freight lot"),
            (crate::wire::TaskKind::Passenger, "Middle passage party"),
        ] {
            let (offer_id, _) = store
                .simulation
                .dispatch_message(
                    &mut txn,
                    0,
                    current_ship.system_id,
                    crate::simulation::MessageClass::ContractOffer,
                    crate::simulation::MessageImportance::Routine,
                    subject,
                    "Ordinary carriage offered under the standing declaration.",
                    &[],
                )
                .unwrap();
            let mut offer = test_task_offer(offer_id, current_ship.system_id, destination, kind);
            offer.collateral_credits = 0;
            offer.failure_penalty_credits = 0;
            if kind == crate::wire::TaskKind::Passenger {
                offer.quantity_millitons = 0;
                offer.passenger_count = 1;
                offer.passenger_class = crate::wire::PassengerClass::Steerage;
                offer.passenger_grace_seconds = 7 * crate::simulation::SECONDS_PER_DAY;
            }
            store
                .task_offers
                .put(
                    &mut txn,
                    &offer_id.to_be_bytes(),
                    &encode_stored_task_offer(&StoredTaskOffer {
                        offer,
                        claimed_by: None,
                        claimed_task_id: 0,
                        closure_message_id: 0,
                    })
                    .unwrap(),
                )
                .unwrap();
            carriage_offer_ids.push(offer_id);
        }
        assert!(matches!(
            store
                .set_carriage_in(
                    &mut txn,
                    &identity(),
                    crate::wire::CarriageDeclaration {
                        plan_revision: 0,
                        destination_system_id: destination,
                        freight_capacity_millitons: MILLITONS_PER_TON,
                        high_berths: 0,
                        middle_berths: 0,
                        steerage_berths: 1,
                        low_berths: 0,
                        accept_electronic_mail: true,
                    },
                )
                .unwrap(),
            RuleResult::Applied(_)
        ));
        txn.commit().unwrap();
        let preview_with_passenger = match store
            .preview_flight_plan_in(&store.env.read_txn().unwrap(), &identity(), &proposal)
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => panic!("preview rejected unexpectedly: {message}"),
        };
        let voyage_days = preview_with_passenger
            .elapsed_seconds
            .div_ceil(crate::simulation::SECONDS_PER_DAY)
            .max(1);
        let crew_count = store
            .crew_services(current_ship.ship_id)
            .unwrap()
            .into_iter()
            .map(|service| u64::from(service.represented_positions.max(1)))
            .sum::<u64>();
        let mut constrained_ship = store.ship_record(current_ship.ship_id).unwrap().unwrap();
        let original_provisions = constrained_ship.provisions.clone();
        constrained_ship.provisions.person_days_remaining = crew_count * voyage_days;
        let mut txn = store.env.write_txn().unwrap();
        store
            .ships
            .put(
                &mut txn,
                &constrained_ship.ship_id,
                &encode_ship_record(&constrained_ship).unwrap(),
            )
            .unwrap();
        let constrained_preview = match store
            .preview_flight_plan_in(&txn, &identity(), &proposal)
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => panic!("preview rejected unexpectedly: {message}"),
        };
        assert!(
            constrained_preview
                .warnings
                .iter()
                .any(|warning| warning.code == "INSUFFICIENT_PROVISIONS")
        );
        constrained_ship.provisions.person_days_remaining = 0;
        store
            .ships
            .put(
                &mut txn,
                &constrained_ship.ship_id,
                &encode_ship_record(&constrained_ship).unwrap(),
            )
            .unwrap();
        let empty_stores_preview = match store
            .preview_flight_plan_in(&txn, &identity(), &proposal)
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => panic!("preview rejected unexpectedly: {message}"),
        };
        let provision_warning = empty_stores_preview
            .warnings
            .iter()
            .find(|warning| warning.code == "INSUFFICIENT_PROVISIONS")
            .expect("empty stores should produce a provision warning");
        assert_eq!(provision_warning.step_indices, vec![0, 1]);
        constrained_ship.provisions = original_provisions;
        store
            .ships
            .put(
                &mut txn,
                &constrained_ship.ship_id,
                &encode_ship_record(&constrained_ship).unwrap(),
            )
            .unwrap();
        txn.commit().unwrap();
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 230, Command::PreviewFlightPlan(proposal.clone())),
            })
            .unwrap();
        let preview = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::FlightPlanPreview(value) => value,
            other => panic!("expected preview, got {other:?}"),
        };
        assert_eq!(preview.preview_hash.len(), 16);
        assert!(preview.elapsed_seconds >= STANDARD_JUMP_SECONDS);
        assert_eq!(preview.carriage_offers.len(), 2);
        assert!(
            preview
                .carriage_offers
                .iter()
                .all(|offer| carriage_offer_ids.contains(&offer.offer_id))
        );
        assert_eq!(preview.carriage_revenue_credits, 50_000);
        assert!(preview.carriage_broker_fees_credits > 0);
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    231,
                    Command::CommitFlightPlan(CommitFlightPlanRequest {
                        proposal: proposal.clone(),
                        preview_hash: preview.preview_hash,
                        acknowledge_warnings: true,
                    }),
                ),
            })
            .unwrap();
        let plan = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::FlightPlan(value) => value,
            other => panic!("expected committed plan, got {other:?}"),
        };
        assert_eq!(plan.revision, 1);
        let ledger = store
            .task_ledger_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        assert_eq!(ledger.tasks.len(), 2);
        assert!(
            ledger
                .tasks
                .iter()
                .any(|task| task.offer.kind == crate::wire::TaskKind::Freight)
        );
        assert!(
            ledger
                .tasks
                .iter()
                .any(|task| task.offer.kind == crate::wire::TaskKind::Passenger)
        );
        let loaded_ship = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap()
            .1;
        let freight_task_ids = ledger
            .tasks
            .iter()
            .filter(|task| task.offer.kind == crate::wire::TaskKind::Freight)
            .map(|task| task.task_id)
            .collect::<Vec<_>>();
        assert!(loaded_ship.cargo.iter().any(|lot| {
            lot.title == CargoTitle::Freight && freight_task_ids.contains(&lot.task_id)
        }));
        assert_eq!(
            store.player_phase(&identity()).unwrap(),
            PlayerPhase::Interplanetary
        );
        assert_eq!(
            store
                .contact_events
                .len(&store.env.read_txn().unwrap())
                .unwrap(),
            2
        );
        drop(store);
        let reopened = Store::open(dir.path()).unwrap();
        assert_eq!(
            reopened
                .flight_plan_in(&reopened.env.read_txn().unwrap(), &identity())
                .unwrap(),
            plan
        );
    }

    #[test]
    fn belt_cycle_persists_a_sourced_lode_and_returns_to_port() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
        ship.catalog_id = 215;
        ship.catalog_revision = 48;
        ship.name = "Test Foundry".into();
        ship.fuel_capacity_bonus_millitons = 100_000;
        ship.current_fuel_millitons = 100_000;
        ship.unrefined_fuel_millitons = 0;

        let mut txn = store.env.write_txn().unwrap();
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        let service = store
            .crew_services
            .iter(&txn)
            .unwrap()
            .filter_map(Result::ok)
            .map(|(_, bytes)| decode_crew_service(bytes).unwrap())
            .find(|service| {
                service.ship_id == ship.ship_id && !service.assigned_slot_ids.is_empty()
            })
            .unwrap();
        let mut prospector = store
            .persons
            .get(&txn, &service.person_id)
            .unwrap()
            .map(decode_person_record)
            .transpose()
            .unwrap()
            .unwrap();
        prospector.person.characteristics.intelligence = 15;
        prospector.person.skills.push(crate::wire::SkillRating {
            skill: crate::wire::SkillId::TradeProspector,
            level: 6,
        });
        store
            .persons
            .put(
                &mut txn,
                &prospector.person_id,
                &encode_person_record(&prospector).unwrap(),
            )
            .unwrap();
        txn.commit().unwrap();

        let known = store
            .known_destinations_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        let belt = known
            .belts
            .first()
            .expect("fixture system must have a belt");
        let proposal = FlightPlanProposal {
            expected_plan_revision: 0,
            steps: vec![
                FlightPlanStep {
                    locus: FlightLocus::Body {
                        system_id: known.current_system_id,
                        body_id: belt.body_id,
                    },
                    authority: WaypointAuthority::Through,
                    action: FlightPlanAction::BeltCycle {
                        body_id: belt.body_id,
                    },
                    terminal: false,
                },
                FlightPlanStep {
                    locus: FlightLocus::Port {
                        system_id: known.current_system_id,
                        world_id: known.current_system_id,
                        facility_id: known.current_system_id,
                    },
                    authority: WaypointAuthority::Through,
                    action: FlightPlanAction::Dock {
                        world_id: known.current_system_id,
                        facility_id: known.current_system_id,
                    },
                    terminal: true,
                },
            ],
            policy: EncounterPolicy::default(),
        };
        let preview = match store
            .preview_flight_plan_in(&store.env.read_txn().unwrap(), &identity(), &proposal)
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => panic!("belt-cycle preview rejected: {message}"),
        };
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    232,
                    Command::CommitFlightPlan(CommitFlightPlanRequest {
                        proposal,
                        preview_hash: preview.preview_hash,
                        acknowledge_warnings: true,
                    }),
                ),
            })
            .unwrap();
        match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::FlightPlan(_) => {}
            other => panic!("expected committed belt plan, got {other:?}"),
        }
        let outbound = store.ship_record(ship.ship_id).unwrap().unwrap();
        let (context, outbound_due) = match outbound.location {
            ShipLocationRecord::InFlight(FlightLegRecord {
                purpose: FlightLegPurpose::ReachBelt(context),
                due_second,
                ..
            }) => (context, due_second),
            other => panic!("expected outbound belt leg, got {other:?}"),
        };

        store.advance_simulation_to(outbound_due).unwrap();
        let prospect_due = match store.ship_record(ship.ship_id).unwrap().unwrap().location {
            ShipLocationRecord::InFlight(FlightLegRecord {
                purpose: FlightLegPurpose::ProspectBelt(_),
                due_second,
                ..
            }) => due_second,
            other => panic!("expected prospecting watch, got {other:?}"),
        };
        store.advance_simulation_to(prospect_due).unwrap();
        let survey_due = match store.ship_record(ship.ship_id).unwrap().unwrap().location {
            ShipLocationRecord::InFlight(FlightLegRecord {
                purpose: FlightLegPurpose::SurveyBelt(_),
                due_second,
                ..
            }) => due_second,
            other => panic!("expected survey watch, got {other:?}"),
        };
        let mut txn = store.env.write_txn().unwrap();
        let mut lode = store
            .resource_lodes
            .get(&txn, &context.lode_id)
            .unwrap()
            .map(decode_resource_lode)
            .transpose()
            .unwrap()
            .unwrap();
        lode.kind = crate::mining::ResourceKind::Metal;
        lode.grade_percent = 100;
        lode.remaining_raw_millitons = MILLITONS_PER_TON;
        store
            .resource_lodes
            .put(&mut txn, &lode.lode_id, &encode_resource_lode(lode))
            .unwrap();
        txn.commit().unwrap();

        store.advance_simulation_to(survey_due).unwrap();
        let mining_due = match store.ship_record(ship.ship_id).unwrap().unwrap().location {
            ShipLocationRecord::InFlight(FlightLegRecord {
                purpose: FlightLegPurpose::MineBelt(_),
                due_second,
                ..
            }) => due_second,
            other => panic!("expected mining day, got {other:?}"),
        };
        store.advance_simulation_to(mining_due).unwrap();
        let refining_due = match store.ship_record(ship.ship_id).unwrap().unwrap().location {
            ShipLocationRecord::InFlight(FlightLegRecord {
                purpose: FlightLegPurpose::RefineBelt(_),
                due_second,
                ..
            }) => due_second,
            other => panic!("expected refining phase, got {other:?}"),
        };
        let mined = store.ship_record(ship.ship_id).unwrap().unwrap();
        assert!(mined.cargo.iter().any(|lot| {
            lot.commodity_id == 40
                && lot.quantity_millitons == MILLITONS_PER_TON
                && lot.source_body_id == belt.body_id
                && lot.source_lode_id == context.lode_id
        }));
        assert_eq!(
            store
                .resource_lodes
                .get(&store.env.read_txn().unwrap(), &context.lode_id)
                .unwrap()
                .map(decode_resource_lode)
                .transpose()
                .unwrap()
                .unwrap()
                .remaining_raw_millitons,
            0
        );

        store.advance_simulation_to(refining_due).unwrap();
        let return_due = match store.ship_record(ship.ship_id).unwrap().unwrap().location {
            ShipLocationRecord::InFlight(FlightLegRecord {
                purpose: FlightLegPurpose::ReturnFromBelt(_),
                due_second,
                ..
            }) => due_second,
            other => panic!("expected belt return, got {other:?}"),
        };
        store.advance_simulation_to(return_due).unwrap();
        let returned = store.ship_record(ship.ship_id).unwrap().unwrap();
        assert!(matches!(
            returned.location,
            ShipLocationRecord::Docked { .. }
        ));
        assert_eq!(
            store
                .flight_plan_in(&store.env.read_txn().unwrap(), &identity())
                .unwrap()
                .state,
            FlightPlanState::Completed
        );
    }

    #[test]
    fn committed_port_fuel_purchase_executes_before_jump() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
        let original_fuel = ship.current_fuel_millitons;
        let arrived_second = match ship.location {
            ShipLocationRecord::Docked { arrived_second, .. } => arrived_second,
            _ => panic!("fixture ship is not docked"),
        };
        let current_second =
            get_meta_u64(store.meta, &store.env.read_txn().unwrap(), META_GAME_SECOND)
                .unwrap()
                .unwrap_or(0);
        let berth_fee = crate::ship_condition::berth_fee_credits(arrived_second, current_second);
        ship.current_fuel_millitons -= MILLITONS_PER_TON;
        let mut txn = store.env.write_txn().unwrap();
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        txn.commit().unwrap();

        let known = store
            .known_destinations_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        let destination = known
            .systems
            .iter()
            .find(|candidate| {
                candidate.within_jump_rating && candidate.system_id != known.current_system_id
            })
            .unwrap()
            .system_id;
        let proposal = FlightPlanProposal {
            expected_plan_revision: 0,
            steps: vec![
                FlightPlanStep {
                    locus: FlightLocus::Port {
                        system_id: known.current_system_id,
                        world_id: known.current_system_id,
                        facility_id: known.current_system_id,
                    },
                    authority: WaypointAuthority::Through,
                    action: FlightPlanAction::Fuel {
                        operation: FuelOperation::BuyRefined,
                        quantity_millitons: MILLITONS_PER_TON,
                        refine_collected: false,
                    },
                    terminal: false,
                },
                FlightPlanStep {
                    locus: FlightLocus::JumpLocus {
                        system_id: known.current_system_id,
                    },
                    authority: WaypointAuthority::Through,
                    action: FlightPlanAction::Jump {
                        destination_system_id: destination,
                        navigation: crate::wire::JumpNavigationMethod::Onboard,
                        proceed_on_known_bad_plot: false,
                    },
                    terminal: false,
                },
                FlightPlanStep {
                    locus: FlightLocus::Port {
                        system_id: destination,
                        world_id: destination,
                        facility_id: destination,
                    },
                    authority: WaypointAuthority::Hold,
                    action: FlightPlanAction::Dock {
                        world_id: destination,
                        facility_id: destination,
                    },
                    terminal: true,
                },
            ],
            policy: EncounterPolicy::default(),
        };
        let preview = match store
            .preview_flight_plan_in(&store.env.read_txn().unwrap(), &identity(), &proposal)
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => panic!("fuel-purchase plan was rejected: {message}"),
        };
        let mut bought_unrefined_then_refined = proposal.clone();
        if let FlightPlanAction::Fuel {
            operation,
            refine_collected,
            ..
        } = &mut bought_unrefined_then_refined.steps[0].action
        {
            *operation = FuelOperation::BuyUnrefined;
            *refine_collected = true;
        }
        let bought_unrefined_then_refined_preview = match store
            .preview_flight_plan_in(
                &store.env.read_txn().unwrap(),
                &identity(),
                &bought_unrefined_then_refined,
            )
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => {
                panic!("buy-and-refine plan was rejected: {message}")
            }
        };
        assert!(
            bought_unrefined_then_refined_preview
                .fuel_timings
                .iter()
                .any(|timing| timing.step_index == 0 && timing.output_refined)
        );
        assert!(
            !bought_unrefined_then_refined_preview
                .warnings
                .iter()
                .any(|warning| warning.code == "UNREFINED_JUMP_FUEL")
        );

        let mut bought_unrefined = bought_unrefined_then_refined;
        if let FlightPlanAction::Fuel {
            refine_collected, ..
        } = &mut bought_unrefined.steps[0].action
        {
            *refine_collected = false;
        }
        let bought_unrefined_preview = match store
            .preview_flight_plan_in(
                &store.env.read_txn().unwrap(),
                &identity(),
                &bought_unrefined,
            )
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => {
                panic!("unrefined-purchase plan was rejected: {message}")
            }
        };
        assert!(bought_unrefined_preview.warnings.iter().any(|warning| {
            warning.code == "UNREFINED_JUMP_FUEL" && warning.step_indices == vec![1]
        }));
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    231,
                    Command::CommitFlightPlan(CommitFlightPlanRequest {
                        proposal,
                        preview_hash: preview.preview_hash,
                        acknowledge_warnings: true,
                    }),
                ),
            })
            .unwrap();
        let committed = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::FlightPlan(plan) => plan,
            other => panic!("expected committed plan, got {other:?}"),
        };
        assert_eq!(committed.current_step, 1);
        let departing = store.ship_record(player.ship_id).unwrap().unwrap();
        assert_eq!(departing.current_fuel_millitons, original_fuel);
        let updated_player = store.player_record(&identity()).unwrap().unwrap();
        assert_eq!(
            updated_player.credits,
            player.credits - REFINED_FUEL_PRICE_PER_TON - berth_fee
        );
    }

    #[test]
    fn committed_frontier_fuel_step_uses_named_body_and_resumes_route() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
        let spec = creation::ship_status_spec(ship.catalog_id).unwrap();
        let system = store
            .systems
            .get(&store.env.read_txn().unwrap(), &ship.system_id)
            .unwrap()
            .map(decode_stellar_system)
            .transpose()
            .unwrap()
            .unwrap();
        let celestial = derive_celestial_system(&system).unwrap();
        let source = nearest_gas_giant_fuel_source(&celestial, 0.0, f64::from(spec.thrust_g))
            .or_else(|| nearest_wilderness_water_source(&celestial, 0.0, f64::from(spec.thrust_g)))
            .expect("generated BBS home must offer a frontier fuel source");
        let operation = if gas_giant_fuel_source(
            &celestial,
            0.0,
            f64::from(spec.thrust_g),
            source.body_local_id,
        )
        .is_some()
        {
            FuelOperation::GasGiant
        } else {
            FuelOperation::WildernessWater
        };
        ship.current_fuel_millitons -= MILLITONS_PER_TON;
        let mut txn = store.env.write_txn().unwrap();
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        txn.commit().unwrap();

        let known = store
            .known_destinations_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        let destination = known
            .systems
            .iter()
            .find(|candidate| {
                candidate.within_jump_rating && candidate.system_id != known.current_system_id
            })
            .unwrap()
            .system_id;
        let proposal = FlightPlanProposal {
            expected_plan_revision: 0,
            steps: vec![
                FlightPlanStep {
                    locus: FlightLocus::Body {
                        system_id: known.current_system_id,
                        body_id: source.body_local_id,
                    },
                    authority: WaypointAuthority::Through,
                    action: FlightPlanAction::Fuel {
                        operation,
                        quantity_millitons: MILLITONS_PER_TON,
                        refine_collected: true,
                    },
                    terminal: false,
                },
                FlightPlanStep {
                    locus: FlightLocus::JumpLocus {
                        system_id: known.current_system_id,
                    },
                    authority: WaypointAuthority::Through,
                    action: FlightPlanAction::Jump {
                        destination_system_id: destination,
                        navigation: crate::wire::JumpNavigationMethod::Onboard,
                        proceed_on_known_bad_plot: false,
                    },
                    terminal: false,
                },
                FlightPlanStep {
                    locus: FlightLocus::Port {
                        system_id: destination,
                        world_id: destination,
                        facility_id: destination,
                    },
                    authority: WaypointAuthority::Hold,
                    action: FlightPlanAction::Dock {
                        world_id: destination,
                        facility_id: destination,
                    },
                    terminal: true,
                },
            ],
            policy: EncounterPolicy::default(),
        };
        let preview = match store
            .preview_flight_plan_in(&store.env.read_txn().unwrap(), &identity(), &proposal)
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => panic!("fuel plan was rejected: {message}"),
        };
        assert!(preview.fuel_timings.iter().any(|timing| {
            timing.step_index == 0
                && timing.output_refined
                && timing.failed_processing_seconds == timing.processing_seconds.saturating_mul(2)
        }));
        assert!(
            !preview
                .warnings
                .iter()
                .any(|warning| warning.code == "UNREFINED_JUMP_FUEL")
        );

        let mut unrefined_then_refined = proposal.clone();
        if let FlightPlanAction::Fuel {
            refine_collected, ..
        } = &mut unrefined_then_refined.steps[0].action
        {
            *refine_collected = false;
        }
        unrefined_then_refined.steps.insert(
            1,
            FlightPlanStep {
                locus: FlightLocus::Port {
                    system_id: known.current_system_id,
                    world_id: known.current_system_id,
                    facility_id: known.current_system_id,
                },
                authority: WaypointAuthority::Through,
                action: FlightPlanAction::RefineFuel {
                    quantity_millitons: MILLITONS_PER_TON,
                },
                terminal: false,
            },
        );
        let refined_before_jump = match store
            .preview_flight_plan_in(
                &store.env.read_txn().unwrap(),
                &identity(),
                &unrefined_then_refined,
            )
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => {
                panic!("refine-before-Jump plan was rejected: {message}")
            }
        };
        assert!(
            !refined_before_jump
                .warnings
                .iter()
                .any(|warning| warning.code == "UNREFINED_JUMP_FUEL")
        );

        let mut unrefined_at_jump = proposal.clone();
        if let FlightPlanAction::Fuel {
            refine_collected, ..
        } = &mut unrefined_at_jump.steps[0].action
        {
            *refine_collected = false;
        }
        let unrefined_preview = match store
            .preview_flight_plan_in(
                &store.env.read_txn().unwrap(),
                &identity(),
                &unrefined_at_jump,
            )
            .unwrap()
        {
            RuleResult::Applied(preview) => preview,
            RuleResult::Rejected(message) => panic!("unrefined plan was rejected: {message}"),
        };
        assert!(unrefined_preview.warnings.iter().any(|warning| {
            warning.code == "UNREFINED_JUMP_FUEL" && warning.step_indices == vec![1]
        }));
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    232,
                    Command::CommitFlightPlan(CommitFlightPlanRequest {
                        proposal,
                        preview_hash: preview.preview_hash,
                        acknowledge_warnings: true,
                    }),
                ),
            })
            .unwrap();
        let committed = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::FlightPlan(plan) => plan,
            other => panic!("expected committed fuel plan, got {other:?}"),
        };
        assert_eq!(committed.current_step, 0);
        let ship = store.ship_record(player.ship_id).unwrap().unwrap();
        let activity = ship.activity.as_ref().expect("fuel work must be active");
        assert!(matches!(
            activity.site,
            ShipActivitySite::Frontier { source_body_id, .. }
                if source_body_id == source.body_local_id
        ));
        let due = activity.due_second;

        // Contacts have their own tests. Removing their deterministic inputs
        // here isolates the flight-plan continuation contract.
        let mut txn = store.env.write_txn().unwrap();
        store.contact_events.clear(&mut txn).unwrap();
        txn.commit().unwrap();
        store.advance_simulation_to(due).unwrap();

        let resumed = store.ship_record(player.ship_id).unwrap().unwrap();
        assert!(resumed.activity.is_none());
        assert!(matches!(
            resumed.location,
            ShipLocationRecord::InFlight(FlightLegRecord {
                plan_id,
                plan_revision,
                leg_index: 1,
                purpose: FlightLegPurpose::DepartForJump {
                    jump_destination_system_id,
                },
                ..
            }) if plan_id == committed.plan_id
                && plan_revision == committed.revision
                && jump_destination_system_id == destination
        ));
        let resumed_plan = store
            .flight_plan_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        assert_eq!(resumed_plan.current_step, 1);
        assert_eq!(resumed_plan.state, FlightPlanState::Active);
    }

    #[test]
    fn observations_are_ordered_but_not_retained_in_the_replay_store() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        establish_player(&store, &identity());
        let (epoch, _, _) = store.issue_session_epoch(&identity()).unwrap();
        let request = request(epoch, 1, Command::Ping);
        for _ in 0..2 {
            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: request.clone(),
                })
                .unwrap();
            let delivery = store.process_next().unwrap().unwrap();
            assert!(matches!(delivery.outcome.kind, OutcomeKind::Pong));
            assert!(!delivery.outcome.replayed);
        }
        assert_eq!(
            store.journal.len(&store.env.read_txn().unwrap()).unwrap(),
            2
        );
        assert_eq!(
            store.results.len(&store.env.read_txn().unwrap()).unwrap(),
            0
        );
        let txn = store.env.read_txn().unwrap();
        let journal = store.journal.get(&txn, &1).unwrap().unwrap();
        assert_eq!(journal[0], 1);
        let queued_len = u32::from_be_bytes(journal[1..5].try_into().unwrap()) as usize;
        assert_eq!(journal[5 + queued_len], 0);
    }

    #[test]
    fn incompatible_storage_formats_are_rejected() {
        for incompatible_version in [STORAGE_FORMAT_VERSION - 1, STORAGE_FORMAT_VERSION + 1] {
            let dir = TempDir::new().unwrap();
            {
                let store = Store::open(dir.path()).unwrap();
                assert_eq!(
                    get_meta_u64(
                        store.meta,
                        &store.env.read_txn().unwrap(),
                        META_STORAGE_FORMAT_VERSION
                    )
                    .unwrap(),
                    Some(STORAGE_FORMAT_VERSION)
                );
                let mut txn = store.env.write_txn().unwrap();
                put_meta_u64(
                    store.meta,
                    &mut txn,
                    META_STORAGE_FORMAT_VERSION,
                    incompatible_version,
                )
                .unwrap();
                txn.commit().unwrap();
            }
            assert!(matches!(
                Store::open(dir.path()),
                Err(StoreError::IncompatibleStorageFormat {
                    actual,
                    required
                }) if actual == incompatible_version && required == STORAGE_FORMAT_VERSION
            ));
        }
    }

    #[test]
    fn reopening_initialized_universe_restores_missing_radio_identifiers() {
        let dir = TempDir::new().unwrap();
        {
            let store = Store::open(dir.path()).unwrap();
            initialize_player_fixture(&store);
            let mut txn = store.env.write_txn().unwrap();
            store
                .meta
                .delete(&mut txn, META_NEXT_RADIO_TRANSMISSION_ID)
                .unwrap();
            store
                .meta
                .delete(&mut txn, META_NEXT_RADIO_RECEPTION_ID)
                .unwrap();
            txn.commit().unwrap();
        }

        let store = Store::open(dir.path()).unwrap();
        let txn = store.env.read_txn().unwrap();
        assert_eq!(
            get_meta_u64(store.meta, &txn, META_NEXT_RADIO_TRANSMISSION_ID).unwrap(),
            Some(1)
        );
        assert_eq!(
            get_meta_u64(store.meta, &txn, META_NEXT_RADIO_RECEPTION_ID).unwrap(),
            Some(1)
        );
    }

    fn squared_distance(first: [f64; 3], second: [f64; 3]) -> f64 {
        first
            .iter()
            .zip(second)
            .map(|(left, right)| (left - right).powi(2))
            .sum()
    }

    fn materialize_for_test(
        store: &Store,
        expected_revision: u64,
        cells: &std::collections::BTreeMap<CoverageChunkCoordinate, CellBitmap>,
    ) -> Result<(u64, u64), StoreError> {
        let mut transaction = store.env.write_txn()?;
        let result = store.apply_coverage_bits_in(
            &mut transaction,
            expected_revision,
            STELLAR_DISTRIBUTION_VERSION,
            COVERAGE_SAMPLER_VERSION,
            cells,
        )?;
        transaction.commit()?;
        Ok(result)
    }

    #[test]
    fn commands_commit_in_ingress_order() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        establish_player(&store, &identity());
        let (epoch, _, phase) = store.issue_session_epoch(&identity()).unwrap();
        assert_eq!(phase, PlayerPhase::Docked);
        assert_eq!(
            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: request(epoch, 1, Command::Ping),
                })
                .unwrap(),
            1
        );
        assert_eq!(
            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: request(epoch, 2, Command::Ping),
                })
                .unwrap(),
            2
        );

        assert_eq!(store.process_next().unwrap().unwrap().outbox_sequence, 1);
        assert_eq!(store.process_next().unwrap().unwrap().outbox_sequence, 2);
        assert!(store.process_next().unwrap().is_none());
        assert_eq!(store.committed_sequence().unwrap(), 2);
        assert_eq!(store.queued_count().unwrap(), 0);
        assert_eq!(store.journal_count().unwrap(), 2);
    }

