    #[test]
    fn universe_initialization_is_durable_and_idempotent() {
        let dir = TempDir::new().unwrap();
        let command_id = [0x44; COMMAND_ID_BYTES];
        let expected = {
            let store = Store::open(dir.path()).unwrap();
            let first = store
                .initialize_universe(&command_id, [0x11; 16], &initial_seeds(1), &[])
                .unwrap();
            let replay = store
                .initialize_universe(&command_id, [0x22; 16], &initial_seeds(80), &[])
                .unwrap();
            assert_eq!(replay, first);
            assert_eq!(first.polity_count, 1);
            assert!(first.system_count > INITIAL_SYSTEMS.len() as u32);
            assert_eq!(first.world_count, first.system_count);
            assert_eq!(
                store.polities().unwrap(),
                vec![Polity {
                    id: FEDERATION_POLITY_ID,
                    name: "Federation".into(),
                    naming_profile_id: FEDERATION_NAMING_PROFILE_ID,
                }]
            );
            let systems = store.stellar_systems().unwrap();
            assert_eq!(systems.len(), first.system_count as usize);
            assert_eq!(systems[0].name, "Sol");
            assert_eq!(systems[0].position_parsecs, [0.0; 3]);
            assert_eq!(systems[0].generation_seed, [1; 32]);
            assert!(
                systems
                    .iter()
                    .take(INITIAL_SYSTEMS.len())
                    .all(|system| system.polity_id == FEDERATION_POLITY_ID)
            );
            assert!(
                systems
                    .iter()
                    .skip(INITIAL_SYSTEMS.len())
                    .all(|system| system.polity_id == 0)
            );
            assert!(
                systems
                    .iter()
                    .all(|system| !system.primary_world_name.ends_with(" Primary"))
            );
            let worlds = store.worlds().unwrap();
            assert_eq!(worlds.len(), systems.len());
            assert_eq!(worlds[0], fixed_earth_world());
            let sol = store.celestial_system(SOL_SYSTEM_ID).unwrap().unwrap();
            assert_eq!(sol.primary_world(), &fixed_earth_world());
            assert!(sol.bodies.iter().any(|body| body.name == "Jupiter"));
            let coverage = store.mapping_coverage([0.0; 3]).unwrap();
            assert!(matches!(coverage, MappingCoverage::FullyMapped { .. }));
            first
        };
        let reopened = Store::open(dir.path()).unwrap();
        assert_eq!(
            reopened.stellar_systems().unwrap().len(),
            expected.system_count as usize
        );
        assert_eq!(reopened.worlds().unwrap()[0].tech_level, 13);
        assert_eq!(
            reopened
                .celestial_system(SOL_SYSTEM_ID)
                .unwrap()
                .unwrap()
                .primary_world(),
            &fixed_earth_world()
        );
        let replay = reopened
            .initialize_universe(&command_id, [0x33; 16], &initial_seeds(120), &[])
            .unwrap();
        assert_eq!(replay, expected);
    }

    #[test]
    fn mapping_oracle_returns_and_persists_materialization_bits() {
        let dir = TempDir::new().unwrap();
        let target = [1.125, -2.75, 0.375];
        let expected_cells;
        {
            let store = Store::open(dir.path()).unwrap();
            let first = store.mapping_coverage(target).unwrap();
            let MappingCoverage::NeedsMaterialization {
                coverage_revision,
                footprint_cells,
                missing_cells,
            } = first
            else {
                panic!("fresh target unexpectedly mapped");
            };
            assert_eq!(coverage_revision, 0);
            assert_eq!(
                missing_cells
                    .values()
                    .map(CellBitmap::count_ones)
                    .sum::<u64>(),
                footprint_cells
            );
            expected_cells = footprint_cells;
            assert_eq!(
                materialize_for_test(&store, coverage_revision, &missing_cells).unwrap(),
                (1, footprint_cells)
            );
            assert_eq!(
                store.mapping_coverage(target).unwrap(),
                MappingCoverage::FullyMapped {
                    coverage_revision: 1,
                    footprint_cells,
                }
            );
        }

        let reopened = Store::open(dir.path()).unwrap();
        assert_eq!(
            reopened.mapping_coverage(target).unwrap(),
            MappingCoverage::FullyMapped {
                coverage_revision: 1,
                footprint_cells: expected_cells,
            }
        );
    }

    #[test]
    fn materialization_bits_require_the_oracle_coverage_revision() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let first = store.mapping_coverage([0.0; 3]).unwrap();
        let second = store.mapping_coverage([8.0, 0.0, 0.0]).unwrap();
        let MappingCoverage::NeedsMaterialization {
            coverage_revision: first_revision,
            missing_cells: first_missing,
            ..
        } = first
        else {
            panic!("fresh target unexpectedly mapped");
        };
        let MappingCoverage::NeedsMaterialization {
            coverage_revision: second_revision,
            missing_cells: second_missing,
            ..
        } = second
        else {
            panic!("fresh target unexpectedly mapped");
        };
        assert_eq!(first_revision, second_revision);
        materialize_for_test(&store, first_revision, &first_missing).unwrap();
        assert!(matches!(
            materialize_for_test(&store, second_revision, &second_missing),
            Err(StoreError::StaleCoverageRevision {
                expected: 0,
                actual: 1,
            })
        ));
    }

