    #[test]
    fn initial_catalog_hull_precedes_a_public_unvisited_frontier_shell() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        store
            .initialize_universe(
                &[0x61; COMMAND_ID_BYTES],
                [0x71; 16],
                &initial_seeds(1),
                &[],
            )
            .unwrap();
        let systems = store.stellar_systems().unwrap();
        assert!(systems.len() > INITIAL_SYSTEMS.len());
        let simulation_systems = store.simulation_systems().unwrap();
        assert_eq!(simulation_systems.len(), systems.len());
        assert_eq!(
            simulation_systems
                .iter()
                .filter(|system| system.generated_traffic_enabled)
                .count(),
            INITIAL_SYSTEMS.len()
        );
        assert!(simulation_systems.iter().all(|system| {
            !system.generated_traffic_enabled
                || system.jump_two_neighbors.iter().all(|neighbor_id| {
                    simulation_systems.iter().any(|neighbor| {
                        neighbor.system_id == *neighbor_id && neighbor.generated_traffic_enabled
                    })
                })
        }));
        let initial_coverage = convex_polyhedron_footprint_masks(
            INITIAL_CATALOG_HULL_VERTICES,
            INITIAL_CATALOG_HULL_FACE_NORMALS,
            INITIAL_CATALOG_HULL_EDGES,
        )
        .unwrap();
        for initial in INITIAL_SYSTEMS {
            assert!(matches!(
                store.mapping_coverage(initial.position_parsecs).unwrap(),
                MappingCoverage::FullyMapped { .. }
            ));
        }
        let txn = store.env.read_txn().unwrap();
        for frontier in systems.iter().skip(INITIAL_SYSTEMS.len()) {
            let (coordinate, bit_index) = point_cell(frontier.position_parsecs).unwrap();
            assert!(
                !initial_coverage
                    .get(&coordinate)
                    .is_some_and(|cells| cells.contains(bit_index)),
                "{} was generated inside the fixed-catalog hull layer",
                frontier.name
            );
            let publication = decode_system_publication(
                store
                    .system_publications
                    .get(&txn, &frontier.id)
                    .unwrap()
                    .unwrap(),
            )
            .unwrap();
            assert_eq!(publication.state, SystemPublicationState::UniversallyKnown);
            assert_eq!(publication.completed_second, 0);
            assert!(
                store
                    .system_visits
                    .get(&txn, &frontier.id)
                    .unwrap()
                    .is_none()
            );
        }
    }

    #[test]
    fn universe_reinitialization_replaces_game_state_but_preserves_bbs_control_state() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        store
            .initialize_universe(
                &[0x05; COMMAND_ID_BYTES],
                [0x06; 16],
                &initial_seeds(1),
                &[],
            )
            .unwrap();
        let credential = store
            .add_bbs(&[0x10; COMMAND_ID_BYTES], "Dark Star", [0x42; 32])
            .unwrap();
        let settings = BbsSettings {
            bbs_name: "Dark Star BBS".into(),
            polity_name: "Far Reach".into(),
            trade_combat: 65,
            chaos_order: 25,
        };
        store
            .configure_bbs(
                credential.bbs_id,
                &[0x20; COMMAND_ID_BYTES],
                0,
                &settings,
                [0x21; 32],
            )
            .unwrap();
        establish_player(&store, &identity());
        let (old_epoch, _, _) = store.issue_session_epoch(&identity()).unwrap();
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(old_epoch, 1, Command::Ping),
            })
            .unwrap();
        store.process_next().unwrap();
        assert!(!store.pending_outbox().unwrap().is_empty());

        let initialized = store
            .initialize_universe(
                &[0x30; COMMAND_ID_BYTES],
                [0x77; 16],
                &initial_seeds(40),
                &[BbsPlacementSeed {
                    bbs_id: credential.bbs_id,
                    seed: [0x31; 32],
                }],
            )
            .unwrap();
        assert_eq!(initialized.committed_sequence, 5);
        assert_eq!(initialized.polity_count, 2);
        assert!(
            initialized.system_count
                > (INITIAL_SYSTEMS.len() + BBS_POLITY_TOTAL_SEEDED_SYSTEMS) as u32
        );
        assert_eq!(
            initialized.system_count as usize,
            store.stellar_systems().unwrap().len()
        );
        assert_eq!(initialized.world_count, initialized.system_count);
        let home = store.bbs_home(credential.bbs_id).unwrap().unwrap();
        assert_eq!(home.placement_seed, [0x31; 32]);
        assert_eq!(home.cluster_system_ids.len(), BBS_POLITY_SYSTEM_COUNT);
        assert_eq!(
            store.player_phase(&identity()).unwrap(),
            PlayerPhase::NewUser
        );
        assert!(store.pending_outbox().unwrap().is_empty());
        assert_eq!(store.bbs_credentials().unwrap(), vec![credential.clone()]);
        let configuration = store.bbs_configuration(credential.bbs_id).unwrap();
        assert_eq!(configuration.revision, 1);
        assert_eq!(configuration.settings, settings);

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(old_epoch, 1, Command::Ping),
            })
            .unwrap();
        let stale = store.process_next().unwrap().unwrap();
        assert!(matches!(
            stale.outcome.kind,
            OutcomeKind::Error {
                code: ErrorCode::StaleSession,
                ..
            }
        ));
    }

    #[test]
    fn configured_bbs_materializes_closest_fit_seeded_polity_after_initialization() {
        let dir = TempDir::new().unwrap();
        let expected_home;
        {
            let store = Store::open(dir.path()).unwrap();
            store
                .initialize_universe(
                    &[0x41; COMMAND_ID_BYTES],
                    [0x51; 16],
                    &initial_seeds(1),
                    &[],
                )
                .unwrap();
            let credential = store
                .add_bbs(&[0x61; COMMAND_ID_BYTES], "Dark Star", [0x71; 32])
                .unwrap();
            let settings = BbsSettings {
                bbs_name: "Dark Star BBS".into(),
                polity_name: "Far Reach".into(),
                trade_combat: 65,
                chaos_order: 25,
            };
            let existing_before = store.stellar_systems().unwrap();
            let candidate_distance = candidate_sites(&existing_before)
                .into_iter()
                .filter(|site| {
                    site.cluster_positions_parsecs
                        .iter()
                        .chain(std::iter::once(&site.frontier_stub_position_parsecs))
                        .all(|position| {
                            !store
                                .point_is_resolved_in(&store.env.read_txn().unwrap(), *position)
                                .unwrap()
                        })
                })
                .map(|site| site.nearest_polity_distance_parsecs)
                .min_by(f64::total_cmp)
                .unwrap();
            store
                .configure_bbs(
                    credential.bbs_id,
                    &[0x81; COMMAND_ID_BYTES],
                    0,
                    &settings,
                    [0x91; 32],
                )
                .unwrap();

            let home = store.bbs_home(credential.bbs_id).unwrap().unwrap();
            assert_eq!(home.placement_seed, [0x91; 32]);
            assert_eq!(home.generation_version, BBS_POLITY_GENERATION_VERSION);
            let polities = store.polities().unwrap();
            assert_eq!(polities.len(), 2);
            assert_eq!(
                polities
                    .iter()
                    .find(|polity| polity.id == home.polity_id)
                    .unwrap()
                    .naming_profile_id,
                polity_profile([0x91; 32]).unwrap()
            );
            let expected_minimum_systems = existing_before.len() + BBS_POLITY_TOTAL_SEEDED_SYSTEMS;
            let actual_systems = store.stellar_systems().unwrap().len();
            assert!(actual_systems > expected_minimum_systems);
            assert_eq!(store.worlds().unwrap().len(), actual_systems);
            assert_eq!(store.simulation_systems().unwrap().len(), actual_systems);
            assert!(
                stellar_jump_two_route_exists(
                    &store.stellar_systems().unwrap(),
                    home.capital_system_id,
                    SOL_SYSTEM_ID,
                ),
                "a newly materialized BBS capital must have a J-2 path to Sol"
            );
            let traffic_systems = store.simulation_systems().unwrap();
            let contact_bridge = crate::simulation::shortest_route(
                &traffic_systems,
                home.capital_system_id,
                SOL_SYSTEM_ID,
            )
            .expect("the founding contact route must become traffic-active");
            assert!(contact_bridge.iter().all(|system_id| {
                traffic_systems
                    .iter()
                    .find(|system| system.system_id == *system_id)
                    .is_some_and(|system| system.generated_traffic_enabled)
            }));

            let systems = store.stellar_systems().unwrap();
            let worlds = store.worlds().unwrap();
            assert_eq!(
                systems
                    .iter()
                    .map(|system| system.name.to_ascii_lowercase())
                    .collect::<HashSet<_>>()
                    .len(),
                systems.len()
            );
            let capital = worlds
                .iter()
                .find(|world| world.id == home.capital_world_id)
                .unwrap();
            assert_eq!(capital.tech_level, 12);
            assert!(matches!(
                capital.starport,
                crate::universe::Starport::A
                    | crate::universe::Starport::B
                    | crate::universe::Starport::C
            ));
            assert_eq!(capital.name, "Dark Star BBS");
            for system_id in home
                .cluster_system_ids
                .into_iter()
                .chain(std::iter::once(home.frontier_stub_system_id))
            {
                let system = systems
                    .iter()
                    .find(|system| system.id == system_id)
                    .unwrap();
                assert!(!system.name.starts_with("Far Reach"));
                assert!(!system.name.starts_with("Frontier "));
                assert!(!system.primary_world_name.ends_with(" Primary"));
            }
            let first_companion = worlds
                .iter()
                .find(|world| world.system_id == home.companion_system_ids[0])
                .unwrap();
            let second_companion = worlds
                .iter()
                .find(|world| world.system_id == home.companion_system_ids[1])
                .unwrap();
            assert!(first_companion.is_agricultural());
            assert!(second_companion.is_industrial());
            for system_id in
                std::iter::once(home.capital_system_id).chain(home.companion_system_ids)
            {
                let system = systems
                    .iter()
                    .find(|system| system.id == system_id)
                    .unwrap();
                let celestial = derive_celestial_system(system).unwrap();
                let guarded_days = bbs_core_jump_guard_days(&celestial);
                assert!(guarded_days >= crate::navigation::MINIMUM_JUMP_APPROACH_DAYS);
                assert!(guarded_days <= BBS_CORE_MAXIMUM_JUMP_APPROACH_DAYS);
            }
            for system_id in home.cluster_system_ids {
                let world = worlds
                    .iter()
                    .find(|world| world.system_id == system_id)
                    .unwrap();
                assert!(world.is_inhabited());
                assert!(world.tech_level <= 12);
            }

            let cluster = home
                .cluster_system_ids
                .iter()
                .map(|system_id| {
                    systems
                        .iter()
                        .find(|system| system.id == *system_id)
                        .unwrap()
                })
                .collect::<Vec<_>>();
            let capital_system = systems
                .iter()
                .find(|system| system.id == home.capital_system_id)
                .unwrap();
            let actual_distance = existing_before
                .iter()
                .filter(|system| system.polity_id != 0)
                .map(|system| {
                    squared_distance(capital_system.position_parsecs, system.position_parsecs)
                        .sqrt()
                })
                .min_by(f64::total_cmp)
                .unwrap();
            assert!((actual_distance - candidate_distance).abs() < 1e-9);
            for companion_id in home.companion_system_ids {
                let companion = systems
                    .iter()
                    .find(|system| system.id == companion_id)
                    .unwrap();
                assert!(
                    squared_distance(capital_system.position_parsecs, companion.position_parsecs)
                        <= 1.0 + 1e-9
                );
            }
            let mut gateways = 0;
            for member in &cluster {
                for external in systems
                    .iter()
                    .filter(|system| !home.cluster_system_ids.contains(&system.id))
                {
                    let distance =
                        squared_distance(member.position_parsecs, external.position_parsecs);
                    if distance <= 9.0 + 1e-9 {
                        assert!(distance <= 4.0 + 1e-9);
                        gateways += 1;
                    }
                }
            }
            assert!((1..=3).contains(&gateways));
            assert!(systems.iter().any(|system| {
                system.id == home.frontier_stub_system_id && system.polity_id == 0
            }));
            for system_id in home.cluster_system_ids {
                let system = systems
                    .iter()
                    .find(|system| system.id == system_id)
                    .unwrap();
                let stored = worlds
                    .iter()
                    .find(|world| world.system_id == system_id)
                    .unwrap();
                let regenerated = generate_primary_world(
                    stored.id,
                    stored.system_id,
                    stored.name.clone(),
                    system.generation_seed,
                )
                .unwrap();
                assert_eq!(&regenerated, stored);
            }
            let simulation_systems = store.simulation_systems().unwrap();
            let coverage_txn = store.env.read_txn().unwrap();
            for member in cluster {
                assert!(
                    store
                        .system_visits
                        .get(&coverage_txn, &member.id)
                        .unwrap()
                        .is_some(),
                    "every BBS polity member begins visited"
                );
                assert!(
                    simulation_systems
                        .iter()
                        .find(|system| system.system_id == member.id)
                        .unwrap()
                        .generated_traffic_enabled,
                    "every BBS polity member participates in generated traffic"
                );
                let footprint = sphere_footprint_masks(
                    member.position_parsecs,
                    crate::coverage::JUMP_ARRIVAL_MAPPING_RADIUS_PARSECS,
                )
                .unwrap();
                for (coordinate, required) in footprint {
                    let encoded = store
                        .coverage_chunks
                        .get(&coverage_txn, &coverage_chunk_key(coordinate))
                        .unwrap()
                        .unwrap();
                    let resolved = decode_coverage_chunk(encoded).unwrap().resolved_cells();
                    let mut missing = required;
                    missing.subtract(&resolved);
                    assert!(missing.is_empty());
                }
            }
            assert!(
                store
                    .system_visits
                    .get(&coverage_txn, &home.frontier_stub_system_id)
                    .unwrap()
                    .is_none(),
                "the unaligned outward stub remains frontier"
            );
            assert!(
                !simulation_systems
                    .iter()
                    .find(|system| system.system_id == home.frontier_stub_system_id)
                    .unwrap()
                    .generated_traffic_enabled,
                "generated traffic must not enter the unvisited stub"
            );
            expected_home = home;
        }

        let reopened = Store::open(dir.path()).unwrap();
        assert_eq!(reopened.bbs_home(1).unwrap(), Some(expected_home));
        assert_eq!(
            reopened.simulation_systems().unwrap().len(),
            reopened.stellar_systems().unwrap().len()
        );
    }

    #[test]
    fn one_public_contact_packet_discloses_the_entire_origin_polity() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        store
            .initialize_universe(
                &[0x92; COMMAND_ID_BYTES],
                [0x93; 16],
                &initial_seeds(9),
                &[],
            )
            .unwrap();
        let credential = store
            .add_bbs(&[0x94; COMMAND_ID_BYTES], "Contact BBS", [0x95; 32])
            .unwrap();
        store
            .configure_bbs(
                credential.bbs_id,
                &[0x96; COMMAND_ID_BYTES],
                0,
                &BbsSettings {
                    bbs_name: "Contact BBS".into(),
                    polity_name: "Packet Reach".into(),
                    trade_combat: 50,
                    chaos_order: 50,
                },
                [0x97; 32],
            )
            .unwrap();
        let home = store.bbs_home(credential.bbs_id).unwrap().unwrap();
        let systems = store.stellar_systems().unwrap();
        let (contact_system_id, message_id) = {
            let txn = store.env.read_txn().unwrap();
            let mut contact = None;
            for system in systems {
                if system.id == home.capital_system_id {
                    continue;
                }
                for available in store
                    .simulation
                    .available_messages(&txn, system.id, 0, true)
                    .unwrap()
                {
                    if available.message.origin_system_id == home.capital_system_id
                        && available.message.subject == "New polity: Packet Reach"
                    {
                        contact = Some((system.id, available.message.message_id));
                        break;
                    }
                }
                if contact.is_some() {
                    break;
                }
            }
            contact.expect("the arriving polity ship must deposit its founding packet")
        };
        establish_player(&store, &identity());

        {
            let mut txn = store.env.write_txn().unwrap();
            let (_, mut ship) = store.player_and_ship_in(&txn, &identity()).unwrap();
            ship.system_id = contact_system_id;
            ship.location = ShipLocationRecord::Docked {
                world_id: contact_system_id,
                facility_id: contact_system_id,
                arrived_second: 0,
            };
            store
                .ships
                .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
                .unwrap();
            store
                .player_arrivals
                .put(
                    &mut txn,
                    &encode_identity(&identity()),
                    &encode_player_arrival(&PlayerArrivalRecord {
                        system_id: contact_system_id,
                        arrival_second: 0,
                        mailbag_id: None,
                        mail_delivered: 1,
                        mail_forwarded: 0,
                        mail_expired: 0,
                        stipend_credits: 0,
                        presented: false,
                    }),
                )
                .unwrap();
            txn.commit().unwrap();
        }

        let mut txn = store.env.write_txn().unwrap();
        let packet = store.open_arrival_packet_in(&mut txn, &identity()).unwrap();
        assert!(
            packet
                .items
                .iter()
                .any(|item| item.message_id == message_id)
        );
        txn.commit().unwrap();

        let player = store.player_record(&identity()).unwrap().unwrap();
        for system_id in home.cluster_system_ids {
            assert!(
                player.known_system_ids.contains(&system_id),
                "one packet must disclose every polity member"
            );
        }
        assert!(
            !player
                .known_system_ids
                .contains(&home.frontier_stub_system_id)
        );
        let txn = store.env.read_txn().unwrap();
        for system_id in home.cluster_system_ids {
            let mapping = store
                .player_system_mappings
                .get(&txn, &player_system_mapping_key(&identity(), system_id))
                .unwrap()
                .map(decode_player_system_mapping)
                .transpose()
                .unwrap()
                .unwrap();
            assert_eq!(mapping.state, SystemMappingState::KnownPublic);
            assert_eq!(mapping.dispatch_message_id, Some(message_id));
        }
    }

    #[test]
    fn polity_policy_changes_take_effect_only_after_the_mail_notice_arrives() {
        let directory = TempDir::new().unwrap();
        let store = Store::open(directory.path()).unwrap();
        store
            .initialize_universe(
                &[0x13; COMMAND_ID_BYTES],
                [0x14; 16],
                &initial_seeds(4),
                &[],
            )
            .unwrap();
        let credential = store
            .add_bbs(&[0x15; COMMAND_ID_BYTES], "Policy BBS", [0x16; 32])
            .unwrap();
        let initial_settings = BbsSettings {
            bbs_name: "Policy BBS".into(),
            polity_name: "Policy Reach".into(),
            trade_combat: 50,
            chaos_order: 0,
        };
        store
            .configure_bbs(
                credential.bbs_id,
                &[0x17; COMMAND_ID_BYTES],
                0,
                &initial_settings,
                [0x18; 32],
            )
            .unwrap();
        let home = store.bbs_home(credential.bbs_id).unwrap().unwrap();
        let companion_id = home.companion_system_ids[0];
        let companion = store
            .stellar_systems()
            .unwrap()
            .into_iter()
            .find(|system| system.id == companion_id)
            .unwrap();
        let low_law = {
            let txn = store.env.read_txn().unwrap();
            assert_eq!(
                decode_system_polity_policy(
                    store
                        .system_polity_policies
                        .get(&txn, &companion_id)
                        .unwrap()
                        .unwrap()
                )
                .unwrap()
                .revision,
                1
            );
            store.primary_world_in(&txn, &companion).unwrap().law_level
        };

        let changed = BbsSettings {
            chaos_order: 100,
            ..initial_settings
        };
        store
            .configure_bbs(
                credential.bbs_id,
                &[0x19; COMMAND_ID_BYTES],
                1,
                &changed,
                [0x1a; 32],
            )
            .unwrap();
        {
            let txn = store.env.read_txn().unwrap();
            let capital_policy = decode_system_polity_policy(
                store
                    .system_polity_policies
                    .get(&txn, &home.capital_system_id)
                    .unwrap()
                    .unwrap(),
            )
            .unwrap();
            let companion_policy = decode_system_polity_policy(
                store
                    .system_polity_policies
                    .get(&txn, &companion_id)
                    .unwrap()
                    .unwrap(),
            )
            .unwrap();
            assert_eq!(capital_policy.revision, 2);
            assert_ne!(capital_policy.message_id, 0);
            assert_eq!(companion_policy.revision, 1);
            assert_eq!(
                store.primary_world_in(&txn, &companion).unwrap().law_level,
                low_law
            );
        }

        let due_second = crate::simulation::STANDARD_JUMP_SECONDS;
        let mut txn = store.env.write_txn().unwrap();
        let pickup = store
            .simulation
            .pickup_player_mail(
                &mut txn,
                9_999,
                home.capital_system_id,
                companion_id,
                0,
                due_second,
            )
            .unwrap()
            .expect("the policy order must be queued for the companion");
        store
            .simulation
            .handoff_player_mail(
                &mut txn,
                9_999,
                pickup.mailbag_id,
                pickup.carrier_leg_id,
                companion_id,
                due_second,
            )
            .unwrap();
        assert_eq!(
            store
                .process_polity_policy_mail_arrival_in(&mut txn, companion_id, due_second)
                .unwrap(),
            1
        );
        let applied = decode_system_polity_policy(
            store
                .system_polity_policies
                .get(&txn, &companion_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(applied.revision, 2);
        assert_eq!(applied.effective_second, due_second);
        assert!(store.primary_world_in(&txn, &companion).unwrap().law_level > low_law);
        txn.commit().unwrap();
    }

    #[test]
    fn later_bbs_polity_preserves_every_existing_guard_and_gateway_boundary() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        store
            .initialize_universe(
                &[0x11; COMMAND_ID_BYTES],
                [0x12; 16],
                &initial_seeds(2),
                &[],
            )
            .unwrap();
        for (index, seed) in [[0x31; 32], [0x41; 32]].into_iter().enumerate() {
            let credential = store
                .add_bbs(
                    &[0x20 + index as u8; COMMAND_ID_BYTES],
                    &format!("BBS {}", index + 1),
                    [0x50 + index as u8; 32],
                )
                .unwrap();
            store
                .configure_bbs(
                    credential.bbs_id,
                    &[0x60 + index as u8; COMMAND_ID_BYTES],
                    0,
                    &BbsSettings {
                        bbs_name: format!("BBS {}", index + 1),
                        polity_name: format!("Polity {}", index + 1),
                        trade_combat: 50,
                        chaos_order: 50,
                    },
                    seed,
                )
                .unwrap();
        }

        let homes = [
            store.bbs_home(1).unwrap().unwrap(),
            store.bbs_home(2).unwrap().unwrap(),
        ];
        assert_ne!(homes[0].capital_system_id, homes[1].capital_system_id);
        let systems = store.stellar_systems().unwrap();
        let simulation_systems = store.simulation_systems().unwrap();
        assert_eq!(store.polities().unwrap().len(), 3);
        let expected_systems = simulation_systems.len();
        assert_eq!(systems.len(), expected_systems);
        assert_eq!(store.worlds().unwrap().len(), expected_systems);
        for home in homes {
            assert!(
                stellar_jump_two_route_exists(&systems, home.capital_system_id, SOL_SYSTEM_ID,),
                "every newly materialized BBS capital must remain on Sol's J-2 network"
            );
            assert!(
                crate::simulation::shortest_route(
                    &simulation_systems,
                    home.capital_system_id,
                    SOL_SYSTEM_ID,
                )
                .is_some(),
                "each founding contact must chart a traffic-active bridge"
            );
            let mut gateways = 0;
            for member_id in home.cluster_system_ids {
                let member = systems
                    .iter()
                    .find(|system| system.id == member_id)
                    .unwrap();
                for external in systems
                    .iter()
                    .filter(|system| !home.cluster_system_ids.contains(&system.id))
                {
                    let distance =
                        squared_distance(member.position_parsecs, external.position_parsecs);
                    if distance <= 9.0 + 1e-9 {
                        assert!(
                            distance <= 4.0 + 1e-9,
                            "non-gateway J-3 edge from {} to {}",
                            member.id,
                            external.id
                        );
                        gateways += 1;
                    }
                }
            }
            assert!((1..=3).contains(&gateways));
        }
    }

    #[test]
    fn scheduled_mail_is_carried_delivered_deterministically_and_survives_reopen() {
        fn run(path: &std::path::Path) -> (SimulationReport, Vec<CarrierLeg>) {
            let store = Store::open(path).unwrap();
            store
                .initialize_universe(
                    &[0xa1; COMMAND_ID_BYTES],
                    [0xa2; 16],
                    &initial_seeds(0x40),
                    &[],
                )
                .unwrap();
            let system_count = store.stellar_systems().unwrap().len();
            let advance = store
                .advance_simulation_to(8 * crate::simulation::SECONDS_PER_DAY)
                .unwrap();
            assert_eq!(advance.system_day_events, 9 * system_count as u64);
            assert_eq!(
                advance.processed_events,
                advance.system_day_events
                    + advance.traffic_departure_events
                    + advance.traffic_arrival_events
            );
            assert_eq!(advance.per_system.len(), system_count);
            assert!(advance.universe_days_per_wall_second(system_count).unwrap() > 0.0);
            if advance.thread_cpu_nanoseconds.is_some() {
                assert!(advance.universe_days_per_cpu_second(system_count).unwrap() > 0.0);
            }
            let report = store.simulation_report().unwrap();
            assert!(report.message_count() > 0);
            assert!(report.remote_envelope_count() > 0);
            assert!(report.traffic_ships > 0);
            assert!(report.mailbags > 0);
            assert!(report.mailbags_delivered > 0);
            assert!(report.envelopes_delivered > 0);
            assert_eq!(store.audit_mail_custody().unwrap(), report.carrier_legs);
            let legs = store.recent_carrier_legs(16).unwrap();
            (report, legs)
        }

        let first_dir = TempDir::new().unwrap();
        let (first_report, first_legs) = run(first_dir.path());
        let reopened = Store::open(first_dir.path()).unwrap();
        assert_eq!(reopened.simulation_report().unwrap(), first_report);
        assert_eq!(reopened.recent_carrier_legs(16).unwrap(), first_legs);
        assert_eq!(
            reopened.audit_mail_custody().unwrap(),
            first_report.carrier_legs
        );

        let second_dir = TempDir::new().unwrap();
        let (second_report, second_legs) = run(second_dir.path());
        assert_eq!(second_report, first_report);
        assert_eq!(second_legs, first_legs);
    }

    #[test]
    fn bbs_configuration_is_revisioned_durable_and_idempotent() {
        let dir = TempDir::new().unwrap();
        let settings = BbsSettings {
            bbs_name: "Dark Star BBS".into(),
            polity_name: "Far Reach".into(),
            trade_combat: 65,
            chaos_order: 25,
        };
        {
            let store = Store::open(dir.path()).unwrap();
            store
                .initialize_universe(
                    &[0x01; COMMAND_ID_BYTES],
                    [0x02; 16],
                    &initial_seeds(1),
                    &[],
                )
                .unwrap();
            let credential = store
                .add_bbs(&[0x10; COMMAND_ID_BYTES], "Dark Star", [0x42; 32])
                .unwrap();
            assert_eq!(
                store.bbs_configuration(credential.bbs_id).unwrap(),
                BbsConfiguration {
                    bbs_id: credential.bbs_id,
                    revision: 0,
                    configured: false,
                    settings: BbsSettings {
                        bbs_name: "Dark Star".into(),
                        polity_name: String::new(),
                        trade_combat: 50,
                        chaos_order: 50,
                    },
                    committed_sequence: credential.committed_sequence,
                }
            );
            let updated = store
                .configure_bbs(
                    credential.bbs_id,
                    &[0x20; COMMAND_ID_BYTES],
                    0,
                    &settings,
                    [0x21; 32],
                )
                .unwrap();
            let ConfigureBbsResult::Updated(updated) = updated else {
                panic!("initial configuration unexpectedly stale");
            };
            assert_eq!(updated.revision, 1);
            assert!(updated.configured);
            assert_eq!(updated.settings, settings);

            let replay = store
                .configure_bbs(
                    credential.bbs_id,
                    &[0x20; COMMAND_ID_BYTES],
                    0,
                    &BbsSettings {
                        bbs_name: "ignored".into(),
                        polity_name: "ignored".into(),
                        trade_combat: 0,
                        chaos_order: 0,
                    },
                    [0x22; 32],
                )
                .unwrap();
            assert_eq!(replay, ConfigureBbsResult::Updated(updated.clone()));

            let stale = store
                .configure_bbs(
                    credential.bbs_id,
                    &[0x30; COMMAND_ID_BYTES],
                    0,
                    &settings,
                    [0x23; 32],
                )
                .unwrap();
            assert_eq!(stale, ConfigureBbsResult::Stale(updated.clone()));
            assert_eq!(store.journal_count().unwrap(), 3);
        }
        let reopened = Store::open(dir.path()).unwrap();
        let configuration = reopened.bbs_configuration(1).unwrap();
        assert_eq!(configuration.revision, 1);
        assert_eq!(configuration.settings, settings);
    }

    #[test]
    fn new_user_can_only_create_player_then_becomes_docked() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        store
            .initialize_universe(
                &[0x85; COMMAND_ID_BYTES],
                [0x86; 16],
                &initial_seeds(90),
                &[],
            )
            .unwrap();
        let credential = store
            .add_bbs(&[0x81; COMMAND_ID_BYTES], "Creation Test", [0x82; 32])
            .unwrap();
        store
            .configure_bbs(
                credential.bbs_id,
                &[0x83; COMMAND_ID_BYTES],
                0,
                &BbsSettings {
                    bbs_name: "Creation Test".into(),
                    polity_name: "Test Reach".into(),
                    trade_combat: 0,
                    chaos_order: 100,
                },
                [0x84; 32],
            )
            .unwrap();
        let (epoch, _, phase) = store.issue_session_epoch(&identity()).unwrap();
        assert_eq!(phase, PlayerPhase::NewUser);

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 1, Command::GetCaptainCreationOptions),
            })
            .unwrap();
        let options = store.process_next().unwrap().unwrap();
        assert_eq!(options.outcome.phase, PlayerPhase::NewUser);
        assert!(matches!(
            options.outcome.kind,
            OutcomeKind::CaptainCreationOptions(_)
        ));

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 2, Command::CreatePlayer(profile())),
            })
            .unwrap();
        let created = store.process_next().unwrap().unwrap();
        assert_eq!(created.outcome.phase, PlayerPhase::Docked);
        assert_eq!(created.outcome.kind, OutcomeKind::PlayerCreated(profile()));
        assert_eq!(
            store.player_phase(&identity()).unwrap(),
            PlayerPhase::Docked
        );
        let player = store.player_record(&identity()).unwrap().unwrap();
        let home = store.bbs_home(credential.bbs_id).unwrap().unwrap();
        assert!(
            player
                .known_system_ids
                .contains(&home.frontier_stub_system_id),
            "a new local captain must inherit the BBS's plotted frontier"
        );
        assert!(
            store
                .system_visits
                .get(
                    &store.env.read_txn().unwrap(),
                    &home.frontier_stub_system_id
                )
                .unwrap()
                .is_none(),
            "starting-chart knowledge must not turn frontier into visited space"
        );
        assert_eq!(
            store
                .person_record(player.captain_person_id)
                .unwrap()
                .unwrap()
                .person
                .name,
            "Alex Mercer"
        );
        let first_crew = store
            .person_record(player.captain_person_id + 1)
            .unwrap()
            .unwrap();
        let first_slot = creation::crew_plan(1, creation::SETUP_REVISION, 1)
            .unwrap()
            .slots
            .into_iter()
            .next()
            .unwrap();
        let mut expected_crew = first_slot.default_crew;
        expected_crew.name = profile().crew[0].name.clone();
        assert_eq!(first_crew.person, expected_crew);
        let ship = store.ship_record(player.ship_id).unwrap().unwrap();
        assert_eq!(ship.catalog_id, 192);
        assert_eq!(ship.name, "Far Horizon");
        assert_eq!(
            store.crew_services(player.ship_id).unwrap().len(),
            profile().crew.len() + 1
        );

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 3, Command::CreatePlayer(profile())),
            })
            .unwrap();
        let duplicate = store.process_next().unwrap().unwrap();
        assert_eq!(duplicate.outcome.phase, PlayerPhase::Docked);
        assert!(matches!(
            duplicate.outcome.kind,
            OutcomeKind::Error {
                code: ErrorCode::InvalidCommand,
                ..
            }
        ));

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 4, Command::GetCrewManagement),
            })
            .unwrap();
        let roster = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::CrewManagement(snapshot) => snapshot,
            other => panic!("expected crew snapshot, got {other:?}"),
        };
        assert_eq!(roster.members.len(), profile().crew.len() + 1);
        assert!(roster.roles.len() >= roster.members.len());
        assert!(
            roster
                .members
                .iter()
                .all(|member| member.assigned_slot_ids.contains(&member.slot_id))
        );

        let captain_slot = roster
            .roles
            .iter()
            .find(|role| role.slot_id == 0)
            .unwrap()
            .slot_id;
        let pilot_slot = roster
            .roles
            .iter()
            .find(|role| role.role.eq_ignore_ascii_case("pilot"))
            .unwrap()
            .slot_id;
        let target = roster
            .members
            .iter()
            .find(|member| !member.captain && member.slot_id != pilot_slot)
            .unwrap();
        let nonpilot_roles: Vec<_> = roster
            .roles
            .iter()
            .filter(|role| role.slot_id != captain_slot && role.slot_id != pilot_slot)
            .map(|role| role.slot_id)
            .take(2)
            .collect();
        assert_eq!(nonpilot_roles.len(), 2);

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    5,
                    Command::SetCrewAssignments {
                        person_id: target.person_id,
                        slot_ids: nonpilot_roles.clone(),
                    },
                ),
            })
            .unwrap();
        let doubled = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::CrewManagement(snapshot) => snapshot,
            other => panic!("expected crew snapshot, got {other:?}"),
        };
        assert_eq!(
            doubled
                .members
                .iter()
                .find(|member| member.person_id == target.person_id)
                .unwrap()
                .assigned_slot_ids,
            nonpilot_roles
        );

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    6,
                    Command::SetCrewAssignments {
                        person_id: target.person_id,
                        slot_ids: Vec::new(),
                    },
                ),
            })
            .unwrap();
        let resting = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::CrewManagement(snapshot) => snapshot,
            other => panic!("expected crew snapshot, got {other:?}"),
        };
        assert!(
            resting
                .members
                .iter()
                .find(|member| member.person_id == target.person_id)
                .unwrap()
                .assigned_slot_ids
                .is_empty()
        );

        for (id, slot_ids, expected_fragment) in [
            (7, vec![captain_slot], "only the captain"),
            (8, vec![pilot_slot], "only one person"),
            (
                9,
                vec![nonpilot_roles[0], nonpilot_roles[0]],
                "only be assigned once",
            ),
        ] {
            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: request(
                        epoch,
                        id,
                        Command::SetCrewAssignments {
                            person_id: target.person_id,
                            slot_ids,
                        },
                    ),
                })
                .unwrap();
            let rejected = store.process_next().unwrap().unwrap();
            match rejected.outcome.kind {
                OutcomeKind::Error {
                    code: ErrorCode::InvalidCommand,
                    message,
                } => assert!(message.contains(expected_fragment), "{message}"),
                other => panic!("expected rejected crew assignment, got {other:?}"),
            }
        }

        let shared_role_owner = roster
            .members
            .iter()
            .find(|member| {
                member.person_id != target.person_id
                    && !member.captain
                    && member.slot_id != pilot_slot
            })
            .unwrap();
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    10,
                    Command::SetCrewAssignments {
                        person_id: target.person_id,
                        slot_ids: vec![shared_role_owner.slot_id],
                    },
                ),
            })
            .unwrap();
        assert!(matches!(
            store.process_next().unwrap().unwrap().outcome.kind,
            OutcomeKind::CrewManagement(_)
        ));

        let old_training = target.person.training;
        let new_training_skill = target
            .person
            .skills
            .iter()
            .map(|rating| rating.skill)
            .find(|skill| {
                *skill != old_training.skill && *skill != crate::wire::SkillId::JackOfAllTrades
            })
            .unwrap();
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    11,
                    Command::SetCrewTrainingTarget {
                        person_id: target.person_id,
                        skill: new_training_skill,
                    },
                ),
            })
            .unwrap();
        let trained = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::CrewManagement(snapshot) => snapshot,
            other => panic!("expected crew snapshot, got {other:?}"),
        };
        let changed = trained
            .members
            .iter()
            .find(|member| member.person_id == target.person_id)
            .unwrap();
        assert_eq!(changed.person.training.skill, new_training_skill);
        assert_eq!(changed.person.training.current_weeks, 0);
        assert!(changed.person.training.needed_weeks > 0);

        let mut stored_ship = store.ship_record(player.ship_id).unwrap().unwrap();
        let spec = creation::ship_status_spec(stored_ship.catalog_id).unwrap();
        assert_eq!(
            stored_ship.current_fuel_millitons,
            spec.fuel_capacity_millitons
        );
        assert!(stored_ship.subsystems.iter().all(|subsystem| {
            subsystem.sustained_hits == 0
                && subsystem.battlefield_repair_hits == 0
                && subsystem.last_proper_repair_second == 0
                && subsystem.installed_second == 0
                && subsystem.calendar_age_months == 0
        }));
        let jump = stored_ship
            .subsystems
            .iter_mut()
            .find(|subsystem| subsystem.kind == ShipSubsystemKind::JumpDrive)
            .unwrap();
        jump.sustained_hits = 2;
        jump.battlefield_repair_hits = 1;
        jump.calendar_age_months = 1;
        jump.neglect_damage_hits = 1;
        let jump_id = jump.subsystem_id;
        {
            let mut transaction = store.env.write_txn().unwrap();
            store
                .ships
                .put(
                    &mut transaction,
                    &stored_ship.ship_id,
                    &encode_ship_record(&stored_ship).unwrap(),
                )
                .unwrap();
            put_meta_u64(store.meta, &mut transaction, META_GAME_SECOND, 101).unwrap();
            transaction.commit().unwrap();
        }
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 12, Command::GetShipStatus),
            })
            .unwrap();
        let status = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::ShipStatus(snapshot) => snapshot,
            other => panic!("expected ship status, got {other:?}"),
        };
        assert_eq!(status.current_game_second, 101);
        assert_eq!(
            status.current_fuel_millitons,
            status.fuel_capacity_millitons
        );
        let jump = status
            .subsystems
            .iter()
            .find(|subsystem| subsystem.subsystem_id == jump_id)
            .unwrap();
        assert_eq!(jump.sustained_hits, 2);
        assert_eq!(jump.battlefield_repair_hits, 1);
        assert_eq!(jump.effective_hits, 1);
        assert_eq!(jump.operational_effect, "-2 DM to Jump Engineering checks");
        assert_eq!(jump.last_proper_repair_second, 0);
        assert_eq!(jump.installed_second, 0);
        assert_eq!(jump.calendar_age_months, 1);
        assert_eq!(jump.neglect_damage_hits, 1);
    }

    #[test]
    fn local_cargo_resale_uses_the_displayed_non_crossing_bid() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        const QUANTITY: u64 = MILLITONS_PER_TON + 1;

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 190, Command::GetMarket),
            })
            .unwrap();
        let market = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::Market(snapshot) => snapshot,
            other => panic!("expected market snapshot, got {other:?}"),
        };
        let offer = market.offers[0].clone();

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    191,
                    Command::BuyCargo {
                        market_revision: market.market_revision,
                        offer_id: offer.offer_id,
                        quantity_millitons: QUANTITY,
                    },
                ),
            })
            .unwrap();
        let loaded = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::Market(snapshot) => snapshot,
            other => panic!("expected loaded market, got {other:?}"),
        };
        let lot = &loaded.cargo[0];
        let quote = loaded
            .cargo_sale_quotes
            .iter()
            .find(|quote| quote.cargo_lot_id == lot.cargo_lot_id)
            .expect("player-owned cargo has an ordinary local bid");
        assert!(quote.price_per_ton < offer.purchase_price_per_ton);

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    192,
                    Command::SellCargo {
                        market_revision: loaded.market_revision,
                        cargo_lot_id: lot.cargo_lot_id,
                        quantity_millitons: QUANTITY,
                        buyer_lead_id: 0,
                    },
                ),
            })
            .unwrap();
        let sold = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::Market(snapshot) => snapshot,
            other => panic!("expected market after sale, got {other:?}"),
        };
        let purchase_cost = purchase_cost_credits(offer.purchase_price_per_ton, QUANTITY).unwrap();
        let sale_proceeds = sale_proceeds_credits(quote.price_per_ton, QUANTITY).unwrap();
        assert!(sold.cargo.is_empty());
        assert_eq!(sold.credits, market.credits - purchase_cost + sale_proceeds);
        assert!(sold.credits < market.credits);
    }

    #[test]
    fn authoritative_trader_circuit_persists_market_cargo_and_scheduled_travel() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        const CARGO_QUANTITY: u64 = MILLITONS_PER_TON + 1;

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 201, Command::GetDockedSnapshot),
            })
            .unwrap();
        let docked = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::DockedSnapshot(snapshot) => snapshot,
            other => panic!("expected docked snapshot, got {other:?}"),
        };
        assert!(docked.credits > 0);
        assert_eq!(docked.cargo_used_millitons, 0);
        assert_eq!(docked.fuel_millitons, docked.fuel_capacity_millitons);

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 202, Command::GetKnownDestinations),
            })
            .unwrap();
        let destinations = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::KnownDestinations(snapshot) => snapshot,
            other => panic!("expected Known Universe snapshot, got {other:?}"),
        };
        let destination = destinations
            .systems
            .iter()
            .find(|system| {
                system.within_jump_rating && system.system_id != destinations.current_system_id
            })
            .expect("fixture must contain a known destination in range")
            .system_id;

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    250,
                    Command::PlotCourse {
                        origin_system_id: destinations.current_system_id,
                        destination_system_id: destination,
                        use_current_fuel: true,
                    },
                ),
            })
            .unwrap();
        let course = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::CoursePlot(plot) => plot,
            other => panic!("expected course plot, got {other:?}"),
        };
        assert!(course.fastest.available);
        assert!(course.cheapest.available);
        assert_eq!(
            course.fastest.waypoints.first().unwrap().system_id,
            destinations.current_system_id
        );
        assert_eq!(
            course.fastest.waypoints.last().unwrap().system_id,
            destination
        );
        assert!(course.fastest.elapsed_seconds <= course.cheapest.elapsed_seconds);
        assert!(course.cheapest.fuel_cost_credits <= course.fastest.fuel_cost_credits);
        assert!(course.fastest.waypoints.iter().all(|waypoint| {
            waypoint.next_leg_milliparsecs <= u64::from(course.jump_rating) * 1_000
        }));

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 203, Command::GetMarket),
            })
            .unwrap();
        let market = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::Market(snapshot) => snapshot,
            other => panic!("expected market snapshot, got {other:?}"),
        };
        assert_eq!(market.market_revision, 0);
        assert!(market.offers.len() >= 6);
        let offer = market.offers[0].clone();
        let purchase = request(
            epoch,
            204,
            Command::BuyCargo {
                market_revision: market.market_revision,
                offer_id: offer.offer_id,
                quantity_millitons: CARGO_QUANTITY,
            },
        );
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: purchase.clone(),
            })
            .unwrap();
        let purchased = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::Market(snapshot) => snapshot,
            other => panic!("expected updated market, got {other:?}"),
        };
        assert_eq!(purchased.market_revision, 1);
        assert_eq!(purchased.cargo.len(), 1);
        assert_eq!(purchased.cargo_used_millitons, CARGO_QUANTITY);
        assert_eq!(
            purchased.credits,
            market.credits
                - purchase_cost_credits(offer.purchase_price_per_ton, CARGO_QUANTITY).unwrap()
        );

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: purchase,
            })
            .unwrap();
        let replay = store.process_next().unwrap().unwrap();
        assert!(replay.outcome.replayed);
        let replayed_market = match replay.outcome.kind {
            OutcomeKind::Market(snapshot) => snapshot,
            other => panic!("expected replayed market, got {other:?}"),
        };
        assert_eq!(replayed_market, purchased);

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    205,
                    Command::BuyCargo {
                        market_revision: 0,
                        offer_id: offer.offer_id,
                        quantity_millitons: MILLITONS_PER_TON,
                    },
                ),
            })
            .unwrap();
        assert!(matches!(
            store.process_next().unwrap().unwrap().outcome.kind,
            OutcomeKind::Error {
                code: ErrorCode::InvalidCommand,
                ..
            }
        ));

        let voyage = request(
            epoch,
            206,
            Command::BeginVoyage {
                destination_system_id: destination,
            },
        );
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: voyage.clone(),
            })
            .unwrap();
        let departing = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::TravelStatus(snapshot) => snapshot,
            other => panic!("expected departing status, got {other:?}"),
        };
        assert_eq!(
            store.player_phase(&identity()).unwrap(),
            PlayerPhase::Interplanetary
        );
        assert!(departing.due_second >= 12 * 60 * 60);
        assert_ne!(departing.plan_id, 0);
        assert_eq!(departing.plan_revision, 1);
        assert_eq!(departing.leg_index, 0);
        assert!(matches!(departing.origin, FlightLocus::Port { .. }));
        assert!(matches!(
            departing.destination,
            FlightLocus::JumpLocus { .. }
        ));
        let fuel_before_jump = departing.current_fuel_millitons;
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: voyage,
            })
            .unwrap();
        let voyage_replay = store.process_next().unwrap().unwrap();
        assert!(voyage_replay.outcome.replayed);
        assert_eq!(
            voyage_replay.outcome.kind,
            OutcomeKind::TravelStatus(departing.clone())
        );

        // Encounters are covered independently.  Keep this end-to-end test
        // focused on the authoritative trade, cargo, and voyage circuit.
        let mut txn = store.env.write_txn().unwrap();
        store.contact_events.clear(&mut txn).unwrap();
        txn.commit().unwrap();

        let first = store.advance_simulation_to(departing.due_second).unwrap();
        assert_eq!(first.player_travel_events, 1);
        assert_eq!(first.player_transitions.len(), 1);
        assert_eq!(first.player_transitions[0].identity, identity());
        assert_eq!(first.player_transitions[0].phase, PlayerPhase::Jump);
        let jump = store
            .travel_status_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        assert_eq!(first.player_transitions[0].status, jump);
        assert_eq!(store.player_phase(&identity()).unwrap(), PlayerPhase::Jump);
        assert_eq!(jump.plan_id, departing.plan_id);
        assert_eq!(jump.plan_revision, departing.plan_revision);
        assert_eq!(jump.leg_index, 1);
        assert!(matches!(jump.origin, FlightLocus::JumpLocus { .. }));
        assert!(matches!(jump.destination, FlightLocus::JumpLocus { .. }));
        assert!(jump.current_fuel_millitons < fuel_before_jump);
        assert!(fuel_before_jump - jump.current_fuel_millitons <= jump.jump_fuel_millitons);

        let second = store.advance_simulation_to(jump.due_second).unwrap();
        assert_eq!(second.player_travel_events, 1);
        assert_eq!(second.player_transitions.len(), 1);
        assert_eq!(
            second.player_transitions[0].phase,
            PlayerPhase::Interplanetary
        );
        let inbound = store
            .travel_status_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        assert_eq!(second.player_transitions[0].status, inbound);
        assert_eq!(
            store.player_phase(&identity()).unwrap(),
            PlayerPhase::Interplanetary
        );
        assert_eq!(inbound.plan_id, departing.plan_id);
        assert_eq!(inbound.plan_revision, departing.plan_revision);
        assert_eq!(inbound.leg_index, 2);
        assert!(matches!(inbound.origin, FlightLocus::JumpLocus { .. }));
        assert!(matches!(inbound.destination, FlightLocus::Port { .. }));
        assert!(inbound.due_second >= jump.due_second + 12 * 60 * 60);

        let third = store.advance_simulation_to(inbound.due_second).unwrap();
        assert_eq!(third.player_travel_events, 1);
        assert_eq!(third.player_transitions.len(), 1);
        assert_eq!(
            third.player_transitions[0].phase,
            PlayerPhase::Interplanetary
        );
        assert_eq!(
            third.player_transitions[0].status.stage,
            TravelStage::Holding
        );
        let checkpoint = store.pending_checkpoint(&identity()).unwrap().unwrap();
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    220,
                    Command::AcknowledgeCheckpoint {
                        checkpoint_id: checkpoint.checkpoint_id,
                    },
                ),
            })
            .unwrap();
        store.process_next().unwrap().unwrap();
        if store.player_phase(&identity()).unwrap() == PlayerPhase::Encounter {
            let encounter = store.pending_encounter(&identity()).unwrap().unwrap();
            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: request(
                        epoch,
                        221,
                        Command::ResolveEncounter(crate::wire::ResolveEncounterRequest {
                            encounter_id: encounter.encounter_id,
                            expected_revision: encounter.revision,
                            posture: EncounterPosture::Comply,
                            fallbacks: vec![EncounterFallback::Surrender],
                        }),
                    ),
                })
                .unwrap();
            store.process_next().unwrap().unwrap();
            store
                .advance_simulation_to(encounter.started_second + 1_000)
                .unwrap();
        }
        assert_eq!(
            store.player_phase(&identity()).unwrap(),
            PlayerPhase::Docked
        );
        let player = store.player_record(&identity()).unwrap().unwrap();
        let arrived_ship = store.ship_record(player.ship_id).unwrap().unwrap();
        assert_eq!(arrived_ship.system_id, destination);
        assert_eq!(arrived_ship.cargo.len(), 1);

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 207, Command::GetMarket),
            })
            .unwrap();
        let destination_market = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::Market(snapshot) => snapshot,
            other => panic!("expected destination market, got {other:?}"),
        };
        let carried_lot = destination_market.cargo[0].clone();
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    208,
                    Command::SellCargo {
                        market_revision: destination_market.market_revision,
                        cargo_lot_id: carried_lot.cargo_lot_id,
                        quantity_millitons: CARGO_QUANTITY,
                        buyer_lead_id: 0,
                    },
                ),
            })
            .unwrap();
        let sold = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::Market(snapshot) => snapshot,
            other => panic!("expected market after sale, got {other:?}"),
        };
        assert!(sold.cargo.is_empty());
        assert_eq!(sold.cargo_used_millitons, 0);
        assert!(sold.credits > destination_market.credits);
    }

    #[test]
    fn player_mail_custody_arrival_readership_and_stipend_survive_restart() {
        let dir = TempDir::new().unwrap();
        let (epoch, destination, departing, cargo_lot_id, message_id);
        {
            let store = Store::open(dir.path()).unwrap();
            epoch = initialize_player_fixture(&store);
            let known = store
                .known_destinations_in(&store.env.read_txn().unwrap(), &identity())
                .unwrap();
            destination = known
                .systems
                .iter()
                .find(|system| {
                    system.within_jump_rating && system.system_id != known.current_system_id
                })
                .unwrap()
                .system_id;

            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: request(epoch, 210, Command::GetMarket),
                })
                .unwrap();
            let market = match store.process_next().unwrap().unwrap().outcome.kind {
                OutcomeKind::Market(snapshot) => snapshot,
                other => panic!("expected market, got {other:?}"),
            };
            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: request(
                        epoch,
                        211,
                        Command::BuyCargo {
                            market_revision: market.market_revision,
                            offer_id: market.offers[0].offer_id,
                            quantity_millitons: MILLITONS_PER_TON,
                        },
                    ),
                })
                .unwrap();
            let loaded = match store.process_next().unwrap().unwrap().outcome.kind {
                OutcomeKind::Market(snapshot) => snapshot,
                other => panic!("expected loaded market, got {other:?}"),
            };
            cargo_lot_id = loaded.cargo[0].cargo_lot_id;

            let proposal = FlightPlanProposal {
                expected_plan_revision: 0,
                steps: vec![
                    FlightPlanStep {
                        locus: FlightLocus::JumpLocus {
                            system_id: known.current_system_id,
                        },
                        authority: WaypointAuthority::Through,
                        action: FlightPlanAction::Jump {
                            destination_system_id: destination,
                            navigation: crate::wire::JumpNavigationMethod::CommercialTape,
                            proceed_on_known_bad_plot: false,
                        },
                        terminal: false,
                    },
                    FlightPlanStep {
                        locus: FlightLocus::Port {
                            system_id: destination,
                            world_id: destination,
                            facility_id: destination,
                        },
                        authority: WaypointAuthority::Hold,
                        action: FlightPlanAction::Dock {
                            world_id: destination,
                            facility_id: destination,
                        },
                        terminal: true,
                    },
                ],
                policy: EncounterPolicy::default(),
            };
            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: request(epoch, 212, Command::PreviewFlightPlan(proposal.clone())),
                })
                .unwrap();
            let preview = match store.process_next().unwrap().unwrap().outcome.kind {
                OutcomeKind::FlightPlanPreview(preview) => preview,
                other => panic!("expected flight-plan preview, got {other:?}"),
            };
            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: request(
                        epoch,
                        217,
                        Command::CommitFlightPlan(CommitFlightPlanRequest {
                            proposal,
                            preview_hash: preview.preview_hash,
                            acknowledge_warnings: true,
                        }),
                    ),
                })
                .unwrap();
            assert!(matches!(
                store.process_next().unwrap().unwrap().outcome.kind,
                OutcomeKind::FlightPlan(_)
            ));
            departing = store
                .travel_status_in(&store.env.read_txn().unwrap(), &identity())
                .unwrap();
            store
                .advance_simulation_to(departing.due_second - 1)
                .unwrap();
            let mut txn = store.env.write_txn().unwrap();
            (message_id, _) = store
                .simulation
                .dispatch_message(
                    &mut txn,
                    departing.due_second - 1,
                    departing.current_system_id,
                    crate::simulation::MessageClass::PublicService,
                    crate::simulation::MessageImportance::Notable,
                    "Delayed route test notice",
                    "A complete delayed-route test article.",
                    &[destination],
                )
                .unwrap();
            let (claim_message_id, _) = store
                .simulation
                .dispatch_message(
                    &mut txn,
                    departing.due_second - 1,
                    departing.current_system_id,
                    crate::simulation::MessageClass::Private,
                    crate::simulation::MessageImportance::Important,
                    "Sender-retained fixture claim",
                    "The captain retains this signed filing while carrying mail.",
                    &[],
                )
                .unwrap();
            let offer_id = 98_001;
            let task_id = 98_101;
            let mut offer = test_task_offer(
                offer_id,
                destination,
                destination,
                crate::wire::TaskKind::Freight,
            );
            offer.expires_second = 100 * crate::simulation::SECONDS_PER_DAY;
            offer.delivery_deadline_second = 200 * crate::simulation::SECONDS_PER_DAY;
            store
                .task_offers
                .put(
                    &mut txn,
                    &offer_id.to_be_bytes(),
                    &encode_stored_task_offer(&StoredTaskOffer {
                        offer: offer.clone(),
                        claimed_by: None,
                        claimed_task_id: 0,
                        closure_message_id: 0,
                    })
                    .unwrap(),
                )
                .unwrap();
            let mut claim = test_task(identity(), task_id, offer, claim_message_id);
            claim.task.performing_ship_id = store
                .player_and_ship_in(&txn, &identity())
                .unwrap()
                .1
                .ship_id;
            store
                .tasks
                .put(
                    &mut txn,
                    &task_id.to_be_bytes(),
                    &encode_stored_task(&claim).unwrap(),
                )
                .unwrap();
            // This fixture proves electronic-mail bundle custody and payment. A
            // terminal contact would correctly wait for the captain and is
            // tested by the encounter/flight-plan fixtures instead.
            store.contact_events.clear(&mut txn).unwrap();
            txn.commit().unwrap();
        }

        let (mailbag_id, carrier_leg_id, stipend, jump_due, credits_before);
        {
            let store = Store::open(dir.path()).unwrap();
            let player_before = store.player_record(&identity()).unwrap().unwrap();
            credits_before = player_before.credits;
            let advanced = store.advance_simulation_to(departing.due_second).unwrap();
            assert_eq!(advanced.player_travel_events, 1);
            let player = store.player_record(&identity()).unwrap().unwrap();
            let ship = store.ship_record(player.ship_id).unwrap().unwrap();
            assert!(
                ship.cargo
                    .iter()
                    .any(|lot| lot.cargo_lot_id == cargo_lot_id)
            );
            let custody = ship
                .mail_custody
                .clone()
                .expect("player must take the queued bag");
            mailbag_id = custody.mailbag_id;
            carrier_leg_id = custody.carrier_leg_id;
            stipend = custody.advertised_stipend_credits;
            assert_eq!(stipend, 100 + u64::from(custody.envelope_count));
            let bag = store
                .simulation
                .mailbag(&store.env.read_txn().unwrap(), mailbag_id)
                .unwrap();
            assert!(bag.envelope_ids.iter().any(|_| true));
            assert_eq!(bag.delivered_second, None);
            jump_due = match ship.location {
                ShipLocationRecord::InFlight(FlightLegRecord {
                    due_second,
                    purpose: FlightLegPurpose::Jump { .. },
                    ..
                }) => due_second,
                other => panic!("expected jump custody, got {other:?}"),
            };
        }

        {
            let store = Store::open(dir.path()).unwrap();
            let player = store.player_record(&identity()).unwrap().unwrap();
            let ship = store.ship_record(player.ship_id).unwrap().unwrap();
            assert_eq!(ship.mail_custody.as_ref().unwrap().mailbag_id, mailbag_id);
            let leg = store
                .simulation
                .player_carrier_leg(&store.env.read_txn().unwrap(), carrier_leg_id)
                .unwrap();
            assert_eq!(leg.delivered_second, None);

            store.advance_simulation_to(jump_due - 1).unwrap();
            let mut txn = store.env.write_txn().unwrap();
            let (newer_local_message_id, _) = store
                .simulation
                .dispatch_message(
                    &mut txn,
                    jump_due - 1,
                    destination,
                    crate::simulation::MessageClass::AgencyNews,
                    crate::simulation::MessageImportance::Notable,
                    "Newer destination bulletin",
                    "A complete newer local bulletin.",
                    &[],
                )
                .unwrap();
            txn.commit().unwrap();
            store.advance_simulation_to(jump_due).unwrap();
            let carried_claim = decode_stored_task(
                store
                    .tasks
                    .get(&store.env.read_txn().unwrap(), &98_101_u64.to_be_bytes())
                    .unwrap()
                    .unwrap(),
            )
            .unwrap();
            assert_ne!(
                carried_claim.task.result_message_id, 0,
                "the issuing office must process a claim in the captain's delivered mailbag"
            );
            let player = store.player_record(&identity()).unwrap().unwrap();
            assert_eq!(player.credits, credits_before + stipend);
            let ship = store.ship_record(player.ship_id).unwrap().unwrap();
            assert!(ship.mail_custody.is_none());
            assert_eq!(
                store.player_phase(&identity()).unwrap(),
                PlayerPhase::Interplanetary,
                "arrival mail must be readable at breakout before docking"
            );
            assert!(
                ship.cargo
                    .iter()
                    .any(|lot| lot.cargo_lot_id == cargo_lot_id)
            );
            let leg = store
                .simulation
                .player_carrier_leg(&store.env.read_txn().unwrap(), carrier_leg_id)
                .unwrap();
            assert_eq!(leg.delivered_second, Some(jump_due));
            assert_eq!(leg.paid_second, Some(jump_due));

            let mut txn = store.env.write_txn().unwrap();
            let duplicate = store
                .simulation
                .handoff_player_mail(
                    &mut txn,
                    ship.ship_id,
                    mailbag_id,
                    carrier_leg_id,
                    destination,
                    jump_due,
                )
                .unwrap();
            assert_eq!(duplicate.stipend_credits, 0);
            txn.abort();

            let open = request(epoch, 213, Command::OpenArrivalPacket);
            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: open.clone(),
                })
                .unwrap();
            let packet = match store.process_next().unwrap().unwrap().outcome.kind {
                OutcomeKind::ArrivalPacket(packet) => packet,
                other => panic!("expected arrival packet, got {other:?}"),
            };
            assert!(packet.new_arrival);
            assert_eq!(packet.mailbag_id, Some(mailbag_id));
            assert_eq!(packet.stipend_credits, stipend);
            let item = packet
                .items
                .iter()
                .find(|item| item.message_id == message_id)
                .expect("carried message must appear in the destination packet");
            assert_eq!(item.created_second, departing.due_second - 1);
            assert_eq!(item.available_second, jump_due);
            assert!(item.available_second > item.created_second);
            let newer_local = packet
                .items
                .iter()
                .find(|item| item.message_id == newer_local_message_id)
                .expect("newer local information must coexist with delayed mail");
            assert!(newer_local.created_second > item.created_second);
            assert_eq!(newer_local.available_second, newer_local.created_second);
            assert_eq!(packet.mapping_status.state, SystemMappingState::KnownPublic);

            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: open,
                })
                .unwrap();
            let replay = store.process_next().unwrap().unwrap();
            assert!(replay.outcome.replayed);
            assert_eq!(
                replay.outcome.kind,
                OutcomeKind::ArrivalPacket(packet.clone())
            );

            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: request(epoch, 214, Command::OpenArrivalPacket),
                })
                .unwrap();
            let repeated = match store.process_next().unwrap().unwrap().outcome.kind {
                OutcomeKind::ArrivalPacket(packet) => packet,
                other => panic!("expected repeated arrival packet, got {other:?}"),
            };
            assert!(!repeated.new_arrival);
            assert!(repeated.items.is_empty());

            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: request(
                        epoch,
                        215,
                        Command::SetMessageClassification {
                            message_id,
                            classification: MessageClassification::ReviewLater,
                        },
                    ),
                })
                .unwrap();
            assert!(matches!(
                store.process_next().unwrap().unwrap().outcome.kind,
                OutcomeKind::MessageManagement(_)
            ));
            assert_eq!(
                store.audit_mail_custody().unwrap(),
                store.simulation_report().unwrap().carrier_legs
            );
        }

        let reopened = Store::open(dir.path()).unwrap();
        reopened
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 216, Command::GetMessageManagement),
            })
            .unwrap();
        let messages = match reopened.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::MessageManagement(snapshot) => snapshot,
            other => panic!("expected retained messages, got {other:?}"),
        };
        assert_eq!(
            messages
                .items
                .iter()
                .find(|item| item.message_id == message_id)
                .unwrap()
                .classification,
            MessageClassification::ReviewLater
        );
        assert_eq!(
            reopened
                .player_record(&identity())
                .unwrap()
                .unwrap()
                .credits,
            credits_before + stipend
        );
    }

    #[test]
    fn mapping_disclosure_is_durable_and_dispatches_through_store_and_forward_mail() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let ship = store.ship_record(player.ship_id).unwrap().unwrap();
        let key = player_system_mapping_key(&identity(), ship.system_id);
        let mut txn = store.env.write_txn().unwrap();
        store.player_system_mappings.delete(&mut txn, &key).unwrap();
        let arrival_key = encode_identity(&identity());
        let mut arrival = store
            .player_arrivals
            .get(&txn, &arrival_key)
            .unwrap()
            .map(decode_player_arrival)
            .transpose()
            .unwrap()
            .unwrap();
        arrival.presented = true;
        store
            .player_arrivals
            .put(&mut txn, &arrival_key, &encode_player_arrival(&arrival))
            .unwrap();
        txn.commit().unwrap();

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 220, Command::OpenArrivalPacket),
            })
            .unwrap();
        let packet = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::ArrivalPacket(packet) => packet,
            other => panic!("expected arrival packet, got {other:?}"),
        };
        assert_eq!(packet.mapping_status.state, SystemMappingState::Unresolved);

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    221,
                    Command::SetSystemMappingDisclosure {
                        system_id: ship.system_id,
                        choice: SystemMappingChoice::WithholdSecret,
                    },
                ),
            })
            .unwrap();
        let secret = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::SystemMappingStatus(status) => status,
            other => panic!("expected mapping status, got {other:?}"),
        };
        assert_eq!(secret.state, SystemMappingState::Secret);
        assert_eq!(secret.dispatch_message_id, None);

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    222,
                    Command::SetSystemMappingDisclosure {
                        system_id: ship.system_id,
                        choice: SystemMappingChoice::PublicNotification,
                    },
                ),
            })
            .unwrap();
        let published = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::SystemMappingStatus(status) => status,
            other => panic!("expected mapping status, got {other:?}"),
        };
        assert_eq!(published.state, SystemMappingState::PublicDispatched);
        let message_id = published.dispatch_message_id.unwrap();
        let message = store
            .simulation
            .message(&store.env.read_txn().unwrap(), message_id)
            .unwrap();
        assert_eq!(
            message.class,
            crate::simulation::MessageClass::PublicService
        );
        assert!(store.simulation_report().unwrap().envelopes_waiting > 0);

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    223,
                    Command::SetSystemMappingDisclosure {
                        system_id: ship.system_id,
                        choice: SystemMappingChoice::Withhold,
                    },
                ),
            })
            .unwrap();
        assert!(matches!(
            store.process_next().unwrap().unwrap().outcome.kind,
            OutcomeKind::Error {
                code: ErrorCode::InvalidCommand,
                ..
            }
        ));
        drop(store);

        let reopened = Store::open(dir.path()).unwrap();
        let status = reopened
            .system_mapping_status_in(
                &reopened.env.read_txn().unwrap(),
                &identity(),
                ship.system_id,
            )
            .unwrap();
        assert_eq!(status, published);
    }

    #[test]
    fn direct_mapping_filing_creates_private_mail_bound_for_earth() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
        let route_origin = store
            .simulation_systems()
            .unwrap()
            .into_iter()
            .find(|system| {
                system.system_id != SOL_SYSTEM_ID
                    && store
                        .simulation
                        .route_exists(
                            &store.env.read_txn().unwrap(),
                            system.system_id,
                            SOL_SYSTEM_ID,
                        )
                        .unwrap()
            })
            .unwrap()
            .system_id;
        ship.system_id = route_origin;
        ship.location = ShipLocationRecord::Docked {
            world_id: route_origin,
            facility_id: route_origin,
            arrived_second: store.game_second().unwrap(),
        };
        let mut txn = store.env.write_txn().unwrap();
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        store
            .player_system_mappings
            .delete(
                &mut txn,
                &player_system_mapping_key(&identity(), ship.system_id),
            )
            .unwrap();
        txn.commit().unwrap();

        let before = store.simulation_report().unwrap();
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    224,
                    Command::SetSystemMappingDisclosure {
                        system_id: ship.system_id,
                        choice: SystemMappingChoice::DirectEarth,
                    },
                ),
            })
            .unwrap();
        let filed = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::SystemMappingStatus(status) => status,
            other => panic!("expected mapping status, got {other:?}"),
        };
        assert_eq!(filed.state, SystemMappingState::DirectDispatched);
        let message = store
            .simulation
            .message(
                &store.env.read_txn().unwrap(),
                filed.dispatch_message_id.unwrap(),
            )
            .unwrap();
        assert_eq!(message.class, crate::simulation::MessageClass::Private);
        let after = store.simulation_report().unwrap();
        assert_eq!(after.message_count(), before.message_count() + 1);
        assert_eq!(after.envelopes_waiting, before.envelopes_waiting + 1);
    }

    #[test]
    fn first_settled_discovery_filing_is_adjudicated_and_paid_at_earth() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let claim_system = store
            .stellar_systems()
            .unwrap()
            .into_iter()
            .find(|system| {
                system.id != SOL_SYSTEM_ID
                    && derive_primary_world(system).is_ok_and(|world| world.is_inhabited())
            })
            .unwrap();
        let before = store
            .finances
            .get(
                &store.env.read_txn().unwrap(),
                &ship_finance_key(player.ship_id),
            )
            .unwrap()
            .map(decode_finance_record)
            .transpose()
            .unwrap()
            .unwrap()
            .restricted_credits;
        let message_id = {
            let mut txn = store.env.write_txn().unwrap();
            let (message_id, _) = store
                .simulation
                .dispatch_message(
                    &mut txn,
                    1,
                    SOL_SYSTEM_ID,
                    crate::simulation::MessageClass::Private,
                    crate::simulation::MessageImportance::Important,
                    "Test sealed discovery filing",
                    "Authenticated test filing",
                    &[SOL_SYSTEM_ID],
                )
                .unwrap();
            store
                .discovery_claims
                .put(
                    &mut txn,
                    &message_id,
                    &encode_discovery_claim(&DiscoveryClaimRecord {
                        message_id,
                        system_id: claim_system.id,
                        claimant: identity(),
                        reached_earth_second: None,
                        awarded: false,
                        result_message_id: 0,
                    }),
                )
                .unwrap();
            store
                .process_discovery_mail_arrival_in(&mut txn, SOL_SYSTEM_ID, 1)
                .unwrap();
            txn.commit().unwrap();
            message_id
        };
        let txn = store.env.read_txn().unwrap();
        let claim = decode_discovery_claim(
            store
                .discovery_claims
                .get(&txn, &message_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert!(claim.awarded);
        assert_eq!(claim.reached_earth_second, Some(1));
        assert_ne!(claim.result_message_id, 0);
        let result_message = store
            .simulation
            .message(&txn, claim.result_message_id)
            .unwrap();
        let result_item = store
            .message_item_in(
                &txn,
                &identity(),
                &result_message,
                1,
                MessageClassification::Unreviewed,
                false,
                SOL_SYSTEM_ID,
                1,
            )
            .unwrap();
        assert_eq!(
            result_item.action_kind,
            crate::wire::MessageActionKind::ReviewMapping
        );
        assert_eq!(result_item.action_reference_id, claim.system_id);
        let finance = decode_finance_record(
            store
                .finances
                .get(&txn, &ship_finance_key(player.ship_id))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(
            finance.restricted_credits,
            before + FEDERATION_DISCOVERY_AWARD_CREDITS
        );
    }

    #[test]
    fn proper_repair_is_durable_and_completes_exactly_once() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
        let subsystem = ship
            .subsystems
            .iter_mut()
            .find(|subsystem| subsystem.maximum_hits > 1)
            .unwrap();
        subsystem.sustained_hits = 1;
        subsystem.battlefield_repair_hits = 1;
        let subsystem_id = subsystem.subsystem_id;
        let mut txn = store.env.write_txn().unwrap();
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        txn.commit().unwrap();
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    240,
                    Command::CommitDockedService(crate::wire::DockedServiceOrder {
                        expected_ship_revision: ship.revision,
                        kind: DockedServiceOrderKind::ProperRepair { subsystem_id },
                    }),
                ),
            })
            .unwrap();
        let scheduled = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::DockedServiceReceipt(receipt) => receipt.ship_status,
            other => panic!("expected docked-service receipt, got {other:?}"),
        };
        let activity = scheduled.active_activity.as_ref().unwrap();
        assert!(matches!(
            activity.kind,
            WireShipActivityKind::ProperRepair {
                subsystem_id: actual
            } if actual == subsystem_id
        ));
        assert_eq!(activity.due_second, crate::ship_condition::SECONDS_PER_DAY);
        let persisted = store.ship_record(player.ship_id).unwrap().unwrap();
        assert!(matches!(
            persisted.activity.unwrap().site,
            ShipActivitySite::Dockyard {
                system_id,
                world_id,
                facility_id
            } if system_id == persisted.system_id
                && world_id == persisted.system_id
                && facility_id == persisted.system_id
        ));

        let first = store.advance_simulation_to(activity.due_second).unwrap();
        assert_eq!(first.ship_activity_events, 1);
        let repaired = store.ship_record(player.ship_id).unwrap().unwrap();
        let subsystem = repaired
            .subsystems
            .iter()
            .find(|subsystem| subsystem.subsystem_id == subsystem_id)
            .unwrap();
        assert_eq!(subsystem.sustained_hits, 0);
        assert_eq!(subsystem.battlefield_repair_hits, 0);
        assert_eq!(subsystem.last_proper_repair_second, activity.due_second);
        assert!(repaired.activity.is_none());
        let second = store.advance_simulation_to(activity.due_second).unwrap();
        assert_eq!(second.ship_activity_events, 0);

        drop(store);
        let reopened = Store::open(dir.path()).unwrap();
        assert!(
            reopened
                .ship_record(player.ship_id)
                .unwrap()
                .unwrap()
                .activity
                .is_none()
        );
    }

    #[test]
    fn quoted_refit_duration_and_completion_scope_are_durable() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let mut player = store.player_record(&identity()).unwrap().unwrap();
        let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
        player.credits = u64::MAX / 4;

        let repairable_index = ship
            .subsystems
            .iter()
            .position(|subsystem| subsystem.maximum_hits > 1)
            .unwrap();
        let destroyed_index = ship
            .subsystems
            .iter()
            .enumerate()
            .find(|(index, subsystem)| *index != repairable_index && subsystem.maximum_hits > 0)
            .map(|(index, _)| index)
            .unwrap();
        ship.subsystems[repairable_index].sustained_hits = 1;
        ship.subsystems[repairable_index].battlefield_repair_hits = 1;
        ship.subsystems[repairable_index].neglect_damage_hits = 1;
        ship.subsystems[repairable_index].installed_second = 7;
        ship.subsystems[repairable_index].calendar_age_months = 17;
        ship.subsystems[repairable_index].operating_seconds = 12_345;
        ship.subsystems[repairable_index].duty_cycles = 9;
        ship.subsystems[repairable_index].skimming_cycles = 3;
        ship.subsystems[destroyed_index].sustained_hits =
            ship.subsystems[destroyed_index].maximum_hits;
        ship.subsystems[destroyed_index].battlefield_repair_hits = 1;
        let repairable_id = ship.subsystems[repairable_index].subsystem_id;
        let destroyed_id = ship.subsystems[destroyed_index].subsystem_id;
        let retained_installation = ship.subsystems[repairable_index].clone();
        let destroyed_installation = ship.subsystems[destroyed_index].clone();
        ship.latent_quirks.push(ShipQuirkRecord {
            quirk_id: 900,
            subsystem_id: repairable_id,
            kind: ShipQuirkKind::TemperatureFault,
            attached_second: 0,
            manifested: false,
            warranty_claimed: false,
        });
        ship.latent_quirks.push(ShipQuirkRecord {
            quirk_id: 901,
            subsystem_id: destroyed_id,
            kind: ShipQuirkKind::JumpDriveDefect,
            attached_second: 0,
            manifested: false,
            warranty_claimed: false,
        });
        let completed_before = ship.maintenance.completed_refits;
        let mut txn = store.env.write_txn().unwrap();
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity()),
                &encode_player_record(&player),
            )
            .unwrap();
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        txn.commit().unwrap();

        let quote = {
            let txn = store.env.read_txn().unwrap();
            store.docked_services_in(&txn, &identity()).unwrap()
        };
        assert!(quote.refit_available);
        let order = crate::wire::DockedServiceOrder {
            expected_ship_revision: quote.ship_revision,
            kind: DockedServiceOrderKind::Refit,
        };
        let mut txn = store.env.write_txn().unwrap();
        let RuleResult::Applied(scheduled) = store
            .commit_docked_service_in(&mut txn, &identity(), &order)
            .unwrap()
        else {
            panic!("refit rejected")
        };
        txn.commit().unwrap();
        assert!(scheduled.ship_status.active_activity.is_some());
        let activity = store
            .ship_record(ship.ship_id)
            .unwrap()
            .unwrap()
            .activity
            .unwrap();
        assert_eq!(
            activity.due_second - activity.started_second,
            quote.refit_service_seconds
        );

        let mut txn = store.env.write_txn().unwrap();
        store
            .process_ship_activity_in(&mut txn, activity.due_second, ship.ship_id)
            .unwrap();
        txn.commit().unwrap();
        let refitted = store.ship_record(ship.ship_id).unwrap().unwrap();
        let repairable = &refitted.subsystems[repairable_index];
        assert_eq!(repairable.sustained_hits, 0);
        assert_eq!(repairable.battlefield_repair_hits, 0);
        assert_eq!(repairable.neglect_damage_hits, 0);
        assert_eq!(
            repairable.installed_second,
            retained_installation.installed_second
        );
        assert_eq!(
            repairable.calendar_age_months,
            retained_installation.calendar_age_months
        );
        assert_eq!(
            repairable.operating_seconds,
            retained_installation.operating_seconds
        );
        assert_eq!(repairable.duty_cycles, retained_installation.duty_cycles);
        assert_eq!(
            repairable.skimming_cycles,
            retained_installation.skimming_cycles
        );
        let destroyed = &refitted.subsystems[destroyed_index];
        assert_eq!(destroyed.sustained_hits, destroyed.maximum_hits);
        assert_eq!(destroyed.battlefield_repair_hits, 0);
        assert_eq!(
            destroyed.installed_second,
            destroyed_installation.installed_second
        );
        assert_eq!(
            destroyed.installation_generation,
            destroyed_installation.installation_generation
        );
        assert_eq!(refitted.maintenance.completed_refits, completed_before + 1);
        assert!(refitted.activity.is_none());
        assert!(
            !refitted
                .latent_quirks
                .iter()
                .any(|quirk| quirk.quirk_id == 900)
        );
        assert!(
            refitted
                .latent_quirks
                .iter()
                .any(|quirk| quirk.quirk_id == 901)
        );
    }

    #[test]
    fn weekly_training_progresses_while_the_crew_remains_on_watch() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let _epoch = initialize_player_fixture(&store);
        let roster = store
            .crew_management_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        let member = roster
            .members
            .iter()
            .find(|member| !member.captain && !member.assigned_slot_ids.is_empty())
            .unwrap();
        let before = member.person.training;
        let advance = store
            .advance_simulation_to(crate::ship_condition::SECONDS_PER_WEEK)
            .unwrap();
        assert!(advance.person_training_events >= roster.members.len() as u64);
        let after = store.person_record(member.person_id).unwrap().unwrap();
        assert_eq!(after.person.training.skill, before.skill);
        assert_eq!(
            after.person.training.current_weeks,
            before.current_weeks + 1
        );
    }

    #[test]
    fn shore_leave_remains_at_its_real_berth_until_the_ship_returns() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let identity = identity();
        let (player, mut ship) = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &identity)
            .unwrap();
        let roster = store
            .crew_management_in(&store.env.read_txn().unwrap(), &identity)
            .unwrap();
        let member = roster
            .members
            .iter()
            .find(|member| !member.captain)
            .unwrap();
        let origin_system_id = ship.system_id;
        let origin_facility_id = match ship.location {
            ShipLocationRecord::Docked { facility_id, .. } => facility_id,
            _ => panic!("fixture ship is not docked"),
        };
        let mut txn = store.env.write_txn().unwrap();
        let RuleResult::Applied(_) = store
            .apply_personnel_action_in(
                &mut txn,
                &identity,
                member.person_id,
                member.service_revision,
                crate::wire::PersonnelActionKind::ShoreLeave,
                0,
                1,
            )
            .unwrap()
        else {
            panic!("shore leave was rejected")
        };
        ship.system_id = 2;
        ship.location = ShipLocationRecord::Docked {
            world_id: 2,
            facility_id: 2,
            arrived_second: 1,
        };
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        store
            .process_person_recovery_day_in(
                &mut txn,
                origin_system_id,
                crate::simulation::SECONDS_PER_DAY,
            )
            .unwrap();
        let service = decode_crew_service(
            store
                .crew_services
                .get(&txn, &member.person_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(service.availability, CrewAvailability::AwaitingRecall);
        assert_eq!(service.shore_system_id, origin_system_id);
        assert_eq!(service.shore_facility_id, origin_facility_id);
        assert!(matches!(
            store
                .apply_personnel_action_in(
                    &mut txn,
                    &identity,
                    member.person_id,
                    service.revision,
                    crate::wire::PersonnelActionKind::Recall,
                    0,
                    0,
                )
                .unwrap(),
            RuleResult::Rejected(_)
        ));
        let persisted_player = decode_player_record(
            store
                .players
                .get(&txn, &encode_identity(&identity))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(persisted_player.ship_id, player.ship_id);
        txn.commit().unwrap();
    }

    #[test]
    fn personnel_transfer_and_discharge_change_the_persisted_service_roster() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let identity = identity();
        let roster = store
            .crew_management_in(&store.env.read_txn().unwrap(), &identity)
            .unwrap();
        let mut ordinary = roster.members.iter().filter(|member| !member.captain);
        let transferred = ordinary.next().unwrap().clone();
        let discharged = ordinary.next().unwrap().clone();
        let mut txn = store.env.write_txn().unwrap();
        let mut player = decode_player_record(
            store
                .players
                .get(&txn, &encode_identity(&identity))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        player.credits = u64::MAX / 4;
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity),
                &encode_player_record(&player),
            )
            .unwrap();
        let offer = store
            .ship_market_in(&txn, &identity)
            .unwrap()
            .offers
            .into_iter()
            .next()
            .unwrap();
        assert!(matches!(
            store
                .purchase_ship_in(&mut txn, &identity, offer.offer_id, false)
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let player = decode_player_record(
            store
                .players
                .get(&txn, &encode_identity(&identity))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        let receiving_ship_id = *player
            .managed_ship_ids
            .iter()
            .find(|ship_id| **ship_id != player.ship_id)
            .unwrap();
        assert!(matches!(
            store
                .apply_personnel_action_in(
                    &mut txn,
                    &identity,
                    transferred.person_id,
                    transferred.service_revision,
                    crate::wire::PersonnelActionKind::Transfer,
                    receiving_ship_id,
                    0,
                )
                .unwrap(),
            RuleResult::Applied(_)
        ));
        assert!(matches!(
            store
                .apply_personnel_action_in(
                    &mut txn,
                    &identity,
                    discharged.person_id,
                    discharged.service_revision,
                    crate::wire::PersonnelActionKind::Dismiss,
                    0,
                    0,
                )
                .unwrap(),
            RuleResult::Applied(_)
        ));
        txn.commit().unwrap();
        drop(store);

        let reopened = Store::open(dir.path()).unwrap();
        let txn = reopened.env.read_txn().unwrap();
        let transferred_service = decode_crew_service(
            reopened
                .crew_services
                .get(&txn, &transferred.person_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(transferred_service.ship_id, receiving_ship_id);
        assert!(transferred_service.assigned_slot_ids.is_empty());
        let discharged_service = decode_crew_service(
            reopened
                .crew_services
                .get(&txn, &discharged.person_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(discharged_service.availability, CrewAvailability::Detached);
    }

    #[test]
    fn surgery_changes_condition_only_when_its_queued_hours_complete() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let identity = identity();
        let player = store.player_record(&identity).unwrap().unwrap();
        let roster = store
            .crew_management_in(&store.env.read_txn().unwrap(), &identity)
            .unwrap();
        let medic = roster
            .members
            .iter()
            .find(|member| !member.captain)
            .unwrap();
        let captain = roster.members.iter().find(|member| member.captain).unwrap();
        let mut txn = store.env.write_txn().unwrap();
        let mut medic_service = decode_crew_service(
            store
                .crew_services
                .get(&txn, &medic.person_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        medic_service.role = "medic".into();
        medic_service.assigned_slot_ids = vec![medic_service.slot_id];
        store
            .crew_services
            .put(
                &mut txn,
                &medic.person_id,
                &encode_crew_service(&medic_service).unwrap(),
            )
            .unwrap();
        let mut medic_person =
            decode_person_record(store.persons.get(&txn, &medic.person_id).unwrap().unwrap())
                .unwrap();
        medic_person.person.skills.push(crate::wire::SkillRating {
            skill: crate::wire::SkillId::Medicine,
            level: 2,
        });
        store
            .persons
            .put(
                &mut txn,
                &medic.person_id,
                &encode_person_record(&medic_person).unwrap(),
            )
            .unwrap();
        let mut patient = decode_person_record(
            store
                .persons
                .get(&txn, &captain.person_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        patient.current_strength = patient.current_strength.saturating_sub(1);
        patient.current_dexterity = patient.current_dexterity.saturating_sub(1);
        patient.current_endurance = patient.current_endurance.saturating_sub(1);
        let before = person_physical(&patient);
        store
            .persons
            .put(
                &mut txn,
                &patient.person_id,
                &encode_person_record(&patient).unwrap(),
            )
            .unwrap();
        let RuleResult::Applied(_) = store
            .apply_personnel_action_in(
                &mut txn,
                &identity,
                patient.person_id,
                captain.service_revision,
                crate::wire::PersonnelActionKind::Surgery,
                0,
                0,
            )
            .unwrap()
        else {
            panic!("surgery was rejected")
        };
        let pending = decode_person_record(
            store
                .persons
                .get(&txn, &patient.person_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(person_physical(&pending), before);
        assert_ne!(pending.pending_treatment_due_second, 0);
        assert_ne!(pending.pending_treatment_effect, 0);
        let due = pending.pending_treatment_due_second;
        store
            .process_person_treatment_in(&mut txn, due, patient.person_id)
            .unwrap();
        let treated = decode_person_record(
            store
                .persons
                .get(&txn, &patient.person_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(treated.pending_treatment_due_second, 0);
        assert_ne!(person_physical(&treated), before);
        let service = decode_crew_service(
            store
                .crew_services
                .get(&txn, &patient.person_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(service.ship_id, player.ship_id);
        assert_eq!(service.availability, CrewAvailability::Active);
        txn.commit().unwrap();
    }

