    #[test]
    fn gas_skimming_is_timed_tracks_unrefined_fuel_and_voids_warranty() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
        ship.current_fuel_millitons = 0;
        ship.unrefined_fuel_millitons = 0;
        let mut txn = store.env.write_txn().unwrap();
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        txn.commit().unwrap();
        let quoted_source = store
            .docked_services_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap()
            .fuel
            .into_iter()
            .find(|service| service.kind == DockedFuelServiceKind::GasGiant)
            .and_then(|service| service.source_body_id)
            .expect("generated system must quote a named gas giant");

        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    241,
                    Command::CommitDockedService(crate::wire::DockedServiceOrder {
                        expected_ship_revision: ship.revision,
                        kind: DockedServiceOrderKind::Fuel {
                            kind: DockedFuelServiceKind::GasGiant,
                            source_body_id: Some(quoted_source),
                            quantity_millitons: MILLITONS_PER_TON,
                        },
                    }),
                ),
            })
            .unwrap();
        let OutcomeKind::DockedServiceReceipt(receipt) =
            store.process_next().unwrap().unwrap().outcome.kind
        else {
            panic!("expected docked-service receipt");
        };
        assert_eq!(receipt.detail, DockedServiceReceiptDetail::Generic);
        let travel = store
            .travel_status_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        assert_eq!(travel.stage, TravelStage::GasGiantSkim);
        assert!(travel.due_second > 0);
        // Contact handling has its own coverage.  This test isolates the
        // three timed frontier-fueling legs and their maintenance effects.
        let mut txn = store.env.write_txn().unwrap();
        store.contact_events.clear(&mut txn).unwrap();
        txn.commit().unwrap();
        let mut due = travel.due_second;
        let mut player_events = 0;
        let mut activity_events = 0;
        loop {
            let advance = store.advance_simulation_to(due).unwrap();
            player_events += advance.player_travel_events;
            activity_events += advance.ship_activity_events;
            let current = store.ship_record(player.ship_id).unwrap().unwrap();
            if current.activity.is_none() {
                break;
            }
            due = match current.location {
                ShipLocationRecord::InFlight(leg) => leg.due_second,
                ShipLocationRecord::Docked { .. } => current.activity.unwrap().due_second,
                ShipLocationRecord::Holding { .. } => {
                    panic!("frontier fueling unexpectedly entered a holding locus")
                }
            };
        }
        assert_eq!(player_events, 3);
        assert_eq!(activity_events, 1);
        let completed = store.ship_record(player.ship_id).unwrap().unwrap();
        assert_eq!(completed.current_fuel_millitons, MILLITONS_PER_TON);
        // The starter has processors, so the elapsed operation returns refined fuel.
        assert_eq!(completed.unrefined_fuel_millitons, 0);
        assert!(completed.maintenance.warranty_voided);
        assert!(completed.activity.is_none());
    }

    #[test]
    fn monthly_accounting_charges_upkeep_without_conjuring_life_support_stores() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let _epoch = initialize_player_fixture(&store);
        let player_before = store.player_record(&identity()).unwrap().unwrap();
        let ship_before = store.ship_record(player_before.ship_id).unwrap().unwrap();
        let upkeep = crate::ship_condition::monthly_maintenance_credits(
            ship_before.maintenance.purchase_price_credits,
        );
        let finance_before = store
            .finances
            .get(
                &store.env.read_txn().unwrap(),
                &ship_finance_key(player_before.ship_id),
            )
            .unwrap()
            .map(decode_finance_record)
            .transpose()
            .unwrap()
            .unwrap();
        let payroll = store
            .crew_services(ship_before.ship_id)
            .unwrap()
            .into_iter()
            .map(|service| service.monthly_salary_credits)
            .sum::<u64>();
        let due = ship_before.maintenance.next_accounting_second;
        let mut txn = store.env.write_txn().unwrap();
        let (key, scheduled_due, event_id, ship_id) =
            first_simple_event(store.ship_condition_events, &txn)
                .unwrap()
                .unwrap();
        assert_eq!((scheduled_due, ship_id), (due, ship_before.ship_id));
        store.ship_condition_events.delete(&mut txn, &key).unwrap();
        store
            .enqueue_engine_input_in(
                &mut txn,
                &EngineInput::Scheduled(ScheduledInput::ShipCondition {
                    event_id,
                    due_second: due,
                    ship_id,
                }),
            )
            .unwrap();
        txn.commit().unwrap();
        let processed = store.process_next_engine_input().unwrap().unwrap();
        assert_eq!(
            processed.category,
            Some(ProcessedScheduledCategory::ShipCondition)
        );

        let player_after = store.player_record(&identity()).unwrap().unwrap();
        assert_eq!(
            player_after.credits,
            player_before.credits
                - upkeep
                - payroll
                - finance_before.monthly_payment_credits
                - finance_before.monthly_insurance_escrow_credits
        );
        let ship_after = store.ship_record(player_before.ship_id).unwrap().unwrap();
        assert_eq!(ship_after.maintenance.completed_cycles, 1);
        assert_eq!(ship_after.maintenance.paid_through_second, due);
        assert!(
            ship_after
                .subsystems
                .iter()
                .all(|subsystem| subsystem.calendar_age_months == 1)
        );
        assert_eq!(
            ship_after.maintenance.next_accounting_second,
            due + crate::ship_condition::ACCOUNTING_MONTH_SECONDS
        );
    }

    fn install_monthly_upkeep_test_state(
        store: &Store,
        player: &PlayerRecord,
        ship: &ShipRecord,
        title: crate::wire::ShipTitleKind,
        restricted_credits: u64,
    ) {
        let finance_key = ship_finance_key(ship.ship_id);
        let mut txn = store.env.write_txn().unwrap();
        let mut finance =
            decode_finance_record(store.finances.get(&txn, &finance_key).unwrap().unwrap())
                .unwrap();
        finance.title = title;
        finance.restricted_credits = restricted_credits;
        finance.principal_credits = 0;
        finance.monthly_payment_credits = 0;
        finance.monthly_insurance_escrow_credits = 0;
        finance.next_payment_due_second = u64::MAX;
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity()),
                &encode_player_record(player),
            )
            .unwrap();
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(ship).unwrap())
            .unwrap();
        store
            .finances
            .put(&mut txn, &finance_key, &encode_finance_record(&finance))
            .unwrap();
        txn.commit().unwrap();
    }

    fn process_monthly_upkeep_test_cycle(store: &Store, ship: &ShipRecord) {
        let mut txn = store.env.write_txn().unwrap();
        store
            .process_ship_condition_in(
                &mut txn,
                ship.maintenance.next_accounting_second,
                ship.ship_id,
            )
            .unwrap();
        txn.commit().unwrap();
    }

    fn restricted_credits_for_test_ship(store: &Store, ship_id: u64) -> u64 {
        let txn = store.env.read_txn().unwrap();
        decode_finance_record(
            store
                .finances
                .get(&txn, &ship_finance_key(ship_id))
                .unwrap()
                .unwrap(),
        )
        .unwrap()
        .restricted_credits
    }

    #[test]
    fn monthly_upkeep_uses_restricted_credit_during_an_active_refit() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let mut player = store.player_record(&identity()).unwrap().unwrap();
        let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
        let upkeep = crate::ship_condition::monthly_maintenance_credits(
            ship.maintenance.purchase_price_credits,
        );
        let due = ship.maintenance.next_accounting_second;
        let (world_id, facility_id) = match &ship.location {
            ShipLocationRecord::Docked {
                world_id,
                facility_id,
                ..
            } => (*world_id, *facility_id),
            other => panic!("expected docked fixture ship, got {other:?}"),
        };
        ship.activity = Some(ShipActivityRecord {
            activity_id: 91,
            kind: ShipActivityKind::Refit,
            started_second: due.saturating_sub(crate::simulation::SECONDS_PER_DAY),
            due_second: due + crate::ship_condition::ACCOUNTING_MONTH_SECONDS,
            cost_credits: upkeep.saturating_mul(4),
            site: ShipActivitySite::Dockyard {
                system_id: ship.system_id,
                world_id,
                facility_id,
            },
        });
        let active_refit = ship.activity.clone();
        player.credits = 0;
        player.debt_credits = 0;
        install_monthly_upkeep_test_state(
            &store,
            &player,
            &ship,
            crate::wire::ShipTitleKind::SponsorOwned,
            upkeep,
        );
        process_monthly_upkeep_test_cycle(&store, &ship);

        let player_after = store.player_record(&identity()).unwrap().unwrap();
        assert_eq!(player_after.credits, 0);
        let ship_after = store.ship_record(ship.ship_id).unwrap().unwrap();
        assert_eq!(ship_after.activity, active_refit);
        assert_eq!(ship_after.maintenance.paid_through_second, due);
        assert_eq!(ship_after.maintenance.consecutive_missed_cycles, 0);
        assert_eq!(ship_after.maintenance.arrears_credits, 0);
        assert!(
            ship_after
                .subsystems
                .iter()
                .all(|subsystem| subsystem.neglect_damage_hits == 0)
        );
        assert_eq!(restricted_credits_for_test_ship(&store, ship.ship_id), 0);
    }

