    #[test]
    fn an_unfed_captain_takes_ce_starvation_damage_after_three_days() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let mut player = store.player_record(&identity()).unwrap().unwrap();
        let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
        ship.provisions.person_days_remaining = 0;
        player.credits = 0;
        let mut txn = store.env.write_txn().unwrap();
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity()),
                &encode_player_record(&player),
            )
            .unwrap();
        for day in 1..=3 {
            store
                .process_person_recovery_day_in(
                    &mut txn,
                    ship.system_id,
                    day * crate::simulation::SECONDS_PER_DAY,
                )
                .unwrap();
        }
        let hungry = decode_person_record(
            store
                .persons
                .get(&txn, &player.captain_person_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(hungry.unfed_days, 3);
        assert_eq!(person_injury_points(&hungry), 0);

        for day in 4..=12 {
            store
                .process_person_recovery_day_in(
                    &mut txn,
                    ship.system_id,
                    day * crate::simulation::SECONDS_PER_DAY,
                )
                .unwrap();
        }
        let starving = decode_person_record(
            store
                .persons
                .get(&txn, &player.captain_person_id)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert!(starving.unfed_days >= 4);
        assert!(person_injury_points(&starving) != 0);
        txn.commit().unwrap();
    }

    #[test]
    fn store_open_reconciles_legacy_provision_capacity_exactly_once() {
        let dir = TempDir::new().unwrap();
        let (ship_id, corrected_persons, prior_remaining, prior_revision) = {
            let store = Store::open(dir.path()).unwrap();
            initialize_player_fixture(&store);
            let player = store.player_record(&identity()).unwrap().unwrap();
            let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
            let corrected_persons = u64::from(
                creation::ship_status_spec(ship.catalog_id)
                    .unwrap()
                    .life_support_capacity_persons,
            );
            let legacy_persons = corrected_persons - 1;
            let prior_remaining = legacy_persons * 30 - 7;
            ship.provisions.person_days_remaining = prior_remaining;
            ship.provisions.installed_capacity_person_days = legacy_persons * 180;
            let prior_revision = ship.revision;
            let mut txn = store.env.write_txn().unwrap();
            store
                .ships
                .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
                .unwrap();
            store
                .meta
                .delete(&mut txn, META_ACCOMMODATION_CAPACITY_VERSION)
                .unwrap();
            txn.commit().unwrap();
            (
                ship.ship_id,
                corrected_persons,
                prior_remaining,
                prior_revision,
            )
        };

        let store = Store::open(dir.path()).unwrap();
        let reconciled = store.ship_record(ship_id).unwrap().unwrap();
        assert_eq!(
            reconciled.provisions.person_days_remaining,
            prior_remaining + 30
        );
        assert_eq!(
            reconciled.provisions.installed_capacity_person_days,
            corrected_persons * 180
        );
        assert_eq!(reconciled.revision, prior_revision + 1);
        drop(store);

        let reopened = Store::open(dir.path()).unwrap();
        let unchanged = reopened.ship_record(ship_id).unwrap().unwrap();
        assert_eq!(unchanged.provisions, reconciled.provisions);
        assert_eq!(unchanged.revision, reconciled.revision);
    }

    #[test]
    fn docked_service_orders_are_revisioned_and_replenish_physical_stores() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let quotation = store
            .docked_services_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        assert!(
            quotation
                .fuel
                .iter()
                .any(|offer| offer.kind == DockedFuelServiceKind::Refined)
        );
        assert!(
            quotation
                .fuel
                .iter()
                .filter(|offer| offer.source_body_id.is_some())
                .all(|offer| !offer.label.contains("Primary"))
        );
        let order = crate::wire::DockedServiceOrder {
            expected_ship_revision: quotation.ship_revision,
            kind: DockedServiceOrderKind::Provisions { packages: 1 },
        };
        let mut txn = store.env.write_txn().unwrap();
        let RuleResult::Applied(after) = store
            .commit_docked_service_in(&mut txn, &identity(), &order)
            .unwrap()
        else {
            panic!("provision order rejected");
        };
        txn.commit().unwrap();
        assert!(
            after.ship_status.provisions.person_days_remaining
                > quotation.provisions.person_days_remaining
        );
        let DockedServiceReceiptDetail::ProvisionPurchase(receipt) = after.detail else {
            panic!("expected provision-purchase receipt");
        };
        assert_eq!(receipt.packages, 1);
        assert_eq!(
            receipt.person_days_loaded,
            quotation.provision_package_person_days
        );
        assert_eq!(
            receipt.person_days_remaining,
            quotation.provisions.person_days_remaining + quotation.provision_package_person_days
        );
        assert_eq!(
            receipt.capacity_person_days,
            quotation.provisions.capacity_person_days
        );
        assert_eq!(
            receipt.cost_credits,
            quotation.provision_package_price_credits
        );
        let mut txn = store.env.write_txn().unwrap();
        assert!(matches!(
            store
                .commit_docked_service_in(&mut txn, &identity(), &order)
                .unwrap(),
            RuleResult::Rejected(_)
        ));
    }

    #[test]
    fn fuel_purchase_receipts_report_exact_account_allocation() {
        for (kind, restricted, liquid) in [
            (DockedFuelServiceKind::Refined, 6_000, 1_000),
            (DockedFuelServiceKind::Unrefined, 0, 2_000),
            (DockedFuelServiceKind::Unrefined, 400, 1_600),
        ] {
            let dir = TempDir::new().unwrap();
            let store = Store::open(dir.path()).unwrap();
            initialize_player_fixture(&store);
            let mut player = store.player_record(&identity()).unwrap().unwrap();
            let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
            let capacity = effective_fuel_capacity(
                &ship,
                &creation::ship_status_spec(ship.catalog_id).unwrap(),
            );
            ship.current_fuel_millitons = capacity - 10 * MILLITONS_PER_TON;
            ship.unrefined_fuel_millitons = 0;
            player.credits = liquid;
            let finance_key = ship_finance_key(ship.ship_id);
            let mut txn = store.env.write_txn().unwrap();
            let mut finance =
                decode_finance_record(store.finances.get(&txn, &finance_key).unwrap().unwrap())
                    .unwrap();
            finance.restricted_credits = restricted;
            store
                .players
                .put(
                    &mut txn,
                    &encode_identity(&identity()),
                    &encode_player_record(&player),
                )
                .unwrap();
            store
                .ships
                .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
                .unwrap();
            store
                .finances
                .put(&mut txn, &finance_key, &encode_finance_record(&finance))
                .unwrap();
            txn.commit().unwrap();

            let quantity = 10 * MILLITONS_PER_TON;
            let cost = match kind {
                DockedFuelServiceKind::Refined => 5_000,
                DockedFuelServiceKind::Unrefined => 1_000,
                _ => unreachable!(),
            };
            let expected_restricted = restricted.min(cost);
            let expected_liquid = cost - expected_restricted;
            let order = crate::wire::DockedServiceOrder {
                expected_ship_revision: ship.revision,
                kind: DockedServiceOrderKind::Fuel {
                    kind,
                    source_body_id: None,
                    quantity_millitons: quantity,
                },
            };
            let mut txn = store.env.write_txn().unwrap();
            let RuleResult::Applied(receipt) = store
                .commit_docked_service_in(&mut txn, &identity(), &order)
                .unwrap()
            else {
                panic!("fuel purchase rejected");
            };
            txn.commit().unwrap();
            let DockedServiceReceiptDetail::FuelPurchase(fuel) = receipt.detail else {
                panic!("expected fuel-purchase receipt");
            };
            assert_eq!(fuel.kind, kind);
            assert_eq!(fuel.quantity_millitons, quantity);
            assert_eq!(fuel.current_fuel_millitons, capacity);
            assert_eq!(fuel.fuel_capacity_millitons, capacity);
            assert_eq!(fuel.cost_credits, cost);
            assert_eq!(fuel.restricted_payment_credits, expected_restricted);
            assert_eq!(fuel.liquid_payment_credits, expected_liquid);
            assert_eq!(
                fuel.restricted_balance_credits,
                restricted - expected_restricted
            );
            assert_eq!(fuel.liquid_balance_credits, liquid - expected_liquid);
            assert_eq!(
                fuel.unrefined_fuel_millitons,
                if kind == DockedFuelServiceKind::Unrefined {
                    quantity
                } else {
                    0
                }
            );
            assert_eq!(
                store.player_record(&identity()).unwrap().unwrap().credits,
                fuel.liquid_balance_credits
            );
            let txn = store.env.read_txn().unwrap();
            let finance =
                decode_finance_record(store.finances.get(&txn, &finance_key).unwrap().unwrap())
                    .unwrap();
            assert_eq!(finance.restricted_credits, fuel.restricted_balance_credits);
        }
    }

    #[test]
    fn provision_purchase_receipts_report_exact_account_allocation() {
        for payment_case in 0..3 {
            let dir = TempDir::new().unwrap();
            let store = Store::open(dir.path()).unwrap();
            initialize_player_fixture(&store);
            let quotation = store
                .docked_services_in(&store.env.read_txn().unwrap(), &identity())
                .unwrap();
            let cost = quotation.provision_package_price_credits;
            let (restricted, liquid) = match payment_case {
                0 => (cost + 100, 100),
                1 => (0, cost + 100),
                _ => (cost / 2, cost - cost / 2 + 100),
            };
            let mut player = store.player_record(&identity()).unwrap().unwrap();
            let ship = store.ship_record(player.ship_id).unwrap().unwrap();
            player.credits = liquid;
            let finance_key = ship_finance_key(ship.ship_id);
            let mut txn = store.env.write_txn().unwrap();
            let mut finance =
                decode_finance_record(store.finances.get(&txn, &finance_key).unwrap().unwrap())
                    .unwrap();
            finance.restricted_credits = restricted;
            store
                .players
                .put(
                    &mut txn,
                    &encode_identity(&identity()),
                    &encode_player_record(&player),
                )
                .unwrap();
            store
                .finances
                .put(&mut txn, &finance_key, &encode_finance_record(&finance))
                .unwrap();
            txn.commit().unwrap();

            let order = crate::wire::DockedServiceOrder {
                expected_ship_revision: quotation.ship_revision,
                kind: DockedServiceOrderKind::Provisions { packages: 1 },
            };
            let mut txn = store.env.write_txn().unwrap();
            let RuleResult::Applied(receipt) = store
                .commit_docked_service_in(&mut txn, &identity(), &order)
                .unwrap()
            else {
                panic!("provision purchase rejected");
            };
            txn.commit().unwrap();
            let DockedServiceReceiptDetail::ProvisionPurchase(provisions) = receipt.detail else {
                panic!("expected provision-purchase receipt");
            };
            let expected_restricted = restricted.min(cost);
            let expected_liquid = cost - expected_restricted;
            assert_eq!(provisions.packages, 1);
            assert_eq!(
                provisions.person_days_loaded,
                quotation.provision_package_person_days
            );
            assert_eq!(
                provisions.person_days_remaining,
                quotation.provisions.person_days_remaining
                    + quotation.provision_package_person_days
            );
            assert_eq!(
                provisions.capacity_person_days,
                quotation.provisions.capacity_person_days
            );
            assert_eq!(provisions.cost_credits, cost);
            assert_eq!(provisions.restricted_payment_credits, expected_restricted);
            assert_eq!(provisions.liquid_payment_credits, expected_liquid);
            assert_eq!(
                provisions.restricted_balance_credits,
                restricted - expected_restricted
            );
            assert_eq!(provisions.liquid_balance_credits, liquid - expected_liquid);
            assert_eq!(
                store.player_record(&identity()).unwrap().unwrap().credits,
                provisions.liquid_balance_credits
            );
            let txn = store.env.read_txn().unwrap();
            let finance =
                decode_finance_record(store.finances.get(&txn, &finance_key).unwrap().unwrap())
                    .unwrap();
            assert_eq!(
                finance.restricted_credits,
                provisions.restricted_balance_credits
            );
        }
    }

    #[test]
    fn fuel_purchase_receipt_replays_across_restart() {
        let dir = TempDir::new().unwrap();
        let (epoch, purchase, committed) = {
            let store = Store::open(dir.path()).unwrap();
            let epoch = initialize_player_fixture(&store);
            let mut player = store.player_record(&identity()).unwrap().unwrap();
            let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
            let capacity = effective_fuel_capacity(
                &ship,
                &creation::ship_status_spec(ship.catalog_id).unwrap(),
            );
            ship.current_fuel_millitons = capacity - 10 * MILLITONS_PER_TON;
            ship.unrefined_fuel_millitons = 0;
            player.credits = 3_000;
            let finance_key = ship_finance_key(ship.ship_id);
            let mut txn = store.env.write_txn().unwrap();
            let mut finance =
                decode_finance_record(store.finances.get(&txn, &finance_key).unwrap().unwrap())
                    .unwrap();
            finance.restricted_credits = 2_000;
            store
                .players
                .put(
                    &mut txn,
                    &encode_identity(&identity()),
                    &encode_player_record(&player),
                )
                .unwrap();
            store
                .ships
                .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
                .unwrap();
            store
                .finances
                .put(&mut txn, &finance_key, &encode_finance_record(&finance))
                .unwrap();
            txn.commit().unwrap();
            let purchase = request(
                epoch,
                226,
                Command::CommitDockedService(crate::wire::DockedServiceOrder {
                    expected_ship_revision: ship.revision,
                    kind: DockedServiceOrderKind::Fuel {
                        kind: DockedFuelServiceKind::Refined,
                        source_body_id: None,
                        quantity_millitons: 10 * MILLITONS_PER_TON,
                    },
                }),
            );
            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: purchase.clone(),
                })
                .unwrap();
            let delivery = store.process_next().unwrap().unwrap();
            assert!(!delivery.outcome.replayed);
            // Version 11 used the same zero/one discriminator for generic and
            // fuel receipts.  Existing retained outcomes must remain readable
            // after version 12 adds the provision variant.
            let mut version_eleven = encode_outcome(&delivery.outcome).unwrap();
            version_eleven[0] = 11;
            assert_eq!(decode_outcome(&version_eleven).unwrap(), delivery.outcome);
            let OutcomeKind::DockedServiceReceipt(committed) = delivery.outcome.kind else {
                panic!("expected docked-service receipt");
            };
            (epoch, purchase, committed)
        };

        let reopened = Store::open(dir.path()).unwrap();
        assert_eq!(purchase.session_epoch, epoch);
        reopened
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: purchase,
            })
            .unwrap();
        let replay = reopened.process_next().unwrap().unwrap();
        assert!(replay.outcome.replayed);
        assert_eq!(
            replay.outcome.kind,
            OutcomeKind::DockedServiceReceipt(committed)
        );
    }

    #[test]
    fn provision_purchase_receipt_replays_across_restart() {
        let dir = TempDir::new().unwrap();
        let (epoch, purchase, committed) = {
            let store = Store::open(dir.path()).unwrap();
            let epoch = initialize_player_fixture(&store);
            let quotation = store
                .docked_services_in(&store.env.read_txn().unwrap(), &identity())
                .unwrap();
            let purchase = request(
                epoch,
                227,
                Command::CommitDockedService(crate::wire::DockedServiceOrder {
                    expected_ship_revision: quotation.ship_revision,
                    kind: DockedServiceOrderKind::Provisions { packages: 1 },
                }),
            );
            store
                .enqueue(&QueuedCommand {
                    identity: identity(),
                    request: purchase.clone(),
                })
                .unwrap();
            let delivery = store.process_next().unwrap().unwrap();
            assert!(!delivery.outcome.replayed);
            let OutcomeKind::DockedServiceReceipt(committed) = delivery.outcome.kind else {
                panic!("expected docked-service receipt");
            };
            assert!(matches!(
                &committed.detail,
                DockedServiceReceiptDetail::ProvisionPurchase(_)
            ));
            (epoch, purchase, committed)
        };

        let reopened = Store::open(dir.path()).unwrap();
        assert_eq!(purchase.session_epoch, epoch);
        reopened
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: purchase,
            })
            .unwrap();
        let replay = reopened.process_next().unwrap().unwrap();
        assert!(replay.outcome.replayed);
        assert_eq!(
            replay.outcome.kind,
            OutcomeKind::DockedServiceReceipt(committed)
        );
    }

    #[test]
    fn persisted_facility_capabilities_govern_both_quotes_and_commits() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let ship = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap()
            .1;
        let facility_id = match ship.location {
            ShipLocationRecord::Docked { facility_id, .. } => facility_id,
            _ => panic!("fixture ship is not docked"),
        };
        let mut txn = store.env.write_txn().unwrap();
        let mut facility =
            decode_facility(store.facilities.get(&txn, &facility_id).unwrap().unwrap()).unwrap();
        facility.refined_fuel = false;
        facility.unrefined_fuel = false;
        facility.chandlery = false;
        facility.ordnance = false;
        facility.personnel_exchange = false;
        facility.banking = false;
        facility.authority_office = false;
        facility.revision += 1;
        store
            .facilities
            .put(&mut txn, &facility_id, &encode_facility(&facility).unwrap())
            .unwrap();

        let docked = store.docked_snapshot_in(&txn, &identity()).unwrap();
        assert_eq!(docked.facility_revision, facility.revision);
        assert!(!docked.personnel_available);
        assert!(!docked.banking_available);
        assert!(!docked.authority_available);
        let services = store.docked_services_in(&txn, &identity()).unwrap();
        assert!(!services.provisions_available);
        assert!(!services.ammunition_available);
        assert!(services.fuel.iter().all(|offer| {
            !matches!(
                offer.kind,
                DockedFuelServiceKind::Refined | DockedFuelServiceKind::Unrefined
            ) || !offer.available
        }));
        assert!(matches!(
            store
                .buy_ship_provisions_in(&mut txn, &identity(), 1)
                .unwrap(),
            RuleResult::Rejected(_)
        ));
        assert!(matches!(
            store
                .buy_ship_ammunition_in(&mut txn, &identity(), "unlisted ammunition", 1)
                .unwrap(),
            RuleResult::Rejected(_)
        ));
        assert!(matches!(
            store
                .buy_fuel_in(&mut txn, &identity(), MILLITONS_PER_TON)
                .unwrap(),
            RuleResult::Rejected(_)
        ));
        txn.commit().unwrap();
        drop(store);

        let reopened = Store::open(dir.path()).unwrap();
        let services = reopened
            .docked_services_in(&reopened.env.read_txn().unwrap(), &identity())
            .unwrap();
        assert!(!services.provisions_available);
        assert!(!services.ammunition_available);
    }

    #[test]
    fn combat_ammunition_and_component_replacement_share_the_persistent_ship_record() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
        if let Some(first) = ship.ammunition.first_mut() {
            first.remaining = first.remaining.saturating_sub(1);
        }
        let mut vessel =
            crate::combat::materialize_vessel(ship.ship_id, 1, &ship.name, ship.catalog_id, 7)
                .unwrap();
        apply_ship_damage_to_combat(&ship, &mut vessel);
        for lot in &vessel.ammunition {
            assert_eq!(
                lot.remaining,
                ship.ammunition
                    .iter()
                    .find(|stored| stored.ammunition_id == lot.ammunition_id)
                    .unwrap()
                    .remaining
            );
        }
        if let Some(first) = vessel.ammunition.first_mut() {
            first.remaining = first.remaining.saturating_sub(1);
        }
        apply_combat_damage_to_ship(&vessel, &mut ship);
        if let Some(first) = vessel.ammunition.first() {
            assert_eq!(
                ship.ammunition
                    .iter()
                    .find(|stored| stored.ammunition_id == first.ammunition_id)
                    .unwrap()
                    .remaining,
                first.remaining
            );
        }
        let target = ship
            .subsystems
            .iter_mut()
            .find(|subsystem| {
                subsystem.replacement_price_credits != 0
                    && !matches!(
                        subsystem.kind,
                        ShipSubsystemKind::Hull | ShipSubsystemKind::Structure
                    )
            })
            .unwrap();
        target.sustained_hits = target.maximum_hits;
        let target_id = target.subsystem_id;
        let previous_generation = target.installation_generation;
        let mut rich = store.player_record(&identity()).unwrap().unwrap();
        rich.credits = u64::MAX / 4;
        let mut txn = store.env.write_txn().unwrap();
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity()),
                &encode_player_record(&rich),
            )
            .unwrap();
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        txn.commit().unwrap();
        let revision = store.ship_record(ship.ship_id).unwrap().unwrap().revision;
        let order = crate::wire::DockedServiceOrder {
            expected_ship_revision: revision,
            kind: DockedServiceOrderKind::Replacement {
                subsystem_id: target_id,
                reconditioned: true,
            },
        };
        let mut txn = store.env.write_txn().unwrap();
        let RuleResult::Applied(scheduled) = store
            .commit_docked_service_in(&mut txn, &identity(), &order)
            .unwrap()
        else {
            panic!("replacement rejected")
        };
        txn.commit().unwrap();
        assert!(matches!(
            scheduled.ship_status.active_activity.unwrap().kind,
            WireShipActivityKind::Refurbishment { component_count: 1 }
        ));
        let due = store
            .ship_record(ship.ship_id)
            .unwrap()
            .unwrap()
            .activity
            .unwrap()
            .due_second;
        let mut txn = store.env.write_txn().unwrap();
        store
            .process_ship_activity_in(&mut txn, due, ship.ship_id)
            .unwrap();
        txn.commit().unwrap();
        let replaced = store.ship_record(ship.ship_id).unwrap().unwrap();
        let target = replaced
            .subsystems
            .iter()
            .find(|subsystem| subsystem.subsystem_id == target_id)
            .unwrap();
        assert_eq!(target.sustained_hits, 0);
        assert!(target.reconditioned);
        assert_eq!(target.installation_generation, previous_generation + 1);
    }

    #[test]
    fn impound_order_is_private_mail_and_not_instant_remote_state() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let mut ship = store.ship_record(player.ship_id).unwrap().unwrap();
        let captain = store
            .persons
            .get(&store.env.read_txn().unwrap(), &player.captain_person_id)
            .unwrap()
            .map(decode_person_record)
            .transpose()
            .unwrap()
            .unwrap();
        assert_ne!(captain.origin_system_id, 2);
        let mut txn = store.env.write_txn().unwrap();
        let mut poor_player = store
            .players
            .get(&txn, &encode_identity(&identity()))
            .unwrap()
            .map(decode_player_record)
            .transpose()
            .unwrap()
            .unwrap();
        poor_player.credits = 0;
        ship.system_id = 2;
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity()),
                &encode_player_record(&poor_player),
            )
            .unwrap();
        store
            .ships
            .put(&mut txn, &ship.ship_id, &encode_ship_record(&ship).unwrap())
            .unwrap();
        txn.commit().unwrap();

        for _ in 0..2 {
            let mut txn = store.env.write_txn().unwrap();
            let (key, due_second, event_id, ship_id) =
                first_simple_event(store.ship_condition_events, &txn)
                    .unwrap()
                    .unwrap();
            store.ship_condition_events.delete(&mut txn, &key).unwrap();
            store
                .enqueue_engine_input_in(
                    &mut txn,
                    &EngineInput::Scheduled(ScheduledInput::ShipCondition {
                        event_id,
                        due_second,
                        ship_id,
                    }),
                )
                .unwrap();
            txn.commit().unwrap();
            store.process_next_engine_input().unwrap().unwrap();
        }

        let txn = store.env.read_txn().unwrap();
        let finance = store
            .finances
            .get(&txn, &ship_finance_key(player.ship_id))
            .unwrap()
            .map(decode_finance_record)
            .transpose()
            .unwrap()
            .unwrap();
        assert!(finance.in_default);
        assert_ne!(finance.impound_message_id, 0);
        let current = get_meta_u64(store.meta, &txn, META_GAME_SECOND)
            .unwrap()
            .unwrap();
        assert!(
            store
                .simulation
                .available_messages(&txn, captain.origin_system_id, current, true)
                .unwrap()
                .iter()
                .any(|m| m.message.message_id == finance.impound_message_id)
        );
        assert!(
            store
                .simulation
                .available_messages(&txn, 2, current, true)
                .unwrap()
                .iter()
                .all(|m| m.message.message_id != finance.impound_message_id)
        );
    }

    #[test]
    fn merchant_offers_are_durable_and_deadlines_enter_the_single_queue() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let epoch = initialize_player_fixture(&store);
        // A fixture does not run the clock. Originate one normal daily batch
        // explicitly so this exercises persisted, globally claimable offers
        // rather than the removed per-player projection.
        let ship = store.ship_record(1).unwrap().unwrap();
        let mut txn = store.env.write_txn().unwrap();
        let now = get_meta_u64(store.meta, &txn, META_GAME_SECOND)
            .unwrap()
            .unwrap_or(0);
        for ordinal in 0..8 {
            store
                .simulation
                .dispatch_message(
                    &mut txn,
                    now,
                    ship.system_id,
                    crate::simulation::MessageClass::ContractOffer,
                    crate::simulation::MessageImportance::Notable,
                    &format!("fixture offer {}", ordinal + 1),
                    "A fixture instrument is attached.",
                    &[],
                )
                .unwrap();
        }
        store
            .materialize_contract_offers_in(&mut txn, ship.system_id, now)
            .unwrap();
        txn.commit().unwrap();
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(epoch, 201, Command::GetTaskLedger),
            })
            .unwrap();
        let ledger = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::TaskLedger(v) => v,
            other => panic!("expected task ledger, got {other:?}"),
        };
        assert!(
            ledger
                .local_offers
                .iter()
                .any(|o| o.kind == crate::wire::TaskKind::Freight)
        );
        assert!(
            ledger
                .local_offers
                .iter()
                .any(|o| o.kind == crate::wire::TaskKind::Charter)
        );
        assert!(
            ledger
                .local_offers
                .iter()
                .any(|o| o.kind == crate::wire::TaskKind::CombatBounty)
        );
        let offer = ledger
            .local_offers
            .iter()
            .find(|o| o.kind == crate::wire::TaskKind::Freight)
            .unwrap()
            .clone();
        let txn = store.env.read_txn().unwrap();
        let article = store.simulation.message(&txn, offer.offer_id).unwrap();
        let item = store
            .message_item_in(
                &txn,
                &identity(),
                &article,
                article.created_second,
                MessageClassification::Unreviewed,
                false,
                ship.system_id,
                article.created_second,
            )
            .unwrap();
        assert_eq!(item.offer_id, Some(offer.offer_id));
        assert!(item.offer_available);
        assert!(item.body.contains("Payment: Cr"));
        drop(txn);
        store
            .enqueue(&QueuedCommand {
                identity: identity(),
                request: request(
                    epoch,
                    202,
                    Command::AcceptTaskOffer {
                        offer_id: offer.offer_id,
                        expected_revision: offer.revision,
                    },
                ),
            })
            .unwrap();
        let accepted = match store.process_next().unwrap().unwrap().outcome.kind {
            OutcomeKind::TaskLedger(v) => v,
            other => panic!("expected accepted task ledger, got {other:?}"),
        };
        assert_eq!(accepted.tasks.len(), 1);
        assert_eq!(accepted.reserved_cargo_millitons, offer.quantity_millitons);
        let message_state = store
            .player_message_state
            .get(
                &store.env.read_txn().unwrap(),
                &player_message_state_key(&identity(), offer.offer_id),
            )
            .unwrap()
            .map(decode_player_message_state)
            .transpose()
            .unwrap()
            .unwrap();
        assert_eq!(
            message_state.classification,
            MessageClassification::Actioned
        );
        let competing_identity = PlayerIdentity {
            bbs_id: identity().bbs_id,
            player_id: identity().player_id + 1,
        };
        establish_player(&store, &competing_identity);
        let mut txn = store.env.write_txn().unwrap();
        let competing_ship = store
            .player_and_ship_in(&txn, &competing_identity)
            .unwrap()
            .1;
        assert!(
            store
                .local_task_offers_in(&txn, &competing_identity, &competing_ship)
                .unwrap()
                .iter()
                .all(|candidate| candidate.offer_id != offer.offer_id)
        );
        assert!(matches!(
            store
                .accept_task_offer_in(
                    &mut txn,
                    &competing_identity,
                    offer.offer_id,
                    offer.revision,
                )
                .unwrap(),
            RuleResult::Rejected(_)
        ));
        txn.abort();
        assert!(
            store
                .work_assignment_events
                .len(&store.env.read_txn().unwrap())
                .unwrap()
                > 0
        );
        // Exercise the same two-stage scheduler contract without advancing the
        // entire fixed-system simulation fixture through several game weeks.
        let mut txn = store.env.write_txn().unwrap();
        let (key, due_second, event_id, assignment_id) =
            first_simple_event(store.work_assignment_events, &txn)
                .unwrap()
                .unwrap();
        assert_eq!(due_second, offer.delivery_deadline_second);
        assert_eq!(assignment_id & !(1_u64 << 63), 1);
        store.work_assignment_events.delete(&mut txn, &key).unwrap();
        store
            .enqueue_engine_input_in(
                &mut txn,
                &EngineInput::Scheduled(ScheduledInput::MerchantWork {
                    event_id,
                    due_second,
                    assignment_id,
                }),
            )
            .unwrap();
        txn.commit().unwrap();
        let processed = store.process_next_engine_input().unwrap().unwrap();
        assert_eq!(
            processed.category,
            Some(ProcessedScheduledCategory::MerchantWork)
        );
        let task = decode_stored_task(
            store
                .tasks
                .get(&store.env.read_txn().unwrap(), &1_u64.to_be_bytes())
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(task.task.state, crate::wire::TaskState::Defaulted);
    }

    #[test]
    fn task_ledger_marks_offers_that_leave_insufficient_departure_cash_and_hold_capacity() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let (player, ship) = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        let mut txn = store.env.write_txn().unwrap();
        let now = get_meta_u64(store.meta, &txn, META_GAME_SECOND)
            .unwrap()
            .unwrap_or(0);
        let (offer_id, _) = store
            .simulation
            .dispatch_message(
                &mut txn,
                now,
                ship.system_id,
                crate::simulation::MessageClass::ContractOffer,
                crate::simulation::MessageImportance::Notable,
                "Oversized fixture contract",
                "A fixture instrument is attached.",
                &[],
            )
            .unwrap();
        let mut offer = test_task_offer(
            offer_id,
            ship.system_id,
            ship.system_id,
            crate::wire::TaskKind::Freight,
        );
        offer.quantity_millitons = u64::MAX;
        offer.collateral_credits = player.credits;
        offer.expires_second = now.saturating_add(crate::simulation::SECONDS_PER_DAY);
        store
            .task_offers
            .put(
                &mut txn,
                &offer_id.to_be_bytes(),
                &encode_stored_task_offer(&StoredTaskOffer {
                    offer,
                    claimed_by: None,
                    claimed_task_id: 0,
                    closure_message_id: 0,
                })
                .unwrap(),
            )
            .unwrap();
        txn.commit().unwrap();

        let ledger = store
            .task_ledger_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        let listed = ledger
            .local_offers
            .iter()
            .find(|candidate| candidate.offer_id == offer_id)
            .unwrap();
        assert!(
            listed
                .unavailable_reasons
                .iter()
                .any(|reason| reason.contains("due to clear the current berth"))
        );
        assert!(
            listed
                .unavailable_reasons
                .iter()
                .any(|reason| reason.contains("hold space"))
        );

        let mut encoded = Vec::new();
        encode_task_ledger_into(&mut encoded, &ledger).unwrap();
        let mut decoder = Decoder::new(&encoded);
        assert_eq!(decode_task_ledger(&mut decoder).unwrap(), ledger);
        decoder.finish().unwrap();
    }

    #[test]
    fn task_ledger_assesses_remote_pickup_and_delivery_as_one_voyage() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let txn = store.env.read_txn().unwrap();
        let (player, ship) = store.player_and_ship_in(&txn, &identity()).unwrap();
        let destination = ship.system_id;
        let pickup = store
            .known_destinations_in(&txn, &identity())
            .unwrap()
            .systems
            .into_iter()
            .find(|system| system.within_jump_rating && system.system_id != ship.system_id)
            .expect("fixture needs a reachable remote pickup")
            .system_id;
        let now = get_meta_u64(store.meta, &txn, META_GAME_SECOND)
            .unwrap()
            .unwrap_or(0);
        drop(txn);

        let mut txn = store.env.write_txn().unwrap();
        let (offer_id, _) = store
            .simulation
            .dispatch_message(
                &mut txn,
                now,
                ship.system_id,
                crate::simulation::MessageClass::ContractOffer,
                crate::simulation::MessageImportance::Notable,
                "Remote pickup timing fixture",
                "A fixture instrument is attached.",
                &[],
            )
            .unwrap();
        let mut offer = test_task_offer(
            offer_id,
            pickup,
            destination,
            crate::wire::TaskKind::Freight,
        );
        offer.expires_second = now.saturating_add(100 * crate::simulation::SECONDS_PER_DAY);
        offer.delivery_deadline_second = now.saturating_add(STANDARD_JUMP_SECONDS);
        store
            .task_offers
            .put(
                &mut txn,
                &offer_id.to_be_bytes(),
                &encode_stored_task_offer(&StoredTaskOffer {
                    offer,
                    claimed_by: None,
                    claimed_task_id: 0,
                    closure_message_id: 0,
                })
                .unwrap(),
            )
            .unwrap();
        txn.commit().unwrap();

        let ledger = store
            .task_ledger_in(&store.env.read_txn().unwrap(), &identity())
            .unwrap();
        assert!(
            ledger
                .local_offers
                .iter()
                .any(|offer| offer.offer_id == offer_id)
        );
        let assessment = ledger
            .route_assessments
            .iter()
            .find(|assessment| assessment.offer_id == offer_id)
            .expect("remote offer needs a route assessment");
        assert!(assessment.pickup_available);
        assert!(assessment.pickup_arrival_second < now + 100 * crate::simulation::SECONDS_PER_DAY);
        assert!(assessment.delivery_available);
        assert!(assessment.delivery_arrival_second > now + STANDARD_JUMP_SECONDS);
        assert!(player.known_system_ids.contains(&pickup));
    }

