    #[test]
    fn customs_confiscates_only_locally_prohibited_cargo_and_collects_available_funds() {
        let world = World {
            id: 1,
            system_id: 1,
            name: "Test Port".into(),
            starport: crate::universe::Starport::A,
            size: 8,
            atmosphere: 6,
            hydrographics: 7,
            population: 8,
            population_multiplier: 5,
            government: 5,
            law_level: 15,
            tech_level: 13,
            planetoid_belts: 0,
            gas_giants: 1,
        };
        let lot = |cargo_lot_id, commodity_id, name: &str, quantity_millitons| CargoLot {
            cargo_lot_id,
            commodity_id,
            commodity_name: name.into(),
            quantity_millitons,
            purchase_price_per_ton: 1,
            origin_system_id: 2,
            acquired_second: 0,
            title: CargoTitle::PlayerOwned,
            task_id: 0,
            unique_object_id: 0,
            condition_percent: 100,
            destination_system_id: 0,
            source_body_id: 0,
            source_lode_id: 0,
        };
        let mut cargo = vec![
            lot(1, 1, "Basic Consumable Goods", 1_000),
            lot(2, 45, "Personal Weapons and Armor", 2_000),
        ];
        let mut credits = 1_000;
        let disposition = apply_customs_inspection(&world, &mut cargo, &mut credits);
        assert_eq!(cargo.len(), 1);
        assert_eq!(cargo[0].commodity_id, 1);
        assert_eq!(disposition.confiscated_millitons, 2_000);
        assert!(disposition.assessed_fine_credits > disposition.collected_fine_credits);
        assert_eq!(disposition.collected_fine_credits, 1_000);
        assert_eq!(
            disposition.commodity_names,
            vec!["Personal Weapons and Armor"]
        );
        assert_eq!(credits, 0);
    }

