    #[test]
    fn unique_pie_is_one_kilogram_one_credit_and_ordinary_loss_does_not_reset() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        let _epoch = initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let ship = store.ship_record(player.ship_id).unwrap().unwrap();
        let mut txn = store.env.write_txn().unwrap();
        let mut pie = store
            .unique_cargo
            .get(&txn, &UNIQUE_APPLE_PIE_ID)
            .unwrap()
            .map(decode_unique_cargo)
            .transpose()
            .unwrap()
            .unwrap();
        pie.location = UniqueCargoLocation::Port {
            system_id: ship.system_id,
        };
        store
            .unique_cargo
            .put(
                &mut txn,
                &pie.object_id,
                &encode_unique_cargo(&pie).unwrap(),
            )
            .unwrap();
        let mut player_record = store
            .players
            .get(&txn, &encode_identity(&identity()))
            .unwrap()
            .map(decode_player_record)
            .transpose()
            .unwrap()
            .unwrap();
        player_record.credits = player_record.credits.saturating_add(1);
        store
            .players
            .put(
                &mut txn,
                &encode_identity(&identity()),
                &encode_player_record(&player_record),
            )
            .unwrap();
        txn.commit().unwrap();
        let mut txn = store.env.write_txn().unwrap();
        let market = store.market_snapshot_in(&txn, &identity()).unwrap();
        let offer = market
            .offers
            .iter()
            .find(|o| o.offer_id == UNIQUE_APPLE_PIE_OFFER_ID)
            .unwrap();
        assert_eq!(
            (offer.available_millitons, offer.purchase_price_per_ton),
            (1, 1_000)
        );
        let bought = match store
            .buy_cargo_in(
                &mut txn,
                &identity(),
                market.market_revision,
                offer.offer_id,
                1,
            )
            .unwrap()
        {
            RuleResult::Applied(v) => v,
            RuleResult::Rejected(e) => panic!("{e}"),
        };
        assert!(
            bought
                .cargo
                .iter()
                .any(|lot| lot.unique_object_id == UNIQUE_APPLE_PIE_ID)
        );
        let mut pie = store
            .unique_cargo
            .get(&txn, &UNIQUE_APPLE_PIE_ID)
            .unwrap()
            .map(decode_unique_cargo)
            .transpose()
            .unwrap()
            .unwrap();
        pie.location = UniqueCargoLocation::Wreckage {
            system_id: ship.system_id,
        };
        store
            .unique_cargo
            .put(
                &mut txn,
                &pie.object_id,
                &encode_unique_cargo(&pie).unwrap(),
            )
            .unwrap();
        txn.commit().unwrap();
        assert!(
            store
                .meta
                .get(&store.env.read_txn().unwrap(), META_UNIVERSE_ID)
                .unwrap()
                .is_some()
        );
        assert!(matches!(
            decode_unique_cargo(
                store
                    .unique_cargo
                    .get(&store.env.read_txn().unwrap(), &UNIQUE_APPLE_PIE_ID)
                    .unwrap()
                    .unwrap()
            )
            .unwrap()
            .location,
            UniqueCargoLocation::Wreckage { .. }
        ));
    }

    #[test]
    fn command_loss_moves_or_destroys_unique_cargo_by_actual_disposition() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let player = store.player_record(&identity()).unwrap().unwrap();
        let ship = store.ship_record(player.ship_id).unwrap().unwrap();
        let mut txn = store.env.write_txn().unwrap();
        let mut pie = store
            .unique_cargo
            .get(&txn, &UNIQUE_APPLE_PIE_ID)
            .unwrap()
            .map(decode_unique_cargo)
            .transpose()
            .unwrap()
            .unwrap();
        pie.location = UniqueCargoLocation::PlayerShip {
            ship_id: ship.ship_id,
            cargo_lot_id: 1,
        };
        store
            .unique_cargo
            .put(
                &mut txn,
                &pie.object_id,
                &encode_unique_cargo(&pie).unwrap(),
            )
            .unwrap();
        store
            .relocate_unique_cargo_after_command_loss_in(
                &mut txn,
                ship.ship_id,
                ship.system_id,
                crate::combat::VesselDisposition::Abandoned,
                0,
            )
            .unwrap();
        assert!(matches!(
            store
                .unique_cargo
                .get(&txn, &UNIQUE_APPLE_PIE_ID)
                .unwrap()
                .map(decode_unique_cargo)
                .transpose()
                .unwrap()
                .unwrap()
                .location,
            UniqueCargoLocation::Wreckage { .. }
        ));

        pie.location = UniqueCargoLocation::PlayerShip {
            ship_id: ship.ship_id,
            cargo_lot_id: 1,
        };
        store
            .unique_cargo
            .put(
                &mut txn,
                &pie.object_id,
                &encode_unique_cargo(&pie).unwrap(),
            )
            .unwrap();
        store
            .relocate_unique_cargo_after_command_loss_in(
                &mut txn,
                ship.ship_id,
                ship.system_id,
                crate::combat::VesselDisposition::Surrendered,
                77,
            )
            .unwrap();
        assert_eq!(
            store
                .unique_cargo
                .get(&txn, &UNIQUE_APPLE_PIE_ID)
                .unwrap()
                .map(decode_unique_cargo)
                .transpose()
                .unwrap()
                .unwrap()
                .location,
            UniqueCargoLocation::TrafficShip {
                traffic_ship_id: 77
            }
        );

        pie.location = UniqueCargoLocation::PlayerShip {
            ship_id: ship.ship_id,
            cargo_lot_id: 1,
        };
        store
            .unique_cargo
            .put(
                &mut txn,
                &pie.object_id,
                &encode_unique_cargo(&pie).unwrap(),
            )
            .unwrap();
        store
            .relocate_unique_cargo_after_command_loss_in(
                &mut txn,
                ship.ship_id,
                ship.system_id,
                crate::combat::VesselDisposition::Destroyed,
                0,
            )
            .unwrap();
        txn.commit().unwrap();
        assert!(store.unique_cargo_reset_required().unwrap());
    }

