    fn all_craft_watch_schedules_the_next_modeled_contact() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let mut txn = store.env.write_txn().unwrap();
        let (_, ship) = store.player_and_ship_in(&txn, &identity()).unwrap();
        let revision = store.career_state_in(&txn, &identity()).unwrap().revision;
        let snapshot = match store
            .set_interception_watch_in(
                &mut txn,
                &identity(),
                &crate::wire::InterceptionWatchRequest::AllCraft {
                    expected_revision: revision,
                    purpose: crate::wire::InterceptionPurpose::ArmedAttack,
                },
            )
            .unwrap()
        {
            RuleResult::Applied(snapshot) => snapshot,
            RuleResult::Rejected(reason) => panic!("all-craft watch rejected: {reason}"),
        };
        assert!(matches!(
            snapshot.interception_watch.map(|watch| watch.filter),
            Some(crate::wire::InterceptionWatchFilterKind::AllCraft)
        ));
        let scheduled = store
            .contact_events
            .iter(&txn)
            .unwrap()
            .map(|entry| {
                let (key, value) = entry.unwrap();
                decode_scheduled_object(key, value).unwrap()
            })
            .find(|(_, _, scheduled_ship_id)| *scheduled_ship_id == ship.ship_id)
            .expect("an all-craft watch should schedule a modeled contact");
        put_meta_u64(store.meta, &mut txn, META_GAME_SECOND, scheduled.0).unwrap();
        let triggered = store
            .process_contact_check_in(&mut txn, scheduled.0, ship.ship_id)
            .unwrap();
        assert_eq!(triggered, Some(identity()));
    }

    #[test]
    fn all_craft_watch_intercepts_a_player_arriving_at_the_locus() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let hunter = identity();
        let arriving = PlayerIdentity {
            bbs_id: hunter.bbs_id,
            player_id: hunter.player_id + 1,
        };
        let hunter_ship = store
            .player_and_ship_in(&store.env.read_txn().unwrap(), &hunter)
            .unwrap()
            .1;
        establish_colocated_player(&store, &arriving, &hunter_ship);

        let mut txn = store.env.write_txn().unwrap();
        let revision = store.career_state_in(&txn, &hunter).unwrap().revision;
        assert!(matches!(
            store
                .set_interception_watch_in(
                    &mut txn,
                    &hunter,
                    &crate::wire::InterceptionWatchRequest::AllCraft {
                        expected_revision: revision,
                        purpose: crate::wire::InterceptionPurpose::ArmedAttack,
                    },
                )
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let mut arriving_ship = store.player_and_ship_in(&txn, &arriving).unwrap().1;
        let ShipLocationRecord::Docked {
            world_id,
            facility_id,
            ..
        } = arriving_ship.location
        else {
            panic!("arriving fixture is not docked")
        };
        let port = ShipLocusRecord::Port {
            system_id: arriving_ship.system_id,
            world_id,
            facility_id,
        };
        arriving_ship.location = ShipLocationRecord::InFlight(FlightLegRecord {
            plan_id: 2,
            plan_revision: 1,
            leg_index: 1,
            origin: ShipLocusRecord::JumpLocus {
                system_id: arriving_ship.system_id,
            },
            destination: port,
            started_second: 0,
            due_second: 100,
            purpose: FlightLegPurpose::ApproachPort,
        });
        store
            .ships
            .put(
                &mut txn,
                &arriving_ship.ship_id,
                &encode_ship_record(&arriving_ship).unwrap(),
            )
            .unwrap();
        put_meta_u64(store.meta, &mut txn, META_GAME_SECOND, 100).unwrap();

        let (_, stage, transitioned) = store
            .process_player_travel_in(&mut txn, 100, arriving_ship.ship_id)
            .unwrap();
        assert_eq!(stage, 6);
        assert_eq!(transitioned, arriving);
        let combat_id = store
            .ship_combats
            .get(&txn, &arriving_ship.ship_id)
            .unwrap()
            .map(decode_u64)
            .transpose()
            .unwrap()
            .expect("arrival should enter shared combat");
        let transitions = store
            .shared_combat_transitions_in(&txn, combat_id, 1, 1)
            .unwrap();
        assert_eq!(transitions.len(), 2);
        assert!(
            transitions
                .iter()
                .any(|transition| transition.identity == hunter)
        );
        assert!(
            transitions
                .iter()
                .any(|transition| transition.identity == arriving)
        );
    }

    #[test]
    fn warrant_satisfaction_is_a_second_delivered_electronic_instrument() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let mut txn = store.env.write_txn().unwrap();
        let (_, ship) = store.player_and_ship_in(&txn, &identity()).unwrap();
        let destinations = store
            .simulation
            .systems(&txn)
            .unwrap()
            .into_iter()
            .map(|system| system.system_id)
            .collect::<Vec<_>>();
        let (message_id, _) = store
            .simulation
            .dispatch_message(
                &mut txn,
                0,
                ship.system_id,
                crate::simulation::MessageClass::PublicService,
                crate::simulation::MessageImportance::Important,
                "Test warrant",
                "A signed test warrant.",
                &destinations,
            )
            .unwrap();
        let mut career = store.career_state_in(&txn, &identity()).unwrap();
        let mut warrant =
            crate::careers::warrant_for_unlawful_attack(44, 1, ship.system_id, 0, 10_000, 75);
        warrant.message_id = message_id;
        warrant.status = crate::careers::WarrantStatus::Active;
        career.warrants.push(warrant);
        career.revision = career.revision.saturating_add(1);
        store
            .put_career_state_in(&mut txn, &identity(), &career)
            .unwrap();

        let settled = match store
            .settle_warrant_in(&mut txn, &identity(), 44, career.revision)
            .unwrap()
        {
            RuleResult::Applied(snapshot) => snapshot,
            RuleResult::Rejected(message) => panic!("{message}"),
        };
        let warrant = &settled.state.warrants[0];
        assert_eq!(warrant.status, crate::careers::WarrantStatus::Satisfied);
        assert_ne!(warrant.resolution_message_id, 0);
        let available = store
            .simulation
            .available_messages(&txn, ship.system_id, 0, false)
            .unwrap()
            .into_iter()
            .map(|item| item.message.message_id)
            .collect::<HashSet<_>>();
        assert!(available.contains(&warrant.message_id));
        assert!(available.contains(&warrant.resolution_message_id));
        assert!(!crate::careers::warrant_is_enforceable(warrant, true, true,));
        txn.commit().unwrap();
    }

    #[test]
    fn stealing_an_issued_command_changes_title_and_files_a_mailed_warrant() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let mut txn = store.env.write_txn().unwrap();
        let (_, ship) = store.player_and_ship_in(&txn, &identity()).unwrap();
        let finance_key = ship_finance_key(ship.ship_id);
        let mut finance = store
            .finances
            .get(&txn, &finance_key)
            .unwrap()
            .map(decode_finance_record)
            .transpose()
            .unwrap()
            .unwrap();
        finance.title = crate::wire::ShipTitleKind::InstitutionOwned;
        store
            .finances
            .put(&mut txn, &finance_key, &encode_finance_record(&finance))
            .unwrap();
        let mut career = store.career_state_in(&txn, &identity()).unwrap();
        career.mode = crate::careers::CombatCareerMode::Navy;
        career.revision = career.revision.saturating_add(1);
        store
            .put_career_state_in(&mut txn, &identity(), &career)
            .unwrap();

        let changed = match store
            .set_combat_career_mode_in(
                &mut txn,
                &identity(),
                crate::careers::CombatCareerMode::Pirate,
                career.revision,
            )
            .unwrap()
        {
            RuleResult::Applied(snapshot) => snapshot,
            RuleResult::Rejected(message) => panic!("{message}"),
        };
        assert_eq!(changed.state.mode, crate::careers::CombatCareerMode::Pirate);
        assert!(changed.state.public_heat >= 50);
        assert!(
            changed
                .state
                .warrants
                .iter()
                .any(|warrant| warrant.accusation.contains("mutiny"))
        );
        let finance = store
            .finances
            .get(&txn, &finance_key)
            .unwrap()
            .map(decode_finance_record)
            .transpose()
            .unwrap()
            .unwrap();
        assert_eq!(finance.title, crate::wire::ShipTitleKind::StolenRegistry);
        txn.commit().unwrap();
    }

    #[test]
    fn naval_orders_are_durable_instruments_delivered_by_mail() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let mut txn = store.env.write_txn().unwrap();
        let (_, ship) = store.player_and_ship_in(&txn, &identity()).unwrap();
        let mut career = store.career_state_in(&txn, &identity()).unwrap();
        career.mode = crate::careers::CombatCareerMode::Navy;
        career.opportunities.clear();
        career.revision = career.revision.saturating_add(1);
        store
            .put_career_state_in(&mut txn, &identity(), &career)
            .unwrap();
        store
            .materialize_career_opportunities_in(&mut txn, ship.system_id, 0)
            .unwrap();
        let issued = store.career_state_in(&txn, &identity()).unwrap();
        assert_eq!(issued.opportunities.len(), 1);
        let order = &issued.opportunities[0];
        assert_ne!(order.order_message_id, 0);
        assert_eq!(order.opportunity_id, order.order_message_id);
        assert!(
            store
                .simulation
                .available_messages(&txn, ship.system_id, 0, false)
                .unwrap()
                .iter()
                .any(|message| message.message.message_id == order.order_message_id)
        );
        let visible = store.combat_career_snapshot_in(&txn, &identity()).unwrap();
        assert_eq!(visible.state.opportunities.len(), 1);
        let revision = visible.state.revision;
        let opportunity_id = visible.state.opportunities[0].opportunity_id;
        assert!(matches!(
            store
                .accept_career_opportunity_in(&mut txn, &identity(), opportunity_id, revision,)
                .unwrap(),
            RuleResult::Applied(_)
        ));
        assert_eq!(
            store
                .career_state_in(&txn, &identity())
                .unwrap()
                .opportunities[0]
                .state,
            crate::careers::OpportunityState::Accepted
        );
        let mut reported = store.career_state_in(&txn, &identity()).unwrap();
        reported.opportunities[0].evidence_kind = crate::careers::ObjectiveEvidenceKind::PatrolLog;
        reported.opportunities[0].evidence_second = 1;
        reported.revision = reported.revision.saturating_add(1);
        store
            .put_career_state_in(&mut txn, &identity(), &reported)
            .unwrap();
        assert!(matches!(
            store
                .accept_career_opportunity_in(
                    &mut txn,
                    &identity(),
                    opportunity_id,
                    reported.revision,
                )
                .unwrap(),
            RuleResult::Applied(_)
        ));
        let in_transit = store.career_state_in(&txn, &identity()).unwrap();
        assert_eq!(
            in_transit.opportunities[0].state,
            crate::careers::OpportunityState::Reporting
        );
        assert_ne!(in_transit.opportunities[0].report_message_id, 0);
        store
            .process_career_mail_arrival_in(&mut txn, ship.system_id, 0)
            .unwrap();
        assert_eq!(
            store
                .career_state_in(&txn, &identity())
                .unwrap()
                .opportunities[0]
                .state,
            crate::careers::OpportunityState::Succeeded
        );
        txn.commit().unwrap();
    }

