    #[test]
    fn surviving_captain_returns_after_rescue_with_career_and_warrants_intact() {
        let dir = TempDir::new().unwrap();
        let store = Store::open(dir.path()).unwrap();
        initialize_player_fixture(&store);
        let mut txn = store.env.write_txn().unwrap();
        let (player, ship) = store.player_and_ship_in(&txn, &identity()).unwrap();
        let old_captain_id = player.captain_person_id;
        let old_ship_id = ship.ship_id;
        let career_before = store.career_state_in(&txn, &identity()).unwrap();
        let contact = store
            .local_traffic_contacts_in(&txn, &identity(), &ship, 0)
            .unwrap()
            .remove(0);
        store
            .engage_traffic_contact_in(
                &mut txn,
                &identity(),
                contact.contact_id,
                career_before.revision,
                crate::wire::InterceptionPurpose::ArmedAttack,
            )
            .unwrap();
        let warrant_count = store
            .career_state_in(&txn, &identity())
            .unwrap()
            .warrants
            .len();
        assert!(warrant_count > 0);
        let mut encounter = store
            .encounters
            .get(&txn, &encode_identity(&identity()))
            .unwrap()
            .map(decode_encounter_record)
            .transpose()
            .unwrap()
            .unwrap();
        encounter
            .combat
            .as_mut()
            .unwrap()
            .vessels
            .iter_mut()
            .find(|vessel| vessel.vessel_id == old_ship_id)
            .unwrap()
            .disposition = crate::combat::VesselDisposition::Abandoned;
        encounter.snapshot.state = EncounterState::Resolved;
        encounter.snapshot.next_turn_second = 1_000;
        encounter.result = Some(EncounterResult {
            encounter_id: encounter.snapshot.encounter_id,
            resolved: true,
            terminal: true,
            outcome: "The crew reaches the escape craft.".into(),
            turns: 1,
            cargo_lost_millitons: 0,
            fuel_lost_millitons: 0,
            damage_hits: 0,
        });
        store
            .encounters
            .put(
                &mut txn,
                &encode_identity(&identity()),
                &encode_encounter_record(&encounter).unwrap(),
            )
            .unwrap();
        put_meta_u64(
            store.meta,
            &mut txn,
            META_GAME_SECOND,
            8 * crate::simulation::SECONDS_PER_DAY,
        )
        .unwrap();
        let recovered = match store.recover_command_in(&mut txn, &identity(), "").unwrap() {
            RuleResult::Applied(fleet) => fleet,
            RuleResult::Rejected(message) => panic!("{message}"),
        };
        let player = store
            .players
            .get(&txn, &encode_identity(&identity()))
            .unwrap()
            .map(decode_player_record)
            .transpose()
            .unwrap()
            .unwrap();
        assert_eq!(player.captain_person_id, old_captain_id);
        assert_ne!(player.ship_id, old_ship_id);
        assert_eq!(recovered.active_ship_id, player.ship_id);
        assert_eq!(
            store
                .career_state_in(&txn, &identity())
                .unwrap()
                .warrants
                .len(),
            warrant_count
        );
        assert_eq!(
            store.player_phase_in(&txn, &identity()).unwrap(),
            PlayerPhase::Docked
        );
        txn.commit().unwrap();
    }

