        captain.current_dexterity = 0;
        captain.current_endurance = 0;
        store
            .persons
            .put(
                &mut txn,
                &old_captain_id,
                &encode_person_record(&captain).unwrap(),
            )
            .unwrap();
        let mut encounter = store
            .encounters
            .get(&txn, &encode_identity(&identity()))
            .unwrap()
            .map(decode_encounter_record)
            .transpose()
            .unwrap()
            .unwrap();
        encounter.snapshot.state = EncounterState::Resolved;
        encounter.snapshot.next_turn_second = 0;
        encounter.result = Some(EncounterResult {
            encounter_id: encounter.snapshot.encounter_id,
            resolved: true,
            terminal: true,
            outcome: "The command vessel and captain are lost.".into(),
            turns: 1,
            cargo_lost_millitons: 0,
            fuel_lost_millitons: 0,
            damage_hits: 0,
        });
        store
            .encounters
            .put(
                &mut txn,
                &encode_identity(&identity()),
                &encode_encounter_record(&encounter).unwrap(),
            )
            .unwrap();
